#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>

#define MAX_DNS_REQUESTS 10
#define DNS_TIMEOUT 1000 // milliseconds
#define RATE_LIMIT_INTERVAL 1000 // milliseconds

typedef struct {
    char *hostname;
    u_char ip[4];
} dns_request_t;

void rate_limit(int interval) {
    static int last_time = 0;
    if (last_time + interval > time(NULL)) {
        usleep((last_time + interval - time(NULL)) * 1000);
    }
    last_time = time(NULL);
}

int dns_resolve(char *hostname, u_char ip[4]) {
    struct addrinfo hints, *res;
    int errcode;

    // Rate limiting
    rate_limit(RATE_LIMIT_INTERVAL);

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((errcode = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(errcode));
        return -1;
    }

    struct in_addr *addr = (struct in_addr *) res->ai_addr;
    memcpy(ip, addr->s_addr, 4);

    freeaddrinfo(res);

    // Logging
    log_dns_query(hostname, ip);

    return 0;
}

void *dns_resolver(void *arg) {
    dns_request_t *req = (dns_request_t *) arg;
    u_char ip[4];

    if (dns_resolve(req->hostname, ip) == -1) {
        fprintf(stderr, "DNS resolution failed for %s\n", req->hostname);
        return NULL;
    }

    memcpy(req->ip, ip, 4);

    free(arg);

    return NULL;
}

int main() {
    pthread_t thread;
    dns_request_t *req = malloc(sizeof(dns_request_t));
    req->hostname = "example.com";

    if (pthread_create(&thread, NULL, dns_resolver, (void *) req) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return -1;
    }

    pthread_join(thread, NULL);

    printf("IP address for %s is %d.%d.%d.%d\n", req->hostname, req->ip[0], req->ip[1], req->ip[2], req->ip[3]);

    free(req);

    return 0;
}
```
