bool validate_token(const char* token) {
    json_object *obj = json_tokener_parse(token);
    if (!obj) {
        return false;
    }

    const char* access_token = json_object_get_string(json_object_object_get(obj, "access_token"));
    if (!access_token) {
        return false;
    }

    int expires_in = json_object_get_int(json_object_object_get(obj, "expires_in"));
    if (expires_in <= 0) {
        return false;
    }

    const char* token_type = json_object_get_string(json_object_object_get(obj, "token_type"));
    if (!token_type || strcmp(token_type, "Bearer") != 0) {
        return false;
    }

    const char* refresh_token = json_object_get_string(json_object_object_get(obj, "refresh_token"));
    if (refresh_token && strlen(refresh_token) > 0) {
        // Optional field, do nothing
    }

    return true;
}

EVP_CIPHER* get_cipher(const char* mode) {
    EVP_CIPHER* cipher = NULL;

    if (strcmp(mode, "ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(mode, "EDE") == 0) {
        cipher = EVP_des_ede();
    } else if (strcmp(mode, "EDE3") == 0) {
        cipher = EVP_des_ede3();
    } else if (strcmp(mode, "CFB") == 0) {
        cipher = EVP_des_cfb();
    } else {
        return NULL;
    }

    return cipher;
}

bool encrypt_token(const char* token, const char* mode) {
    if (!validate_token(token)) {
        return false;
    }

    EVP_CIPHER* cipher = get_cipher(mode);
    if (!cipher) {
        return false;
    }

    // Encrypt the token using the chosen cipher
    int len = strlen(token);
    unsigned char* encrypted = OPENSSL_malloc(len + 1);
    memset(encrypted, 0, len + 1);
    EVP_EncryptUpdate(cipher, encrypted, &len, (unsigned char*)token, len);

    // Free the cipher and return the encrypted token
    EVP_CIPHER_free(cipher);
    return true;
}
