        return weaknesses.toArray(new Weakness[0]);
      } catch (IOException e) {
        // Handle error
      }
    }
  }

  private static WeatherData getWeatherData(String location) {
    if (weatherCache.containsKey(location)) {
      return weatherCache.get(location);
    } else {
      try {
        URL url = new URL(WEATHER_API_URL + location);
        JsonObject json = fetchJson(url);
        WeatherData weatherData = new WeatherData();
        weatherData.setTemperature(json.get("main").getAsJsonObject().get("temp").getAsDouble());
        weatherCache.put(location, weatherData);
        return weatherData;
      } catch (IOException e) {
        // Handle error
      }
    }
  }

  private static JsonObject fetchJson(URL url) throws IOException {
    HttpURLConnection connection = (HttpURLConnection) url.openConnection();
    connection.setRequestMethod("GET");
    connection.connect();
    int status = connection.getResponseCode();
    if (status == 200) {
      JsonObject json = new Gson().fromJson(new InputStreamReader(connection.getInputStream()), JsonObject.class);
      return json;
    } else {
      // Handle error
    }
  }
}
