} algo_info_t;

// Function to dynamically load and return a list of available algorithms
algo_info_t* get_algorithms(void) {
    // List of available algorithms
    static algo_info_t *algos = NULL;

    // Check if the list has already been loaded
    if (algos != NULL) {
        return algos;
    }

    // Load the shared library for cryptographic hash functions
    void *hash_lib = dlopen("cryptohash.so", RTLD_LAZY);
    if (!hash_lib) {
        fprintf(stderr, "Error loading hash library: %s\n", dlerror());
        return NULL;
    }

    // Load the shared library for block ciphers
    void *cipher_lib = dlopen("cryptocrypto.so", RTLD_LAZY);
    if (!cipher_lib) {
        fprintf(stderr, "Error loading cipher library: %s\n", dlerror());
        return NULL;
    }

    // Get the list of available hash functions from the shared library
    void *hash_funcs = dlsym(hash_lib, "get_available_hashes");
    if (!hash_funcs) {
        fprintf(stderr, "Error getting hash functions: %s\n", dlerror());
        return NULL;
    }

    // Get the list of available block ciphers from the shared library
    void *cipher_funcs = dlsym(cipher_lib, "get_available_ciphers");
    if (!cipher_funcs) {
        fprintf(stderr, "Error getting cipher functions: %s\n", dlerror());
        return NULL;
    }

    // Create a list of available algorithms
    algos = malloc(sizeof(algo_info_t) * (hash_funcs->num_funcs + cipher_funcs->num_funcs));
    if (!algos) {
        fprintf(stderr, "Error allocating memory for algorithm list\n");
        return NULL;
    }

    // Load the hash functions and add them to the list of available algorithms
    for (int i = 0; i < hash_funcs->num_funcs; i++) {
        algo_info_t *algo = &algos[i];
        algo->name = hash_funcs->func_names[i];
        algo->func_ptr = dlsym(hash_lib, algo->name);
        if (!algo->func_ptr) {
            fprintf(stderr, "Error loading hash function %s: %s\n", algo->name, dlerror());
            return NULL;
        }
    }

    // Load the block ciphers and add them to the list of available algorithms
    for (int i = 0; i < cipher_funcs->num_funcs; i++) {
        algo_info_t *algo = &algos[i + hash_funcs->num_funcs];
        algo->name = cipher_funcs->func_names[i];
        algo->func_ptr = dlsym(cipher_lib, algo->name);
        if (!algo->func_ptr) {
            fprintf(stderr, "Error loading cipher function %s: %s\n", algo->name, dlerror());
            return NULL;
        }
    }

    // Return the list of available algorithms
    return algos;
}
