#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

struct queue {
    int capacity;
    int size;
    int front;
    int rear;
    void** data;
    sem_t* mutex;
    sem_t* not_full;
    sem_t* not_empty;
};

void init_queue(struct queue* q, int capacity) {
    q->capacity = capacity;
    q->size = 0;
    q->front = 0;
    q->rear = -1;
    q->data = malloc(sizeof(void*) * capacity);
    q->mutex = sem_open("queue_mutex", O_CREAT, 0644, 1);
    q->not_full = sem_open("queue_not_full", O_CREAT, 0644, capacity - q->size);
    q->not_empty = sem_open("queue_not_empty", O_CREAT, 0644, 0);
}

void enqueue(struct queue* q, void* data) {
    sem_wait(q->mutex);
    if (q->rear == q->capacity - 1) {
        q->rear = 0;
    } else {
        q->rear++;
    }
    q->data[q->rear] = data;
    sem_post(q->not_full);
    sem_post(q->mutex);
}

void* dequeue(struct queue* q) {
    void* data = NULL;
    sem_wait(q->mutex);
    if (q->size > 0) {
        data = q->data[q->front];
        q->front++;
        if (q->front == q->capacity - 1) {
            q->front = 0;
        }
        sem_post(q->not_empty);
    }
    sem_post(q->mutex);
    return data;
}

void delete_queue(struct queue* q) {
    sem_close(q->mutex);
    sem_close(q->not_full);
    sem_close(q->not_empty);
    free(q->data);
}
