function testEnvironment(envLabel, modulePath, f) {
  // Dynamically load the module using require() based on envLabel
  let module;
  try {
    module = require(modulePath);
  } catch (err) {
    console.error(`Error loading module ${modulePath}: ${err}`);
    return;
  }

  // Execute the tests
  try {
    f(module);
  } catch (err) {
    console.error(`Error executing test for module ${modulePath} in environment ${envLabel}: ${err}`);
    return;
  }

  // Reset the mocking library blueslip after each test
  try {
    blueslip.reset();
  } catch (err) {
    console.error(`Error resetting blueslip: ${err}`);
    return;
  }

  // Handle potential failures gracefully and provide detailed error logging to the console
  try {
    module.cleanup();
  } catch (err) {
    console.error(`Error cleaning up resources for module ${modulePath} in environment ${envLabel}: ${err}`);
    return;
  }
}
```
