function processStream(stream) {
  const array = [];
  let paused = false;

  stream.on('data', (data) => {
    if (!paused) {
      array.push(data);
    }
  });

  stream.on('pause', () => {
    paused = true;
  });

  stream.on('resume', () => {
    paused = false;
  });

  const addRandomVerticesAndEdges = (graph) => {
    const numVertices = Math.floor(Math.random() * 10);
    for (let i = 0; i < numVertices; i++) {
      graph.addVertex({
        id: `vertex-${i}`,
        label: `Vertex ${i}`,
        properties: {
          randomProperty: Math.random() * 10,
        },
      });
    }
    const numEdges = Math.floor(Math.random() * 20);
    for (let i = 0; i < numEdges; i++) {
      graph.addEdge({
        id: `edge-${i}`,
        label: `Edge ${i}`,
        properties: {
          randomProperty: Math.random() * 10,
        },
      });
    }
  };

  return { array, addRandomVerticesAndEdges };
}
```"]

