To ensure scalability, this implementation is designed to efficiently handle a large number of scripts and minimize memory usage, by using asynchronous loading and caching strategies, and by avoiding unnecessary DOM manipulation during script execution.

To make the loader easy to integrate into existing projects, this implementation provides clear documentation and examples, and can be easily integrated into existing build processes. It also follows best practices for modular and testable code, to facilitate future updates and maintenance."]

['```java
import java.util.*;

class Transaction {
    int userId;
    int transactionId;
    double amount;
}

class UnionFind {
    private Map<Integer, Integer> parent = new HashMap<>();
    private Map<Integer, Integer> rank = new HashMap<>();

    public void makeSet(int x) {
        parent.put(x, x);
        rank.put(x, 0);
    }

    public int find(int x) {
        if (parent.get(x) == x) return x;
        else return find(parent.get(x));
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (rank.get(rootX) > rank.get(rootY)) parent.put(rootY, rootX);
            else {
                parent.put(rootX, rootY);
                if (rank.get(rootX) == rank.get(rootY)) rank.put(rootX, rank.get(rootX) + 1);
            }
        }
    }
}

class DisjointTransactionGroups {
    public int countDisjointTransactionGroups(List<Transaction> transactions) {
        UnionFind uf = new UnionFind();
        for (Transaction transaction : transactions) {
            uf.makeSet(transaction.userId);
        }
        long startTime = System.currentTimeMillis();
        for (int i = 0; i < transactions.size() - 1; i++) {
            Transaction transaction1 = transactions.get(i);
            Transaction transaction2 = transactions.get(i + 1);
            if (transaction1.userId == transaction2.userId) uf.union(transaction1.userId, transaction2.userId);
        }
        long endTime = System.currentTimeMillis();
        int disjointGroups = uf.parent.size();
        // Logging mechanism to record the number of milliseconds taken to process each user's transactions
        for (int userId : uf.parent.keySet()) {
            long timeTaken = endTime - startTime;
            System.out.println("User " + userId + " processed in " + timeTaken + " milliseconds");
        }
        return disjointGroups;
    }
}
