// Function to dynamically load and return a list of available cryptographic hash functions and block ciphers
AlgorithmInfo** get_algorithms() {
    // Initialize an array to store the loaded algorithms
    AlgorithmInfo** algorithms = malloc(sizeof(AlgorithmInfo*) * 10);
    if (!algorithms) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }

    // Load the shared libraries for the cryptographic hash functions and block ciphers
