    if (!handle) {
        fprintf(stderr, "Error: %s\n", dlerror());
        return NULL;
    }
    char* name = "sha256"; // Name of the algorithm to load
    void* sym = dlsym(handle, name);
    if (!sym) {
        fprintf(stderr, "Error: %s\n", dlerror());
        return NULL;
    }
    algorithms[0] = malloc(sizeof(AlgorithmInfo));
    algorithms[0]->handle = handle;
    algorithms[0]->name = strdup(name);

    // Load the shared libraries for the cryptographic hash functions and block ciphers
