function generateRandomString($length = 10, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
    // Fetch additional character sets from external API
    $additionalCharsets = fetchAdditionalCharsets();

    // Combine the given charset with the additional charsets
    $charset .= $additionalCharsets;

    // Generate a random string using the combined charset
    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomString .= $charset[mt_rand(0, strlen($charset) - 1)];
    }

    // Hash the password using a configurable hash algorithm and strength level
    $hashedPassword = hashPassword($password, $algorithm, $strength);

    return $randomString;
}

function fetchAdditionalCharsets() {
    // Fetch additional character sets from external API
    $response = file_get_contents('https://example.com/charsets');

    // Check for potential failures in the response
    if ($response === false) {
        return '';
    }

    // Parse the response and extract the additional character sets
    $additionalCharsets = json_decode($response, true);

    // Return the combined character set
    return implode('', $additionalCharsets);
}

function hashPassword($password, $algorithm, $strength) {
    // Check for invalid input
    if (!is_string($password) || !is_string($algorithm) || !is_int($strength)) {
        return '';
    }

    // Hash the password using the specified algorithm and strength level
    switch ($algorithm) {
        case 'bcrypt':
            $hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $strength]);
            break;
        case 'argon2i':
            $hashedPassword = password_hash($password, PASSWORD_ARGON2I, ['memory_cost' => $strength]);
            break;
        default:
            $hashedPassword = '';
    }

    return $hashedPassword;
}
