function updateUserPassword($userId, $newPassword) {
    // Validate the password strength according to predefined criteria
    if (!validatePasswordStrength($newPassword)) {
        throw new Exception("Invalid password strength");
    }

    // Handle error conditions gracefully
    try {
        // Update the user's password in the local database
        $result = updateUserPasswordInDatabase($userId, $newPassword);

        // If the update was successful, propagate the change to external authentication services
        if ($result) {
            $externalServices = getExternalAuthenticationServices();
            foreach ($externalServices as $service) {
                try {
                    $service->updateUserPassword($userId, $newPassword);
                } catch (Exception $e) {
                    // If an error occurs while updating the password in an external service, log it and continue
                    logError("Failed to update user password in {$service->getName()}: {$e->getMessage()}");
                }
            }
        }
    } catch (Exception $e) {
        // If an error occurs during the update process, roll back any changes made so far
        rollbackUserPasswordUpdate($userId);
        throw new Exception("Failed to update user password: {$e->getMessage()}");
    }
}

function validatePasswordStrength($password) {
