    int dataCapacity; // maximum number of data points per node
    std::vector<std::unique_ptr<OctreeNode>> children; // child nodes
    std::vector<int> dataIndices; // indices of data points stored in this node
};

struct Octree {
    int featureSize; // size of each feature in bytes
    int dataCapacity; // maximum number of data points per octree
    std::unique_ptr<OctreeNode> root; // root node of the octree
};

// Function to initialize an octree for managing spatial data
Octree* initOctree(int featureSize, int numLeafNodes, int dataCapacity) {
    Octree* octree = new Octree();
    octree->featureSize = featureSize;
    octree->dataCapacity = dataCapacity;
    octree->root = std::make_unique<OctreeNode>();
    octree->root->featureSize = featureSize;
    octree->root->dataCapacity = dataCapacity;
    octree->root->children.reserve(numLeafNodes);
    for (int i = 0; i < numLeafNodes; ++i) {
        auto child = std::make_unique<OctreeNode>();
        child->featureSize = featureSize;
        child->dataCapacity = dataCapacity;
        octree->root->children.push_back(std::move(child));
    }
    return octree;
}

// Function to insert a new data point into the octree
void insertDataPoint(Octree* octree, const void* data) {
    // Find the appropriate leaf node for the data point
    OctreeNode* current = octree->root.get();
    while (current->children.size() > 0) {
        int childIndex = getChildIndex(data, current);
        current = current->children[childIndex].get();
    }
    // Insert the data point into the leaf node
    if (current->dataIndices.size() < current->dataCapacity) {
        current->dataIndices.push_back(data);
    } else {
        // Split the leaf node if it is full
        splitNode(octree, current);
        insertDataPoint(octree, data);
    }
}

// Function to remove a data point from the octree
void removeDataPoint(Octree* octree, const void* data) {
    // Find the leaf node containing the data point
    OctreeNode* current = octree->root.get();
    while (current->children.size() > 0) {
        int childIndex = getChildIndex(data, current);
        current = current->children[childIndex].get();
    }
    // Remove the data point from the leaf node
    auto it = std::find(current->dataIndices.begin(), current->dataIndices.end(), data);
    if (it != current->dataIndices.end()) {
        current->dataIndices.erase(it);
    } else {
        // Merge the leaf node with its parent if it is empty
        mergeNode(octree, current);
    }
}

// Function to query the octree for data points within a given region
std::vector<const void*> queryRegion(Octree* octree, const void* region) {
    // Find the leaf nodes containing the region
    std::vector<OctreeNode*> leafNodes;
    OctreeNode* current = octree->root.get();
    while (current->children.size() > 0) {
        int childIndex = getChildIndex(region, current);
        if (childIndex >= 0) {
            leafNodes.push_back(current->children[childIndex].get());
        }
        current = current->children[childIndex].get();
    }
    // Query the leaf nodes for data points within the region
    std::vector<const void*> results;
    for (auto& node : leafNodes) {
        auto it = std::find_if(node->dataIndices.begin(), node->dataIndices.end(), [region](const void* data) {
            return isInRegion(data, region);
        });
        results.insert(results.end(), it, node->dataIndices.end());
    }
    return results;
}

// Function to split a leaf node into two child nodes
void splitNode(Octree* octree, OctreeNode* node) {
    // Create new child nodes and assign them to the parent node
    auto child1 = std::make_unique<OctreeNode>();
    auto child2 = std::make_unique<OctreeNode>();
    child1->featureSize = node->featureSize;
    child1->dataCapacity = node->dataCapacity / 2;
    child2->featureSize = node->featureSize;
    child2->dataCapacity = node->dataCapacity - child1->dataCapacity;
    node->children.push_back(std::move(child1));
    node->children.push_back(std::move(child2));
    // Move data points from the parent node to the child nodes
    for (int i = 0; i < node->dataIndices.size(); ++i) {
        auto& data = node->dataIndices[i];
        int childIndex = getChildIndex(data, node);
        if (childIndex == 0) {
            child1->dataIndices.push_back(data);
        } else {
            child2->dataIndices.push_back(data);
        }
    }
}

// Function to merge a leaf node with its parent node
void mergeNode(Octree* octree, OctreeNode* node) {
    // Move data points from the child nodes to the parent node
    for (int i = 0; i < node->children.size(); ++i) {
        auto& child = node->children[i];
        for (auto& data : child->dataIndices) {
            node->dataIndices.push_back(data);
        }
    }
    // Remove the child nodes from the parent node
    node->children.clear();
}

// Function to get the index of a child node for a given data point
int getChildIndex(const void* data, OctreeNode* node) {
    int childIndex = -1;
    // Calculate the feature value for the child node
    float featureValue = 0.0f;
    switch (node->featureSize) {
        case sizeof(float):
            featureValue = *reinterpret_cast<const float*>(data);
            break;
        case sizeof(double):
            featureValue = *reinterpret_cast<const double*>(data);
            break;
    }
    // Find the child node with the closest feature value
    for (int i = 0; i < node->children.size(); ++i) {
        auto& child = node->children[i];
        float childFeatureValue = 0.0f;
        switch (child->featureSize) {
            case sizeof(float):
                childFeatureValue = *reinterpret_cast<const float*>(data);
                break;
            case sizeof(double):
                childFeatureValue = *reinterpret_cast<const double*>(data);
                break;
        }
        if (childFeatureValue > featureValue) {
            childIndex = i;
            break;
        }
    }
    return childIndex;
}

// Function to check whether a data point is within a given region
bool isInRegion(const void* data, const void* region) {
    // Calculate the feature values for the data point and region
    float dataFeatureValue = 0.0f;
    float regionFeatureValue = 0.0f;
    switch (node->featureSize) {
        case sizeof(float):
            dataFeatureValue = *reinterpret_cast<const float*>(data);
            regionFeatureValue = *reinterpret_cast<const float*>(region);
            break;
        case sizeof(double):
            dataFeatureValue = *reinterpret_cast<const double*>(data);
            regionFeatureValue = *reinterpret_cast<const double*>(region);
            break;
    }
    // Check whether the data point is within the region
    return (dataFeatureValue >= regionFeatureValue - 0.5f) && (dataFeatureValue <= regionFeatureValue + 0.5f);
}
```
