// Define the maximum memory limit for the system (10 MB)
#define MAX_MEMORY 10 * 1024 * 1024

// Define the sliding window size (5 seconds)
#define WINDOW_SIZE 5

// Define the transaction structure
struct Transaction {
    int id;
    long timestamp;
    double value;
};

// Define the transaction queue data structure
struct Queue {
    struct Transaction *transactions;
    size_t capacity;
    size_t count;
};

// Define the sliding window data structure
struct Window {
    struct Queue transactions;
    long start_time;
    long end_time;
    int transaction_count;
    double total_volume;
    double weighted_sum;
};

// Function to initialize a new transaction queue
void initQueue(struct Queue *queue) {
    queue->transactions = NULL;
    queue->capacity = 0;
    queue->count = 0;
}

// Function to add a new transaction to the queue
void enqueueTransaction(struct Queue *queue, struct Transaction *transaction) {
    // Check if the queue is full
    if (queue->count == queue->capacity) {
        // If the queue is full, double its capacity
        queue->capacity *= 2;
        queue->transactions = realloc(queue->transactions, sizeof(struct Transaction) * queue->capacity);
    }

    // Add the new transaction to the end of the queue
    queue->transactions[queue->count++] = *transaction;
}

// Function to remove a transaction from the queue
void dequeueTransaction(struct Queue *queue, struct Transaction *transaction) {
    // Check if the queue is empty
    if (queue->count == 0) {
        return;
    }

    // Remove the first transaction from the queue
    *transaction = queue->transactions[0];
    memmove(queue->transactions, queue->transactions + 1, sizeof(struct Transaction) * (queue->count - 1));
    queue->count--;
}

// Function to update the sliding window with a new transaction
void updateWindow(struct Window *window, struct Transaction *transaction) {
    // Check if the transaction is within the sliding window
    if (transaction->timestamp < window->start_time || transaction->timestamp > window->end_time) {
        return;
    }

    // Update the transaction count and total volume for the current sliding window
    window->transaction_count++;
    window->total_volume += transaction->value;

    // Calculate the weighted sum of transactions within the sliding window
    double weight = (double)(window->end_time - transaction->timestamp) / WINDOW_SIZE;
    window->weighted_sum += transaction->value * weight;
}

// Function to identify the transaction with the highest weighted sum within the last 5 seconds
struct Transaction findHighestWeightedSum(struct Window *window) {
    struct Transaction highest = {0, 0, 0};
    for (int i = 0; i < window->transaction_count; i++) {
        if (window->transactions[i].timestamp >= window->end_time - WINDOW_SIZE) {
            continue;
        }
        if (highest.weighted_sum < window->transactions[i].weighted_sum) {
            highest = window->transactions[i];
        }
    }
    return highest;
}

// Function to handle a new transaction and update the sliding window
void handleTransaction(struct Window *window, struct Transaction *transaction) {
    // Update the sliding window with the new transaction
    updateWindow(window, transaction);

    // Identify the transaction with the highest weighted sum within the last 5 seconds
    struct Transaction highest = findHighestWeightedSum(window);

    // Return the transaction ID with the highest weighted sum and the total transaction count over the last 5 seconds
    printf("Transaction ID: %d\n", highest.id);
    printf("Total transaction count: %d\n", window->transaction_count);
}

// Function to handle a burst of transactions and update the sliding window
void handleBurst(struct Window *window, struct Transaction *transactions, int count) {
    // Update the sliding window with each new transaction
    for (int i = 0; i < count; i++) {
        updateWindow(window, transactions + i);
    }

    // Identify the transaction with the highest weighted sum within the last 5 seconds
    struct Transaction highest = findHighestWeightedSum(window);

    // Return the transaction ID with the highest weighted sum and the total transaction count over the last 5 seconds
    printf("Transaction ID: %d\n", highest.id);
    printf("Total transaction count: %d\n", window->transaction_count);
}

// Function to handle a minimal activity period and update the sliding window
void handleMinimalActivity(struct Window *window) {
    // Update the sliding window with each new transaction
    for (int i = 0; i < WINDOW_SIZE; i++) {
        struct Transaction transaction = {0, 0, 0};
        dequeueTransaction(&window->transactions, &transaction);
        updateWindow(window, &transaction);
