namespace RandomValueGenerator
{
    public class RandomValueGenerator
    {
        private readonly Random _random;
        private int _seed;
        private float _precision;
        private bool _inclusive;
        private int _min;
        private int _max;

        public RandomValueGenerator(int seed = 0)
        {
            _random = new Random(seed);
            _seed = seed;
            _precision = 1.0f;
            _inclusive = true;
            _min = int.MinValue;
            _max = int.MaxValue;
        }

        public void SetSeed(int seed)
        {
            if (seed < 0 || seed > int.MaxValue)
                throw new ArgumentOutOfRangeException("Invalid seed value");

            _random = new Random(seed);
            _seed = seed;
        }

        public void SetPrecision(float precision)
        {
            if (precision < 0 || precision > 1.0f)
                throw new ArgumentOutOfRangeException("Invalid precision value");

            _precision = precision;
        }

        public void SetInclusive(bool inclusive)
        {
            _inclusive = inclusive;
        }

        public void SetRange(int min, int max)
        {
            if (min > max)
                throw new ArgumentException("Invalid range");

            _min = min;
            _max = max;
        }

        public int NextInt()
        {
            return _random.Next(_min, _max);
        }

        public float NextFloat()
        {
            return (float)_random.NextDouble() * (_max - _min) + _min;
        }

        public void Reset()
        {
            _random = new Random(_seed);
        }

        public override string ToString()
        {
            return $"RandomValueGenerator: Seed={_seed}, Precision={_precision}, Inclusive={_inclusive}, Range=[{_min}, {_max}]";
        }
    }
}
