#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/ssl.h>

struct tiff_info {
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples;
    struct {
        int sample_value;
        char* sample_name;
    } extra_samples[16];
};

struct tiff_info parse_tiff(const char* filename, const char* operation) {
    // Open the TIFF file and read its header
    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        perror("fopen");
        exit(1);
    }
    unsigned char header[2];
    if (fread(header, 1, 2, fp) != 2) {
        perror("fread");
        exit(1);
    }

    // Check the TIFF magic number and version
    if (header[0] != 'I' || header[1] != 'I') {
        printf("Error: Not a valid TIFF file\n");
        fclose(fp);
        exit(1);
    }

    // Read the image width and height
    unsigned short width, height;
    if (fread(&width, 2, 1, fp) != 1 || fread(&height, 2, 1, fp) != 1) {
        perror("fread");
        exit(1);
    }

    // Read the bits per sample and samples per pixel
    unsigned short bps, spp;
    if (fread(&bps, 2, 1, fp) != 1 || fread(&spp, 2, 1, fp) != 1) {
        perror("fread");
        exit(1);
    }

    // Check the bit depth and samples per pixel
    if (bps < 1 || bps > 16 || spp < 1 || spp > 16) {
        printf("Error: Unsupported bit depth or samples per pixel\n");
        fclose(fp);
        exit(1);
    }

    // Read the extra samples count and information
    unsigned short es_count;
    if (fread(&es_count, 2, 1, fp) != 1) {
        perror("fread");
        exit(1);
    }

    struct tiff_info info = {bps, spp, es_count};
    for (int i = 0; i < es_count; i++) {
        unsigned short value;
        char name[32];
        if (fread(&value, 2, 1, fp) != 1 || fread(name, 1, 32, fp) != 32) {
            perror("fread");
            exit(1);
        }
        info.extra_samples[i].sample_value = value;
        info.extra_samples[i].sample_name = name;
    }

    // Close the file and return the extracted data
    fclose(fp);
    return info;
}
