#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <png.h>

int compress_png(const char* input_file, const char* output_file, int compression_level) {
    // Check if the input file exists and is a valid PNG image
    FILE *input = fopen(input_file, "rb");
    if (input == NULL) {
        printf("Error: Input file does not exist or is not a valid PNG image\n");
        return 1;
    }

    // Check if the output file exists and is writable
    FILE *output = fopen(output_file, "wb");
    if (output == NULL) {
        printf("Error: Output file does not exist or is not writable\n");
        return 1;
    }

    // Check if the compression level is valid
    if (compression_level < 0 || compression_level > 9) {
        printf("Error: Compression level must be between 0 and 9\n");
        return 1;
    }

    // Read the input file into memory
    fseek(input, 0, SEEK_END);
    long input_size = ftell(input);
    rewind(input);
    unsigned char* input_data = (unsigned char*)malloc(input_size);
    if (fread(input_data, 1, input_size, input) != input_size) {
        printf("Error: Failed to read input file\n");
        return 1;
    }

    // Compress the PNG image using a third-party library
    png_structp png = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
    if (png == NULL) {
        printf("Error: Failed to create PNG read struct\n");
        return 1;
    }

    png_infop info = png_create_info_struct(png);
    if (info == NULL) {
        printf("Error: Failed to create PNG info struct\n");
        return 1;
    }

    png_set_compression_level(png, compression_level);

    png_init_io(png, input);
    png_read_info(png, info);

    unsigned char* output_data = (unsigned char*)malloc(input_size);
    if (output_data == NULL) {
        printf("Error: Failed to allocate memory for output data\n");
        return 1;
    }

    png_set_write_fn(png, output, &png_write_data, &png_flush_data);
    png_write_info(png, info);
    png_write_image(png, input_data);
    png_write_end(png, NULL);

    // Clean up
    free(input_data);
    free(output_data);
    png_destroy_read_struct(&png, &info, NULL);
    fclose(input);
    fclose(output);

    return 0;
}
```
