using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

public static class WebApplicationInitializer
{
    public static async Task<string> AddWebApplicationAsync(string directoryPath, string siteName)
    {
        // Verify the presence of a web.config file within the specified directory
        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            return "";
        }

        // Handle potential race conditions when multiple applications attempt to add sites simultaneously
        using (var mutex = new Mutex(false, $"{siteName}_AddWebApplication"))
        {
            try
            {
                await mutex.WaitAsync();

                // Initialize the web application within the specified directory
                var sitePath = Path.Combine(directoryPath, siteName);
                if (!Directory.Exists(sitePath))
                {
                    Directory.CreateDirectory(sitePath);
                }

                // Add a new web.config file to the site directory
                var configFilePath = Path.Combine(sitePath, "web.config");
                using (var writer = File.CreateText(configFilePath))
                {
                    await writer.WriteLineAsync("<?xml version=\"1.0\" encoding=\"utf-8\"?>");
                    await writer.WriteLineAsync("<configuration>");
                    await writer.WriteLineAsync("</configuration>");
                }

                // Log the addition process and any failures
                Logger.LogInformation($"Added web application {siteName} to directory {directoryPath}");
            }
            catch (Exception ex)
            {
                Logger.LogError(ex, $"Failed to add web application {siteName} to directory {directoryPath}");
                return "";
            }
            finally
            {
                mutex.ReleaseMutex();
            }
        }

        // Return the path of the newly added web application
        return Path.Combine(directoryPath, siteName);
    }
}
