using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class CloudStorageService {
    private readonly HttpClient _httpClient;

    public CloudStorageService(string apiKey, string endpoint) {
        _httpClient = new HttpClient();
        _httpClient.DefaultRequestHeaders.Authorization = "Bearer " + apiKey;
        _httpClient.BaseAddress = new Uri(endpoint);
    }

    public async Task<List<string>> UploadFilesAsync(IEnumerable<byte[]> files) {
        var uris = new List<string>();

        // Create a task for each file to be uploaded
        var tasks = files.Select(file => UploadFileAsync(file));

        // Wait for all tasks to complete
        await Task.WhenAll(tasks);

        // Get the URIs of the uploaded files
        uris = tasks.Select(task => task.Result).ToList();

        return uris;
    }

    private async Task<string> UploadFileAsync(byte[] file) {
        var uri = "";

        try {
            // Create a new HTTP request for the upload
            var request = new HttpRequestMessage(HttpMethod.Post, _httpClient.BaseAddress);

            // Add the file to the request body
            using (var stream = new MemoryStream(file)) {
                request.Content = new StreamContent(stream);
            }

            // Send the request and get the response
            var response = await _httpClient.SendAsync(request);

            // Get the URI of the uploaded file from the response headers
            uri = response.Headers.GetValues("Location").FirstOrDefault();
        } catch (Exception ex) {
            Console.WriteLine($"Error uploading file: {ex.Message}");
        }

        return uri;
    }
}
```
