using System.Text;

public static byte[] Decrypt(byte[] ciphertext, byte[] encryptionKey, byte[] initializationVector, PaddingMode padding)
{
    // Determine the key size based on the length of the encryption key
    int keySize = (encryptionKey.Length == 16) ? 128 : 256;

    // Create a new AES-CBC decryptor with the specified key and initialization vector
    using var decryptor = Aes.Create();
    decryptor.KeySize = keySize;
    decryptor.BlockSize = 128;
    decryptor.Mode = CipherMode.CBC;
    decryptor.Padding = padding;
    decryptor.IV = initializationVector;

    // Decrypt the ciphertext using the specified padding scheme
    byte[] plaintext = decryptor.Decrypt(ciphertext);

    // Return the decrypted plaintext as a byte array
    return plaintext;
}
```
