using namespace std;

class CustomDeserializer {
public:
    static void deserialize(JNIEnv* env, jbyteArray byteArray, jobject& obj) {
        // Check if the class of the object being deserialized is available
        jclass clazz = env->FindClass("com/example/MyClass");
        if (clazz == nullptr) {
            throw runtime_error("Class not found: com.example.MyClass");
        }

        // Create an ObjectInputStream from the byte array
        jobject inputStream = env->NewObject(
            "java/io/ObjectInputStream", "(Ljava/io/InputStream;)V",
            env->NewObject("java/io/ByteArrayInputStream", "(Lbyte[];)V", byteArray));

        // Deserialize the object using Java's ObjectInputStream
        jobject deserializedObj = env->CallObjectMethod(inputStream, "readObject", nullptr);

        // Check if the deserialization was successful
        if (deserializedObj == nullptr) {
            throw runtime_error("Deserialization failed");
        }

        // Cast the deserialized object to the correct class
        jclass objClass = env->GetObjectClass(deserializedObj);
        if (!env->IsInstanceOf(deserializedObj, clazz)) {
            throw runtime_error("Deserialized object is not an instance of com.example.MyClass");
        }

        // Return the deserialized object
        obj = env->NewGlobalRef(deserializedObj);
    }
};

class DeserializationQueue {
public:
    static void enqueue(JNIEnv* env, jbyteArray byteArray) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(byteArray);
    }

    static bool dequeue(JNIEnv* env, jobject& obj) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (queue_.empty()) {
            return false;
        }
        jbyteArray byteArray = queue_.front();
        queue_.pop();
        CustomDeserializer::deserialize(env, byteArray, obj);
        return true;
    }

private:
    static std::mutex mutex_;
    static std::queue<jbyteArray> queue_;
};

std::mutex DeserializationQueue::mutex_;
std::queue<jbyteArray> DeserializationQueue::queue_;

JNIEXPORT jobject JNICALL Java_com_example_MyClass_deserialize(JNIEnv* env, jclass clazz, jbyteArray byteArray) {
    // Check if the class of the object being deserialized is available
    jclass objClass = env->FindClass("com/example/MyClass");
    if (objClass == nullptr) {
        throw runtime_error("Class not found: com.example.MyClass");
    }

    // Create an ObjectInputStream from the byte array
    jobject inputStream = env->NewObject(
        "java/io/ObjectInputStream", "(Ljava/io/InputStream;)V",
        env->NewObject("java/io/ByteArrayInputStream", "(Lbyte[];)V", byteArray));

    // Deserialize the object using Java's ObjectInputStream
    jobject deserializedObj = env->CallObjectMethod(inputStream, "readObject", nullptr);

    // Check if the deserialization was successful
    if (deserializedObj == nullptr) {
        throw runtime_error("Deserialization failed");
    }

    // Cast the deserialized object to the correct class
    if (!env->IsInstanceOf(deserializedObj, objClass)) {
        throw runtime_error("Deserialized object is not an instance of com.example.MyClass");
    }

    // Return the deserialized object
    return env->NewGlobalRef(deserializedObj);
}
```
