const { spawn } = require('child_process');

async function addVerticesAndEdges(graph, numVertices, numEdges) {
  const command = 'some-shell-command';
  const args = ['arg1', 'arg2'];
  const options = { stdio: 'pipe' };

  try {
    const childProcess = spawn(command, args, options);
    const stdout = await getStdout(childProcess);
    const stderr = await getStderr(childProcess);

    if (stderr) {
      console.error(`Error executing command: ${stderr}`);
      return;
    }

    const results = JSON.parse(stdout);
    graph.addVertices(results.vertices);
    graph.addEdges(results.edges);

    for (const vertex of graph.getVertices()) {
      vertex.setProperty('random', Math.random());
    }

    for (const edge of graph.getEdges()) {
      edge.setProperty('random', Math.random());
    }

    return {
      updatedGraph: graph,
      commandResults: results,
    };
  } catch (error) {
    console.error(`Error executing function: ${error}`);
    return;
  }
}

async function getStdout(childProcess) {
  const stdout = [];
  for await (const data of childProcess.stdout) {
    stdout.push(data.toString());
  }
  return stdout.join('');
}

async function getStderr(childProcess) {
  const stderr = [];
  for await (const data of childProcess.stderr) {
    stderr.push(data.toString());
  }
  return stderr.join('');
}
