['```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use tokio::time::{Instant, Duration};

struct Task {
    id: String,
    description: String,
    scheduled_time: Instant,
}

impl Task {
    fn new(id: &str, description: &str, scheduled_time: Instant) -> Self {
        Self {
            id: id.to_string(),
            description: description.to_string(),
            scheduled_time,
        }
    }
}

struct TaskScheduler {
    tasks: HashMap<String, Arc<Mutex<Task>>>,
}

impl TaskScheduler {
    fn new() -> Self {
        Self {
            tasks: HashMap::new(),
        }
    }

    fn add_task(&mut self, id: &str, description: &str, scheduled_time: Instant) {
        let task = Arc::new(Mutex::new(Task::new(id, description, scheduled_time)));
        self.tasks.insert(id.to_string(), task);
    }

    fn remove_task(&mut self, id: &str) -> Option<Arc<Mutex<Task>>> {
        self.tasks.remove(id)
    }

    fn list_tasks(&self) -> Vec<String> {
        self.tasks.keys().cloned().collect()
    }

    fn run_task(&mut self, id: &str) -> Option<Arc<Mutex<Task>>> {
        let task = self.tasks.get(id)?;
        let mut task = task.lock().unwrap();
        if Instant::now() >= task.scheduled_time {
            Some(task)
        } else {
            None
        }
    }
}

fn main() {
    let mut scheduler = TaskScheduler::new();

    // Add a new task with ID "task1" and description "Task 1" that is scheduled to run in 5 seconds.
    scheduler.add_task("task1", "Task 1", Instant::now() + Duration::from_secs(5));

    // Remove the task with ID "task2".
    scheduler.remove_task("task2");

    // List all tasks and their descriptions.
    println!("Tasks: {:?}", scheduler.list_tasks());

    // Run the task with ID "task1" if it is scheduled to run.
    let task = scheduler.run_task("task1");
    if let Some(task) = task {
        let mut task = task.lock().unwrap();
        println!("Task {} ran at {:?}", task.id, task.scheduled_time);
    } else {
        println!("Task not scheduled to run.");
    }
}
```
This code uses the `tokio` library to handle concurrent tasks and scheduling gracefully without data races. The `TaskScheduler` struct maintains a hash map of task IDs to `Arc<Mutex<Task>>`, where each task is represented by its ID, description, and scheduled execution time.

The `add_task` method adds a new task to the scheduler with the given ID, description, and scheduled execution time. The `remove_task` method removes a task from the scheduler with the given ID. The `list_tasks` method returns a vector of all tasks and their descriptions.

The `run_task` method checks if the task with the given ID is scheduled to run and returns its `Arc<Mutex<Task>>` if it is, or `None` otherwise. If the task is returned, its description and scheduled execution time are printed to the console.

Note that this code assumes that the program runs indefinitely and that tasks are added and removed continuously. To persist task data between program runs, you can use a file-based storage system or a database like SQLite.']

