fn manage_config_dir(config_id: &str) -> Result<(), String> {
    let config_dir = env::var("CONFIG_DIR").unwrap();
    let mut path = PathBuf::from(&config_dir);
    path.push(config_id);

    if !path.exists() {
        fs::create_dir(&path).map_err(|e| format!("Failed to create directory: {}", e))?;
        env::set_var("CONFIG_DIR", &path);
    } else {
        let config_dir = env::var("CONFIG_DIR").unwrap();
        if !config_dir.ends_with(config_id) {
            return Err(format!("Invalid configuration ID: {}", config_id));
        }
    }

    Ok(())
}
