    jwt_t jwt = parse_jwt(token);

    // Check that the sub and iss claims are non-empty strings
    if (strlen(jwt.payload[SUB]) == 0 || strlen(jwt.payload[ISS]) == 0) {
        return false;
    }

    // Check that the exp claim is a valid timestamp indicating a future date
    long exp = atol(jwt.payload[EXP]);
    if (exp <= time(NULL)) {
        return false;
    }

    // Check that the nbf claim is either omitted or a valid timestamp indicating a past date
    long nbf = 0;
    if (strlen(jwt.payload[NBF]) > 0) {
        nbf = atol(jwt.payload[NBF]);
        if (nbf >= time(NULL)) {
            return false;
        }
    }

    // Check that the signature is valid for the given mode
    switch (mode) {
        case CBC:
