            if (!AES_ctr_verify(EVP_aes_256_cbc(), jwt.signature, strlen(jwt.signature), jwt.payload, strlen(jwt.payload), NULL)) {
                return false;
            }
            break;
        case GCM:
            // Use AES-GCM to verify the signature
            if (!AES_gcm_verify(EVP_aes_256_cbc(), jwt.signature, strlen(jwt.signature), jwt.payload, strlen(jwt.payload), NULL)) {
                return false;
            }
            break;
        case OFB:
