// Define constants for the program
#define MAX_FILE_SIZE 1024 * 1024 // 1 MB
#define MAX_CONCURRENT_THREADS 8
#define VERBOSE_LEVEL 3

// Define a structure to hold information about each file being processed
typedef struct {
    char* filename;
    int fd;
    size_t filesize;
} file_info_t;

// Define a function to handle errors and recover from failures
void error_handler(const char* message) {
    printf("Error: %s\n", message);
}

// Define a function to read a file in chunks, ensuring memory usage is within limits
int read_file(char* filename, void** buffer, size_t* filesize) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        error_handler("Failed to open file");
        return -1;
    }

    struct stat st;
    if (fstat(fd, &st) == -1) {
        error_handler("Failed to get file size");
        close(fd);
        return -1;
    }

    *filesize = st.st_size;
    if (*filesize > MAX_FILE_SIZE) {
        error_handler("File is too large");
        close(fd);
        return -1;
    }

    void* buf = malloc(*filesize);
    if (buf == NULL) {
        error_handler("Failed to allocate memory for file");
        close(fd);
        return -1;
    }

    ssize_t bytes_read = read(fd, buf, *filesize);
    if (bytes_read < 0) {
        error_handler("Failed to read from file");
        free(buf);
        close(fd);
        return -1;
    }

    *buffer = buf;
    close(fd);
    return bytes_read;
}

// Define a function to process a single file in parallel
void* process_file(void* arg) {
    file_info_t* info = (file_info_t*)arg;
    void* buffer = NULL;
    size_t filesize = 0;

    // Read the file into memory
    if (read_file(info->filename, &buffer, &filesize) == -1) {
        error_handler("Failed to read file");
        return NULL;
    }

    // Process the file in some way
    printf("Processing file %s\n", info->filename);

    // Clean up memory and close file descriptor
    free(buffer);
    close(info->fd);
    return NULL;
}

// Define a function to process multiple files in parallel, with concurrency limit
void process_files(char** filenames, int num_filenames) {
    // Create an array of file information structures
    file_info_t* infos = malloc(num_filenames * sizeof(file_info_t));
    if (infos == NULL) {
        error_handler("Failed to allocate memory for file information");
        return;
    }

    // Initialize the file information structures
    for (int i = 0; i < num_filenames; i++) {
        infos[i].filename = filenames[i];
        infos[i].fd = -1;
        infos[i].filesize = 0;
    }

    // Create a semaphore to limit the number of concurrent threads
    sem_t* sem = sem_open("sem", O_CREAT, 0644, MAX_CONCURRENT_THREADS);
    if (sem == SEM_FAILED) {
        error_handler("Failed to create semaphore");
        free(infos);
        return;
    }

    // Create an array of threads to process the files
    pthread_t* threads = malloc(num_filenames * sizeof(pthread_t));
    if (threads == NULL) {
        error_handler("Failed to allocate memory for thread information");
        sem_close(sem);
        free(infos);
        return;
    }

    // Initialize the threads and start processing the files
    for (int i = 0; i < num_filenames; i++) {
        infos[i].fd = open(infos[i].filename, O_RDONLY);
        if (infos[i].fd == -1) {
            error_handler("Failed to open file");
            continue;
        }

        // Acquire a semaphore before starting the thread
        if (sem_wait(sem) == -1) {
            error_handler("Failed to acquire semaphore");
            close(infos[i].fd);
            continue;
        }

        int rc = pthread_create(&threads[i], NULL, process_file, &infos[i]);
        if (rc != 0) {
            error_handler("Failed to create thread");
            sem_post(sem);
            close(infos[i].fd);
            continue;
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_filenames; i++) {
        if (threads[i] != NULL) {
            pthread_join(threads[i], NULL);
        }
    }

    // Clean up memory and close semaphore
    free(infos);
    free(threads);
    sem_close(sem);
}

