EVP_CIPHER *validateJWT(const char *jwt, const char *json) {
    // Initialize the OpenSSL library
    OPENSSL_init_crypto(OPENSSL_INIT_ADD_ALL_CIPHERS | OPENSSL_INIT_ADD_ALL_DIGESTS, NULL);

    // Parse the JSON object
    json_error_t error;
    json_t *root = json_loads(json, 0, &error);
    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return NULL;
    }

    // Extract the access token and expiration time from the JWT
    const char *access_token = json_string_value(json_object_get(root, "access_token"));
    int expires_in = json_integer_value(json_object_get(root, "expires_in"));
    if (expires_in <= 0) {
        fprintf(stderr, "Invalid expiration time: %d\n", expires_in);
        return NULL;
    }

    // Verify that the token type is 'Bearer'
    const char *token_type = json_string_value(json_object_get(root, "token_type"));
    if (strcmp(token_type, "Bearer") != 0) {
        fprintf(stderr, "Invalid token type: %s\n", token_type);
        return NULL;
    }

    // Verify that the access token is valid according to the provided JWT verification keys
    if (!json_object_get(root, "refresh_token")) {
        fprintf(stderr, "Missing refresh token\n");
        return NULL;
    }

    // Set up the DES cipher for encryption/decryption
