    switch (json_string_value(json_object_get(root, "mode"))) {
        case "ECB":
            cipher = EVP_des_ecb();
            break;
        case "EDE":
            cipher = EVP_des_ede();
            break;
        case "EDE3":
            cipher = EVP_des_ede3();
            break;
        case "CFB":
