            break;
        default:
            fprintf(stderr, "Invalid mode: %s\n", json_string_value(json_object_get(root, "mode")));
            return NULL;
    }

    // Set up the cryptographic ciphers using the DES algorithm
    if (!EVP_CipherInit(cipher, NULL, NULL, 1)) {
        fprintf(stderr, "Failed to initialize cipher\n");
        return NULL;
    }

    // Handle multiple types of token expiration checks and ensure that the token has not been tampered with before processing
    if (expires_in < 0) {
        fprintf(stderr, "Invalid expiration time: %d\n", expires_in);
        return NULL;
    }

    // Return a pointer to an EVP_CIPHER structure representing the chosen cipher
    return cipher;
}
