import java.io.File;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import javax.crypto.Cipher;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import org.apache.commons.io.FileUtils;
import org.apache.commons.lang3.StringUtils;
import org.bouncycastle.jce.provider.BouncyCastleProvider;
import org.openssl.EVP_add_cipher;
import org.openssl.EVP_add_digest;
import org.openssl.EVP_add_digest_alias;
import org.openssl.OpenSSLException;

public class CryptographicPrimitives {
    private static final Map<String, Cipher> ciphers = new HashMap<>();
    private static final Map<String, Mac> macs = new HashMap<>();
    private static final String CONFIG_FILE_PATH = "config.txt";
    private static final int HASH_LENGTH = 32; // in bytes

    public static void addCryptographicPrimitives(String configFilePath) {
        if (StringUtils.isBlank(configFilePath)) {
            throw new IllegalArgumentException("Configuration file path cannot be null or empty");
        }

        try {
            // Load configuration from securely encrypted file
            String config = FileUtils.readFileToString(new File(configFilePath), "UTF-8");
            if (StringUtils.isBlank(config)) {
                throw new IllegalArgumentException("Configuration file is empty or invalid");
            }

            // Parse configuration and add cryptographic primitives
            String[] lines = config.split("\n");
            for (String line : lines) {
                if (line.startsWith("#")) continue; // skip comments
                String[] tokens = line.trim().split("\\s+");
                if (tokens.length < 2) continue; // skip invalid lines

                String primitiveName = tokens[0];
                String primitiveType = tokens[1];
                switch (primitiveType) {
                    case "cipher":
                        addCipher(primitiveName, tokens);
                        break;
                    case "digest":
                        addDigest(primitiveName, tokens);
                        break;
                    case "digest-alias":
                        addDigestAlias(primitiveName, tokens);
                        break;
                }
            }
        } catch (Exception e) {
            throw new OpenSSLException("Failed to load cryptographic primitives", e);
        }
    }

    private static void addCipher(String primitiveName, String[] tokens) throws NoSuchAlgorithmException {
        if (ciphers.containsKey(primitiveName)) return; // skip duplicate entries

        int mode = Integer.parseInt(tokens[2]);
        int padding = Integer.parseInt(tokens[3]);
        Cipher cipher = Cipher.getInstance(primitiveName);
        cipher.init(mode, new SecretKeySpec(Arrays.copyOfRange(tokens, 4, tokens.length), primitiveName));
        ciphers.put(primitiveName, cipher);
    }

    private static void addDigest(String primitiveName, String[] tokens) throws NoSuchAlgorithmException {
        if (macs.containsKey(primitiveName)) return; // skip duplicate entries

        Mac mac = Mac.getInstance(primitiveName);
        mac.init(new SecretKeySpec(Arrays.copyOfRange(tokens, 2, tokens.length), primitiveName));
        macs.put(primitiveName, mac);
    }

    private static void addDigestAlias(String primitiveName, String[] tokens) throws NoSuchAlgorithmException {
        if (macs.containsKey(primitiveName)) return; // skip duplicate entries

        Mac mac = Mac.getInstance(tokens[2]);
        mac.init(new SecretKeySpec(Arrays.copyOfRange(tokens, 3, tokens.length), primitiveName));
        macs.put(primitiveName, mac);
    }

    public static byte[] encrypt(String plaintext) {
        try {
            Cipher cipher = getCipher("AES/ECB/PKCS5Padding");
            return cipher.doFinal(plaintext.getBytes());
        } catch (Exception e) {
            throw new OpenSSLException("Failed to encrypt plaintext", e);
        }
    }

    public static byte[] decrypt(byte[] ciphertext) {
        try {
            Cipher cipher = getCipher("AES/ECB/PKCS5Padding");
            return cipher.doFinal(ciphertext);
        } catch (Exception e) {
            throw new OpenSSLException("Failed to decrypt ciphertext", e);
        }
    }

    public static byte[] hash(String data) {
        try {
            Mac mac = getMac("SHA-256");
            return mac.doFinal(data.getBytes());
        } catch (Exception e) {
            throw new OpenSSLException("Failed to generate hash", e);
        }
    }

    public static byte[] sign(byte[] data, String privateKey) {
        try {
            Mac mac = getMac("SHA-256");
            return mac.doFinal(data);
        } catch (Exception e) {
            throw new OpenSSLException("Failed to generate signature", e);
        }
    }

    public static boolean verify(byte[] data, byte[] signature, String publicKey) {
        try {
            Mac mac = getMac("SHA-256");
            return Arrays.equals(mac.doFinal(data), signature);
        } catch (Exception e) {
            throw new OpenSSLException("Failed to verify signature", e);
        }
    }

    private static Cipher getCipher(String algorithm) throws NoSuchAlgorithmException, InvalidKeyException {
        if (!ciphers.containsKey(algorithm)) {
            EVP_add_cipher(algorithm);
            ciphers.put(algorithm, Cipher.getInstance(algorithm));
        }
        return ciphers.get(algorithm);
    }

    private static Mac getMac(String algorithm) throws NoSuchAlgorithmException, InvalidKeyException {
        if (!macs.containsKey(algorithm)) {
            EVP_add_digest(algorithm);
            macs.put(algorithm, Mac.getInstance(algorithm));
        }
        return macs.get(algorithm);
    }
}
