// Define the error codes for the cleanup function
#define ERR_CIPHER_INIT 1
#define ERR_FILENAME_RENAME 2
#define ERR_CLEANUP 3

// Define the structure to hold the cipher context and the modified filename
typedef struct {
    EVP_CIPHER_CTX *ctx;
    char *filename;
} CipherContext;

// Function to initialize the AES-256-CBC cipher with a password and derive a secure key
int initEncryptAndRename(const char *filename, const char *password, int num_digits) {
    // Check if the filename is valid
    if (filename == NULL || strlen(filename) == 0) {
        return ERR_FILENAME_RENAME;
    }

    // Check if the password is valid
    if (password == NULL || strlen(password) < 16) {
        return ERR_CIPHER_INIT;
    }

    // Create a new cipher context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return ERR_CLEANUP;
    }

    // Set the key length and IV length according to the user-provided integer
    int key_len = 32;
    int iv_len = 16;
    if (num_digits > 0) {
        key_len += num_digits * 8;
        iv_len += num_digits * 8;
    }

    // Initialize the cipher with the given password and salt
    int ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char *)password, (unsigned char *)"salt");
    if (ret != 1) {
        return ERR_CIPHER_INIT;
    }

    // Derive a secure key and IV using a secure KDF
    unsigned char key[key_len];
    unsigned char iv[iv_len];
    ret = EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL, (unsigned char *)password, strlen(password), 1, key, iv);
    if (ret != 1) {
        return ERR_CLEANUP;
    }

    // Set the key and IV for the cipher context
    ret = EVP_CIPHER_CTX_set_key_length(ctx, key_len);
    if (ret != 1) {
        return ERR_CLEANUP;
    }
    ret = EVP_CIPHER_CTX_set_iv_length(ctx, iv_len);
    if (ret != 1) {
        return ERR_CLEANUP;
    }
    ret = EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    if (ret != 1) {
        return ERR_CLEANUP;
    }

    // Rename the file by appending a string of digits corresponding to the user-specified length
    char *new_filename = malloc(strlen(filename) + num_digits + 1);
    if (new_filename == NULL) {
        return ERR_FILENAME_RENAME;
    }
    strcpy(new_filename, filename);
    sprintf(new_filename + strlen(filename), "%0*d", num_digits, rand() % 1000000000);
    ret = rename(filename, new_filename);
    if (ret != 0) {
        return ERR_FILENAME_RENAME;
    }

    // Create a new structure to hold the cipher context and the modified filename
    CipherContext *cipher_context = malloc(sizeof(CipherContext));
    if (cipher_context == NULL) {
        return ERR_CLEANUP;
    }
    cipher_context->ctx = ctx;
    cipher_context->filename = new_filename;

    // Return the pointer to the cipher context and the modified filename
    return (void *)cipher_context;
}

// Function to clean up the cipher context and disable the cipher when it is no longer needed
int cleanup(CipherContext *cipher_context) {
    // Check if the cipher context is valid
    if (cipher_context == NULL || cipher_context->ctx == NULL) {
        return ERR_CLEANUP;
    }

    // Disable the cipher and free the memory allocated for the cipher context
    EVP_CIPHER_CTX_cleanup(cipher_context->ctx);
    free(cipher_context->filename);
    free(cipher_context);

    return 0;
}
