#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Define constants for the compression level, password length, and file format identifier
#define COMPRESSION_LEVEL 6
#define PASSWORD_LENGTH 32
#define FILE_FORMAT_IDENTIFIER "encrypted"

// Define a struct to hold the cipher context and modified filename
struct CipherContext {
    EVP_CIPHER_CTX *ctx;
    char *filename;
};

// Function to generate a secure 256-bit encryption key and initialization vector (IV) using a KDF
void generateKeyAndIv(unsigned char *key, unsigned char *iv, const char *password) {
    // Use PBKDF2 with SHA-256 as the PRF to derive the key and IV from the password
    EVP_PKEY_CTX *pctx = NULL;
    EVP_PKEY *pkey = NULL;
    unsigned char salt[32];
    RAND_bytes(salt, sizeof(salt));
    pctx = EVP_PKEY_CTX_new_id(EVP_PKEY_HKDF, NULL);
    if (pctx == NULL) {
        fprintf(stderr, "Error: failed to create PBKDF2 context\n");
        return;
    }
    EVP_PKEY_derive_init(pctx);
    EVP_PKEY_CTX_set_hkdf_md(pctx, EVP_sha256());
    EVP_PKEY_CTX_set_hkdf_salt(pctx, salt, sizeof(salt));
    EVP_PKEY_CTX_set_hkdf_key(pctx, password, strlen(password));
    if (EVP_PKEY_derive(pctx, key, 32) <= 0 || EVP_PKEY_derive(pctx, iv, 16) <= 0) {
        fprintf(stderr, "Error: failed to derive key and IV\n");
        return;
    }
    EVP_PKEY_CTX_free(pctx);
}

// Function to compress a file using zlib with the given compression level
int compressFile(const char *filename, int compressionLevel) {
    // Open the input file for reading
    FILE *input = fopen(filename, "rb");
    if (input == NULL) {
        fprintf(stderr, "Error: failed to open input file\n");
        return -1;
    }

    // Create a new output file with the same name but with a .gz extension
    char *outputFilename = malloc(strlen(filename) + 4);
    strcpy(outputFilename, filename);
    strcat(outputFilename, ".gz");
    FILE *output = fopen(outputFilename, "wb");
    if (output == NULL) {
        fprintf(stderr, "Error: failed to create output file\n");
        return -1;
    }

    // Compress the input file using zlib with the given compression level
    int ret = 0;
    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;
    strm.avail_in = 0;
    strm.next_in = Z_NULL;
    ret = deflateInit2(&strm, compressionLevel, Z_DEFLATED, 15 + 16, 8, Z_DEFAULT_STRATEGY);
    if (ret != Z_OK) {
        fprintf(stderr, "Error: failed to initialize zlib\n");
        return -1;
    }
    do {
        strm.avail_in = fread(strm.next_in, 1, CHUNK, input);
        if (ferror(input)) {
            fprintf(stderr, "Error: failed to read from input file\n");
            return -1;
        }
        do {
            strm.avail_out = CHUNK;
            strm.next_out = outputBuffer;
            ret = deflate(&strm, Z_FINISH);
            if (ret == Z_STREAM_ERROR) {
                fprintf(stderr, "Error: failed to compress data\n");
                return -1;
            }
            fwrite(outputBuffer, 1, CHUNK - strm.avail_out, output);
        } while (strm.avail_out == 0);
    } while (strm.avail_in != 0);
    deflateEnd(&strm);
    fclose(input);
    fclose(output);
    return 0;
}

// Function to encrypt a file using AES-256-CBC with the given key and IV
int encryptFile(const char *filename, unsigned char *key, unsigned char *iv) {
    // Open the input file for reading
    FILE *input = fopen(filename, "rb");
    if (input == NULL) {
        fprintf(stderr, "Error: failed to open input file\n");
        return -1;
    }

    // Create a new output file with the same name but with an .enc extension
    char *outputFilename = malloc(strlen(filename) + 5);
    strcpy(outputFilename, filename);
    strcat(outputFilename, ".enc");
    FILE *output = fopen(outputFilename, "wb");
    if (output == NULL) {
        fprintf(stderr, "Error: failed to create output file\n");
        return -1;
    }

    // Encrypt the input file using AES-256-CBC with the given key and IV
    EVP_CIPHER_CTX *ctx = NULL;
    int ret = 0;
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Error: failed to create cipher context\n");
        return -1;
    }
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    do {
        strm.avail_in = fread(strm.next_in, 1, CHUNK, input);
        if (ferror(input)) {
            fprintf(stderr, "Error: failed to read from input file\n");
            return -1;
        }
        do {
            strm.avail_out = CHUNK;
            strm.next_out = outputBuffer;
            ret = EVP_EncryptUpdate(ctx, outputBuffer, &strm.avail_out, strm.next_in, strm.avail_in);
            if (ret == 0) {
                fprintf(stderr, "Error: failed to encrypt data\n");
                return -1;
            }
            fwrite(outputBuffer, 1, CHUNK - strm.avail_out, output);
        } while (strm.avail_out == 0);
    } while (strm.avail_in != 0);
    EVP_EncryptFinal_ex(ctx, outputBuffer, &strm.avail_out);
    if (ret == 0) {
        fprintf(stderr, "Error: failed to encrypt data\n");
        return -1;
    }
    EVP_CIPHER_CTX_free(ctx);
    fclose(input);
    fclose(output);
    return 0;
}

// Function to append a string of digits corresponding to the user-specified length to the file's existing extension to create a new filename
void appendDigitsToExtension(char *filename, int numDigits) {
    // Get the original filename and extension
    char *originalFilename = strtok(filename, ".");
    char *extension = strtok(NULL, ".");

    // Create a new filename with the original filename, a hyphen, and the specified number of digits
    int numChars = strlen(originalFilename) + 1 + numDigits;
    char *newFilename = malloc(numChars);
    snprintf(newFilename, numChars, "%s-%0*d.%s", originalFilename, numDigits, 0, extension);

    // Replace the original filename with the new one
    strcpy(filename, newFilename);
}

// Function to handle edge cases, including invalid password lengths, insufficient memory for compression, and potential errors in generating the cipher or renaming the file
int processFile(const char *filename, int compressionLevel, int maxSizeInKb, const char *password, const char *fileFormatIdentifier) {
    // Check if the password is valid
    if (strlen(password) < PASSWORD_LENGTH) {
        fprintf(stderr, "Error: invalid password length\n");
        return -1;
    }

    // Allocate memory for the encryption key and initialization vector
    unsigned char key[32];
    unsigned char iv[16];

    // Generate a secure 256-bit encryption key and initialization vector using a KDF
    generateKeyAndIv(key, iv, password);

    // Compress the file using zlib with the given compression level
    int ret = compressFile(filename, compressionLevel);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to compress file\n");
        return -1;
    }

    // Get the size of the compressed file in bytes
    struct stat st;
    stat(filename, &st);
    int fileSizeInBytes = st.st_size;

    // Check if the compressed file is larger than the maximum allowed size in kilobytes
    if (fileSizeInBytes > maxSizeInKb * 1024) {
        fprintf(stderr, "Error: compressed file exceeds maximum size\n");
        return -1;
    }

    // Encrypt the compressed data using AES-256-CBC with the given key and IV
    ret = encryptFile(filename, key, iv);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to encrypt file\n");
        return -1;
    }

    // Append a string of digits corresponding to the user-specified length to the file's existing extension to create a new filename
    appendDigitsToExtension(filename, strlen(fileFormatIdentifier));

    // Return a pointer to the cipher context and the modified filename
    struct CipherContext *cipherContext = malloc(sizeof(struct CipherContext));
    cipherContext->ctx = EVP_CIPHER_CTX_new();
    cipherContext->filename = strdup(filename);
    return cipherContext;
}

// Function to disable the cipher and free resources when they are no longer needed
void cleanup(struct CipherContext *cipherContext) {
    EVP_CIPHER_CTX_free(cipherContext->ctx);
    free(cipherContext->filename);
}
