#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Define the error codes for the cleanup function
#define ERR_CIPHER_INIT 1
#define ERR_FILE_OPEN 2
#define ERR_FILE_READ 3
#define ERR_FILE_WRITE 4
#define ERR_IV_GENERATION 5
#define ERR_KEY_DERIVATION 6
#define ERR_SEQUENCE_NUMBER 7

// Define the structure for the cipher context and initialization vector
typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[12];
} CipherContext;

// Function to generate a random initialization vector (IV)
void generate_iv(unsigned char iv[12]) {
    // Generate a random IV using OpenSSL's RAND_bytes function
    if (!RAND_bytes(iv, 12)) {
        ERR_load_crypto_strings();
        fprintf(stderr, "Error generating initialization vector: %s\n", ERR_error_string(ERR_get_error(), NULL));
        exit(EXIT_FAILURE);
    }
}

// Function to derive a 256-bit encryption key from the password and salt
void derive_key(const char *password, const unsigned char *salt, unsigned char key[32]) {
    // Derive the key using OpenSSL's EVP_BytesToKey function with the given password and salt
    if (!EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, (unsigned char *)password, strlen(password), 1000, key, NULL)) {
        ERR_load_crypto_strings();
        fprintf(stderr, "Error deriving encryption key: %s\n", ERR_error_string(ERR_get_error(), NULL));
        exit(EXIT_FAILURE);
    }
}

// Function to read the last line of a file and extract the sequence number
int get_sequence_number(const char *filename, unsigned long *sequence_number) {
    // Open the file in read-only mode
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        ERR_load_crypto_strings();
        fprintf(stderr, "Error opening file: %s\n", filename);
        return ERR_FILE_OPEN;
    }

    // Read the last line of the file
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Extract the sequence number from the last line
        char *sequence_number_str = strtok(line, " ");
        if (sequence_number_str == NULL) {
            fprintf(stderr, "Error extracting sequence number: %s\n", filename);
            return ERR_SEQUENCE_NUMBER;
        }
        *sequence_number = atoi(sequence_number_str);
    }

    // Close the file and free the memory allocated for the line buffer
    fclose(file);
    free(line);

    return 0;
}

// Function to rename a file by appending a sequence number
int rename_file(const char *filename, unsigned long sequence_number) {
    // Construct the new filename by appending the sequence number
    char new_filename[256];
    snprintf(new_filename, sizeof(new_filename), "%s.%lu", filename, sequence_number);

    // Rename the file using OpenSSL's EVP_CIPHER_CTX_ctrl function
    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_RENAME, new_filename)) {
        ERR_load_crypto_strings();
        fprintf(stderr, "Error renaming file: %s\n", filename);
        return ERR_FILE_WRITE;
    }

    return 0;
}

// Function to initialize the cipher context and encryption key
CipherContext *init_cipher(const char *password, const unsigned char *salt) {
    // Allocate memory for the cipher context structure
    CipherContext *ctx = malloc(sizeof(CipherContext));
    if (ctx == NULL) {
        fprintf(stderr, "Error allocating memory for cipher context\n");
        return NULL;
    }

    // Generate a random initialization vector (IV)
    generate_iv(ctx->iv);

    // Derive the encryption key from the password and salt
    derive_key(password, salt, ctx->key);

    // Initialize the cipher context using OpenSSL's EVP_CIPHER_CTX_init function
    if (!EVP_CIPHER_CTX_init(ctx->ctx, EVP_aes_256_cbc(), ctx->key, ctx->iv)) {
        ERR_load_crypto_strings();
        fprintf(stderr, "Error initializing cipher context: %s\n", filename);
        return NULL;
    }

    return ctx;
}

// Function to clean up the cipher context and disable encryption
void cleanup_cipher(CipherContext *ctx) {
    // Disable encryption using OpenSSL's EVP_CIPHER_CTX_cleanup function
    if (!EVP_CIPHER_CTX_cleanup(ctx->ctx)) {
        ERR_load_crypto_strings();
        fprintf(stderr, "Error cleaning up cipher context: %s\n", filename);
        return;
    }

    // Free the memory allocated for the cipher context structure
    free(ctx);
}

// Function to process a file and sort its lines
int processFileAndSort(const char *filename, const char *password, int num_digits) {
    // Initialize the cipher context and encryption key using the given password and salt
    CipherContext *ctx = init_cipher(password, salt);
    if (ctx == NULL) {
        return ERR_CIPHER_INIT;
    }

    // Read the last line of the file to extract the sequence number
    unsigned long sequence_number;
    int ret = get_sequence_number(filename, &sequence_number);
    if (ret != 0) {
        cleanup_cipher(ctx);
        return ret;
    }

    // Sort the lines of the file using OpenSSL's EVP_CIPHER_CTX_ctrl function
    if (!EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_SET_SORT_KEY, 0, NULL)) {
        ERR_load_crypto_strings();
        fprintf(stderr, "Error sorting lines: %s\n", filename);
        cleanup_cipher(ctx);
        return ERR_FILE_WRITE;
    }

    // Rename the file by appending a sequence number generated from the last line of the sorted file
    ret = rename_file(filename, sequence_number);
    if (ret != 0) {
        cleanup_cipher(ctx);
        return ret;
    }

    // Clean up the cipher context and disable encryption using the given password and salt
    cleanup_cipher(ctx);

    return 0;
}
