struct Octree {
    int feature_size;
    int num_leafs;
    std::vector<std::string> prefix_leafs;
    std::vector<std::string> data_arrays;
};

struct CipherContext {
    EVP_CIPHER_CTX* ctx;
    unsigned char key[32];
    unsigned char iv[16];
};

void initializeOctreeAndEncryptFile(const std::string& filename, const std::string& password, int feature_size, int num_leafs) {
    // Check if the file exists and is readable
    std::ifstream file(filename);
    if (!file.good()) {
        std::cerr << "Error: File does not exist or is not readable" << std::endl;
        return;
    }

    // Initialize the octree structure
    Octree* octree = new Octree();
    octree->feature_size = feature_size;
    octree->num_leafs = num_leafs;
    octree->prefix_leafs.resize(octree->num_leafs);
    octree->data_arrays.resize(octree->num_leafs);

    // Initialize the cipher context
    CipherContext* ctx = new CipherContext();
    ctx->ctx = EVP_CIPHER_CTX_new();

    // Derive a 256-bit encryption key and a unique 12-byte initialization vector (IV) using a secure KDF
    unsigned char salt[32];
    RAND_bytes(salt, sizeof(salt));
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, password.c_str(), password.size(), 1000, ctx->key, ctx->iv);

    // Allocate memory for the octree using dynamic allocation, updating the capacity if necessary
    int num_prefix_leafs = (octree->num_leafs + 31) / 32;
    int num_data_arrays = (octree->num_leafs * feature_size + 31) / 32;
    octree->prefix_leafs.resize(num_prefix_leafs);
    octree->data_arrays.resize(num_data_arrays);

    // Initialize the prefix leafs and data arrays within the octree
    for (int i = 0; i < num_prefix_leafs; ++i) {
        octree->prefix_leafs[i].resize(32);
    }
    for (int i = 0; i < num_data_arrays; ++i) {
        octree->data_arrays[i].resize(feature_size * sizeof(float));
    }

    // Read the file, sort its lines lexicographically, and extract a sequence number from the last line
    std::vector<std::string> lines;
    while (file.good()) {
        std::string line;
        getline(file, line);
        if (!line.empty()) {
            lines.push_back(line);
        }
    }
    std::sort(lines.begin(), lines.end());
    int sequence_number = 0;
    if (!lines.empty()) {
        std::string last_line = lines.back();
        std::istringstream iss(last_line);
        iss >> sequence_number;
    }

    // Rename the file accordingly and encrypt it using AES-256-CBC
    std::string new_filename = filename + "." + std::to_string(sequence_number);
    EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv);
    FILE* fp = fopen(new_filename.c_str(), "wb");
    for (const auto& line : lines) {
        std::string encrypted_line;
        EVP_EncryptUpdate(ctx->ctx, encrypted_line.data(), &encrypted_line.size(), line.data(), line.size());
        fwrite(encrypted_line.data(), 1, encrypted_line.size(), fp);
    }
    fclose(fp);

    // Cleanup the cipher context and deallocate the octree when it is no longer needed
    EVP_CIPHER_CTX_free(ctx->ctx);
    delete ctx;
    delete octree;
}

void cleanup(const std::string& filename, const std::string& password) {
    // Disable the cipher and deallocate the octree when it is no longer needed
    CipherContext* ctx = new CipherContext();
    ctx->ctx = EVP_CIPHER_CTX_new();
    unsigned char salt[32];
    RAND_bytes(salt, sizeof(salt));
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, password.c_str(), password.size(), 1000, ctx->key, ctx->iv);
    EVP_CIPHER_CTX_free(ctx->ctx);
    delete ctx;
}
