import java.security.MessageDigest;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.logging.Logger;

public class HashValidator {
    private static final Logger LOGGER = Logger.getLogger(HashValidator.class.getName());
    private static final ConcurrentHashMap<String, String> CACHE = new ConcurrentHashMap<>();
    private static final int TIMEOUT_SECONDS = 10;

    public static String validateHash(String input) {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be null or empty");
        }

        // Check cache first
        String cachedHash = CACHE.get(input);
        if (cachedHash != null) {
            return cachedHash;
        }

        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashBytes = digest.digest(input.getBytes());
            String hash = bytesToHexString(hashBytes);

            // Cache the result for future requests
            CACHE.put(input, hash);

            return hash;
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error validating hash", e);
            throw new RuntimeException("Failed to validate hash");
        }
    }

    private static String bytesToHexString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
```
