// Define the maximum size of the queue
#define MAX_SIZE 10000

// Define the minimum and maximum size thresholds for the queue
#define MIN_THRESHOLD 5000
#define MAX_THRESHOLD 8000

// Define the data structure to hold the queue elements
typedef struct {
    int capacity;
    int size;
    int head;
    int tail;
    void** elements;
} Queue;

// Function to initialize the queue with a specified capacity
Queue* init_queue(int capacity) {
    // Check if the capacity is valid
    if (capacity <= 0 || capacity > MAX_SIZE) {
        return NULL;
    }

    // Allocate memory for the queue structure
    Queue* queue = malloc(sizeof(Queue));
    if (!queue) {
        return NULL;
    }

    // Initialize the queue fields
    queue->capacity = capacity;
    queue->size = 0;
    queue->head = 0;
    queue->tail = 0;
    queue->elements = malloc(sizeof(void*) * capacity);
    if (!queue->elements) {
        free(queue);
        return NULL;
    }

    // Initialize the semaphores for thread synchronization
    sem_init(&queue->semaphore, 0, 1);
    sem_init(&queue->enqueue_semaphore, 0, 0);
    sem_init(&queue->dequeue_semaphore, 0, 0);

    // Return the initialized queue structure
    return queue;
}

// Function to enqueue an element in the queue
int enqueue(Queue* queue, void* element) {
    // Check if the queue is full
    if (queue->size == queue->capacity) {
        return -1;
    }

    // Acquire the semaphore for thread synchronization
    sem_wait(&queue->enqueue_semaphore);

    // Increment the size of the queue
    queue->size++;

    // Add the element to the end of the queue
    queue->elements[queue->tail] = element;

    // Update the tail index
    queue->tail = (queue->tail + 1) % queue->capacity;

    // Release the semaphore for thread synchronization
    sem_post(&queue->enqueue_semaphore);

    // Return the success status
    return 0;
}

// Function to dequeue an element from the queue
void* dequeue(Queue* queue) {
    // Check if the queue is empty
    if (queue->size == 0) {
        return NULL;
    }

    // Acquire the semaphore for thread synchronization
    sem_wait(&queue->dequeue_semaphore);

    // Decrement the size of the queue
    queue->size--;

    // Get the element from the front of the queue
    void* element = queue->elements[queue->head];

    // Update the head index
    queue->head = (queue->head + 1) % queue->capacity;

    // Release the semaphore for thread synchronization
    sem_post(&queue->dequeue_semaphore);

    // Return the dequeued element
    return element;
}

// Function to delete the queue and free its resources
void delete_queue(Queue* queue) {
    // Check if the queue is valid
    if (!queue) {
        return;
    }

    // Acquire the semaphore for thread synchronization
    sem_wait(&queue->semaphore);

    // Free the memory allocated to the queue elements
    free(queue->elements);

    // Release the semaphore for thread synchronization
    sem_post(&queue->semaphore);

    // Free the memory allocated to the queue structure
    free(queue);
}

// Function to handle potential race conditions and ensure data integrity under concurrent access
void* race_condition_handler(Queue* queue) {
    // Check if the queue is valid
