    }

    // Dynamically allocate memory for each line of the file
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Calculate the average of the last three fields in the line
        int sum = 0;
        char* token = strtok(line, ",");
        for (int i = 0; i < 3; i++) {
            if (token == NULL) {
                break;
            }
            sum += atoi(token);
            token = strtok(NULL, ",");
