    char buffer[1024];
    do {
        strm.avail_in = fread(buffer, 1, sizeof(buffer), file);
        if (ferror(file)) {
            deflateEnd(&strm);
            return false;
        }
        strm.next_in = buffer;
        do {
            strm.avail_out = sizeof(buffer);
            strm.next_out = buffer;
            result = deflate(&strm, Z_NO_FLUSH);
            if (result == Z_STREAM_ERROR) {
                deflateEnd(&strm);
                return false;
            }
            fwrite(buffer, 1, sizeof(buffer), stdout);
        } while (strm.avail_out == 0);
    } while (strm.avail_in != 0);

    // Finish the compression and free the zlib stream
    result = deflate(&strm, Z_FINISH);
    if (result != Z_STREAM_END) {
        deflateEnd(&strm);
        return false;
    }
    deflateEnd(&strm);

    // Return success
    return true;
