// Define a structure to represent a record
typedef struct {
    int key;
    char *descriptive_string;
} Record;

// Define a data structure to store the records
typedef struct {
    int size;
    int capacity;
    Record **records;
} MoSTState;

// Define a function to initialize the data structure
MoSTState *init_mo_st(int initial_capacity) {
    MoSTState *state = malloc(sizeof(MoSTState));
    state->size = 0;
    state->capacity = initial_capacity;
    state->records = malloc(initial_capacity * sizeof(Record*));
    return state;
}

// Define a function to insert a new record with a given key, if the key does not already exist
void mo_st_insert(MoSTState *state, int key, char *descriptive_string) {
    // Check if the key already exists in the data structure
    for (int i = 0; i < state->size; i++) {
        if (state->records[i]->key == key) {
            return;
        }
    }

    // If the key does not exist, allocate a new record and insert it into the data structure
    Record *new_record = malloc(sizeof(Record));
    new_record->key = key;
    new_record->descriptive_string = descriptive_string;
    state->records[state->size++] = new_record;

    // If the data structure is at capacity, double its size
    if (state->size == state->capacity) {
        state->capacity *= 2;
        state->records = realloc(state->records, state->capacity * sizeof(Record*));
    }
}

// Define a function to update the value of an existing record based on its key
void mo_st_update(MoSTState *state, int key, char *descriptive_string) {
    // Find the index of the record with the given key
    for (int i = 0; i < state->size; i++) {
        if (state->records[i]->key == key) {
            free(state->records[i]->descriptive_string);
            state->records[i]->descriptive_string = descriptive_string;
            return;
        }
    }
}

// Define a function to retrieve the value of a record by its key
Record *mo_st_get(MoSTState *state, int key) {
    // Find the index of the record with the given key
    for (int i = 0; i < state->size; i++) {
        if (state->records[i]->key == key) {
            return state->records[i];
        }
    }
    return NULL;
}

// Define a function to remove a record by its key
void mo_st_remove(MoSTState *state, int key) {
    // Find the index of the record with the given key
    for (int i = 0; i < state->size; i++) {
        if (state->records[i]->key == key) {
            free(state->records[i]);
            state->records[i] = NULL;
            return;
        }
    }
}

// Define a function to destroy the data structure and deallocate all memory
void mo_st_destroy(MoSTState *state) {
    for (int i = 0; i < state->size; i++) {
        free(state->records[i]);
    }
    free(state->records);
    free(state);
}
