// Function to generate an RSA key pair with a variable modulus size based on user input parameters
RSA* generate_key_pair(int modulus_size) {
    // Check if the modulus size is valid and at least 2048 bits
    if (modulus_size < 2048) {
        return NULL;
    }

    // Initialize an RSA key pair with a variable modulus size
    RSA* rsa = RSA_new();
    BIGNUM* bn = BN_new();
    BN_set_word(bn, modulus_size);
    RSA_generate_key_ex(rsa, bn, NULL);

    // Use a secure random number generator to seed the key generation process
    unsigned char seed[16];
    if (RAND_bytes(seed, sizeof(seed)) != 1) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }
    RSA_set0_key(rsa, rsa->n, rsa->e, rsa->d);

    // Derive a unique identifier for each key pair to facilitate key management and prevent key reuse across different contexts
    unsigned char* id = (unsigned char*)malloc(sizeof(unsigned char) * 16);
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, seed, sizeof(seed));
    SHA256_Final(id, &ctx);

    // Implement a mechanism to securely store and retrieve the public and private keys
    unsigned char* pub_key = (unsigned char*)malloc(sizeof(unsigned char) * RSA_size(rsa));
    unsigned char* priv_key = (unsigned char*)malloc(sizeof(unsigned char) * RSA_size(rsa));
    RSA_public_encrypt(RSA_size(rsa), rsa->n, pub_key, rsa->e, NULL);
    RSA_private_decrypt(RSA_size(rsa), rsa->d, priv_key, rsa->p, NULL);

    // Clean up and disable the key pair when it is no longer needed
    free(id);
    free(pub_key);
    free(priv_key);
    RSA_free(rsa);
    BN_clear_free(bn);

    return rsa;
}
```
