int initializeAndResolveDNS(const char* password, const char* hostname, int max_length) {
    // Initialize AES-256-CBC cipher with given password
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)password, NULL)) {
        return -1; // Error initializing cipher
    }

    // Set IV length and key length to 16 bytes and 32 bytes respectively
    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SET_IVLEN, 16, NULL) || !EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SET_KEYLEN, 32, NULL)) {
        return -2; // Error setting IV or key length
    }

    // Enable the cipher and return a pointer to the cipher context
    if (!EVP_EncryptEnable(ctx, 1)) {
        return -3; // Error enabling cipher
    }

    // Perform DNS resolution for the provided hostname
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        return -4; // Error resolving DNS
    }

    // Store the resolved IP address in a u_char array
    u_char ip[max_length];
    memcpy(ip, res->ai_addr, max_length);

    // Clean up and disable both cipher and DNS resolution resources when they are no longer needed
    EVP_CIPHER_CTX_free(ctx);
    freeaddrinfo(res);

    return 0; // Success
}
