int streamDataWithRateLimiting(int fd, char *buffer, size_t bufferSize, size_t rateLimit) {
    // Initialize variables
    int bytesTransferred = 0;
    size_t delay = 0;
    struct timespec startTime, endTime;
    double elapsedTime = 0.0;
    int status = 0;

    // Check for invalid rate limit
    if (rateLimit == 0) {
        return -EINVAL;
    }

    // Set non-blocking mode on file descriptor
    if (fcntl(fd, F_SETFL, O_NONBLOCK) < 0) {
        return -errno;
    }

    // Start timer
    clock_gettime(CLOCK_MONOTONIC, &startTime);

    // Loop until all data is transferred or an error occurs
    while (bytesTransferred < bufferSize) {
        // Calculate delay based on transfer rate
        elapsedTime = (double)(endTime.tv_sec - startTime.tv_sec) + (double)(endTime.tv_nsec - startTime.tv_nsec) / 1000000000;
        delay = (size_t)(elapsedTime * rateLimit);

        // Send data in chunks, adjusting delay based on actual transfer rate
        status = send(fd, buffer + bytesTransferred, bufferSize - bytesTransferred, 0);
        if (status < 0) {
            return -errno;
        }
        bytesTransferred += status;

        // Handle edge case where buffer is smaller than rate limit
        if (bytesTransferred == bufferSize) {
            break;
        }

        // Pause and resume streaming as needed to maintain rate limit
        while (delay > 0) {
            usleep(1000);
            delay -= 1000;
        }
    }

    // Cancel operation safely if necessary
    if (bytesTransferred < bufferSize) {
        shutdown(fd, SHUT_RDWR);
    }

    return bytesTransferred;
}
