        String hash = hashCache.get(input);
        if (hash != null) {
            return hash;
        }

        // Compute the MD5 hash of the input string
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = md.digest(input.getBytes());
            hash = bytesToHexString(bytes);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to compute MD5 hash", e);
        }

        // Add the computed hash to the cache and return it
        hashCache.put(input, hash);
        return hash;
    }

    private static String bytesToHexString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
