        // Find the index of the input UE session in the list of UE sessions
        int ueSessionIndex = -1;
        for (int i = 0; i < numUeSessions; i++) {
            if (memcmp(ueSessions[i]->ueId, ueSession->ueId, sizeof(UeIdentity_t)) == 0) {
                ueSessionIndex = i;
                break;
            }
        }

        // Check if the input UE session is found in the list of UE sessions
        if (ueSessionIndex < 0) {
            printf("Error: The input UE session is not found in the list\n");
            pthread_mutex_unlock(&ueSessionMutex);
            return;
        }

        // Remove the input UE session from the list of UE sessions
        LTE_UESession_t *removedUeSession = ueSessions[ueSessionIndex];
        for (int i = ueSessionIndex + 1; i < numUeSessions; i++) {
            ueSessions[i - 1] = ueSessions[i];
        }
        numUeSessions--;

        // Release the mutex for thread safety
        pthread_mutex_unlock(&ueSessionMutex);
