    void optimizeMemoryUsage() {
        // Acquire the mutex for thread safety
        pthread_mutex_lock(&ueSessionMutex);

        // Iterate over the list of UE sessions and remove any duplicates
        int numUniqueUeSessions = 0;
        for (int i = 0; i < numUeSessions; i++) {
            bool isDuplicate = false;
            for (int j = i + 1; j < numUeSessions; j++) {
                if (memcmp(ueSessions[i]->ueId, ueSessions[j]->ueId, sizeof(UeIdentity_t)) == 0) {
                    isDuplicate = true;
                    break;
                }
            }
            if (!isDuplicate) {
                numUniqueUeSessions++;
