        // If there are any duplicates, remove them from the list of UE sessions
        if (numUniqueUeSessions < numUeSessions) {
            LTE_UESession_t **newUeSessions = malloc(sizeof(LTE_UESession_t *) * numUniqueUeSessions);
            int newNumUeSessions = 0;
            for (int i = 0; i < numUeSessions; i++) {
