        // Release the mutex for thread safety
        pthread_mutex_unlock(&ueSessionMutex);
    }

    // Define a function to handle dynamic scaling by adding or removing session management instances based on current load and resource availability
    void handleDynamicScaling() {
        // Acquire the mutex for thread safety
        pthread_mutex_lock(&ueSessionMutex);

        // Check if there is any need to add or remove session management instances based on current load and resource availability
        int numCores = sysconf(_SC_NPROCESSORS_ONLN);
        int numUeSessionsPerCore = numUeSessions / numCores;
        if (numUeSessionsPerCore > MAX_NUM_UE_SESSIONS_PER_CORE) {
            // Add more session management instances to handle the increased load
            LTE_UESession_t **newUeSessions = malloc(sizeof(LTE_UESession_t *) * (numUeSessions + numCores));
            for (int i = 0; i < numUeSessions; i++) {
                newUeSessions[i] = ueSessions[i];
            }
            free(ueSessions);
            ueSessions = newUeSessions;
            numUeSessions += numCores;
