            // Remove some session management instances to reduce the memory footprint and improve lookup times
            LTE_UESession_t **newUeSessions = malloc(sizeof(LTE_UESession_t *) * (numUeSessions - numCores));
            int newNumUeSessions = 0;
            for (int i = 0; i < numUeSessions; i++) {
                if (i % numCores != 0) {
                    newUeSessions[newNumUeSessions++] = ueSessions[i];
                }
            }
            free(ueSessions);
            ueSessions = newUeSessions;
            numUeSessions = newNumUeSessions;
        }

        // Release the mutex for thread safety
        pthread_mutex_unlock(&ueSessionMutex);
    }

    // Define a function to export the current state of all UE sessions in a standardized format (e.g., JSON)
    void exportUESessions(char *fileName) {
        // Acquire the mutex for thread safety
        pthread_mutex_lock(&ueSessionMutex);

        // Open the output file and write the current state of all UE sessions in a standardized format (e.g., JSON)
        FILE *outputFile = fopen(fileName, "w");
        if (outputFile == NULL) {
            printf("Error: Failed to open the output file\n");
            pthread_mutex_unlock(&ueSessionMutex);
            return;
        }
