            fprintf(outputFile, "{\"ueId\": \"%s\", \"ipAddress\": \"%s\", \"portNumber\": %d, \"radioResourceConfigs\": [", ueSessions[i]->ueId.imsi, ueSessions[i]->ipAddress, ueSessions[i]->portNumber);
            for (int j = 0; j < ueSessions[i]->radioResourceConfigs->size(); j++) {
                fprintf(outputFile, "{\"bandwidth\": %d, \"transmissionMode\": %d, \"guardBand\": %d, \"puschPower\": %d, \"pucchPower\": %d}", ueSessions[i]->radioResourceConfigs->get(j)->bandwidth, ueSessions[i]->radioResourceConfigs->get(j)->transmissionMode, ueSessions[i]->radioResourceConfigs->get(j)->guardBand, ueSessions[i]->radioResourceConfigs->get(j)->puschPower, ueSessions[i]->radioResourceConfigs->get(j)->pucchPower);
            }
            fprintf(outputFile, "]}\n");
        }
        fclose(outputFile);

        // Release the mutex for thread safety
        pthread_mutex_unlock(&ueSessionMutex);
    }
}
