    def __init__(self, chunk_size: int = 1024 * 1024, max_threads: int = None):
        self.chunk_size = chunk_size
        self.max_threads = max_threads

    def process_file(self, file_path: str) -> Optional[str]:
        if not os.path.exists(file_path):
