#include <string.h>

// Structure to store transaction data
struct Transaction {
    char user[20];
    float amount;
};

int main() {
    // Open the CSV file for reading
    FILE *file = fopen("transactions.csv", "r");
    if (file == NULL) {
        printf("Error: unable to open file\n");
        return 1;
    }

    // Initialize variables to keep track of total transaction amount and number of transactions per user
    float total_amount = 0.0f;
    int num_transactions = 0;

    // Read the file line by line
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Allocate memory for the transaction data
        struct Transaction *transaction = malloc(sizeof(struct Transaction));
        if (transaction == NULL) {
            printf("Error: unable to allocate memory\n");
            return 1;
        }

        // Parse the line and store the transaction data in the structure
        sscanf(line, "%s %f", transaction->user, &transaction->amount);

        // Update the total transaction amount and number of transactions per user
        total_amount += transaction->amount;
        num_transactions++;

        // Free the memory allocated for the transaction data
        free(transaction);
    }

    // Close the file
    fclose(file);

    // Print the results
    printf("Total transaction amount: $%.2f\n", total_amount);
    printf("Number of transactions per user: %d\n", num_transactions);
    printf("Average transaction amount per user: $%.2f\n", total_amount / (float)num_transactions);

    return 0;
}
```
This code uses the `getline` function to read the file line by line, and the `sscanf` function to parse each line and store the transaction data in a structure. The `malloc` function is used to allocate memory for the structure, and the `free` function is used to free the memory when it is no longer needed.

To optimize performance, the code minimizes memory usage by using dynamic allocation for the structure, and handles large files efficiently without excessive swapping by reading the file line by line instead of loading the entire file into memory at once.']

