```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <limits.h>

// Define the maximum length of a filename
#define MAX_FILENAME_LENGTH 256

// Define the available logging facilities
enum LoggingFacilities {
    LOGGING_FACILITY_SYSLOG,
    LOGGING_FACILITY_FILE,
    LOGGING_FACILITY_CONSOLE
};

// Define the available configuration options for each logging facility
struct LoggingConfig {
    enum LoggingFacilities facility;
    char *filename;
    int log_level;
};

// Define a cache to store the loaded libraries
static struct LibraryCache {
    void *handle;
    struct LoggingConfig config;
} library_cache[MAX_FILENAME_LENGTH];

// Load a logging facility dynamically
void load_logging_facility(const char *filename, enum LoggingFacilities facility) {
    // Check if the filename is valid and not empty
    if (strlen(filename) == 0 || strlen(filename) > MAX_FILENAME_LENGTH) {
        return;
    }

    // Check if the library has already been loaded
    for (int i = 0; i < MAX_FILENAME_LENGTH; i++) {
        if (library_cache[i].handle != NULL && strcmp(filename, library_cache[i].config.filename) == 0) {
            return;
        }
    }

    // Load the library and store it in the cache
    void *handle = dlopen(filename, RTLD_LAZY);
    if (handle != NULL) {
        struct LoggingConfig config = { facility, filename, 0 };
        for (int i = 0; i < MAX_FILENAME_LENGTH; i++) {
            if (library_cache[i].handle == NULL) {
                library_cache[i].handle = handle;
                library_cache[i].config = config;
                break;
            }
        }
    }
}

// Unload a logging facility dynamically
void unload_logging_facility(const char *filename) {
    // Check if the filename is valid and not empty
    if (strlen(filename) == 0 || strlen(filename) > MAX_FILENAME_LENGTH) {
        return;
    }

    // Find the library in the cache and unload it
    for (int i = 0; i < MAX_FILENAME_LENGTH; i++) {
        if (library_cache[i].handle != NULL && strcmp(filename, library_cache[i].config.filename) == 0) {
            dlclose(library_cache[i].handle);
            library_cache[i].handle = NULL;
            break;
        }
    }
}

// Get the logging facility configuration for a given filename
struct LoggingConfig *get_logging_config(const char *filename) {
    // Check if the filename is valid and not empty
    if (strlen(filename) == 0 || strlen(filename) > MAX_FILENAME_LENGTH) {
        return NULL;
    }

    // Find the library in the cache and return its configuration
    for (int i = 0; i < MAX_FILENAME_LENGTH; i++) {
        if (library_cache[i].handle != NULL && strcmp(filename, library_cache[i].config.filename) == 0) {
            return &library_cache[i].config;
        }
    }

    // Return NULL if the library is not found in the cache
    return NULL;
}
