Java Service (LoggingService.java):
```java
import java.util.HashMap;
import java.util.Map;

public class LoggingService {
    private static final Map<String, LoggingFacility> facilities = new HashMap<>();

    public void start() {
        // Load the logging facilities dynamically
        loadLoggingFacilities();
    }

    public void stop() {
        // Unload the logging facilities dynamically
        unloadLoggingFacilities();
    }

    public boolean isRunning() {
        // Check if any logging facility is running
        for (String facility : facilities.keySet()) {
            if (facilities.get(facility).isRunning()) {
                return true;
            }
        }
        return false;
    }

    public void loadLoggingFacilities() {
        // Load the logging facilities dynamically
        for (String facility : facilities.keySet()) {
            loadLoggingFacility(facility);
        }
    }

    public void unloadLoggingFacilities() {
        // Unload the logging facilities dynamically
        for (String facility : facilities.keySet()) {
            unloadLoggingFacility(facility);
        }
    }

    private void loadLoggingFacility(String facility) {
        // Load the logging facility dynamically
        try {
            Class<?> clazz = Class.forName("com.example." + facility);
            Object instance = clazz.newInstance();
            facilities.put(facility, (LoggingFacility) instance);
        } catch (ClassNotFoundException | InstantiationException | IllegalAccessException e) {
            // Handle the exception
        }
    }

    private void unloadLoggingFacility(String facility) {
        // Unload the logging facility dynamically
        try {
            facilities.remove(facility);
        } catch (IllegalArgumentException e) {
            // Handle the exception
        }
    }
}
```
