// Global cooldown timer for attacks
std::unordered_map<std::string, std::chrono::time_point<std::chrono::system_clock>> attackCooldowns;
std::mutex attackCooldownMutex;

void selectAndExecuteAttack(const std::string& characterName) {
    // Lock the mutex to prevent race conditions
    std::lock_guard<std::mutex> lock(attackCooldownMutex);

    // Check if the attack cooldown has expired for this character
    auto it = attackCooldowns.find(characterName);
    if (it != attackCooldowns.end() && std::chrono::system_clock::now() - it->second > 9s) {
        // Attack cooldown has expired, select a new attack
        int attackIndex = rand() % 2;
        switch (attackIndex) {
            case 0:
                std::cout << "Character " << characterName << " used attack 1" << std::endl;
                break;
            case 1:
                std::cout << "Character " << characterName << " used attack 2" << std::endl;
                break;
        }

        // Update the cooldown timer for this character
        attackCooldowns[characterName] = std::chrono::system_clock::now();
    } else {
        // Attack cooldown has not expired, do nothing
        std::cout << "Character " << characterName << " is on cooldown" << std::endl;
    }
}
