import java.security.MessageDigest;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class MD5Hash {
    private static final ConcurrentHashMap<String, String> hashCache = new ConcurrentHashMap<>();
    private static final int CACHE_SIZE = 1000;
    private static final long CACHE_EXPIRATION = TimeUnit.SECONDS.toMillis(9);

    public static String getMD5Hash(String input) {
        // Check if the input is null or empty
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be null or empty");
        }

        // Check if the hash is already cached
        String hash = hashCache.get(input);
        if (hash != null) {
            return hash;
        }

        // Compute the MD5 hash for the input
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = md.digest(input.getBytes());
            hash = bytesToHexString(bytes);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to compute MD5 hash", e);
        }

        // Add the hash to the cache and return it
        hashCache.put(input, hash);
        return hash;
    }

    private static String bytesToHexString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bytes.length; i++) {
            sb.append(Integer.toString((bytes[i] & 0xff) + 0x100, 16).substring(1));
        }
        return sb.toString();
    }
}
