import hashlib
import os
import threading
import time
from concurrent.futures import ThreadPoolExecutor
from typing import List, Optional

class FileHasher:
    def __init__(self, chunk_size: int = 1024 * 1024):
        self.chunk_size = chunk_size
        self.executor = ThreadPoolExecutor(max_workers=None)

    def hash_file(self, filepath: str, algorithm: str = "md5") -> Optional[str]:
        if not os.path.exists(filepath):
            return None

        with open(filepath, "rb") as f:
            hasher = getattr(hashlib, algorithm)()
            while True:
                chunk = f.read(self.chunk_size)
                if not chunk:
                    break
                hasher.update(chunk)

            return hasher.hexdigest()

    def hash_files(self, filepaths: List[str], algorithms: List[str] = ["md5", "sha256"]) -> dict:
        results = {}

        for filepath in filepaths:
            if not os.path.exists(filepath):
                continue

            for algorithm in algorithms:
                result = self.hash_file(filepath, algorithm)
                if result is None:
                    continue
                results[filepath] = results.get(filepath, {})
                results[filepath][algorithm] = result

        return results

    def process_files(self, filepaths: List[str], algorithms: List[str] = ["md5", "sha256"], max_threads: int = 10) -> dict:
        with self.executor as executor:
            futures = [executor.submit(self.hash_file, filepath, algorithm) for filepath in filepaths for algorithm in algorithms]
            results = {}

            for future in futures:
                result = future.result()
                if result is None:
                    continue
                filepath, algorithm, hash = result
                results[filepath] = results.get(filepath, {})
                results[filepath][algorithm] = hash

            return results

    def upload_files(self, filepaths: List[str], cloud_storage_service: str = "aws", credentials: dict = None) -> bool:
        if not os.path.exists(filepaths):
            return False

        try:
            import boto3

            s3 = boto3.client("s3")
            for filepath in filepaths:
                with open(filepath, "rb") as f:
                    s3.put_object(Body=f, Bucket=cloud_storage_service)
        except ImportError:
            return False

        return True

    def monitor_system_performance(self, filepaths: List[str], algorithms: List[str] = ["md5", "sha256"], max_threads: int = 10) -> dict:
        with self.executor as executor:
            futures = [executor.submit(self.hash_file, filepath, algorithm) for filepath in filepaths for algorithm in algorithms]
            results = {}

            for future in futures:
                result = future.result()
                if result is None:
