                filepath, algorithm, hash = result
                results[filepath] = results.get(filepath, {})
                results[filepath][algorithm] = hash

            return results

    def monitor_resource_usage(self, filepaths: List[str], algorithms: List[str] = ["md5", "sha256"], max_threads: int = 10) -> dict:
        with self.executor as executor:
            futures = [executor.submit(self.hash_file, filepath, algorithm) for filepath in filepaths for algorithm in algorithms]
            results = {}

            for future in futures:
                result = future.result()
                if result is None:
