#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int key;
    char* desc;
} Record;

// Define the array of records
Record* records = NULL;
size_t num_records = 0;

// Define the arrays for offset values, keys, and record structures
long* offsets = NULL;
int* keys = NULL;
Record** records_array = NULL;

// Define the mutex for thread-safe access to the arrays
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate memory for and initialize the arrays
void init_arrays(size_t num_records) {
    // Allocate memory for the offset values array
    offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offset values");
        exit(1);
    }

    // Initialize the offset values array
    memset(offsets, 0, num_records * sizeof(long));

    // Allocate memory for the key array
    keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for key values");
        exit(1);
    }

    // Initialize the key array
    memset(keys, 0, num_records * sizeof(int));

    // Allocate memory for the record structures array
    records_array = (Record**)malloc(num_records * sizeof(Record*));
    if (!records_array) {
        perror("Failed to allocate memory for record structures");
        exit(1);
    }

    // Initialize the record structures array
    memset(records_array, 0, num_records * sizeof(Record*));
}

// Function to insert a new record into the arrays
void insert_record(int key, char* desc) {
    pthread_mutex_lock(&mutex);

    // Check if the array needs to be resized
    if (num_records == 0 || num_records == records_array->size) {
        size_t new_size = num_records * 2;
        long* new_offsets = realloc(offsets, new_size);
        int* new_keys = realloc(keys, new_size);
        Record** new_records_array = realloc(records_array, new_size);
        if (!new_offsets || !new_keys || !new_records_array) {
            perror("Failed to resize arrays");
            exit(1);
        }
        offsets = new_offsets;
        keys = new_keys;
        records_array = new_records_array;
    }

    // Insert the record into the arrays
    offsets[num_records] = 0;
    keys[num_records] = key;
    records_array[num_records] = (Record*)malloc(sizeof(Record));
    if (!records_array[num_records]) {
        perror("Failed to allocate memory for record");
        exit(1);
    }
    records_array[num_records]->key = key;
    records_array[num_records]->desc = desc;

    num_records++;

    pthread_mutex_unlock(&mutex);
}

// Function to update a record in the arrays
void update_record(int key, char* desc) {
    pthread_mutex_lock(&mutex);

    // Find the index of the record to be updated
    size_t i;
    for (i = 0; i < num_records; i++) {
        if (keys[i] == key) {
            break;
        }
    }

    // Update the record in the arrays
    offsets[i] = 0;
    keys[i] = key;
    records_array[i]->desc = desc;

    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a record from the arrays
Record* get_record(int key) {
    pthread_mutex_lock(&mutex);

    // Find the index of the record to be retrieved
    size_t i;
    for (i = 0; i < num_records; i++) {
        if (keys[i] == key) {
            break;
        }
    }

    // Return the record from the arrays
    Record* record = records_array[i];
    pthread_mutex_unlock(&mutex);
    return record;
}

// Function to remove a record from the arrays
void remove_record(int key) {
    pthread_mutex_lock(&mutex);

    // Find the index of the record to be removed
    size_t i;
    for (i = 0; i < num_records; i++) {
        if (keys[i] == key) {
            break;
        }
    }

    // Remove the record from the arrays
    offsets[i] = 0;
    keys[i] = 0;
    records_array[i]->desc = NULL;

    num_records--;

    pthread_mutex_unlock(&mutex);
}

// Function to destroy the arrays and free memory
void destroy_arrays() {
    pthread_mutex_lock(&mutex);

    // Free the memory allocated for the offset values array
    free(offsets);

    // Free the memory allocated for the key array
    free(keys);

    // Free the memory allocated for the record structures array
    for (size_t i = 0; i < num_records; i++) {
        free(records_array[i]);
    }
    free(records_array);

    pthread_mutex_unlock(&mutex);
}
