import hashlib
import os
import sys
from concurrent.futures import ThreadPoolExecutor

# Define the chunk size for processing large files
CHUNK_SIZE = 1024 * 1024

# Define the path to the file to be processed
FILE_PATH = "large_file.txt"

# Define the hash algorithm to use (MD5 or SHA-256)
HASH_ALGORITHM = "md5"

# Define the number of threads for concurrent processing
NUM_THREADS = 4

# Function to calculate the MD5 or SHA-256 hash of a file
def calculate_hash(file_path):
    # Open the file and read it in chunks
    with open(file_path, "rb") as f:
        chunk = f.read(CHUNK_SIZE)
        while chunk:
            # Calculate the hash of the current chunk
            if HASH_ALGORITHM == "md5":
                hash_value = hashlib.md5(chunk).hexdigest()
            else:
                hash_value = hashlib.sha256(chunk).hexdigest()

            # Print the hash value to stdout
            print(hash_value)

            # Read the next chunk
            chunk = f.read(CHUNK_SIZE)

# Function to process a file and calculate its MD5 or SHA-256 hash
def process_file(file_path):
    # Calculate the hash of the file
    calculate_hash(file_path)

    # Print a message indicating that the file has been processed
    print("File processed:", file_path)

# Function to trigger processing of a file and retrieve its results asynchronously
def process_file_async(file_path):
    # Create a thread pool with the specified number of threads
    with ThreadPoolExecutor(max_workers=NUM_THREADS) as executor:
        # Submit the task to the thread pool
