#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Define the data structure for storing records
typedef struct {
    long offset;
    int key;
    char *descriptive_string;
    bool active;
} record_t;

// Define the data structure for managing the records
typedef struct {
    record_t **records;
    size_t num_records;
    pthread_mutex_t mutex;
} record_manager_t;

// Function to insert a new record with a given key, if it does not already exist
void insert_record(record_manager_t *manager, int key, long offset) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&manager->mutex);

    // Check if the record already exists
    for (size_t i = 0; i < manager->num_records; i++) {
        if (manager->records[i]->key == key) {
            // Update the status flag to indicate the record's current operational state
            manager->records[i]->active = true;
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
    }

    // Allocate memory for the new record
    record_t *new_record = malloc(sizeof(record_t));
    if (new_record == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for new record\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    // Initialize the new record
    new_record->offset = offset;
    new_record->key = key;
    new_record->descriptive_string = NULL;
    new_record->active = true;

    // Add the new record to the list of records
    manager->records = realloc(manager->records, (manager->num_records + 1) * sizeof(record_t*));
    if (manager->records == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for new record\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    manager->records[manager->num_records++] = new_record;

    // Unlock the mutex
    pthread_mutex_unlock(&manager->mutex);
}

// Function to update the value of an existing record based on its key, taking into account the status flag
void update_record(record_manager_t *manager, int key, long offset) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&manager->mutex);

    // Find the record with the given key
    for (size_t i = 0; i < manager->num_records; i++) {
        if (manager->records[i]->key == key) {
            // Update the offset value of the record
            manager->records[i]->offset = offset;
            break;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&manager->mutex);
}

// Function to retrieve the value of a record by its key, considering the status flag to ensure that inactive records are not accessed
void *get_record(record_manager_t *manager, int key) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&manager->mutex);

    // Find the record with the given key
    for (size_t i = 0; i < manager->num_records; i++) {
        if (manager->records[i]->key == key) {
            // Return a copy of the record's value, considering the status flag
            if (manager->records[i]->active) {
                return malloc(sizeof(record_t));
            } else {
                return NULL;
            }
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&manager->mutex);

    // Return NULL if no record was found with the given key
    return NULL;
}

// Function to remove a record by its key, ensuring that the status flag is updated accordingly and that any references to the removed record are properly handled
void remove_record(record_manager_t *manager, int key) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&manager->mutex);

    // Find the record with the given key
    for (size_t i = 0; i < manager->num_records; i++) {
        if (manager->records[i]->key == key) {
            // Update the status flag of the record to indicate that it is no longer active
            manager->records[i]->active = false;

            // Remove the record from the list of records
            for (size_t j = i + 1; j < manager->num_records; j++) {
                manager->records[j - 1] = manager->records[j];
            }
            manager->num_records--;

            // Deallocate the memory for the removed record
            free(manager->records[i]);
            break;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&manager->mutex);
}

// Function to list all active records, including their keys, values, and status flags
void list_records(record_manager_t *manager) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&manager->mutex);

    // Iterate over the records and print their information
    for (size_t i = 0; i < manager->num_records; i++) {
        if (manager->records[i]->active) {
            printf("Record %d: key=%d, offset=%ld, active\n", i, manager->records[i]->key, manager->records[i]->offset);
        } else {
            printf("Record %d: key=%d, offset=%ld, inactive\n", i, manager->records[i]->key, manager->records[i]->offset);
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&manager->mutex);
}
```
