```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Define the structure for a UE session
typedef struct {
    UeIdentity_t identity;
    LTE_RadioResourceConfig_t *configs;
} LTE_UESession_t;

// Define the array of UE sessions
LTE_UESession_t *ue_sessions = NULL;
size_t num_sessions = 0;

// Define the mutex for thread safety
pthread_mutex_t ue_session_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new UE session
int add_ue_session(UeIdentity_t identity, LTE_RadioResourceConfig_t *configs) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ue_session_lock);

    // Check if the IP address and port number are valid
    if (!validate_ip_address(identity.ip_addr) || !validate_port_number(identity.port)) {
        printf("Invalid IP address or port number\n");
        pthread_mutex_unlock(&ue_session_lock);
        return -1;
    }

    // Check if the configuration parameters are valid
    if (!validate_configs(configs)) {
        printf("Invalid configuration parameters\n");
        pthread_mutex_unlock(&ue_session_lock);
        return -1;
    }

    // Allocate memory for the new UE session
    LTE_UESession_t *new_session = malloc(sizeof(LTE_UESession_t));
    if (new_session == NULL) {
        printf("Failed to allocate memory for new UE session\n");
        pthread_mutex_unlock(&ue_session_lock);
        return -1;
    }

    // Initialize the new UE session
    new_session->identity = identity;
    new_session->configs = configs;

    // Add the new UE session to the array of sessions
    ue_sessions[num_sessions++] = new_session;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&ue_session_lock);
    return 0;
}

// Function to remove an existing UE session
int remove_ue_session(UeIdentity_t identity) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ue_session_lock);

    // Find the index of the UE session to be removed
    size_t i;
    for (i = 0; i < num_sessions; i++) {
        if (ue_sessions[i]->identity.ip_addr == identity.ip_addr && ue_sessions[i]->identity.port == identity.port) {
            break;
        }
    }

    // Check if the UE session was found
    if (i == num_sessions) {
        printf("UE session not found\n");
        pthread_mutex_unlock(&ue_session_lock);
        return -1;
    }

    // Remove the UE session from the array of sessions
    LTE_UESession_t *removed_session = ue_sessions[i];
    memmove(ue_sessions + i, ue_sessions + i + 1, (num_sessions - i) * sizeof(LTE_UESession_t));
    num_sessions--;

    // Free the memory allocated for the removed UE session
    free(removed_session);

    // Unlock the mutex and return success
    pthread_mutex_unlock(&ue_session_lock);
    return 0;
}

// Function to update an existing UE session
int update_ue_session(UeIdentity_t identity, LTE_RadioResourceConfig_t *configs) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ue_session_lock);

    // Find the index of the UE session to be updated
    size_t i;
    for (i = 0; i < num_sessions; i++) {
        if (ue_sessions[i]->identity.ip_addr == identity.ip_addr && ue_sessions[i]->identity.port == identity.port) {
            break;
        }
    }

    // Check if the UE session was found
    if (i == num_sessions) {
        printf("UE session not found\n");
        pthread_mutex_unlock(&ue_session_lock);
        return -1;
    }

    // Update the configuration parameters of the UE session
    ue_sessions[i]->configs = configs;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&ue_session_lock);
    return 0;
}

// Function to validate the configuration parameters of a UE session
int validate_configs(LTE_RadioResourceConfig_t *configs) {
    // Check if the configuration parameters are valid
    if (!validate_ip_address(configs->ip_addr) || !validate_port_number(configs->port)) {
        return 0;
    }

    // Check if the configuration parameters are consistent with each other
    if (configs->ip_addr != configs->ip_addr_2 || configs->port != configs->port_2) {
        return 0;
    }

    // Return success if the configuration parameters are valid and consistent
    return 1;
}

// Function to validate an IP address
int validate_ip_address(char *ip_addr) {
    // Check if the IP address is a valid IPv4 or IPv6 address
    if (inet_pton(AF_INET, ip_addr, NULL) == 1 || inet_pton(AF_INET6, ip_addr, NULL) == 1) {
        return 1;
    }

    // Return failure if the IP address is not a valid IPv4 or IPv6 address
    return 0;
}

// Function to validate a port number
int validate_port_number(uint16_t port) {
    // Check if the port number is within the valid range
    if (port >= 1 && port <= 65535) {
        return 1;
    }

    // Return failure if the port number is not within the valid range
    return 0;
}
