#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Memory pool allocator for dynamic memory allocation
struct mempool {
    void* data;
    size_t size;
};

// Data structure to maintain a list of active elements and their HTML content
struct element {
    char* id;
    char* html;
    bool active;
};

// Function to generate a random number within a given range
int rand_range(int min, int max) {
    return min + (rand() % (max - min));
}

// Function to acquire a lock on the data structure
void lock(pthread_mutex_t* mutex) {
    pthread_mutex_lock(mutex);
}

// Function to release a lock on the data structure
void unlock(pthread_mutex_t* mutex) {
    pthread_mutex_unlock(mutex);
}

// Function to insert or update an element's HTML content
void handleHTTPPostRequest(int pageSectionID, int elementID, char* htmlContent, bool statusFlag) {
    // Acquire a lock on the data structure
    lock(&data_structure_lock);

    // Find the element in the list of active elements
    struct element* element = findElement(pageSectionID, elementID);

    // If the element is not found, create a new one
    if (element == NULL) {
        element = malloc(sizeof(struct element));
        element->id = malloc(strlen(elementID) + 1);
        strcpy(element->id, elementID);
        element->html = malloc(strlen(htmlContent) + 1);
        strcpy(element->html, htmlContent);
        element->active = true;
    }

    // Update the element's HTML content if the status flag is set
    if (statusFlag) {
        free(element->html);
        element->html = malloc(strlen(htmlContent) + 1);
        strcpy(element->html, htmlContent);
    }

    // Release the lock on the data structure
    unlock(&data_structure_lock);
}

// Function to retrieve an element's HTML content by its ID
char* getElementHTML(int pageSectionID, int elementID) {
    // Acquire a lock on the data structure
    lock(&data_structure_lock);

    // Find the element in the list of active elements
    struct element* element = findElement(pageSectionID, elementID);

    // If the element is not found, return NULL
    if (element == NULL) {
        unlock(&data_structure_lock);
        return NULL;
    }

    // Return a copy of the element's HTML content
    char* html = malloc(strlen(element->html) + 1);
    strcpy(html, element->html);

    // Release the lock on the data structure
    unlock(&data_structure_lock);

    return html;
}

// Function to list all active elements and their HTML content
void listActiveElements() {
    // Acquire a lock on the data structure
    lock(&data_structure_lock);

    // Iterate over the list of active elements
    for (struct element* element = head; element != NULL; element = element->next) {
        if (element->active) {
            printf("%s: %s\n", element->id, element->html);
        }
    }

    // Release the lock on the data structure
    unlock(&data_structure_lock);
}

// Function to find an element in the list of active elements by its ID
struct element* findElement(int pageSectionID, int elementID) {
    // Acquire a lock on the data structure
    lock(&data_structure_lock);

    // Iterate over the list of active elements
    for (struct element* element = head; element != NULL; element = element->next) {
        if (element->active && strcmp(element->id, elementID) == 0) {
            break;
        }
    }

    // Release the lock on the data structure
    unlock(&data_structure_lock);

    return element;
}
