void* handle_rate_limiting() {
    while (1) {
        // Wait for a semaphore permit
        if (sem_wait(&sem) == -1) {
            perror("sem_wait");
            return NULL;
        }

        // Get the current time
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

