// Define a structure to represent a file chunk
typedef struct {
    char *data;
    size_t size;
} FileChunk;

// Define a function to read a file into chunks of a specified size
void readFileIntoChunks(const char *filePath, size_t chunkSize, void (*processChunk)(FileChunk *chunk)) {
    // Open the file for reading
    int fd = open(filePath, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
        return;
    }

    // Get the size of the file
    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("Failed to get file size");
        close(fd);
        return;
    }

    // Read the file in chunks
    size_t remaining = st.st_size;
    while (remaining > 0) {
        // Calculate the size of the current chunk
        size_t chunkSizeToRead = remaining < chunkSize ? remaining : chunkSize;

        // Allocate memory for the chunk
        FileChunk *chunk = malloc(sizeof(FileChunk));
        if (chunk == NULL) {
            perror("Failed to allocate memory for file chunk");
            close(fd);
            return;
        }

        // Read the chunk from the file
        ssize_t bytesRead = read(fd, chunk->data, chunkSizeToRead);
        if (bytesRead == -1) {
            perror("Failed to read file");
            free(chunk);
            close(fd);
            return;
        }

        // Set the size of the chunk
        chunk->size = bytesRead;

        // Process the chunk
        processChunk(chunk);

        // Free the chunk
        free(chunk);

        // Update the remaining file size
        remaining -= chunkSizeToRead;
    }

    // Close the file
    close(fd);
}

// Define a function to handle directory inputs recursively
void processDirectoryInputs(const char *directoryPath, void (*processFile)(const char *filePath)) {
    // Open the directory for reading
    DIR *dir = opendir(directoryPath);
    if (dir == NULL) {
        perror("Failed to open directory");
        return;
    }

    // Read the directory entries
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        // Get the full path of the entry
        char *filePath = malloc(PATH_MAX);
        if (filePath == NULL) {
            perror("Failed to allocate memory for file path");
            closedir(dir);
            return;
        }
        snprintf(filePath, PATH_MAX, "%s/%s", directoryPath, entry->d_name);

        // Check if the entry is a file or directory
        struct stat st;
        if (stat(filePath, &st) == -1) {
            perror("Failed to get file status");
            free(filePath);
            closedir(dir);
            return;
        }

        // Process the entry
        if (S_ISREG(st.st_mode)) {
            processFile(filePath);
        } else if (S_ISDIR(st.st_mode)) {
            processDirectoryInputs(filePath, processFile);
        }

        // Free the file path
        free(filePath);
    }

    // Close the directory
    closedir(dir);
}

// Define a function to handle symbolic links
void handleSymbolicLinks(const char *filePath, void (*processFile)(const char *filePath)) {
    // Check if the file exists
    struct stat st;
    if (lstat(filePath, &st) == -1) {
        perror("Failed to get file status");
        return;
    }

    // If the file is a symbolic link, follow it and process the target file
    if (S_ISLNK(st.st_mode)) {
        char *targetFilePath = malloc(PATH_MAX);
        if (targetFilePath == NULL) {
            perror("Failed to allocate memory for target file path");
            return;
        }
        ssize_t bytesRead = readlink(filePath, targetFilePath, PATH_MAX - 1);
        if (bytesRead == -1) {
            perror("Failed to read symbolic link");
            free(targetFilePath);
            return;
