// Define a function to handle very large files that may exceed system memory limits
void handleLargeFiles(const char *filePath, void (*processFile)(const char *filePath)) {
    // Open the file for reading
    int fd = open(filePath, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
