    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("Failed to get file size");
        close(fd);
        return;
    }

    // Check if the file is too large for memory mapping
    if (st.st_size > 50 * 1024 * 1024) {
        // Read the file in chunks and process each chunk separately
        size_t remaining = st.st_size;
        while (remaining > 0) {
            // Calculate the size of the current chunk
            size_t chunkSizeToRead = remaining < 50 * 1024 * 1024 ? remaining : 50 * 1024 * 1024;

            // Map the file into memory
            void *map = mmap(NULL, chunkSizeToRead, PROT_READ, MAP_PRIVATE, fd, 0);
            if (map == MAP_FAILED) {
