            // Unmap the file from memory
            munmap(map, chunkSizeToRead);

            // Update the remaining file size
            remaining -= chunkSizeToRead;
        }
    } else {
        // Read the entire file into memory and process it at once
        char *buffer = malloc(st.st_size + 1);
        if (buffer == NULL) {
