using System;
using System.Data;
using System.Threading;

public class DataGenerator
{
    private readonly Random _random;
    private int _seed;
    private int _precision;
    private int _length;
    private bool _isInclusive;
    private bool _isExclusive;
    private double _minValue;
    private double _maxValue;
    private string[] _stringValues;

    public DataGenerator(int seed = 0)
    {
        _random = new Random(seed);
        _seed = seed;
        _precision = 1;
        _length = 10;
        _isInclusive = true;
        _isExclusive = false;
        _minValue = double.MinValue;
        _maxValue = double.MaxValue;
    }

    public void SetSeed(int seed)
    {
        _seed = seed;
        _random = new Random(seed);
    }

    public void SetPrecision(int precision)
    {
        _precision = precision;
    }

    public void SetLength(int length)
    {
        _length = length;
    }

    public void SetIsInclusive(bool isInclusive)
    {
        _isInclusive = isInclusive;
    }

    public void SetIsExclusive(bool isExclusive)
    {
        _isExclusive = isExclusive;
    }

    public void SetMinValue(double minValue)
    {
        _minValue = minValue;
    }

    public void SetMaxValue(double maxValue)
    {
        _maxValue = maxValue;
    }

    public void SetStringValues(string[] stringValues)
    {
        _stringValues = stringValues;
    }

    public int GenerateInt()
    {
        return GenerateRandomNumber();
    }

    public float GenerateFloat()
    {
        return (float)GenerateRandomNumber();
    }

    public double GenerateDouble()
    {
        return GenerateRandomNumber();
    }

    public string GenerateString(int length = 10)
    {
        if (_stringValues == null || _stringValues.Length == 0)
        {
            throw new ArgumentException("No string values provided");
        }

        return _stringValues[_random.Next(_stringValues.Length)];
    }

    public void Reset()
    {
        _random = new Random(_seed);
    }

    private double GenerateRandomNumber()
    {
        if (_isInclusive && _isExclusive)
        {
            throw new ArgumentException("Cannot set both inclusive and exclusive");
        }

        if (_minValue > _maxValue)
        {
            throw new ArgumentException("Min value cannot be greater than max value");
        }

        double randomNumber = 0;

        if (_isInclusive)
        {
            randomNumber = _random.Next((int)_minValue, (int)_maxValue + 1);
        }
        else if (_isExclusive)
        {
            randomNumber = _random.Next((int)_minValue, (int)_maxValue);
        }
        else
        {
            randomNumber = _random.NextDouble();
        }

        return randomNumber;
    }

    public override string ToString()
    {
        return $"Seed: {_seed}, Precision: {_precision}, Length: {_length}, IsInclusive: {_isInclusive}, IsExclusive: {_isExclusive}, MinValue: {_minValue}, MaxValue: {_maxValue}, StringValues: {string.Join(", ", _stringValues)}";
    }
}
