// Define a function to handle file uploads
void* handle_upload(void* args) {
    // Cast the arguments to the correct types
    char* file_name = (char*)args;
    size_t file_size = strlen(file_name);

    // Open the file for reading
    int fd = open(file_name, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
        return NULL;
    }

    // Create a semaphore to track upload progress
    sem_t* sem = sem_open("/upload_sem", O_CREAT, 0644, 0);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        return NULL;
    }

    // Initialize the upload metadata struct
    upload_metadata_t* metadata = malloc(sizeof(upload_metadata_t));
    metadata->file_name = file_name;
    metadata->file_size = file_size;
    metadata->offset = 0;

    // Cache the metadata in a shared memory segment
    int shmid = shmget(IPC_PRIVATE, sizeof(upload_metadata_t), IPC_CREAT | 0644);
    if (shmid == -1) {
        perror("Failed to create shared memory segment");
        return NULL;
    }
    void* shmaddr = shmat(shmid, NULL, 0);
    memcpy(shmaddr, metadata, sizeof(upload_metadata_t));

    // Loop until the upload is complete or an error occurs
    while (1) {
        // Check if the upload has been canceled
        if (sem_trywait(sem) == -1 && errno == EAGAIN) {
            break;
        }

        // Read from the file and write to the cloud storage service
        char buffer[4096];
        ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
        if (bytes_read == -1) {
            perror("Failed to read from file");
            break;
        } else if (bytes_read == 0) {
            // Upload is complete
            break;
        }

        // Update the offset in the shared memory segment
        metadata->offset += bytes_read;
        memcpy(shmaddr, metadata, sizeof(upload_metadata_t));

        // Log progress to the error log
        char message[1024];
        snprintf(message, 1024, "Uploaded %d%% of file %s", (int)(metadata->offset * 100 / metadata->file_size), metadata->file_name);
        va_list args;
        va_start(args, message);
        vfprintf(stderr, message, args);
        va_end(args);
    }

    // Clean up resources
    close(fd);
    shmctl(shmid, IPC_RMID, NULL);
    sem_close(sem);
    free(metadata);

    return NULL;
}

