        return NULL;
    }
    void* shmaddr = shmat(shmid, NULL, 0);
    memcpy(shmaddr, metadata, sizeof(upload_metadata_t));

    // Loop until all files have been uploaded or an error occurs
    while (1) {
        // Check if any of the uploads have been canceled
        for (size_t i = 0; i < num_files; i++) {
            if (sem_trywait(sem) == -1 && errno == EAGAIN) {
                break;
            }
        }

        // If all uploads have been canceled, exit the loop
