                close(fd);
                continue;
            } else if (bytes_read == 0) {
                // Upload is complete
                close(fd);
                break;
            }

            // Update the offset in the shared memory segment
            metadata->offset += bytes_read;
            memcpy(shmaddr, metadata, sizeof(upload_metadata_t));

            // Log progress to the error log
            char message[1024];
            snprintf(message, 1024, "Uploaded %d%% of file %s", (int)(metadata->offset * 100 / metadata->file_size), metadata->file_name);
            va_list args;
            va_start(args, message);
            vfprintf(stderr, message, args);
            va_end(args);
        }
    }

    // Clean up resources
    for (size_t i = 0; i < num_files; i++) {
        close(fd);
    }
    shmctl(shmid, IPC_RMID, NULL);
    sem_close(sem);
    free(metadata);

    return NULL;
}

