    ServiceConfig_t *services;
} NetworkNode_t;

// Define the function to manage the array of NetworkNodes
void manageNetworkNodes(NetworkNode_t **nodes, int num_nodes) {
    // Initialize the array of nodes if it is NULL
    if (*nodes == NULL) {
        *nodes = (NetworkNode_t *)malloc(sizeof(NetworkNode_t) * num_nodes);
        memset(*nodes, 0, sizeof(NetworkNode_t) * num_nodes);
    }

    // Add a new node to the array
    void addNode(NetworkNode_t *node) {
        int i;
        for (i = 0; i < num_nodes; i++) {
            if ((*nodes)[i].identity.ip == node->identity.ip && (*nodes)[i].identity.port == node->identity.port) {
                // Node already exists, update the services list
                free((*nodes)[i].services);
                (*nodes)[i].services = (ServiceConfig_t *)malloc(sizeof(ServiceConfig_t) * node->num_services);
                memcpy((*nodes)[i].services, node->services, sizeof(ServiceConfig_t) * node->num_services);
            } else {
                // Node does not exist, add it to the array
                (*nodes)[i] = *node;
            }
        }
    }

    // Remove a node from the array
    void removeNode(NetworkNode_t *node) {
        int i;
        for (i = 0; i < num_nodes; i++) {
            if ((*nodes)[i].identity.ip == node->identity.ip && (*nodes)[i].identity.port == node->identity.port) {
                // Node found, remove it from the array
                free((*nodes)[i].services);
                memmove(&(*nodes)[i], &(*nodes)[i + 1], (num_nodes - i - 1) * sizeof(NetworkNode_t));
                num_nodes--;
            }
        }
    }

