                // Node found, update the services list
                free((*nodes)[i].services);
                (*nodes)[i].services = (ServiceConfig_t *)malloc(sizeof(ServiceConfig_t) * node->num_services);
                memcpy((*nodes)[i].services, node->services, sizeof(ServiceConfig_t) * node->num_services);
            }
        }
    }

    // Validate the configuration parameters to prevent invalid settings and optimize memory usage by avoiding unnecessary allocations
    void validateConfiguration() {
        int i;
        for (i = 0; i < num_nodes; i++) {
            if ((*nodes)[i].identity.ip == NULL || (*nodes)[i].identity.port == NULL) {
                // Invalid IP address or port, remove the node from the array
                removeNode(&(*nodes)[i]);
            } else {
                // Valid IP address and port, validate the services list
                int j;
                for (j = 0; j < (*nodes)[i].num_services; j++) {
                    if ((*nodes)[i].services[j].name == NULL || (*nodes)[i].services[j].port == NULL) {
                        // Invalid service name or port, remove the node from the array
                        removeNode(&(*nodes)[i]);
                        break;
                    }
                }
            }
        }
    }

    // Implement a failover mechanism to ensure uninterrupted service if a primary node fails
    void failover() {
        int i;
        for (i = 0; i < num_nodes; i++) {
            if ((*nodes)[i].identity.ip == NULL || (*nodes)[i].identity.port == NULL) {
                // Invalid IP address or port, remove the node from the array
                removeNode(&(*nodes)[i]);
            } else {
                // Valid IP address and port, check if the node is a primary node
                if ((*nodes)[i].primary) {
                    // Primary node found, failover to another node in the array
                    int j;
                    for (j = 0; j < num_nodes; j++) {
                        if (j != i && (*nodes)[j].identity.ip != NULL && (*nodes)[j].identity.port != NULL) {
                            // Another node found, failover to it
                            (*nodes)[i].primary = 0;
                            (*nodes)[j].primary = 1;
                            break;
                        }
                    }
                }
            }
        }
    }

    // Design a strategy to handle dynamic network changes efficiently
    void handleDynamicNetworkChanges() {
        int i;
        for (i = 0; i < num_nodes; i++) {
            if ((*nodes)[i].identity.ip == NULL || (*nodes)[i].identity.port == NULL) {
                // Invalid IP address or port, remove the node from the array
                removeNode(&(*nodes)[i]);
            } else {
                // Valid IP address and port, check if the node is a primary node
                if ((*nodes)[i].primary) {
                    // Primary node found, handle dynamic network changes by updating the services list
                    int j;
                    for (j = 0; j < (*nodes)[i].num_services; j++) {
