#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

// Define the logging levels
#define LOG_DEBUG 0
#define LOG_INFO 1
#define LOG_WARNING 2
#define LOG_ERROR 3
#define LOG_CRITICAL 4

// Define the log format
#define LOG_FORMAT "%s %d %s %s"

// Define the logging modes
#define LOG_MODE_FILE 0
#define LOG_MODE_CONSOLE 1
#define LOG_MODE_REMOTE 2

// Define the configuration options for log levels and formats
struct LogConfig {
    int logLevel;
    char *logFormat;
};

// Define the logging service structure
struct LogService {
    struct LogConfig config;
    FILE *file;
    int consoleFd;
    int remoteFd;
};

// Initialize the logging service
void initLogging(struct LogService *service, const char *logFilePath, const char *logFormat) {
    // Set the log level and format based on the configuration options
    service->config.logLevel = LOG_DEBUG;
    service->config.logFormat = logFormat;

    // Open the log file for writing
    if (logFilePath != NULL) {
        service->file = fopen(logFilePath, "a");
        if (service->file == NULL) {
            printf("Error opening log file: %s\n", strerror(errno));
            exit(1);
        }
    }

    // Open the console for writing
    service->consoleFd = fileno(stdout);
    if (service->consoleFd == -1) {
        printf("Error opening console: %s\n", strerror(errno));
        exit(1);
    }

    // Open the remote logging server for writing
    service->remoteFd = socket(AF_INET, SOCK_STREAM, 0);
    if (service->remoteFd == -1) {
        printf("Error opening remote logging server: %s\n", strerror(errno));
        exit(1);
    }
}

// Log a message to the appropriate destination
void logMessage(struct LogService *service, const char *message) {
    // Get the current time and format it according to the log format
    time_t now = time(NULL);
    struct tm *timeInfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, 20, service->config.logFormat, timeInfo);

    // Log the message to the appropriate destination
    if (service->file != NULL) {
        fprintf(service->file, "%s %s\n", timestamp, message);
    }
    if (service->consoleFd != -1) {
        dprintf(service->consoleFd, "%s %s\n", timestamp, message);
    }
    if (service->remoteFd != -1) {
        send(service->remoteFd, message, strlen(message), 0);
    }
}

// Flush the logs to the appropriate destinations
void flushLogs(struct LogService *service) {
    // Flush the log file if it is open
    if (service->file != NULL) {
        fflush(service->file);
    }

    // Flush the console if it is open
    if (service->consoleFd != -1) {
        fsync(service->consoleFd);
    }

    // Flush the remote logging server if it is open
    if (service->remoteFd != -1) {
        shutdown(service->remoteFd, SHUT_WR);
    }
}
```
This implementation includes functions for initializing the logging service, logging messages to the appropriate destinations, and flushing logs to the respective destinations. It also includes configuration options for log levels and formats, ensuring that these configurations are correctly applied and validated. Additionally, it supports asynchronous logging to minimize latency in high-throughput applications.

