#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>

// Define log levels and formats
enum LogLevel { DEBUG, INFO, WARNING, ERROR, CRITICAL };
const char* log_levels[] = { "DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL" };
const char* log_formats[] = { "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M:%S.%f", "%Y-%m-%d %H:%M:%S.%f %z", "%Y-%m-%d %H:%M:%S.%f %z" };

// Define log file and console output options
const char* log_file = "log.txt";
bool log_to_console = true;

// Define remote server logging options
const char* remote_server_url = "https://example.com/logs";
int remote_server_port = 443;
bool remote_server_enabled = false;

// Define custom log levels and formats
const char* custom_log_levels[] = { "DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL" };
const char* custom_log_formats[] = { "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M:%S.%f", "%Y-%m-%d %H:%M:%S.%f %z", "%Y-%m-%d %H:%M:%S.%f %z" };

// Define log buffer size and flush interval
const int LOG_BUFFER_SIZE = 1024;
const int FLUSH_INTERVAL = 5; // seconds

// Define log file mode and permissions
const char* LOG_FILE_MODE = "a";
const char* LOG_FILE_PERMISSIONS = "644";

// Define remote server connection timeout and retry settings
const int CONNECTION_TIMEOUT = 5; // seconds
const int RETRY_COUNT = 3;
const int RETRY_INTERVAL = 10; // seconds

// Define log entry structure
struct LogEntry {
    enum LogLevel level;
    char* message;
};

// Define log buffer structure
struct LogBuffer {
    struct LogEntry entries[LOG_BUFFER_SIZE];
    int count;
};

// Initialize log buffer and flush interval
static struct LogBuffer log_buffer = { 0 };
static int flush_interval = FLUSH_INTERVAL;

// Define log file descriptor
static int log_file_fd = -1;

// Define remote server connection settings
static bool remote_server_connected = false;
static struct addrinfo* remote_server_addr = NULL;

// Define custom log levels and formats
static const char** custom_log_levels_ptr = &custom_log_levels[0];
static const char** custom_log_formats_ptr = &custom_log_formats[0];

// Function to initialize logging framework
void init_logging(const char* log_file, bool log_to_console, bool remote_server_enabled) {
    // Open log file for writing
    if (log_file != NULL && strlen(log_file) > 0) {
        log_file_fd = open(log_file, O_WRONLY | O_CREAT | O_APPEND, LOG_FILE_MODE);
        if (log_file_fd < 0) {
            perror("Failed to open log file");
            exit(1);
        }
    }

    // Set up remote server connection
    if (remote_server_enabled) {
        struct addrinfo hints;
        memset(&hints, 0, sizeof(struct addrinfo));
        hints.ai_family = AF_UNSPEC;
        hints.ai_socktype = SOCK_STREAM;
        hints.ai_protocol = IPPROTO_TCP;
        if (getaddrinfo(remote_server_url, NULL, &hints, &remote_server_addr) != 0) {
            perror("Failed to resolve remote server address");
            exit(1);
        }
    }
}

// Function to log a message with a specific level and format
void log_message(enum LogLevel level, const char* message, ...) {
    // Check if logging is enabled
    if (!log_to_console && !remote_server_enabled) {
        return;
    }

    // Format log message
    va_list args;
    va_start(args, message);
    char* formatted_message = NULL;
    vasprintf(&formatted_message, message, args);
    va_end(args);

    // Add log entry to buffer
    struct LogEntry entry = { level, formatted_message };
    if (log_buffer.count < LOG_BUFFER_SIZE) {
        log_buffer.entries[log_buffer.count++] = entry;
    } else {
        flush_log_buffer();
        log_buffer.entries[log_buffer.count++] = entry;
    }
}

// Function to flush log buffer to file and remote server
void flush_log_buffer() {
    // Check if logging is enabled
    if (!log_to_console && !remote_server_enabled) {
        return;
    }

    // Flush log buffer to file
    if (log_file_fd >= 0) {
        for (int i = 0; i < log_buffer.count; i++) {
            struct LogEntry entry = log_buffer.entries[i];
            char* formatted_message = format_log_entry(entry);
            write(log_file_fd, formatted_message, strlen(formatted_message));
        }
    }

    // Flush log buffer to remote server
    if (remote_server_enabled) {
        for (int i = 0; i < log_buffer.count; i++) {
            struct LogEntry entry = log_buffer.entries[i];
            char* formatted_message = format_log_entry(entry);
            send_log_to_remote_server(formatted_message);
        }
    }

    // Reset log buffer
    log_buffer.count = 0;
}

// Function to format a log entry with the specified level and format
char* format_log_entry(struct LogEntry entry) {
    char* formatted_message = NULL;
    const char* log_level = log_levels[entry.level];
    const char* log_format = log_formats[entry.level];
    vasprintf(&formatted_message, log_format, entry.message);
    return formatted_message;
}

// Function to send a log message to the remote server
void send_log_to_remote_server(const char* message) {
    // Check if remote server is connected
    if (!remote_server_connected) {
        connect_to_remote_server();
    }

    // Send log message to remote server
    int bytes_sent = send(remote_server_fd, message, strlen(message), 0);
    if (bytes_sent < 0) {
        perror("Failed to send log message to remote server");
        exit(1);
    }
}

// Function to connect to the remote server
void connect_to_remote_server() {
    // Create socket for remote server connection
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Failed to create socket");
        exit(1);
    }

    // Connect to remote server
    struct addrinfo* remote_server_addr_ptr = remote_server_addr;
    int connect_result = connect(sock, remote_server_addr_ptr->ai_addr, remote_server_addr_ptr->ai_addrlen);
    if (connect_result < 0) {
        perror("Failed to connect to remote server");
        exit(1);
    }

    // Set up remote server connection settings
    remote_server_connected = true;
    remote_server_fd = sock;
}

// Function to handle errors in the logging framework
void handle_error(const char* message) {
    perror(message);
    exit(1);
}
