#include <iostream>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <cassert>

using namespace std;

struct NetworkServiceInstance {
    int serviceID;
    set<pair<string, int>> networkConfigurations;
};

class NetworkServiceManager {
public:
    void addService(int serviceID, const vector<pair<string, int>>& networkConfigurations) {
        // Check if the service already exists
        if (serviceMap.find(serviceID) != serviceMap.end()) {
            throw runtime_error("Service with ID " + to_string(serviceID) + " already exists");
        }

        // Add the new service to the map
        NetworkServiceInstance instance;
        instance.serviceID = serviceID;
        for (const auto& config : networkConfigurations) {
            instance.networkConfigurations.insert(config);
        }
        serviceMap[serviceID] = instance;
    }

    void modifyService(int serviceID, const vector<pair<string, int>>& networkConfigurations) {
        // Check if the service exists
        auto it = serviceMap.find(serviceID);
        if (it == serviceMap.end()) {
            throw runtime_error("Service with ID " + to_string(serviceID) + " does not exist");
        }

        // Remove the old configurations and add the new ones
        it->second.networkConfigurations.clear();
        for (const auto& config : networkConfigurations) {
            it->second.networkConfigurations.insert(config);
        }
    }

    void deleteService(int serviceID) {
        // Check if the service exists
        auto it = serviceMap.find(serviceID);
        if (it == serviceMap.end()) {
            throw runtime_error("Service with ID " + to_string(serviceID) + " does not exist");
        }

        // Remove the service from the map
        serviceMap.erase(it);
    }

    void checkForOverlaps() {
        // Check for overlaps between services
        for (const auto& it : serviceMap) {
            const NetworkServiceInstance& instance = it.second;
            for (const auto& config : instance.networkConfigurations) {
                for (const auto& otherIt : serviceMap) {
                    if (otherIt == it) continue; // Skip the current service
                    const NetworkServiceInstance& otherInstance = otherIt.second;
                    for (const auto& otherConfig : otherInstance.networkConfigurations) {
                        if (config.first == otherConfig.first && config.second == otherConfig.second) {
                            // Overlap found, resolve it
                            resolveOverlap(instance, otherInstance);
                            break;
                        }
                    }
                }
            }
        }
    }

private:
    map<int, NetworkServiceInstance> serviceMap;

    void resolveOverlap(const NetworkServiceInstance& instance1, const NetworkServiceInstance& instance2) {
        // Resolve the overlap by dynamically resizing the IP range or adjusting port numbers
        if (instance1.networkConfigurations.size() > instance2.networkConfigurations.size()) {
            // Instance 1 has more configurations, resize its IP range to avoid overlaps
            for (const auto& config : instance1.networkConfigurations) {
                const string& ip = config.first;
                int port = config.second;
                if (instance2.networkConfigurations.find(ip) != instance2.networkConfigurations.end()) {
                    // Overlap found, resize the IP range
                    string newIP = resizeIPRange(ip);
                    modifyService(instance1.serviceID, {{newIP, port}});
                }
            }
        } else {
            // Instance 2 has more configurations, adjust its port numbers to avoid overlaps
            for (const auto& config : instance2.networkConfigurations) {
                const string& ip = config.first;
                int port = config.second;
                if (instance1.networkConfigurations.find(ip) != instance1.networkConfigurations.end()) {
                    // Overlap found, adjust the port number
                    modifyService(instance2.serviceID, {{ip, adjustPortNumber(port)}});
                }
            }
        }
    }

    string resizeIPRange(const string& ip) {
        // Resize the IP range by adding a new octet to the end of the address
        vector<string> parts = split(ip, '.');
        parts.push_back("0");
        return join(parts, '.');
    }

    int adjustPortNumber(int port) {
        // Adjust the port number by adding 1 to it
        return port + 1;
    }
};
```
