using namespace std;

void insertAfterInListAndParseFile(forward_list<string>& list, const string& target, const string& value) {
    // Initialize AES-256-CBC cipher context
    AES_KEY key;
    AES_set_encrypt_key(password, 32 * 8, &key);
    AES_ctr128_ctx ctx;
    AES_ctr128_encrypt(&key, &ctx, NULL, 0);

    // Insert value after target in list
    auto it = find(list.begin(), list.end(), target);
    if (it != list.end()) {
        ++it;
        list.insert_after(it, value);
    } else {
        list.push_back(value);
    }

    // Read binary file and parse contents
    ifstream infile(argv[1], ios::binary);
    vector<unsigned char> data(istreambuf_iterator<char>(infile), {});
    infile.close();

    // Apply transformation based on rules provided as second command-line argument
    string rule = argv[2];
    if (rule == "uppercase") {
        for (auto& c : data) {
            c = toupper(c);
        }
    } else if (rule == "lowercase") {
        for (auto& c : data) {
            c = tolower(c);
        }
    } else {
        // Unknown rule, do nothing
    }

    // Generate output file with transformed contents
    ofstream outfile("output.bin", ios::binary | ios::trunc);
    outfile.write((char*)data.data(), data.size());
    outfile.close();

    // Clean up cipher context
    AES_ctr128_encrypt(&key, &ctx, NULL, 0);
}
