    if (offsets == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return;
    }

    // Initialize offsets array with random values within the range [0, MAX_KEY)
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % MAX_KEY;
    }

    // Allocate memory for keys array
    int *keys = malloc(num_keys * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        free(offsets);
        return;
    }

    // Initialize keys array with unique random values within the range [0, MAX_KEY)
    for (int i = 0; i < num_keys; i++) {
        int key = rand() % MAX_KEY;
        bool found = false;
        for (int j = 0; j < i; j++) {
            if (keys[j] == key) {
                found = true;
                break;
            }
        }
        if (!found) {
            keys[i] = key;
        } else {
            i--;
        }
    }

    // Allocate memory for records array
    struct record **records = malloc(num_records * sizeof(struct record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        free(offsets);
        free(keys);
        return;
    }

    // Initialize records array with random values within the range [MIN_VALUE, MAX_VALUE]
    for (int i = 0; i < num_records; i++) {
        struct record *record = malloc(sizeof(struct record));
        if (record == NULL) {
            fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
            free(offsets);
            free(keys);
            free(records);
            return;
        }
        record->value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        records[i] = record;
    }

    // Free memory allocated for offsets, keys and records arrays
    free(offsets);
    free(keys);
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
    free(records);
}
