        printf("Invalid number of records: %d\n", num_records);
        return NULL;
    }
    if (range < 1 || range > 1000) {
        printf("Invalid range for random values: %d\n", range);
        return NULL;
    }

    // Allocate memory for arrays
    long* offset_array = malloc(num_records * sizeof(long));
    int* key_array = malloc(num_records * sizeof(int));
    record* records = malloc(num_records * sizeof(record));

    // Initialize arrays and records
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = i;
        key_array[i] = rand() % range + 1;
        records[i].key = key_array[i];
    }

    // Sort records based on keys
    qsort(records, num_records, sizeof(record), compare_records);

    return records;
}

int compare_records(const void* a, const void* b) {
    record* ra = (record*)a;
    record* rb = (record*)b;
    return ra->key - rb->key;
}
