    for (int i = 0; i < num_entries; i++) {
        bool found = false;
        for (int j = 0; j < num_groups; j++) {
            if (strcmp(locations[i], grouped_data[j].location) == 0) {
                found = true;
                grouped_data[j].average_temperature += data[i].temperature;
                break;
            }
        }
        if (!found) {
            strcpy(grouped_data[num_groups].location, locations[i]);
            grouped_data[num_groups].average_temperature = data[i].temperature;
            num_groups++;
        }
    }

    // Return pointer to array of grouped data structures
    return grouped_data;
}

// Function to deallocate memory for arrays
