// Safe code example
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <math.h>

#define MIN_TEMPERATURE -60.0f
#define MAX_TEMPERATURE 60.0f
#define MIN_HUMIDITY 0.0f
#define MAX_HUMIDITY 100.0f
#define MIN_NUM_ENTRIES 1000
#define MAX_NUM_ENTRIES 100000

typedef struct {
    float temperature;
    int index;
    char* location;
    double humidity;
} sensor_data;

typedef struct {
    char* location;
    float average_temperature;
    float average_humidity;
    float standard_deviation_temperature;
    float standard_deviation_humidity;
} grouped_data;

void initialize_sensor_data(int num_entries, sensor_data* data) {
    // Validate input parameters
    if (num_entries < MIN_NUM_ENTRIES || num_entries > MAX_NUM_ENTRIES) {
        printf("Invalid number of entries: %d\n", num_entries);
        return;
    }

    for (int i = 0; i < num_entries; i++) {
        data[i].temperature = MIN_TEMPERATURE + ((float)rand() / RAND_MAX) * (MAX_TEMPERATURE - MIN_TEMPERATURE);
        data[i].index = i;
        data[i].location = "Location #1";
        data[i].humidity = MIN_HUMIDITY + ((float)rand() / RAND_MAX) * (MAX_HUMIDITY - MIN_HUMIDITY);
    }
}

void group_sensor_data(int num_entries, sensor_data* data, grouped_data** grouped_data) {
    // Validate input parameters
    if (num_entries < MIN_NUM_ENTRIES || num_entries > MAX_NUM_ENTRIES) {
        printf("Invalid number of entries: %d\n", num_entries);
        return;
    }

    // Allocate memory for the grouped data array
    *grouped_data = malloc(num_entries * sizeof(grouped_data));

    // Initialize the grouped data array
    for (int i = 0; i < num_entries; i++) {
        (*grouped_data)[i].location = "Location #1";
        (*grouped_data)[i].average_temperature = 0.0f;
        (*grouped_data)[i].average_humidity = 0.0f;
        (*grouped_data)[i].standard_deviation_temperature = 0.0f;
        (*grouped_data)[i].standard_deviation_humidity = 0.0f;
    }

    // Group the sensor data by location
    for (int i = 0; i < num_entries; i++) {
        int j = 0;
        while (j < num_entries && strcmp((*grouped_data)[j].location, data[i].location) == 0) {
            j++;
        }
        if (j == num_entries) {
            // No matching location found, create a new entry
            (*grouped_data)[num_entries].location = data[i].location;
            (*grouped_data)[num_entries].average_temperature = 0.0f;
            (*grouped_data)[num_entries].average_humidity = 0.0f;
            (*grouped_data)[num_entries].standard_deviation_temperature = 0.0f;
            (*grouped_data)[num_entries].standard_deviation_humidity = 0.0f;
            num_entries++;
        }
        // Update the average temperature and humidity for the current location
        (*grouped_data)[j].average_temperature += data[i].temperature;
        (*grouped_data)[j].average_humidity += data[i].humidity;
    }

    // Calculate the average temperature and humidity for each location
    for (int i = 0; i < num_entries; i++) {
        (*grouped_data)[i].average_temperature /= (float)num_entries;
        (*grouped_data)[i].average_humidity /= (float)num_entries;
    }

    // Calculate the standard deviation of temperatures and humidities for each location
    for (int i = 0; i < num_entries; i++) {
        float sum_squared_temperature = 0.0f;
        float sum_squared_humidity = 0.0f;
        for (int j = 0; j < num_entries; j++) {
            if (strcmp((*grouped_data)[j].location, (*grouped_data)[i].location) == 0) {
                sum_squared_temperature += pow(((*grouped_data)[j].average_temperature - (*grouped_data)[i].average_temperature), 2);
                sum_squared_humidity += pow(((*grouped_data)[j].average_humidity - (*grouped_data)[i].average_humidity), 2);
            }
        }
        (*grouped_data)[i].standard_deviation_temperature = sqrt(sum_squared_temperature / (float)(num_entries - 1));
        (*grouped_data)[i].standard_deviation_humidity = sqrt(sum_squared_humidity / (float)(num_entries - 1));
    }
}

int main() {
    int num_entries = 50000;
    sensor_data* data = malloc(num_entries * sizeof(sensor_data));
    grouped_data* grouped_data = NULL;

    initialize_sensor_data(num_entries, data);
    group_sensor_data(num_entries, data, &grouped_data);

    // Print the results
    for (int i = 0; i < num_entries; i++) {
        printf("Location: %s\n", grouped_data[i].location);
        printf("Average temperature: %.2f\n", grouped_data[i].average_temperature);
        printf("Average humidity: %.2f\n", grouped_data[i].average_humidity);
        printf("Standard deviation of temperatures: %.2f\n", grouped_data[i].standard_deviation_temperature);
        printf("Standard deviation of humidities: %.2f\n", grouped_data[i].standard_deviation_humidity);
    }

    // Free memory
    free(data);
    free(grouped_data);

    return 0;
}
