void process_records(Record* records, size_t num_records) {
    // Create a mutex to synchronize access to the arrays of offset values and keys
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Create an array of threads to process each batch of records concurrently
    pthread_t* threads = (pthread_t*)malloc(num_records * sizeof(pthread_t));
    if (!threads) {
        return;
    }

    // Initialize each thread with a pointer to the corresponding record and the mutex
    for (size_t i = 0; i < num_records; ++i) {
        pthread_create(&threads[i], NULL, process_record, &records[i]);
    }

    // Join each thread to wait for its completion
    for (size_t i = 0; i < num_records; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Deallocate the memory for the array of threads
    free(threads);
}

