#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>

// Define logging levels
#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_WARNING 2
#define LOG_LEVEL_ERROR 3
#define LOG_LEVEL_CRITICAL 4

// Define logging configuration structure
typedef struct {
    int log_level;
    size_t max_log_files;
    char *log_dir;
} logging_config_t;

// Define logging context structure
typedef struct {
    pthread_mutex_t mutex;
    FILE *log_file;
    int log_level;
    size_t max_log_files;
    char *log_dir;
} logging_context_t;

// Define logging function prototype
void configure_logging_system(logging_config_t *config);

// Implement configuration file parsing
static void parse_configuration_file(const char *filename, logging_config_t *config) {
    // Open the configuration file for reading
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open configuration file %s\n", filename);
        exit(1);
    }

    // Read the log level from the configuration file
    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (strncmp(line, "log_level", 9) == 0) {
            int i = 0;
            for (i = 0; i < 9; i++) {
                line[i] = tolower(line[i]);
            }
            if (strcmp(line, "log_level") == 0) {
                printf("Error: invalid log level in configuration file\n");
                exit(1);
            } else if (strcmp(line, "debug") == 0) {
                config->log_level = LOG_LEVEL_DEBUG;
            } else if (strcmp(line, "info") == 0) {
                config->log_level = LOG_LEVEL_INFO;
            } else if (strcmp(line, "warning") == 0) {
                config->log_level = LOG_LEVEL_WARNING;
            } else if (strcmp(line, "error") == 0) {
                config->log_level = LOG_LEVEL_ERROR;
            } else if (strcmp(line, "critical") == 0) {
                config->log_level = LOG_LEVEL_CRITICAL;
            } else {
                printf("Error: invalid log level in configuration file\n");
                exit(1);
            }
        }
    }

    // Read the maximum number of log files from the configuration file
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (strncmp(line, "max_log_files", 13) == 0) {
            int i = 0;
            for (i = 0; i < 13; i++) {
                line[i] = tolower(line[i]);
            }
            if (strcmp(line, "max_log_files") == 0) {
                printf("Error: invalid maximum number of log files in configuration file\n");
                exit(1);
            } else {
                config->max_log_files = atoi(line + 13);
            }
        }
    }

    // Read the log directory path from the configuration file
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (strncmp(line, "log_dir", 7) == 0) {
            int i = 0;
            for (i = 0; i < 7; i++) {
                line[i] = tolower(line[i]);
            }
            if (strcmp(line, "log_dir") == 0) {
                printf("Error: invalid log directory path in configuration file\n");
                exit(1);
            } else {
                config->log_dir = strdup(line + 7);
            }
        }
    }

    // Close the configuration file
    fclose(fp);
}

// Implement log directory creation
static void create_log_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0 && S_ISDIR(st.st_mode)) {
        // Directory already exists
        return;
    } else {
        // Create the directory
        int ret = mkdir(path, 0755);
        if (ret != 0) {
            printf("Error: unable to create log directory %s\n", path);
            exit(1);
        }
    }
}

// Implement log file management
static void manage_log_files(logging_context_t *ctx) {
    // Check if the maximum number of log files has been reached
    if (ctx->max_log_files > 0 && ctx->log_file != NULL) {
        // Get the current time in milliseconds
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long ms = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

        // Check if the log file needs to be rotated based on time interval or size
        if (ms - ctx->log_file->last_modified > 86400000 || ctx->log_file->size >= 1024 * 1024) {
            // Rotate the log file
            char new_path[PATH_MAX];
            snprintf(new_path, PATH_MAX, "%s/%s.%ld", ctx->log_dir, ctx->log_file->name, ms);
            rename(ctx->log_file->path, new_path);
            ctx->log_file->last_modified = ms;
            ctx->log_file->size = 0;
        }
    }
}

// Implement thread safety for logging functions
static void log_message(logging_context_t *ctx, int level, const char *format, ...) {
    // Check if the message should be logged based on the current log level
    if (level >= ctx->log_level) {
        // Acquire the mutex to prevent race conditions and data corruption
        pthread_mutex_lock(&ctx->mutex);

        // Log the message
        va_list args;
        va_start(args, format);
        vfprintf(ctx->log_file, format, args);
        va_end(args);

        // Release the mutex and return
        pthread_mutex_unlock(&ctx->mutex);
    }
}

// Implement error handling for logging functions
static void handle_error(logging_context_t *ctx, const char *message) {
    // Acquire the mutex to prevent race conditions and data corruption
    pthread_mutex_lock(&ctx->mutex);

    // Log the error message
    fprintf(stderr, "Error: %s\n", message);

    // Release the mutex and return
    pthread_mutex_unlock(&ctx->mutex);
}

// Implement cleanup for logging resources
static void cleanup_logging_system(logging_context_t *ctx) {
    // Close the log file
    if (ctx->log_file != NULL) {
        fclose(ctx->log_file);
    }

    // Release the mutex
    pthread_mutex_destroy(&ctx->mutex);
}

// Implement the logging system configuration function
void configure_logging_system(logging_config_t *config) {
    // Initialize the logging context structure
    logging_context_t ctx;
    ctx.log_level = config->log_level;
    ctx.max_log_files = config->max_log_files;
    ctx.log_dir = strdup(config->log_dir);
    pthread_mutex_init(&ctx.mutex, NULL);

    // Parse the configuration file
    parse_configuration_file("logging.conf", config);

    // Create the log directory if it does not already exist
    create_log_directory(config->log_dir);

    // Open the log file for writing
    ctx.log_file = fopen(config->log_dir, "a");
    if (ctx.log_file == NULL) {
        handle_error(&ctx, "unable to open log file");
    }

    // Manage log files based on time interval or size
    manage_log_files(&ctx);

    // Clean up the logging system resources
    cleanup_logging_system(&ctx);
}
