    double *humidity_levels = (double *)malloc(sizeof(double) * num_entries);

    // Initialize the temperature readings, indices, location names, and humidity levels
    for (int i = 0; i < num_entries; i++) {
        temperature[i].temperature = generate_random(-60, 60);
        indices[i] = i + 1;
        location_names[i] = "Location Name";
        humidity_levels[i] = generate_random(0, 100) * 100;
    }
}

// Function to group the sensor data by location name and calculate statistics
void group_data(int num_entries, float temperature_range, double humidity_range) {
    // Validate input parameters
    validate_input(num_entries, temperature_range, humidity_range);

    // Allocate memory for the grouped data array
    grouped_data *grouped_data = (grouped_data *)malloc(sizeof(grouped_data) * num_entries);

    // Initialize the grouped data array
    for (int i = 0; i < num_entries; i++) {
        grouped_data[i].location = "Location Name";
        grouped_data[i].average_temperature = 0;
        grouped_data[i].average_humidity = 0;
        grouped_data[i].standard_deviation_temperature = 0;
        grouped_data[i].standard_deviation_humidity = 0;
    }

    // Group the sensor data by location name and calculate statistics
    for (int i = 0; i < num_entries; i++) {
        int j = 0;
        while (j < num_entries && strcmp(grouped_data[j].location, "Location Name") == 0) {
            grouped_data[j].average_temperature += temperature[i];
            grouped_data[j].average_humidity += humidity_levels[i];
            j++;
        }
        if (j < num_entries) {
            grouped_data[j].location = "Location Name";
            grouped_data[j].average_temperature = temperature[i] / j;
            grouped_data[j].average_humidity = humidity_levels[i] / j;
        }
    }
}

// Function to compute the standard deviation of temperatures and humidity levels for each group
void compute_standard_deviation(int num_entries, float temperature_range, double humidity_range) {
    // Validate input parameters
    validate_input(num_entries, temperature_range, humidity_range);

    // Allocate memory for the standard deviation arrays
    float *standard_deviation_temperature = (float *)malloc(sizeof(float) * num_entries);
    double *standard_deviation_humidity = (double *)malloc(sizeof(double) * num_entries);

    // Compute the standard deviation of temperatures and humidity levels for each group
    for (int i = 0; i < num_entries; i++) {
        standard_deviation_temperature[i] = sqrt((grouped_data[i].average_temperature - temperature[i]) * (grouped_data[i].average_temperature - temperature[i]) / (num_entries - 1));
        standard_deviation_humidity[i] = sqrt((grouped_data[i].average_humidity - humidity_levels[i]) * (grouped_data[i].average_humidity - humidity_levels[i]) / (num_entries - 1));
    }
}

// Function to return a pointer to an array of grouped data structures
grouped_data *get_grouped_data(int num_entries, float temperature_range, double humidity_range) {
    // Validate input parameters
    validate_input(num_entries, temperature_range, humidity_range);

    // Initialize the sensor data arrays
    init_sensor_data(num_entries, temperature_range, humidity_range);

    // Group the sensor data by location name and calculate statistics
    group_data(num_entries, temperature_range, humidity_range);

    // Compute the standard deviation of temperatures and humidity levels for each group
    compute_standard_deviation(num_entries, temperature_range, humidity_range);

    // Return a pointer to an array of grouped data structures
    return grouped_data;
}
