```java
import java.security.MessageDigest;
import java.util.logging.Logger;

public class MD5Hash {
    private static final Logger LOGGER = Logger.getLogger(MD5Hash.class.getName());

    public static String generateMD5Hash(String input) throws Exception {
        // Validate input parameter
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be null or empty");
        }

        // Create a MessageDigest object for MD5 hashing
        MessageDigest md = MessageDigest.getInstance("MD5");

        // Update the digest with the input string
        byte[] bytes = input.getBytes();
        md.update(bytes, 0, bytes.length);

        // Get the hashed output and convert it to a hexadecimal string
        byte[] hash = md.digest();
        StringBuffer sb = new StringBuffer();
        for (int i = 0; i < hash.length; i++) {
            sb.append(Integer.toString((hash[i] & 0xff) + 0x100, 16).substring(1));
        }
        return sb.toString();
    }
}
