error_summary* processLogFiles(const char* directory) {
    // Check if the input directory is valid
    if (!directory || !strlen(directory)) {
        fprintf(stderr, "Invalid directory path\n");
        return NULL;
    }

    // Get the number of log files in the directory
    int file_count = 0;
    struct dirent* entry;
    DIR* dir = opendir(directory);
    if (dir) {
        while ((entry = readdir(dir)) != NULL) {
            if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) {
                continue;
            }
            file_count++;
        }
    } else {
        fprintf(stderr, "Error opening directory: %s\n", strerror(errno));
        return NULL;
    }

    // Check if the number of log files is within the expected range
    if (file_count < 100 || file_count > 10000) {
        fprintf(stderr, "Invalid number of log files: %d\n", file_count);
        return NULL;
    }

    // Allocate memory for the log entries and error summaries
    log_entry* log_entries = (log_entry*)malloc(file_count * sizeof(log_entry));
    if (!log_entries) {
        fprintf(stderr, "Error allocating memory for log entries\n");
        return NULL;
    }
    error_summary* error_summaries = (error_summary*)malloc(file_count * sizeof(error_summary));
    if (!error_summaries) {
        fprintf(stderr, "Error allocating memory for error summaries\n");
        free(log_entries);
        return NULL;
    }

    // Initialize the log entries and error summaries
    int i = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) {
            continue;
        }
        log_entries[i].path = strdup(entry->d_name);
        log_entries[i].timestamp = 0;
        log_entries[i].line_count = 0;
        error_summaries[i].path = NULL;
        error_summaries[i].timestamp = 0;
        error_summaries[i].errors = NULL;
        i++;
    }

    // Analyze the contents of each log file to identify critical errors
    for (int j = 0; j < file_count; j++) {
        FILE* fp = fopen(log_entries[j].path, "r");
        if (!fp) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            continue;
        }
        char line[1024];
        while (fgets(line, sizeof(line), fp)) {
            // Check if the line contains a critical error message
            if (strstr(line, "critical error")) {
                // Add the error message to the error summary
                error_summaries[j].errors = realloc(error_summaries[j].errors, sizeof(char*) * (error_summaries[j].line_count + 1));
                if (!error_summaries[j].errors) {
                    fprintf(stderr, "Error allocating memory for error messages\n");
                    continue;
                }
                error_summaries[j].errors[error_summaries[j].line_count] = strdup(line);
                error_summaries[j].line_count++;
            }
        }
        fclose(fp);
    }

    // Return the error summaries
    return error_summaries;
}
