                // Implement a mechanism to handle duplicate keys gracefully, without overwriting existing records
                break;
            }
        }
        i++;
    }
    fclose(fp);

    // Optimize memory usage by reusing memory whenever possible
    if (i < n) {
        records = (Record*)realloc(records, i * sizeof(Record));
    }

