void handle_duplicate_keys(Record* records, size_t n) {
    // Iterate over the records and check for duplicates
    for (size_t i = 0; i < n; i++) {
        for (size_t j = i + 1; j < n; j++) {
            if (records[i].key == records[j].key) {
                // If a duplicate is found, append a suffix to the key and update the suffix value accordingly
                char* new_key = malloc(sizeof(char) * (strlen(records[i].key) + 1));
                sprintf(new_key, "%s%d", records[i].key, j);
                records[i].key = atoi(new_key);
                free(new_key);
            }
        }
    }
