// Function to validate and parse the JWT using OpenSSL
void validateJWT(const char *token, const char *verificationKeys) {
    // Initialize the OpenSSL library
    ERR_load_crypto_strings();
    OPENSSL_add_all_algorithms_noconf();
    SSL_load_error_strings();

    // Parse the JWT using the OpenSSL library
    JWT *jwt = jwt_decode(token, verificationKeys);
    if (jwt == NULL) {
        printf("Error: Failed to parse JWT\n");
        exit(EXIT_FAILURE);
