    // Validate the token type is 'Bearer'
    if (!jwt_get_type(jwt)) {
        printf("Error: Token type is not 'Bearer'\n");
        exit(EXIT_FAILURE);
    }

    // Validate the expires in value is a positive integer
    long expiresIn = jwt_get_expires_in(jwt);
    if (expiresIn <= 0) {
        printf("Error: Expires in value is not a positive integer\n");
        exit(EXIT_FAILURE);
    }

    // Validate the access token is valid according to the provided JWT verification keys
    bool isValid = jwt_verify(jwt, verificationKeys);
    if (!isValid) {
        printf("Error: Access token is not valid\n");
        exit(EXIT_FAILURE);
