#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdbool.h>

// Custom data structure for storing 'data_packet' information
typedef struct {
    double value;
    char *string;
    bool flag;
} data_packet;

// Global variables for managing memory and threads
static int fd = -1;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t max_size = 0;
static bool serialized = false;
static data_packet *data = NULL;

// Function to initialize the memory management system
void init_memory(int fd, size_t max_size) {
    this->fd = fd;
    this->max_size = max_size;
    this->serialized = false;
    this->data = NULL;
}

// Function to read data from the file descriptor and store it in memory
void read_data(int fd, size_t max_size) {
    // Open the file descriptor for reading
    int fd = open(fd, O_RDONLY);
    if (fd < 0) {
        perror("Error opening file");
        return;
    }

    // Allocate memory for the data structure
    data = malloc(max_size * sizeof(data_packet));
    if (!data) {
        perror("Error allocating memory");
        close(fd);
        return;
    }

    // Read the data from the file descriptor and store it in the data structure
    size_t read = 0;
    while (read < max_size && !feof(fd)) {
        double value;
        char string[256];
        bool flag;
        fscanf(fd, "%lf %s %d", &value, string, &flag);
        data[read].value = value;
        data[read].string = strdup(string);
        data[read].flag = flag;
        read++;
    }

    // Close the file descriptor
    close(fd);
}

// Function to serialize the data structures to a binary format
void serialize_data() {
    if (!serialized) {
        // Open the file for writing
        int fd = open("data.bin", O_WRONLY | O_CREAT, 0644);
        if (fd < 0) {
            perror("Error opening file");
            return;
        }

        // Write the data structures to the file
        size_t written = 0;
        while (written < max_size && !feof(data)) {
            fwrite(&data[written], sizeof(data_packet), 1, fd);
            written++;
        }

        // Close the file
        close(fd);
    }
}

// Function to deserialize the data structures from a binary format
void deserialize_data() {
    if (serialized) {
        // Open the file for reading
        int fd = open("data.bin", O_RDONLY);
        if (fd < 0) {
            perror("Error opening file");
            return;
        }

        // Read the data structures from the file
        size_t read = 0;
        while (read < max_size && !feof(data)) {
            fread(&data[read], sizeof(data_packet), 1, fd);
            read++;
        }

        // Close the file
        close(fd);
    }
}

// Function to compress stored 'data_packet' structures
void compress_data() {
    // Compress each data packet individually
    for (size_t i = 0; i < max_size; i++) {
        // Check if the data packet is compressed already
        if (!data[i].flag) {
            // Compress the data packet using a custom compression algorithm
            data[i].value = compress(data[i].value);
            data[i].string = compress(data[i].string);
            data[i].flag = true;
        }
    }
}

// Function to handle errors during the data reading and processing
void error_handler(int errno, const char *message) {
    perror(message);
    close(fd);
    free(data);
    exit(1);
}

// Thread-safe function for accessing the data structures from multiple threads
void access_data(size_t index) {
    pthread_mutex_lock(&mutex);
    if (index < max_size && !feof(data)) {
        // Access the data structure at the specified index
        printf("Value: %lf\nString: %s\nFlag: %d\n", data[index].value, data[index].string, data[index].flag);
    } else {
        perror("Error accessing data");
    }
    pthread_mutex_unlock(&mutex);
}

// Main function for managing memory and threads
int main(int argc, char *argv[]) {
    // Initialize the memory management system
    init_memory(argc > 1 ? atoi(argv[1]) : -1, argc > 2 ? atoi(argv[2]) : 0);

    // Read data from the file descriptor and store it in memory
    read_data(fd, max_size);

    // Serialize the data structures to a binary format
    serialize_data();

    // Compress stored 'data_packet' structures
    compress_data();

    // Handle errors during the data reading and processing
    error_handler(-1, "Error handling errors");

    // Access the data structures from multiple threads
    pthread_t thread[3];
    for (size_t i = 0; i < 3; i++) {
        if (pthread_create(&thread[i], NULL, access_data, i) != 0) {
            perror("Error creating thread");
            exit(1);
        }
    }

    // Wait for all threads to complete
    for (size_t i = 0; i < 3; i++) {
        if (pthread_join(thread[i], NULL) != 0) {
            perror("Error joining thread");
            exit(1);
        }
    }

    // Clean up memory and close the file descriptor
    free(data);
    close(fd);

    return 0;
}
