    for (int i = 0; i < num_records; i++) {
        offset_arr[i] = rand() % 100 + 1;
    }

    // Allocate memory for the key array
    key_arr = (int*)malloc(num_records * sizeof(int));
    if (!key_arr) {
        printf("Error: Failed to allocate memory for key array\n");
        return;
    }

    // Initialize the key array with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        key_arr[i] = rand() % 100 + 1;
    }

    // Allocate memory for the record array
    records = (Record**)malloc(num_records * sizeof(Record*));
    if (!records) {
        printf("Error: Failed to allocate memory for record array\n");
        return;
    }

    // Initialize each record with a random integer value within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            return;
        }
        records[i]->value = rand() % 100 + 1;
    }

    // Create a linked list of the records for efficient traversal and modification
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    Record* head = NULL;
    Record* current = NULL;
    for (int i = 0; i < num_records; i++) {
        if (!head) {
            head = records[i];
            current = head;
        } else {
            current->next = records[i];
            current = current->next;
        }
    }
}

// Define the function to update the value of a specific record by its index
void update_record(int index, int new_value) {
    // Check if the index is valid
    if (index < 0 || index >= num_records) {
        printf("Error: Invalid index %d\n", index);
        return;
    }

    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Update the value of the record at the specified index
    records[index]->value = new_value;

    // Release the mutex
    pthread_mutex_unlock(&mutex);
}

// Define the function to retrieve the index of a record based on its value
int get_record_index(int value) {
    // Check if the value is valid
    if (value < 0 || value > 100) {
        printf("Error: Invalid value %d\n", value);
        return -1;
    }

    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Iterate through the linked list of records and find the record with the specified value
    Record* current = head;
    while (current) {
        if (current->value == value) {
            int index = 0;
            for (Record* temp = head; temp != current; temp = temp->next) {
                index++;
            }
            // Release the mutex and return the index of the found record
            pthread_mutex_unlock(&mutex);
            return index;
        }
        current = current->next;
    }

    // Release the mutex and return -1 if no record with the specified value is found
    pthread_mutex_unlock(&mutex);
    return -1;
}

// Define the function to handle potential errors gracefully
void error_handler(char* message) {
    printf("Error: %s\n", message);
}
