```csharp
using System;
using System.Collections.Generic;
using System.Threading;

public class DataGenerator {
    private readonly Random _random = new Random();
    private readonly int _minValue;
    private readonly int _maxValue;
    private readonly Distribution _distribution;
    private readonly List<int> _values = new List<int>();

    public DataGenerator(int minValue, int maxValue, Distribution distribution) {
        _minValue = minValue;
        _maxValue = maxValue;
        _distribution = distribution;
    }

    public void GenerateRandomData() {
        // Acquire the lock for concurrent access to the data generator
        lock (_values) {
            // Iterate over the records and update their values randomly
            foreach (var record in _values) {
                int value = generate_random_value(_minValue, _maxValue, _distribution);
                update_record(record, value, 0);
            }
        }
    }

    public void Reset() {
        // Acquire the lock for concurrent access to the data generator
        lock (_values) {
            // Reset the number of records and total memory usage to zero
            _values.Clear();
        }
    }

    private int generate_random_value(int minValue, int maxValue, Distribution distribution) {
        switch (distribution) {
            case Distribution.Normal:
                return (int)(_random.NextDouble() * (maxValue - minValue + 1)) + minValue;
            case Distribution.Uniform:
                return _random.Next(minValue, maxValue);
            default:
                throw new ArgumentException("Invalid distribution", nameof(distribution));
        }
    }

    private void update_record(int record, int value, char status) {
        // Update the value and status flag of the record
        record.value = value;
        record.status = status;
    }
}
