```c
// DataManager.cpp
#include "DataManager.h"

DataManager::DataManager(int numRecords, int maxValue) {
    this->numRecords_ = numRecords;
    this->maxValue_ = maxValue;
}

DataManager::~DataManager() {}

void DataManager::init() {
    // Initialize the record pool
    recordPool_.init();

    // Generate random data for each record
    for (int i = 0; i < numRecords_; i++) {
        Record* record = recordPool_.allocate();
        record->value = dataGenerator_.generateInt(1, maxValue_);
        record->status = 'A';
        record->next = NULL;
    }
}

void DataManager::addRecord(int key, int value) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex_);

    // Allocate a new record from the pool
    Record* record = recordPool_.allocate();

    // Set the record's key and value
    record->key = key;
    record->value = value;

    // Add the record to the linked list
    if (head_ == NULL) {
        head_ = tail_ = record;
    } else {
        tail_->next = record;
        tail_ = record;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex_);
}

void DataManager::updateRecord(int index, int value, char status) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex_);

    // Find the record at the specified index
    Record* record = findRecordByIndex(index);

    // Update the record's value and status flag
    if (record != NULL) {
        record->value = value;
        record->status = status;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex_);
}

int DataManager::getIndexByValue(int value) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex_);

    // Find the record with the specified value
    Record* record = findRecordByValue(value);

    // Return the index of the record, or -1 if not found
    int index = (record != NULL) ? record->index : -1;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex_);

    return index;
}

void DataManager::garbageCollect() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex_);

    // Iterate over the linked list and free unused records
    Record* record = head_;
    while (record != NULL) {
        if (record->status == 'U') {
            recordPool_.free(record);
            record = head_;
        } else {
            record = record->next;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex_);
}

void DataManager::periodicGarbageCollection() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex_);

    // Iterate over the linked list and free unused records
    Record* record = head_;
    while (record != NULL) {
        if (record->status == 'U') {
            recordPool_.free(record);
            record = head_;
        } else {
            record = record->next;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex_);
}

void DataManager::filter(const char* query) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex_);

    // Create a new filter object
    QueryFilter filter(query);

    // Filter the linked list based on the complex query condition
    filter.filter(&head_, &tail_);

    // Unlock the mutex
    pthread_mutex_unlock(&mutex_);
}

void DataManager::monitorPerformance() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex_);

    // Monitor and log performance metrics, including memory usage, garbage collection frequency, and query processing times
    // ...

    // Unlock the mutex
    pthread_mutex_unlock(&mutex_);
}
