```c
// RecordPool.cpp
#include "RecordPool.h"

RecordPool::RecordPool(int numRecords) {
    this->numRecords_ = numRecords;
}

RecordPool::~RecordPool() {}

void RecordPool::init() {
    // Allocate memory for the record pool
    records_ = (Record**)malloc(sizeof(Record*) * numRecords_);

    // Initialize each record in the pool
    for (int i = 0; i < numRecords_; i++) {
        records_[i] = NULL;
    }
}

Record* RecordPool::allocate() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex_);

    // Find the first available record in the pool
    for (int i = 0; i < numRecords_; i++) {
        if (records_[i] == NULL) {
            records_[i] = (Record*)malloc(sizeof(Record));
            break;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex_);

    return records_[i];
}

void RecordPool::free(Record* record) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex_);

    // Free the record back to the pool
    free(record);

    // Unlock the mutex
    pthread_mutex_unlock(&mutex_);
}
