}

QueryFilter::~QueryFilter() {}

void QueryFilter::filter(Record** head, Record** tail) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex_);

    // Iterate over the linked list and filter based on the complex query condition
    Record* record = *head;
    while (record != NULL) {
        if (!filterRecord(record)) {
            record->status = 'U';
        } else {
            record->status = 'A';
        }
        record = record->next;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex_);
}
