        fprintf(stderr, "Error: %s does not exist\n", path);
        return -1;
    }

    int count = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        count++;
    }

    fclose(file);
    return count;
}

void analyze_log_file(log_entry entry, long *offset, int *key) {
    // Open the log file and read its contents
    FILE *file = fopen(entry.log_file_path, "r");
    if (file == NULL) {
        fprintf(stderr, "Error: %s does not exist\n", entry.log_file_path);
        return;
