    // Initialize the offset and key variables
    *offset = 0;
    *key = 0;

    // Read the contents of the log file line by line
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Check if the current line contains a critical error message
        if (strstr(line, "critical error") != NULL) {
            *offset = ftell(file);
            *key = 1;
            break;
        }
    }

    fclose(file);
}
