['```c
// DataManager.h
#ifndef DATAMANAGER_H
#define DATAMANAGER_H

#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

// Define the record structure
typedef struct Record {
    int value;
    char status;
    struct Record* next;
} Record;

// Define the data manager class
class DataManager {
public:
    // Constructor
    DataManager(int numRecords, int maxValue);

    // Destructor
    ~DataManager();

    // Initialize the data manager
    void init();

    // Add a new record to the linked list
    void addRecord(int key, int value);

    // Update the value and status flag of a specific record by its index
    void updateRecord(int index, int value, char status);

    // Retrieve the index of a record based on its value
    int getIndexByValue(int value);

    // Garbage collector thread function
    static void* garbageCollectorThread();

    // Periodically reclaim memory from unused records and reinsert them into the pool of free records
    void garbageCollection();

    // Monitor and log performance metrics
    void monitorPerformance();

private:
    // Number of records in the linked list
    int numRecords_;

    // Maximum value for random generation
    int maxValue_;

    // Linked list of records
    Record* head_;

    // Pool of free records
    Record* freeList_;

    // Mutex for thread-safe access to the linked list and pool of free records
    pthread_mutex_t mutex_;

    // Condition variable for signaling when a new record is added or a record is updated
    pthread_cond_t condVar_;

    // Flag indicating whether garbage collection is enabled
    bool enableGarbageCollection_;

    // Frequency of garbage collection in seconds
    int garbageCollectionFrequency_;

    // Memory usage threshold in bytes
    size_t memoryUsageThreshold_;

    // Logging mechanism for performance metrics
    FILE* logFile_;
};

#endif /* DATAMANAGER_H */
