```c
// DataManager.cpp
#include "DataManager.h"

DataManager::DataManager(int numRecords, int maxValue) {
    // Initialize the number of records and maximum value for random generation
    numRecords_ = numRecords;
    maxValue_ = maxValue;

    // Allocate memory for the linked list and pool of free records
    head_ = (Record*)malloc(sizeof(Record) * numRecords);
    freeList_ = (Record*)malloc(sizeof(Record) * numRecords);

    // Initialize the mutex and condition variable for thread-safe access to the linked list and pool of free records
    pthread_mutex_init(&mutex_, NULL);
    pthread_cond_init(&condVar_, NULL);

    // Set the flag indicating whether garbage collection is enabled
    enableGarbageCollection_ = true;

    // Set the frequency of garbage collection in seconds
    garbageCollectionFrequency_ = 60;

    // Set the memory usage threshold in bytes
    memoryUsageThreshold_ = 1024 * 1024 * 500; // 500 MB

    // Open the log file for performance metrics logging
    logFile_ = fopen("performance.log", "w");
}

DataManager::~DataManager() {
    // Free the memory allocated for the linked list and pool of free records
    free(head_);
    free(freeList_);

    // Destroy the mutex and condition variable for thread-safe access to the linked list and pool of free records
    pthread_mutex_destroy(&mutex_);
    pthread_cond_destroy(&condVar_);

    // Close the log file for performance metrics logging
    fclose(logFile_);
}

void DataManager::init() {
    // Initialize the linked list and pool of free records
    head_ = NULL;
    freeList_ = NULL;

    // Generate random values for each record
    srand(time(NULL));
    for (int i = 0; i < numRecords_; i++) {
        addRecord(i, rand() % maxValue_);
    }
}

void DataManager::addRecord(int key, int value) {
    // Acquire the mutex for thread-safe access to the linked list and pool of free records
    pthread_mutex_lock(&mutex_);

    // Check if there is a free record available in the pool
    Record* freeRecord = freeList_;
    if (freeRecord != NULL) {
        // Update the value and status flag of the free record
        freeRecord->value = value;
        freeRecord->status = 'A';

        // Remove the free record from the pool
        freeList_ = freeRecord->next;
    } else {
        // Allocate a new record if there is no free record available in the pool
        Record* newRecord = (Record*)malloc(sizeof(Record));
        newRecord->value = value;
        newRecord->status = 'A';
        newRecord->next = NULL;
    }

    // Add the new record to the linked list
    if (head_ == NULL) {
        head_ = newRecord;
    } else {
        Record* current = head_;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newRecord;
    }

    // Signal the condition variable to wake up any waiting threads
    pthread_cond_signal(&condVar_);

    // Release the mutex for thread-safe access to the linked list and pool of free records
    pthread_mutex_unlock(&mutex_);
}

void DataManager::updateRecord(int index, int value, char status) {
    // Acquire the mutex for thread-safe access to the linked list and pool of free records
    pthread_mutex_lock(&mutex_);

    // Check if the index is valid
    if (index < 0 || index >= numRecords_) {
        printf("Invalid index: %d\n", index);
        return;
    }

    // Update the value and status flag of the record at the specified index
    Record* current = head_;
    for (int i = 0; i < index; i++) {
        current = current->next;
    }
    current->value = value;
    current->status = status;

    // Release the mutex for thread-safe access to the linked list and pool of free records
    pthread_mutex_unlock(&mutex_);
}

int DataManager::getIndexByValue(int value) {
    // Acquire the mutex for thread-safe access to the linked list and pool of free records
    pthread_mutex_lock(&mutex_);

    // Check if the value is valid
    if (value < 0 || value > maxValue_) {
        printf("Invalid value: %d\n", value);
        return -1;
    }

    // Search for the record with the specified value
    Record* current = head_;
    int index = 0;
    while (current != NULL) {
        if (current->value == value) {
            break;
        }
        current = current->next;
        index++;
    }

    // Release the mutex for thread-safe access to the linked list and pool of free records
    pthread_mutex_unlock(&mutex_);

    return (current != NULL) ? index : -1;
}

void* DataManager::garbageCollectorThread() {
    // Acquire the mutex for thread-safe access to the linked list and pool of free records
    pthread_mutex_lock(&mutex_);

    // Check if garbage collection is enabled
    if (!enableGarbageCollection_) {
        printf("Garbage collection disabled\n");
        return NULL;
    }

    // Periodically reclaim memory from unused records and reinsert them into the pool of free records
    while (true) {
        // Sleep for a specified amount of time before checking if there are any unused records
        sleep(garbageCollectionFrequency_);

        // Check if there are any unused records in the linked list
        Record* current = head_;
        while (current != NULL) {
            if (current->status == 'U') {
                break;
            }
            current = current->next;
        }

        // If there are no unused records, continue to sleep for the specified amount of time before checking again
        if (current == NULL) {
            continue;
        }

        // Reclaim memory from the unused record and reinsert it into the pool of free records
        Record* unusedRecord = current;
        current->status = 'F';
        freeList_ = unusedRecord;

        // Signal the condition variable to wake up any waiting threads
        pthread_cond_signal(&condVar_);
    }

    // Release the mutex for thread-safe access to the linked list and pool of free records
    pthread_mutex_unlock(&mutex_);

    return NULL;
}

void DataManager::garbageCollection() {
    // Acquire the mutex for thread-safe access to the linked list and pool of free records
    pthread_mutex_lock(&mutex_);

    // Check if garbage collection is enabled
    if (!enableGarbageCollection_) {
        printf("Garbage collection disabled\n");
        return;
    }

    // Periodically reclaim memory from unused records and reinsert them into the pool of free records
    while (true) {
        // Sleep for a specified amount of time before checking if there are any unused records
        sleep(garbageCollectionFrequency_);

        // Check if there are any unused records in the linked list
        Record* current = head_;
        while (current != NULL) {
            if (current->status == 'U') {
                break;
            }
            current = current->next;
        }

        // If there are no unused records, continue to sleep for the specified amount of time before checking again
        if (current == NULL) {
            continue;
        }

        // Reclaim memory from the unused record and reinsert it into the pool of free records
        Record* unusedRecord = current;
        current->status = 'F';
        freeList_ = unusedRecord;

        // Signal the condition variable to wake up any waiting threads
        pthread_cond_signal(&condVar_);
    }

    // Release the mutex for thread-safe access to the linked list and pool of free records
    pthread_mutex_unlock(&mutex_);
}

void DataManager::monitorPerformance() {
    // Acquire the mutex for thread-safe access to the linked list and pool of free records
    pthread_mutex_lock(&mutex_);

    // Check if there is any memory usage threshold exceeded
    size_t usedMemory = 0;
    Record* current = head_;
    while (current != NULL) {
        usedMemory += sizeof(Record);
        current = current->next;
    }
    if (usedMemory > memoryUsageThreshold_) {
        printf("Memory usage threshold exceeded: %zu bytes\n", usedMemory);
    }

    // Check if there is any garbage collection frequency configured
    if (garbageCollectionFrequency_ != 0) {
        printf("Garbage collection frequency: %d seconds\n", garbageCollectionFrequency_);
    }

    // Release the mutex for thread-safe access to the linked list and pool of free records
    pthread_mutex_unlock(&mutex_);
}
