void processAndAggregateMetrics(const char* directory) {
    // Validate input directory path
    if (!validateDirectoryPath(directory)) {
        printf("Invalid directory path: %s\n", directory);
        return;
    }

    // Initialize arrays and structures
    int num_files = getNumFilesInDirectory(directory);
    if (num_files < MIN_METRIC_FILES || num_files > MAX_METRIC_FILES) {
        printf("Invalid number of metric files: %d\n", num_files);
        return;
    }
    double *thresholds = malloc(sizeof(double) * num_files);
    int *counters = malloc(sizeof(int) * num_files);
    char **identifiers = malloc(sizeof(char *) * num_files);
    metric_entry *metric_entries = malloc(sizeof(metric_entry) * num_files);
    data_point *data_points = malloc(sizeof(data_point) * num_files);
    unsigned long *timestamp_offsets = malloc(sizeof(unsigned long) * num_files);
    float *weights = malloc(sizeof(float) * num_files);

    // Populate metric file paths and validate files
    char **metric_file_paths = populateMetricFilePaths(directory, num_files);
    for (int i = 0; i < num_files; i++) {
        if (!validateMetricFile(metric_file_paths[i])) {
            printf("Invalid metric file: %s\n", metric_file_paths[i]);
            return;
        }
    }

    // Process and aggregate metrics in parallel
    pthread_t threads[THREAD_COUNT];
    semaphore_t semaphore = createSemaphore(0);
    for (int i = 0; i < THREAD_COUNT; i++) {
        int thread_id = i;
        pthread_create(&threads[i], NULL, processMetricsThread, &thread_id);
    }
    for (int i = 0; i < THREAD_COUNT; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up memory and log statistics
    free(thresholds);
    free(counters);
    free(identifiers);
    free(metric_entries);
    free(data_points);
    free(timestamp_offsets);
    free(weights);
    for (int i = 0; i < num_files; i++) {
        free(metric_file_paths[i]);
    }
    free(metric_file_paths);
    logStatistics();
}

// Validate directory path and return number of files in directory
bool validateDirectoryPath(const char* directory) {
    struct stat info;
    if (stat(directory, &info) != 0) {
        return false;
    }
    if (!S_ISDIR(info.st_mode)) {
        return false;
    }
    return true;
}

// Get number of files in directory
int getNumFilesInDirectory(const char* directory) {
    DIR *dir = opendir(directory);
    if (dir == NULL) {
        return -1;
    }
    int num_files = 0;
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        num_files++;
    }
    closedir(dir);
    return num_files;
}

// Populate metric file paths and validate files
char **populateMetricFilePaths(const char* directory, int num_files) {
    char **metric_file_paths = malloc(sizeof(char *) * num_files);
    for (int i = 0; i < num_files; i++) {
        metric_file_paths[i] = malloc(PATH_MAX);
        snprintf(metric_file_paths[i], PATH_MAX, "%s/%d.txt", directory, i);
        if (!validateMetricFile(metric_file_paths[i])) {
            printf("Invalid metric file: %s\n", metric_file_paths[i]);
            return NULL;
        }
    }
    return metric_file_paths;
}

// Validate metric file and return true if valid, false otherwise
bool validateMetricFile(const char* path) {
    FILE *file = fopen(path, "r");
    if (file == NULL) {
        return false;
    }
    fclose(file);
    return true;
}

// Process metrics in parallel using threads
void processMetricsThread(void* thread_id) {
    int id = *((int*)thread_id);
    semaphore_wait(&semaphore);
    for (int i = 0; i < num_files; i++) {
        // Process metric file and update data structures
        processMetricFile(metric_file_paths[i], id, &thresholds[i], &counters[i], &identifiers[i], &metric_entries[i], &data_points[i], &timestamp_offsets[i], &weights[i]);
    }
    semaphore_post(&semaphore);
}

// Process a single metric file and update data structures
void processMetricFile(const char* path, int thread_id, double *threshold, int *counter, char **identifier, metric_entry *metric_entry, data_point *data_point, unsigned long *timestamp_offset, float *weight) {
    // Open file and read contents
    FILE *file = fopen(path, "r");
    if (file == NULL) {
        return;
    }
    char line[1024];
    while (fgets(line, 1024, file)) {
        // Parse line and update data structures
        double value = strtod(line, NULL);
        *threshold += value;
        *counter++;
        *identifier = "metric_file";
        *metric_entry = (metric_entry){*threshold, *counter, *identifier};
        *data_point = (data_point){value};
        *timestamp_offset = 0;
        *weight = 1.0f;
    }
    fclose(file);
}

