void initDynamicArray(struct DynamicArray* arr) {
    arr->capacity = 1000; // initial capacity of 1000 nodes
    arr->count = 0;
    arr->nodes = (struct Node*)malloc(arr->capacity * sizeof(struct Node));
}

// Function to add a new node with a random value and timestamp
void addNode(struct DynamicArray* arr, int min_value, int max_value) {
    struct Node node;
    node.value = rand() % (max_value - min_value + 1) + min_value;
    node.timestamp = time(NULL);
    if (arr->count == arr->capacity) { // check if the array is full
        arr->capacity *= 2; // double the capacity of the array
        arr->nodes = (struct Node*)realloc(arr->nodes, arr->capacity * sizeof(struct Node));
    }
    arr->nodes[arr->count++] = node;
}

// Function to update the value of a specific node by its index
void updateNodeValue(struct DynamicArray* arr, int index, int new_value) {
