        if (arr->nodes[i].value == value) {
            return i;
        }
    }
    return -1; // return -1 if the node is not found
}

// Function to clean up nodes that are older than a specified age threshold
void cleanupNodes(struct DynamicArray* arr, time_t age_threshold) {
    for (int i = 0; i < arr->count; i++) {
        if (arr->nodes[i].timestamp < age_threshold) {
            arr->nodes[i] = arr->nodes[--arr->count]; // move the last node to the current position and decrement the count
        }
    }
}

// Function to handle potential errors gracefully
void errorHandler(char* message) {
    printf("Error: %s\n", message);
}

