    }
    new_node->value = value;
    new_node->timestamp = timestamp;
    pthread_mutex_lock(&list->mutex);
    list->nodes = realloc(list->nodes, (list->count + 1) * sizeof(struct Node));
    if (list->nodes == NULL) {
        free(new_node);
        return -2; // Reallocation failed
    }
    list->nodes[list->count] = new_node;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Function to update the value of a specific node by its index
int updateNodeValue(struct NodeList* list, int index, int new_value) {
    if (index < 0 || index >= list->count) {
        return -1; // Invalid index
    }
    pthread_mutex_lock(&list->mutex);
    list->nodes[index]->value = new_value;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Function to retrieve the index of a node based on its value
int getNodeIndex(struct NodeList* list, int value) {
    for (size_t i = 0; i < list->count; i++) {
        if (list->nodes[i]->value == value) {
            return i;
        }
    }
    return -1; // Node not found
}

// Function to remove nodes that are older than a specified age threshold
void cleanupNodes(struct NodeList* list, time_t age_threshold) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->nodes[i]->timestamp < age_threshold) {
            free(list->nodes[i]);
            list->nodes[i] = NULL;
            list->count--;
            i--; // Decrement the index to account for the removed node
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to set the range of values that can be used when adding new nodes
void setValueRange(struct NodeList* list, int min_value, int max_value) {
    list->min_value = min_value;
    list->max_value = max_value;
}

// Function to generate a random value within the defined range
int getRandomValue(struct NodeList* list) {
    return rand() % (list->max_value - list->min_value + 1) + list->min_value;
}

// Function to add a new node with a random value and timestamp
int addNodeWithRandomValue(struct NodeList* list, time_t timestamp) {
    int value = getRandomValue(list);
    return addNode(list, value, timestamp);
}
