struct DynamicDataStructure {
    // Array of nodes
    Node* nodes;
    // Size of the array
    size_t size;
    // Number of elements in the array
    size_t count;
    // Lock for thread safety
    pthread_mutex_t lock;
};

// Initialize the dynamic data structure
void initDynamicDataStructure(struct DynamicDataStructure* ds) {
    // Allocate memory for the nodes
    ds->nodes = (Node*)malloc(sizeof(Node) * INITIAL_SIZE);
    if (!ds->nodes) {
        printf("Error: Failed to allocate memory for nodes\n");
        exit(1);
    }
    // Initialize the size and count
    ds->size = INITIAL_SIZE;
    ds->count = 0;
    // Initialize the lock
    pthread_mutex_init(&ds->lock, NULL);
}

// Add a node to the dynamic data structure
void addNode(struct DynamicDataStructure* ds, int value) {
    // Lock the mutex
    pthread_mutex_lock(&ds->lock);
    // Check if the array is full
    if (ds->count == ds->size) {
        // Double the size of the array
        ds->size *= 2;
        // Reallocate memory for the nodes
        Node* newNodes = (Node*)realloc(ds->nodes, sizeof(Node) * ds->size);
        if (!newNodes) {
            printf("Error: Failed to reallocate memory for nodes\n");
            exit(1);
        }
        // Update the nodes pointer
        ds->nodes = newNodes;
    }
    // Generate a random value within the range
    int randomValue = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    // Add the node to the array
    ds->nodes[ds->count++] = (Node){randomValue, time(NULL)};
    // Unlock the mutex
    pthread_mutex_unlock(&ds->lock);
}

// Update the value of a specific node by its index
void updateNodeValueByIndex(struct DynamicDataStructure* ds, size_t index, int newValue) {
    // Lock the mutex
    pthread_mutex_lock(&ds->lock);
    // Check if the index is valid
    if (index >= ds->count) {
        printf("Error: Invalid index\n");
        exit(1);
    }
    // Update the value of the node
    ds->nodes[index].value = newValue;
    // Unlock the mutex
    pthread_mutex_unlock(&ds->lock);
}

// Retrieve the index of a node based on its value
size_t getNodeIndexByValue(struct DynamicDataStructure* ds, int value) {
    // Lock the mutex
    pthread_mutex_lock(&ds->lock);
    // Iterate over the nodes and find the matching value
    for (size_t i = 0; i < ds->count; i++) {
        if (ds->nodes[i].value == value) {
            // Unlock the mutex
            pthread_mutex_unlock(&ds->lock);
            return i;
        }
    }
    // If no matching node is found, return -1
    printf("Error: Node with value %d not found\n", value);
    exit(1);
}

// Remove nodes older than a specified age threshold
void removeOldNodes(struct DynamicDataStructure* ds, time_t ageThreshold) {
    // Lock the mutex
    pthread_mutex_lock(&ds->lock);
    // Iterate over the nodes and remove those older than the threshold
    for (size_t i = 0; i < ds->count; i++) {
        if (ds->nodes[i].timestamp < ageThreshold) {
            // Remove the node from the array
            ds->count--;
            // Shift the remaining nodes to fill the gap
            for (size_t j = i; j < ds->count; j++) {
                ds->nodes[j] = ds->nodes[j + 1];
            }
            i--;
        }
    }
    // Unlock the mutex
    pthread_mutex_unlock(&ds->lock);
}

// Cleanup function to free memory and release resources
void cleanupDynamicDataStructure(struct DynamicDataStructure* ds) {
    // Lock the mutex
    pthread_mutex_lock(&ds->lock);
    // Free the nodes array
    free(ds->nodes);
    // Release the lock
    pthread_mutex_unlock(&ds->lock);
}
