    if (num_device_data % 50000 != 0) {
        num_groups++;
    }
    grouped_data *grouped_data_array = (grouped_data *)malloc(num_groups * sizeof(grouped_data));
    if (!grouped_data_array) {
        fprintf(stderr, "Failed to allocate memory for grouped data array.\n");
        return NULL;
    }

    // Initialize grouped data array with device data
    int group_index = 0;
    for (int i = 0; i < num_device_data; i++) {
        if (i % 50000 == 0) {
            grouped_data_array[group_index].total_energy_consumption = 0.0f;
            grouped_data_array[group_index].average_energy_consumption_per_hour = 0.0f;
            grouped_data_array[group_index].median_energy_consumption = 0.0f;
            grouped_data_array[group_index].earliest_timestamp = UINT64_MAX;
