        grouped_data_array[group_index - 1].total_energy_consumption += device_data_array[i].energy_consumption;
        grouped_data_array[group_index - 1].average_energy_consumption_per_hour += (device_data_array[i].energy_consumption / 3600.0f);
        if (device_data_array[i].energy_consumption > grouped_data_array[group_index - 1].median_energy_consumption) {
            grouped_data_array[group_index - 1].median_energy_consumption = device_data_array[i].energy_consumption;
        }
        if (device_data_array[i].timestamp < grouped_data_array[group_index - 1].earliest_timestamp) {
            grouped_data_array[group_index - 1].earliest_timestamp = device_data_array[i].timestamp;
