void apply_rules(struct Record* record, char* rules) {
    // Parse the rules string into an array of rule strings
    char** rule_strings = parse_rules(rules);

    // Apply each rule to the record
    for (int i = 0; i < num_rule_strings; i++) {
        apply_rule(record, rule_strings[i]);
    }
}

// Define a function to apply a single rule to a record
void apply_rule(struct Record* record, char* rule) {
    // Check if the rule is a random value assignment
    if (strncmp(rule, "random", 6) == 0) {
        // Extract the range from the rule string
        int min = atoi(rule + 7);
        int max = atoi(rule + 13);

        // Generate a random value within the specified range
        record->value = rand() % (max - min) + min;
    } else {
        // Check if the rule is a key assignment
        if (strncmp(rule, "key", 3) == 0) {
            // Extract the key from the rule string
            int key = atoi(rule + 4);

            // Assign the key to the record
            record->key = key;
        } else {
            // Check if the rule is an offset assignment
            if (strncmp(rule, "offset", 6) == 0) {
                // Extract the offset from the rule string
                long offset = atol(rule + 7);

                // Assign the offset to the record
                record->offset = offset;
            } else {
                // Unknown rule, ignore it
            }
        }
    }
}

// Define a function to parse the rules string into an array of rule strings
char** parse_rules(char* rules) {
    // Count the number of rule strings in the input string
    int num_rule_strings = 1;
    for (int i = 0; i < strlen(rules); i++) {
        if (rules[i] == ';') {
            num_rule_strings++;
        }
    }

    // Allocate memory for the array of rule strings
    char** rule_strings = malloc(num_rule_strings * sizeof(char*));
    if (rule_strings == NULL) {
        printf("Error: unable to allocate memory for rule strings\n");
        return;
    }

    // Parse the rules string into an array of rule strings
    int current_rule = 0;
    char* token = strtok(rules, ";");
    while (token != NULL) {
        rule_strings[current_rule] = malloc(strlen(token) + 1);
        if (rule_strings[current_rule] == NULL) {
            printf("Error: unable to allocate memory for rule string\n");
            return;
        }
        strcpy(rule_strings[current_rule], token);
        current_rule++;
        token = strtok(NULL, ";");
    }

    // Return the array of rule strings
    return rule_strings;
}

// Define a function to free memory allocated for the rule strings
void free_rules(char** rules) {
    // Free each rule string in the array
    for (int i = 0; i < num_rule_strings; i++) {
        free(rules[i]);
    }

    // Free the memory allocated for the array of rule strings
    free(rules);
}

// Define a function to handle buffer overflows and gracefully handle memory allocation failures
void handle_error(char* error) {
    printf("Error: %s\n", error);
    exit(1);
}
