// Define a class for managing the collection of records
class MoSTState {
private:
    // Array to store all records
    Record* records;

    // Number of records in the array
    size_t numRecords;

    // Mutex for thread-safe access to the array
    pthread_mutex_t mutex;

public:
    // Constructor initializes the array and mutex
    MoSTState(size_t capacity) {
        records = (Record*) malloc(capacity * sizeof(Record));
        numRecords = 0;
        pthread_mutex_init(&mutex, NULL);
    }

    // Destructor frees the array and mutex
    ~MoSTState() {
        free(records);
        pthread_mutex_destroy(&mutex);
    }

    // Insert a new record into the collection
    void insertRecord(long offset, int key, int value, const char* buffer) {
        Record newRecord = {offset, key, value, buffer};
        pthread_mutex_lock(&mutex);
        records[numRecords++] = newRecord;
        pthread_mutex_unlock(&mutex);
    }

    // Update an existing record in the collection
    void updateRecord(int key, int value) {
        pthread_mutex_lock(&mutex);
        for (size_t i = 0; i < numRecords; i++) {
            if (records[i].key == key) {
                records[i].value = value;
                break;
            }
        }
        pthread_mutex_unlock(&mutex);
    }

    // Retrieve a record from the collection by its key
    Record* getRecord(int key) {
        pthread_mutex_lock(&mutex);
        for (size_t i = 0; i < numRecords; i++) {
            if (records[i].key == key) {
                return &records[i];
            }
        }
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Remove a record from the collection by its key
    void removeRecord(int key) {
        pthread_mutex_lock(&mutex);
        for (size_t i = 0; i < numRecords; i++) {
            if (records[i].key == key) {
                records[i] = records[--numRecords];
                break;
            }
        }
        pthread_mutex_unlock(&mutex);
    }

    // Serialize the collection to a file
    void serialize(const char* filename) {
        FILE* fp = fopen(filename, "wb");
        if (fp == NULL) {
            printf("Error: unable to open file for serialization\n");
            return;
        }
        pthread_mutex_lock(&mutex);
        fwrite(records, sizeof(Record), numRecords, fp);
        pthread_mutex_unlock(&mutex);
        fclose(fp);
    }

    // Deserialize the collection from a file
    static MoSTState* deserialize(const char* filename) {
        FILE* fp = fopen(filename, "rb");
        if (fp == NULL) {
            printf("Error: unable to open file for deserialization\n");
            return NULL;
        }
        size_t numRecords = 0;
        Record* records = NULL;
        fread(&numRecords, sizeof(size_t), 1, fp);
        if (numRecords > 0) {
            records = (Record*) malloc(numRecords * sizeof(Record));
            fread(records, sizeof(Record), numRecords, fp);
        }
        fclose(fp);
        return new MoSTState(records, numRecords);
    }
};
