#include <utility>

class ConfigCache {
public:
    // Constructor
    ConfigCache() : cache_(), mutex_(), cv_(), update_thread_(nullptr) {}

    // Destructor
    ~ConfigCache() {
        if (update_thread_) {
            update_thread_->join();
        }
    }

    // Load configuration from network
    void load(const std::string& id, const std::string& version) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(id);
        if (it != cache_.end()) {
            // Update existing setting
            it->second.version = version;
            it->second.timestamp = std::chrono::system_clock::now();
            it->second.status = Status::OK;
        } else {
            // Add new setting
            cache_.emplace(id, Config{version, std::chrono::system_clock::now(), Status::OK});
        }
    }

    // Update configuration from network
    void update(const std::string& id, const std::string& version) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(id);
        if (it != cache_.end()) {
            // Update existing setting
            it->second.version = version;
            it->second.timestamp = std::chrono::system_clock::now();
            it->second.status = Status::OK;
        } else {
            // Add new setting
            cache_.emplace(id, Config{version, std::chrono::system_clock::now(), Status::OK});
        }
    }

    // Retrieve configuration from cache
    const Config& get(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(id);
        if (it != cache_.end()) {
            return it->second;
        } else {
            // Return default value
            static Config default_config{"", std::chrono::system_clock::now(), Status::NOT_FOUND};
            return default_config;
        }
    }

    // Invalidate configuration from cache
    void invalidate(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(id);
        if (it != cache_.end()) {
            it->second.status = Status::INVALID;
        }
    }

private:
    // Configuration struct
    struct Config {
        std::string version;
        std::chrono::system_clock::time_point timestamp;
        Status status;
    };

    // Status enum
    enum class Status {
        OK,
        NOT_FOUND,
        INVALID
    };

    // Cache map
    std::unordered_map<std::string, Config> cache_;

    // Mutex for thread safety
    std::mutex mutex_;

    // Condition variable for waiting on updates
    std::condition_variable cv_;

    // Update thread
    std::thread* update_thread_;
};
```
