    for (size_t i = 0; i < numRecords; i++) {
        if (fread(&offsets[i], sizeof(long), 1, input) != 1) {
            printf("Error: unable to read offset %lu\n", (unsigned long)i);
            fclose(input);
            fclose(output);
            return;
        }
        if (fread(&keys[i], sizeof(int), 1, input) != 1) {
            printf("Error: unable to read key %lu\n", (unsigned long)i);
            fclose(input);
            fclose(output);
            return;
        }
    }

    // Update the integer field of each record using a random value within a specified range, using a seed value for reproducible randomization
    srand(time(NULL));
    int minValue = 0;
    int maxValue = 100;
    for (size_t i = 0; i < numRecords; i++) {
        keys[i] = rand() % (maxValue - minValue + 1) + minValue;
    }

    // Compress the output file at the specified compression level, balancing compression efficiency and decompression speed
    size_t compressedSize = compressBound(outputSize);
    void* compressedData = allocateFromPool(&pool, compressedSize);
    if (compressedData == NULL) {
        printf("Error: unable to allocate memory for compressed data\n");
        fclose(input);
        fclose(output);
        return;
    }
    int status = compress2(compressedData, &compressedSize, output, outputSize, compressionLevel);
    if (status != Z_OK) {
        printf("Error: unable to compress data\n");
        fclose(input);
        fclose(output);
        return;
    }

    // Write the compressed data to the output file
    size_t bytesWritten = fwrite(compressedData, 1, compressedSize, output);
    if (bytesWritten != compressedSize) {
        printf("Error: unable to write compressed data\n");
        fclose(input);
        fclose(output);
        return;
    }

    // Clean up memory allocations and deallocations
    free(offsets);
    free(keys);
    deallocateFromPool(&pool, compressedData, compressedSize);

    // Close the input and output files
    fclose(input);
    fclose(output);
}
