    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        exit(1);
    }

    // Initialize the keys with random values
    srand(time(NULL));
    for (size_t i = 0; i < num_keys; i++) {
        keys[i] = rand() % 1000000;
    }

    // Allocate memory for the entry array
    entry_t *entries = (entry_t *)malloc(num_entries * sizeof(entry_t));
    if (!entries) {
        printf("Error: Failed to allocate memory for entries\n");
        exit(1);
    }

    // Initialize the entries with random values
    srand(time(NULL));
    for (size_t i = 0; i < num_entries; i++) {
        entries[i].key = keys[i % num_keys];
        entries[i].value = rand() % 1000000;
        entries[i].timestamp = time(NULL);
    }

    // Read external data from a specified file to populate the key array
    FILE *file = fopen("data.txt", "r");
    if (!file) {
        printf("Error: Failed to open file\n");
        exit(1);
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Parse the line and extract the key-value pair
        int key = atoi(strtok(line, "="));
        int value = atoi(strtok(NULL, "\n"));

        // Add the key-value pair to the entry array
        entries[i].key = key;
        entries[i].value = value;
        entries[i].timestamp = time(NULL);
    }

    fclose(file);

    // Free the memory for the offset, key, and entry arrays
    free(offsets);
    free(keys);
    free(entries);
}
