#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <unistd.h>
#include <pthread.h>

// Define the structure for a session
typedef struct {
    int id;
    char* user_id;
    time_t last_activity;
    bool active;
} session_t;

// Define the hash table for quick lookups of active sessions by user ID
#define HASH_TABLE_SIZE 1024
static session_t* sessions[HASH_TABLE_SIZE];

// Initialize the session collection based on configuration parameters
void init_sessions(int max_sessions, int idle_timeout, int range) {
    // Allocate memory for the hash table and initialize it to NULL
    sessions = calloc(HASH_TABLE_SIZE, sizeof(session_t*));

    // Read user information from a JSON file
    json_object* users = json_object_from_file("users.json");

    // Iterate over the users in the JSON object
    for (int i = 0; i < json_object_array_length(users); i++) {
        json_object* user = json_object_array_get_idx(users, i);

        // Extract the user ID and create a new session structure
        const char* user_id = json_object_get_string(json_object_object_get(user, "id"));
        session_t* session = malloc(sizeof(session_t));
        session->id = i;
        session->user_id = strdup(user_id);
        session->last_activity = time(NULL);
        session->active = true;

        // Add the new session to the hash table
        int index = user_id % HASH_TABLE_SIZE;
        sessions[index] = session;
    }

    // Clean up the JSON object
    json_object_put(users);
}

// Update the last activity timestamp for a given session ID
void update_last_activity(int id) {
    int index = id % HASH_TABLE_SIZE;
    sessions[index]->last_activity = time(NULL);
}

// Check if a session is active based on its ID
bool is_session_active(int id) {
    int index = id % HASH_TABLE_SIZE;
    return sessions[index]->active;
}

// Remove an inactive session from the hash table
void remove_inactive_sessions() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (!sessions[i]) continue;
        if (!is_session_active(sessions[i]->id)) {
            free(sessions[i]);
            sessions[i] = NULL;
        }
    }
}

// Clean up the session collection and free all memory
void cleanup_sessions() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (!sessions[i]) continue;
        free(sessions[i]);
    }
    free(sessions);
}
```
This code defines a function `init_sessions` that initializes the session collection based on configuration parameters such as the maximum number of sessions allowed, the idle timeout period, and the range of unique session identifiers. It also defines functions for updating the last activity timestamp for a given session ID, checking if a session is active based on its ID, removing an inactive session from the hash table, and cleaning up the session collection and freeing all memory.

The `init_sessions` function reads user information from a JSON file using the `json-c` library, ensuring efficient parsing and handling of large files while managing memory to prevent leaks. It uses a hash table for quick lookups of active sessions by user ID, balancing between space efficiency and fast access times.

The `update_last_activity` function updates the last activity timestamp for a given session ID. The `is_session_active` function checks if a session is active based on its ID. The `remove_inactive_sessions` function removes an inactive session from the hash table. Finally, the `cleanup_sessions` function cleans up the session collection and frees all memory.

