}

// Generate a unique identifier for each key pair to facilitate key management and prevent key reuse across different contexts
char* generateUniqueKeyID(BIGNUM* bn) {
    char* id = (char*)malloc(sizeof(char) * 1024);
    sprintf(id, "%s", BN_bn2hex(bn));
    return id;
}

// Get the last modified time of a file in seconds since the epoch
time_t getFileLastModifiedTime(const char* path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        return st.st_mtime;
    } else {
        printf("Error: Could not get last modified time of file %s\n", path);
        return -1;
    }
}

// Count the number of lines in a file
int countLinesInFile(const char* path) {
    FILE* file = fopen(path, "r");
    if (file == NULL) {
        printf("Error: Could not open file %s\n", path);
        return -1;
    }
    int line_count = 0;
    char c;
    while ((c = fgetc(file)) != EOF) {
        if (c == '\n') {
            line_count++;
        }
    }
    fclose(file);
    return line_count;
}
