#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define data structures
typedef struct {
    float temperature;
    int index;
    char location[256];
    double humidity;
    uint64_t timestamp;
} sensor_data;

typedef struct {
    char location[256];
    float average_temperature;
    float average_humidity;
    float stddev_temperature;
    float stddev_humidity;
    uint64_t max_timestamp;
    uint64_t min_timestamp;
    uint64_t num_unique_sensors;
    float num_sensor_readings;
} grouped_data;

// Function to generate random values within a specified range
float rand_range(float min, float max) {
    return (float)(rand() % 1000) / 1000 * (max - min) + min;
}

// Function to validate input parameters
void validate_input(int num_entries, float temperature_min, float temperature_max, double humidity_min, double humidity_max, uint64_t timestamp_min, uint64_t timestamp_max) {
    if (num_entries < 1000 || num_entries > 100000) {
        printf("Invalid number of entries: %d\n", num_entries);
        exit(1);
    }
    if (temperature_min >= temperature_max || humidity_min >= humidity_max) {
        printf("Invalid temperature range: [%.2f, %.2f]\n", temperature_min, temperature_max);
        exit(1);
    }
    if (timestamp_min >= timestamp_max) {
        printf("Invalid timestamp range: [%lu, %lu]\n", timestamp_min, timestamp_max);
        exit(1);
    }
}

// Function to initialize sensor data
void init_sensor_data(sensor_data* data, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        data[i].temperature = rand_range(-60.0f, 60.0f);
        data[i].index = i + 1;
        sprintf(data[i].location, "Location %d", i + 1);
        data[i].humidity = rand_range(0.0, 100.0);
        data[i].timestamp = (uint64_t)time(NULL) + rand() % 31536000; // Add random timestamp within the next year
    }
}

// Function to group sensor data by location and calculate statistics
void group_sensor_data(sensor_data* data, int num_entries, grouped_data** groups, int* num_groups) {
    *num_groups = 0;
    for (int i = 0; i < num_entries; i++) {
        bool found = false;
        for (int j = 0; j < *num_groups; j++) {
            if (!strcmp(data[i].location, groups[j]->location)) {
                groups[j]->average_temperature += data[i].temperature;
                groups[j]->average_humidity += data[i].humidity;
                groups[j]->stddev_temperature += pow(data[i].temperature - groups[j]->average_temperature, 2);
                groups[j]->stddev_humidity += pow(data[i].humidity - groups[j]->average_humidity, 2);
                groups[j]->max_timestamp = max(groups[j]->max_timestamp, data[i].timestamp);
                groups[j]->min_timestamp = min(groups[j]->min_timestamp, data[i].timestamp);
                groups[j]->num_unique_sensors++;
                found = true;
            }
        }
        if (!found) {
            grouped_data* new_group = malloc(sizeof(grouped_data));
            strcpy(new_group->location, data[i].location);
            new_group->average_temperature = data[i].temperature;
            new_group->average_humidity = data[i].humidity;
            new_group->stddev_temperature = 0.0f;
            new_group->stddev_humidity = 0.0f;
            new_group->max_timestamp = data[i].timestamp;
            new_group->min_timestamp = data[i].timestamp;
            new_group->num_unique_sensors = 1;
            groups[*num_groups] = new_group;
            (*num_groups)++;
        }
    }
}

// Function to compute standard deviation of temperatures and humidity levels
void stddev(float* values, int num_values, float* stddev) {
    *stddev = sqrt((pow(values[0], 2) - pow(mean(values, num_values), 2)) / (num_values - 1));
}

// Function to compute mean of temperatures and humidity levels
float mean(float* values, int num_values) {
    float sum = 0.0f;
    for (int i = 0; i < num_values; i++) {
        sum += values[i];
    }
    return sum / num_values;
}

// Function to deallocate memory
void free_memory(grouped_data** groups, int* num_groups) {
    for (int i = 0; i < *num_groups; i++) {
        free(groups[i]);
    }
    free(groups);
}

