void init_sensor_data(int num_entries, float temperature_range, double humidity_range, uint64_t timestamp_range) {
    // Validate input parameters
    validate_input_parameters(num_entries, temperature_range, humidity_range, timestamp_range);

    // Allocate memory for sensor data structures
    sensor_data *sensor_data = malloc(sizeof(sensor_data) * num_entries);

    // Initialize temperature readings
    for (int i = 0; i < num_entries; i++) {
        sensor_data[i].temperature = generate_random_value(-temperature_range, temperature_range);
        sensor_data[i].index = i;
        sensor_data[i].humidity = generate_random_value(0, humidity_range);
        sensor_data[i].timestamp = time(NULL) + (uint64_t)(generate_random_value(0, timestamp_range));
        sensor_data[i].accuracy = HIGH;
    }

    // Initialize location names and metadata
    for (int i = 0; i < num_entries; i++) {
        snprintf(sensor_data[i].location, sizeof(sensor_data[i].location), "Location %d", i);
        sensor_data[i].metadata.geographic_identifier = generate_random_value(1000000, 9999999);
        sensor_data[i].metadata.altitude = generate_random_value(1000, 3000);
    }
}

// Define function to group sensor data by location name and calculate statistics
void group_sensor_data(int num_entries) {
