        grouped_data[i].max_temperature = INT_MIN;
        grouped_data[i].min_humidity = INT_MAX;
        grouped_data[i].max_humidity = INT_MIN;
    }

    // Group sensor data by location name and calculate statistics
    for (int i = 0; i < num_entries; i++) {
