            grouped_data[num_entries].max_temperature = sensor_data[i].temperature;
            grouped_data[num_entries].min_humidity = sensor_data[i].humidity;
            grouped_data[num_entries].max_humidity = sensor_data[i].humidity;
            num_entries++;
        } else {
            // Location name already found, update statistics
            grouped_data[j].average_temperature += sensor_data[i].temperature;
            grouped_data[j].average_humidity += sensor_data[i].humidity;
            grouped_data[j].average_timestamp += sensor_data[i].timestamp;
            grouped_data[j].num_unique_sensors++;
            if (sensor_data[i].temperature < grouped_data[j].min_temperature) {
                grouped_data[j].min_temperature = sensor_data[i].temperature;
            }
            if (sensor_data[i].temperature > grouped_data[j].max_temperature) {
                grouped_data[j].max_temperature = sensor_data[i].temperature;
