            if (sensor_data[i].humidity < grouped_data[j].min_humidity) {
                grouped_data[j].min_humidity = sensor_data[i].humidity;
            }
            if (sensor_data[i].humidity > grouped_data[j].max_humidity) {
                grouped_data[j].max_humidity = sensor_data[i].humidity;
            }
        }
    }
}

