#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <math.h>

// Define the data structure to store the sensor readings
typedef struct {
    char location[20];
    float temperature;
    int index;
    double humidity;
    uint64_t timestamp;
    enum weather_condition {sunny, rainy, cloudy} weather;
} sensor_data;

// Define the data structure to store the grouped data
typedef struct {
    char location[20];
    float average_temperature;
    double average_humidity;
    enum weather_condition most_frequent_weather;
    double standard_deviation_temperature;
    double standard_deviation_humidity;
    uint64_t earliest_timestamp;
    uint64_t latest_timestamp;
} grouped_data;

// Function to manage and analyze the large dataset of sensor readings
grouped_data* analyze_sensor_readings(int num_sensors, int num_locations) {
    // Allocate memory for the sensor data array
    sensor_data* sensor_array = (sensor_data*)malloc(num_sensors * sizeof(sensor_data));
    if (!sensor_array) {
        printf("Error: Failed to allocate memory for sensor data array\n");
        return NULL;
    }

    // Initialize the sensor data array with random values within specified ranges
    for (int i = 0; i < num_sensors; i++) {
        sensor_array[i].temperature = roundf(rand() % 100) / 10.0;
        sensor_array[i].index = rand() % 100;
        sensor_array[i].humidity = (double)(rand() % 100) / 10.0;
        sensor_array[i].timestamp = time(NULL);
        sensor_array[i].weather = (enum weather_condition)(rand() % 3);
    }

    // Allocate memory for the grouped data array
    grouped_data* grouped_array = (grouped_data*)malloc(num_locations * sizeof(grouped_data));
    if (!grouped_array) {
        printf("Error: Failed to allocate memory for grouped data array\n");
        free(sensor_array);
        return NULL;
    }

    // Group the sensor data by location name and calculate the average temperature, humidity, most frequent weather condition, and standard deviations
    for (int i = 0; i < num_locations; i++) {
        grouped_array[i].location[0] = '\0';
        grouped_array[i].average_temperature = 0.0;
        grouped_array[i].average_humidity = 0.0;
        grouped_array[i].most_frequent_weather = sunny;
        grouped_array[i].standard_deviation_temperature = 0.0;
        grouped_array[i].standard_deviation_humidity = 0.0;
        grouped_array[i].earliest_timestamp = UINT64_MAX;
        grouped_array[i].latest_timestamp = 0;
    }

    for (int i = 0; i < num_sensors; i++) {
        int location_index = -1;
        for (int j = 0; j < num_locations; j++) {
            if (strcmp(sensor_array[i].location, grouped_array[j].location) == 0) {
                location_index = j;
                break;
            }
        }

        if (location_index == -1) {
            printf("Error: Failed to find location for sensor data\n");
            free(sensor_array);
            free(grouped_array);
            return NULL;
        }

        grouped_array[location_index].average_temperature += sensor_array[i].temperature;
        grouped_array[location_index].average_humidity += sensor_array[i].humidity;
        grouped_array[location_index].most_frequent_weather = (enum weather_condition)max(grouped_array[location_index].most_frequent_weather, sensor_array[i].weather);
        grouped_array[location_index].standard_deviation_temperature += pow((sensor_array[i].temperature - grouped_array[location_index].average_temperature), 2.0);
        grouped_array[location_index].standard_deviation_humidity += pow((sensor_array[i].humidity - grouped_array[location_index].average_humidity), 2.0);
        grouped_array[location_index].earliest_timestamp = min(grouped_array[location_index].earliest_timestamp, sensor_array[i].timestamp);
        grouped_array[location_index].latest_timestamp = max(grouped_array[location_index].latest_timestamp, sensor_array[i].timestamp);
    }

    for (int i = 0; i < num_locations; i++) {
        grouped_array[i].average_temperature /= num_sensors;
        grouped_array[i].average_humidity /= num_sensors;
        grouped_array[i].standard_deviation_temperature = sqrt(grouped_array[i].standard_deviation_temperature / (num_sensors - 1));
        grouped_array[i].standard_deviation_humidity = sqrt(grouped_array[i].standard_deviation_humidity / (num_sensors - 1));
    }

    free(sensor_array);
    return grouped_array;
}
