// Define the data structures for device data and grouped data
typedef struct {
    float energy_consumption;
    char *device_id;
    double timestamp;
    int device_type;
} device_data;

typedef struct {
    char *device_id;
    float total_energy_consumption;
    float average_energy_consumption_per_hour;
    char median_energy_consumption;
    int device_type;
    uint64_t earliest_timestamp;
    uint64_t latest_timestamp;
} grouped_data;

// Define the custom hash function for grouping data
uint64_t hash(const char *device_id) {
    // Implement a simple hash function that takes the first 8 characters of the device ID and returns an integer value
    uint64_t hash = 0;
    for (int i = 0; i < 8; i++) {
        hash += device_id[i];
    }
    return hash % 1000000007; // Use a modulo to ensure that the hash value is between 0 and 10^8 - 1
}

// Define the function for grouping data by device ID
grouped_data *group_data(device_data *data, int num_entries) {
    // Allocate memory for the array of grouped data structures
    grouped_data *grouped_data = (grouped_data *)malloc(num_entries * sizeof(grouped_data));
    if (!grouped_data) {
        fprintf(stderr, "Error: Failed to allocate memory for grouped data\n");
        return NULL;
    }

    // Initialize the array of grouped data structures
    for (int i = 0; i < num_entries; i++) {
        grouped_data[i].device_id = NULL;
        grouped_data[i].total_energy_consumption = 0.0f;
        grouped_data[i].average_energy_consumption_per_hour = 0.0f;
        grouped_data[i].median_energy_consumption = 0.0f;
        grouped_data[i].device_type = 0;
        grouped_data[i].earliest_timestamp = 0;
        grouped_data[i].latest_timestamp = 0;
    }

    // Loop through the device data and group by device ID
    for (int i = 0; i < num_entries; i++) {
        int hash_value = hash(data[i].device_id);
        grouped_data[hash_value].device_id = strdup(data[i].device_id);
        grouped_data[hash_value].total_energy_consumption += data[i].energy_consumption;
        grouped_data[hash_value].average_energy_consumption_per_hour += data[i].energy_consumption / 3600.0f;
        if (data[i].energy_consumption > grouped_data[hash_value].median_energy_consumption) {
            grouped_data[hash_value].median_energy_consumption = data[i].energy_consumption;
        }
        grouped_data[hash_value].device_type = data[i].device_type;
        if (data[i].timestamp < grouped_data[hash_value].earliest_timestamp || grouped_data[hash_value].earliest_timestamp == 0) {
            grouped_data[hash_value].earliest_timestamp = data[i].timestamp;
        }
        if (data[i].timestamp > grouped_data[hash_value].latest_timestamp) {
            grouped_data[hash_value].latest_timestamp = data[i].timestamp;
        }
    }

    // Compute the median energy consumption for each group
    for (int i = 0; i < num_entries; i++) {
        if (grouped_data[i].total_energy_consumption > 0) {
            grouped_data[i].median_energy_consumption = grouped_data[i].total_energy_consumption / 2.0f;
        }
    }

    // Compute the variance and standard deviation for each group
    for (int i = 0; i < num_entries; i++) {
        float sum = 0.0f;
        for (int j = 0; j < num_entries; j++) {
            if (strcmp(grouped_data[i].device_id, data[j].device_id) == 0) {
                sum += pow((data[j].energy_consumption - grouped_data[i].median_energy_consumption), 2.0f);
            }
        }
        grouped_data[i].variance = sum / (num_entries - 1.0f);
        grouped_data[i].standard_deviation = sqrt(sum / (num_entries - 1.0f));
    }

    // Return the array of grouped data structures
    return grouped_data;
}
