void allocateAndInitializeArrays(int numRecords, int keyRange) {
    // Allocate memory for the offset and key arrays
    long *offsets = (long *)malloc(numRecords * sizeof(long));
    int *keys = (int *)malloc(numRecords * sizeof(int));

    // Initialize the offset array with random values within the given range
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = rand() % keyRange;
    }

    // Initialize the key array with random values within the given range
    for (int i = 0; i < numRecords; i++) {
        keys[i] = rand() % keyRange;
    }

    // Use a loop to set the value of each record's int field to a random value within the given range
    for (int i = 0; i < numRecords; i++) {
        keys[i] = rand() % keyRange;
    }

    // Free the memory allocated for the offset and key arrays
    free(offsets);
    free(keys);
}

String getMD5Hash(String input) {
    try {
        // Use a standard library function to generate the MD5 hash of the input string
        byte[] bytes = input.getBytes("UTF-8");
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(bytes);
        return new String(digest, "UTF-8");
    } catch (NoSuchAlgorithmException | UnsupportedEncodingException e) {
        // Handle any exceptions gracefully
        System.out.println("Error generating MD5 hash: " + e.getMessage());
        return null;
    }
}
