// Define constants for array sizes and seed value
#define MAX_OFFSETS 1000
#define MAX_KEYS 1000
#define SEED 42

// Function to allocate memory for two arrays: offsets and keys
void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to compute MD5 hash of a given string and return it as a hexadecimal string
char* getMD5Hash(const char* str) {
    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)str, strlen(str), md5);
    char* hash = malloc(MD5_DIGEST_LENGTH * 2 + 1);
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&hash[i * 2], "%02x", md5[i]);
    }
    hash[MD5_DIGEST_LENGTH * 2] = '\0';
    return hash;
}

// Function to populate the key array with random numbers between -1000 and 1000, inclusive
void populateKeys(int* keys) {
    srand(SEED);
    for (int i = 0; i < MAX_KEYS; ++i) {
        keys[i] = rand() % 2000 - 1000;
    }
}

// Function to process data and compute MD5 hashes
void processData(int* keys, char** md5Hashes) {
    // Allocate memory for the offsets array
    int* offsets = allocateMemory(MAX_OFFSETS * sizeof(int));
    // Compute the MD5 hash of each key and store it in a dynamically allocated char array
    for (int i = 0; i < MAX_KEYS; ++i) {
        md5Hashes[i] = getMD5Hash(keys[i]);
    }
    // Populate the offsets array with the starting indices of each MD5 hash in the char array
    for (int i = 0; i < MAX_KEYS; ++i) {
        offsets[i] = strlen(md5Hashes[i - 1]) + 1;
    }
}

// Function to free all allocated memory
void cleanup(int* keys, char** md5Hashes, int* offsets) {
    // Free the memory for the key array and MD5 hashes
    free(keys);
    free(md5Hashes);
    // Free the memory for the offsets array
    free(offsets);
}

int main() {
