    char** md5Hashes = malloc(MAX_KEYS * sizeof(char*));
    // Populate the key array with random numbers between -1000 and 1000, inclusive
    populateKeys(keys);
    // Process the data and compute MD5 hashes
    processData(keys, md5Hashes);
    // Free all allocated memory to prevent resource leaks
    cleanup(keys, md5Hashes, offsets);
    return 0;
}
