#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the struct for storing transaction data
typedef struct {
    float amount;
    int age;
    bool is_valid;
    char* description;
    void* transaction_id;
} transaction_t;

// Define the enum for storing status codes
typedef enum {
    SUCCESS,
    FAILURE,
    PENDING
} status_t;

// Define the struct for storing hash table entries
typedef struct {
    char* key;
    transaction_t value;
} hash_entry_t;

// Define the struct for storing metrics
typedef struct {
    int num_transactions;
    float total_amount;
    status_t max_status;
    void* max_transaction_id;
} metrics_t;

// Define the hash function for generating hash values
unsigned long hash(char* key) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++) != '\0') {
        hash = ((hash << 5) + hash) + c;
    }
    return hash % TABLE_SIZE;
}

// Define the collision resolution strategy using chaining for open addressing with linear probing
void resolve_collision(hash_entry_t* entry, int index) {
    // Check if the current index is a valid index in the table
    if (index < 0 || index >= TABLE_SIZE) {
        return;
    }

    // If the current index is already occupied, try linear probing
    while (table[index].key != NULL) {
        index = (index + 1) % TABLE_SIZE;
    }

    // Insert the entry at the found index
    table[index] = *entry;
}

// Define the function for inserting a new transaction into the hash table
void insert(char* key, transaction_t value) {
    // Calculate the hash value for the given key
    unsigned long hash = hash(key);

    // Check if the current index is a valid index in the table
    int index = hash % TABLE_SIZE;
    if (index < 0 || index >= TABLE_SIZE) {
        return;
    }

    // If the current index is already occupied, try collision resolution
    while (table[index].key != NULL && strcmp(table[index].key, key) != 0) {
        resolve_collision(&table[index], index);
    }

    // Insert the entry at the found index
    table[index] = (hash_entry_t){ .key = key, .value = value };
}

// Define the function for updating a transaction in the hash table
void update(char* key, transaction_t new_value) {
    // Calculate the hash value for the given key
    unsigned long hash = hash(key);

    // Check if the current index is a valid index in the table
    int index = hash % TABLE_SIZE;
    if (index < 0 || index >= TABLE_SIZE) {
        return;
    }

    // If the current index is already occupied, try collision resolution
    while (table[index].key != NULL && strcmp(table[index].key, key) != 0) {
        resolve_collision(&table[index], index);
    }

    // Update the entry at the found index with the new value
    table[index] = (hash_entry_t){ .key = key, .value = new_value };
}

// Define the function for deleting a transaction from the hash table
void delete(char* key) {
    // Calculate the hash value for the given key
    unsigned long hash = hash(key);

    // Check if the current index is a valid index in the table
    int index = hash % TABLE_SIZE;
    if (index < 0 || index >= TABLE_SIZE) {
        return;
    }

    // If the current index is already occupied, try collision resolution
    while (table[index].key != NULL && strcmp(table[index].key, key) != 0) {
        resolve_collision(&table[index], index);
    }

    // Delete the entry at the found index
    table[index] = (hash_entry_t){ .key = NULL, .value = { 0.0f, 0, false, NULL, NULL } };
}

// Define the function for iterating over the hash table and printing its contents
void print_table() {
    // Iterate over each entry in the table
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (table[i].key != NULL) {
            printf("Key: %s\n", table[i].key);
            printf("Value:\n");
            printf("\tAmount: %.2f\n", table[i].value.amount);
            printf("\tAge: %d\n", table[i].value.age);
            printf("\tIs Valid: %s\n", table[i].value.is_valid ? "true" : "false");
            printf("\tDescription: %s\n", table[i].value.description);
            printf("\tTransaction ID: %p\n", table[i].value.transaction_id);
        }
    }
}

// Define the function for filtering transactions based on a set of criteria
void filter(metrics_t* metrics, int num_transactions) {
    // Iterate over each entry in the table
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (table[i].key != NULL) {
            // Check if the transaction meets the filtering criteria
            bool is_valid = true;
            int age = table[i].value.age;
            float amount = table[i].value.amount;
            void* transaction_id = table[i].value.transaction_id;
            if (age < 3 || amount < 100.0f) {
                is_valid = false;
            }

            // Update the metrics accordingly
            if (is_valid) {
                metrics->num_transactions++;
                metrics->total_amount += amount;
                if (metrics->max_status < table[i].value.status) {
                    metrics->max_status = table[i].value.status;
                    metrics->max_transaction_id = transaction_id;
                }
            }
        }
    }
}

// Define the function for resizing the hash table if it becomes too full
void resize(int new_size) {
    // Create a new hash table with the given size
    hash_entry_t* new_table = (hash_entry_t*)malloc(new_size * sizeof(hash_entry_t));
    for (int i = 0; i < new_size; i++) {
        new_table[i] = (hash_entry_t){ .key = NULL, .value = { 0.0f, 0, false, NULL, NULL } };
    }

    // Iterate over each entry in the old table and insert it into the new table
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (table[i].key != NULL) {
            unsigned long hash = hash(table[i].key);
            int index = hash % new_size;
            while (new_table[index].key != NULL && strcmp(new_table[index].key, table[i].key) != 0) {
                index = (index + 1) % new_size;
            }
            if (new_table[index].key == NULL) {
                new_table[index] = table[i];
            } else {
                resolve_collision(&new_table[index], index);
            }
        }
    }

    // Free the old hash table and assign the new one
    free(table);
    table = new_table;
}

// Define the function for managing memory allocation and deallocation
void manage_memory() {
    // Allocate memory for the hash table
    table = (hash_entry_t*)malloc(TABLE_SIZE * sizeof(hash_entry_t));
    if (table == NULL) {
        printf("Error: Failed to allocate memory for the hash table\n");
        exit(1);
    }

    // Initialize each entry in the table with a null key and value
    for (int i = 0; i < TABLE_SIZE; i++) {
        table[i] = (hash_entry_t){ .key = NULL, .value = { 0.0f, 0, false, NULL, NULL } };
    }
}

// Define the function for handling allocation failures gracefully
void handle_allocation_failure() {
    printf("Error: Failed to allocate memory\n");
    exit(1);
}

int main() {
    // Initialize the hash table and metrics
    manage_memory();
    metrics = (metrics_t){ .num_transactions = 0, .total_amount = 0.0f, .max_status = SUCCESS, .max_transaction_id = NULL };

    // Insert transactions into the hash table
    insert("transaction1", (transaction_t){ .amount = 100.0f, .age = 5, .is_valid = true, .description = "Test transaction 1", .transaction_id = NULL });
    insert("transaction2", (transaction_t){ .amount = 200.0f, .age = 3, .is_valid = false, .description = "Test transaction 2", .transaction_id = NULL });
    insert("transaction3", (transaction_t){ .amount = 300.0f, .age = 10, .is_valid = true, .description = "Test transaction 3", .transaction_id = NULL });
    insert("transaction4", (transaction_t){ .amount = 400.0f, .age = 2, .is_valid = false, .description = "Test transaction 4", .transaction_id = NULL });
    insert("transaction5", (transaction_t){ .amount = 500.0f, .age = 8, .is_valid = true, .description = "Test transaction 5", .transaction_id = NULL });

    // Filter transactions based on a set of criteria
    filter(&metrics, 3);

    // Print the contents of the hash table and metrics
    print_table();
    printf("Metrics:\n");
    printf("\tNumber of Transactions: %d\n", metrics.num_transactions);
    printf("\tTotal Amount: %.2f\n", metrics.total_amount);
    printf("\tMax Status: %s\n", metrics.max_status == SUCCESS ? "SUCCESS" : (metrics.max_status == FAILURE ? "FAILURE" : "PENDING"));
    printf("\tMax Transaction ID: %p\n", metrics.max_transaction_id);

    // Resize the hash table if it becomes too full
    resize(TABLE_SIZE * 2);

    // Free all allocated memory
    free(table);
    return 0;
}
