#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>

// Custom data structure for storing metadata
struct metadata {
    int some_int;
    float some_float;
};

// Custom data structure for storing struct data
struct data {
    double d;
    char *s;
    struct metadata *m;
    bool b;
};

// Custom enum for storing status codes
enum status {
    OK,
    ERROR
};

// Custom hash function for calculating hash values
unsigned long custom_hash(void *key) {
    unsigned long hash = 0;
    char *str = (char *)key;
    int i;
    for (i = 0; i < strlen(str); i++) {
        hash += (unsigned long)str[i];
        hash <<= 1;
    }
    return hash % 1000003; // Prime number to ensure good distribution
}

// Custom collision resolution strategy using open addressing with quadratic probing
void *custom_probe(struct data **table, unsigned long index) {
    while (table[index] != NULL && table[index]->status == ERROR) {
        index = (index + 1) % TABLE_SIZE;
    }
    return table[index];
}

// Custom linked list for managing hash table entries
struct entry {
    struct data *data;
    struct entry *next;
};

// Hash table structure
struct hash_table {
    unsigned long size;
    struct entry **table;
    pthread_mutex_t mutex;
};

// Function to create a new hash table with the given size
struct hash_table *create_hash_table(unsigned long size) {
    struct hash_table *ht = malloc(sizeof(struct hash_table));
    ht->size = size;
    ht->table = calloc(size, sizeof(struct entry *));
    pthread_mutex_init(&ht->mutex, NULL);
    return ht;
}

// Function to insert a new struct data into the hash table
void insert(struct hash_table *ht, struct data *data) {
    unsigned long index = custom_hash(data->s) % ht->size;
    struct entry *entry = malloc(sizeof(struct entry));
    entry->data = data;
    entry->next = NULL;
    pthread_mutex_lock(&ht->mutex);
    if (ht->table[index] == NULL) {
        ht->table[index] = entry;
    } else {
        struct entry *curr = ht->table[index];
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = entry;
    }
    pthread_mutex_unlock(&ht->mutex);
}

// Function to delete a struct data from the hash table
void delete(struct hash_table *ht, struct data *data) {
    unsigned long index = custom_hash(data->s) % ht->size;
    pthread_mutex_lock(&ht->mutex);
    if (ht->table[index] == NULL) {
        pthread_mutex_unlock(&ht->mutex);
        return;
    }
    struct entry *curr = ht->table[index];
    while (curr != NULL && curr->data != data) {
        curr = curr->next;
    }
    if (curr == NULL) {
        pthread_mutex_unlock(&ht->mutex);
        return;
    }
    if (curr->next == NULL) {
        ht->table[index] = NULL;
    } else {
        curr->next = curr->next->next;
    }
    free(curr);
    pthread_mutex_unlock(&ht->mutex);
}

// Function to update a struct data in the hash table
void update(struct hash_table *ht, struct data *data) {
    unsigned long index = custom_hash(data->s) % ht->size;
    pthread_mutex_lock(&ht->mutex);
    if (ht->table[index] == NULL) {
        pthread_mutex_unlock(&ht->mutex);
        return;
    }
    struct entry *curr = ht->table[index];
    while (curr != NULL && curr->data != data) {
        curr = curr->next;
    }
    if (curr == NULL) {
        pthread_mutex_unlock(&ht->mutex);
        return;
    }
    curr->data = data;
    pthread_mutex_unlock(&ht->mutex);
}

// Function to iterate over the hash table and print its contents in a formatted manner
void print(struct hash_table *ht) {
    unsigned long i;
    for (i = 0; i < ht->size; i++) {
        struct entry *curr = ht->table[i];
        while (curr != NULL) {
            printf("Key: %s\n", curr->data->s);
            printf("Value: ");
            print_struct(curr->data);
            printf("\n");
            curr = curr->next;
        }
    }
}

// Function to resize the hash table if it becomes too full
void resize(struct hash_table *ht) {
    unsigned long new_size = ht->size * 2;
    struct entry **new_table = calloc(new_size, sizeof(struct entry *));
    unsigned long i;
    for (i = 0; i < ht->size; i++) {
        struct entry *curr = ht->table[i];
        while (curr != NULL) {
            unsigned long new_index = custom_hash(curr->data->s) % new_size;
            if (new_table[new_index] == NULL) {
                new_table[new_index] = malloc(sizeof(struct entry));
                new_table[new_index]->data = curr->data;
                new_table[new_index]->next = NULL;
            } else {
                struct entry *curr2 = new_table[new_index];
                while (curr2->next != NULL) {
                    curr2 = curr2->next;
                }
                curr2->next = malloc(sizeof(struct entry));
                curr2->next->data = curr->data;
                curr2->next->next = NULL;
            }
            curr = curr->next;
        }
    }
    free(ht->table);
    ht->size = new_size;
    ht->table = new_table;
}

// Function to compress a char string using a custom algorithm
char *compress(char *str) {
    int i, j;
    for (i = 0, j = 0; str[j] != '\0'; j++) {
        if (str[j] == ' ') {
            while (str[j + 1] == ' ') {
                j++;
            }
            str[i++] = ' ';
        } else {
            str[i++] = str[j];
        }
    }
    str[i] = '\0';
    return str;
}

// Function to enable or disable compression of char strings
void set_compression(struct hash_table *ht, bool enabled) {
    ht->compress = enabled;
}

// Function to flush the logs to a file at specified intervals
void flush_logs(struct hash_table *ht) {
    FILE *fp = fopen("log.txt", "a");
    if (fp == NULL) {
        return;
    }
    unsigned long i;
    for (i = 0; i < ht->size; i++) {
        struct entry *curr = ht->table[i];
        while (curr != NULL) {
            fprintf(fp, "Key: %s\n", curr->data->s);
            fprintf(fp, "Value: ");
            print_struct(curr->data);
            fprintf(fp, "\n");
            curr = curr->next;
        }
    }
    fclose(fp);
}

// Function to free all allocated memory upon function exit
void cleanup(struct hash_table *ht) {
    unsigned long i;
    for (i = 0; i < ht->size; i++) {
        struct entry *curr = ht->table[i];
        while (curr != NULL) {
            free(curr->data);
            curr = curr->next;
        }
    }
    free(ht->table);
}
