using System;
using System.Xml;
using System.Linq;
using System.Collections.Generic;

public struct Data {
    public double[] dataPoints;
    public char[] labels;
    public int[] indices;
}

public static Data parseAndProcessXML(string xmlFilePath, string xpathQuery) {
    // Load the XML document
    XmlDocument doc = new XmlDocument();
    doc.Load(xmlFilePath);

    // Select the first element matching the XPath query
    XmlNode node = doc.SelectSingleNode(xpathQuery);

    // Check if the node exists and has child nodes
    if (node == null || !node.HasChildNodes) {
        return null;
    }

    // Allocate memory for the data arrays
    int maxSize = 5000;
    double[] dataPoints = new double[maxSize];
    char[] labels = new char[maxSize];
    int[] indices = new int[maxSize];

    // Fill the index array with unique sequential numbers starting from 0
    for (int i = 0; i < maxSize; i++) {
        indices[i] = i;
    }

    // Populate the label array with unique identifiers based on the corresponding index
    for (int i = 0; i < maxSize; i++) {
        labels[i] = "ID_" + (i + 1).ToString("D4");
    }

    // Calculate the mean of the data points
    double[] dataPointsArray = node.ChildNodes.Cast<XmlNode>().Select(n => Convert.ToDouble(n.InnerText)).ToArray();
    double mean = calculateMean(dataPointsArray);

    // Return the mean value along with a pointer to the label array and the total number of processed records
    return new Data {
        dataPoints = dataPoints,
        labels = labels,
        indices = indices,
        mean = mean,
        numRecords = node.ChildNodes.Count
    };
}

public static double calculateMean(double[] values) {
    // Calculate the sum of all values
    double sum = 0;
    for (int i = 0; i < values.Length; i++) {
        sum += values[i];
    }

    // Return the mean value
    return sum / values.Length;
}
