DataObject parseAndProcessXML(const char *xml, const char *xpath) {
    // Initialize the DataObject structure to be returned
    DataObject obj;
    obj.label = NULL;
    obj.index = 0;
    obj.mean = 0.0;

    // Parse the XML document using XPath and extract the first element matching the specified name
    xmlDocPtr doc = xmlReadFile(xml, NULL, 0);
    if (!doc) {
        fprintf(stderr, "Error: Unable to parse XML file\n");
        return obj;
    }
    xmlXPathContextPtr context = xmlXPathNewContext(doc);
    if (!context) {
        fprintf(stderr, "Error: Unable to create XPath context\n");
        xmlFreeDoc(doc);
        return obj;
    }
    xmlNodeSetPtr nodes = xmlXPathNodeSetCreate();
    if (!nodes) {
        fprintf(stderr, "Error: Unable to create node set\n");
        xmlXPathFreeContext(context);
        xmlFreeDoc(doc);
        return obj;
    }
    int result = xmlXPathEval(xpath, context, nodes);
    if (result != 0) {
        fprintf(stderr, "Error: Unable to evaluate XPath expression\n");
        xmlXPathFreeNodeSet(nodes);
        xmlXPathFreeContext(context);
        xmlFreeDoc(doc);
        return obj;
    }
    if (nodes->nodeNr == 0) {
        fprintf(stderr, "Error: No nodes found\n");
        xmlXPathFreeNodeSet(nodes);
        xmlXPathFreeContext(context);
        xmlFreeDoc(doc);
        return obj;
    }
    xmlNodePtr node = nodes->nodeTab[0];

    // Extract the label and index from the first element matching the specified name
    const char *label = (const char *)xmlGetProp(node, "label");
    int index = atoi((const char *)xmlGetProp(node, "index"));

    // Allocate memory for the label and index strings
    obj.label = (char *)malloc(strlen(label) + 1);
    if (!obj.label) {
        fprintf(stderr, "Error: Unable to allocate memory for label\n");
        xmlXPathFreeNodeSet(nodes);
        xmlXPathFreeContext(context);
        xmlFreeDoc(doc);
        return obj;
    }
    strcpy(obj.label, label);
    obj.index = index;

    // Free the memory allocated for the XML document and node set
    xmlXPathFreeNodeSet(nodes);
    xmlXPathFreeContext(context);
    xmlFreeDoc(doc);

    // Return the structured data object containing the first element matching the specified name along with additional metadata
    return obj;
}

