    char* md5HashArray = malloc(numRecords * 32);
    char* sha256HashArray = malloc(numRecords * 32);

    // Check if memory allocation was successful
    if (offsetArray == NULL || md5HashArray == NULL || sha256HashArray == NULL) {
        printf("Memory allocation failed\n");
        return -1;
    }

    // Initialize the random seed for generating random numbers
    srand(time(NULL));

    // Fill the key array with random integers between -1000 and 1000, inclusive
    for (int i = 0; i < numRecords; i++) {
        keyArray[i] = rand() % 2000 - 1000;
    }

    // Populate the value array with random doubles between 0.0 and 1.0, ensuring uniform distribution and avoiding duplicates
    for (int i = 0; i < numRecords; i++) {
        double randDouble = ((double)rand() / RAND_MAX);
        while (valueArray[i] == valueArray[i - 1]) {
            randDouble = ((double)rand() / RAND_MAX);
        }
        valueArray[i] = randDouble;
    }

    // Compute the MD5 hash of each key and store it in the md5HashArray
    for (int i = 0; i < numRecords; i++) {
        char* md5Hash = getMD5Hash(keyArray[i]);
        strcpy(md5HashArray + (32 * i), md5Hash);
    }

    // Compute the SHA-256 hash of each key and store it in the sha256HashArray
    for (int i = 0; i < numRecords; i++) {
        char* sha256Hash = getSHA256Hash(keyArray[i]);
        strcpy(sha256HashArray + (32 * i), sha256Hash);
    }

    // Cache frequently accessed hash results to improve performance
    for (int i = 0; i < numRecords; i++) {
        char* md5Hash = getMD5Hash(keyArray[i]);
        cacheMD5Hash(md5Hash);
        char* sha256Hash = getSHA256Hash(keyArray[i]);
        cacheSHA256Hash(sha256Hash);
    }

    // Free the memory allocated for the arrays
    free(offsetArray);
    free(md5HashArray);
    free(sha256HashArray);

    return numRecords;
}

// Java method to compute the MD5 hash of a string
public static String getMD5Hash(String input) {
    try {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        BigInteger number = new BigInteger(1, messageDigest);
        String hashtext = number.toString(16);
        while (hashtext.length() < 32) {
            hashtext = "0" + hashtext;
        }
        return hashtext;
    } catch (NoSuchAlgorithmException e) {
        System.out.println("MD5 algorithm not found.");
        return null;
    }
}

// Java method to compute the SHA-256 hash of a string
public static String getSHA256Hash(String input) {
    try {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] messageDigest = md.digest(input.getBytes());
        BigInteger number = new BigInteger(1, messageDigest);
        String hashtext = number.toString(16);
        while (hashtext.length() < 32) {
            hashtext = "0" + hashtext;
        }
        return hashtext;
    } catch (NoSuchAlgorithmException e) {
        System.out.println("SHA-256 algorithm not found.");
        return null;
    }
}

// Cache frequently accessed MD5 hashes to improve performance
private static Map<String, String> md5Cache = new HashMap<>();
public static void cacheMD5Hash(String input) {
    md5Cache.put(input, getMD5Hash(input));
}

// Cache frequently accessed SHA-256 hashes to improve performance
private static Map<String, String> sha256Cache = new HashMap<>();
public static void cacheSHA256Hash(String input) {
    sha256Cache.put(input, getSHA256Hash(input));
}
