    // Compute the hash of the string
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, str, strlen(str));
    SHA256_Final(hash, &ctx);

    // Convert the hash to a hexadecimal string
