// Custom memory management system for efficient cleanup
struct MemoryPool {
    size_t capacity;
    void** blocks;
};

void* allocate(size_t size) {
    // Allocate memory from the pool
    return malloc(size);
}

void deallocate(void* ptr) {
    // Deallocate memory back to the pool
    free(ptr);
}

struct MemoryPool* createMemoryPool(size_t capacity) {
    struct MemoryPool* pool = (struct MemoryPool*)malloc(sizeof(struct MemoryPool));
    pool->capacity = capacity;
    pool->blocks = (void**)malloc(sizeof(void*) * capacity);
    return pool;
}

void destroyMemoryPool(struct MemoryPool* pool) {
    // Deallocate all memory blocks in the pool
    for (size_t i = 0; i < pool->capacity; ++i) {
        free(pool->blocks[i]);
    }
    free(pool->blocks);
    free(pool);
}

