// Define a custom memory pool for frequent allocations and deallocations of records
struct MemoryPool {
    size_t capacity; // maximum number of elements in the pool
    size_t count; // current number of elements in the pool
    void** elements; // array of pointers to allocated memory
};

// Define a linked list node for storing records
struct RecordNode {
    int key;
    long offset;
    struct RecordNode* next;
};

// Define a linked list for storing records
struct RecordList {
    struct RecordNode* head; // pointer to the first node in the list
    struct RecordNode* tail; // pointer to the last node in the list
};

// Define a function for allocating memory for and initializing four arrays: one for 'long' offset values, one for 'int' keys, one for 'record' structures, and another for 'status flags'. Each 'record' contains a single 'int' value, 'char' status, and 'double' timestamp.
// The function should also maintain a linked list of these records to allow efficient addition and deletion of individual records.
int allocate_and_initialize_records(size_t n, struct MemoryPool* pool, struct RecordList** record_list) {
    // Allocate memory for the arrays
    long* offset_array = malloc(n * sizeof(long));
    int* key_array = malloc(n * sizeof(int));
    struct Record* record_array = malloc(n * sizeof(struct Record));
    char* status_flag_array = malloc(n * sizeof(char));

    // Check for allocation failures
    if (offset_array == NULL || key_array == NULL || record_array == NULL || status_flag_array == NULL) {
        return -1; // error code for allocation failure
    }

    // Initialize the arrays with random values within a specified range [min, max]
    srand(time(NULL));
    for (size_t i = 0; i < n; i++) {
        offset_array[i] = rand() % (max - min + 1) + min;
        key_array[i] = rand() % (max - min + 1) + min;
        record_array[i].value = rand() % (max - min + 1) + min;
        status_flag_array[i] = ' ';
    }

    // Initialize the linked list for storing records
    *record_list = malloc(sizeof(struct RecordList));
    (*record_list)->head = NULL;
    (*record_list)->tail = NULL;

    // Allocate memory for each record and store it in the linked list
    for (size_t i = 0; i < n; i++) {
        struct RecordNode* node = malloc(sizeof(struct RecordNode));
        if (node == NULL) {
            return -1; // error code for allocation failure
        }
        node->key = key_array[i];
        node->offset = offset_array[i];
        node->next = NULL;
        if ((*record_list)->head == NULL) {
            (*record_list)->head = node;
            (*record_list)->tail = node;
        } else {
            (*record_list)->tail->next = node;
            (*record_list)->tail = node;
        }
    }

    // Free the memory for the arrays and return success
    free(offset_array);
    free(key_array);
    free(record_array);
    free(status_flag_array);
    return 0; // success code
}

// Define a function for deallocating all allocated memory for the record arrays and linked list
void deallocate_records(struct MemoryPool* pool, struct RecordList** record_list) {
    // Deallocate memory for each record in the linked list
    while ((*record_list)->head != NULL) {
        struct RecordNode* node = (*record_list)->head;
        (*record_list)->head = (*record_list)->head->next;
        free(node);
    }

    // Deallocate memory for the linked list
    free(*record_list);
    *record_list = NULL;
}

// Define a function for resetting the entire structure to its initial state, which involves freeing all allocated memory, reinitializing the arrays with zeros, and resetting the linked list to its empty state.
void reset_records(struct MemoryPool* pool, struct RecordList** record_list) {
    // Deallocate memory for each record in the linked list
    deallocate_records(pool, record_list);

    // Reinitialize the arrays with zeros
    memset(pool->elements[0], 0, pool->capacity * sizeof(long));
    memset(pool->elements[1], 0, pool->capacity * sizeof(int));
    memset(pool->elements[2], 0, pool->capacity * sizeof(struct Record));
    memset(pool->elements[3], 0, pool->capacity * sizeof(char));

    // Reset the linked list to its empty state
    (*record_list)->head = NULL;
    (*record_list)->tail = NULL;
}
