// Custom hash table implementation
struct HashTable {
    struct Node *head;
};

struct Node {
    int key;
    void *value;
    struct Node *next;
};

void initHashTable(struct HashTable *ht) {
    ht->head = NULL;
}

void insertIntoHashTable(struct HashTable *ht, int key, void *value) {
    struct Node *node = malloc(sizeof(struct Node));
    node->key = key;
    node->value = value;
    node->next = ht->head;
    ht->head = node;
}

void *lookupInHashTable(struct HashTable *ht, int key) {
    struct Node *node = ht->head;
    while (node != NULL && node->key != key) {
        node = node->next;
    }
    return node == NULL ? NULL : node->value;
}

void freeHashTable(struct HashTable *ht) {
    struct Node *node = ht->head;
    while (node != NULL) {
        struct Node *next = node->next;
        free(node);
        node = next;
    }
}

