#include <string.h>
#include <time.h>
#include <pthread.h>

// Define data structures and constants
#define MAX_METRICS 20000
#define MIN_METRIC_SIZE 100
#define MAX_DATA_POINTS 50000
#define MEMORY_LIMIT (1024 * 1024 * 1024) // 1 GB
#define ALLOCATION_FAILURE -1
#define SUCCESS 0
#define FAILURE 1

// Define custom memory pool for record structures
struct MemoryPool {
    struct Record* records;
    int size;
};

// Define data point structure
struct DataPoint {
    unsigned long timestamp_offset;
    float weight;
};

// Define record structure
struct Record {
    int key;
    char status;
    double timestamp;
    double metric_threshold;
    int event_counter;
    char resource_identifier;
    struct DataPoint* data_points;
};

// Define function to initialize memory pool
void initMemoryPool(struct MemoryPool* pool) {
    pool->records = NULL;
    pool->size = 0;
}

// Define function to allocate record in memory pool
int allocateRecord(struct MemoryPool* pool, struct Record* record) {
    if (pool->size == 0) {
        // Allocate initial block of records
        pool->records = malloc(sizeof(struct Record) * MAX_DATA_POINTS);
        if (pool->records == NULL) {
            return ALLOCATION_FAILURE;
        }
        pool->size = MAX_DATA_POINTS;
    } else if (pool->size < MAX_DATA_POINTS) {
        // Allocate additional block of records
        struct Record* new_records = realloc(pool->records, sizeof(struct Record) * pool->size * 2);
        if (new_records == NULL) {
            return ALLOCATION_FAILURE;
        }
        pool->records = new_records;
        pool->size *= 2;
    } else {
        // Memory limit reached, cannot allocate more records
        return FAILURE;
    }
    memcpy(pool->records + (pool->size - MAX_DATA_POINTS), record, sizeof(struct Record));
    return SUCCESS;
}

// Define function to deallocate record in memory pool
void deallocateRecord(struct MemoryPool* pool, struct Record* record) {
    if (record == NULL) {
        return;
    }
    memcpy(pool->records + (pool->size - MAX_DATA_POINTS), record, sizeof(struct Record));
}

// Define function to process and aggregate data
void processAndAggregateData(char* resource_directory) {
    // Initialize memory pool for records
    struct MemoryPool record_pool;
    initMemoryPool(&record_pool);

    // Initialize arrays for offset values, keys, statuses, timestamps, metric thresholds, event counters, and resource identifiers
    long* offset_values = malloc(sizeof(long) * MAX_DATA_POINTS);
    int* keys = malloc(sizeof(int) * MAX_DATA_POINTS);
    char* statuses = malloc(sizeof(char) * MAX_DATA_POINTS);
    double* timestamps = malloc(sizeof(double) * MAX_DATA_POINTS);
    double* metric_thresholds = malloc(sizeof(double) * MAX_DATA_POINTS);
    int* event_counters = malloc(sizeof(int) * MAX_DATA_POINTS);
    char* resource_identifiers = malloc(sizeof(char) * MAX_DATA_POINTS);

    // Initialize data point array
    struct DataPoint* data_points = malloc(sizeof(struct DataPoint) * MAX_DATA_POINTS);

    // Initialize linked list for records
    struct Record* head = NULL;
    struct Record* tail = NULL;

    // Open resource directory and validate path
    FILE* resource_dir = fopen(resource_directory, "r");
    if (resource_dir == NULL) {
        printf("Error: Could not open resource directory\n");
        return;
    }

    // Process each metric file in the directory
    while (fscanf(resource_dir, "%s", filename) != EOF) {
        if (strlen(filename) < MIN_METRIC_SIZE) {
            continue;
        }
        FILE* metric_file = fopen(filename, "r");
        if (metric_file == NULL) {
            printf("Error: Could not open metric file %s\n", filename);
            continue;
        }

        // Process contents of each metric file
        while (fscanf(metric_file, "%d %c %lf %lf %d %c", &key, &status, &timestamp, &metric_threshold, &event_counter, &resource_identifier) != EOF) {
            // Allocate record in memory pool
            struct Record* new_record = malloc(sizeof(struct Record));
            if (new_record == NULL) {
                printf("Error: Could not allocate record\n");
                continue;
            }
            memcpy(new_record, &key, sizeof(int));
            memcpy(new_record + 1, &status, sizeof(char));
            memcpy(new_record + 2, &timestamp, sizeof(double));
            memcpy(new_record + 3, &metric_threshold, sizeof(double));
            memcpy(new_record + 4, &event_counter, sizeof(int));
            memcpy(new_record + 5, &resource_identifier, sizeof(char));

            // Allocate data point array in record
            struct DataPoint* new_data_points = malloc(sizeof(struct DataPoint) * MAX_DATA_POINTS);
            if (new_data_points == NULL) {
                printf("Error: Could not allocate data points\n");
                continue;
            }
            memcpy(new_record + 6, new_data_points, sizeof(struct DataPoint) * MAX_DATA_POINTS);

            // Add record to linked list
            if (head == NULL) {
                head = tail = new_record;
            } else {
                tail->next = new_record;
                tail = new_record;
            }
        }

        // Close metric file
        fclose(metric_file);
    }

    // Close resource directory
    fclose(resource_dir);

    // Process and aggregate data
    while (head != NULL) {
        struct Record* record = head;
        head = head->next;

        // Aggregate data points for each record
        int i = 0;
        while (i < MAX_DATA_POINTS && record->data_points[i].timestamp_offset != 0) {
            // Update offset values, keys, statuses, timestamps, metric thresholds, event counters, and resource identifiers
            offset_values[i] = record->data_points[i].timestamp_offset;
            keys[i] = record->key;
            statuses[i] = record->status;
            timestamps[i] = record->timestamp;
            metric_thresholds[i] = record->metric_threshold;
            event_counters[i] = record->event_counter;
            resource_identifiers[i] = record->resource_identifier;

            // Update data point array
            data_points[i].timestamp_offset = offset_values[i];
            data_points[i].weight = record->data_points[i].weight;

            i++;
        }

        // Deallocate record in memory pool
        deallocateRecord(&record_pool, record);
    }

    // Log operations and validate data integrity
    FILE* log_file = fopen("log.txt", "a");
    if (log_file == NULL) {
        printf("Error: Could not open log file\n");
        return;
    }
    for (int i = 0; i < MAX_DATA_POINTS; i++) {
        fprintf(log_file, "%d %c %lf %lf %d %c %lu %f\n", keys[i], statuses[i], timestamps[i], metric_thresholds[i], event_counters[i], resource_identifiers[i], offset_values[i], data_points[i].weight);
    }
    fclose(log_file);
}
