void init_database(struct Database *db) {
    db->events = NULL;
    db->n_events = 0;
    pthread_mutex_init(&db->mutex, NULL);
}

void destroy_database(struct Database *db) {
    free(db->events);
    pthread_mutex_destroy(&db->mutex);
}

int insert_event(struct Database *db, struct Event *event) {
    int ret = 0;
    pthread_mutex_lock(&db->mutex);
    if (db->n_events == 0) {
        db->events = malloc(sizeof(struct Event));
        assert(db->events != NULL);
        memcpy(db->events, event, sizeof(struct Event));
        db->n_events++;
    } else {
        struct Event *new_events = realloc(db->events, (db->n_events + 1) * sizeof(struct Event));
        assert(new_events != NULL);
        memcpy(&new_events[db->n_events], event, sizeof(struct Event));
        db->events = new_events;
        db->n_events++;
    }
    pthread_mutex_unlock(&db->mutex);
    return ret;
}

int lookup_event(struct Database *db, int id) {
    int ret = -1;
    pthread_mutex_lock(&db->mutex);
    for (size_t i = 0; i < db->n_events; i++) {
        if (db->events[i].id == id) {
            ret = i;
            break;
        }
    }
    pthread_mutex_unlock(&db->mutex);
    return ret;
}

int update_event(struct Database *db, int id, struct Event *event) {
    int ret = -1;
    pthread_mutex_lock(&db->mutex);
    int index = lookup_event(db, id);
    if (index != -1) {
        memcpy(&db->events[index], event, sizeof(struct Event));
        ret = 0;
    }
    pthread_mutex_unlock(&db->mutex);
    return ret;
}

int delete_event(struct Database *db, int id) {
    int ret = -1;
    pthread_mutex_lock(&db->mutex);
    int index = lookup_event(db, id);
    if (index != -1) {
        struct Event *new_events = realloc(db->events, (db->n_events - 1) * sizeof(struct Event));
        assert(new_events != NULL);
        memmove(&new_events[index], &new_events[index + 1], (db->n_events - index - 1) * sizeof(struct Event));
        db->events = new_events;
        db->n_events--;
        ret = 0;
    }
    pthread_mutex_unlock(&db->mutex);
    return ret;
}

