    pthread_mutex_lock(&ds->mutex);
    Node* node = &ds->nodes[index];
    node->value = new_value;
    node->timestamp = time(NULL);
    pthread_mutex_unlock(&ds->mutex);
}

// Define the function for retrieving the index of a node based on its value
int get_node_index(DataStructure* ds, int value) {
    pthread_mutex_lock(&ds->mutex);
    for (size_t i = 0; i < ds->num_nodes; i++) {
        if (ds->nodes[i].value == value) {
            pthread_mutex_unlock(&ds->mutex);
            return i;
        }
    }
    pthread_mutex_unlock(&ds->mutex);
    return -1; // Return -1 if the node is not found
}

// Define the function for periodically cleaning up old nodes
void cleanup(DataStructure* ds) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&ds->mutex);
    for (size_t i = 0; i < ds->num_nodes; i++) {
        if (current_time - ds->nodes[i].timestamp > 3600) { // Remove nodes older than an hour
            Node* node = &ds->nodes[i];
            free(node);
            ds->num_nodes--;
            for (size_t j = i; j < ds->num_nodes; j++) {
                ds->nodes[j] = ds->nodes[j + 1];
            }
        }
    }
    pthread_mutex_unlock(&ds->mutex);
}

