void compress(DataStructure* ds) {
    size_t num_nodes = ds->num_nodes;
    Node* nodes = ds->nodes;
    pthread_mutex_lock(&ds->mutex);
    for (size_t i = 0; i < num_nodes; i++) {
        if (nodes[i].value == 0) { // Remove zero-valued nodes
            Node* node = &nodes[i];
            free(node);
            ds->num_nodes--;
            for (size_t j = i; j < num_nodes; j++) {
                nodes[j] = nodes[j + 1];
            }
        }
    }
    pthread_mutex_unlock(&ds->mutex);
}

