    Node* nodes = malloc(num_nodes * sizeof(Node));
    if (nodes == NULL) {
        printf("Error: Failed to allocate memory for nodes\n");
        exit(1);
    }
    pthread_mutex_lock(&ds->mutex);
    ds->nodes = nodes;
    ds->num_nodes = num_nodes;
    pthread_mutex_unlock(&ds->mutex);
}
