    // Validate the consistency of the data structure across all threads
    for (int i = 0; i < cds->num_nodes; i++) {
        if (cds->nodes[i].value != cds->nodes[i].value || cds->nodes[i].priority != cds->nodes[i].priority) {
            printf("Corruption detected in node %d\n", i);
        }
    }

    // Release the lock on the data structure
    pthread_mutex_unlock(&cds->mutex);
}

void log_modification(ConcurrentDataStructure* cds, int index, int value, unsigned long timestamp, int priority) {
    // Acquire the lock on the logging system
    pthread_mutex_lock(&cds->logging_system.mutex);

    // Add a new log entry to the logging system
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->index = index;
    entry->value = value;
    entry->timestamp = timestamp;
    entry->priority = priority;
    cds->logging_system.log[cds->logging_system.num_entries++] = entry;

    // Release the lock on the logging system
    pthread_mutex_unlock(&cds->logging_system.mutex);
}

void compress(ConcurrentDataStructure* cds) {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&cds->mutex);

    // Compress the data structure by reducing its size by up to 50%
    for (int i = 0; i < cds->num_nodes / 2; i++) {
        free(cds->nodes[i]);
        cds->num_nodes--;
    }

    // Release the lock on the data structure
    pthread_mutex_unlock(&cds->mutex);
}
