#include <unistd.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>

// Custom data structures and functions for managing memory and resources
struct record {
    long offset;
    int key;
    struct data_point *data_points;
    char status;
    double timestamp;
    double metric_threshold;
    int event_counter;
    char resource_identifier;
};

struct data_point {
    unsigned long timestamp_offset;
    float weight;
};

void init_record(struct record *r) {
    r->offset = 0;
    r->key = 0;
    r->data_points = NULL;
    r->status = ' ';
    r->timestamp = 0.0;
    r->metric_threshold = 0.0;
    r->event_counter = 0;
    r->resource_identifier = ' ';
}

void init_data_point(struct data_point *dp) {
    dp->timestamp_offset = 0;
    dp->weight = 0.0;
}

// Linked list implementation for managing records
struct record_list {
    struct record *head;
    struct record *tail;
};

void init_record_list(struct record_list *rl) {
    rl->head = NULL;
    rl->tail = NULL;
}

void insert_record(struct record_list *rl, struct record *r) {
    if (rl->head == NULL) {
        rl->head = r;
        rl->tail = r;
    } else {
        rl->tail->next = r;
        rl->tail = r;
    }
}

void delete_record(struct record_list *rl, struct record *r) {
    if (rl->head == r) {
        rl->head = r->next;
    } else {
        struct record *tmp = rl->head;
        while (tmp != NULL && tmp->next != r) {
            tmp = tmp->next;
        }
        if (tmp != NULL) {
            tmp->next = r->next;
        }
    }
}

// Memory pool implementation for managing record structures
struct memory_pool {
    struct record *head;
    size_t capacity;
};

void init_memory_pool(struct memory_pool *mp, size_t capacity) {
    mp->head = NULL;
    mp->capacity = capacity;
}

struct record *allocate_record(struct memory_pool *mp) {
    if (mp->head == NULL) {
        return NULL;
    } else {
        struct record *r = mp->head;
        mp->head = r->next;
        return r;
    }
}

void deallocate_record(struct memory_pool *mp, struct record *r) {
    if (mp->head == NULL) {
        mp->head = r;
    } else {
        struct record *tmp = mp->head;
        while (tmp != NULL && tmp->next != NULL) {
            tmp = tmp->next;
        }
        tmp->next = r;
    }
}

// Function for processing and aggregating data
void processAndAggregateData(char *resource_directory, struct record_list *rl, struct memory_pool *mp) {
    // Validate the directory path to ensure it points to a valid directory with metric files meeting a minimum size requirement
    if (validate_directory(resource_directory)) {
        printf("Invalid directory path\n");
        return;
    }

    // Process each metric file in the specified resource directory
    struct record *r = NULL;
    for (int i = 0; i < get_num_files(resource_directory); i++) {
        char *file_path = get_file_path(resource_directory, i);
        if (validate_file(file_path)) {
            printf("Invalid file path\n");
            continue;
        }

        // Initialize a new record structure for each metric file
        r = allocate_record(mp);
        init_record(r);

        // Process the contents of each metric file to categorize event occurrences based on predefined ranges
        struct data_point *dp = NULL;
        for (int j = 0; j < get_num_data_points(file_path); j++) {
            dp = allocate_data_point(mp);
            init_data_point(dp);

            // Read the timestamp and weight from the data point
            read_timestamp_and_weight(file_path, j, &dp->timestamp_offset, &dp->weight);

            // Insert the data point into the record structure
            insert_data_point(r, dp);
        }

        // Insert the record structure into the linked list for efficient insertion and deletion of individual records
        insert_record(rl, r);
    }
}

// Custom functions for managing memory and resources
void validate_directory(char *path) {
    struct stat sb;
    if (stat(path, &sb) == 0 && S_ISDIR(sb.st_mode)) {
        return 1;
    } else {
        return 0;
    }
}

void validate_file(char *path) {
    struct stat sb;
    if (stat(path, &sb) == 0 && S_ISREG(sb.st_mode)) {
        return 1;
    } else {
        return 0;
    }
}

int get_num_files(char *path) {
    int num_files = 0;
    DIR *dir = opendir(path);
    if (dir != NULL) {
        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL) {
            if (strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
                num_files++;
            }
        }
    }
    return num_files;
}

char *get_file_path(char *directory, int index) {
    char *file_path = malloc(strlen(directory) + strlen("/") + 10);
    sprintf(file_path, "%s/%d", directory, index);
    return file_path;
}

int get_num_data_points(char *file_path) {
    int num_data_points = 0;
    FILE *fp = fopen(file_path, "r");
    if (fp != NULL) {
        while (!feof(fp)) {
            char line[1024];
            fgets(line, 1024, fp);
            num_data_points++;
        }
    }
    return num_data_points;
}

void read_timestamp_and_weight(char *file_path, int index, unsigned long *timestamp_offset, float *weight) {
    FILE *fp = fopen(file_path, "r");
    if (fp != NULL) {
        char line[1024];
        for (int i = 0; i < index; i++) {
            fgets(line, 1024, fp);
        }
        sscanf(line, "%lu %f", timestamp_offset, weight);
    }
}

struct data_point *allocate_data_point(struct memory_pool *mp) {
    if (mp->head == NULL) {
        return NULL;
    } else {
        struct data_point *dp = mp->head;
        mp->head = dp->next;
        return dp;
    }
}

void deallocate_data_point(struct memory_pool *mp, struct data_point *dp) {
    if (mp->head == NULL) {
        mp->head = dp;
    } else {
        struct data_point *tmp = mp->head;
        while (tmp != NULL && tmp->next != NULL) {
            tmp = tmp->next;
        }
        tmp->next = dp;
    }
}
