    // Set the affected entries in the log entry to the thread index and the entry index
    new_entry->affected_entries[0] = thread_idx;
    new_entry->affected_entries[1] = entry_idx;

    // Add the new log entry to the logging system
    ds->logging.entries[ds->logging.num_entries++] = new_entry;
}

// Compress the data structure by reducing its memory usage by up to 50% while maintaining access times within an acceptable range
void compress(struct concurrent_data_structure* ds) {
    // If the data structure is already compressed, return
    if (ds->compressed) {
        return;
    }

    // Set the flag indicating that the data structure has been compressed
    ds->compressed = true;

    // Iterate over all entries in the data structure
    for (size_t i = 0; i < ds->num_entries; i++) {
        // If the entry is not found, return an error
        if (ds->entries[i].key == -1) {
            return ERROR;
        }

        // Get the current value of the entry
        float value = ds->entries[i].value;

        // If the value is not a valid number, return an error
        if (!is_valid_number(value)) {
            return ERROR;
        }

        // Set the new value of the entry to the compressed value
        ds->entries[i].value = compress_value(value);
    }
}

// Decompress the data structure by increasing its memory usage while maintaining access times within an acceptable range
void decompress(struct concurrent_data_structure* ds) {
    // If the data structure is already decompressed, return
    if (!ds->compressed) {
        return;
    }

    // Set the flag indicating that the data structure has been decompressed
    ds->compressed = false;

    // Iterate over all entries in the data structure
    for (size_t i = 0; i < ds->num_entries; i++) {
        // If the entry is not found, return an error
        if (ds->entries[i].key == -1) {
