        }

        // Get the current value of the entry
        float value = ds->entries[i].value;

        // If the value is not a valid number, return an error
        if (!is_valid_number(value)) {
            return ERROR;
        }

        // Set the new value of the entry to the decompressed value
        ds->entries[i].value = decompress_value(value);
    }
}
