from concurrent.futures import ThreadPoolExecutor

# Define a function to calculate the MD5 hash of a file
def md5_hash(filepath):
    # Open the file and read its contents
    with open(filepath, "rb") as f:
        data = f.read()
    # Calculate the MD5 hash of the file's contents
    return hashlib.md5(data).hexdigest()

# Define a function to calculate the MD5 hashes of multiple files concurrently
def md5_hashes(filepaths, chunk_size=1024*1024):
    # Create a thread pool with the maximum number of parallel threads or processes
    with ThreadPoolExecutor(max_workers=len(filepaths)) as executor:
        # Submit tasks to calculate the MD5 hashes of each file in parallel
        futures = [executor.submit(md5_hash, filepath) for filepath in filepaths]
        # Wait for all tasks to complete and return their results
        return [future.result() for future in futures]

# Define a function to calculate the MD5 hashes of multiple files sequentially
def md5_hashes_sequential(filepaths, chunk_size=1024*1024):
    # Initialize an empty list to store the MD5 hashes
    hashes = []
    # Iterate over each file path
    for filepath in filepaths:
        # Calculate the MD5 hash of the file's contents
        hash = md5_hash(filepath)
        # Add the hash to the list of hashes
        hashes.append(hash)
    return hashes

# Define a function to calculate the MD5 hashes of multiple files with progress indication and monitoring
def md5_hashes_progress(filepaths, chunk_size=1024*1024):
    # Initialize an empty list to store the MD5 hashes
    hashes = []
    # Iterate over each file path
    for filepath in filepaths:
        # Calculate the MD5 hash of the file's contents
        hash = md5_hash(filepath)
        # Add the hash to the list of hashes
        hashes.append(hash)
        # Print a progress indicator and update the monitoring system
        print("Calculated MD5 hash for %s" % filepath)
    return hashes

# Define a function to upload files to a cloud storage service
