void add_record(record_list_t* list, record_t* record) {
    // Check if the linked list is empty and initialize it if necessary
    if (list->head == NULL) {
        list->head = record;
        list->tail = record;
    } else {
        // Add the record to the end of the linked list
        list->tail->next = record;
        list->tail = record;
    }
}

// Define a function to remove a record from the linked list
void remove_record(record_list_t* list, record_t* record) {
    // Check if the linked list is empty and return if it is
    if (list->head == NULL) {
        return;
    }

    // Remove the record from the linked list
    if (list->head == record) {
        list->head = record->next;
    } else {
        record_t* current = list->head;
        while (current != NULL && current->next != record) {
            current = current->next;
        }
        if (current != NULL) {
            current->next = record->next;
        }
    }
}

// Define a function to process and aggregate data from a specified resource directory
void process_and_aggregate_data(record_pool_t* pool, record_list_t* list, const char* resource_directory) {
    // Check if the resource directory is valid and return if it is not
    if (resource_directory == NULL || strlen(resource_directory) == 0) {
        return;
    }

    // Open the resource directory and iterate over its contents
    DIR* dir = opendir(resource_directory);
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        // Check if the file is a metric file and process it if it is
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
