        // Process the contents of the metric file to categorize event occurrences based on predefined ranges
        while (!feof(file)) {
            // Read a line from the file and parse it into a record structure
            char* line = (char*)malloc(1024 * sizeof(char));
            fgets(line, 1024, file);
            record_t* record = (record_t*)dynamic_array_alloc(sizeof(record_t));
            if (record == NULL) {
                continue;
            }

            // Parse the record structure from the line and add it to the linked list
            parse_record(line, record);
            add_record(list, record);
        }

        // Close the metric file and free its resources
        fclose(file);
    }

    // Iterate over the records in the linked list and process them
    record_t* current = list->head;
    while (current != NULL) {
        // Process the record and add it to the memory pool if necessary
        process_record(pool, current);

        // Remove the record from the linked list and free its resources
        remove_record(list, current);
        dynamic_array_free(current);

        // Move on to the next record in the linked list
        current = current->next;
    }
}

// Define a function to process a single record and add it to the memory pool if necessary
void process_record(record_pool_t* pool, record_t* record) {
    // Check if the record is already stored in the memory pool and return if it is
    for (size_t i = 0; i < pool->count; i++) {
        if (pool->records[i].key == record->key && pool->records[i].value == record->value) {
            return;
        }
    }

    // Add the record to the memory pool and update its count
    pool->records[pool->count] = *record;
    pool->count++;

    // Check if the memory pool needs to be resized and resize it if necessary
    if (pool->count == pool->capacity) {
        resize_records(pool, pool->capacity * 2);
    }
}

// Define a function to parse a record structure from a line of text
void parse_record(const char* line, record_t* record) {
    // Parse the key and value from the line
    sscanf(line, "%d %d", &record->key, &record->value);

    // Set the status to "A" (active) by default
    record->status = 'A';

    // Set the timestamp to the current time by default
    record->timestamp = time(NULL);

    // Set the metric threshold and event counter to 0 by default
    record->metric_threshold = 0;
    record->event_counter = 0;

    // Set the resource identifier to "N/A" by default
    record->resource_identifier = 'N';
}
