typedef struct {
    config_t *configs;
    size_t num_configs;
    pthread_mutex_t mutex;
} config_system_t;

// Initialize the configuration system with default values from a JSON file
int init_config_system(const char *json_file, config_system_t *sys) {
    // Load the JSON file and parse it into a json_object
    json_object *obj = json_object_from_file(json_file);
    if (!obj) {
        fprintf(stderr, "Failed to load JSON file: %s\n", json_file);
        return -1;
    }

    // Iterate over the JSON object and add each key-value pair to the configuration system
    size_t i = 0;
    json_object_object_foreach(obj, key, val) {
        config_t *config = malloc(sizeof(config_t));
        if (!config) {
            fprintf(stderr, "Failed to allocate memory for configuration: %s\n", key);
            return -1;
        }
        config->key = strdup(key);
        switch (json_object_get_type(val)) {
            case json_type_int:
                config->value = malloc(sizeof(int));
                if (!config->value) {
                    fprintf(stderr, "Failed to allocate memory for integer value: %s\n", key);
                    return -1;
                }
                *(int *)config->value = json_object_get_int(val);
                break;
            case json_type_double:
                config->value = malloc(sizeof(double));
                if (!config->value) {
                    fprintf(stderr, "Failed to allocate memory for double value: %s\n", key);
                    return -1;
                }
                *(double *)config->value = json_object_get_double(val);
                break;
            case json_type_boolean:
                config->value = malloc(sizeof(bool));
                if (!config->value) {
                    fprintf(stderr, "Failed to allocate memory for boolean value: %s\n", key);
                    return -1;
                }
                *(bool *)config->value = json_object_get_boolean(val);
                break;
            default:
                fprintf(stderr, "Unsupported JSON type for configuration: %s\n", key);
                return -1;
        }
        sys->configs[i++] = config;
    }
    sys->num_configs = i;

    // Clean up the JSON object
    json_object_put(obj);

    // Initialize the mutex for thread safety
    pthread_mutex_init(&sys->mutex, NULL);

    return 0;
}

// Get a configuration value by key
void *get_config(const char *key, config_system_t *sys) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&sys->mutex);

