    size_t i = 0;
    while (i < sys->num_configs) {
        if (!strcmp(sys->configs[i]->key, key)) {
            break;
        }
        i++;
    }

    // Update the value and release the mutex
    sys->configs[i]->value = value;
    pthread_mutex_unlock(&sys->mutex);

    return 0;
}

