        }
        i++;
    }

    // Check if the password is empty or NULL and release the mutex
    int result = 0;
    if (sys->configs[i]->value == NULL || *(char **)sys->configs[i]->value == NULL) {
        result = -1;
    }
    pthread_mutex_unlock(&sys->mutex);

    return result;
}

// Check if a connection has a title set
int check_connection(const char *title, config_system_t *sys) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&sys->mutex);

    // Iterate over the configuration system and find the matching key
    size_t i = 0;
    while (i < sys->num_configs) {
        if (!strcmp(sys->configs[i]->key, "connection")) {
            break;
        }
        i++;
    }

    // Check if the connection has a title set and release the mutex
    int result = 0;
    if (sys->configs[i]->value == NULL || ((connection_t *)sys->configs[i]->value)->title == NULL) {
        result = -1;
    }
    pthread_mutex_unlock(&sys->mutex);

    return result;
}

// Check if a callback function is not NULL
int check_callback(callback_func func, config_system_t *sys) {
    // Acquire the mutex for thread safety
