        return;
    }

    // Allocate memory for the keys array
    int* keys_ptr = (int*)malloc(num_records * sizeof(int));
    if (!keys_ptr) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(offsets_ptr);
        return;
    }

    // Allocate memory for the records array
    record** records_ptr = (record**)malloc(num_records * sizeof(record*));
    if (!records_ptr) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(offsets_ptr);
        free(keys_ptr);
        return;
    }

    // Initialize the offsets array with random values within a specified range
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        offsets_ptr[i] = rand() % 100 + 1; // Random value between 1 and 100
    }

    // Initialize the keys array with random values within a specified range
    for (size_t i = 0; i < num_records; ++i) {
        keys_ptr[i] = rand() % 10 + 1; // Random value between 1 and 10
    }

    // Initialize the records array with random values within a specified range
    for (size_t i = 0; i < num_records; ++i) {
        record* current_record = (record*)malloc(sizeof(record));
        if (!current_record) {
            fprintf(stderr, "Failed to allocate memory for record %zu\n", i);
            free(offsets_ptr);
            free(keys_ptr);
            free(records_ptr);
            return;
        }
        current_record->value = rand() % 100 + 1; // Random value between 1 and 100
        records_ptr[i] = current_record;
    }

    // Set the output parameters to the allocated memory
    *offsets = offsets_ptr;
    *keys = keys_ptr;
    *records = records_ptr;
}
