void init_sensor_data(struct sensor_data **data, struct sensor_location **locations, int num_entries) {
    // Allocate memory for arrays of sensor data and locations
    *data = (struct sensor_data *)malloc(num_entries * sizeof(struct sensor_data));
    *locations = (struct sensor_location *)malloc(num_entries * sizeof(struct sensor_location));

    // Initialize arrays with random values within given range
    for (int i = 0; i < num_entries; i++) {
        (*data)[i].temperature = rand_range(-60, 60) / 10.0;
        (*data)[i].index = rand() % 50000;
        (*data)[i].location = (char *)malloc(20 * sizeof(char));
        sprintf((*data)[i].location, "Location %d", i);
