        (*data)[i].timestamp = time(NULL) + rand() % (60 * 60 * 24 * 365);
        (*data)[i].type = rand() % 2;
        (*locations)[i].geo_id = i;
        (*locations)[i].altitude = rand_range(10, 100) / 10.0;
    }
}

// Define function to group sensor data by location and calculate metrics
void group_sensor_data(struct sensor_data *data, int num_entries) {
    // Initialize variables for grouping and metric calculation
    struct sensor_location *locations = (struct sensor_location *)malloc(num_entries * sizeof(struct sensor_location));
    float avg_temperature = 0.0;
    double avg_humidity = 0.0;
    uint64_t avg_timestamp = 0;
    int num_unique_sensors = 0;
    int max_temperature = -1000000;
    int min_temperature = 1000000;
    double max_humidity = -1.0;
    double min_humidity = 1.0;
    uint64_t max_timestamp = 0;
    uint64_t min_timestamp = UINT64_MAX;
    int num_records = 0;
    float stddev_temperature = 0.0;
    double stddev_humidity = 0.0;
    float weighted_avg_accuracy = 0.0;

    // Loop through each entry in the data array and group by location
    for (int i = 0; i < num_entries; i++) {
        int j = 0;
        while (j < num_unique_sensors && strcmp(locations[j].location, data[i].location) != 0) {
            j++;
        }

        // If location is new, add to locations array and calculate metrics
        if (j == num_unique_sensors) {
            locations[num_unique_sensors] = data[i].location_info;
            avg_temperature += data[i].temperature;
            avg_humidity += data[i].humidity;
            avg_timestamp += data[i].timestamp;
            num_records++;
            if (data[i].temperature > max_temperature) {
                max_temperature = data[i].temperature;
            }
            if (data[i].temperature < min_temperature) {
                min_temperature = data[i].temperature;
            }
            if (data[i].humidity > max_humidity) {
                max_humidity = data[i].humidity;
            }
            if (data[i].humidity < min_humidity) {
                min_humidity = data[i].humidity;
            }
            if (data[i].timestamp > max_timestamp) {
                max_timestamp = data[i].timestamp;
            }
            if (data[i].timestamp < min_timestamp) {
                min_timestamp = data[i].timestamp;
            }
            num_unique_sensors++;
        }
    }

    // Calculate metrics for each group
    for (int i = 0; i < num_unique_sensors; i++) {
        avg_temperature /= num_records;
        avg_humidity /= num_records;
        avg_timestamp /= num_records;
        stddev_temperature = sqrt(pow((avg_temperature - data[i].temperature), 2) / (num_records - 1));
        stddev_humidity = sqrt(pow((avg_humidity - data[i].humidity), 2) / (num_records - 1));
        weighted_avg_accuracy += data[i].type * data[i].location_info.altitude;
    }

    // Print results for each group
    printf("Group: %s\n", locations[0].location);
    printf("Average temperature: %.2f\n", avg_temperature);
    printf("Standard deviation of temperature: %.2f\n", stddev_temperature);
    printf("Maximum temperature: %.2f\n", max_temperature);
    printf("Minimum temperature: %.2f\n", min_temperature);
    printf("Average humidity: %.2f\n", avg_humidity);
    printf("Standard deviation of humidity: %.2f\n", stddev_humidity);
    printf("Maximum humidity: %.2f\n", max_humidity);
    printf("Minimum humidity: %.2f\n", min_humidity);
    printf("Average timestamp: %" PRIu64 "\n", avg_timestamp);
    printf("Maximum timestamp: %" PRIu64 "\n", max_timestamp);
    printf("Minimum timestamp: %" PRIu64 "\n", min_timestamp);
    printf("Number of unique sensors: %d\n", num_unique_sensors);
    printf("Weighted average accuracy: %.2f\n", weighted_avg_accuracy / num_records);
}

int main() {
    // Define input parameters and allocate memory for arrays
    int num_entries = 5000;
    struct sensor_data *data;
    struct sensor_location *locations;
    init_sensor_data(&data, &locations, num_entries);

    // Group sensor data by location and calculate metrics
    group_sensor_data(data, num_entries);

    return 0;
}
