        avg_humidity[i] = 0.0f;
        avg_sensor_accuracy[i] = 0.0f;
    }
    for (int i = 0; i < ds->num_entries; i++) {
        int group_index = ds->key_array[i] % num_groups;
        avg_temperature[group_index] += ds->entry_array[i].value;
        avg_humidity[group_index] += ds->offset_array[i];
        avg_sensor_accuracy[group_index] += ds->entry_array[i].priority;
    }
    for (int i = 0; i < num_groups; i++) {
        avg_temperature[i] /= ds->num_entries;
        avg_humidity[i] /= ds->num_entries;
        avg_sensor_accuracy[i] /= ds->num_entries;
    }
}

// Define the function to calculate the standard deviation and weighted average of sensor accuracies, determining maximum and minimum values and the number of unique sensors contributing to each group
void calculate_standard_deviation(data_structure_t* ds) {
    // Calculate the standard deviation and weighted average of sensor accuracies for each group
    int num_groups = 10; // Replace with actual number of groups
    float std_dev[num_groups];
    float weighted_avg[num_groups];
    for (int i = 0; i < num_groups; i++) {
        std_dev[i] = 0.0f;
        weighted_avg[i] = 0.0f;
    }
    for (int i = 0; i < ds->num_entries; i++) {
        int group_index = ds->key_array[i] % num_groups;
        std_dev[group_index] += pow(ds->entry_array[i].priority - weighted_avg[group_index], 2);
        weighted_avg[group_index] += ds->entry_array[i].priority * ds->offset_array[i];
    }
    for (int i = 0; i < num_groups; i++) {
        std_dev[i] /= ds->num_entries;
        weighted_avg[i] /= ds->num_entries;
    }
}

// Define the function to remove outdated nodes and optimize for efficient memory management, minimizing lock contention
void cleanup(data_structure_t* ds) {
    // Remove outdated nodes from the data structure
    time_t current_time = time(NULL);
    int num_outdated_nodes = 0;
    for (int i = 0; i < ds->num_entries; i++) {
        if (ds->entry_array[i].timestamp < current_time - 10 * 365 * 24 * 60 * 60) { // 10 years
            num_outdated_nodes++;
        }
    }
    if (num_outdated_nodes > 0) {
        printf("Removing %d outdated nodes\n", num_outdated_nodes);
        for (int i = 0; i < ds->num_entries - num_outdated_nodes; i++) {
            ds->offset_array[i] = ds->offset_array[i + num_outdated_nodes];
            ds->key_array[i] = ds->key_array[i + num_outdated_nodes];
            ds->entry_array[i] = ds->entry_array[i + num_outdated_nodes];
        }
        ds->num_entries -= num_outdated_nodes;
    }
}

// Define the function to compress the data structure when memory usage exceeds a certain threshold, reducing the footprint by up to 50% while maintaining access times
void compress(data_structure_t* ds) {
    // Compress the data structure by half
    int num_compressed_entries = ds->num_entries / 2;
    entry_t* compressed_offset_array = (entry_t*)calloc(num_compressed_entries, sizeof(entry_t));
    entry_t* compressed_key_array = (int*)calloc(num_compressed_entries, sizeof(int));
    entry_t* compressed_entry_array = (entry_t*)calloc(num_compressed_entries, sizeof(entry_t));
    for (int i = 0; i < num_compressed_entries; i++) {
        compressed_offset_array[i] = ds->offset_array[2 * i];
        compressed_key_array[i] = ds->key_array[2 * i];
        compressed_entry_array[i] = ds->entry_array[2 * i];
    }
    free(ds->offset_array);
    free(ds->key_array);
    free(ds->entry_array);
    ds->offset_array = compressed_offset_array;
    ds->key_array = compressed_key_array;
    ds->entry_array = compressed_entry_array;
    ds->num_entries = num_compressed_entries;
}

// Define the function to dynamically resize the data structure when memory usage exceeds a certain threshold, maintaining high throughput under heavy load
void resize(data_structure_t* ds) {
    // Resize the data structure by 50%
    int num_resized_entries = ds->num_entries * 1.5;
    entry_t* resized_offset_array = (entry_t*)calloc(num_resized_entries, sizeof(entry_t));
    entry_t* resized_key_array = (int*)calloc(num_resized_entries, sizeof(int));
    entry_t* resized_entry_array = (entry_t*)calloc(num_resized_entries, sizeof(entry_t));
    for (int i = 0; i < ds->num_entries; i++) {
        resized_offset_array[i] = ds->offset_array[i];
        resized_key_array[i] = ds->key_array[i];
        resized_entry_array[i] = ds->entry_array[i];
    }
    free(ds->offset_array);
    free(ds->key_array);
    free(ds->entry_array);
    ds->offset_array = resized_offset_array;
    ds->key_array = resized_key_array;
    ds->entry_array = resized_entry_array;
    ds->num_entries = num_resized_entries;
}

