#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

// Define the data structures used by the allocator
typedef struct Record {
    int value;
} Record;

typedef struct DynamicMemoryAllocator {
    // Array of long integers
    long* long_array;
    size_t long_array_size;
    size_t long_array_capacity;

    // Array of int keys
    int* int_key_array;
    size_t int_key_array_size;
    size_t int_key_array_capacity;

    // Structures named Record, each containing a single int value
    Record* record_array;
    size_t record_array_size;
    size_t record_array_capacity;

    // Random number generator for both integers and floats
    RandomValueGenerator random_generator;

    // Memory usage statistics tracking
    size_t allocations;
    size_t deallocations;
    size_t current_memory_consumption;
} DynamicMemoryAllocator;

// Initialize the allocator with a given capacity for each data structure
void init_allocator(DynamicMemoryAllocator* allocator, size_t long_array_capacity, size_t int_key_array_capacity, size_t record_array_capacity) {
    // Allocate memory for the arrays
    allocator->long_array = (long*)malloc(sizeof(long) * long_array_capacity);
    allocator->int_key_array = (int*)malloc(sizeof(int) * int_key_array_capacity);
    allocator->record_array = (Record*)malloc(sizeof(Record) * record_array_capacity);

    // Initialize the random number generator
    init_random_generator(&allocator->random_generator);

    // Set the capacity for each data structure
    allocator->long_array_capacity = long_array_capacity;
    allocator->int_key_array_capacity = int_key_array_capacity;
    allocator->record_array_capacity = record_array_capacity;
}

// Resize the arrays to fit a given number of elements
void resize_arrays(DynamicMemoryAllocator* allocator, size_t long_array_size, size_t int_key_array_size, size_t record_array_size) {
    // Reallocate memory for the arrays
    allocator->long_array = (long*)realloc(allocator->long_array, sizeof(long) * long_array_size);
    allocator->int_key_array = (int*)realloc(allocator->int_key_array, sizeof(int) * int_key_array_size);
    allocator->record_array = (Record*)realloc(allocator->record_array, sizeof(Record) * record_array_size);

    // Update the capacity for each data structure
    allocator->long_array_capacity = long_array_size;
    allocator->int_key_array_capacity = int_key_array_size;
    allocator->record_array_capacity = record_array_size;
}

// Populate a given array with random integers within a specified range
void populate_array(DynamicMemoryAllocator* allocator, void* array, size_t size, int min, int max) {
    // Generate random numbers using the random number generator
    for (size_t i = 0; i < size; i++) {
        ((int*)array)[i] = generate_random_integer(&allocator->random_generator, min, max);
    }
}

// Populate a given structure with a random integer within a specified range
void populate_record(DynamicMemoryAllocator* allocator, Record* record, int min, int max) {
    // Generate a random integer using the random number generator
    record->value = generate_random_integer(&allocator->random_generator, min, max);
}

// Allocate memory for a given data structure and populate it with random values
void* allocate(DynamicMemoryAllocator* allocator, size_t size) {
    // Check if the allocation would exceed the capacity of the arrays
    if (size > allocator->long_array_capacity || size > allocator->int_key_array_capacity || size > allocator->record_array_capacity) {
        // Reallocate the arrays to fit the new size
        resize_arrays(allocator, size, size, size);
    }

    // Allocate memory for the data structure
    void* ptr = malloc(size * sizeof(Record));

    // Populate the data structure with random values
    populate_record(allocator, (Record*)ptr, 0, 100);

    // Update the allocation statistics
    allocator->allocations++;
    allocator->current_memory_consumption += size * sizeof(Record);

    return ptr;
}

// Deallocate memory for a given data structure
void deallocate(DynamicMemoryAllocator* allocator, void* ptr) {
    // Update the deallocation statistics
    allocator->deallocations++;
    allocator->current_memory_consumption -= size * sizeof(Record);

    // Free the memory for the data structure
    free(ptr);
}

// Print a report on the current memory usage statistics
void print_memory_usage_report(DynamicMemoryAllocator* allocator) {
    printf("Memory Usage Report\n");
    printf("-------------------\n");
    printf("Allocations: %zu\n", allocator->allocations);
    printf("Deallocations: %zu\n", allocator->deallocations);
    printf("Current Memory Consumption: %zu bytes\n", allocator->current_memory_consumption);
}

// Overload the ToString method for the RandomValueGenerator class to display its state
void to_string(RandomValueGenerator* generator) {
    printf("Random Value Generator State:\n");
    printf("---------------------------\n");
    printf("Seed: %d\n", generator->seed);
    printf("Range: [%d, %d]\n", generator->min_value, generator->max_value);
    printf("Precision: %d\n", generator->precision);
}
