void group_sensor_data(int num_records, sensor_record* records) {
    // Initialize variables for grouping and calculation
    int num_groups = 0;
    float avg_temperature = 0.0f;
    double avg_humidity = 0.0;
    uint64_t avg_timestamp = 0;
    int unique_sensors = 0;
    float stddev_temperature = 0.0f;
    double stddev_humidity = 0.0;
    float min_temperature = FLT_MAX;
    float max_temperature = -FLT_MAX;
    double min_humidity = DBL_MAX;
    double max_humidity = -DBL_MAX;
    uint64_t min_timestamp = UINT64_MAX;
    uint64_t max_timestamp = 0;

    // Iterate over sensor records and group by location name
