        int j = 0;
        while (j < num_groups && strcmp(records[i].location, records[j].location) != 0) {
            j++;
        }
        if (j == num_groups) {
            // New group found
            num_groups++;
            avg_temperature = records[i].temperature;
            avg_humidity = records[i].humidity;
            avg_timestamp = records[i].timestamp;
            unique_sensors = 1;
            stddev_temperature = 0.0f;
            stddev_humidity = 0.0;
            min_temperature = FLT_MAX;
            max_temperature = -FLT_MAX;
            min_humidity = DBL_MAX;
            max_humidity = -DBL_MAX;
            min_timestamp = UINT64_MAX;
            max_timestamp = 0;
        } else {
            // Add record to existing group
            avg_temperature += records[i].temperature;
            avg_humidity += records[i].humidity;
            avg_timestamp += records[i].timestamp;
            unique_sensors++;
            stddev_temperature += powf(records[i].temperature - avg_temperature, 2);
