                min_humidity = records[i].humidity;
            }
            if (records[i].humidity > max_humidity) {
                max_humidity = records[i].humidity;
            }
            if (records[i].timestamp < min_timestamp) {
                min_timestamp = records[i].timestamp;
            }
            if (records[i].timestamp > max_timestamp) {
                max_timestamp = records[i].timestamp;
            }
        }
    }

