    for (int i = 0; i < num_groups; i++) {
        avg_temperature /= unique_sensors;
        stddev_temperature /= unique_sensors - 1;
        stddev_temperature = sqrtf(stddev_temperature);
        avg_humidity /= unique_sensors;
        stddev_humidity /= unique_sensors - 1;
        stddev_humidity = sqrt(stddev_humidity);
    }

    // Print results for each group
    for (int i = 0; i < num_groups; i++) {
        printf("Group %d:\n", i + 1);
        printf("\tAverage temperature: %.2f\n", avg_temperature[i]);
        printf("\tStandard deviation of temperature: %.2f\n", stddev_temperature[i]);
        printf("\tMinimum temperature: %.2f\n", min_temperature[i]);
        printf("\tMaximum temperature: %.2f\n", max_temperature[i]);
