#include "RandomValueGenerator.h"

// Define the maximum size of each array
#define MAX_OFFSETS 1000000
#define MAX_KEYS 1000000
#define MAX_RECORDS 1000000

// Define the structure for a record
typedef struct {
    int value;
} Record;

// Define the memory manager function
void MemoryManager(int numOffsets, int numKeys, int numRecords) {
    // Initialize the random number generator with a custom seed
    RandomValueGenerator rng = RandomValueGenerator_Create(1234);

    // Allocate memory for the arrays
    long *offsets = malloc(numOffsets * sizeof(long));
    int *keys = malloc(numKeys * sizeof(int));
    Record *records = malloc(numRecords * sizeof(Record));

    // Initialize the arrays with random values within a specified range
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = RandomValueGenerator_NextInt(&rng, 1, MAX_OFFSETS);
    }
    for (int i = 0; i < numKeys; i++) {
        keys[i] = RandomValueGenerator_NextInt(&rng, 1, MAX_KEYS);
    }
    for (int i = 0; i < numRecords; i++) {
        records[i].value = RandomValueGenerator_NextInt(&rng, 1, MAX_RECORDS);
    }

    // Free the memory allocated by the random number generator
    RandomValueGenerator_Free(&rng);

    // Print the arrays to stdout
    printf("Offsets: ");
    for (int i = 0; i < numOffsets; i++) {
        printf("%ld ", offsets[i]);
    }
    printf("\n");
    printf("Keys: ");
    for (int i = 0; i < numKeys; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");
    printf("Records: ");
    for (int i = 0; i < numRecords; i++) {
        printf("%d ", records[i].value);
    }
    printf("\n");

    // Free the memory allocated by malloc
    free(offsets);
    free(keys);
    free(records);
}
