using namespace std;

// Define the RandomValueGenerator class
class RandomValueGenerator {
public:
    // Constructor to initialize the generator with a seed value
    RandomValueGenerator(int seed) : seed_(seed) {}

    // Generate a random integer within the specified range (inclusive and exclusive)
    int generateRandomInt(int min, int max) {
        std::uniform_int_distribution<int> distribution(min, max);
        return distribution(seed_);
    }

    // Generate a random float within the specified range (inclusive and exclusive)
    float generateRandomFloat(float min, float max) {
        std::uniform_real_distribution<float> distribution(min, max);
        return distribution(seed_);
    }

    // Set the seed value for the generator
    void setSeed(int seed) {
        seed_ = seed;
    }

    // Get the current state of the generator (range, precision, and seed)
    string getState() {
        return "Range: [" + to_string(min_) + ", " + to_string(max_) + "], Precision: " + to_string(precision_) + ", Seed: " + to_string(seed_);
    }

private:
    // The seed value for the generator
    int seed_;

    // The minimum and maximum values for the random number generation
    int min_, max_;

    // The precision of the generated numbers (number of decimal places)
    int precision_;
};

// Define the DynamicMemoryManager class
class DynamicMemoryManager {
public:
    // Constructor to initialize the memory manager with a specified size and allocation strategy
    DynamicMemoryManager(int size, AllocationStrategy strategy) : size_(size), strategy_(strategy) {}

    // Allocate memory for a variable-size array of long integers representing offsets
    void allocateOffsets(vector<long>& offsets) {
        // Use the specified allocation strategy to allocate memory for the offsets
        switch (strategy_) {
            case AllocationStrategy::FIRST_FIT:
                allocateFirstFit(offsets);
                break;
            case AllocationStrategy::BEST_FIT:
                allocateBestFit(offsets);
                break;
            case AllocationStrategy::WORST_FIT:
                allocateWorstFit(offsets);
                break;
        }
    }

    // Allocate memory for a variable-size array of int keys
    void allocateKeys(vector<int>& keys) {
        // Use the specified allocation strategy to allocate memory for the keys
        switch (strategy_) {
            case AllocationStrategy::FIRST_FIT:
                allocateFirstFit(keys);
                break;
            case AllocationStrategy::BEST_FIT:
                allocateBestFit(keys);
                break;
            case AllocationStrategy::WORST_FIT:
                allocateWorstFit(keys);
                break;
        }
    }

    // Allocate memory for a variable-size array of record structures, each containing a single int value
    void allocateRecords(vector<record>& records) {
        // Use the specified allocation strategy to allocate memory for the records
        switch (strategy_) {
            case AllocationStrategy::FIRST_FIT:
                allocateFirstFit(records);
                break;
            case AllocationStrategy::BEST_FIT:
                allocateBestFit(records);
                break;
            case AllocationStrategy::WORST_FIT:
                allocateWorstFit(records);
                break;
        }
    }

    // Resize the memory allocation for a variable-size array of long integers representing offsets
    void resizeOffsets(vector<long>& offsets, int newSize) {
        // Use the specified allocation strategy to resize the offsets
        switch (strategy_) {
            case AllocationStrategy::FIRST_FIT:
                resizeFirstFit(offsets, newSize);
                break;
            case AllocationStrategy::BEST_FIT:
                resizeBestFit(offsets, newSize);
                break;
            case AllocationStrategy::WORST_FIT:
                resizeWorstFit(offsets, newSize);
                break;
        }
    }

    // Resize the memory allocation for a variable-size array of int keys
    void resizeKeys(vector<int>& keys, int newSize) {
        // Use the specified allocation strategy to resize the keys
        switch (strategy_) {
            case AllocationStrategy::FIRST_FIT:
                resizeFirstFit(keys, newSize);
                break;
            case AllocationStrategy::BEST_FIT:
                resizeBestFit(keys, newSize);
                break;
            case AllocationStrategy::WORST_FIT:
                resizeWorstFit(keys, newSize);
                break;
        }
    }

    // Resize the memory allocation for a variable-size array of record structures, each containing a single int value
    void resizeRecords(vector<record>& records, int newSize) {
        // Use the specified allocation strategy to resize the records
        switch (strategy_) {
            case AllocationStrategy::FIRST_FIT:
                resizeFirstFit(records, newSize);
                break;
            case AllocationStrategy::BEST_FIT:
                resizeBestFit(records, newSize);
                break;
            case AllocationStrategy::WORST_FIT:
                resizeWorstFit(records, newSize);
                break;
        }
    }

    // Overload the ToString method to display the generator's current state (range, precision, and seed)
    string ToString() {
        return "Range: [" + to_string(min_) + ", " + to_string(max_) + "], Precision: " + to_string(precision_) + ", Seed: " + to_string(seed_);
    }

private:
    // The size of the memory allocation
    int size_;

    // The allocation strategy for the memory manager (first-fit, best-fit, or worst-fit)
    AllocationStrategy strategy_;

    // The minimum and maximum values for the random number generation
    int min_, max_;

    // The precision of the generated numbers (number of decimal places)
    int precision_;

    // The seed value for the generator
    int seed_;

    // A mutex to protect the memory allocation from concurrent access
    std::mutex mutex_;

    // A condition variable to signal when a resize operation is complete
    std::condition_variable cv_;

    // A vector of long integers representing offsets
    vector<long> offsets_;

    // A vector of int keys
    vector<int> keys_;

    // A vector of record structures, each containing a single int value
    vector<record> records_;

    // Allocate memory for a variable-size array of long integers representing offsets using the first-fit strategy
    void allocateFirstFit(vector<long>& offsets) {
        // Lock the mutex to protect the memory allocation from concurrent access
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if there is enough memory available for the allocation request
        if (size_ - offsets_.size() < offsets.size()) {
            throw std::runtime_error("Not enough memory available");
        }

        // Allocate memory for the offsets
        offsets = vector<long>(offsets_.begin(), offsets_.end());
    }

    // Allocate memory for a variable-size array of int keys using the first-fit strategy
    void allocateFirstFit(vector<int>& keys) {
        // Lock the mutex to protect the memory allocation from concurrent access
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if there is enough memory available for the allocation request
        if (size_ - keys_.size() < keys.size()) {
            throw std::runtime_error("Not enough memory available");
        }

        // Allocate memory for the keys
        keys = vector<int>(keys_.begin(), keys_.end());
    }

    // Allocate memory for a variable-size array of record structures, each containing a single int value using the first-fit strategy
    void allocateFirstFit(vector<record>& records) {
        // Lock the mutex to protect the memory allocation from concurrent access
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if there is enough memory available for the allocation request
        if (size_ - records_.size() < records.size()) {
            throw std::runtime_error("Not enough memory available");
        }

        // Allocate memory for the records
        records = vector<record>(records_.begin(), records_.end());
    }

    // Resize the memory allocation for a variable-size array of long integers representing offsets using the first-fit strategy
    void resizeFirstFit(vector<long>& offsets, int newSize) {
        // Lock the mutex to protect the memory allocation from concurrent access
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if there is enough memory available for the resizing request
        if (size_ - offsets_.size() < newSize) {
            throw std::runtime_error("Not enough memory available");
        }

        // Resize the offsets vector
        offsets = vector<long>(offsets_.begin(), offsets_.end());
    }

    // Resize the memory allocation for a variable-size array of int keys using the first-fit strategy
    void resizeFirstFit(vector<int>& keys, int newSize) {
        // Lock the mutex to protect the memory allocation from concurrent access
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if there is enough memory available for the resizing request
        if (size_ - keys_.size() < newSize) {
            throw std::runtime_error("Not enough memory available");
        }

        // Resize the keys vector
        keys = vector<int>(keys_.begin(), keys_.end());
    }

    // Resize the memory allocation for a variable-size array of record structures, each containing a single int value using the first-fit strategy
    void resizeFirstFit(vector<record>& records, int newSize) {
        // Lock the mutex to protect the memory allocation from concurrent access
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if there is enough memory available for the resizing request
        if (size_ - records_.size() < newSize) {
            throw std::runtime_error("Not enough memory available");
        }

        // Resize the records vector
        records = vector<record>(records_.begin(), records_.end());
    }
};

// Define the AllocationStrategy enum to represent the different allocation strategies (first-fit, best-fit, or worst-fit)
enum class AllocationStrategy {
    FIRST_FIT,
    BEST_FIT,
    WORST_FIT
};

// Define the record structure to represent a single int value
struct record {
    int value;
};

int main() {
    // Initialize the random number generator with a seed value
    RandomValueGenerator generator(1234);

    // Set the range and precision for the generated numbers
    generator.setRange(0, 100);
    generator.setPrecision(2);

    // Initialize the memory manager with a specified size and allocation strategy
    DynamicMemoryManager manager(1000, AllocationStrategy::FIRST_FIT);

    // Allocate memory for a variable-size array of long integers representing offsets
    vector<long> offsets;
    manager.allocateOffsets(offsets);

    // Allocate memory for a variable-size array of int keys
    vector<int> keys;
    manager.allocateKeys(keys);

    // Allocate memory for a variable-size array of record structures, each containing a single int value
    vector<record> records;
    manager.allocateRecords(records);

    // Resize the memory allocation for a variable-size array of long integers representing offsets
    manager.resizeOffsets(offsets, 200);

    // Resize the memory allocation for a variable-size array of int keys
    manager.resizeKeys(keys, 300);

    // Resize the memory allocation for a variable-size array of record structures, each containing a single int value
    manager.resizeRecords(records, 400);

    // Overload the ToString method to display the generator's current state (range, precision, and seed)
    cout << "Generator State: " << generator.ToString() << endl;

    // Display the memory allocation for the offsets vector
    cout << "Offsets Vector: ";
    for (auto offset : offsets) {
        cout << offset << ", ";
    }
    cout << endl;

    // Display the memory allocation for the keys vector
    cout << "Keys Vector: ";
    for (auto key : keys) {
        cout << key << ", ";
    }
    cout << endl;

    // Display the memory allocation for the records vector
    cout << "Records Vector: ";
    for (auto record : records) {
        cout << record.value << ", ";
    }
    cout << endl;

