// Define data structures and constants
#define MAX_MEMORY 1024 * 1024 * 1024 // 1 GB
#define MIN_ARRAY_SIZE 1000
#define MAX_ARRAY_SIZE 50000
#define METRIC_FILE_MIN_SIZE 1000
#define EVENT_CATEGORIZATION_CRITERIA "event_categorization_criteria"

// Define data structures
typedef struct {
    long offset;
    int key;
    record value;
    char status;
    double timestamp;
    double metric_threshold;
    int event_counter;
    char resource_identifier;
} data_point;

typedef struct {
    unsigned long timestamp_offset;
    float weight;
} record;

// Define functions
void processAndAggregateData(char* directory_path) {
    // Initialize memory pool for custom allocation and deallocation of records
    void* memory_pool = malloc(MAX_MEMORY);
    if (memory_pool == NULL) {
        printf("Error: Failed to allocate memory pool\n");
        return;
    }

    // Initialize arrays for data structures
    int array_size = MIN_ARRAY_SIZE;
    long* offset_array = malloc(sizeof(long) * array_size);
    int* key_array = malloc(sizeof(int) * array_size);
    record* value_array = malloc(sizeof(record) * array_size);
    char* status_array = malloc(sizeof(char) * array_size);
    double* timestamp_array = malloc(sizeof(double) * array_size);
    double* metric_threshold_array = malloc(sizeof(double) * array_size);
    int* event_counter_array = malloc(sizeof(int) * array_size);
    char* resource_identifier_array = malloc(sizeof(char) * array_size);

    // Initialize linked list for records
    record* head = NULL;
    record* tail = NULL;

    // Define variables for data processing and aggregation
    int current_index = 0;
    long offset = 0;
    int key = 0;
    record value;
    char status = ' ';
    double timestamp = 0.0;
    double metric_threshold = 0.0;
    int event_counter = 0;
    char resource_identifier = ' ';

    // Define variables for memory management and logging
    int memory_usage = 0;
    int log_file = -1;

    // Open log file for writing
    if ((log_file = open("processAndAggregateData.log", O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR)) == -1) {
        printf("Error: Failed to open log file\n");
        return;
    }

    // Process and aggregate data from metric files in the specified directory
    DIR* dir = opendir(directory_path);
    if (dir == NULL) {
        printf("Error: Failed to open directory %s\n", directory_path);
        return;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip non-metric files and files with insufficient size
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0 || entry->d_type != DT_REG || entry->d_namlen < METRIC_FILE_MIN_SIZE) {
            continue;
        }

        // Open metric file for reading
        FILE* file = fopen(entry->d_name, "r");
        if (file == NULL) {
            printf("Error: Failed to open metric file %s\n", entry->d_name);
            continue;
        }

        // Process contents of metric file
        while ((fscanf(file, "%ld%d%lf%c%d%lf%c%s", &offset, &key, &value.weight, &status, &event_counter, &timestamp, &metric_threshold, &resource_identifier)) == 8) {
            // Check for memory allocation failures and handle accordingly
            if (memory_usage + sizeof(record) > MAX_MEMORY) {
                printf("Error: Memory allocation failure\n");
                break;
            }

            // Allocate record from memory pool
            record* new_record = malloc(sizeof(record));
            if (new_record == NULL) {
                printf("Error: Failed to allocate record from memory pool\n");
                break;
            }

            // Initialize record fields and add to linked list
            new_record->offset = offset;
            new_record->key = key;
            new_record->value.weight = value.weight;
            new_record->status = status;
            new_record->timestamp = timestamp;
            new_record->metric_threshold = metric_threshold;
            new_record->event_counter = event_counter;
            new_record->resource_identifier = resource_identifier;
            if (head == NULL) {
                head = tail = new_record;
            } else {
                tail->next = new_record;
                tail = new_record;
            }

            // Update memory usage and array sizes as needed
            memory_usage += sizeof(record);
            if (current_index == array_size) {
                array_size *= 2;
                offset_array = realloc(offset_array, sizeof(long) * array_size);
                key_array = realloc(key_array, sizeof(int) * array_size);
                value_array = realloc(value_array, sizeof(record) * array_size);
                status_array = realloc(status_array, sizeof(char) * array_size);
                timestamp_array = realloc(timestamp_array, sizeof(double) * array_size);
                metric_threshold_array = realloc(metric_threshold_array, sizeof(double) * array_size);
                event_counter_array = realloc(event_counter_array, sizeof(int) * array_size);
                resource_identifier_array = realloc(resource_identifier_array, sizeof(char) * array_size);
            }
            offset_array[current_index] = offset;
            key_array[current_index] = key;
            value_array[current_index] = value;
            status_array[current_index] = status;
            timestamp_array[current_index] = timestamp;
            metric_threshold_array[current_index] = metric_threshold;
            event_counter_array[current_index] = event_counter;
            resource_identifier_array[current_index] = resource_identifier;
            current_index++;
        }

        // Close metric file and handle errors
        if (fclose(file) == EOF) {
            printf("Error: Failed to close metric file %s\n", entry->d_name);
        }
    }

    // Close directory and handle errors
    if (closedir(dir) == -1) {
        printf("Error: Failed to close directory %s\n", directory_path);
    }

    // Log all operations and handle errors
    for (int i = 0; i < current_index; i++) {
        fprintf(log_file, "%ld %d %f %c %d %f %f %c\n", offset_array[i], key_array[i], value_array[i].weight, status_array[i], event_counter_array[i], timestamp_array[i], metric_threshold_array[i], resource_identifier_array[i]);
        if (fprintf(log_file, "%ld %d %f %c %d %f %f %c\n", offset_array[i], key_array[i], value_array[i].weight, status_array[i], event_counter_array[i], timestamp_array[i], metric_threshold_array[i], resource_identifier_array[i]) < 0) {
            printf("Error: Failed to log operation\n");
        }
    }
    if (fclose(log_file) == EOF) {
        printf("Error: Failed to close log file\n");
    }

    // Clean up memory pool and arrays
    free(memory_pool);
    free(offset_array);
    free(key_array);
    free(value_array);
    free(status_array);
    free(timestamp_array);
    free(metric_threshold_array);
    free(event_counter_array);
    free(resource_identifier_array);
}
