// Define the functions for managing the concurrent data structure
void initialize_entries(ConcurrentDataStructure* ds, size_t num_nodes) {
    // Allocate memory for the nodes and initialize them with random values
    Node* nodes = (Node*)malloc(num_nodes * sizeof(Node));
    if (!nodes) {
