    ds->num_nodes = num_nodes;
    ds->nodes = nodes;
}

void update_node(ConcurrentDataStructure* ds, size_t index, int value, unsigned char priority) {
    // Acquire the mutex to prevent race conditions
    pthread_mutex_lock(&ds->mutex);

    // Update the node with the new value and priority
    Node* node = &ds->nodes[index];
    node->value = value;
    node->priority = priority;

    // Release the mutex
    pthread_mutex_unlock(&ds->mutex);
}

void retrieve_node(ConcurrentDataStructure* ds, size_t index) {
    // Acquire the mutex to prevent race conditions
    pthread_mutex_lock(&ds->mutex);

    // Retrieve the node with the given index
    Node* node = &ds->nodes[index];

    // Release the mutex
    pthread_mutex_unlock(&ds->mutex);
}

void cleanup(ConcurrentDataStructure* ds) {
    // Acquire the mutex to prevent race conditions
    pthread_mutex_lock(&ds->mutex);

    // Remove nodes older than a specified age threshold
    for (size_t i = 0; i < ds->num_nodes; i++) {
        Node* node = &ds->nodes[i];
        if (node->timestamp < time(NULL) - AGE_THRESHOLD) {
            // Remove the node from the data structure
            for (size_t j = i; j < ds->num_nodes - 1; j++) {
                ds->nodes[j] = ds->nodes[j + 1];
            }
            ds->num_nodes--;
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&ds->mutex);
}

void validate(ConcurrentDataStructure* ds) {
    // Acquire the mutex to prevent race conditions
    pthread_mutex_lock(&ds->mutex);

    // Validate the consistency of the data structure across all threads
    for (size_t i = 0; i < ds->num_nodes; i++) {
        Node* node1 = &ds->nodes[i];
        for (size_t j = i + 1; j < ds->num_nodes; j++) {
            Node* node2 = &ds->nodes[j];
            if (node1->value == node2->value && node1->priority == node2->priority) {
                // Log the inconsistency and break out of the loop
                printf("Inconsistency detected: value=%d, priority=%d\n", node1->value, node1->priority);
                break;
            }
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&ds->mutex);
}
