    sensor_data->status_indicators = calloc(sizeof(char), m);
    sensor_data->event_logs = calloc(sizeof(int), MAX_LOGS);

    // Set 'alarm status' to false for all elements
    for (int i = 0; i < m; i++) {
        sensor_data->metadata[i].alarm_status = false;
    }
}

// Function to append new events to the event logs, ensuring that the log does not exceed a maximum size defined by a parameter
void append_events(sensor_data_t *sensor_data, int num_events) {
    // Check if the input parameter is valid
    if (num_events < 0) {
        return;
    }

    // Ensure that the event logs do not exceed their maximum size
    if (sensor_data->event_logs[MAX_LOGS - 1] != 0) {
        return;
    }

    // Append new events to the event logs
    for (int i = 0; i < num_events; i++) {
        sensor_data->event_logs[i] = rand() % (max_temp - min_temp) + min_temp;
    }
}
