#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Define the data structures used in the weather station system
typedef struct {
    double temperature;
} TemperatureReading;

typedef struct {
    float wind_speed;
    int precipitation_level;
    bool storm_alert_status;
    char warning_code;
    enum EventType event_type;
} SensorMetadata;

typedef struct {
    char status_message[256];
} StatusMessage;

// Define the error handling mechanism for out-of-memory conditions
#define OUT_OF_MEMORY -1

int weather_station_init(int n, float average_wind_speed, int average_precipitation_level) {
    // Allocate memory for the temperature readings array
    TemperatureReading *temperatures = (TemperatureReading *)malloc(n * sizeof(TemperatureReading));
    if (!temperatures) {
        printf("Error: Failed to allocate memory for temperature readings\n");
        return OUT_OF_MEMORY;
    }

    // Initialize the temperature readings array with zeros
    memset(temperatures, 0, n * sizeof(TemperatureReading));

    // Allocate memory for the linked list of sensor metadata
    SensorMetadata *sensors = (SensorMetadata *)malloc(n * sizeof(SensorMetadata));
    if (!sensors) {
        printf("Error: Failed to allocate memory for sensor metadata\n");
        free(temperatures);
        return OUT_OF_MEMORY;
    }

    // Initialize the linked list of sensor metadata with default values
    for (int i = 0; i < n; i++) {
        sensors[i].wind_speed = average_wind_speed;
        sensors[i].precipitation_level = average_precipitation_level;
        sensors[i].storm_alert_status = false;
        sensors[i].warning_code = ' ';
        sensors[i].event_type = NORMAL_OPERATION;
    }

    // Allocate memory for the ring buffer of status messages
    StatusMessage *status_messages = (StatusMessage *)malloc(max_buffer_size * sizeof(StatusMessage));
    if (!status_messages) {
        printf("Error: Failed to allocate memory for status messages\n");
        free(temperatures);
        free(sensors);
        return OUT_OF_MEMORY;
    }

    // Initialize the ring buffer of status messages with default values
    memset(status_messages, 0, max_buffer_size * sizeof(StatusMessage));

    // Return a pointer to the weather station system data structure
    WeatherStationSystem *system = (WeatherStationSystem *)malloc(sizeof(WeatherStationSystem));
    if (!system) {
        printf("Error: Failed to allocate memory for weather station system\n");
        free(temperatures);
        free(sensors);
        free(status_messages);
        return OUT_OF_MEMORY;
    }

    // Initialize the weather station system data structure with pointers to the allocated memory
    system->temperatures = temperatures;
    system->sensors = sensors;
    system->status_messages = status_messages;
    system->max_buffer_size = max_buffer_size;

    return 0;
}

// Function to reset the entire weather station system to its initial state
void weather_station_reset(WeatherStationSystem *system) {
    // Free all allocated memory for the temperature readings array
    free(system->temperatures);

    // Free all allocated memory for the linked list of sensor metadata
    free(system->sensors);

    // Free all allocated memory for the ring buffer of status messages
    free(system->status_messages);

    // Reinitialize the temperature readings array with zeros
    memset(system->temperatures, 0, system->max_buffer_size * sizeof(TemperatureReading));

    // Reinitialize the linked list of sensor metadata with default values
    for (int i = 0; i < system->max_buffer_size; i++) {
        system->sensors[i].wind_speed = average_wind_speed;
        system->sensors[i].precipitation_level = average_precipitation_level;
        system->sensors[i].storm_alert_status = false;
        system->sensors[i].warning_code = ' ';
        system->sensors[i].event_type = NORMAL_OPERATION;
    }

    // Reinitialize the ring buffer of status messages with default values
    memset(system->status_messages, 0, system->max_buffer_size * sizeof(StatusMessage));
}

// Function to partially reset the weather station system, resetting only the precipitation level and storm alert status to their initial states
void weather_station_partial_reset(WeatherStationSystem *system) {
    // Reinitialize the linked list of sensor metadata with default values for the precipitation level and storm alert status
    for (int i = 0; i < system->max_buffer_size; i++) {
        system->sensors[i].precipitation_level = average_precipitation_level;
        system->sensors[i].storm_alert_status = false;
    }
}

// Function to enqueue new status messages into the ring buffer, ensuring that the buffer does not exceed a maximum size defined by a parameter
void weather_station_enqueue_status(WeatherStationSystem *system, char *message) {
    // Check if the ring buffer is full
    if (system->status_messages_count >= system->max_buffer_size) {
        // If the ring buffer is full, remove the oldest message from the front of the queue
        free(system->status_messages[0]);
        memmove(system->status_messages, system->status_messages + 1, (system->max_buffer_size - 1) * sizeof(StatusMessage));
        system->status_messages_count--;
    }

    // Allocate memory for the new status message
    StatusMessage *new_message = (StatusMessage *)malloc(sizeof(StatusMessage));
    if (!new_message) {
        printf("Error: Failed to allocate memory for new status message\n");
        return;
    }

    // Copy the contents of the new status message into the ring buffer
    strcpy(new_message->status_message, message);
    system->status_messages[system->status_messages_count] = new_message;
    system->status_messages_count++;
}
