// Define error codes for memory allocation and data integrity issues
#define MEMORY_ALLOCATION_ERROR 1
#define DATA_INTEGRITY_ERROR 2

// Define the maximum size of the hash table
#define MAX_TABLE_SIZE 1000

// Define a struct for sensor metadata
typedef struct {
    float speed_limit;
    int average_speed;
    bool congestion_alert_status;
    char incident_code;
    enum event_type;
