// Define a function to dynamically manage memory for and initialize the simplified traffic monitoring system
int init_traffic_monitoring_system(int n, float speed_limit, bool congestion_alert_status, char incident_code) {
    // Check if the input parameter 'n' is valid
    if (n < 0) {
        return MEMORY_ALLOCATION_ERROR;
    }

    // Allocate memory for the vehicle counts array
    int *vehicle_counts = malloc(sizeof(int) * n);
    if (!vehicle_counts) {
        return MEMORY_ALLOCATION_ERROR;
    }

    // Initialize the vehicle counts array with zeros
    memset(vehicle_counts, 0, sizeof(int) * n);

    // Allocate memory for the linked list of sensor metadata
    sensor_metadata_t *sensor_metadata = malloc(sizeof(sensor_metadata_t) * n);
    if (!sensor_metadata) {
        free(vehicle_counts);
        return MEMORY_ALLOCATION_ERROR;
    }

    // Initialize the linked list of sensor metadata with default values
    for (int i = 0; i < n; i++) {
        sensor_metadata[i].speed_limit = speed_limit;
        sensor_metadata[i].average_speed = 0;
        sensor_metadata[i].congestion_alert_status = congestion_alert_status;
        sensor_metadata[i].incident_code = incident_code;
        sensor_metadata[i].event_type = NORMAL_OPERATION;
    }

    // Allocate memory for the hash table of location codes and their descriptions
    char **location_codes = malloc(sizeof(char *) * MAX_TABLE_SIZE);
    if (!location_codes) {
        free(vehicle_counts);
        free(sensor_metadata);
        return MEMORY_ALLOCATION_ERROR;
    }

    // Initialize the hash table with default values
    for (int i = 0; i < MAX_TABLE_SIZE; i++) {
        location_codes[i] = NULL;
    }

    // Allocate memory for the array of event records
    event_record_t *event_records = malloc(sizeof(event_record_t) * n);
    if (!event_records) {
        free(vehicle_counts);
        free(sensor_metadata);
        free(location_codes);
        return MEMORY_ALLOCATION_ERROR;
    }

    // Initialize the array of event records with default values
    for (int i = 0; i < n; i++) {
        event_records[i].timestamp = 0;
        event_records[i].event_description[0] = '\0';
        event_records[i].impact_level = 0;
    }

    // Return a success code
    return 0;
}

// Define a function to reset the entire system to its initial state
void reset_traffic_monitoring_system() {
    // Free all allocated memory
    free(vehicle_counts);
    free(sensor_metadata);
    free(location_codes);
    free(event_records);

    // Reinitialize the arrays with zeros
    vehicle_counts = malloc(sizeof(int) * n);
    memset(vehicle_counts, 0, sizeof(int) * n);

    sensor_metadata = malloc(sizeof(sensor_metadata_t) * n);
    for (int i = 0; i < n; i++) {
        sensor_metadata[i].speed_limit = speed_limit;
        sensor_metadata[i].average_speed = 0;
        sensor_metadata[i].congestion_alert_status = congestion_alert_status;
        sensor_metadata[i].incident_code = incident_code;
        sensor_metadata[i].event_type = NORMAL_OPERATION;
    }

    location_codes = malloc(sizeof(char *) * MAX_TABLE_SIZE);
    for (int i = 0; i < MAX_TABLE_SIZE; i++) {
        location_codes[i] = NULL;
    }

    event_records = malloc(sizeof(event_record_t) * n);
    for (int i = 0; i < n; i++) {
        event_records[i].timestamp = 0;
        event_records[i].event_description[0] = '\0';
        event_records[i].impact_level = 0;
    }
}

// Define a function to partially reset the system, resetting only the average speed and congestion alert status to their initial states
void partial_reset_traffic_monitoring_system() {
    // Free all allocated memory
    free(vehicle_counts);
    free(sensor_metadata);
    free(location_codes);
    free(event_records);

    // Reinitialize the arrays with zeros
    vehicle_counts = malloc(sizeof(int) * n);
    memset(vehicle_counts, 0, sizeof(int) * n);

    sensor_metadata = malloc(sizeof(sensor_metadata_t) * n);
    for (int i = 0; i < n; i++) {
        sensor_metadata[i].speed_limit = speed_limit;
        sensor_metadata[i].average_speed = 0;
        sensor_metadata[i].congestion_alert_status = congestion_alert_status;
        sensor_metadata[i].incident_code = incident_code;
        sensor_metadata[i].event_type = NORMAL_OPERATION;
    }
}

// Define a function to update the hash table with new location codes and their associated descriptions
void update_location_codes(char **new_location_codes, int num_new_locations) {
    // Check if the input parameter 'num_new_locations' is valid
    if (num_new_locations < 0) {
        return;
    }

    // Allocate memory for the new location codes and their descriptions
    char **new_location_codes = malloc(sizeof(char *) * num_new_locations);
    if (!new_location_codes) {
        return;
    }

    // Initialize the new location codes and their descriptions with default values
    for (int i = 0; i < num_new_locations; i++) {
        new_location_codes[i] = NULL;
    }

    // Update the hash table with the new location codes and their descriptions
    for (int i = 0; i < num_new_locations; i++) {
        if (!new_location_codes[i]) {
            continue;
        }
        char *location_code = strdup(new_location_codes[i]);
        if (!location_code) {
            free(new_location_codes);
            return;
        }
        location_codes[i] = location_code;
    }
}
