typedef struct {
    double *double_array;
    char **char_array;
    int *int_array;
} UserData;

// Define a thread-safe mechanism for handling concurrent access to shared resources
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a persistent storage solution to avoid re-generating usernames in case of application restarts
FILE *user_data_file = NULL;

// Define the function to generate and store user data
void addUser(double double_value, char *username, int user_id) {
    // Lock the mutex to prevent concurrent access to shared resources
    pthread_mutex_lock(&mutex);

    // Check if the username is already taken
    UserData *user_data = NULL;
    while ((user_data = getUserByUsername(username)) != NULL) {
        // If the username is already taken, generate a new one
        char new_username[16];
        sprintf(new_username, "%s%d", username, rand() % 1000);
        username = new_username;
    }

    // Allocate memory for the user data
    UserData *user_data = malloc(sizeof(UserData));
    if (user_data == NULL) {
        printf("Error: Failed to allocate memory for user data\n");
        return;
    }

    // Initialize the user data
    user_data->double_array = malloc(sizeof(double) * 10);
    user_data->char_array = malloc(sizeof(char *) * 10);
    user_data->int_array = malloc(sizeof(int) * 10);
    for (int i = 0; i < 10; i++) {
        user_data->double_array[i] = double_value;
        user_data->char_array[i] = strdup(username);
        user_data->int_array[i] = user_id;
    }

    // Add the user data to the persistent storage solution
    if (user_data_file != NULL) {
        fwrite(user_data, sizeof(UserData), 1, user_data_file);
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Define a function to retrieve user data by username
UserData *getUserByUsername(char *username) {
    // Lock the mutex to prevent concurrent access to shared resources
    pthread_mutex_lock(&mutex);

    // Search for the user data in the persistent storage solution
    UserData *user_data = NULL;
    if (user_data_file != NULL) {
        fseek(user_data_file, 0, SEEK_SET);
        while ((user_data = malloc(sizeof(UserData))) != NULL) {
            fread(user_data, sizeof(UserData), 1, user_data_file);
            if (strcmp(user_data->char_array[0], username) == 0) {
                break;
            }
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
    return user_data;
}

// Define a function to clean up old user data based on a configurable retention policy
void cleanupUserData(int retention_period) {
    // Lock the mutex to prevent concurrent access to shared resources
    pthread_mutex_lock(&mutex);

    // Search for users that are older than the retention period and delete their data
    UserData *user_data = NULL;
    while ((user_data = getUserByUsername("")) != NULL) {
        if (time(NULL) - user_data->int_array[0] > retention_period) {
            free(user_data);
        } else {
            break;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}
