} EventRecord;

// Define functions for the system
int initializeSystem(int n) {
    // Check if input parameter is valid
    if (n < 0) {
        return -1;
    }

    // Allocate memory for the vehicle counts array
    int *vehicleCounts = malloc(sizeof(int) * n);
    if (!vehicleCounts) {
        printf("Error: Failed to allocate memory for vehicle counts\n");
        return -1;
    }

    // Initialize the vehicle counts array with zeros
    memset(vehicleCounts, 0, sizeof(int) * n);

    // Allocate memory for the linked list of sensor metadata
    SensorMetadata *sensorMetadata = malloc(sizeof(SensorMetadata));
    if (!sensorMetadata) {
        printf("Error: Failed to allocate memory for sensor metadata\n");
        free(vehicleCounts);
        return -1;
    }

    // Initialize the linked list of sensor metadata with default values
    sensorMetadata->speedLimit = MIN_SPEED_LIMIT;
    sensorMetadata->averageSpeed = 0;
    sensorMetadata->congestionAlertStatus = false;
    sensorMetadata->incidentCode = INCIDENT_CODE_DEFAULT;
    sensorMetadata->eventType = EVENT_TYPE_NORMAL;

    // Allocate memory for the hash table of location codes and their descriptions
    char **locationCodes = malloc(sizeof(char *) * n);
    if (!locationCodes) {
        printf("Error: Failed to allocate memory for location codes\n");
        free(vehicleCounts);
        free(sensorMetadata);
        return -1;
    }

    // Initialize the hash table with default values
    memset(locationCodes, 0, sizeof(char *) * n);

    // Allocate memory for the array of event records
    EventRecord *eventRecords = malloc(sizeof(EventRecord) * n);
    if (!eventRecords) {
        printf("Error: Failed to allocate memory for event records\n");
        free(vehicleCounts);
        free(sensorMetadata);
        free(locationCodes);
        return -1;
    }

    // Initialize the array of event records with default values
    memset(eventRecords, 0, sizeof(EventRecord) * n);

    // Return success
    return 0;
}

void resetSystem() {
    // Free all allocated memory
    free(vehicleCounts);
    free(sensorMetadata);
    free(locationCodes);
    free(eventRecords);

    // Reinitialize the system with default values
    initializeSystem(MAX_VEHICLE_COUNT);
}

void partialResetSystem() {
    // Reset only the 'int' average speed and 'bool' congestion alert status to their initial states
    sensorMetadata->averageSpeed = 0;
    sensorMetadata->congestionAlertStatus = false;
}

void updateHashTable(char *locationCode, char *description) {
    // Check if the hash table is full
    if (hashTableSize >= max_table_size) {
        printf("Error: Hash table is full\n");
        return;
    }

    // Allocate memory for the new location code and description
    char *newLocationCode = malloc(sizeof(char));
    if (!newLocationCode) {
        printf("Error: Failed to allocate memory for new location code\n");
        return;
    }

    char *newDescription = malloc(sizeof(char) * 256);
    if (!newDescription) {
        printf("Error: Failed to allocate memory for new description\n");
        free(newLocationCode);
        return;
    }

    // Copy the location code and description into the new memory locations
    strcpy(newLocationCode, locationCode);
    strcpy(newDescription, description);

    // Add the new location code and description to the hash table
    locationCodes[hashTableSize] = newLocationCode;
    descriptions[hashTableSize] = newDescription;

    // Increment the hash table size
    hashTableSize++;
}

void updateEventRecords(time_t timestamp, char *eventDescription, int impactLevel) {
    // Check if the event records array is full
    if (eventRecordCount >= MAX_VEHICLE_COUNT) {
        printf("Error: Event records array is full\n");
        return;
    }

    // Allocate memory for the new event record
    EventRecord *newEventRecord = malloc(sizeof(EventRecord));
    if (!newEventRecord) {
        printf("Error: Failed to allocate memory for new event record\n");
        return;
    }

    // Copy the timestamp, description, and impact level into the new event record
    newEventRecord->timestamp = timestamp;
    strcpy(newEventRecord->eventDescription, eventDescription);
    newEventRecord->impactLevel = impactLevel;

    // Add the new event record to the array
    eventRecords[eventRecordCount] = newEventRecord;

    // Increment the event record count
    eventRecordCount++;
}

void deallocateMemory() {
    // Deallocate memory in reverse order
    free(eventRecords);
    free(locationCodes);
    free(sensorMetadata);
    free(vehicleCounts);
}

int main() {
    int n = 10;
    initializeSystem(n);

    // Update the hash table with new location codes and their descriptions
    updateHashTable("A", "Location A");
    updateHashTable("B", "Location B");
    updateHashTable("C", "Location C");

    // Update the event records with new events
    updateEventRecords(time(NULL), "Event 1", 1);
    updateEventRecords(time(NULL), "Event 2", 2);
    updateEventRecords(time(NULL), "Event 3", 3);

    // Reset the system to its initial state
    resetSystem();

    // Partially reset the system, resetting only the 'int' average speed and 'bool' congestion alert status to their initial states
    partialResetSystem();

    // Deallocate memory
    deallocateMemory();

    return 0;
}']

