// Define the custom memory pool manager
struct mem_pool {
    void *memory;
    size_t size;
};

void init_mem_pool(struct mem_pool *pool, size_t size) {
    pool->memory = malloc(size);
    if (pool->memory == NULL) {
        printf("Error: Failed to allocate memory for the custom memory pool\n");
        exit(1);
    }
    pool->size = size;
}

void *allocate_mem(struct mem_pool *pool, size_t size) {
    if (pool->memory + pool->size - pool->memory < size) {
        printf("Error: Insufficient memory available in the custom memory pool\n");
        return NULL;
    }
    void *ptr = pool->memory;
    pool->memory += size;
    return ptr;
}

void free_mem(struct mem_pool *pool, void *ptr) {
    if (ptr < pool->memory || ptr > pool->memory + pool->size - pool->memory) {
        printf("Error: Attempted to free memory outside of the custom memory pool\n");
        return;
    }
    size_t offset = ptr - pool->memory;
    memmove(ptr, ptr + size, pool->size - offset);
}

// Define the function for generating random data points
