    for (int i = 0; i < num_data_points; i++) {
        structs[i].info.f = rand_float(seed);
        structs[i].info.i = rand_int(seed);
    }

    // Implement a custom memory pool manager to optimize memory usage and reduce fragmentation
    for (int i = 0; i < num_data_points; i++) {
        if (rand() % 2 == 0) {
            free_mem(&pool, strings[i]);
            strings[i] = allocate_mem(&pool, sizeof(char) * 10);
        }
    }

    // Implement error handling to ensure that memory allocation fails gracefully if insufficient resources are available
    for (int i = 0; i < num_data_points; i++) {
