// Reset the entire system to its initial state
void reset_traffic_monitoring_system(VehicleCount *vehicle_counts, SensorMetadata *sensor_metadata, LinkedList *sensor_list, HashTable *location_codes, long *offset_values, int *keys, EventRecord *event_records) {
