    for (int i = 0; i < n; i++) {
        vehicle_counts[i].vehicle_count = 0;
        sensor_metadata[i].speed_limit = speed_limit;
        sensor_metadata[i].average_speed = 0;
        sensor_metadata[i].congestion_alert_status = false;
        sensor_metadata[i].incident_code = '\0';
