// Define the entry type
typedef struct {
    key_t key;
    value_t value;
    timestamp_t timestamp;
    priority_level_t priority;
} entry_t;

// Define the data structure to manage entries
typedef struct {
    pthread_mutex_t mutex; // Mutex for thread-safe operations
    int size; // Size of the data structure
    int capacity; // Capacity of the data structure
    entry_t* entries; // Array of entries
} concurrent_data_structure_t;

// Define the function to create a new entry
entry_t create_entry(key_t key, value_t value, priority_level_t priority) {
    entry_t entry = {key, value, 0, priority};
    return entry;
}

// Define the function to update an entry's value and timestamp
void update_entry(concurrent_data_structure_t* data_structure, int index, value_t new_value, timestamp_t new_timestamp) {
    pthread_mutex_lock(&data_structure->mutex);
    data_structure->entries[index].value = new_value;
    data_structure->entries[index].timestamp = new_timestamp;
    pthread_mutex_unlock(&data_structure->mutex);
}

// Define the function to retrieve an entry's index based on its key and value
int get_entry_index(concurrent_data_structure_t* data_structure, key_t key, value_t value) {
    int i;
    for (i = 0; i < data_structure->size; i++) {
        if (data_structure->entries[i].key == key && data_structure->entries[i].value == value) {
            return i;
        }
    }
    return -1; // Return -1 if the entry is not found
}

// Define the function to remove an entry from the data structure based on its index
void remove_entry(concurrent_data_structure_t* data_structure, int index) {
    pthread_mutex_lock(&data_structure->mutex);
    if (index >= 0 && index < data_structure->size) {
        // Shift the remaining entries to fill the gap
        for (int i = index; i < data_structure->size - 1; i++) {
            data_structure->entries[i] = data_structure->entries[i + 1];
        }
        data_structure->size--;
    }
    pthread_mutex_unlock(&data_structure->mutex);
}

// Define the function to add an entry to the data structure
void add_entry(concurrent_data_structure_t* data_structure, key_t key, value_t value, priority_level_t priority) {
    pthread_mutex_lock(&data_structure->mutex);
    if (data_structure->size == data_structure->capacity) {
        // Resize the data structure if it is full
        int new_capacity = data_structure->capacity * 2;
        entry_t* new_entries = realloc(data_structure->entries, sizeof(entry_t) * new_capacity);
        if (new_entries == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&data_structure->mutex);
            return;
        }
        data_structure->entries = new_entries;
        data_structure->capacity = new_capacity;
    }
    entry_t new_entry = create_entry(key, value, priority);
    data_structure->entries[data_structure->size] = new_entry;
    data_structure->size++;
    pthread_mutex_unlock(&data_structure->mutex);
}

// Define the function to retrieve an entry from the data structure based on its index
entry_t get_entry(concurrent_data_structure_t* data_structure, int index) {
    if (index < 0 || index >= data_structure->size) {
        return NULL; // Return NULL if the index is invalid
    }
    return data_structure->entries[index];
}

// Define the function to retrieve all entries from the data structure
entry_t* get_all_entries(concurrent_data_structure_t* data_structure) {
    entry_t* entries = malloc(sizeof(entry_t) * data_structure->size);
    if (entries == NULL) {
        return NULL; // Return NULL if memory allocation fails
    }
    for (int i = 0; i < data_structure->size; i++) {
        entries[i] = get_entry(data_structure, i);
    }
    return entries;
}

// Define the function to clean up old entries based on their age threshold
void cleanup_entries(concurrent_data_structure_t* data_structure, int age_threshold) {
    pthread_mutex_lock(&data_structure->mutex);
    for (int i = 0; i < data_structure->size; i++) {
        if (data_structure->entries[i].timestamp <= age_threshold) {
