            offsets[i] = rand() % 1000;
            keys[i] = rand() % 1000;
            entries[i].value = rand() % 1000;
            entries[i].timestamp = time(NULL) * 1000 + rand() % 1000;
            entries[i].priority = rand() % 1000;
            sprintf(entries[i].location, "Location %d", i);
        }
    }
}
