    struct Record *record;
    struct Node *next;
} Node;

// Define a function to insert a new record into the collection
void insertRecord(struct Record *record) {
    // Create a new node for the record
    Node *newNode = malloc(sizeof(Node));
    newNode->record = record;
    newNode->next = NULL;

    // Check if the list is empty
    if (head == NULL) {
        head = newNode;
        return;
    }

    // Find the last node in the list
    Node *lastNode = head;
    while (lastNode->next != NULL) {
        lastNode = lastNode->next;
    }

    // Insert the new node at the end of the list
    lastNode->next = newNode;
}

// Define a function to retrieve all records within a specified date range
void getRecordsInRange(long startTimestamp, long endTimestamp) {
    // Initialize a variable to keep track of the current node
    Node *currentNode = head;

    // Loop through the list until we reach the end
    while (currentNode != NULL) {
        // Check if the record's timestamp is within the specified range
        if (currentNode->record->timestamp >= startTimestamp && currentNode->record->timestamp <= endTimestamp) {
            printf("%ld: %f\n", currentNode->record->timestamp, currentNode->record->value);
        }

        // Move to the next node in the list
        currentNode = currentNode->next;
    }
}
