struct RecordCollection {
    struct Record* records;
    int num_records;
};

void insertRecord(struct RecordCollection* collection, long timestamp, double value) {
    // Check if the record already exists in the collection
    for (int i = 0; i < collection->num_records; i++) {
        if (collection->records[i].timestamp == timestamp) {
            return;
        }
    }

    // Insert the new record into the collection
    struct Record* new_record = malloc(sizeof(struct Record));
    new_record->timestamp = timestamp;
    new_record->value = value;
    collection->records[collection->num_records++] = *new_record;
}

void retrieveRecords(struct RecordCollection* collection, long start_time, long end_time) {
    // Iterate over the records in the collection and filter out those that are not within the specified date range
    for (int i = 0; i < collection->num_records; i++) {
        if (collection->records[i].timestamp >= start_time && collection->records[i].timestamp <= end_time) {
            printf("%ld %f\n", collection->records[i].timestamp, collection->records[i].value);
        }
    }
}

void generateCertificate(struct RecordCollection* collection, char* oauth_parameters) {
    // Extract the necessary OAuth parameters from the input string
    char* private_key = strtok(oauth_parameters, " ");
