    // Generate a new PEM file containing both the private key and certificate
    char* pem_file = malloc(sizeof(char) * 1024);
    sprintf(pem_file, "%s\n%s", private_key, certificate);

    // Combine the private key and certificate into a single PEM file
    FILE* combined_file = fopen("combined.pem", "w");
