import logging
from collections import deque
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timedelta
from typing import Deque, Dict, List, Optional

import pandas as pd

logger = logging.getLogger(__name__)

class LogProcessor:
    def __init__(self, source_systems: List[str], cache_size: int = 10000):
        self.source_systems = source_systems
        self.cache_size = cache_size
        self.cache: Deque[Dict] = deque(maxlen=self.cache_size)
        self.executor = ThreadPoolExecutor()

    def process_log_entry(self, entry: Dict) -> None:
        system_id = entry["system_id"]
        timestamp = datetime.fromtimestamp(entry["timestamp"])
        if (
            timestamp > datetime.now() - timedelta(hours=24)
            and system_id in self.source_systems
        ):
            self.cache.append(entry)

    def filter_and_sort_log_entries(self, entries: List[Dict]) -> List[Dict]:
        return sorted(entries, key=lambda x: x["timestamp"])

    def identify_most_recent_valid_entry(self, entries: List[Dict]) -> Optional[Dict]:
        valid_entries = [e for e in entries if self.is_valid_log_entry(e)]
        if not valid_entries:
            return None
        most_recent_valid_entry = max(valid_entries, key=lambda x: x["timestamp"])
        return most_recent_valid_entry

    def is_valid_log_entry(self, entry: Dict) -> bool:
        system_id = entry["system_id"]
        timestamp = datetime.fromtimestamp(entry["timestamp"])
        if (
            timestamp > datetime.now() - timedelta(hours=24)
            and system_id in self.source_systems
        ):
            return True
        else:
            return False

    def cache_most_recent_valid_entry(self, entry: Dict) -> None:
        if self.is_valid_log_entry(entry):
            self.cache.append(entry)

    def process_log_entries(self, entries: List[Dict]) -> None:
        filtered_entries = self.filter_and_sort_log_entries(entries)
        most_recent_valid_entry = self.identify_most_recent_valid_entry(filtered_entries)
        if most_recent_valid_entry:
            self.cache_most_recent_valid_entry(most_recent_valid_entry)

    def process_log_file(self, filepath: str) -> None:
        try:
            with open(filepath, "r") as f:
                entries = [json.loads(line) for line in f]
                self.process_log_entries(entries)
        except Exception as e:
            logger.error(f"Error processing log file {filepath}: {e}")

    def process_log_files(self, filepaths: List[str]) -> None:
        for filepath in filepaths:
            self.process_log_file(filepath)

    def run(self) -> None:
        while True:
            try:
                with open("log_files.txt", "r") as f:
                    filepaths = [line.strip() for line in f]
                    self.process_log_files(filepaths)
            except Exception as e:
                logger.error(f"Error processing log files: {e}")
