void offload_record(Cache *cache, Record **records, size_t *num_records) {
    // Find the least recently used record in the cache
    size_t lru = 0;
    for (size_t i = 1; i < cache->size; i++) {
        if (cache->records[i]->last_accessed < cache->records[lru]->last_accessed) {
            lru = i;
