#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

// Define the task structure
typedef struct {
    int priority;
    time_t deadline;
    char status[10];
} task_t;

// Define the queue structure
typedef struct {
    task_t *tasks;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} queue_t;

// Function to initialize a new task
void init_task(task_t *task) {
    // Set the priority and deadline randomly
    task->priority = rand() % 10 + 1;
    task->deadline = time(NULL) + (rand() % 3600);
    // Set the status to "pending" or "in-progress" randomly
    if (rand() % 2 == 0) {
        strcpy(task->status, "pending");
    } else {
        strcpy(task->status, "in-progress");
    }
}

// Function to initialize a new queue
void init_queue(queue_t *queue) {
    // Allocate memory for the tasks array
    queue->tasks = malloc(sizeof(task_t) * 10);
    if (queue->tasks == NULL) {
        printf("Error: failed to allocate memory for tasks\n");
        exit(1);
    }
    // Set the capacity and size of the queue
    queue->capacity = 10;
    queue->size = 0;
    // Initialize the mutex
    pthread_mutex_init(&queue->mutex, NULL);
}

// Function to enqueue a task
void enqueue(queue_t *queue, task_t *task) {
    // Lock the mutex
    pthread_mutex_lock(&queue->mutex);
    // Check if the queue is full
    if (queue->size == queue->capacity) {
        printf("Error: queue is full\n");
        pthread_mutex_unlock(&queue->mutex);
        return;
    }
    // Add the task to the end of the queue
    queue->tasks[queue->size++] = *task;
    // Unlock the mutex
    pthread_mutex_unlock(&queue->mutex);
}

// Function to dequeue a task
void dequeue(queue_t *queue, task_t **task) {
    // Lock the mutex
    pthread_mutex_lock(&queue->mutex);
    // Check if the queue is empty
    if (queue->size == 0) {
        printf("Error: queue is empty\n");
        pthread_mutex_unlock(&queue->mutex);
        return;
    }
    // Remove the first task from the queue
    *task = &queue->tasks[0];
    for (int i = 1; i < queue->size; i++) {
        queue->tasks[i - 1] = queue->tasks[i];
    }
    queue->size--;
    // Unlock the mutex
    pthread_mutex_unlock(&queue->mutex);
}

// Function to update the status and deadline of a task by its index
void update(queue_t *queue, int index, char *status, time_t deadline) {
    // Lock the mutex
    pthread_mutex_lock(&queue->mutex);
    // Check if the index is valid
    if (index < 0 || index >= queue->size) {
        printf("Error: invalid index\n");
        pthread_mutex_unlock(&queue->mutex);
        return;
    }
    // Update the status and deadline of the task
    queue->tasks[index].status = status;
    queue->tasks[index].deadline = deadline;
    // Unlock the mutex
    pthread_mutex_unlock(&queue->mutex);
}

// Function to periodically validate the consistency of the queue across all threads
void validate(queue_t *queue) {
    // Lock the mutex
    pthread_mutex_lock(&queue->mutex);
    // Check if the queue is empty
    if (queue->size == 0) {
        printf("Error: queue is empty\n");
        pthread_mutex_unlock(&queue->mutex);
        return;
    }
    // Validate the consistency of the queue across all threads
    for (int i = 1; i < queue->size; i++) {
        if (strcmp(queue->tasks[i - 1].status, queue->tasks[i].status) != 0 ||
            queue->tasks[i - 1].deadline != queue->tasks[i].deadline) {
            printf("Error: inconsistent status or deadline\n");
            pthread_mutex_unlock(&queue->mutex);
            return;
        }
    }
    // Unlock the mutex
    pthread_mutex_unlock(&queue->mutex);
}

// Function to periodically evaluate the queue's current state and decide whether to compress the data structure when memory usage exceeds a certain threshold
void evaluate(queue_t *queue) {
    // Lock the mutex
    pthread_mutex_lock(&queue->mutex);
    // Check if the memory usage is above the threshold
    if (queue->size > 10 && queue->capacity < 100) {
        // Compress the data structure by half
        int new_capacity = queue->capacity / 2;
        task_t *new_tasks = malloc(sizeof(task_t) * new_capacity);
        if (new_tasks == NULL) {
            printf("Error: failed to allocate memory for tasks\n");
            pthread_mutex_unlock(&queue->mutex);
            return;
        }
        // Copy the tasks from the old array to the new array
        for (int i = 0; i < queue->size; i++) {
            new_tasks[i] = queue->tasks[i];
        }
        // Free the old array and update the queue's capacity and size
        free(queue->tasks);
        queue->tasks = new_tasks;
        queue->capacity = new_capacity;
        queue->size = queue->size / 2;
    }
    // Unlock the mutex
    pthread_mutex_unlock(&queue->mutex);
}

// Function to initialize an array of task structures with random initial conditions
void init_tasks(task_t *tasks, int num_tasks) {
    for (int i = 0; i < num_tasks; i++) {
        init_task(&tasks[i]);
    }
}

// Function to periodically compress the queue's data structure when memory usage exceeds a certain threshold
void compress(queue_t *queue) {
    // Lock the mutex
    pthread_mutex_lock(&queue->mutex);
    // Check if the memory usage is above the threshold
    if (queue->size > 10 && queue->capacity < 100) {
        // Compress the data structure by half
        int new_capacity = queue->capacity / 2;
        task_t *new_tasks = malloc(sizeof(task_t) * new_capacity);
        if (new_tasks == NULL) {
            printf("Error: failed to allocate memory for tasks\n");
            pthread_mutex_unlock(&queue->mutex);
            return;
        }
        // Copy the tasks from the old array to the new array
        for (int i = 0; i < queue->size; i++) {
            new_tasks[i] = queue->tasks[i];
        }
        // Free the old array and update the queue's capacity and size
        free(queue->tasks);
        queue->tasks = new_tasks;
        queue->capacity = new_capacity;
        queue->size = queue->size / 2;
    }
    // Unlock the mutex
    pthread_mutex_unlock(&queue->mutex);
}
