#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the log entry structure
struct log_entry {
    time_t timestamp;
    enum severity level;
    char* message;
};

// Define the doubly linked list node structure
struct node {
    struct log_entry* data;
    struct node* next;
    struct node* prev;
};

// Define the memory pool for log entries
static struct node* log_entries = NULL;

// Define the mutex for thread safety
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the memory pool and doubly linked list
void init_log(int num_entries) {
    log_entries = (struct node*)malloc(sizeof(struct node) * num_entries);
    for (int i = 0; i < num_entries; i++) {
        log_entries[i].data = NULL;
        log_entries[i].next = NULL;
        log_entries[i].prev = NULL;
    }
}

// Insert a new log entry into the doubly linked list
void insert_log(struct log_entry* entry) {
    pthread_mutex_lock(&lock);
    struct node* current = log_entries;
    while (current->next != NULL && current->data->level > entry->level) {
        current = current->next;
    }
    struct node* new_node = (struct node*)malloc(sizeof(struct node));
    new_node->data = entry;
    if (current == log_entries) {
        new_node->prev = NULL;
        new_node->next = current;
        current->prev = new_node;
        log_entries = new_node;
    } else {
        new_node->prev = current->prev;
        new_node->next = current;
        current->prev->next = new_node;
        current->prev = new_node;
    }
    pthread_mutex_unlock(&lock);
}

// Delete a log entry from the doubly linked list
void delete_log(struct log_entry* entry) {
    pthread_mutex_lock(&lock);
    struct node* current = log_entries;
    while (current != NULL && current->data != entry) {
        current = current->next;
    }
    if (current == NULL) {
        // Entry not found, do nothing
    } else {
        if (current->prev == NULL) {
            log_entries = current->next;
        } else {
            current->prev->next = current->next;
        }
        if (current->next != NULL) {
            current->next->prev = current->prev;
        }
        free(current);
    }
    pthread_mutex_unlock(&lock);
}

// Update the log entry with a new message
void update_log(struct log_entry* entry, char* message) {
    pthread_mutex_lock(&lock);
    struct node* current = log_entries;
    while (current != NULL && current->data != entry) {
        current = current->next;
    }
    if (current == NULL) {
        // Entry not found, do nothing
    } else {
        free(entry->message);
        entry->message = strdup(message);
    }
    pthread_mutex_unlock(&lock);
}

// Free the memory pool and doubly linked list
void free_log() {
    struct node* current = log_entries;
    while (current != NULL) {
        struct node* next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
}
```
