typedef struct entry {
    event* event;
    struct entry* next;
} entry;

// Define the hash table to store events based on their category
typedef struct hashtable {
    int size;
    entry** buckets;
} hashtable;

// Function to initialize a new hashtable with a given size
hashtable* init_hashtable(int size) {
    hashtable* table = malloc(sizeof(hashtable));
    if (!table) {
        return NULL;
    }
    table->size = size;
    table->buckets = calloc(size, sizeof(entry*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    return table;
}

// Function to insert a new event into the hashtable
int insert_event(hashtable* table, event* event) {
    // Calculate the hash value for the event's category
    int hash = event->category % table->size;
    entry* bucket = table->buckets[hash];
    while (bucket && bucket->next) {
        if (bucket->event->category == event->category) {
            // If a collision occurs, allocate a new entry and link it to the existing one
            entry* new_entry = malloc(sizeof(entry));
            if (!new_entry) {
                return -1;
            }
            new_entry->event = event;
            new_entry->next = bucket->next;
            bucket->next = new_entry;
        } else {
            // If no collision occurs, allocate a new entry and link it to the end of the list
            entry* new_entry = malloc(sizeof(entry));
            if (!new_entry) {
                return -1;
            }
            new_entry->event = event;
            new_entry->next = NULL;
            bucket->next = new_entry;
        }
    }
    return 0;
}

// Function to retrieve all events with a specific priority level and sort them by timestamp
void get_events(hashtable* table, enum priority priority) {
    // Iterate through the hashtable and retrieve all events with the specified priority level
    for (int i = 0; i < table->size; i++) {
        entry* bucket = table->buckets[i];
        while (bucket && bucket->next) {
            if (bucket->event->priority == priority) {
                // Add the event to a sorted list based on its timestamp
                add_to_sorted_list(bucket->event);
            }
            bucket = bucket->next;
        }
    }
}

