// Define the structure for each record
typedef struct {
    long offset;
    int key;
    double temperature;
    char location[256];
    double humidity;
    float wind_speed;
    bool data_quality;
    enum sensor_type {
        SENSOR_TYPE_1,
        SENSOR_TYPE_2,
        SENSOR_TYPE_3
    } sensor_type;
    struct sensor_location {
        int geographic_id;
        double altitude;
    } sensor_location;
    enum data_accuracy {
        ACCURACY_LOW,
        ACCURACY_MEDIUM,
        ACCURACY_HIGH
    } data_accuracy;
} record;

// Define the function to initialize and validate the records
void init_records(record *records, int num_records) {
    // Initialize each record with default values
    for (int i = 0; i < num_records; i++) {
        records[i].offset = 0;
        records[i].key = 0;
        records[i].temperature = 0.0;
        records[i].humidity = 0.0;
        records[i].wind_speed = 0.0;
        records[i].data_quality = false;
        records[i].sensor_type = SENSOR_TYPE_1;
        records[i].sensor_location.geographic_id = 0;
        records[i].sensor_location.altitude = 0.0;
        records[i].data_accuracy = ACCURACY_LOW;
    }

    // Validate each record against constraints
    for (int i = 0; i < num_records; i++) {
        if (records[i].offset < 0 || records[i].offset > 5 * 365 * 24 * 60 * 60) {
            // Timestamp is negative or greater than 5 years from current time
            printf("Invalid timestamp for record %d\n", i);
        } else if (records[i].key < 0 || records[i].key > 100000) {
            // Key is negative or greater than 100,000
            printf("Invalid key for record %d\n", i);
        } else if (records[i].temperature < -273.15 || records[i].temperature > 50) {
            // Temperature is less than -273.15 or greater than 50 degrees Celsius
            printf("Invalid temperature for record %d\n", i);
        } else if (records[i].humidity < 0 || records[i].humidity > 100) {
            // Humidity is less than 0 or greater than 100%
            printf("Invalid humidity for record %d\n", i);
        } else if (records[i].wind_speed < 0 || records[i].wind_speed > 50) {
            // Wind speed is less than 0 or greater than 50 km/h
            printf("Invalid wind speed for record %d\n", i);
        } else if (records[i].data_quality == false) {
            // Data quality flag is set to false
            printf("Invalid data quality flag for record %d\n", i);
        } else if (strlen(records[i].location) > 256) {
            // Location name is longer than 256 characters
            printf("Invalid location name for record %d\n", i);
        } else if (records[i].sensor_type < SENSOR_TYPE_1 || records[i].sensor_type > SENSOR_TYPE_3) {
            // Sensor type is not within the valid range
            printf("Invalid sensor type for record %d\n", i);
        } else if (records[i].sensor_location.geographic_id < 0 || records[i].sensor_location.geographic_id > 100000) {
            // Geographic ID is negative or greater than 100,000
            printf("Invalid geographic ID for record %d\n", i);
        } else if (records[i].sensor_location.altitude < 0 || records[i].sensor_location.altitude > 10000) {
            // Altitude is negative or greater than 10,000 meters
            printf("Invalid altitude for record %d\n", i);
        } else if (records[i].data_accuracy < ACCURACY_LOW || records[i].data_accuracy > ACCURACY_HIGH) {
            // Data accuracy is not within the valid range
            printf("Invalid data accuracy for record %d\n", i);
        }
    }
}

// Define the function to group and calculate statistics
void group_and_calculate(record *records, int num_records) {
    // Initialize a hash table to store the grouped records
    struct hash_table *hash_table = create_hash_table();

    // Iterate through each record and add it to the hash table
    for (int i = 0; i < num_records; i++) {
        // Check if the location name already exists in the hash table
        if (hash_table_contains(hash_table, records[i].location)) {
            // If the location name already exists, add the record to the existing group
            struct hash_entry *entry = hash_table_get(hash_table, records[i].location);
            entry->data.num_records++;
            entry->data.total_offset += records[i].offset;
            entry->data.total_key += records[i].key;
            entry->data.total_temperature += records[i].temperature;
            entry->data.total_humidity += records[i].humidity;
            entry->data.total_wind_speed += records[i].wind_speed;
        } else {
            // If the location name does not exist, create a new group and add the record to it
            struct hash_entry *entry = malloc(sizeof(struct hash_entry));
            strcpy(entry->key, records[i].location);
            entry->data.num_records = 1;
            entry->data.total_offset = records[i].offset;
            entry->data.total_key = records[i].key;
            entry->data.total_temperature = records[i].temperature;
            entry->data.total_humidity = records[i].humidity;
            entry->data.total_wind_speed = records[i].wind_speed;
