    // Iterate through each group and calculate the statistics
    for (int i = 0; i < hash_table->size; i++) {
        struct hash_entry *entry = hash_table->entries[i];
        if (entry != NULL) {
            entry->data.average_offset = entry->data.total_offset / entry->data.num_records;
            entry->data.average_key = entry->data.total_key / entry->data.num_records;
            entry->data.average_temperature = entry->data.total_temperature / entry->data.num_records;
            entry->data.average_humidity = entry->data.total_humidity / entry->data.num_records;
            entry->data.average_wind_speed = entry->data.total_wind_speed / entry->data.num_records;
        }
    }

    // Free the hash table and return the statistics
    free(hash_table);
}

