    char location[256];
    double humidity;
    float windSpeed;
    bool flag;
    enum sensor_type type;
    struct sensor_location loc;
    enum data_accuracy accuracy;
};

// Define the data structures for the sensor locations
struct sensor_location {
    int geo_id;
    double altitude;
};

// Define the data structures for the data accuracy
enum data_accuracy {
    ACCURATE,
    INACCURATE
};

// Define the data structures for the sensor types
enum sensor_type {
    TEMPERATURE,
    HUMIDITY,
    WIND_SPEED
};

// Function to dynamically allocate memory for and initialize a variable number of arrays based on user-provided parameters
void init_sensor_readings(int num_records, int num_locations) {
    // Allocate memory for the sensor readings array
    struct SensorReading *readings = (struct SensorReading *)malloc(num_records * sizeof(struct SensorReading));
    if (!readings) {
        printf("Error: Failed to allocate memory for sensor readings\n");
        return;
    }

    // Initialize the sensor readings array with default values
    for (int i = 0; i < num_records; i++) {
        readings[i].offset = 0;
        readings[i].key = 0;
        readings[i].temperature = 0.0;
        readings[i].humidity = 0.0;
        readings[i].windSpeed = 0.0;
        readings[i].flag = false;
        readings[i].type = TEMPERATURE;
        readings[i].loc.geo_id = 0;
        readings[i].loc.altitude = 0.0;
        readings[i].accuracy = ACCURATE;
    }

    // Allocate memory for the sensor locations array
    struct sensor_location *locations = (struct sensor_location *)malloc(num_locations * sizeof(struct sensor_location));
    if (!locations) {
        printf("Error: Failed to allocate memory for sensor locations\n");
        return;
    }

    // Initialize the sensor locations array with default values
    for (int i = 0; i < num_locations; i++) {
        locations[i].geo_id = 0;
        locations[i].altitude = 0.0;
    }
}

// Function to validate the sensor readings against specified constraints
void validate_sensor_readings(struct SensorReading *readings, int num_records) {
    // Validate that each record has a non-negative offset and is less than 5 years from the current time
    for (int i = 0; i < num_records; i++) {
        if (readings[i].offset < 0 || readings[i].offset > 182500) {
            printf("Error: Invalid offset value for record %d\n", i);
            return;
        }
    }

    // Validate that each location name is unique and does not overlap with other sensor locations
    for (int i = 0; i < num_records; i++) {
        for (int j = i + 1; j < num_records; j++) {
            if (strcmp(readings[i].location, readings[j].location) == 0) {
                printf("Error: Duplicate location name for records %d and %d\n", i, j);
                return;
            }
        }
    }
}

// Function to group the sensor readings by location name and calculate the average temperature, humidity, wind speed, timestamp, and sensor accuracy for each group
void group_sensor_readings(struct SensorReading *readings, int num_records) {
    // Initialize a hash table to store the grouped sensor readings
    struct HashTable *ht = createHashTable();

    // Iterate over the sensor readings and add them to the hash table
    for (int i = 0; i < num_records; i++) {
        char *location = readings[i].location;
        struct SensorReading reading = readings[i];
        if (!ht->containsKey(ht, location)) {
            ht->put(ht, location, reading);
        } else {
            struct SensorReading existing_reading = ht->get(ht, location);
            existing_reading.temperature += reading.temperature;
            existing_reading.humidity += reading.humidity;
            existing_reading.windSpeed += reading.windSpeed;
            existing_reading.offset += reading.offset;
            ht->put(ht, location, existing_reading);
        }
    }

    // Iterate over the hash table and calculate the average temperature, humidity, wind speed, timestamp, and sensor accuracy for each group
    struct HashTableIterator *it = ht->iterator(ht);
    while (it->hasNext(it)) {
        char *location = it->next(it);
        struct SensorReading reading = ht->get(ht, location);
        printf("Location: %s\n", location);
        printf("Average temperature: %.2f\n", reading.temperature / num_records);
        printf("Average humidity: %.2f\n", reading.humidity / num_records);
        printf("Average wind speed: %.2f\n", reading.windSpeed / num_records);
        printf("Average timestamp: %ld\n", reading.offset / num_records);
        printf("Average sensor accuracy: %d\n", reading.accuracy);
    }
}

// Function to determine the maximum, minimum, and median temperature, humidity, and wind speed for the entire dataset
void calculate_statistics(struct SensorReading *readings, int num_records) {
    // Initialize variables to store the maximum, minimum, and median values
    double max_temperature = -INFINITY;
    double min_temperature = INFINITY;
    double median_temperature = 0.0;
    double max_humidity = -INFINITY;
    double min_humidity = INFINITY;
    double median_humidity = 0.0;
    double max_windSpeed = -INFINITY;
    double min_windSpeed = INFINITY;
    double median_windSpeed = 0.0;

    // Iterate over the sensor readings and update the maximum, minimum, and median values
    for (int i = 0; i < num_records; i++) {
        if (readings[i].temperature > max_temperature) {
            max_temperature = readings[i].temperature;
        }
        if (readings[i].temperature < min_temperature) {
            min_temperature = readings[i].temperature;
        }
        median_temperature += readings[i].temperature;
        if (i % 2 == 0) {
            median_temperature /= 2.0;
        } else {
            median_temperature = (median_temperature + readings[i].temperature) / 2.0;
        }
        if (readings[i].humidity > max_humidity) {
            max_humidity = readings[i].humidity;
        }
        if (readings[i].humidity < min_humidity) {
            min_humidity = readings[i].humidity;
        }
        median_humidity += readings[i].humidity;
        if (i % 2 == 0) {
            median_humidity /= 2.0;
        } else {
            median_humidity = (median_humidity + readings[i].humidity) / 2.0;
        }
        if (readings[i].windSpeed > max_windSpeed) {
            max_windSpeed = readings[i].windSpeed;
        }
        if (readings[i].windSpeed < min_windSpeed) {
            min_windSpeed = readings[i].windSpeed;
        }
        median_windSpeed += readings[i].windSpeed;
        if (i % 2 == 0) {
            median_windSpeed /= 2.0;
        } else {
            median_windSpeed = (median_windSpeed + readings[i].windSpeed) / 2.0;
        }
    }

    // Print the maximum, minimum, and median temperature, humidity, and wind speed for the entire dataset
    printf("Maximum temperature: %.2f\n", max_temperature);
    printf("Minimum temperature: %.2f\n", min_temperature);
    printf("Median temperature: %.2f\n", median_temperature);
    printf("Maximum humidity: %.2f\n", max_humidity);
    printf("Minimum humidity: %.2f\n", min_humidity);
    printf("Median humidity: %.2f\n", median_humidity);
    printf("Maximum wind speed: %.2f\n", max_windSpeed);
    printf("Minimum wind speed: %.2f\n", min_windSpeed);
    printf("Median wind speed: %.2f\n", median_windSpeed);
}

// Function to handle memory allocation failures and invalid data inputs gracefully
void error_handling(struct SensorReading *readings, int num_records) {
    // Check if the memory allocation for the sensor readings array failed
