        // Initialize the log message fields
        log_messages[i].timestamp = time(NULL);
        sprintf(log_messages[i].message, "Record %d initialized", i + 1);
        log_messages[i].metadata.key = keys[i];
        log_messages[i].metadata.offset = offsets[i];
        log_messages[i].metadata.temperature = temperatures[i];
        strcpy(log_messages[i].metadata.location, locations[i]);
        log_messages[i].metadata.humidity = humidities[i];
        log_messages[i].metadata.wind_speed = wind_speeds[i];
        log_messages[i].metadata.data_quality = data_qualities[i];
        log_messages[i].metadata.metadata.identifier = metadata[i].identifier;
        log_messages[i].metadata.metadata.length = metadata[i].length;
        log_messages[i].sensor_type = sensor_types[i];
        log_messages[i].reliability = reliabilities[i];

        // Initialize the event data fields
        event_datas[i].event_name = "Event #";
        event_datas[i].event_duration = i * 10;
    }
}
