        SENSOR_TYPE_2,
        SENSOR_TYPE_3
    } sensor_type;
} sensor_data;

// Define the linked list structure for storing sensor data
typedef struct node {
    sensor_data *data;
    struct node *next;
} node;

// Function to dynamically allocate memory for and initialize an arbitrary number of records representing environmental sensor data
void init_sensor_data(int num_records, int min_offset, int max_offset, int min_key, int max_key, int min_temperature, int max_temperature, double min_humidity, double max_humidity, float min_wind_speed, float max_wind_speed, long min_timestamp, long max_timestamp, char *location_names[], int num_locations) {
    // Check if the number of records is within the specified range
    if (num_records < 1000 || num_records > 100000) {
        printf("Invalid number of records: %d\n", num_records);
        return;
    }

    // Allocate memory for the linked list and initialize it to NULL
    node *head = NULL;

    // Loop through each record and allocate memory for the sensor data structure
    for (int i = 0; i < num_records; i++) {
        sensor_data *data = malloc(sizeof(sensor_data));
        if (!data) {
            printf("Failed to allocate memory for sensor data\n");
            return;
