        data->temperature = min_temperature + (rand() % (max_temperature - min_temperature));
        data->humidity = min_humidity + (rand() % (max_humidity - min_humidity));
        data->wind_speed = min_wind_speed + (rand() % (max_wind_speed - min_wind_speed));
        data->timestamp = min_timestamp + (rand() % (max_timestamp - min_timestamp));
        strcpy(data->location, location_names[i % num_locations]);
        data->data_quality = true;
        data->sensor_type = SENSOR_TYPE_1;

        // Add the record to the linked list
        node *new_node = malloc(sizeof(node));
        new_node->data = data;
        new_node->next = head;
        head = new_node;
    }

    // Group the records by location name and calculate the average temperature, humidity, wind speed, timestamp, and sensor accuracy for each group
    node *current = head;
    while (current != NULL) {
        node *next = current->next;
        char *location_name = current->data->location;
        int num_records = 0;
        double total_temperature = 0.0;
        double total_humidity = 0.0;
        float total_wind_speed = 0.0;
        long total_timestamp = 0;
        bool data_quality = true;
        enum sensor_type sensor_type = SENSOR_TYPE_1;

        // Loop through each record and add it to the group if the location name matches
        while (next != NULL && strcmp(location_name, next->data->location) == 0) {
            num_records++;
            total_temperature += next->data->temperature;
            total_humidity += next->data->humidity;
            total_wind_speed += next->data->wind_speed;
            total_timestamp += next->data->timestamp;
            data_quality &= next->data->data_quality;
            sensor_type = next->data->sensor_type;
            next = next->next;
        }

        // Calculate the average temperature, humidity, wind speed, timestamp, and sensor accuracy for each group
        double avg_temperature = total_temperature / num_records;
        double avg_humidity = total_humidity / num_records;
        float avg_wind_speed = total_wind_speed / num_records;
        long avg_timestamp = total_timestamp / num_records;
        bool avg_data_quality = data_quality;
        enum sensor_type avg_sensor_type = sensor_type;

        // Calculate the standard deviation of temperatures and humidity levels for each group
        double stddev_temperature = 0.0;
        double stddev_humidity = 0.0;

        while (next != NULL && strcmp(location_name, next->data->location) == 0) {
            double temp_diff = avg_temperature - next->data->temperature;
            stddev_temperature += temp_diff * temp_diff;
            double humidity_diff = avg_humidity - next->data->humidity;
            stddev_humidity += humidity_diff * humidity_diff;
            next = next->next;
        }

        // Calculate the weighted average of sensor accuracies based on the number of readings from each sensor type
        double weighted_avg_sensor_accuracy = 0.0;
        int num_readings = 0;

        while (next != NULL && strcmp(location_name, next->data->location) == 0) {
            if (next->data->sensor_type == avg_sensor_type) {
                weighted_avg_sensor_accuracy += next->data->data_quality ? 1.0 : -1.0;
                num_readings++;
            }
            next = next->next;
        }

        if (num_readings > 0) {
            weighted_avg_sensor_accuracy /= num_readings;
        }

        // Print the results for each group
        printf("Location: %s\n", location_name);
        printf("Average temperature: %.2f\n", avg_temperature);
        printf("Standard deviation of temperatures: %.2f\n", sqrt(stddev_temperature));
        printf("Average humidity: %.2f\n", avg_humidity);
        printf("Standard deviation of humidity levels: %.2f\n", sqrt(stddev_humidity));
        printf("Average wind speed: %.2f\n", avg_wind_speed);
        printf("Maximum wind speed: %.2f\n", max_wind_speed);
        printf("Minimum wind speed: %.2f\n", min_wind_speed);
        printf("Average timestamp: %ld\n", avg_timestamp);
        printf("Data quality flag: %s\n", avg_data_quality ? "true" : "false");
        printf("Sensor type: %d\n", avg_sensor_type);
        printf("Weighted average of sensor accuracies: %.2f\n", weighted_avg_sensor_accuracy);
    }
}
