// Define the structure for sensor data
struct sensor_data {
    long offset;
    int key;
    int temperature;
    char location[256];
    double humidity;
    float wind_speed;
    bool data_quality;
    enum sensor_type {
        SENSOR_TYPE_1,
        SENSOR_TYPE_2,
        SENSOR_TYPE_3
    } sensor_type;
};

// Define the structure for linked list node
struct node {
    struct sensor_data data;
    struct node *next;
};

// Function to dynamically allocate memory for and initialize an arbitrary number of records representing environmental sensor data
void init_sensor_data(int num_records, struct node **head) {
    // Check if the input is within the valid range
    if (num_records < 1000 || num_records > 100000) {
        printf("Invalid number of records. Must be between 1000 and 100000.\n");
        return;
    }

    // Allocate memory for the linked list nodes
    struct node *current = malloc(sizeof(struct node));
    current->next = NULL;
    *head = current;

    // Initialize the sensor data in each node
    for (int i = 0; i < num_records; i++) {
        current->data.offset = i;
        current->data.key = i;
        current->data.temperature = rand() % 160 - 80;
        sprintf(current->data.location, "Location %d", i);
        current->data.humidity = (float)rand() / RAND_MAX * 100;
        current->data.wind_speed = (float)rand() / RAND_MAX * 50;
        current->data.data_quality = true;
        current->data.sensor_type = SENSOR_TYPE_1;
        current = current->next = malloc(sizeof(struct node));
    }
}

// Function to group the entries by location name and calculate the average temperature, humidity, wind speed, timestamp, and sensor accuracy for each group
void group_sensor_data(struct node *head) {
    // Create a hash map to store the grouped data
    struct hashmap *grouped_data = create_hashmap();

    // Iterate through the linked list and add each record to the hash map
    for (struct node *current = head; current != NULL; current = current->next) {
        char location[256];
        sprintf(location, "%s", current->data.location);
        struct sensor_data data = current->data;
        add_to_hashmap(grouped_data, location, &data);
    }

    // Iterate through the hash map and calculate the average temperature, humidity, wind speed, timestamp, and sensor accuracy for each group
    struct hashmap_iter iter = hashmap_get_first(grouped_data);
    while (hashmap_iter_has_more(&iter)) {
        char *location = hashmap_iter_get_key(&iter);
        struct sensor_data *data = hashmap_iter_get_value(&iter);
        int num_records = 0;
        float total_temperature = 0.0f;
        float total_humidity = 0.0f;
        float total_wind_speed = 0.0f;
        long total_timestamp = 0L;
        int num_data_quality_flags = 0;
        for (int i = 0; i < data->length; i++) {
            struct sensor_data record = data[i];
            num_records++;
            total_temperature += record.temperature;
            total_humidity += record.humidity;
            total_wind_speed += record.wind_speed;
            total_timestamp += record.offset;
            if (record.data_quality) {
                num_data_quality_flags++;
            }
        }
        float average_temperature = total_temperature / num_records;
        float average_humidity = total_humidity / num_records;
        float average_wind_speed = total_wind_speed / num_records;
        long average_timestamp = total_timestamp / num_records;
        int average_data_quality_flag = num_data_quality_flags / num_records;
        printf("Location: %s\n", location);
        printf("Average temperature: %.2f\n", average_temperature);
        printf("Average humidity: %.2f\n", average_humidity);
        printf("Average wind speed: %.2f\n", average_wind_speed);
        printf("Average timestamp: %ld\n", average_timestamp);
        printf("Average data quality flag: %d\n", average_data_quality_flag);
    }
}

// Function to handle incomplete or corrupted data gracefully, providing fallback values when necessary without affecting the overall computation of statistics
void handle_incomplete_data(struct node *head) {
    // Iterate through the linked list and check for incomplete or corrupted data
    for (struct node *current = head; current != NULL; current = current->next) {
        if (current->data.temperature < -80 || current->data.temperature > 80) {
            // Replace invalid temperature values with a fallback value
            current->data.temperature = -999;
        }
        if (current->data.humidity < 0 || current->data.humidity > 100) {
            // Replace invalid humidity values with a fallback value
            current->data.humidity = -999;
        }
        if (current->data.wind_speed < 0 || current->data.wind_speed > 50) {
            // Replace invalid wind speed values with a fallback value
            current->data.wind_speed = -999;
        }
    }
}

// Function to determine the maximum and minimum wind speeds recorded for each location and report them alongside the grouped statistics
void determine_max_min_wind_speeds(struct node *head) {
    // Create a hash map to store the maximum and minimum wind speeds for each location
    struct hashmap *max_min_wind_speeds = create_hashmap();

    // Iterate through the linked list and add each record to the hash map
    for (struct node *current = head; current != NULL; current = current->next) {
        char location[256];
        sprintf(location, "%s", current->data.location);
        struct sensor_data data = current->data;
        add_to_hashmap(max_min_wind_speeds, location, &data);
    }

    // Iterate through the hash map and determine the maximum and minimum wind speeds for each location
    struct hashmap_iter iter = hashmap_get_first(max_min_wind_speeds);
    while (hashmap_iter_has_more(&iter)) {
        char *location = hashmap_iter_get_key(&iter);
        struct sensor_data *data = hashmap_iter_get_value(&iter);
        int num_records = 0;
        float max_wind_speed = -999.0f;
        float min_wind_speed = 999.0f;
        for (int i = 0; i < data->length; i++) {
            struct sensor_data record = data[i];
            num_records++;
            if (record.wind_speed > max_wind_speed) {
                max_wind_speed = record.wind_speed;
            }
            if (record.wind_speed < min_wind_speed) {
                min_wind_speed = record.wind_speed;
            }
        }
        printf("Location: %s\n", location);
        printf("Maximum wind speed: %.2f\n", max_wind_speed);
        printf("Minimum wind speed: %.2f\n", min_wind_speed);
    }
}

// Function to handle concurrent data updates and ensure thread safety if necessary
void handle_concurrent_updates(struct node *head) {
    // Implement a locking mechanism to prevent concurrent updates to the linked list
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Iterate through the linked list and update each record with the latest data
    for (struct node *current = head; current != NULL; current = current->next) {
        struct sensor_data data = current->data;
        // Update the temperature, humidity, wind speed, timestamp, and data quality flag
        data.temperature = get_latest_temperature(data.key);
        data.humidity = get_latest_humidity(data.key);
        data.wind_speed = get_latest_wind_speed(data.key);
        data.offset = get_latest_timestamp(data.key);
        data.data_quality = get_latest_data_quality_flag(data.key);
        current->data = data;
    }

    // Unlock the mutex to allow other threads to access the linked list
    pthread_mutex_unlock(&mutex);
}
