            fprintf(stderr, "Error: failed to get message from buffer\n");
            return;
        }
        // Process the message here
    }
}

// Implement a mechanism for message delivery status tracking and reporting
void report_delivery_statuses(message_t* messages, int num_messages) {
    // Create an array to store the delivery statuses
    bool* delivery_statuses = malloc(sizeof(bool) * num_messages);
    if (!delivery_statuses) {
        fprintf(stderr, "Error: failed to allocate memory for delivery statuses\n");
        return;
    }

    // Loop over each message and update the delivery status accordingly
    for (int i = 0; i < num_messages; i++) {
        if (messages[i].delivery_status) {
            delivery_statuses[i] = true;
        } else {
            delivery_statuses[i] = false;
        }
    }

    // Print the delivery statuses to standard output
    for (int i = 0; i < num_messages; i++) {
        printf("Message %d: %s\n", i + 1, delivery_statuses[i] ? "delivered" : "not delivered");
    }
}
