```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

struct node {
    char *str;
    int num;
};

int validate_double(double value, double min, double max) {
    if (value < min || value > max) {
        fprintf(stderr, "Value out of range: %f\n", value);
        return -1;
    }

    int precision = DBL_DIG;
    if (precision < 0) {
        // Precision not supported by the system
        precision = 6;
    }

    double min_exp = pow(10, precision);
    double max_exp = pow(10, precision + 1);
    if (value < min_exp || value > max_exp) {
        fprintf(stderr, "Value exceeds precision limits: %f\n", value);
        return -1;
    }

    return 0;
}

int calculate_num(struct node *node, const char *env_var) {
    double value = node->value;
    if (validate_double(value, 0.0, 1.0)) {
        return -1;
    }

    int num = round(value * atoi(env_var));
    if (num < 0) {
        fprintf(stderr, "Invalid value for environment variable: %s\n", env_var);
        return -1;
    }

    node->num = num;
    return 0;
}
