5. Implement a performance optimization that minimizes memory fragmentation during the dynamic allocation of the 'struct node' structures, considering the system's available memory and the expected number of allocations. Use advanced memory pooling techniques to optimize performance, ensuring that the function can handle concurrent access from multiple threads by employing appropriate synchronization mechanisms, including mutexes and read-write locks.
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <malloc.h>

struct node {
    char *str;
    int num;
};

int optimize_memory(struct config *config, struct node **nodes) {
    // Initialize the memory pool with a fixed size based on the expected number of allocations
    size_t pool_size = sizeof(struct node) * config->struct_node_ptr_array_size;
    void *pool = malloc(pool_size);
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for memory pool: %s\n", strerror(errno));
        return -1;
    }

    // Initialize the mutex and condition variable for synchronization
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Allocate memory from the pool in a thread-safe manner
    for (int i = 0; i < config->struct_node_ptr_array_size; i++) {
        pthread_mutex_lock(&mutex);
        while (!pool) {
            pthread_cond_wait(&cond, &mutex);
        }

        struct node *node = pool;
        pool = NULL;
        pthread_mutex_unlock(&mutex);

        nodes[i] = node;
    }

    // Free the memory pool and synchronization objects
    free(pool);
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);

    return 0;
}
