    for (int i = 0; i < num_records; i++) {
        records[i].timestamp = timestamps[i];
        strcpy(records[i].identifier, identifiers[i]);
    }

    // Return the number of events fetched from the service
    return num_events;
}

// Filter the events based on user criteria
void filter_events(int num_events, double *timestamps, char **identifiers, struct log_entry *records) {
    // Declare variables for filtering and sorting
    int filtered_num_events = 0;
    double *filtered_timestamps = (double *)malloc(num_events * sizeof(double));
    char **filtered_identifiers = (char **)malloc(num_events * sizeof(char *));
    struct log_entry *filtered_records = (struct log_entry *)malloc(num_events * sizeof(struct log_entry));

    // Filter the events based on user criteria
    for (int i = 0; i < num_events; i++) {
        if (timestamps[i] >= get_start_timestamp() && timestamps[i] <= get_end_timestamp()) {
            filtered_timestamps[filtered_num_events] = timestamps[i];
            filtered_identifiers[filtered_num_events] = identifiers[i];
            filtered_records[filtered_num_events].timestamp = timestamps[i];
            strcpy(filtered_records[filtered_num_events].identifier, identifiers[i]);
            filtered_num_events++;
        }
    }

    // Sort the filtered events based on timestamp
    qsort(filtered_timestamps, filtered_num_events, sizeof(double), compare_timestamps);
    qsort(filtered_identifiers, filtered_num_events, sizeof(char *), compare_identifiers);
    for (int i = 0; i < filtered_num_events; i++) {
        filtered_records[i].timestamp = filtered_timestamps[i];
        strcpy(filtered_records[i].identifier, filtered_identifiers[i]);
    }

    // Free allocated memory when no longer needed
    free(filtered_timestamps);
    for (int i = 0; i < filtered_num_events; i++) {
        free(filtered_identifiers[i]);
    }
    free(filtered_records);
}

// Compare two timestamps and return the difference
double compare_timestamps(const void *a, const void *b) {
    double diff = (*(double *)a - *(double *)b);
    if (diff < 0) {
        return -1;
    } else if (diff > 0) {
        return 1;
    } else {
        return 0;
    }
}

// Compare two identifiers and return the difference
int compare_identifiers(const void *a, const void *b) {
    int diff = strcmp(*(char **)a, *(char **)b);
    if (diff < 0) {
        return -1;
    } else if (diff > 0) {
        return 1;
    } else {
        return 0;
    }
}

