// Function to compress the data structure when memory usage exceeds a certain threshold
void compress_data_structure(record_store_t *store) {
    // Lock the mutex
    pthread_mutex_lock(&store->mutex);

    // Compress the data structure by reducing the number of records
    store->num_records = store->num_records / 2;

    // Unlock the mutex
    pthread_mutex_unlock(&store->mutex);
}

// Function to dynamically resize the data structure based on the number of records
void dynamic_resize(record_store_t *store, size_t num_records) {
    // Lock the mutex
    pthread_mutex_lock(&store->mutex);

    // Resize the data structure if necessary
    if (num_records > store->num_records) {
        store->records = (record_t *)realloc(store->records, num_records * sizeof(record_t));
        if (!store->records) {
            fprintf(stderr, "Failed to resize the data structure\n");
            exit(1);
        }
    }

