void init_data(int num_records, int *temperature_range, int *humidity_range, float *wind_speed_range) {
    // Validate the input parameters
    if (num_records < 1000 || num_records > 100000) {
        printf("Invalid number of records: %d\n", num_records);
        return;
    }
    if (*temperature_range < -80 || *temperature_range > 80) {
        printf("Invalid temperature range: %d\n", *temperature_range);
        return;
    }
    if (*humidity_range < 0 || *humidity_range > 100) {
        printf("Invalid humidity range: %d\n", *humidity_range);
        return;
    }
    if (*wind_speed_range < 0 || *wind_speed_range > 50) {
        printf("Invalid wind speed range: %f\n", *wind_speed_range);
        return;
    }

    // Allocate memory for the arrays
    struct record *records = malloc(num_records * sizeof(struct record));
    char **location_names = malloc(num_records * sizeof(char*));
    int *temperatures = malloc(num_records * sizeof(int));
    double *humidities = malloc(num_records * sizeof(double));
    float *wind_speeds = malloc(num_records * sizeof(float));
    bool *data_qualities = malloc(num_records * sizeof(bool));
    struct sensor_location *sensor_locations = malloc(num_records * sizeof(struct sensor_location));
    enum data_accuracy *accuracies = malloc(num_records * sizeof(enum data_accuracy));

    // Initialize the arrays with random values within the given ranges
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand() % 1000000;
        records[i].key = rand() % 1000000;
        records[i].temperature = round(rand() % *temperature_range);
        location_names[i] = malloc(256 * sizeof(char));
        sprintf(location_names[i], "Location %d", i + 1);
        records[i].humidity = rand() % *humidity_range / 100.0;
        wind_speeds[i] = round(rand() % *wind_speed_range);
        data_qualities[i] = (bool) (rand() % 2);
        sensor_locations[i].geographic_identifier = rand() % 1000000;
        sensor_locations[i].altitude = rand() % 1000000;
        accuracies[i] = (enum data_accuracy) (rand() % 2);
    }

    // Group the entries by location name and calculate the average temperature, humidity, wind speed, timestamp, sensor accuracy, and geographic identifier for each group
    struct record *grouped_records = malloc(num_records * sizeof(struct record));
    int num_groups = 0;
    for (int i = 0; i < num_records; i++) {
        bool found = false;
        for (int j = 0; j < num_groups; j++) {
            if (strcmp(location_names[i], location_names[j]) == 0) {
                grouped_records[j].offset += records[i].offset;
                grouped_records[j].key += records[i].key;
                grouped_records[j].temperature += records[i].temperature;
                grouped_records[j].humidity += records[i].humidity;
                grouped_records[j].wind_speed += wind_speeds[i];
                grouped_records[j].data_quality = data_qualities[i] || grouped_records[j].data_quality;
                grouped_records[j].location.geographic_identifier += sensor_locations[i].geographic_identifier;
                grouped_records[j].location.altitude += sensor_locations[i].altitude;
                grouped_records[j].accuracy = accuracies[i] || grouped_records[j].accuracy;
                found = true;
            }
        }
        if (!found) {
            num_groups++;
            grouped_records[num_groups - 1].offset = records[i].offset;
            grouped_records[num_groups - 1].key = records[i].key;
            grouped_records[num_groups - 1].temperature = records[i].temperature;
            grouped_records[num_groups - 1].humidity = records[i].humidity;
            grouped_records[num_groups - 1].wind_speed = wind_speeds[i];
            grouped_records[num_groups - 1].data_quality = data_qualities[i];
            grouped_records[num_groups - 1].location.geographic_identifier = sensor_locations[i].geographic_identifier;
            grouped_records[num_groups - 1].location.altitude = sensor_locations[i].altitude;
            grouped_records[num_groups - 1].accuracy = accuracies[i];
        }
    }

    // Print the results
    printf("Number of groups: %d\n", num_groups);
    for (int i = 0; i < num_groups; i++) {
        printf("Group %d:\n", i + 1);
        printf("\tOffset: %ld\n", grouped_records[i].offset / num_records);
        printf("\tKey: %d\n", grouped_records[i].key / num_records);
        printf("\tTemperature: %.2f\n", grouped_records[i].temperature / num_records);
        printf("\tHumidity: %.2f\n", grouped_records[i].humidity / num_records);
        printf("\tWind speed: %.2f\n", grouped_records[i].wind_speed / num_records);
        printf("\tData quality: %s\n", grouped_records[i].data_quality ? "true" : "false");
        printf("\tSensor location: (%ld, %d)\n", grouped_records[i].location.geographic_identifier / num_records, grouped_records[i].location.altitude / num_records);
        printf("\tAccuracy: %s\n", grouped_records[i].accuracy == ACCURATE ? "ACCURATE" : "INACCURATE");
    }
}
