    float value;
    bool valid;
    char* string;
} entry;

typedef struct data_node {
    entry data;
    struct data_node* next;
    int ref_count;
} node;

// Define the function to allocate and initialize the arrays and linked list
void init_data(int num_values, int num_entries, int seed) {
    // Allocate memory for the arrays
    array_data data = {
        malloc(num_values * sizeof(double)),
        malloc(num_values * sizeof(char)),
        malloc(num_entries * sizeof(entry))
    };

    // Initialize the arrays and linked list
    for (int i = 0; i < num_values; i++) {
        data.values[i] = drand48() * 100;
        data.indicators[i] = 'A';
    }

    // Initialize the linked list
    node* head = NULL;
    for (int i = 0; i < num_entries; i++) {
        entry e = {data.values[i], true, "string"};
        node* n = malloc(sizeof(node));
        n->data = e;
        n->next = head;
        head = n;
    }

    // Set the reference count for each node to 1
    for (node* n = head; n != NULL; n = n->next) {
        n->ref_count = 1;
    }

    // Free any unused memory
    free(data.values);
    free(data.indicators);
    free(data.entries);
}

// Define the function to populate the linked list with random values
void populate_list(node* head, int num_nodes) {
    // Initialize a random number generator
