    for (int i = 0; i < num_nodes; i++) {
        node* n = malloc(sizeof(node));
        entry e = {drand48() * 100, true, "string"};
        n->data = e;
        n->next = head;
        head = n;
    }
}

// Define the function to handle memory allocation failures
void handle_failure(int error) {
    // Log the failure and provide insights into the root cause
    printf("Memory allocation failed with error %d\n", error);
}

// Define the function to free allocated memory when no longer needed
void free_memory(node* head) {
    // Free any unused memory
    for (node* n = head; n != NULL; n = n->next) {
        free(n->data.string);
        free(n);
    }
}
