// Define the function to manage dynamic memory allocation for processing a text file containing sensor data
void processSensorData(const char* filename, int numDevices) {
    // Initialize the linked list of sensor data
    node* head = NULL;
    node* current = NULL;

    // Open the input file and read each line
    FILE* fp = fopen(filename, "r");
    char line[1024];
    while (fgets(line, 1024, fp) != NULL) {
        // Allocate memory for the sensor reading and device identifier
        double* reading = malloc(sizeof(double));
        char* identifier = malloc(numDevices * sizeof(char));

        // Parse the line and extract the sensor reading and device identifier
        sscanf(line, "%lf %s", reading, identifier);

        // Allocate memory for the timestamp
        time_t* timestamp = malloc(sizeof(time_t));

        // Get the current timestamp using an external library
        *timestamp = getTimestamp();

        // Create a new node for the sensor data and add it to the linked list
        node* newNode = malloc(sizeof(node));
        newNode->data.reading = *reading;
        newNode->data.identifier = identifier;
        newNode->data.timestamp = *timestamp;
        newNode->next = NULL;

        // If the linked list is empty, set the head and current pointers to the new node
        if (head == NULL) {
            head = newNode;
            current = newNode;
        } else {
            // Otherwise, add the new node to the end of the linked list
            current->next = newNode;
            current = newNode;
        }
    }

    // Close the input file
    fclose(fp);

    // Compute the average of the last two fields for each sensor reading and print the result in a comma-separated format
    node* previous = head;
    while (previous != NULL) {
        double sum = 0.0;
        int count = 0;
        node* current = previous->next;
        while (current != NULL && count < 2) {
            sum += current->data.reading;
            count++;
            current = current->next;
        }
        double average = sum / count;
        printf("%s, %f\n", previous->data.identifier, average);
        previous = previous->next;
    }

    // Deallocate memory for the linked list and sensor data
    node* temp = head;
    while (temp != NULL) {
        free(temp->data.reading);
        free(temp->data.identifier);
        free(temp->data.timestamp);
        temp = temp->next;
    }
}

