#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <math.h>

// Define the structure for environmental sensor data
struct record {
    long offset;
    int key;
    int temperature;
    char location[256];
    double humidity;
    float wind_speed;
    bool data_quality;
    enum sensor_type {
        SENSOR_TYPE_1,
        SENSOR_TYPE_2,
        SENSOR_TYPE_3
    } sensor_type;
    double timestamp;
    int geographic_id;
};

// Define the function to dynamically allocate memory for and initialize a variable number of records
struct record* init_records(int num_records) {
    // Check if the input is within the valid range
    if (num_records < 1000 || num_records > 100000) {
        printf("Invalid number of records: %d\n", num_records);
        return NULL;
    }

    // Allocate memory for the records
    struct record* records = (struct record*)malloc(num_records * sizeof(struct record));
    if (!records) {
        printf("Failed to allocate memory for %d records\n", num_records);
        return NULL;
    }

    // Initialize the records
    for (int i = 0; i < num_records; i++) {
        records[i].offset = i * sizeof(struct record);
        records[i].key = i + 1;
        records[i].temperature = roundf(2.0 * i) / 2.0;
        sprintf(records[i].location, "Location %d", i + 1);
        records[i].humidity = (double)i / 100.0;
        records[i].wind_speed = (float)(i * 5) / 100.0;
        records[i].data_quality = true;
        records[i].sensor_type = SENSOR_TYPE_1;
        records[i].timestamp = i * 3600 + 86400;
        records[i].geographic_id = i + 1;
    }

    return records;
}

// Define the function to group the records by location name and calculate the average temperature, humidity, wind speed, timestamp, and sensor accuracy for each group
void group_records(struct record* records, int num_records) {
    // Create a hash table to store the grouped records
    struct record** grouped_records = (struct record**)malloc(num_records * sizeof(struct record*));
    if (!grouped_records) {
        printf("Failed to allocate memory for %d grouped records\n", num_records);
        return;
    }

    // Initialize the hash table with NULL values
    for (int i = 0; i < num_records; i++) {
        grouped_records[i] = NULL;
    }

    // Group the records by location name and calculate the average temperature, humidity, wind speed, timestamp, and sensor accuracy for each group
    for (int i = 0; i < num_records; i++) {
        struct record* current_record = &records[i];
        char* location_name = current_record->location;
        int geographic_id = current_record->geographic_id;

        // Check if the location name is already in the hash table
        bool found = false;
        for (int j = 0; j < num_records; j++) {
            struct record* grouped_record = grouped_records[j];
            if (grouped_record && strcmp(location_name, grouped_record->location) == 0 && geographic_id == grouped_record->geographic_id) {
                found = true;
                break;
            }
        }

        // If the location name is not in the hash table, add it to the hash table and initialize the average values
        if (!found) {
            struct record* new_grouped_record = (struct record*)malloc(sizeof(struct record));
            if (!new_grouped_record) {
                printf("Failed to allocate memory for a new grouped record\n");
                return;
            }
            strcpy(new_grouped_record->location, location_name);
            new_grouped_record->geographic_id = geographic_id;
            new_grouped_record->temperature = 0.0;
            new_grouped_record->humidity = 0.0;
            new_grouped_record->wind_speed = 0.0;
            new_grouped_record->timestamp = 0.0;
            new_grouped_record->data_quality = true;
            grouped_records[i] = new_grouped_record;
        }

        // Add the current record to the corresponding group
        struct record* grouped_record = grouped_records[i];
        grouped_record->temperature += current_record->temperature;
        grouped_record->humidity += current_record->humidity;
        grouped_record->wind_speed += current_record->wind_speed;
        grouped_record->timestamp += current_record->timestamp;
        if (!current_record->data_quality) {
            grouped_record->data_quality = false;
        }
    }

    // Calculate the average values for each group
    for (int i = 0; i < num_records; i++) {
        struct record* grouped_record = grouped_records[i];
        if (grouped_record) {
            grouped_record->temperature /= grouped_record->key;
            grouped_record->humidity /= grouped_record->key;
            grouped_record->wind_speed /= grouped_record->key;
            grouped_record->timestamp /= grouped_record->key;
        }
    }
}
