    for (int i = 0; i < ds->num_records; i++) {
        fprintf(log, "%lu\n", ds->records[i].timestamp);
    }

    // Close the log file
    fclose(log);
}

// Define the function to compress the data structure when memory usage exceeds a certain threshold
void compress_data_structure(data_structure_t *ds) {
    // Lock the data structure for writing
    pthread_rwlock_wrlock(&ds->lock);

    // Compress the data structure by reducing the size of each record's data field
    for (int i = 0; i < ds->num_records; i++) {
        ds->records[i].data = realloc(ds->records[i].data, sizeof(data_t) / 2);
    }

    // Unlock the data structure for writing
    pthread_rwlock_unlock(&ds->lock);
}

// Define the function to dynamically resize the data structure based on incoming updates
void dynamic_resize(data_structure_t *ds, size_t num_records) {
    // Lock the data structure for writing
    pthread_rwlock_wrlock(&ds->lock);

    // Resize the data structure if necessary
    if (num_records > ds->max_records) {
        ds->records = realloc(ds->records, num_records * sizeof(record_t));
        ds->offsets = realloc(ds->offsets, num_records * sizeof(offset_t));
        ds->unique_ids = realloc(ds->unique_ids, num_records * sizeof(unique_id_t));
        ds->max_records = num_records;
    }

    // Unlock the data structure for writing
    pthread_rwlock_unlock(&ds->lock);
}
