    struct hash_table* table = create_hash_table();

    // Iterate over each record in the dataset
    for (int i = 0; i < data->length; i++) {
        // Get the current record
        sensor_data* current = &data[i];

        // Check if the location name already exists in the hash table
        bool exists = false;
        struct hash_table_entry* entry = find_hash_table_entry(table, current->location_name);
        if (entry != NULL) {
            exists = true;
        }

        // If the location name does not exist in the hash table, create a new entry
        if (!exists) {
            struct hash_table_entry* new_entry = create_hash_table_entry(current->location_name);
            add_hash_table_entry(table, new_entry);
        }

        // Update the grouped data for the current location name
        entry = find_hash_table_entry(table, current->location_name);
        entry->temperature += current->temperature;
        entry->humidity += current->humidity;
        entry->wind_speed += current->wind_speed;
        entry->timestamp += current->timestamp;
        entry->data_quality |= current->data_quality;
        entry->location.geographic_id = current->location.geographic_id;
        entry->location.altitude = current->location.altitude;
        entry->sensor_type = current->sensor_type;
        entry->accuracy |= current->accuracy;
    }

    // Calculate the averages for each location name in the hash table
    struct hash_table_entry* entry;
    int i = 0;
    while ((entry = get_hash_table_entry(table, i++)) != NULL) {
        entry->temperature /= entry->length;
        entry->humidity /= entry->length;
        entry->wind_speed /= entry->length;
        entry->timestamp /= entry->length;
        entry->data_quality = (entry->data_quality == 1);
    }

    // Free the hash table
    free_hash_table(table);
}

// Function to create a new hash table entry
struct hash_table_entry* create_hash_table_entry(char* location_name) {
    struct hash_table_entry* entry = malloc(sizeof(struct hash_table_entry));
    entry->location_name = location_name;
    entry->temperature = 0.0;
    entry->humidity = 0.0;
    entry->wind_speed = 0.0;
    entry->timestamp = 0.0;
    entry->data_quality = false;
    entry->location.geographic_id = 0;
    entry->location.altitude = 0.0;
    entry->sensor_type = TEMPERATURE;
    entry->accuracy = LOW;
    return entry;
}

// Function to add a new hash table entry
void add_hash_table_entry(struct hash_table* table, struct hash_table_entry* entry) {
    // Check if the hash table is empty
    if (table->length == 0) {
        table->entries = malloc(sizeof(struct hash_table_entry));
        table->entries[0] = entry;
        table->length++;
    } else {
        // Grow the hash table by a factor of 2
        int new_size = table->length * 2;
        struct hash_table_entry** new_entries = malloc(new_size * sizeof(struct hash_table_entry));
        for (int i = 0; i < table->length; i++) {
            new_entries[i] = table->entries[i];
        }
        free(table->entries);
        table->entries = new_entries;
        table->entries[table->length++] = entry;
    }
}

// Function to find a hash table entry by location name
struct hash_table_entry* find_hash_table_entry(struct hash_table* table, char* location_name) {
    for (int i = 0; i < table->length; i++) {
        if (strcmp(location_name, table->entries[i]->location_name) == 0) {
            return table->entries[i];
        }
    }
    return NULL;
}

// Function to get a hash table entry by index
struct hash_table_entry* get_hash_table_entry(struct hash_table* table, int index) {
    if (index < 0 || index >= table->length) {
        return NULL;
    }
    return table->entries[index];
}

// Function to free a hash table
void free_hash_table(struct hash_table* table) {
    for (int i = 0; i < table->length; i++) {
        free(table->entries[i]);
    }
    free(table->entries);
}
