        records[i].key = rand_range(1, 10000);
        records[i].temperature = round((rand() % 120 - 60) / 10.0);
        records[i].humidity = (rand() % 100) / 100.0;
        records[i].wind_speed = rand_range(0, 30);
        records[i].cloud_cover = rand_range(0, 4);
        records[i].precipitation = (rand() % 2 == 0) ? true : false;
        records[i].timestamp = time(NULL) + rand_range(-5 * 365 * 86400, 5 * 365 * 86400);
        records[i].atmospheric_pressure = rand_range(900, 1100);
    }

    // Initialize the locations array with unique geographic IDs and altitudes
    for (int i = 0; i < num_records; i++) {
        locations[i].geographic_id = rand_range(1, 1000000);
        locations[i].altitude = rand_range(500, 3000);
    }
}

// Function to group the records by location name and calculate statistics
void group_records(record *records, sensor_location *locations, int num_records) {
    // Create a hash table to store the grouped records
    typedef struct {
        char location[256];
        int count;
        double avg_temperature;
        double avg_humidity;
        float avg_wind_speed;
        float avg_atmospheric_pressure;
        time_t avg_timestamp;
        float avg_cloud_cover;
        bool avg_precipitation;
    } group;
    group *groups = malloc(num_records * sizeof(group));

    // Initialize the hash table with empty groups
    for (int i = 0; i < num_records; i++) {
        strcpy(groups[i].location, "");
        groups[i].count = 0;
        groups[i].avg_temperature = 0.0;
        groups[i].avg_humidity = 0.0;
        groups[i].avg_wind_speed = 0.0;
        groups[i].avg_atmospheric_pressure = 0.0;
        groups[i].avg_timestamp = 0;
        groups[i].avg_cloud_cover = 0.0;
        groups[i].avg_precipitation = false;
    }

    // Loop through the records and update the hash table
    for (int i = 0; i < num_records; i++) {
        char *location = locations[i].location;
        group *group = NULL;
        for (int j = 0; j < num_records; j++) {
            if (strcmp(groups[j].location, location) == 0) {
                group = &groups[j];
                break;
            }
        }
        if (group == NULL) {
            // Create a new group for the location
            strcpy(groups[i].location, location);
            groups[i].count = 1;
            groups[i].avg_temperature = records[i].temperature;
            groups[i].avg_humidity = records[i].humidity;
            groups[i].avg_wind_speed = records[i].wind_speed;
            groups[i].avg_atmospheric_pressure = records[i].atmospheric_pressure;
            groups[i].avg_timestamp = records[i].timestamp;
            groups[i].avg_cloud_cover = records[i].cloud_cover;
            groups[i].avg_precipitation = records[i].precipitation;
        } else {
            // Update the existing group with the new record
            group->count++;
            group->avg_temperature += records[i].temperature;
            group->avg_humidity += records[i].humidity;
            group->avg_wind_speed += records[i].wind_speed;
            group->avg_atmospheric_pressure += records[i].atmospheric_pressure;
            group->avg_timestamp += records[i].timestamp;
            group->avg_cloud_cover += records[i].cloud_cover;
            group->avg_precipitation |= records[i].precipitation;
        }
    }

    // Compute the statistics for each group
    for (int i = 0; i < num_records; i++) {
