        free(labels[i]);
    }
    free(metrics);
    free(categories);
    free(labels);

    // Return the standard deviation value, pointers to the char category and label arrays, and the total number of successfully processed metrics as an integer
    return stddev;
}

// Define a custom method to compute the standard deviation of the float metric values efficiently
float computeStandardDeviation(Metric *metrics, char **categories, char **labels, int num_metrics) {
    // Initialize a static buffer for temporary storage of standard deviation calculations
    static float stddev_buffer[500];

    // Compute the standard deviation using the formula: stddev = sqrt(sum((x - mean)^2) / (n - 1))
    float sum = 0.0f;
    for (int i = 0; i < num_metrics; i++) {
        sum += pow((metrics[i].metric_value - computeMean(metrics, categories, labels, num_metrics)), 2);
    }
    float stddev = sqrt(sum / (num_metrics - 1));

    // Store the standard deviation in the static buffer and return it
    stddev_buffer[0] = stddev;
    return stddev_buffer[0];
}

// Define a custom method to compute the mean of the float metric values efficiently
float computeMean(Metric *metrics, char **categories, char **labels, int num_metrics) {
    // Initialize a static buffer for temporary storage of mean calculations
    static float mean_buffer[500];

    // Compute the mean using the formula: mean = sum(x) / n
    float sum = 0.0f;
    for (int i = 0; i < num_metrics; i++) {
        sum += metrics[i].metric_value;
    }
    float mean = sum / num_metrics;

    // Store the mean in the static buffer and return it
    mean_buffer[0] = mean;
    return mean_buffer[0];
}
