// Define data structures for records and nodes
typedef struct record {
    int key;
    double value;
    bool indicator;
    char* string;
} record_t;

typedef struct data_node {
    int id;
    float value;
    bool indicator;
    char* string;
    struct data_node* next;
} data_node_t;

// Define function parameters for memory allocation and initialization
void initialize_data(int num_records, int num_nodes) {
    // Allocate memory for arrays of long, int, double, and char
    long* offset_array = (long*)malloc(num_records * sizeof(long));
    int* key_array = (int*)malloc(num_records * sizeof(int));
    double* value_array = (double*)malloc(num_records * sizeof(double));
    char* indicator_array = (char*)malloc(num_records * sizeof(char));

    // Initialize arrays with random values within specified ranges
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = rand() % 1000000;
        key_array[i] = rand() % 1000000;
        value_array[i] = (double)rand() / RAND_MAX;
        indicator_array[i] = (bool)(rand() % 2);
    }

    // Allocate memory for array of records and linked list of nodes
    record_t* record_array = (record_t*)malloc(num_records * sizeof(record_t));
    data_node_t* node_list = NULL;

    // Populate records and nodes with data from external data source
    for (int i = 0; i < num_records; i++) {
        record_array[i].key = key_array[i];
        record_array[i].value = value_array[i];
        record_array[i].indicator = indicator_array[i];
        record_array[i].string = (char*)malloc(strlen("Hello, World!") + 1);
        strcpy(record_array[i].string, "Hello, World!");

        data_node_t* new_node = (data_node_t*)malloc(sizeof(data_node_t));
        new_node->id = i;
        new_node->value = value_array[i];
        new_node->indicator = indicator_array[i];
        new_node->string = (char*)malloc(strlen("Hello, World!") + 1);
        strcpy(new_node->string, "Hello, World!");
        new_node->next = node_list;
        node_list = new_node;
    }

    // Free memory for arrays and linked list of nodes
    free(offset_array);
    free(key_array);
    free(value_array);
    free(indicator_array);
    while (node_list != NULL) {
        data_node_t* temp = node_list;
        node_list = node_list->next;
        free(temp);
    }
}

