#include <math.h>

// Custom memory allocator for managing large data sets
struct MemoryAllocator {
    // Linked list of free blocks
    struct FreeBlock* free_blocks;

    // Mutex to protect concurrent access from multiple threads
    pthread_mutex_t mutex;
};

// Struct representing a free block in the memory allocator
struct FreeBlock {
    void* data;
    size_t size;
    struct FreeBlock* next;
};

// Function to allocate memory from the memory allocator
void* MemoryAllocator_Allocate(size_t size) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&allocator->mutex);

    // Search for a free block of sufficient size
    struct FreeBlock* current = allocator->free_blocks;
    while (current != NULL && current->size < size) {
        current = current->next;
    }

    // If no suitable free block is found, allocate a new one
    if (current == NULL || current->size < size) {
        void* data = malloc(size);
        if (data == NULL) {
            pthread_mutex_unlock(&allocator->mutex);
            return NULL;
        }
        struct FreeBlock* new_block = malloc(sizeof(struct FreeBlock));
        new_block->data = data;
        new_block->size = size;
        new_block->next = allocator->free_blocks;
        allocator->free_blocks = new_block;
    } else {
        // Remove the free block from the list and return it
        struct FreeBlock* removed = current;
        allocator->free_blocks = current->next;
        pthread_mutex_unlock(&allocator->mutex);
        return removed->data;
    }
}

// Function to free memory allocated by the memory allocator
void MemoryAllocator_Free(void* data) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&allocator->mutex);

    // Search for the free block containing the given data
    struct FreeBlock* current = allocator->free_blocks;
    while (current != NULL && current->data != data) {
        current = current->next;
    }

    // If the free block is found, add it to the list of free blocks
    if (current != NULL) {
        struct FreeBlock* new_block = malloc(sizeof(struct FreeBlock));
        new_block->data = data;
        new_block->size = current->size;
        new_block->next = allocator->free_blocks;
        allocator->free_blocks = new_block;
    } else {
        // If the free block is not found, add it to the list of free blocks
        struct FreeBlock* new_block = malloc(sizeof(struct FreeBlock));
        new_block->data = data;
        new_block->size = 0;
        new_block->next = allocator->free_blocks;
        allocator->free_blocks = new_block;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&allocator->mutex);
}

// Function to initialize arrays for float, char, and struct objects
void InitializeArrays(size_t size1, size_t size2, size_t size3) {
    // Allocate memory for the arrays
    float* array1 = malloc(sizeof(float) * size1);
    char* array2 = malloc(sizeof(char) * size2);
    struct Object* array3 = malloc(sizeof(struct Object) * size3);

    // Initialize the arrays with random values within a specified range
    for (int i = 0; i < size1; i++) {
        array1[i] = (float)(rand() % 1000) / 100.0f;
    }
    for (int i = 0; i < size2; i++) {
        array2[i] = 'a' + (rand() % 26);
    }
    for (int i = 0; i < size3; i++) {
        array3[i].value = (double)(rand() % 1000) / 100.0f;
        array3[i].status = rand() % 2;
    }
}

// Function to populate the event structures with data from an external source
void PopulateEvents(size_t num_events, size_t max_string_length) {
    // Allocate memory for the events
    struct Event* events = malloc(sizeof(struct Event) * num_events);

    // Initialize the events with data from an external source
    for (int i = 0; i < num_events; i++) {
        events[i].string = malloc(max_string_length + 1);
        events[i].timestamp = time(NULL);
