}

// Function to handle errors and exceptions in the program
void HandleErrors(int error_code) {
    // Log the error code and exception to a centralized logging system
    printf("Error: %d\n", error_code);
}

// Function to free memory allocated by the program
void FreeMemory() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&allocator->mutex);

    // Search for all free blocks and add them to the list of free blocks
    struct FreeBlock* current = allocator->free_blocks;
    while (current != NULL) {
        struct FreeBlock* removed = current;
        allocator->free_blocks = current->next;
        free(removed);
        current = allocator->free_blocks;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&allocator->mutex);
}
```
