// Function to allocate memory for arrays and initialize them
void init_arrays(size_t num_events, size_t max_threshold) {
    // Allocate memory for the time interval array
    double *time_intervals = (double *)malloc(num_events * sizeof(double));
    if (!time_intervals) {
        fprintf(stderr, "Error: Failed to allocate memory for time intervals\n");
        return;
    }

    // Allocate memory for the identifier array
    char **identifiers = (char **)malloc(num_events * sizeof(char *));
    if (!identifiers) {
        fprintf(stderr, "Error: Failed to allocate memory for identifiers\n");
        free(time_intervals);
        return;
    }

    // Allocate memory for the event array
    struct event *events = (struct event *)malloc(num_events * sizeof(struct event));
    if (!events) {
        fprintf(stderr, "Error: Failed to allocate memory for events\n");
        free(time_intervals);
        free(identifiers);
        return;
    }

    // Initialize the time intervals and identifiers
    for (size_t i = 0; i < num_events; i++) {
        time_intervals[i] = 0.0;
        identifiers[i] = NULL;
        events[i].timestamp = 0;
        events[i].identifier[0] = '\0';
        events[i].priority = 0;
    }

    // Initialize the event records with predefined data from an external configuration file
    FILE *config_file = fopen("config.txt", "r");
    if (config_file) {
        char line[256];
        while (fgets(line, sizeof(line), config_file)) {
            // Parse the line and validate the fields
            struct event *event = &events[i++];
            sscanf(line, "%lf %s %d", &event->timestamp, event->identifier, &event->priority);
            if (event->timestamp == 0 || strlen(event->identifier) == 0 || event->priority < 0) {
                fprintf(stderr, "Error: Invalid data in configuration file\n");
                break;
            }
        }
    } else {
        fprintf(stderr, "Error: Failed to open configuration file\n");
    }

    // Populate the event records with additional time-based events
    struct timespec start_time = {0, 0};
    struct timespec end_time = {0, 0};
    clock_gettime(CLOCK_REALTIME, &start_time);
    clock_gettime(CLOCK_REALTIME, &end_time);
    double interval = (double)(end_time.tv_sec - start_time.tv_sec) + (double)(end_time.tv_nsec - start_time.tv_nsec) / 1e9;
    for (size_t i = num_events; i < max_threshold; i++) {
        time_intervals[i] = interval;
        identifiers[i] = "event";
        events[i].timestamp = start_time.tv_sec + start_time.tv_nsec / 1e9;
        events[i].identifier[0] = 'e';
        events[i].priority = 5;
    }

    // Sort the event records based on their priority levels
    qsort(events, num_events, sizeof(struct event), compare_events);
}

// Function to free allocated memory
void free_arrays() {
    free(time_intervals);
    free(identifiers);
    free(events);
}

// Custom memory pool for managing event records
struct event_pool {
    struct event *events;
    size_t num_events;
};

// Function to allocate memory from the custom memory pool
void *event_pool_alloc(size_t size) {
    if (size > max_threshold) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return NULL;
    }
    struct event_pool *pool = malloc(sizeof(struct event_pool));
    if (!pool) {
        fprintf(stderr, "Error: Failed to allocate memory for the event pool\n");
        return NULL;
    }
    pool->events = (struct event *)malloc(size * sizeof(struct event));
    if (!pool->events) {
        fprintf(stderr, "Error: Failed to allocate memory for the event records\n");
        free(pool);
        return NULL;
    }
    pool->num_events = size;
    return pool;
}

// Function to free allocated memory from the custom memory pool
void event_pool_free(void *ptr) {
    struct event_pool *pool = ptr;
    free(pool->events);
    free(pool);
}

// Comparison function for sorting events based on their priority levels
int compare_events(const void *a, const void *b) {
    const struct event *event1 = a;
    const struct event *event2 = b;
    return (event1->priority > event2->priority) - (event1->priority < event2->priority);
}
