#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/sha.h>
#include <pthread.h>

// Define the structure for a user record
typedef struct {
    char *username;
    int id;
    Record record;
    float *floats;
} User;

// Define the function to generate a random integer within a specified range
int generate_random_integer(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Define the function to generate a random float within a specified precision range
float generate_random_float(float min, float max) {
    return ((float)generate_random_integer((int)(min * 100), (int)(max * 100))) / 100;
}

// Define the function to compute the SHA-256 hash of a given string and return it as a hexadecimal string representation
char* sha256_hash(const char* input) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, input, strlen(input));
    SHA256_Final(hash, &ctx);
    char* hex = malloc(SHA256_DIGEST_LENGTH * 2 + 1);
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        sprintf(&hex[i * 2], "%02x", hash[i]);
    }
    return hex;
}

// Define the function to allocate and initialize memory for a user record
User* create_user(const char* username, int id) {
    User* user = malloc(sizeof(User));
    user->username = strdup(username);
    user->id = id;
    user->record.integer = generate_random_integer(100, 200);
    user->record.string = "Hello World!";
    user->floats = malloc(sizeof(float) * 5);
    for (int i = 0; i < 5; ++i) {
        user->floats[i] = generate_random_float(1.0, 2.0);
    }
    return user;
}

// Define the function to add a new user record to the collection
void add_user(User* user) {
    pthread_mutex_lock(&users_mutex);
    // Check if the username is already taken
    for (int i = 0; i < users.size(); ++i) {
        if (strcmp(users[i]->username, user->username) == 0) {
            pthread_mutex_unlock(&users_mutex);
            return;
        }
    }
    // Add the new user to the collection
    users.push_back(user);
    pthread_mutex_unlock(&users_mutex);
}

// Define the function to delete a user record from the collection
void delete_user(const char* username) {
    pthread_mutex_lock(&users_mutex);
    // Find the user with the given username and remove it from the collection
    for (int i = 0; i < users.size(); ++i) {
        if (strcmp(users[i]->username, username) == 0) {
            free(users[i]);
            users.erase(users.begin() + i);
            break;
        }
    }
    pthread_mutex_unlock(&users_mutex);
}

