} transaction_t;

// Function to allocate and initialize memory for arrays of floats, IDs, and strings
void init_arrays(float** floats, unsigned short** ids, char*** descriptions, int num_transactions) {
    // Allocate memory for the float array
    *floats = (float*)malloc(num_transactions * sizeof(float));
    if (*floats == NULL) {
        printf("Error: Failed to allocate memory for float array\n");
        return;
    }

    // Initialize the float array with random values
    srand(time(NULL));
    for (int i = 0; i < num_transactions; i++) {
        (*floats)[i] = (float)rand() / RAND_MAX * 100.0;
    }

    // Allocate memory for the ID array
    *ids = (unsigned short*)malloc(num_transactions * sizeof(unsigned short));
    if (*ids == NULL) {
        printf("Error: Failed to allocate memory for ID array\n");
        return;
    }

    // Initialize the ID array with random values
    srand(time(NULL));
    for (int i = 0; i < num_transactions; i++) {
        (*ids)[i] = rand() % 10000;
    }

    // Allocate memory for the string array
    *descriptions = (char**)malloc(num_transactions * sizeof(char*));
    if (*descriptions == NULL) {
        printf("Error: Failed to allocate memory for string array\n");
        return;
    }

    // Initialize the string array with random descriptions
    srand(time(NULL));
    for (int i = 0; i < num_transactions; i++) {
        (*descriptions)[i] = malloc(10 * sizeof(char));
        if ((*descriptions)[i] == NULL) {
            printf("Error: Failed to allocate memory for string %d\n", i);
            return;
        }
        sprintf((*descriptions)[i], "Transaction %d", i);
    }
}

// Function to populate the transaction structures with data from an external source
void populate_transactions(transaction_t** transactions, int num_transactions) {
    // Allocate memory for the transaction array
    *transactions = (transaction_t*)malloc(num_transactions * sizeof(transaction_t));
    if (*transactions == NULL) {
        printf("Error: Failed to allocate memory for transaction array\n");
        return;
    }

    // Populate the transaction array with data from an external source
    srand(time(NULL));
    for (int i = 0; i < num_transactions; i++) {
        (*transactions)[i].value = (float)rand() / RAND_MAX * 100.0;
        (*transactions)[i].timestamp = time(NULL);
        (*transactions)[i].id = rand() % 10000;
        (*transactions)[i].description = malloc(10 * sizeof(char));
        if ((*transactions)[i].description == NULL) {
            printf("Error: Failed to allocate memory for transaction description\n");
            return;
        }
        sprintf((*transactions)[i].description, "Transaction %d", i);
    }
}

// Function to free allocated memory when no longer needed
void free_memory(float** floats, unsigned short** ids, char*** descriptions, transaction_t** transactions) {
    // Free the float array
    if (*floats != NULL) {
        free(*floats);
        *floats = NULL;
    }

    // Free the ID array
    if (*ids != NULL) {
        free(*ids);
        *ids = NULL;
    }

    // Free the string array
    if (*descriptions != NULL) {
        for (int i = 0; i < num_transactions; i++) {
            free((*descriptions)[i]);
        }
        free(*descriptions);
        *descriptions = NULL;
    }

    // Free the transaction array
    if (*transactions != NULL) {
        for (int i = 0; i < num_transactions; i++) {
            free((*transactions)[i].description);
        }
        free(*transactions);
        *transactions = NULL;
    }
}

// Main function to handle all tasks
void main(int argc, char** argv) {
    // Check for valid input arguments
    if (argc != 3) {
        printf("Usage: %s <number of transactions> <description length>\n", argv[0]);
        return;
    }

    // Parse the input arguments
    int num_transactions = atoi(argv[1]);
    int description_length = atoi(argv[2]);

    // Initialize arrays for floats, IDs, and strings
    float* floats = NULL;
    unsigned short* ids = NULL;
    char** descriptions = NULL;
    transaction_t* transactions = NULL;

    // Allocate memory for the arrays and initialize them with random data
    init_arrays(&floats, &ids, &descriptions, num_transactions);

    // Populate the transaction structures with data from an external source
    populate_transactions(&transactions, num_transactions);

    // Free allocated memory when no longer needed
    free_memory(&floats, &ids, &descriptions, &transactions);
}
