        readings[i].weather = (enum weather_condition)rand_range(0, 4);
        readings[i].manual_reading = (bool)(rand() % 2);
        readings[i].wind_speed = rand_range(0, 100);
        readings[i].sensor_id = i + 1;
    }

    // Initialize the arrays for location names and associated sensors
    for (int i = 0; i < num_records; i++) {
        locations[i].geographic_identifier = rand_range(1, 100);
        locations[i].altitude = rand_range(0, 10000);
        strcpy(locations[i].location, "Location ");
        strcat(locations[i].location, rand_range(1, 100));
        locations[i].associated_sensors.push_back(i + 1);
    }
}

// Function to group the entries by location name and calculate the average temperature, humidity, pressure, timestamp, sensor accuracy, wind speed, and frequency of each weather condition for each group
void group_data(struct sensor_reading *readings, struct sensor_location *locations, int num_records) {
    // Initialize the arrays for grouped data
    struct sensor_reading *grouped_readings = (struct sensor_reading *)malloc(num_records * sizeof(struct sensor_reading));
    struct sensor_location *grouped_locations = (struct sensor_location *)malloc(num_records * sizeof(struct sensor_location));

    // Loop through each record and group the entries by location name
    for (int i = 0; i < num_records; i++) {
        bool found = false;
        int j = 0;
        while (!found && j < num_records) {
            if (strcmp(readings[i].location, grouped_locations[j].location) == 0) {
                found = true;
                grouped_readings[j].offset += readings[i].offset;
                grouped_readings[j].key += readings[i].key;
                grouped_readings[j].temperature += readings[i].temperature;
                grouped_readings[j].humidity += readings[i].humidity;
                grouped_readings[j].pressure += readings[i].pressure;
                grouped_readings[j].weather = (enum weather_condition)((int)grouped_readings[j].weather + (int)readings[i].weather);
                grouped_readings[j].manual_reading += readings[i].manual_reading;
                grouped_readings[j].wind_speed += readings[i].wind_speed;
                grouped_locations[j].geographic_identifier += locations[i].geographic_identifier;
                grouped_locations[j].altitude += locations[i].altitude;
                grouped_locations[j].associated_sensors.push_back(readings[i].sensor_id);
            }
            j++;
        }
        if (!found) {
            grouped_readings[num_records - 1].offset = readings[i].offset;
            grouped_readings[num_records - 1].key = readings[i].key;
            grouped_readings[num_records - 1].temperature = readings[i].temperature;
            grouped_readings[num_records - 1].humidity = readings[i].humidity;
            grouped_readings[num_records - 1].pressure = readings[i].pressure;
            grouped_readings[num_records - 1].weather = readings[i].weather;
            grouped_readings[num_records - 1].manual_reading = readings[i].manual_reading;
            grouped_readings[num_records - 1].wind_speed = readings[i].wind_speed;
            grouped_locations[num_records - 1].geographic_identifier = locations[i].geographic_identifier;
            grouped_locations[num_records - 1].altitude = locations[i].altitude;
            grouped_locations[num_records - 1].associated_sensors.push_back(readings[i].sensor_id);
        }
    }

    // Calculate the average temperature, humidity, pressure, timestamp, sensor accuracy, wind speed, and frequency of each weather condition for each group
    for (int i = 0; i < num_records; i++) {
        grouped_readings[i].offset /= grouped_locations[i].associated_sensors.size();
        grouped_readings[i].key /= grouped_locations[i].associated_sensors.size();
        grouped_readings[i].temperature /= grouped_locations[i].associated_sensors.size();
        grouped_readings[i].humidity /= grouped_locations[i].associated_sensors.size();
        grouped_readings[i].pressure /= grouped_locations[i].associated_sensors.size();
        grouped_readings[i].weather = (enum weather_condition)((int)grouped_readings[i].weather / grouped_locations[i].associated_sensors.size());
        grouped_readings[i].manual_reading /= grouped_locations[i].associated_sensors.size();
        grouped_readings[i].wind_speed /= grouped_locations[i].associated_sensors.size();
    }
}

// Function to validate the input parameters and ensure they meet the constraints
void validate_input(struct sensor_reading *readings, struct sensor_location *locations, int num_records) {
    // Validate the number of records
    if (num_records < 1000 || num_records > 100000) {
        printf("Invalid number of records: %d\n", num_records);
        exit(1);
