            exit(1);
        }
    }

    // Validate the pressure readings
    for (int i = 0; i < num_records; i++) {
        if (readings[i].pressure <= 0 || readings[i].pressure > 1020) {
            printf("Invalid pressure reading: %f\n", readings[i].pressure);
            exit(1);
        }
    }

    // Validate the timestamps
    for (int i = 0; i < num_records; i++) {
        if (readings[i].offset < 0 || readings[i].offset > 5 * 365 * 24 * 60 * 60) {
            printf("Invalid timestamp: %ld\n", readings[i].offset);
            exit(1);
        }
    }

    // Validate the location names
    for (int i = 0; i < num_records; i++) {
        if (strlen(readings[i].location) > 256) {
            printf("Invalid location name: %s\n", readings[i].location);
            exit(1);
        }
    }

    // Validate the weather conditions
    for (int i = 0; i < num_records; i++) {
        if (readings[i].weather < SUNNY || readings[i].weather > THUNDERSTORM) {
            printf("Invalid weather condition: %d\n", readings[i].weather);
            exit(1);
        }
    }

    // Validate the wind speeds
    for (int i = 0; i < num_records; i++) {
        if (readings[i].wind_speed <= 0 || readings[i].wind_speed > 100) {
            printf("Invalid wind speed: %f\n", readings[i].wind_speed);
            exit(1);
        }
    }

    // Validate the sensor IDs
    for (int i = 0; i < num_records; i++) {
        if (readings[i].sensor_id <= 0 || readings[i].sensor_id > 100000) {
            printf("Invalid sensor ID: %d\n", readings[i].sensor_id);
            exit(1);
        }
    }
}

// Main function to demonstrate the use of the functions
