double rand_range(double min, double max) {
    return (min + (max - min) * ((double)rand() / RAND_MAX));
}

// Function to initialize a variable number of records representing environmental sensor readings
void init_records(int num_records, record* records) {
    // Validate input parameters
    if (num_records < 1000 || num_records > 100000) {
        printf("Invalid number of records: %d\n", num_records);
        return;
    }

    // Allocate memory for the records
    records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        printf("Failed to allocate memory for records\n");
        return;
    }

    // Initialize each record with random values within specified ranges
    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand() % 1000000;
        records[i].key = rand() % 1000000;
        records[i].temperature = round(rand_range(-80.0, 80.0));
        records[i].humidity = rand_range(0.0, 100.0);
        records[i].pressure = rand_range(0.0, 100000.0);
        records[i].weather = (enum weather_condition)rand() % NUM_WEATHER_CONDITIONS;
        records[i].manual_reading = (bool)(rand() % 2);
        records[i].wind_speed = rand_range(0.0, 1000.0);
        records[i].sensor_id = i + 1;
    }
}

// Function to group the entries by location name and calculate the average temperature, humidity, pressure, timestamp, sensor accuracy, wind speed, and frequency of each weather condition for each group
void group_records(int num_records, record* records) {
    // Create a map to store the grouped records
    std::map<std::string, std::vector<record>> grouped_records;

    // Iterate over the records and add them to the map
    for (int i = 0; i < num_records; i++) {
        std::string location_name = records[i].location_name;
        grouped_records[location_name].push_back(records[i]);
    }

    // Iterate over the map and calculate the average values for each group
    for (auto& [location_name, records] : grouped_records) {
        int num_records = records.size();
        double avg_temperature = 0;
        double avg_humidity = 0;
        double avg_pressure = 0;
        long avg_timestamp = 0;
        double avg_sensor_accuracy = 0;
        double avg_wind_speed = 0;
        int num_weather_conditions[NUM_WEATHER_CONDITIONS] = {0};

        // Calculate the average values for each group
        for (int i = 0; i < num_records; i++) {
            avg_temperature += records[i].temperature;
            avg_humidity += records[i].humidity;
            avg_pressure += records[i].pressure;
            avg_timestamp += records[i].offset;
            avg_sensor_accuracy += (records[i].manual_reading ? 1.0 : 0.5);
            avg_wind_speed += records[i].wind_speed;
            num_weather_conditions[records[i].weather]++;
        }

        // Calculate the average values for each group
        avg_temperature /= num_records;
        avg_humidity /= num_records;
        avg_pressure /= num_records;
        avg_timestamp /= num_records;
        avg_sensor_accuracy /= num_records;
        avg_wind_speed /= num_records;

        // Print the results for each group
        printf("Location: %s\n", location_name.c_str());
        printf("Average temperature: %.2f\n", avg_temperature);
        printf("Average humidity: %.2f\n", avg_humidity);
        printf("Average pressure: %.2f\n", avg_pressure);
        printf("Average timestamp: %ld\n", avg_timestamp);
        printf("Average sensor accuracy: %.2f\n", avg_sensor_accuracy);
        printf("Average wind speed: %.2f\n", avg_wind_speed);
        for (int i = 0; i < NUM_WEATHER_CONDITIONS; i++) {
            if (num_weather_conditions[i] > 0) {
                printf("Frequency of weather condition %d: %d\n", i, num_weather_conditions[i]);
            }
        }
    }
}
