#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    char* name;
    void* payload;
    size_t timestamp;
    int state;
} record_t;

// Define the hash table structure
typedef struct {
    pthread_mutex_t mutex;
    record_t** records;
    size_t capacity;
    size_t size;
} hash_table_t;

// Initialize a new hash table with a given capacity
hash_table_t* initialize_hash_table(size_t capacity) {
    hash_table_t* table = malloc(sizeof(hash_table_t));
    if (!table) {
        return NULL;
    }
    table->mutex = PTHREAD_MUTEX_INITIALIZER;
    table->records = calloc(capacity, sizeof(record_t*));
    if (!table->records) {
        free(table);
        return NULL;
    }
    table->capacity = capacity;
    table->size = 0;
    return table;
}

// Add a new record to the hash table
int add_record(hash_table_t* table, const char* name, void* payload, size_t timestamp, int state) {
    pthread_mutex_lock(&table->mutex);
    if (table->size >= table->capacity) {
        // The hash table is full, cannot add new records
        pthread_mutex_unlock(&table->mutex);
        return -1;
    }
    record_t* record = malloc(sizeof(record_t));
    if (!record) {
        pthread_mutex_unlock(&table->mutex);
        return -1;
    }
    record->name = strdup(name);
    record->payload = payload;
    record->timestamp = timestamp;
    record->state = state;
    table->records[table->size++] = record;
    pthread_mutex_unlock(&table->mutex);
    return 0;
}

// Update the payload, state, and timestamp of a specific record by its name
int update_record(hash_table_t* table, const char* name, void* new_payload, size_t new_timestamp, int new_state) {
    pthread_mutex_lock(&table->mutex);
    for (size_t i = 0; i < table->size; i++) {
        if (strcmp(name, table->records[i]->name) == 0) {
            record_t* record = table->records[i];
            record->payload = new_payload;
            record->timestamp = new_timestamp;
            record->state = new_state;
            pthread_mutex_unlock(&table->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&table->mutex);
    return -1;
}

// Retrieve records based on a subset of criteria such as timestamp range and state
int retrieve_records(hash_table_t* table, size_t start_timestamp, size_t end_timestamp, int state) {
    pthread_mutex_lock(&table->mutex);
    for (size_t i = 0; i < table->size; i++) {
        record_t* record = table->records[i];
        if (record->timestamp >= start_timestamp && record->timestamp <= end_timestamp && record->state == state) {
            // Do something with the retrieved records
        }
    }
    pthread_mutex_unlock(&table->mutex);
}

// Periodically clean up inactive records to optimize memory management
void cleanup_records(hash_table_t* table) {
    pthread_mutex_lock(&table->mutex);
    for (size_t i = 0; i < table->size; i++) {
        record_t* record = table->records[i];
        if (record->state == INACTIVE) {
            free(record->name);
            free(record->payload);
            table->records[i] = NULL;
            table->size--;
        }
    }
    pthread_mutex_unlock(&table->mutex);
}
```
