using namespace std;

// Define a struct to represent a customer transaction
struct Transaction {
    int id;
    string timestamp;
    double amount;
    string status;
};

// Define a vector to store all transactions
vector<Transaction> transactions;

// Define a mutex and condition variable for synchronizing access to the vector
mutex mtx;
condition_variable cv;

// Define a function to add a new transaction to the vector
void addTransaction(const Transaction& transaction) {
    unique_lock<mutex> lock(mtx);
    transactions.push_back(transaction);
    cv.notify_all();
}

// Define a function to remove a transaction from the vector by ID
void removeTransaction(int id) {
    unique_lock<mutex> lock(mtx);
    for (auto it = transactions.begin(); it != transactions.end(); ++it) {
        if (it->id == id) {
            transactions.erase(it);
            break;
        }
    }
}

// Define a function to query transactions based on ID and status
vector<Transaction> queryTransactions(int id, string status) {
    unique_lock<mutex> lock(mtx);
    vector<Transaction> result;
    for (const auto& transaction : transactions) {
        if (transaction.id == id && transaction.status == status) {
            result.push_back(transaction);
        }
    }
    return result;
}

// Define a function to query transactions based on date range and status
vector<Transaction> queryTransactions(string startDate, string endDate, string status) {
    unique_lock<mutex> lock(mtx);
    vector<Transaction> result;
    for (const auto& transaction : transactions) {
        if (transaction.timestamp >= startDate && transaction.timestamp <= endDate && transaction.status == status) {
            result.push_back(transaction);
        }
    }
    return result;
}

// Define a function to query all transactions
vector<Transaction> getAllTransactions() {
    unique_lock<mutex> lock(mtx);
    return transactions;
}

int main() {
    // Initialize the vector with some sample data
    Transaction transaction1 = { 1, "2022-01-01", 10.0, "success" };
    Transaction transaction2 = { 2, "2022-01-02", 20.0, "failure" };
    Transaction transaction3 = { 3, "2022-01-03", 30.0, "success" };
    transactions.push_back(transaction1);
    transactions.push_back(transaction2);
    transactions.push_back(transaction3);

    // Add a new transaction to the vector
    Transaction newTransaction = { 4, "2022-01-04", 40.0, "success" };
    addTransaction(newTransaction);

    // Remove a transaction from the vector by ID
    removeTransaction(3);

    // Query transactions based on ID and status
    vector<Transaction> result = queryTransactions(1, "success");
    for (const auto& transaction : result) {
        cout << transaction.id << ", " << transaction.timestamp << ", " << transaction.amount << ", " << transaction.status << endl;
    }

    // Query transactions based on date range and status
    result = queryTransactions("2022-01-02", "2022-01-03", "success");
    for (const auto& transaction : result) {
        cout << transaction.id << ", " << transaction.timestamp << ", " << transaction.amount << ", " << transaction.status << endl;
    }

    // Query all transactions
    result = getAllTransactions();
    for (const auto& transaction : result) {
        cout << transaction.id << ", " << transaction.timestamp << ", " << transaction.amount << ", " << transaction.status << endl;
    }

    return 0;
}
