#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>

// Define constants for memory allocation
#define MAX_RECORDS 5000
#define MAX_STRING_LENGTH 100
#define HASH_SIZE SHA256_DIGEST_LENGTH * 2 + 1

// Define data structures for storing records and hashes
typedef struct {
    double value;
    char string[MAX_STRING_LENGTH];
    int index;
} Record;

typedef struct {
    char hash[HASH_SIZE];
} Hash;

int processRecords(Record* records, int numRecords) {
    // Check if there is enough memory available for allocation
    if (numRecords > MAX_RECORDS) {
        printf("Error: too many records to process\n");
        return -1;
    }

    // Allocate memory for arrays of strings and indices
    char* stringArray = malloc(sizeof(char) * numRecords * MAX_STRING_LENGTH);
    int* indexArray = malloc(sizeof(int) * numRecords);
    if (stringArray == NULL || indexArray == NULL) {
        printf("Error: not enough memory to allocate arrays\n");
        return -1;
    }

    // Fill the string array with random alphanumeric strings
    srand(42); // Use a fixed seed for reproducibility
    for (int i = 0; i < numRecords; i++) {
        int length = rand() % MAX_STRING_LENGTH + 1;
        for (int j = 0; j < length; j++) {
            stringArray[i * MAX_STRING_LENGTH + j] = 'a' + rand() % 26;
        }
    }

    // Compute SHA-256 hashes of strings and store them in a new array
    Hash* hashArray = malloc(sizeof(Hash) * numRecords);
    if (hashArray == NULL) {
        printf("Error: not enough memory to allocate hash array\n");
        return -1;
    }
    for (int i = 0; i < numRecords; i++) {
        char* string = &stringArray[i * MAX_STRING_LENGTH];
        computeSHA256Hash(string, &hashArray[i].hash);
    }

    // Free memory allocated for arrays of strings and indices
    free(stringArray);
    free(indexArray);

    return numRecords;
}

// Compute SHA-256 hash of a string and store it in a buffer
void computeSHA256Hash(const char* string, char* hash) {
    // Check if there is enough memory available for hashing
    if (hash == NULL) {
        printf("Error: not enough memory to allocate hash\n");
        return;
    }

    // Compute SHA-256 hash of the string and store it in the buffer
    try {
        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        SHA256_Update(&ctx, string, strlen(string));
        SHA256_Final(hash, &ctx);
    } catch (const std::exception& e) {
        printf("Error: %s\n", e.what());
        return;
    }
}
```
