    struct Block* head; // Pointer to the first block in the linked list of allocated blocks
};

// Structure representing a single block of memory
struct Block {
    void* data; // Pointer to the start of the block
    size_t size; // Size of the block in bytes
    struct Block* next; // Pointer to the next block in the linked list
};

// Function for allocating memory using a custom memory manager
void* allocate(struct MemoryManager* mm, size_t size) {
    // Check if there is enough memory available before allocation
    if (mm->head == NULL || mm->head->size < size) {
        return NULL;
    }

    // Allocate the requested amount of memory from the first block in the linked list
    void* data = malloc(size);
    if (data == NULL) {
        return NULL;
    }

    // Update the head pointer to point to the next block in the linked list
    mm->head = mm->head->next;

    return data;
}

// Function for freeing memory using a custom memory manager
void free(struct MemoryManager* mm, void* data) {
    // Check if the data pointer is valid and points to a block in the linked list
    struct Block* block = (struct Block*)data - 1;
    if (block == NULL || block->next != mm->head) {
        return;
    }

    // Update the head pointer to point to the next block in the linked list
    mm->head = block->next;

    free(data);
}

// Function for computing the SHA-256 hash of a string
char* computeSHA256Hash(const char* str) {
    // Initialize the SHA-256 context
    SHA256_CTX ctx;
    SHA256_Init(&ctx);

    // Update the hash with the input string
    SHA256_Update(&ctx, str, strlen(str));

    // Finalize the hash and obtain the result
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_Final(hash, &ctx);

    // Convert the hash to a hexadecimal string
    char* hex = malloc(SHA256_DIGEST_LENGTH * 2 + 1);
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        sprintf(&hex[i * 2], "%02x", hash[i]);
    }

    return hex;
}

// Function for processing records and computing the SHA-256 hashes of their strings
int processRecords(struct MemoryManager* mm, int num_records) {
    // Allocate memory for the arrays
    double* doubles = allocate(mm, sizeof(double) * 10000);
    char** strings = allocate(mm, sizeof(char*) * 10000);
    int* indices = allocate(mm, sizeof(int) * 10000);

    // Check if memory allocation failed and handle the error gracefully
    if (doubles == NULL || strings == NULL || indices == NULL) {
        printf("Error: Memory allocation failed\n");
        return -1;
    }

    // Fill the arrays with random alphanumeric strings of varying lengths
    srand(42); // Use a fixed seed for reproducibility
    for (int i = 0; i < num_records; i++) {
        int length = rand() % 200 + 1;
        strings[i] = malloc(length + 1);
        if (strings[i] == NULL) {
            printf("Error: Memory allocation failed\n");
            return -1;
        }
        for (int j = 0; j < length; j++) {
            strings[i][j] = 'a' + rand() % 26;
        }
        strings[i][length] = '\0';
    }

    // Compute the SHA-256 hashes of the strings and store them in a new array
    char** sha256_hashes = allocate(mm, sizeof(char*) * num_records);
    if (sha256_hashes == NULL) {
        printf("Error: Memory allocation failed\n");
        return -1;
    }
    for (int i = 0; i < num_records; i++) {
        sha256_hashes[i] = computeSHA256Hash(strings[i]);
        if (sha256_hashes[i] == NULL) {
            printf("Error: Hashing failed\n");
            return -1;
        }
    }

    // Free the memory allocated for the arrays
    free(mm, doubles);
    free(mm, strings);
    free(mm, indices);

    return num_records;
}
