    for (int i = 0; i < node_array_size; i++) {
        preallocated_node_array[i].value = 0;
        preallocated_node_array[i].string = malloc(sizeof(char) * string_length);
        if (preallocated_node_array[i].string == NULL) {
            printf("Error: unable to allocate memory for pre-allocated node array\n");
            return;
        }
    }
    // Set values of nodes in pre-allocated node array
    for (int i = 0; i < node_array_size; i++) {
        preallocated_node_array[i].value = node_array[i].value;
        strcpy(preallocated_node_array[i].string, node_array[i].string);
    }
}

// Function to reset all node values to a default value after a specified number of iterations
void reset_values(struct node* node_array, int node_array_size) {
    // Reset values of nodes in pre-allocated node array
    for (int i = 0; i < node_array_size; i++) {
        node_array[i].value = 0;
        strcpy(node_array[i].string, "");
    }
}
```
