#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

struct node {
    unsigned long id;
    time_t timestamp;
    bool status;
};

void manage_nodes(struct node** nodes, size_t* num_nodes) {
    // Add new node to the array
    struct node* new_node = malloc(sizeof(struct node));
    if (new_node == NULL) {
        return;
    }
    new_node->id = 0;
    new_node->timestamp = time(NULL);
    new_node->status = false;
    *nodes = realloc(*nodes, (*num_nodes + 1) * sizeof(struct node));
    if (*nodes == NULL) {
        free(new_node);
        return;
    }
    (*nodes)[*num_nodes] = new_node;
    (*num_nodes)++;

    // Update timestamp for existing nodes
    for (size_t i = 0; i < *num_nodes; i++) {
        (*nodes)[i]->timestamp = time(NULL);
    }
}
