// Define the function to allocate and initialize memory for arrays
void allocate_memory(int num_double, int num_char, int num_point, int num_measurement) {
    // Allocate memory for the double precision floating-point numbers array
    double *doubles = (double *)malloc(num_double * sizeof(double));
    if (!doubles) {
        printf("Error: Failed to allocate memory for doubles\n");
        return;
    }

    // Initialize the doubles array with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_double; i++) {
        doubles[i] = rand() % 100;
    }

    // Allocate memory for the char strings array
    char **strings = (char **)malloc(num_char * sizeof(char *));
    if (!strings) {
        printf("Error: Failed to allocate memory for strings\n");
        return;
    }

    // Initialize the strings array with predefined string literals
    for (int i = 0; i < num_char; i++) {
        strings[i] = "Hello, World!";
    }

    // Allocate memory for the struct point objects array
    struct point *points = (struct point *)malloc(num_point * sizeof(struct point));
    if (!points) {
        printf("Error: Failed to allocate memory for points\n");
        return;
    }

    // Initialize the points array with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_point; i++) {
        points[i].x = rand() % 100;
        points[i].y = rand() % 100;
    }

    // Allocate memory for the measurement structures array
    measurement *measurements = (measurement *)malloc(num_measurement * sizeof(measurement));
    if (!measurements) {
        printf("Error: Failed to allocate memory for measurements\n");
        return;
    }

    // Populate the measurements array with both random floating-point values and predefined string literals
    srand(time(NULL));
    for (int i = 0; i < num_measurement; i++) {
        measurements[i].value = rand() % 100;
        strcpy(measurements[i].string, "Hello, World!");
        measurements[i].point.x = rand() % 100;
        measurements[i].point.y = rand() % 100;
    }
}

// Define the function to free allocated memory
void free_memory(double *doubles, char **strings, struct point *points, measurement *measurements) {
    // Free the doubles array
    if (doubles) {
        free(doubles);
    }

    // Free the strings array
    if (strings) {
        for (int i = 0; i < num_char; i++) {
            free(strings[i]);
        }
        free(strings);
    }

    // Free the points array
    if (points) {
        free(points);
    }

    // Free the measurements array
    if (measurements) {
        free(measurements);
    }
}

