#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the struct for storing transaction data
typedef struct {
    double float_value;
    int int_value;
    bool bool_value;
    char* string_field;
    void* transaction_id;
    void* timestamp;
} transaction_data;

// Define the enum for storing transaction statuses
typedef enum {
    SUCCESS,
    FAILURE,
    PENDING
} transaction_status;

// Define the struct for storing hash table entries
typedef struct {
    char* key;
    transaction_data value;
} hash_table_entry;

// Define the linked list node for managing hash table entries
typedef struct {
    hash_table_entry entry;
    struct node* next;
} linked_list_node;

// Define the hash function for generating unique keys
unsigned long hash(char* key) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++) != '\0') {
        hash = ((hash << 5) + hash) + c;
    }
    return hash % 1000000007;
}

// Define the collision resolution strategy using chaining with quadratic probing
void resolve_collision(linked_list_node* node, linked_list_node* new_node) {
    int i = 0;
    while (i < 10) {
        if (node->next == NULL) {
            break;
        } else {
            node = node->next;
            i++;
        }
    }
    if (i == 10) {
        printf("Collision resolution failed\n");
    } else {
        new_node->next = node->next;
        node->next = new_node;
    }
}

// Define the function for inserting a new transaction into the hash table
void insert_transaction(char* key, transaction_data value) {
    linked_list_node* new_node = malloc(sizeof(linked_list_node));
    if (new_node == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    new_node->entry.key = key;
    new_node->entry.value = value;
    unsigned long hash_value = hash(key);
    linked_list_node* node = &hash_table[hash_value];
    if (node == NULL) {
        node = malloc(sizeof(linked_list_node));
        if (node == NULL) {
            printf("Memory allocation failed\n");
            return;
        }
        node->entry.key = key;
        node->entry.value = value;
        hash_table[hash_value] = node;
    } else {
        resolve_collision(node, new_node);
    }
}

// Define the function for deleting an expired transaction from the hash table
void delete_transaction(char* key) {
    unsigned long hash_value = hash(key);
    linked_list_node* node = &hash_table[hash_value];
    if (node == NULL) {
        return;
    } else if (strcmp(node->entry.key, key) == 0) {
        free(node);
        hash_table[hash_value] = NULL;
    } else {
        linked_list_node* prev = node;
        while (prev->next != NULL && strcmp(prev->next->entry.key, key) != 0) {
            prev = prev->next;
        }
        if (strcmp(prev->next->entry.key, key) == 0) {
            linked_list_node* temp = prev->next;
            prev->next = temp->next;
            free(temp);
        }
    }
}

