// Function to populate the transaction records with additional data generated at regular intervals
void generateData(size_t startTime, size_t endTime, size_t interval) {
    // Calculate the number of transactions to be generated based on the start and end times
    size_t numTransactions = (endTime - startTime) / interval;

    // Iterate over each transaction and generate new data points
    for (size_t i = 0; i < numTransactions; i++) {
        // Generate a new transaction ID based on the current time
        int id = startTime + i * interval;

        // Generate a new numerical value based on the current time and the interval
        float value = (float)startTime + i * interval;

        // Generate a new category based on the current time and the interval
        char category[10];
        sprintf(category, "Category %d", startTime + i * interval);

        // Add the new transaction to the array of transactions
        struct Transaction* transaction = malloc(sizeof(struct Transaction));
        if (transaction == NULL) {
            printf("Error: Failed to allocate memory for transaction record\n");
            return;
        }
        transaction->id = id;
        transaction->value = value;
        strcpy(transaction->category, category);
        transaction->next = NULL;

        // Add the new transaction to the end of the linked list of transactions
        struct Transaction* currentTransaction = transactions;
        while (currentTransaction->next != NULL) {
            currentTransaction = currentTransaction->next;
        }
        currentTransaction->next = transaction;
    }
}

// Function to handle memory allocation failures gracefully
void handleMemoryAllocationFailure(const char* message) {
    printf("Error: %s\n", message);
    return;
}

// Function to free allocated memory when no longer needed
void freeArrays() {
    // Free the ID array
    free(ids);

    // Free the numerical data array
    free(values);

    // Free the category array
    free(categories);

    // Free the transaction records
    struct Transaction* currentTransaction = transactions;
    while (currentTransaction != NULL) {
        struct Transaction* nextTransaction = currentTransaction->next;
        free(currentTransaction);
        currentTransaction = nextTransaction;
    }

    // Free the audit log entries
    free(auditLog);
}
