// Define the log entry structure
struct log_entry {
    time_t timestamp;
    enum severity level;
    char* message;
    char* metadata;
};

// Define the doubly linked list node structure
struct node {
    struct log_entry* data;
    struct node* next;
    struct node* prev;
};

// Define the memory pool for allocating nodes
struct mempool {
    size_t capacity;
    size_t used;
    struct node* head;
    struct node* tail;
};

// Initialize the memory pool with a given capacity
void init_mempool(struct mempool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->used = 0;
    pool->head = NULL;
    pool->tail = NULL;
}

// Allocate a node from the memory pool
struct node* alloc_node(struct mempool* pool) {
    struct node* node = malloc(sizeof(struct node));
    if (node == NULL) {
        return NULL;
    }
    node->data = NULL;
    node->next = NULL;
    node->prev = NULL;
    pool->used++;
    return node;
}

// Free a node from the memory pool
void free_node(struct mempool* pool, struct node* node) {
    if (node == NULL) {
        return;
    }
    pool->used--;
    free(node);
}

// Insert a log entry into the doubly linked list
void insert_log_entry(struct mempool* pool, struct log_entry* entry) {
    // Allocate a new node for the entry
    struct node* node = alloc_node(pool);
    if (node == NULL) {
        return;
    }
    node->data = entry;

    // Insert the node into the list
    if (pool->head == NULL) {
        pool->head = node;
        pool->tail = node;
    } else {
        struct node* current = pool->head;
        while (current != NULL && current->data->level > entry->level) {
            current = current->next;
        }
        if (current == NULL) {
            // Insert at the end of the list
            pool->tail->next = node;
            node->prev = pool->tail;
            pool->tail = node;
        } else {
            // Insert before the current node
            node->next = current;
            node->prev = current->prev;
            current->prev = node;
            if (current == pool->head) {
                pool->head = node;
            }
        }
    }
}

// Remove a log entry from the doubly linked list
void remove_log_entry(struct mempool* pool, struct log_entry* entry) {
    // Find the node containing the entry
    struct node* current = pool->head;
    while (current != NULL && current->data != entry) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }

    // Remove the node from the list
    if (current == pool->head) {
        pool->head = current->next;
    }
    if (current == pool->tail) {
        pool->tail = current->prev;
    }
    if (current->prev != NULL) {
        current->prev->next = current->next;
    }
    if (current->next != NULL) {
        current->next->prev = current->prev;
    }

    // Free the node and its data
    free_node(pool, current);
}

// Update the external service configurations for log processing
