#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <assert.h>

// Custom memory pool for managing large allocations efficiently
struct MemoryPool {
    size_t capacity; // Total capacity of the pool in bytes
    size_t used;     // Amount of memory currently used by the pool
    void* buffer;    // Pointer to the start of the memory pool
};

// Function to allocate memory from the custom memory pool
void* mempool_alloc(struct MemoryPool* pool, size_t size) {
    if (size > pool->capacity - pool->used) {
        return NULL; // Return NULL if insufficient resources are available
    }

    void* ptr = pool->buffer + pool->used;
    pool->used += size;
    return ptr;
}

// Function to free memory from the custom memory pool
void mempool_free(struct MemoryPool* pool, void* ptr) {
    if (ptr < pool->buffer || ptr >= pool->buffer + pool->capacity) {
        return; // Ignore invalid pointers
    }

    size_t offset = ptr - pool->buffer;
    pool->used -= offset;
}

// Function to initialize the memory pool with a fixed capacity
void mempool_init(struct MemoryPool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->used = 0;
    pool->buffer = malloc(capacity);
    assert(pool->buffer != NULL); // Check for memory allocation failure
}

// Function to deinitialize the memory pool and free all allocated memory
void mempool_deinit(struct MemoryPool* pool) {
    free(pool->buffer);
    pool->buffer = NULL;
    pool->capacity = 0;
    pool->used = 0;
}

// Function to allocate memory for an array of long offsets and initialize them with random values within a specified range
void* alloc_long_offsets(size_t count, size_t min, size_t max) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    mempool_init(pool, sizeof(long) * count);

    long* offsets = (long*)mempool_alloc(pool, sizeof(long) * count);
    if (offsets == NULL) {
        return NULL; // Return NULL if memory allocation fails
    }

    for (size_t i = 0; i < count; i++) {
        offsets[i] = rand() % (max - min + 1) + min;
    }

    return offsets;
}

// Function to allocate memory for an array of int keys and initialize them with random values within a specified range
void* alloc_int_keys(size_t count, size_t min, size_t max) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    mempool_init(pool, sizeof(int) * count);

    int* keys = (int*)mempool_alloc(pool, sizeof(int) * count);
    if (keys == NULL) {
        return NULL; // Return NULL if memory allocation fails
    }

    for (size_t i = 0; i < count; i++) {
        keys[i] = rand() % (max - min + 1) + min;
    }

    return keys;
}

// Function to allocate memory for an array of record structures and initialize them with random integer values within a specified range
void* alloc_records(size_t count, size_t min, size_t max) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    mempool_init(pool, sizeof(record) * count);

    record* records = (record*)mempool_alloc(pool, sizeof(record) * count);
    if (records == NULL) {
        return NULL; // Return NULL if memory allocation fails
    }

    for (size_t i = 0; i < count; i++) {
        records[i].value = rand() % (max - min + 1) + min;
    }

    return records;
}

// Function to populate the record structures with initial data from an external data source before randomization
void populate_records(record* records, size_t count, int* keys, long* offsets) {
    // Simulate an external data source that provides a stream of integers
    int data[] = {10, 20, 30, 40, 50};
    size_t data_count = sizeof(data) / sizeof(int);

    for (size_t i = 0; i < count; i++) {
        // Handle potential mismatches between the structure of the external data and the expected internal format
        if (i >= data_count) {
            break;
        }

        records[i].value = data[i];
    }
}

// Function to randomize the record structures using a user-provided seed for reproducibility
void randomize_records(record* records, size_t count, int* keys, long* offsets) {
    srand(1234); // Use a fixed seed for reproducibility

    for (size_t i = 0; i < count; i++) {
        records[i].value = rand() % 100 + 1;
    }
}

// Function to handle memory allocation failures gracefully and log the error
void handle_memory_allocation_failure(struct MemoryPool* pool) {
    if (pool->used == pool->capacity) {
        printf("Memory allocation failed: pool is full\n");
    } else {
        printf("Memory allocation failed: unknown reason\n");
    }
}

// Function to free all allocated memory when no longer needed
void free_memory(struct MemoryPool* pool) {
    mempool_deinit(pool);
    free(pool);
}
