    int id;
    char* name;
    double price;
    int quantity;
} Product;

// Define the function to initialize the product inventory
Product* init_inventory(int numProducts) {
    // Check if the number of products is valid
    if (numProducts <= 0 || numProducts > MAX_PRODUCTS) {
        return NULL;
    }

    // Allocate memory for the arrays of IDs, names, and products
    int* ids = malloc(sizeof(int) * numProducts);
    char** names = malloc(sizeof(char*) * numProducts);
    Product* products = malloc(sizeof(Product) * numProducts);

    // Initialize the arrays with random values
    for (int i = 0; i < numProducts; i++) {
        ids[i] = rand() % MAX_PRODUCTS + 1;
        names[i] = malloc(sizeof(char) * 256);
        sprintf(names[i], "Product %d", ids[i]);
        products[i].id = ids[i];
        products[i].name = names[i];
        products[i].price = rand() % 100 + 1;
        products[i].quantity = rand() % 100 + 1;
    }

    // Return a pointer to the initialized inventory structure
    return products;
}

// Define the function to update the product inventory
void update_inventory(Product* inventory, int numProducts) {
    // Check if the number of products is valid
    if (numProducts <= 0 || numProducts > MAX_PRODUCTS) {
        return;
    }

    // Update the product quantities and prices randomly
    for (int i = 0; i < numProducts; i++) {
        inventory[i].quantity += rand() % 10 - 5;
        inventory[i].price *= 1 + (rand() % 100) / 100.0;
    }
}

// Define the function to query product details by ID
Product* get_product(int id, Product* inventory, int numProducts) {
    // Check if the number of products is valid
    if (numProducts <= 0 || numProducts > MAX_PRODUCTS) {
        return NULL;
    }

    // Search for the product with the given ID in the inventory
    for (int i = 0; i < numProducts; i++) {
        if (inventory[i].id == id) {
            return &inventory[i];
        }
    }

    // Return NULL if the product is not found
    return NULL;
}

// Define the function to manage a product inventory system that supports batch updates
void update_batch(Product* inventory, int numProducts, int* ids, int numUpdates) {
    // Check if the number of products and updates are valid
    if (numProducts <= 0 || numProducts > MAX_PRODUCTS || numUpdates <= 0) {
        return;
    }

    // Lock the inventory to prevent concurrent updates
    pthread_mutex_lock(&inventory->mutex);

    // Update the product quantities and prices for each ID in the batch
    for (int i = 0; i < numUpdates; i++) {
        int id = ids[i];
        Product* product = get_product(id, inventory, numProducts);
        if (product != NULL) {
            product->quantity += rand() % 10 - 5;
            product->price *= 1 + (rand() % 100) / 100.0;
        }
    }

    // Unlock the inventory to allow other threads to access it
    pthread_mutex_unlock(&inventory->mutex);
}

// Define the function to query product details by ID and cache recently accessed products
Product* get_product_cached(int id, Product* inventory, int numProducts) {
    // Check if the number of products is valid
    if (numProducts <= 0 || numProducts > MAX_PRODUCTS) {
        return NULL;
    }

    // Search for the product with the given ID in the cache
    Product* cachedProduct = get_product(id, inventory->cache, inventory->cacheSize);
    if (cachedProduct != NULL) {
        return cachedProduct;
    }

    // If the product is not found in the cache, search for it in the inventory
    Product* product = get_product(id, inventory, numProducts);
    if (product != NULL) {
        // Add the product to the cache if it is not already there
        add_to_cache(inventory->cache, &inventory->cacheSize, product);
        return product;
    }

    // Return NULL if the product is not found in the inventory or cache
    return NULL;
}

// Define the function to add a product to the cache
void add_to_cache(Product* cache, int* cacheSize, Product* product) {
    // Check if the cache is full
    if (*cacheSize >= MAX_PRODUCTS) {
        return;
    }

    // Add the product to the cache and update the cache size
    cache[*cacheSize] = *product;
    (*cacheSize)++;
}

// Define the function to remove a product from the cache
void remove_from_cache(Product* cache, int* cacheSize, Product* product) {
    // Check if the cache is empty
    if (*cacheSize <= 0) {
        return;
    }

    // Remove the product from the cache and update the cache size
    for (int i = 0; i < *cacheSize; i++) {
        if (&cache[i] == product) {
            memmove(&cache[i], &cache[i + 1], sizeof(Product) * (*cacheSize - i));
            (*cacheSize)--;
            return;
        }
    }
}
