    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

// Define the function to retrieve records based on their status and score range
int get_records(record_manager_t *manager, status_t ready, score_t min_score, score_t max_score) {
    // Acquire the mutex for thread-safe operations
    pthread_mutex_lock(&manager->mutex);

    // Find all records with the given status and score range
    int num_records = 0;
    for (int i = 0; i < manager->num_records; i++) {
        if (manager->records[i].ready == ready && manager->records[i].score >= min_score && manager->records[i].score <= max_score) {
            num_records++;
        }
