void init_probabilities(int numProbabilities, double* probabilities) {
    // Validate input parameters
    if (numProbabilities > MAX_PROBABILITIES) {
        numProbabilities = MAX_PROBABILITIES;
        printf("WARNING: Resizing probabilities array to maximum allowed size\n");
