        numProbabilities = 0;
        printf("ERROR: Invalid number of probabilities provided. Using default value.\n");
    }

    // Initialize probabilities array
    for (int i = 0; i < numProbabilities; i++) {
        probabilities[i] = DEFAULT_SCALE_FACTOR * ((double)rand() / RAND_MAX);
    }

    // Enforce maximum total sum of probabilities
    double totalSum = 0.0;
    for (int i = 0; i < numProbabilities; i++) {
        totalSum += probabilities[i];
        if (totalSum > MAX_SUM_PROBABILITIES) {
            printf("WARNING: Total sum of probabilities exceeds maximum allowed value. Normalizing...\n");
            for (int j = 0; j < numProbabilities; j++) {
                probabilities[j] /= totalSum;
            }
        }
    }
}

void init_weights(int numProbabilities, float* weights) {
