    // Find the product with the given ID
    for (int i = 0; i < inv->num_products; i++) {
        if (inv->ids[i] == id) {
            inv->products[i].quantity = quantity;
            inv->products[i].price = price;
            break;
        }
    }
}

// Function to remove a product from the inventory
void remove_product(struct inventory* inv, int id) {
    // Find the product with the given ID
    for (int i = 0; i < inv->num_products; i++) {
        if (inv->ids[i] == id) {
            // Remove the product from the arrays
            free(inv->names[i]);
            free(inv->products[i].description);
            memmove(&inv->ids[i], &inv->ids[i + 1], sizeof(int) * (inv->num_products - i - 1));
            memmove(&inv->names[i], &inv->names[i + 1], sizeof(char*) * (inv->num_products - i - 1));
            memmove(&inv->products[i], &inv->products[i + 1], sizeof(struct product) * (inv->num_products - i - 1));
            inv->num_products--;
            break;
        }
    }
}

