    int* ids = realloc(inv->ids, sizeof(int) * (inv->num_products + 1));
    char** names = realloc(inv->names, sizeof(char*) * (inv->num_products + 1));
    struct product* products = realloc(inv->products, sizeof(struct product) * (inv->num_products + 1));

