void cache_product(struct inventory* inv, int id) {
    // Find the product with the given ID
    for (int i = 0; i < inv->num_products; i++) {
        if (inv->ids[i] == id) {
            // Add the product to the cache
            inv->cache[id].quantity = inv->products[i].quantity;
            inv->cache[id].price = inv->products[i].price;
            inv->cache[id].description = malloc(strlen(inv->products[i].description) + 1);
            strcpy(inv->cache[id].description, inv->products[i].description);
            break;
        }
    }
}

// Function to retrieve a product's details from the cache
struct product* get_cached_product(struct inventory* inv, int id) {
