        inv->products[i].available = false;
        inv->products[i].timestamp = 0;
        inv->products[i].quantity = 0;
    }

    // Initialize the mutex for thread-safe operations
    pthread_mutex_init(&inv->mutex, NULL);
}

// Function to update the status, quantity, and timestamp of a specific product by its unique ID
void update_product(inventory_t* inv, unique_id_t id, status_t available, quantity_t quantity, timestamp_t timestamp) {
    // Lock the mutex for thread-safe operations
    pthread_mutex_lock(&inv->mutex);

    // Find the product with the given ID in the inventory
    size_t i;
    for (i = 0; i < inv->num_products; i++) {
        if (inv->products[i].id == id) {
            break;
        }
    }

    // If the product was not found, return an error
    if (i == inv->num_products) {
        printf("Error: product with ID %d not found\n", id);
        pthread_mutex_unlock(&inv->mutex);
        return;
    }

    // Update the status, quantity, and timestamp of the product
    inv->products[i].available = available;
    inv->products[i].quantity = quantity;
    inv->products[i].timestamp = timestamp;

    // Unlock the mutex for thread-safe operations
    pthread_mutex_unlock(&inv->mutex);
}

// Function to retrieve products based on their status and quantity range
void get_products(inventory_t* inv, status_t available, quantity_t min_quantity, quantity_t max_quantity) {
    // Lock the mutex for thread-safe operations
    pthread_mutex_lock(&inv->mutex);

    // Find products with the given status and quantity range in the inventory
    size_t i;
    for (i = 0; i < inv->num_products; i++) {
        if (inv->products[i].available == available && inv->products[i].quantity >= min_quantity && inv->products[i].quantity <= max_quantity) {
            break;
        }
    }

    // If no products were found, return an error
    if (i == inv->num_products) {
        printf("Error: no products with status %d and quantity range [%d, %d] found\n", available, min_quantity, max_quantity);
        pthread_mutex_unlock(&inv->mutex);
        return;
    }

    // Print the products that were found
    for (size_t j = i; j < inv->num_products; j++) {
        printf("Product %d: status=%s, quantity=%d, timestamp=%ld\n", inv->products[j].id, available ? "available" : "unavailable", inv->products[j].quantity, inv->products[j].timestamp);
