struct record {
    int value;
};

EVP_CIPHER_CTX *allocate_cipher(const char *command) {
    // Allocate memory for the offset and key arrays
    long *offset_array = malloc(sizeof(long) * 10);
    int *key_array = malloc(sizeof(int) * 10);

    // Initialize the offset and key arrays with random values
    for (int i = 0; i < 10; i++) {
        offset_array[i] = rand() % 100;
        key_array[i] = rand() % 26 + 97; // 'a' to 'z'
    }

    // Allocate memory for the record array and initialize each record with a random value
    struct record *record_array = malloc(sizeof(struct record) * 10);
    for (int i = 0; i < 10; i++) {
        record_array[i].value = rand() % 100;
    }

    // Perform the specific operation based on the command line option
    if (strcmp(command, "encrypt") == 0) {
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key_array, offset_array);
        return ctx;
    } else if (strcmp(command, "decrypt") == 0) {
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key_array, offset_array);
        return ctx;
    } else {
        // Invalid command line option
        return NULL;
    }
}
