int generate_random(int min, int max) {
    return min + (rand() % (max - min));
}

// Define the function to perform encryption in parallel using multiple threads
void* encrypt_data(void* args) {
    // Cast the arguments to the appropriate types
    char* data = (char*)args;
    int length = strlen(data);

    // Allocate memory for the encrypted data
    char* encrypted_data = malloc(length);
    if (!encrypted_data) {
        printf("Error: Failed to allocate memory for encrypted data\n");
        return NULL;
    }

    // Encrypt the data in parallel using multiple threads
    #pragma omp parallel for shared(data, length, encrypted_data)
    for (int i = 0; i < length; i++) {
        char c = data[i];
        encrypted_data[i] = c ^ AES_ENCRYPTION_KEY;
    }

    // Return the pointer to the encrypted data
    return encrypted_data;
}

