}

// Define the function to return a pointer to a cipher object encapsulating the encrypted data and any metadata needed for decryption
Cipher* encrypt(char* data, int length, int encryption_key) {
    // Allocate memory for the offset array
    long* offsets = allocate_memory(length * sizeof(long));
    if (!offsets) {
        handle_error("Failed to allocate memory for offsets");
        return NULL;
    }

    // Initialize the offset array with random values within a specified range
    #pragma omp parallel for shared(offsets, length)
    for (int i = 0; i < length; i++) {
        offsets[i] = generate_random(MIN_OFFSET, MAX_OFFSET);
    }

    // Allocate memory for the key array
    int* keys = allocate_memory(length * sizeof(int));
    if (!keys) {
        handle_error("Failed to allocate memory for keys");
        free_memory(offsets);
        return NULL;
    }

    // Initialize the key array with random values within a specified range
    #pragma omp parallel for shared(keys, length)
    for (int i = 0; i < length; i++) {
        keys[i] = generate_random(MIN_KEY, MAX_KEY);
    }

    // Allocate memory for the record array
    Record* records = allocate_memory(length * sizeof(Record));
    if (!records) {
        handle_error("Failed to allocate memory for records");
        free_memory(offsets);
        free_memory(keys);
        return NULL;
    }

    // Initialize the record array with random values within a specified range
    #pragma omp parallel for shared(records, length)
    for (int i = 0; i < length; i++) {
        records[i].value = generate_random(MIN_VALUE, MAX_VALUE);
    }

    // Perform the encryption in parallel using multiple threads
    void* encrypted_data = encrypt_data(data);
    if (!encrypted_data) {
        handle_error("Failed to encrypt data");
        free_memory(offsets);
        free_memory(keys);
        free_memory(records);
        return NULL;
    }

    // Create a cipher object encapsulating the encrypted data and any metadata needed for decryption
    Cipher* cipher = create_cipher(encrypted_data, length, offsets, keys, records);
    if (!cipher) {
        handle_error("Failed to create cipher");
        free_memory(offsets);
        free_memory(keys);
        free_memory(records);
        return NULL;
    }

    // Free the memory allocated for the offset, key, and record arrays
    free_memory(offsets);
    free_memory(keys);
    free_memory(records);

    // Return the pointer to the cipher object
    return cipher;
}
