typedef struct {
    int key;
} Record;

// Function to dynamically allocate memory for arrays of long and int values
void allocate_arrays(long *offset_arr, int *key_arr, size_t num_records) {
    // Calculate the total size required for the arrays
    size_t offset_size = sizeof(long) * num_records;
    size_t key_size = sizeof(int) * num_records;
    size_t total_size = offset_size + key_size;

    // Check if the total size exceeds system-defined limits
    assert(total_size <= SIZE_MAX);

    // Allocate memory for the arrays
    void *mem = malloc(total_size);
    if (mem == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(1);
    }

    // Initialize the offset and key arrays
    long *offset_ptr = mem;
    int *key_ptr = (int *)((char *)mem + offset_size);
    for (size_t i = 0; i < num_records; i++) {
        offset_arr[i] = offset_ptr[i];
        key_arr[i] = key_ptr[i];
    }
}

// Function to initialize an array of record structures
void allocate_records(Record *record_arr, size_t num_records) {
    // Allocate memory for the array
    Record *mem = malloc(sizeof(Record) * num_records);
    if (mem == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(1);
    }

    // Initialize the record array
    for (size_t i = 0; i < num_records; i++) {
        record_arr[i].key = i;
    }
}

// Function to handle potential synchronization issues if multiple threads are accessing the data concurrently
void synchronized_allocate_arrays(long *offset_arr, int *key_arr, size_t num_records) {
    // Use a mutex to protect the allocation function
    pthread_mutex_lock(&mutex);
    allocate_arrays(offset_arr, key_arr, num_records);
    pthread_mutex_unlock(&mutex);
}

// Function to handle potential synchronization issues if multiple threads are accessing the data concurrently
void synchronized_allocate_records(Record *record_arr, size_t num_records) {
    // Use a mutex to protect the allocation function
    pthread_mutex_lock(&mutex);
    allocate_records(record_arr, num_records);
    pthread_mutex_unlock(&mutex);
}
