using System;
using System.Security.Cryptography;
using System.Text;

namespace EncryptionLibrary
{
    public class AesCbcDecrypter
    {
        private readonly byte[] _key;
        private readonly byte[] _iv;

        public AesCbcDecrypter(byte[] key, byte[] iv)
        {
            _key = key;
            _iv = iv;
        }

        public byte[] Decrypt(byte[] ciphertext)
        {
            using (var aes = new AesCryptoServiceProvider())
            {
                aes.KeySize = 128; // default to 128-bit key size
                aes.BlockSize = 128; // default to 128-bit block size
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7; // default to PKCS7 padding

                var decryptedBytes = new byte[ciphertext.Length];
                int bytesRead = 0;
                int bytesWritten = 0;

                using (var cryptoStream = new CryptoStream(new MemoryStream(ciphertext), aes.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    while ((bytesRead = cryptoStream.Read(decryptedBytes, bytesWritten, decryptedBytes.Length - bytesWritten)) > 0)
                    {
                        bytesWritten += bytesRead;
                    }
                }

                return decryptedBytes;
            }
        }

        public byte[] Decrypt(byte[] ciphertext, int keySize, int blockSize, PaddingMode paddingMode)
        {
            using (var aes = new AesCryptoServiceProvider())
            {
                aes.KeySize = keySize;
                aes.BlockSize = blockSize;
                aes.Mode = CipherMode.CBC;
                aes.Padding = paddingMode;

                var decryptedBytes = new byte[ciphertext.Length];
                int bytesRead = 0;
                int bytesWritten = 0;

                using (var cryptoStream = new CryptoStream(new MemoryStream(ciphertext), aes.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    while ((bytesRead = cryptoStream.Read(decryptedBytes, bytesWritten, decryptedBytes.Length - bytesWritten)) > 0)
                    {
                        bytesWritten += bytesRead;
                    }
                }

                return decryptedBytes;
            }
        }
    }
}
