    if (pem_certificate == NULL) {
        free(offsets);
        free(keys);
        free(records);
        free(private_key);
        free(certificate);
        return NULL;
    }

    strcpy(pem_certificate, private_key);
    strcat(pem_certificate, certificate);

    // Free the memory allocated for the private key and certificate
    free(private_key);
    free(certificate);

    return pem_certificate;
}
