// Define the function to group and calculate statistics for each location
void group_and_calculate(record *records, size_t num_records) {
    // Create a map to store the grouped records
    std::map<std::string, std::vector<record>> grouped_records;

    // Iterate over each record and add it to the corresponding group
    for (size_t i = 0; i < num_records; i++) {
        grouped_records[records[i].location].push_back(records[i]);
    }

    // Calculate the statistics for each group
    for (auto &group : grouped_records) {
        double average_temperature = 0.0;
        double average_humidity = 0.0;
        double average_wind_speed = 0.0;
        long average_timestamp = 0;
        int num_records = group.second.size();
        for (auto &record : group.second) {
            average_temperature += record.temperature;
            average_humidity += record.humidity;
            average_wind_speed += record.wind_speed;
            average_timestamp += record.offset;
        }
        average_temperature /= num_records;
        average_humidity /= num_records;
        average_wind_speed /= num_records;
        average_timestamp /= num_records;

