            records[i].offset = decrypt(records[i].offset);
        }
    } else {
        // No command line option was provided, print an error message
        printf("Error: Invalid command line option\n");
    }
}

int main(int argc, char *argv[]) {
    // Check if the correct number of arguments were provided
    if (argc != 3) {
        printf("Usage: %s <input file> <output file>\n", argv[0]);
        return 1;
    }

    // Open the input and output files
    FILE *input_file = fopen(argv[1], "r");
    FILE *output_file = fopen(argv[2], "w");

    // Check if the input file could be opened
    if (input_file == NULL) {
        printf("Error: Could not open input file\n");
        return 1;
    }

    // Check if the output file could be opened
