        num_records++;
    }

    // Initialize the records and validate them against constraints
    init_records(records, num_records);

    // Group the entries by location name and calculate statistics for each group
    group_and_calculate(records, num_records);

    // Perform cryptographic operations based on command line options
    perform_cryptographic_operation(records, num_records);

    // Write the output file
    for (size_t i = 0; i < num_records; i++) {
        fprintf(output_file, "%ld %d %lf %s %lf %f %d %d %d %d\n", records[i].offset, records[i].key, records[i].temperature, records[i].location, records[i].humidity, records[i].wind_speed, records[i].data_quality, records[i].sensor_type, records[i].sensor_location.geographic_identifier, records[i].sensor_location.altitude, records[i].data_accuracy);
    }

    // Close the input and output files
    fclose(input_file);
    fclose(output_file);

    return 0;
}
