int processLogEntries(char *filterCriteria, int processingLimit, void (*callbackFunction)(logEntry)) {
    // Allocate memory for the arrays
    double *doubleArray = (double *)malloc(1000 * sizeof(double));
    char *charArray = (char *)malloc(200 * sizeof(char));
