        strcpy(logEntries[i].severity, "INFO");
        strcpy(logEntries[i].message, "Pending processing");
    }

    // Filter the log entries based on the filter criteria
    int filteredCount = 0;
    for (int i = 0; i < processingLimit; i++) {
        if (strcmp(filterCriteria, "ERROR") == 0 && strcmp(logEntries[i].severity, "ERROR") == 0) {
            filteredCount++;
        } else if (strcmp(filterCriteria, "DEBUG") == 0 && strcmp(logEntries[i].severity, "DEBUG") == 0) {
            filteredCount++;
        } else {
            filteredCount++;
        }
    }

    // Process the filtered log entries
    for (int i = 0; i < filteredCount; i++) {
