// Define the record structure
typedef struct {
    unique_id_t id;
    status_t status;
    timestamp_t timestamp;
    data_t data;
} record_t;

// Define the concurrent data structure
typedef struct {
    pthread_mutex_t mutex;
    int size;
    int capacity;
    record_t* records;
} concurrent_data_structure_t;

// Function to initialize the concurrent data structure
void init_concurrent_data_structure(concurrent_data_structure_t* cds, int initial_size) {
    // Allocate memory for the records array
    cds->records = (record_t*)malloc(initial_size * sizeof(record_t));
    if (!cds->records) {
        fprintf(stderr, "Error: failed to allocate memory for records\n");
        exit(1);
    }

    // Initialize the mutex and size variables
    pthread_mutex_init(&cds->mutex, NULL);
    cds->size = 0;
    cds->capacity = initial_size;
}

// Function to update the status of a record by its unique ID
void update_status(concurrent_data_structure_t* cds, unique_id_t id, status_t new_status) {
    // Lock the mutex before updating the status
    pthread_mutex_lock(&cds->mutex);

    // Find the record with the given ID and update its status
    for (int i = 0; i < cds->size; i++) {
        if (cds->records[i].id == id) {
            cds->records[i].status = new_status;
            break;
        }
    }

    // Unlock the mutex after updating the status
    pthread_mutex_unlock(&cds->mutex);
}

// Function to retrieve the unique ID of a record based on its status and data hash
unique_id_t get_record_id(concurrent_data_structure_t* cds, status_t status, data_hash_t data_hash) {
    // Lock the mutex before searching for the record
    pthread_mutex_lock(&cds->mutex);

    // Search for the record with the given status and data hash
    for (int i = 0; i < cds->size; i++) {
        if (cds->records[i].status == status && cds->records[i].data_hash == data_hash) {
            unique_id_t id = cds->records[i].id;
            pthread_mutex_unlock(&cds->mutex);
            return id;
        }
    }

    // Unlock the mutex after searching for the record
    pthread_mutex_unlock(&cds->mutex);

    // Return NULL if no matching record is found
    return NULL;
}

// Function to add a new record to the data structure
void add_record(concurrent_data_structure_t* cds, unique_id_t id, status_t status, timestamp_t timestamp, data_t data) {
    // Lock the mutex before adding the new record
    pthread_mutex_lock(&cds->mutex);

    // Check if the data structure needs to be resized
    if (cds->size == cds->capacity) {
        int new_capacity = cds->capacity * 2;
        record_t* new_records = (record_t*)realloc(cds->records, new_capacity * sizeof(record_t));
        if (!new_records) {
            fprintf(stderr, "Error: failed to resize records array\n");
            exit(1);
        }
        cds->records = new_records;
        cds->capacity = new_capacity;
    }

    // Add the new record to the data structure
    cds->records[cds->size].id = id;
    cds->records[cds->size].status = status;
    cds->records[cds->size].timestamp = timestamp;
    cds->records[cds->size].data = data;
    cds->size++;

    // Unlock the mutex after adding the new record
    pthread_mutex_unlock(&cds->mutex);
}

// Function to remove a record from the data structure
void remove_record(concurrent_data_structure_t* cds, unique_id_t id) {
    // Lock the mutex before removing the record
    pthread_mutex_lock(&cds->mutex);

    // Find the record with the given ID and remove it from the data structure
    for (int i = 0; i < cds->size; i++) {
        if (cds->records[i].id == id) {
            for (int j = i; j < cds->size - 1; j++) {
                cds->records[j] = cds->records[j + 1];
            }
            cds->size--;
            break;
        }
    }

    // Unlock the mutex after removing the record
    pthread_mutex_unlock(&cds->mutex);
}

// Function to periodically clean up records whose data size exceeds a specified threshold
void cleanup(concurrent_data_structure_t* cds, int threshold) {
    // Lock the mutex before cleaning up the records
    pthread_mutex_lock(&cds->mutex);

    // Iterate over the records and remove those whose data size exceeds the threshold
    for (int i = 0; i < cds->size; i++) {
        if (cds->records[i].data.size > threshold) {
            remove_record(cds, cds->records[i].id);
        }
    }

    // Unlock the mutex after cleaning up the records
    pthread_mutex_unlock(&cds->mutex);
}

// Function to validate the consistency of the data structure across all threads
void validate(concurrent_data_structure_t* cds) {
    // Lock the mutex before validating the data structure
    pthread_mutex_lock(&cds->mutex);

    // Iterate over the records and check for any inconsistencies
    for (int i = 0; i < cds->size; i++) {
        if (cds->records[i].status != cds->records[i].data.status) {
