using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Identity;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace CustomValidation
{
    public class UserRecord
    {
        public long Offset { get; set; }
        public int Key { get; set; }
        public int Value { get; set; }
    }

    public class CustomUserValidator<TUser> : IUserValidator<TUser> where TUser : IdentityUser
    {
        private readonly IConfiguration _configuration;
        private readonly ILogger<CustomUserValidator<TUser>> _logger;

        public CustomUserValidator(IConfiguration configuration, ILogger<CustomUserValidator<TUser>> logger)
        {
            _configuration = configuration;
            _logger = logger;
        }

        public async Task<IdentityResult> ValidateAsync(UserManager<TUser> manager, TUser user)
        {
            var usernameRegex = new Regex(_configuration["UsernameRegex"]);
            if (!usernameRegex.IsMatch(user.UserName))
            {
                _logger.LogWarning($"Invalid username: {user.UserName}");
                return IdentityResult.Failed(new IdentityError { Description = "Invalid username" });
            }

            var passwordRegex = new Regex(_configuration["PasswordRegex"]);
            if (!passwordRegex.IsMatch(user.Password))
            {
                _logger.LogWarning($"Invalid password: {user.Password}");
                return IdentityResult.Failed(new IdentityError { Description = "Invalid password" });
            }

            var usernameLength = user.UserName.Length;
            if (usernameLength < _configuration["UsernameMinLength"] || usernameLength > _configuration["UsernameMaxLength"])
            {
                _logger.LogWarning($"Invalid username length: {usernameLength}");
                return IdentityResult.Failed(new IdentityError { Description = "Invalid username length" });
            }

            var passwordLength = user.Password.Length;
            if (passwordLength < _configuration["PasswordMinLength"] || passwordLength > _configuration["PasswordMaxLength"])
            {
                _logger.LogWarning($"Invalid password length: {passwordLength}");
                return IdentityResult.Failed(new IdentityError { Description = "Invalid password length" });
            }

            var usernameHasUppercaseLetter = user.UserName.Any(c => char.IsUpper(c));
            if (!usernameHasUppercaseLetter)
            {
                _logger.LogWarning($"Username does not have an uppercase letter: {user.UserName}");
                return IdentityResult.Failed(new IdentityError { Description = "Username does not have an uppercase letter" });
            }

            var passwordHasNumber = user.Password.Any(c => char.IsDigit(c));
            if (!passwordHasNumber)
            {
                _logger.LogWarning($"Password does not have a number: {user.Password}");
                return IdentityResult.Failed(new IdentityError { Description = "Password does not have a number" });
            }

            var usernameHasSpecialCharacter = user.UserName.Any(c => char.IsSymbol(c));
            if (!usernameHasSpecialCharacter)
            {
                _logger.LogWarning($"Username does not have a special character: {user.UserName}");
                return IdentityResult.Failed(new IdentityError { Description = "Username does not have a special character" });
            }

            var passwordHasSpecialCharacter = user.Password.Any(c => char.IsSymbol(c));
            if (!passwordHasSpecialCharacter)
            {
                _logger.LogWarning($"Password does not have a special character: {user.Password}");
                return IdentityResult.Failed(new IdentityError { Description = "Password does not have a special character" });
            }

            return await Task.FromResult(IdentityResult.Success);
        }
    }

    public class CustomUserStore<TUser> : IUserStore<TUser> where TUser : IdentityUser
    {
        private readonly IConfiguration _configuration;
        private readonly ILogger<CustomUserStore<TUser>> _logger;
        private readonly List<UserRecord> _userRecords = new List<UserRecord>();

        public CustomUserStore(IConfiguration configuration, ILogger<CustomUserStore<TUser>> logger)
        {
            _configuration = configuration;
            _logger = logger;
        }

        public async Task AddAsync(TUser user)
        {
            var userRecord = new UserRecord
            {
                Offset = 0,
                Key = user.Id,
                Value = new Random().Next(_configuration["ValueMinRange"], _configuration["ValueMaxRange"])
            };

            _userRecords.Add(userRecord);
        }

        public async Task<TUser> FindByIdAsync(string userId)
        {
            var userRecord = _userRecords.FirstOrDefault(r => r.Key == int.Parse(userId));
            if (userRecord == null)
            {
                return await Task.FromResult<TUser>(null);
            }

            return await Task.FromResult(new IdentityUser
            {
                Id = userRecord.Key,
                UserName = userRecord.Value.ToString()
            });
        }

        public async Task<IList<Claim>> GetClaimsAsync(TUser user)
        {
            var claims = new List<Claim>();
            claims.Add(new Claim("username", user.UserName));
            return await Task.FromResult(claims);
        }

        public async Task RemoveAsync(TUser user)
        {
            _userRecords.RemoveAll(r => r.Key == user.Id);
        }

        public async Task UpdateAsync(TUser user)
        {
            var userRecord = _userRecords.FirstOrDefault(r => r.Key == user.Id);
            if (userRecord != null)
            {
                userRecord.Value = new Random().Next(_configuration["ValueMinRange"], _configuration["ValueMaxRange"]);
            }
        }
    }

    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
            services.AddIdentity<IdentityUser, IdentityRole>()
                .AddUserStore<CustomUserStore<IdentityUser>>()
                .AddUserValidator<CustomUserValidator<IdentityUser>>();
        }
    }
}
