        return false;
    }
    return true;
}

// Define the function to process files in the directory
void processFiles() {
    // Initialize the arrays with default values
    initArrays();

    // Validate the directory path
    if (!validateDirectoryPath(directoryPath)) {
        fprintf(stderr, "Failed to validate directory path\n");
        return;
    }

    // Open the directory stream
    DIR *dir = opendir(directoryPath);
    if (!dir) {
        fprintf(stderr, "Failed to open directory: %s\n", strerror(errno));
        return;
    }

    // Iterate over the files in the directory
    struct dirent *entry = NULL;
    while ((entry = readdir(dir))) {
        // Skip hidden files and directories
        if (entry->d_name[0] == '.') {
            continue;
        }

        // Get the file path
        char *filePath = malloc(strlen(directoryPath) + strlen(entry->d_name) + 2);
        sprintf(filePath, "%s/%s", directoryPath, entry->d_name);

        // Get the file metadata
        struct stat sb;
        if (stat(filePath, &sb)) {
            fprintf(stderr, "Failed to get file metadata: %s\n", strerror(errno));
            continue;
        }

        // Check if the file is a regular file and not a directory or link
        if (!S_ISREG(sb.st_mode)) {
            fprintf(stderr, "File is not a regular file: %s\n", filePath);
            continue;
        }

        // Check if the file size exceeds the maximum allowed size
        if (sb.st_size > MAX_FILE_SIZE) {
            fprintf(stderr, "File size exceeds maximum allowed size: %s\n", filePath);
            continue;
        }

        // Calculate the checksum of the file
        unsigned long checksum = 0;
        FILE *file = fopen(filePath, "rb");
        if (!file) {
            fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
            continue;
        }
        while (true) {
            char buffer[4096];
            size_t bytesRead = fread(buffer, 1, sizeof(buffer), file);
            if (bytesRead == 0) {
                break;
            }
            checksum += calculateChecksum(buffer, bytesRead);
        }
        fclose(file);

        // Add the file metadata to the cache
        sem_wait(&cacheSemaphore);
        pthread_mutex_lock(&cacheMutex);
        if (cache[sb.st_ino] == 0) {
            metaCache[sb.st_ino].fileSize = sb.st_size;
            metaCache[sb.st_ino].lastModified = sb.st_mtime;
            metaCache[sb.st_ino].checksum = checksum;
        }
        pthread_mutex_unlock(&cacheMutex);
        sem_post(&cacheSemaphore);
    }

    // Close the directory stream
    closedir(dir);
}

