    record_t** buckets; // An array of pointers to the records in each bucket
} hash_table_t;

// Define the function to initialize the hash table
void init_hash_table(hash_table_t* ht, int size) {
    assert(ht != NULL);
    assert(size > 0);

    // Allocate memory for the hash table and its buckets
    ht->buckets = (record_t**)malloc(sizeof(record_t*) * size);
    if (ht->buckets == NULL) {
        fprintf(stderr, "Failed to allocate memory for the hash table\n");
        exit(1);
