    if (ht->buckets[index] != NULL && strcmp(ht->buckets[index]->key, key) == 0) {
        // If there is, update the value of the existing record
        ht->buckets[index]->value = value;
    } else {
        // If there isn't, create a new record and insert it into the bucket
        record_t* new_record = (record_t*)malloc(sizeof(record_t));
        if (new_record == NULL) {
            fprintf(stderr, "Failed to allocate memory for the new record\n");
            exit(1);
        }
        new_record->key = key;
        new_record->value = value;
        ht->buckets[index] = new_record;
        ht->count++;
    }
}

// Define the function to delete a record from the data store
void delete_record(hash_table_t* ht, char* key) {
    assert(ht != NULL);
    assert(key != NULL);

    // Calculate the hash code for the key
    int hash = hash_code(key);

    // Find the bucket in the hash table where the record should be located
    int index = hash % ht->size;

    // Check if there is a record with the same key in the bucket
    if (ht->buckets[index] != NULL && strcmp(ht->buckets[index]->key, key) == 0) {
        // If there is, delete the record from the bucket
        free(ht->buckets[index]);
        ht->buckets[index] = NULL;
        ht->count--;
    }
}

// Define the function to clean up the hash table and release all allocated resources
void cleanup_hash_table(hash_table_t* ht) {
    assert(ht != NULL);

    // Free the memory for each bucket in the hash table
    for (int i = 0; i < ht->size; i++) {
        if (ht->buckets[i] != NULL) {
            free(ht->buckets[i]);
        }
    }

    // Free the memory for the hash table itself
    free(ht->buckets);
}
