#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>

// Custom object structure
typedef struct {
    double value;
    char* string;
} Object;

// Linked list node structure
typedef struct Node {
    Object obj;
    struct Node* next;
} Node;

// Linked list head pointer
Node* head = NULL;

// Mutex for synchronizing access to the linked list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate memory for an array of custom objects
Object* createObjects(int numObjects, double minValue, double maxValue) {
    // Allocate memory for the array of objects
    Object* objects = (Object*)malloc(numObjects * sizeof(Object));
    if (!objects) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize each object with a randomly generated double value and string
    for (int i = 0; i < numObjects; i++) {
        objects[i].value = minValue + ((double)rand() / RAND_MAX) * (maxValue - minValue);
        objects[i].string = (char*)malloc(1024 * sizeof(char));
        if (!objects[i].string) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
        sprintf(objects[i].string, "%f", objects[i].value);
    }

    // Return the array of objects
    return objects;
}

// Function to insert a new object into the linked list
void insertObject(Object* obj) {
    // Acquire the mutex for synchronizing access to the linked list
    pthread_mutex_lock(&mutex);

    // Create a new node for the object and add it to the end of the linked list
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    newNode->obj = *obj;
    newNode->next = NULL;
    if (head == NULL) {
        head = newNode;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    // Release the mutex for synchronizing access to the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to delete an object from the linked list
void deleteObject(int id) {
    // Acquire the mutex for synchronizing access to the linked list
    pthread_mutex_lock(&mutex);

    // Find the node corresponding to the given ID and remove it from the linked list
    Node* current = head;
    while (current != NULL) {
        if (current->obj.id == id) {
            if (current == head) {
                head = current->next;
            } else {
                Node* previous = current->previous;
                previous->next = current->next;
            }
            free(current);
            break;
        }
        current = current->next;
    }

    // Release the mutex for synchronizing access to the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve an object from the linked list
Object* getObject(int id) {
    // Acquire the mutex for synchronizing access to the linked list
    pthread_mutex_lock(&mutex);

    // Find the node corresponding to the given ID and return its object
    Node* current = head;
    while (current != NULL) {
        if (current->obj.id == id) {
            Object* obj = &(current->obj);
            pthread_mutex_unlock(&mutex);
            return obj;
        }
        current = current->next;
    }

    // Release the mutex for synchronizing access to the linked list
    pthread_mutex_unlock(&mutex);

    // Return NULL if the object is not found in the linked list
    return NULL;
}

// Function to compress an object independently
void compressObject(Object* obj) {
    // Use a data compression algorithm to reduce the size of the object's string
    int compressedSize = (int)(obj->string.size() * 0.5);
    char* compressedString = new char[compressedSize];
    for (int i = 0; i < compressedSize; i++) {
        compressedString[i] = obj->string[i];
    }
    delete[] obj->string;
    obj->string = compressedString;
}

// Function to decompress an object independently
void decompressObject(Object* obj) {
    // Use a data compression algorithm to expand the size of the object's string
    int originalSize = (int)(obj->string.size() * 2);
    char* originalString = new char[originalSize];
    for (int i = 0; i < originalSize; i++) {
        originalString[i] = obj->string[i];
    }
    delete[] obj->string;
    obj->string = originalString;
}

// Function to handle memory allocation failures gracefully
void handleMemoryAllocationFailure(const char* errorMessage) {
    fprintf(stderr, "Error: %s\n", errorMessage);
    exit(1);
}

// Function to handle invalid input strings gracefully
void handleInvalidInputString(const char* errorMessage) {
    fprintf(stderr, "Error: %s\n", errorMessage);
    return;
}

int main() {
    // Initialize the linked list head pointer
    head = NULL;

    // Create an array of custom objects with randomly generated values and strings
    int numObjects = 10;
    double minValue = -10.0;
    double maxValue = 10.0;
    Object* objects = createObjects(numObjects, minValue, maxValue);
    if (!objects) {
        handleMemoryAllocationFailure("Failed to allocate memory for the array of objects");
    }

    // Insert each object into the linked list
    for (int i = 0; i < numObjects; i++) {
        insertObject(&(objects[i]));
    }

    // Retrieve an object from the linked list and compress its string independently
    Object* obj = getObject(1);
    if (!obj) {
        handleInvalidInputString("Invalid ID provided");
    } else {
        compressObject(obj);
    }

    // Delete an object from the linked list and decompress its string independently
    deleteObject(2);
    obj = getObject(2);
    if (!obj) {
        handleInvalidInputString("Invalid ID provided");
    } else {
        decompressObject(obj);
    }

    // Clean up the linked list and free all memory allocated for the objects
    while (head != NULL) {
        Node* current = head;
        head = head->next;
        delete[] current->obj.string;
        delete current;
    }

    return 0;
}
