// Define the function to decrypt a record
int decryptRecord(const char* password, const char* salt, const unsigned char* ciphertext, size_t ciphertextLen, Record** record) {
    // Check if the input parameters are valid
    if (password == NULL || salt == NULL || ciphertext == NULL || ciphertextLen == 0 || record == NULL) {
        return ERR_INVALID_KEY;
    }

    // Derive the encryption key and IV from the password and salt using a secure KDF
    unsigned char* key = NULL;
    unsigned char* iv = NULL;
    int keyLen = 0;
    int ivLen = 0;
    if (!EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, (unsigned char*)password, strlen(password), 1000, &key, &keyLen) ||
        !EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, (unsigned char*)password, strlen(password), 1000, &iv, &ivLen)) {
        return ERR_INVALID_KEY;
    }

    // Allocate memory for the decrypted data
    unsigned char* plaintext = NULL;
    if ((plaintext = (unsigned char*)malloc(ciphertextLen)) == NULL) {
        return ERR_MEMORY_ALLOCATION;
    }

    // Initialize the AES-256-CBC cipher
    EVP_CIPHER_CTX* ctx = NULL;
    if ((ctx = EVP_CIPHER_CTX_new()) == NULL) {
        return ERR_CIPHER_INITIALIZATION;
    }
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) <= 0) {
        return ERR_DECRYPTION;
    }

    // Decrypt the ciphertext and store the result in plaintext
    if (EVP_DecryptUpdate(ctx, plaintext, &ciphertextLen, ciphertext, ciphertextLen) <= 0) {
        return ERR_DECRYPTION;
    }

    // Create a new record object and store the decrypted data in it
    *record = (Record*)malloc(sizeof(Record));
    (*record)->key = key;
    (*record)->iv = iv;
    (*record)->ciphertext = plaintext;

    // Clean up the cipher context and free the memory allocated for the decrypted data
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

