        !EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, (unsigned char*)password, strlen(password), 1000, &iv, &ivLen)) {
        return ERR_INVALID_KEY;
    }

    // Update the record with the new encryption key and IV
    record->key = key;
    record->iv = iv;

    // Clean up the cipher context and free the memory allocated for the decrypted data
    EVP_CIPHER_CTX* ctx = NULL;
    if ((ctx = EVP_CIPHER_CTX_new()) == NULL) {
        return ERR_CIPHER_INITIALIZATION;
    }
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) <= 0) {
        return ERR_DECRYPTION;
    }

    // Decrypt the ciphertext and store the result in plaintext
    if (EVP_DecryptUpdate(ctx, record->ciphertext, &record->ciphertextLen, record->ciphertext, record->ciphertextLen) <= 0) {
        return ERR_DECRYPTION;
    }

    // Clean up the cipher context and free the memory allocated for the decrypted data
    EVP_CIPHER_CTX_free(ctx);
    return 0;
