    }

    // Clean up the cipher context and free the memory allocated for the decrypted data
    EVP_CIPHER_CTX* ctx = NULL;
    if ((ctx = EVP_CIPHER_CTX_new()) == NULL) {
        return;
    }
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, record->key, record->iv) <= 0) {
        return;
    }

    // Free the memory allocated for the encryption key and IV
    OPENSSL_cleanse(record->key, record->keyLen);
    free(record->key);
    OPENSSL_cleanse(record->iv, record->ivLen);
    free(record->iv);

    // Free the memory allocated for the decrypted data
    OPENSSL_cleanse(record->ciphertext, record->ciphertextLen);
    free(record->ciphertext);

    // Clean up the cipher context and free the memory allocated for the decrypted data
    EVP_CIPHER_CTX_free(ctx);
}
