typedef struct {
    Record **records;
    size_t capacity;
    pthread_mutex_t *locks;
} HashTable;

// Initialize a new hash table with a given capacity
HashTable* init_hashtable(size_t capacity) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Failed to allocate memory for hash table\n");
        return NULL;
    }
    table->records = calloc(capacity, sizeof(Record*));
    if (!table->records) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        free(table);
        return NULL;
    }
    table->locks = malloc(sizeof(pthread_mutex_t) * capacity);
    if (!table->locks) {
        fprintf(stderr, "Failed to allocate memory for lock array\n");
        free(table->records);
        free(table);
        return NULL;
    }
    table->capacity = capacity;
    int i;
    for (i = 0; i < capacity; i++) {
        pthread_mutex_init(&table->locks[i], NULL);
    }
    return table;
}

// Insert a new record into the hash table
int insert(HashTable *table, int key, long offset) {
    if (!table || !key || !offset) {
        fprintf(stderr, "Invalid arguments\n");
        return -1;
    }
    // Calculate the index of the record in the hash table
    size_t index = key % table->capacity;
    // Lock the corresponding lock to prevent concurrent access
    pthread_mutex_lock(&table->locks[index]);
    // Check if a record with the same key already exists
    Record *record = table->records[index];
    while (record && record->key != key) {
        index++;
        index %= table->capacity;
        record = table->records[index];
    }
    // If a record with the same key already exists, update its offset value
    if (record) {
        record->offset = offset;
        pthread_mutex_unlock(&table->locks[index]);
        return 0;
    }
    // Allocate memory for the new record and initialize it with a random value
    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Failed to allocate memory for new record\n");
        pthread_mutex_unlock(&table->locks[index]);
        return -1;
    }
    new_record->key = key;
    new_record->offset = offset;
    // Insert the new record into the hash table
    table->records[index] = new_record;
    pthread_mutex_unlock(&table->locks[index]);
    return 0;
}

