        index++;
        index %= table->capacity;
        record = table->records[index];
    }
    // If a record with the same key already exists, remove it from the hash table
    if (record) {
        free(record);
        table->records[index] = NULL;
        pthread_mutex_unlock(&table->locks[index]);
        return 0;
    }
    // Otherwise, return an error code
    pthread_mutex_unlock(&table->locks[index]);
