void initMemoryPool(struct MemoryPool* pool, size_t size) {
    pool->size = size;
    pool->data = malloc(pool->size);
}

void freeMemoryPool(struct MemoryPool* pool) {
    if (pool->data != NULL) {
        free(pool->data);
    }
}

void* allocateFromPool(struct MemoryPool* pool, size_t size) {
    void* data = malloc(size);
    if (data == NULL) {
        return NULL;
    }
    memcpy(data, pool->data, size);
    pool->data += size;
    return data;
}

void deallocateFromPool(struct MemoryPool* pool, void* data) {
