Record* init_record(int min, int max) {
    // Generate a random integer between the minimum and maximum values
    int random_value = rand() % (max - min + 1) + min;

    // Allocate memory for the record structure
    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        printf("Error: Failed to allocate memory for new record\n");
        return NULL;
    }

    // Initialize the key and encrypted data fields of the record
    new_record->key = random_value;
    new_record->encrypted_data = malloc(sizeof(unsigned char) * 16);
    if (!new_record->encrypted_data) {
        printf("Error: Failed to allocate memory for encrypted data\n");
        free(new_record);
        return NULL;
    }

    // Encrypt the random integer using AES-256-GCM
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        printf("Error: Failed to create cipher context\n");
        free(new_record->encrypted_data);
        free(new_record);
        return NULL;
