    // Set the key length and IV length based on user input parameters
    int key_len = 32;
    int iv_len = 16;

    // Derive a 256-bit encryption key and a unique initialization vector (IV) from a given password using a secure key derivation function (KDF)
    unsigned char *key = malloc(sizeof(unsigned char) * key_len);
    if (!key) {
        printf("Error: Failed to allocate memory for encryption key\n");
        EVP_CIPHER_CTX_free(ctx);
        free(new_record->encrypted_data);
        free(new_record);
        return NULL;
