// Function to update the value of a record using its key, ensuring that updates are atomic and do not affect other records during the update process
void update_record(HashTable *hash_table, int key, int new_value) {
    // Find the index of the record with the given key in the hash table
    int index = -1;
    for (int i = 0; i < hash_table->size; i++) {
        if (hash_table->records[i]->key == key) {
            index = i;
            break;
        }
    }

    // If the record was not found, return an error message
    if (index == -1) {
        printf("Error: Record with key %d not found\n", key);
        return;
    }

    // Update the value of the record and encrypt it using AES-256-GCM
    hash_table->records[index]->key = new_value;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        printf("Error: Failed to create cipher context\n");
        return;
    }

    // Set the key length and IV length based on user input parameters
    int key_len = 32;
    int iv_len = 16;

    // Derive a 256-bit encryption key and a unique initialization vector (IV) from a given password using a secure key derivation function (KDF)
    unsigned char *key = malloc(sizeof(unsigned char) * key_len);
    if (!key) {
        printf("Error: Failed to allocate memory for encryption key\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Generate a random salt to enhance security
    unsigned char *salt = malloc(sizeof(unsigned char) * 16);
    if (!salt) {
        printf("Error: Failed to allocate memory for salt\n");
        free(key);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Use the KDF to derive a 256-bit encryption key and a unique initialization vector (IV) from the given password
    if (!EVP_BytesToKey(EVP_aes_256_gcm(), EVP_sha256(), salt, key, key_len)) {
        printf("Error: Failed to derive encryption key and IV\n");
        free(salt);
        free(key);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Encrypt the new value using AES-256-GCM with the derived key and IV
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
        printf("Error: Failed to initialize encryption context\n");
        free(salt);
        free(key);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Encrypt the new value using AES-256-GCM with the derived key and IV
    if (!EVP_EncryptUpdate(ctx, hash_table->records[index]->encrypted_data, &len, (unsigned char *)&new_value, sizeof(int))) {
        printf("Error: Failed to encrypt data\n");
        free(salt);
        free(key);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Free the memory allocated for the salt and key
    free(salt);
    free(key);

    // Return the updated record
    return hash_table->records[index];
}

// Function to decrypt the encrypted byte sequence in each record using the same key and IV used for encryption
void* decrypt_record(HashTable *hash_table, int index) {
    // If the record was not found, return an error message
    if (index < 0 || index >= hash_table->size) {
        printf("Error: Record with index %d not found\n", index);
        return NULL;
    }

    // Decrypt the encrypted data using AES-256-GCM with the derived key and IV
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
