    if (!salt) {
        printf("Error: Failed to allocate memory for salt\n");
        free(key);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Use the KDF to derive a 256-bit encryption key and a unique initialization vector (IV) from the given password
    if (!EVP_BytesToKey(EVP_aes_256_gcm(), EVP_sha256(), salt, key, key_len)) {
        printf("Error: Failed to derive encryption key and IV\n");
        free(salt);
        free(key);
        EVP_CIPHER_CTX_free(ctx);
