        free(salt);
        free(key);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Free the memory allocated for the salt and key
    free(salt);
    free(key);

    // Return the decrypted record
    return hash_table->records[index];
}

