struct MemoryPool {
    size_t capacity; // Total capacity of the memory pool
    size_t used;     // Amount of memory currently in use
    void* data;      // Pointer to the start of the memory pool
};

// Function to allocate and initialize a new memory pool with the given capacity
struct MemoryPool* createMemoryPool(size_t capacity) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) {
        fprintf(stderr, "Error: Failed to allocate memory for memory pool\n");
        return NULL;
    }
    pool->capacity = capacity;
    pool->used = 0;
    pool->data = malloc(capacity);
    if (!pool->data) {
        fprintf(stderr, "Error: Failed to allocate memory for memory pool\n");
        free(pool);
        return NULL;
    }
    return pool;
}

// Function to release a memory pool and its associated resources
void destroyMemoryPool(struct MemoryPool* pool) {
    if (pool) {
        free(pool->data);
        free(pool);
    }
}

// Function to allocate memory from a memory pool
void* allocateFromPool(struct MemoryPool* pool, size_t size) {
    void* ptr = NULL;
    if (pool && pool->used + size <= pool->capacity) {
        ptr = pool->data + pool->used;
        pool->used += size;
    } else {
        fprintf(stderr, "Error: Memory pool exhausted\n");
    }
    return ptr;
}

// Function to deallocate memory from a memory pool
void deallocateFromPool(struct MemoryPool* pool, void* ptr) {
    if (pool && ptr >= pool->data && ptr < pool->data + pool->capacity) {
        size_t offset = ptr - pool->data;
        pool->used -= offset;
    } else {
        fprintf(stderr, "Error: Invalid memory deallocation\n");
    }
}

