    }
    table->size = size;
    table->buckets = malloc(sizeof(struct Bucket*) * size);
    if (!table->buckets) {
        fprintf(stderr, "Error: Failed to allocate memory for hash table buckets\n");
        free(table);
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        table->buckets[i] = NULL;
    }
    return table;
}

// Function to release a hash table and its associated resources
void destroyHashTable(struct HashTable* table) {
    if (table) {
        for (int i = 0; i < table->size; i++) {
            struct Bucket* bucket = table->buckets[i];
            while (bucket) {
                struct Bucket* next = bucket->next;
                free(bucket);
                bucket = next;
            }
        }
        free(table->buckets);
        free(table);
    }
}

// Function to insert a new record into the hash table
void insertRecord(struct HashTable* table, int key, struct Record* record) {
    if (!table || !record) {
        return;
    }
    size_t index = key % table->size;
    struct Bucket* bucket = table->buckets[index];
    while (bucket && bucket->key != key) {
        bucket = bucket->next;
    }
    if (!bucket) {
        bucket = malloc(sizeof(struct Bucket));
        if (!bucket) {
            fprintf(stderr, "Error: Failed to allocate memory for hash table bucket\n");
            return;
        }
        bucket->key = key;
        bucket->record = record;
        bucket->next = table->buckets[index];
        table->buckets[index] = bucket;
    } else {
        fprintf(stderr, "Error: Key already exists in hash table\n");
    }
}

// Function to retrieve a record from the hash table
