// Define a record structure for storing integer values
typedef struct {
    int value;
} Record;

// Define a hash table structure for storing records
typedef struct {
    Record** records; // Array of pointers to records
    size_t capacity; // Capacity of the hash table
    size_t count; // Number of records in the hash table
    float loadFactor; // Load factor of the hash table
} HashTable;

// Define a mutex lock for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a new hash table with a specified capacity and load factor
HashTable* initHashTable(size_t capacity, float loadFactor) {
    HashTable* ht = malloc(sizeof(HashTable));
    if (!ht) {
        fprintf(stderr, "Error: Failed to allocate memory for hash table\n");
        return NULL;
    }
    ht->records = calloc(capacity, sizeof(Record*));
    if (!ht->records) {
        fprintf(stderr, "Error: Failed to allocate memory for record array\n");
        free(ht);
        return NULL;
    }
    ht->capacity = capacity;
    ht->count = 0;
    ht->loadFactor = loadFactor;
    return ht;
}

// Function to insert a new record into the hash table
int insertRecord(HashTable* ht, int key, int value) {
    // Acquire lock for thread safety
    pthread_mutex_lock(&lock);

    // Check if the hash table is full and needs to be resized
    if (ht->count >= ht->capacity * ht->loadFactor) {
        resizeHashTable(ht, 2 * ht->capacity);
    }

    // Calculate the index of the record in the hash table
    size_t index = key % ht->capacity;

    // Check if a record with the same key already exists
    while (ht->records[index] != NULL && ht->records[index]->key != key) {
        index = (index + 1) % ht->capacity;
    }

    // If no record with the same key exists, create a new one and insert it into the hash table
    if (ht->records[index] == NULL) {
        Record* rec = malloc(sizeof(Record));
        if (!rec) {
            fprintf(stderr, "Error: Failed to allocate memory for record\n");
            pthread_mutex_unlock(&lock);
            return -1;
        }
        rec->key = key;
        rec->value = value;
        ht->records[index] = rec;
        ht->count++;
    } else { // If a record with the same key already exists, update its value
        ht->records[index]->value = value;
    }

    // Release lock for thread safety
    pthread_mutex_unlock(&lock);

    return 0;
}

// Function to retrieve a record from the hash table by key
Record* getRecord(HashTable* ht, int key) {
    // Acquire lock for thread safety
    pthread_mutex_lock(&lock);

    // Calculate the index of the record in the hash table
    size_t index = key % ht->capacity;

    // Check if a record with the same key exists
    while (ht->records[index] != NULL && ht->records[index]->key != key) {
        index = (index + 1) % ht->capacity;
    }

    // If no record with the same key exists, return NULL
    if (ht->records[index] == NULL) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Return a copy of the record
    Record* rec = malloc(sizeof(Record));
    memcpy(rec, ht->records[index], sizeof(Record));

    // Release lock for thread safety
    pthread_mutex_unlock(&lock);

    return rec;
}

// Function to update the value of a record in the hash table by key
int updateRecord(HashTable* ht, int key, int value) {
    // Acquire lock for thread safety
    pthread_mutex_lock(&lock);

    // Calculate the index of the record in the hash table
    size_t index = key % ht->capacity;

    // Check if a record with the same key exists
    while (ht->records[index] != NULL && ht->records[index]->key != key) {
        index = (index + 1) % ht->capacity;
    }

    // If no record with the same key exists, return an error code
    if (ht->records[index] == NULL) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    // Update the value of the record
    ht->records[index]->value = value;

    // Release lock for thread safety
    pthread_mutex_unlock(&lock);

    return 0;
}

// Function to resize the hash table when it becomes full
void resizeHashTable(HashTable* ht, size_t newCapacity) {
    // Acquire lock for thread safety
    pthread_mutex_lock(&lock);

    // Create a new array of pointers to records with the new capacity
    Record** newRecords = calloc(newCapacity, sizeof(Record*));
    if (!newRecords) {
        fprintf(stderr, "Error: Failed to allocate memory for record array\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Copy the records from the old hash table to the new one
    size_t i = 0;
    while (i < ht->capacity) {
        if (ht->records[i] != NULL) {
            Record* rec = malloc(sizeof(Record));
            memcpy(rec, ht->records[i], sizeof(Record));
            newRecords[rec->key % newCapacity] = rec;
        }
        i++;
    }

    // Free the old array of pointers to records and assign the new one
    free(ht->records);
    ht->records = newRecords;
    ht->capacity = newCapacity;

    // Release lock for thread safety
    pthread_mutex_unlock(&lock);
}

// Function to clean up the hash table and free all allocated memory
void cleanupHashTable(HashTable* ht) {
    // Acquire lock for thread safety
    pthread_mutex_lock(&lock);

    // Free each record in the hash table
    size_t i = 0;
    while (i < ht->capacity) {
        if (ht->records[i] != NULL) {
            free(ht->records[i]);
        }
        i++;
    }

    // Free the array of pointers to records and the hash table structure itself
    free(ht->records);
    free(ht);

    // Release lock for thread safety
    pthread_mutex_unlock(&lock);
}
