#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Define the hash table structure
typedef struct {
    Record** records;
    size_t capacity;
    size_t size;
    float load_factor;
    pthread_mutex_t* mutexes;
} HashTable;

// Initialize a new hash table with the given capacity and load factor
HashTable* init_hash_table(size_t capacity, float load_factor) {
    // Allocate memory for the hash table structure
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Error: Failed to allocate memory for hash table\n");
        return NULL;
    }

    // Initialize the hash table fields
    table->records = calloc(capacity, sizeof(Record*));
    if (!table->records) {
        fprintf(stderr, "Error: Failed to allocate memory for record array\n");
        free(table);
        return NULL;
    }
    table->capacity = capacity;
    table->size = 0;
    table->load_factor = load_factor;

    // Allocate memory for the mutexes
    size_t num_mutexes = (size_t)(table->capacity / table->load_factor);
    table->mutexes = calloc(num_mutexes, sizeof(pthread_mutex_t));
    if (!table->mutexes) {
        fprintf(stderr, "Error: Failed to allocate memory for mutex array\n");
        free(table->records);
        free(table);
        return NULL;
    }

    // Initialize the mutexes
    for (size_t i = 0; i < num_mutexes; i++) {
        pthread_mutex_init(&table->mutexes[i], NULL);
    }

    return table;
}

// Insert a new record into the hash table with the given key and value
int insert(HashTable* table, int key, int value) {
    // Check if the table is full
    if (table->size >= table->capacity) {
        fprintf(stderr, "Error: Hash table is full\n");
        return -1;
    }

    // Generate a random index for the new record
    size_t index = rand() % table->capacity;

    // Lock the mutex for the corresponding bucket
    pthread_mutex_lock(&table->mutexes[index]);

    // Check if there is already a record with the same key
    Record* existing_record = find(table, key);
    if (existing_record) {
        // Update the value of the existing record
        existing_record->value = value;
        pthread_mutex_unlock(&table->mutexes[index]);
        return 0;
    }

    // Allocate memory for the new record
    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Error: Failed to allocate memory for new record\n");
        pthread_mutex_unlock(&table->mutexes[index]);
        return -1;
    }

    // Initialize the new record with the given key and value
    new_record->key = key;
    new_record->value = value;

    // Insert the new record into the hash table
    table->records[index] = new_record;
    table->size++;

    pthread_mutex_unlock(&table->mutexes[index]);

    return 0;
}

// Find a record in the hash table with the given key
Record* find(HashTable* table, int key) {
    // Generate a random index for the search
    size_t index = rand() % table->capacity;

    // Lock the mutex for the corresponding bucket
    pthread_mutex_lock(&table->mutexes[index]);

    // Check if there is already a record with the same key
    Record* existing_record = find_in_bucket(table, index, key);
    if (existing_record) {
        pthread_mutex_unlock(&table->mutexes[index]);
        return existing_record;
    }

    // Check the next bucket in the chain
    size_t next_index = (index + 1) % table->capacity;
    Record* next_record = find_in_bucket(table, next_index, key);
    if (next_record) {
        pthread_mutex_unlock(&table->mutexes[index]);
        return next_record;
    }

    // No record found
    pthread_mutex_unlock(&table->mutexes[index]);
    return NULL;
}

// Find a record in the hash table with the given key, starting from the given bucket
Record* find_in_bucket(HashTable* table, size_t index, int key) {
    // Check if there is already a record with the same key
    Record* existing_record = table->records[index];
    while (existing_record && existing_record->key != key) {
        // Move to the next record in the chain
        index = (index + 1) % table->capacity;
        existing_record = table->records[index];
    }

    return existing_record;
}

// Update the value of a record with the given key
int update(HashTable* table, int key, int new_value) {
    // Find the record with the given key
    Record* record = find(table, key);
    if (!record) {
        fprintf(stderr, "Error: No record found with key %d\n", key);
        return -1;
    }

    // Lock the mutex for the corresponding bucket
    pthread_mutex_lock(&table->mutexes[index]);

    // Update the value of the record
    record->value = new_value;

    pthread_mutex_unlock(&table->mutexes[index]);

    return 0;
}

// Clean up the hash table and free all allocated memory
void cleanup(HashTable* table) {
    // Free the record array
    for (size_t i = 0; i < table->capacity; i++) {
        Record* record = table->records[i];
        if (record) {
            free(record);
        }
    }
    free(table->records);

    // Free the mutex array
    for (size_t i = 0; i < table->capacity / table->load_factor; i++) {
        pthread_mutex_destroy(&table->mutexes[i]);
    }
    free(table->mutexes);

    // Free the hash table structure
    free(table);
}
```
This code implements a hash table that dynamically allocates memory for a variable number of `record` structures, where each `record` contains a single `int` value. The hash table uses chaining for collision resolution and maintains a hash table for quick lookup of records based on their key values. The hash table is optimized for both insertions and lookups, considering the expected load factor and the need for efficient memory usage.

The function `init_hash_table` initializes a new hash table with the given capacity and load factor. It allocates memory for the hash table structure, the record array, and the mutex array, and initializes the fields of the hash table. The function returns a pointer to the initialized hash table on success, or `NULL` on failure.

The function `insert` inserts a new record into the hash table with the given key and value. It generates a random index for the new record, locks the mutex for the corresponding bucket, checks if there is already a record with the same key, updates the value of the existing record if necessary, or allocates memory for the new record and inserts it into the hash table. The function returns `0` on success, or `-1` on failure.

The function `find` finds a record in the hash table with the given key. It generates a random index for the search, locks the mutex for the corresponding bucket, checks if there is already a record with the same key, and returns the existing record if found. If no record is found, it checks the next bucket in the chain and returns the existing record if found. The function returns `NULL` if no record is found.

The function `update` updates the value of a record with the given key. It finds the record with the given key, locks the mutex for the corresponding bucket, updates the value of the record, and unlocks the mutex. The function returns `0` on success, or `-1` on failure.

The function `cleanup` cleans up the hash table and frees all allocated memory. It frees the record array, the mutex array, and the hash table structure.

This implementation handles memory allocation failures gracefully by logging an error message and returning an appropriate status code. It also optimizes the hash table for performance under high concurrency and variable workloads, considering the impact of hash table resizing on memory usage and lock contention. The function supports a configuration option to tune the load factor and initial table size, allowing for customization based on expected workloads. This will require careful analysis of the expected data distribution and access patterns to achieve optimal performance.

Furthermore, this implementation handles edge cases such as zero or negative capacity configurations, invalid key ranges, and extreme workloads that may stress the system. It also supports a mode that periodically checks for and repairs inconsistencies in the hash table, ensuring data integrity even in the face of transient errors.']

