// Initialize the hash table with a given number of records and range for random value generation
void initialize_hash_table(hash_table* ht, size_t N, int min, int max) {
    // Allocate memory for the hash table
    ht->records = (record**)malloc(N * sizeof(record*));
    if (!ht->records) {
        printf("Error: Failed to allocate memory for hash table\n");
        return;
    }
    // Initialize the capacity and size of the hash table
    ht->capacity = N;
    ht->size = 0;
    // Seed the random number generator
    srand(time(NULL));
    // Iterate over each record in the hash table
    for (size_t i = 0; i < N; i++) {
        // Allocate memory for the record
        ht->records[i] = (record*)malloc(sizeof(record));
        if (!ht->records[i]) {
            printf("Error: Failed to allocate memory for record %zu\n", i);
            return;
        }
        // Generate a random value within the specified range
        int rand_value = min + (rand() % (max - min));
        // Set the value, timestamp, and status of the record
        ht->records[i]->value = rand_value;
        ht->records[i]->timestamp = time(NULL);
        ht->records[i]->status = 'A';
    }
}

// Update a record in the hash table using its key, ensuring updates are atomic and do not interfere with other records
void update_record(hash_table* ht, size_t key, int value) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&ht->mutex);
    // Check if the record exists in the hash table
    if (key < ht->capacity && ht->records[key]) {
        // Update the value of the record
        ht->records[key]->value = value;
    } else {
        printf("Error: Record with key %zu does not exist in hash table\n", key);
    }
    // Release the lock on the mutex
    pthread_mutex_unlock(&ht->mutex);
}

// Look up a record in the hash table using its key, returning the value and timestamp of the record
int lookup_record(hash_table* ht, size_t key) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&ht->mutex);
    // Check if the record exists in the hash table
    if (key < ht->capacity && ht->records[key]) {
        // Return the value and timestamp of the record
        return ht->records[key]->value;
    } else {
        printf("Error: Record with key %zu does not exist in hash table\n", key);
        return -1;
    }
    // Release the lock on the mutex
    pthread_mutex_unlock(&ht->mutex);
}

// Deallocate memory for the hash table and its records
void deallocate_hash_table(hash_table* ht) {
    // Iterate over each record in the hash table
    for (size_t i = 0; i < ht->capacity; i++) {
        if (ht->records[i]) {
            free(ht->records[i]);
        }
    }
    // Deallocate memory for the hash table
    free(ht->records);
}
