// Define the hash table data structure
typedef struct {
    Record **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t *locks;
} HashTable;

// Function to initialize a new hash table with a given capacity and load factor
HashTable* init_hash_table(size_t capacity, float load_factor) {
    // Allocate memory for the hash table data structure
    HashTable *ht = malloc(sizeof(HashTable));
    if (!ht) {
        fprintf(stderr, "Error: failed to allocate memory for hash table\n");
        return NULL;
    }

    // Initialize the hash table fields
    ht->records = calloc(capacity, sizeof(Record*));
    ht->capacity = capacity;
    ht->size = 0;

    // Allocate memory for the locks array
    size_t lock_count = (size_t)(load_factor * capacity);
    ht->locks = calloc(lock_count, sizeof(pthread_mutex_t));
    if (!ht->locks) {
        fprintf(stderr, "Error: failed to allocate memory for locks\n");
        free(ht);
        return NULL;
    }

    // Initialize the locks
    for (size_t i = 0; i < lock_count; i++) {
        pthread_mutex_init(&ht->locks[i], NULL);
    }

    return ht;
}

// Function to insert a new record into the hash table
int insert(HashTable *ht, int key, int value) {
    // Check if the hash table is full
    if (ht->size >= ht->capacity) {
        fprintf(stderr, "Error: hash table is full\n");
        return -1;
    }

    // Generate a random index for the new record
    size_t idx = rand() % ht->capacity;

    // Lock the corresponding lock to prevent race conditions
    pthread_mutex_lock(&ht->locks[idx]);

    // Check if there is already a record with the same key
    for (size_t i = 0; i < ht->size; i++) {
        if (ht->records[i]->key == key) {
            fprintf(stderr, "Error: duplicate key\n");
            pthread_mutex_unlock(&ht->locks[idx]);
            return -1;
        }
    }

    // Allocate memory for the new record
    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Error: failed to allocate memory for new record\n");
        pthread_mutex_unlock(&ht->locks[idx]);
        return -1;
    }

    // Initialize the new record with the given key and value
    new_record->key = key;
    new_record->value = value;

    // Insert the new record into the hash table
    ht->records[idx] = new_record;
    ht->size++;

    // Unlock the corresponding lock
    pthread_mutex_unlock(&ht->locks[idx]);

    return 0;
}

// Function to update a record in the hash table
int update(HashTable *ht, int key, int value) {
    // Check if the hash table is empty
    if (ht->size == 0) {
        fprintf(stderr, "Error: hash table is empty\n");
        return -1;
    }

    // Generate a random index for the record to be updated
    size_t idx = rand() % ht->capacity;

    // Lock the corresponding lock to prevent race conditions
    pthread_mutex_lock(&ht->locks[idx]);

    // Check if there is already a record with the same key
    for (size_t i = 0; i < ht->size; i++) {
        if (ht->records[i]->key == key) {
            // Update the value of the existing record
            ht->records[i]->value = value;
            break;
        }
    }

    // Unlock the corresponding lock
    pthread_mutex_unlock(&ht->locks[idx]);

    return 0;
}

// Function to retrieve a record from the hash table
int get(HashTable *ht, int key) {
    // Check if the hash table is empty
    if (ht->size == 0) {
        fprintf(stderr, "Error: hash table is empty\n");
        return -1;
    }

    // Generate a random index for the record to be retrieved
    size_t idx = rand() % ht->capacity;

    // Lock the corresponding lock to prevent race conditions
    pthread_mutex_lock(&ht->locks[idx]);

    // Check if there is already a record with the same key
    for (size_t i = 0; i < ht->size; i++) {
        if (ht->records[i]->key == key) {
            // Return the value of the existing record
            pthread_mutex_unlock(&ht->locks[idx]);
            return ht->records[i]->value;
        }
    }

    // Unlock the corresponding lock
    pthread_mutex_unlock(&ht->locks[idx]);

    fprintf(stderr, "Error: key not found\n");
    return -1;
}

// Function to clean up the hash table and free all allocated memory
void cleanup(HashTable *ht) {
    // Lock all locks to prevent race conditions
    for (size_t i = 0; i < ht->capacity; i++) {
        pthread_mutex_lock(&ht->locks[i]);
    }

    // Free the records and locks
    for (size_t i = 0; i < ht->capacity; i++) {
        free(ht->records[i]);
        pthread_mutex_destroy(&ht->locks[i]);
    }

    // Free the hash table data structure
    free(ht);
}
