    if (entry == NULL) {
        printf("Memory allocation failed\n");
        return -1;
    }

    // Initialize the entry with the task information
    init_task(&entry->task, task->name, task->expression);

    // Add the entry to the hash table
    int index = hash(task->id) % hash_table->size;
    entry->next = hash_table->entries[index];
    hash_table->entries[index] = entry;

    return 0;
}

// Define the function to find a task in the hash table
HashEntry *find_task(struct hash_table *hash_table, int id) {
    // Calculate the index of the task in the hash table
    int index = hash(id) % hash_table->size;

    // Search for the task in the hash table
    HashEntry *entry = hash_table->entries[index];
    while (entry != NULL && entry->task.id != id) {
        entry = entry->next;
    }

    return entry;
}

