int remove_task(struct hash_table *hash_table, int id) {
    // Find the task in the hash table
    HashEntry *entry = find_task(hash_table, id);
    if (entry == NULL) {
        return 1;
    }

    // Remove the entry from the hash table
    int index = hash(id) % hash_table->size;
    if (entry == hash_table->entries[index]) {
        hash_table->entries[index] = entry->next;
    } else {
        HashEntry *prev = hash_table->entries[index];
        while (prev->next != entry) {
            prev = prev->next;
        }
        prev->next = entry->next;
    }

    // Free the memory allocated for the task
    free(entry);

    return 0;
}

// Define the function to update a task in the hash table
