void schedule_tasks(struct hash_table *hash_table) {
    // Get the current time
    time_t now = time(NULL);

    // Iterate over all tasks in the hash table
    for (int i = 0; i < hash_table->size; i++) {
        HashEntry *entry = hash_table->entries[i];
        while (entry != NULL) {
            Task *task = &entry->task;

            // Check if the task is due to be executed
            time_t next_execution = now + task->expression;
            if (next_execution <= now) {
                execute_task(task);
            }

            entry = entry->next;
        }
    }
