// Define the record structure
typedef struct {
    int value;
} Record;

// Define the hash table structure
typedef struct {
    Record** records;
    size_t capacity;
    size_t size;
    float load_factor;
    pthread_mutex_t* mutexes;
} HashTable;

// Initialize a new hash table with the given capacity and load factor
HashTable* init_hash_table(size_t capacity, float load_factor) {
    // Allocate memory for the hash table structure
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Error: Failed to allocate memory for hash table\n");
        return NULL;
    }

    // Initialize the hash table fields
    table->records = calloc(capacity, sizeof(Record*));
    if (!table->records) {
        fprintf(stderr, "Error: Failed to allocate memory for record array\n");
        free(table);
        return NULL;
    }
    table->capacity = capacity;
    table->size = 0;
    table->load_factor = load_factor;

    // Allocate memory for the mutexes
    size_t num_mutexes = (size_t)(table->capacity / table->load_factor);
    table->mutexes = calloc(num_mutexes, sizeof(pthread_mutex_t));
    if (!table->mutexes) {
        fprintf(stderr, "Error: Failed to allocate memory for mutexes\n");
        free(table->records);
        free(table);
        return NULL;
    }

    // Initialize the mutexes
    size_t i;
    for (i = 0; i < num_mutexes; ++i) {
        pthread_mutex_init(&table->mutexes[i], NULL);
    }

    return table;
}

// Insert a new record into the hash table with the given key and value
int insert(HashTable* table, int key, int value) {
    // Check if the table is full
    if (table->size >= table->capacity) {
        fprintf(stderr, "Error: Hash table is full\n");
        return -1;
    }

    // Find the index of the record to insert
    size_t index = key % table->capacity;

    // Lock the mutex for the corresponding bucket
    pthread_mutex_lock(&table->mutexes[index]);

    // Check if a record with the same key already exists
    Record* existing_record = find(table, key);
    if (existing_record) {
        fprintf(stderr, "Error: A record with the same key already exists\n");
        pthread_mutex_unlock(&table->mutexes[index]);
        return -1;
    }

    // Allocate memory for the new record
    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Error: Failed to allocate memory for new record\n");
        pthread_mutex_unlock(&table->mutexes[index]);
        return -1;
    }

    // Initialize the new record with the given key and value
    new_record->key = key;
    new_record->value = value;

    // Insert the new record into the hash table
    table->records[index] = new_record;
    ++table->size;

    pthread_mutex_unlock(&table->mutexes[index]);

    return 0;
}

// Find a record in the hash table with the given key
Record* find(HashTable* table, int key) {
    // Check if the table is empty
    if (table->size == 0) {
        fprintf(stderr, "Error: Hash table is empty\n");
        return NULL;
    }

    // Find the index of the record to find
    size_t index = key % table->capacity;

    // Lock the mutex for the corresponding bucket
    pthread_mutex_lock(&table->mutexes[index]);

    // Check if a record with the given key exists
    Record* record = table->records[index];
    while (record && record->key != key) {
        record = record->next;
    }

    pthread_mutex_unlock(&table->mutexes[index]);

    return record;
}

// Update the value of a record in the hash table with the given key
int update(HashTable* table, int key, int new_value) {
    // Check if the table is empty
    if (table->size == 0) {
        fprintf(stderr, "Error: Hash table is empty\n");
        return -1;
    }

    // Find the index of the record to update
    size_t index = key % table->capacity;

    // Lock the mutex for the corresponding bucket
    pthread_mutex_lock(&table->mutexes[index]);

    // Check if a record with the given key exists
    Record* record = find(table, key);
    if (!record) {
        fprintf(stderr, "Error: A record with the given key does not exist\n");
        pthread_mutex_unlock(&table->mutexes[index]);
        return -1;
    }

    // Update the value of the record
    record->value = new_value;

    pthread_mutex_unlock(&table->mutexes[index]);

    return 0;
}

// Clean up the hash table and free all allocated memory
void cleanup(HashTable* table) {
    // Check if the table is empty
    if (table->size == 0) {
        fprintf(stderr, "Error: Hash table is empty\n");
        return;
    }

    // Lock all mutexes to prevent concurrent access
    size_t i;
    for (i = 0; i < table->capacity; ++i) {
        pthread_mutex_lock(&table->mutexes[i]);
    }

    // Free all records and the hash table structure
    Record* record = table->records[0];
    while (record) {
        Record* next = record->next;
        free(record);
        record = next;
    }
    free(table->mutexes);
    free(table->records);
    free(table);

    // Unlock all mutexes
    for (i = 0; i < table->capacity; ++i) {
        pthread_mutex_unlock(&table->mutexes[i]);
    }
}
