#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define a structure to represent a record
typedef struct {
    int key;
    long offset;
} Record;

// Define a hash table to store the records
typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} HashTable;

// Function to initialize the hash table
void initHashTable(HashTable *ht) {
    ht->capacity = 1024; // initial capacity of the hash table
    ht->count = 0;
    ht->records = (Record **)malloc(sizeof(Record *) * ht->capacity);
    memset(ht->records, 0, sizeof(Record *) * ht->capacity);
    pthread_mutex_init(&ht->mutex, NULL);
}

// Function to allocate memory for a new record
int allocRecord(HashTable *ht, int key, long offset) {
    // Check if the hash table is full
    if (ht->count == ht->capacity) {
        // Double the capacity of the hash table
        ht->capacity *= 2;
        ht->records = (Record **)realloc(ht->records, sizeof(Record *) * ht->capacity);
        memset(ht->records + ht->count, 0, sizeof(Record *) * (ht->capacity - ht->count));
    }

    // Allocate memory for the new record
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) {
        printf("Error: Failed to allocate memory for a new record\n");
        return 1;
    }

    // Initialize the new record with the given key and offset
    record->key = key;
    record->offset = offset;

    // Add the new record to the hash table
    pthread_mutex_lock(&ht->mutex);
    ht->records[ht->count++] = record;
    pthread_mutex_unlock(&ht->mutex);

    return 0;
}

// Function to update the value of a record using its key
int updateRecord(HashTable *ht, int key, long offset) {
    // Find the record with the given key
    Record *record = NULL;
    pthread_mutex_lock(&ht->mutex);
    for (size_t i = 0; i < ht->count; i++) {
        if (ht->records[i]->key == key) {
            record = ht->records[i];
            break;
        }
    }
    pthread_mutex_unlock(&ht->mutex);

    // Check if the record was found
    if (!record) {
        printf("Error: Record with key %d not found\n", key);
        return 1;
    }

    // Update the offset value of the record
    pthread_mutex_lock(&ht->mutex);
    record->offset = offset;
    pthread_mutex_unlock(&ht->mutex);

    return 0;
}

// Function to free all allocated memory
void cleanup(HashTable *ht) {
    // Free the records in the hash table
    for (size_t i = 0; i < ht->count; i++) {
        free(ht->records[i]);
    }

    // Free the hash table itself
    pthread_mutex_destroy(&ht->mutex);
    free(ht->records);
}
