#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a structure to represent a node in the list
typedef struct Node {
    char* key;
    int* values;
    size_t num_values;
    time_t timestamp;
} Node;

// Define a linked list data structure to store nodes
typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t size;
} LinkedList;

// Function to add a new node with the given key and values
int addNode(LinkedList* list, char* key, int* values, size_t num_values) {
    // Allocate memory for the new node
    Node* new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Memory allocation failed\n");
        return -1;
    }

    // Initialize the new node with the given key and values
    new_node->key = strdup(key);
    new_node->values = malloc(num_values * sizeof(int));
    memcpy(new_node->values, values, num_values * sizeof(int));
    new_node->num_values = num_values;
    new_node->timestamp = time(NULL);

    // Add the new node to the end of the list
    if (list->tail == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    // Increment the size of the list
    list->size++;

    return 0;
}

// Function to remove a node with the given key from the list
int removeNode(LinkedList* list, char* key) {
    // Find the node with the given key in the list
    Node* current = list->head;
    while (current != NULL && strcmp(current->key, key) != 0) {
        current = current->next;
    }

    // If the node is not found, return an error
    if (current == NULL) {
        printf("Node with key %s not found\n", key);
        return -1;
    }

    // Remove the node from the list
    if (current == list->head) {
        list->head = current->next;
    } else {
        Node* previous = current->previous;
        previous->next = current->next;
    }

    // Free the memory allocated for the node
    free(current->key);
    free(current->values);
    free(current);

    // Decrement the size of the list
    list->size--;

    return 0;
}

// Function to update a value in a node with the given key and index
int updateValue(LinkedList* list, char* key, int index, int new_value) {
    // Find the node with the given key in the list
    Node* current = list->head;
    while (current != NULL && strcmp(current->key, key) != 0) {
        current = current->next;
    }

    // If the node is not found, return an error
    if (current == NULL) {
        printf("Node with key %s not found\n", key);
        return -1;
    }

    // Update the value at the given index in the node
    current->values[index] = new_value;

    return 0;
}

// Function to iterate over all nodes in the list and perform a callback function on each node
void iterateNodes(LinkedList* list, void (*callback)(Node*)) {
    // Iterate over all nodes in the list and call the callback function on each one
    Node* current = list->head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }
}

// Function to clean up all allocated memory for the linked list
void cleanupList(LinkedList* list) {
    // Iterate over all nodes in the list and free their memory
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->key);
        free(current->values);
        free(current);
        current = next;
    }
}
