#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Define the hash table data structure
typedef struct {
    int size;
    int capacity;
    int *offsets;
    int *keys;
    Record **records;
    pthread_mutex_t mutex;
} HashTable;

// Function to dynamically allocate memory for the hash table
HashTable* createHashTable(int size) {
    // Allocate memory for the hash table structure
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) {
        printf("Error: Failed to allocate memory for hash table\n");
        return NULL;
    }

    // Initialize the size and capacity of the hash table
    ht->size = 0;
    ht->capacity = size;

    // Allocate memory for the offset, key, and record arrays
    ht->offsets = (int*)malloc(sizeof(int) * size);
    ht->keys = (int*)malloc(sizeof(int) * size);
    ht->records = (Record**)malloc(sizeof(Record*) * size);
    if (!ht->offsets || !ht->keys || !ht->records) {
        printf("Error: Failed to allocate memory for hash table arrays\n");
        free(ht->offsets);
        free(ht->keys);
        free(ht->records);
        free(ht);
        return NULL;
    }

    // Initialize the mutex for thread safety
    pthread_mutex_init(&ht->mutex, NULL);

    return ht;
}

// Function to dynamically allocate memory for a single record
Record* createRecord(int value) {
    Record *rec = (Record*)malloc(sizeof(Record));
    if (!rec) {
        printf("Error: Failed to allocate memory for record\n");
        return NULL;
    }

    rec->value = value;

    return rec;
}

// Function to insert a new record into the hash table
int insertRecord(HashTable *ht, int key, Record *rec) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&ht->mutex);

    // Check if the hash table is full
    if (ht->size == ht->capacity) {
        printf("Error: Hash table is full\n");
        pthread_mutex_unlock(&ht->mutex);
        return -1;
    }

    // Generate a random offset for the record
    int offset = rand() % ht->capacity;

    // Insert the record into the hash table
    ht->offsets[offset] = key;
    ht->keys[key] = offset;
    ht->records[offset] = rec;

    // Increment the size of the hash table
    ht->size++;

    // Release the mutex for thread safety
    pthread_mutex_unlock(&ht->mutex);

    return 0;
}

// Function to retrieve a record from the hash table
Record* getRecord(HashTable *ht, int key) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&ht->mutex);

    // Check if the key exists in the hash table
    if (ht->keys[key] == -1) {
        printf("Error: Key not found\n");
        pthread_mutex_unlock(&ht->mutex);
        return NULL;
    }

    // Retrieve the record from the hash table
    Record *rec = ht->records[ht->keys[key]];

    // Release the mutex for thread safety
    pthread_mutex_unlock(&ht->mutex);

    return rec;
}

// Function to delete a record from the hash table
int deleteRecord(HashTable *ht, int key) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&ht->mutex);

    // Check if the key exists in the hash table
    if (ht->keys[key] == -1) {
        printf("Error: Key not found\n");
        pthread_mutex_unlock(&ht->mutex);
        return -1;
    }

    // Delete the record from the hash table
    int offset = ht->keys[key];
    ht->offsets[offset] = -1;
    ht->keys[key] = -1;
    free(ht->records[offset]);
    ht->records[offset] = NULL;

    // Decrement the size of the hash table
    ht->size--;

    // Release the mutex for thread safety
    pthread_mutex_unlock(&ht->mutex);

    return 0;
}

// Function to perform a batch insertion of records into the hash table
int batchInsert(HashTable *ht, int numRecords) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&ht->mutex);

    // Check if there is enough space in the hash table to accommodate the new records
    if (numRecords > ht->capacity - ht->size) {
        printf("Error: Not enough space in hash table\n");
        pthread_mutex_unlock(&ht->mutex);
        return -1;
    }

    // Generate random offsets for the new records
    int *offsets = (int*)malloc(sizeof(int) * numRecords);
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        pthread_mutex_unlock(&ht->mutex);
        return -1;
    }
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = rand() % ht->capacity;
    }

    // Insert the new records into the hash table
    for (int i = 0; i < numRecords; i++) {
        int offset = offsets[i];
        if (ht->offsets[offset] != -1) {
            printf("Error: Offset already in use\n");
            pthread_mutex_unlock(&ht->mutex);
            free(offsets);
            return -1;
        }
        ht->offsets[offset] = i;
        ht->keys[i] = offset;
        ht->records[offset] = createRecord(i);
    }

    // Increment the size of the hash table
    ht->size += numRecords;

    // Release the mutex for thread safety
    pthread_mutex_unlock(&ht->mutex);

    free(offsets);

    return 0;
}

// Function to perform a batch deletion of records from the hash table
int batchDelete(HashTable *ht, int numRecords) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&ht->mutex);

    // Check if there are enough records in the hash table to accommodate the deletion
    if (numRecords > ht->size) {
        printf("Error: Not enough records in hash table\n");
        pthread_mutex_unlock(&ht->mutex);
        return -1;
    }

    // Generate random offsets for the records to be deleted
    int *offsets = (int*)malloc(sizeof(int) * numRecords);
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        pthread_mutex_unlock(&ht->mutex);
        return -1;
    }
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = rand() % ht->capacity;
    }

    // Delete the records from the hash table
    for (int i = 0; i < numRecords; i++) {
        int offset = offsets[i];
        if (ht->offsets[offset] == -1) {
            printf("Error: Offset not in use\n");
            pthread_mutex_unlock(&ht->mutex);
            free(offsets);
            return -1;
        }
        ht->offsets[offset] = -1;
        ht->keys[ht->offsets[offset]] = -1;
        free(ht->records[offset]);
        ht->records[offset] = NULL;
    }

    // Decrement the size of the hash table
    ht->size -= numRecords;

    // Release the mutex for thread safety
    pthread_mutex_unlock(&ht->mutex);

    free(offsets);

    return 0;
}

// Function to clean up all allocated memory in the hash table
void cleanupHashTable(HashTable *ht) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&ht->mutex);

    // Free the offset, key, and record arrays
    free(ht->offsets);
    free(ht->keys);
    free(ht->records);

    // Release the mutex for thread safety
    pthread_mutex_unlock(&ht->mutex);
}

// Function to clean up a subset of records in the hash table based on a specified criteria
void incrementalCleanup(HashTable *ht, int (*criteria)(Record*)) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&ht->mutex);

    // Iterate over the records in the hash table and delete those that meet the specified criteria
    for (int i = 0; i < ht->capacity; i++) {
        if (ht->offsets[i] != -1) {
            Record *rec = ht->records[i];
            if (criteria(rec)) {
                deleteRecord(ht, rec->value);
            }
        }
    }

    // Release the mutex for thread safety
    pthread_mutex_unlock(&ht->mutex);
