["```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Define the hash table data structure
typedef struct {
    int size;
    int capacity;
    int *offsets;
    int *keys;
    Record **records;
    pthread_mutex_t mutex;
} HashTable;

// Function to dynamically allocate memory for the hash table
HashTable* createHashTable(int size) {
    // Allocate memory for the offsets, keys, and records arrays
    int *offsets = (int*)malloc(size * sizeof(int));
    int *keys = (int*)malloc(size * sizeof(int));
    Record **records = (Record**)malloc(size * sizeof(Record*));

    // Initialize the offsets, keys, and records arrays
    for (int i = 0; i < size; i++) {
        offsets[i] = -1;
        keys[i] = -1;
        records[i] = NULL;
    }

    // Allocate memory for the mutex
    pthread_mutex_t *mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(mutex, NULL);

    // Create the hash table data structure
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->size = size;
    ht->capacity = size;
    ht->offsets = offsets;
    ht->keys = keys;
    ht->records = records;
    ht->mutex = mutex;

    return ht;
}

// Function to dynamically allocate memory for a single record
Record* createRecord(int value) {
    Record *record = (Record*)malloc(sizeof(Record));
    record->value = value;
    return record;
}

// Function to insert a record into the hash table
void insertRecord(HashTable *ht, int key, int value) {
    // Acquire the mutex lock
    pthread_mutex_lock(&ht->mutex);

    // Check if the hash table is full
    if (ht->size == ht->capacity) {
        // Double the capacity of the hash table
        int newCapacity = ht->capacity * 2;
        int *newOffsets = (int*)realloc(ht->offsets, newCapacity * sizeof(int));
        int *newKeys = (int*)realloc(ht->keys, newCapacity * sizeof(int));
        Record **newRecords = (Record**)realloc(ht->records, newCapacity * sizeof(Record*));

        // Initialize the new offsets, keys, and records arrays
        for (int i = ht->capacity; i < newCapacity; i++) {
            newOffsets[i] = -1;
            newKeys[i] = -1;
            newRecords[i] = NULL;
        }

        // Update the hash table data structure
        ht->offsets = newOffsets;
        ht->keys = newKeys;
        ht->records = newRecords;
        ht->capacity = newCapacity;
    }

    // Generate a random offset for the record
    int offset = rand() % (ht->capacity - ht->size);

    // Insert the record into the hash table
    ht->offsets[offset] = key;
    ht->keys[offset] = key;
    ht->records[offset] = createRecord(value);

    // Release the mutex lock
    pthread_mutex_unlock(&ht->mutex);
}

// Function to retrieve a record from the hash table
Record* getRecord(HashTable *ht, int key) {
    // Acquire the mutex lock
    pthread_mutex_lock(&ht->mutex);

    // Find the offset of the record in the hash table
    int offset = -1;
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] == key) {
            offset = i;
            break;
        }
    }

    // Release the mutex lock
    pthread_mutex_unlock(&ht->mutex);

    // Return NULL if the record is not found
    if (offset == -1) {
        return NULL;
    }

    // Return the record
    return ht->records[offset];
}

// Function to delete a record from the hash table
void deleteRecord(HashTable *ht, int key) {
    // Acquire the mutex lock
    pthread_mutex_lock(&ht->mutex);

    // Find the offset of the record in the hash table
    int offset = -1;
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] == key) {
            offset = i;
            break;
        }
    }

    // Release the mutex lock
    pthread_mutex_unlock(&ht->mutex);

    // Return if the record is not found
    if (offset == -1) {
        return;
    }

    // Shift all records after the deleted record to fill the gap
    for (int i = offset + 1; i < ht->size; i++) {
        ht->offsets[i - 1] = ht->offsets[i];
        ht->keys[i - 1] = ht->keys[i];
        ht->records[i - 1] = ht->records[i];
    }

    // Decrement the size of the hash table
    ht->size--;
}

// Function to cleanup the hash table and free all allocated memory
void cleanupHashTable(HashTable *ht) {
    // Acquire the mutex lock
    pthread_mutex_lock(&ht->mutex);

    // Free the offsets, keys, and records arrays
    free(ht->offsets);
    free(ht->keys);
    for (int i = 0; i < ht->size; i++) {
        free(ht->records[i]);
    }
    free(ht->records);

    // Release the mutex lock
    pthread_mutex_unlock(&ht->mutex);

    // Free the mutex
    pthread_mutex_destroy(&ht->mutex);

    // Free the hash table data structure
    free(ht);
}
```
