#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the Node structure to hold a string key, linked list of integer values, and timestamp
typedef struct Node {
    char* key;
    int* values;
    size_t num_values;
    time_t last_updated;
} Node;

// Define the function to manage the dynamic list of Nodes
void manage_nodes(Node** nodes, size_t* num_nodes) {
    // Add a new node with the given key and value
    void add_node(const char* key, int value) {
        Node* new_node = malloc(sizeof(Node));
        if (new_node == NULL) {
            printf("Error: Failed to allocate memory for new node\n");
            return;
        }
        new_node->key = strdup(key);
        new_node->values = malloc(sizeof(int));
        new_node->num_values = 1;
        new_node->last_updated = time(NULL);
        *nodes = realloc(*nodes, (*num_nodes + 1) * sizeof(Node*));
        if (*nodes == NULL) {
            printf("Error: Failed to allocate memory for new node\n");
            free(new_node->key);
            free(new_node->values);
            return;
        }
        (*nodes)[*num_nodes] = new_node;
        *num_nodes += 1;
    }

    // Remove the node with the given key
    void remove_node(const char* key) {
        size_t i;
        for (i = 0; i < *num_nodes; i++) {
            if (strcmp((*nodes)[i]->key, key) == 0) {
                free((*nodes)[i]->key);
                free((*nodes)[i]->values);
                (*nodes)[i] = NULL;
                break;
            }
        }
    }

    // Update the value list of a node with the given key
    void update_node(const char* key, int value) {
        size_t i;
        for (i = 0; i < *num_nodes; i++) {
            if (strcmp((*nodes)[i]->key, key) == 0) {
                (*nodes)[i]->values[(*nodes)[i]->num_values] = value;
                (*nodes)[i]->num_values++;
                break;
            }
        }
    }

    // Iterate over all nodes and perform the given action
    void iterate(void (*action)(Node*)) {
        size_t i;
        for (i = 0; i < *num_nodes; i++) {
            if ((*nodes)[i] != NULL) {
                action((*nodes)[i]);
            }
        }
    }

    // Clean up all allocated memory
    void cleanup() {
        size_t i;
        for (i = 0; i < *num_nodes; i++) {
            if ((*nodes)[i] != NULL) {
                free((*nodes)[i]->key);
                free((*nodes)[i]->values);
                (*nodes)[i] = NULL;
            }
        }
        free(*nodes);
    }
