void init_arrays(long* offset_arr, int* key_arr, Record** rec_arr, int num_records) {
    // Allocate memory for the offset array
    offset_arr = (long*)malloc(num_records * sizeof(long));
    if (!offset_arr) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Initialize the offset array with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offset_arr[i] = rand() % 100;
    }

    // Allocate memory for the key array
    key_arr = (int*)malloc(num_records * sizeof(int));
    if (!key_arr) {
        printf("Error: Failed to allocate memory for key array\n");
        return;
    }

    // Initialize the key array with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        key_arr[i] = rand() % 100;
    }

    // Allocate memory for the record array
    rec_arr = (Record**)malloc(num_records * sizeof(Record*));
    if (!rec_arr) {
        printf("Error: Failed to allocate memory for record array\n");
        return;
    }

    // Initialize each record with a random value and its corresponding key
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        rec_arr[i] = malloc(sizeof(Record));
        if (!rec_arr[i]) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            return;
        }
        rec_arr[i]->key = key_arr[i];
        rec_arr[i]->value = rand() % 100;
    }
}

// Function to clean up the allocated resources
void cleanup(long* offset_arr, int* key_arr, Record** rec_arr) {
    // Free the memory for the offset array
    free(offset_arr);

    // Free the memory for the key array
    free(key_arr);

    // Free the memory for each record in the record array
    for (int i = 0; i < num_records; i++) {
        free(rec_arr[i]);
    }

    // Free the memory for the record array
    free(rec_arr);
}
