using namespace std;

class RandomNumberGenerator {
public:
    RandomNumberGenerator() : mt(time(0)) {}
    ~RandomNumberGenerator() = default;

    static RandomNumberGenerator& getInstance() {
        static RandomNumberGenerator instance;
        return instance;
    }

    int generateRandomNumber(int min, int max) {
        std::uniform_int_distribution<int> distribution(min, max);
        return distribution(mt);
    }

private:
    mt19937 mt;
};

struct Record {
    int key;
    int value;
    Record* next;
};

void initializeRecords(int numRecords, int minValue, int maxValue) {
    // Allocate memory for the arrays
    long* offsetArray = new long[numRecords];
    int* keyArray = new int[numRecords];
    Record* recordArray = new Record[numRecords];

    if (!offsetArray || !keyArray || !recordArray) {
        // Handle memory allocation failure gracefully
        cout << "Memory allocation failed. Exiting." << endl;
        return;
    }

    // Initialize the arrays and records
    for (int i = 0; i < numRecords; i++) {
        offsetArray[i] = i * sizeof(Record);
        keyArray[i] = RandomNumberGenerator::getInstance().generateRandomNumber(minValue, maxValue);
        recordArray[i].key = keyArray[i];
        recordArray[i].value = 0; // Initialize value to 0
        recordArray[i].next = nullptr;
    }

    // Clean up resources when function exits
    delete[] offsetArray;
    delete[] keyArray;
    delete[] recordArray;
}

int main() {
    int numRecords = 10;
    int minValue = 0;
    int maxValue = 100;

    initializeRecords(numRecords, minValue, maxValue);

    // Use the records in a concurrent manner
    std::thread t1([&]() {
        Record* record = &recordArray[0];
        while (true) {
            int key = record->key;
            int value = record->value;
            if (value == 0) {
                // Update the value with a new random number
                record->value = RandomNumberGenerator::getInstance().generateRandomNumber(minValue, maxValue);
            } else {
                // Do something with the key and value
                cout << "Key: " << key << ", Value: " << value << endl;
            }
        }
    });

    std::thread t2([&]() {
        Record* record = &recordArray[1];
        while (true) {
            int key = record->key;
            int value = record->value;
            if (value == 0) {
                // Update the value with a new random number
                record->value = RandomNumberGenerator::getInstance().generateRandomNumber(minValue, maxValue);
            } else {
                // Do something with the key and value
                cout << "Key: " << key << ", Value: " << value << endl;
            }
        }
    });

    t1.join();
    t2.join();

    return 0;
}
