// Define the function to manage the collection of records
void manage_records(Collection* collection, const char* data_source, int seed) {
    // Initialize the collection with a default size
    collection->capacity = 1024;
    collection->count = 0;
    collection->offset_array_size = 1024;
    collection->key_array_size = 1024;
    collection->records = (Record*)malloc(sizeof(Record) * collection->capacity);
    collection->offsets = (long*)malloc(sizeof(long) * collection->offset_array_size);
    collection->keys = (int*)malloc(sizeof(int) * collection->key_array_size);

    // Pre-populate the records with initial data from an external data source
    if (data_source != NULL) {
        FILE* file = fopen(data_source, "r");
        if (file == NULL) {
            printf("Error: unable to open file %s\n", data_source);
            return;
        }
        while (!feof(file)) {
            Record record;
            int key = 0;
            fscanf(file, "%d", &key);
            if (key != EOF) {
                record.key = key;
                record.value = rand_range(seed, 1000);
                add_record(collection, record);
            }
        }
        fclose(file);
    }
}

// Add a new record to the collection
void add_record(Collection* collection, Record record) {
    // Check if the collection is full and needs to be resized
    if (collection->count == collection->capacity) {
        collection->capacity *= 2;
        collection->records = (Record*)realloc(collection->records, sizeof(Record) * collection->capacity);
        collection->offsets = (long*)realloc(collection->offsets, sizeof(long) * collection->offset_array_size * 2);
        collection->keys = (int*)realloc(collection->keys, sizeof(int) * collection->key_array_size * 2);
    }

    // Add the new record to the collection
    collection->records[collection->count] = record;
    collection->offsets[collection->count] = -1;
    collection->keys[collection->count] = record.key;
    collection->count++;
}

// Remove a record from the collection by its key
void remove_record(Collection* collection, int key) {
    // Find the index of the record to be removed
    size_t i = 0;
    while (i < collection->count && collection->keys[i] != key) {
        i++;
    }

    // Check if the record was found and remove it from the collection
    if (i < collection->count) {
        collection->count--;
        for (size_t j = i; j < collection->count; j++) {
            collection->records[j] = collection->records[j + 1];
            collection->offsets[j] = collection->offsets[j + 1];
            collection->keys[j] = collection->keys[j + 1];
        }
    }
}

// Get a record from the collection by its key
Record* get_record(Collection* collection, int key) {
    // Find the index of the record to be retrieved
    size_t i = 0;
    while (i < collection->count && collection->keys[i] != key) {
        i++;
    }

    // Check if the record was found and return it
    if (i < collection->count) {
        return &collection->records[i];
    } else {
        return NULL;
    }
}

