void init_data(int num_offsets, int num_keys, struct record *records) {
    // Check if the user-provided sizes are non-negative and within limits
    if (num_offsets < 0 || num_keys < 0 || num_offsets > MAX_ARRAY_SIZE || num_keys > MAX_ARRAY_SIZE) {
        printf("Invalid input size. Please provide a valid number of offsets and keys.\n");
        return;
    }

    // Allocate memory for the arrays and record structures
    long *offsets = malloc(num_offsets * sizeof(long));
    int *keys = malloc(num_keys * sizeof(int));
    struct record *records = malloc(num_records * sizeof(struct record));

    // Initialize the arrays and record structures with random values within ranges
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % (MAX_OFFSET - MIN_OFFSET + 1) + MIN_OFFSET;
    }
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
    }
    for (int i = 0; i < num_records; i++) {
        records[i].temperature = rand() % (MAX_TEMPERATURE - MIN_TEMPERATURE + 1) + MIN_TEMPERATURE;
        records[i].humidity = rand() % (MAX_HUMIDITY - MIN_HUMIDITY + 1) + MIN_HUMIDITY;
        records[i].wind_speed = rand() % (MAX_WIND_SPEED - MIN_WIND_SPEED + 1) + MIN_WIND_SPEED;
        records[i].weather_type = rand() % (RAINY - CLEAR + 1) + CLEAR;
        records[i].precipitation = rand() % 2 == 0 ? true : false;
        records[i].timestamp = time(NULL);
        records[i].atmospheric_pressure = rand() % (MAX_ATMOSPHERIC_PRESSURE - MIN_ATMOSPHERIC_PRESSURE + 1) + MIN_ATMOSPHERIC_PRESSURE;
    }

    // Free the memory allocated for the arrays and record structures
    free(offsets);
    free(keys);
    free(records);
}

// Function to group the entries by location name and compute averages and standard deviations
void group_entries(struct record *records, int num_records) {
    // Create a hash table to store the unique location names and their corresponding indices in the records array
    struct hash_table *location_hash = create_hash_table();

    // Iterate over the records and add each location name to the hash table
    for (int i = 0; i < num_records; i++) {
        char *location_name = records[i].location;
        if (!hash_table_contains(location_hash, location_name)) {
            hash_table_add(location_hash, location_name);
        }
    }

    // Iterate over the hash table and compute the averages and standard deviations for each group of records
    struct hash_node *current_node = location_hash->head;
    while (current_node != NULL) {
        char *location_name = current_node->key;
        int start_index = current_node->value;
        int end_index = start_index + 1;
        while (end_index < num_records && strcmp(location_hash->keys[end_index], location_name) == 0) {
            end_index++;
        }
        struct record *group_records = &records[start_index];
        int group_size = end_index - start_index;
        double average_temperature = 0;
        double average_humidity = 0;
        double average_wind_speed = 0;
        double average_atmospheric_pressure = 0;
        for (int i = start_index; i < end_index; i++) {
            average_temperature += group_records[i].temperature;
            average_humidity += group_records[i].humidity;
            average_wind_speed += group_records[i].wind_speed;
            average_atmospheric_pressure += group_records[i].atmospheric_pressure;
        }
        average_temperature /= group_size;
        average_humidity /= group_size;
        average_wind_speed /= group_size;
        average_atmospheric_pressure /= group_size;
        double standard_deviation_temperature = 0;
        double standard_deviation_humidity = 0;
        double standard_deviation_wind_speed = 0;
        double standard_deviation_atmospheric_pressure = 0;
        for (int i = start_index; i < end_index; i++) {
            standard_deviation_temperature += pow(group_records[i].temperature - average_temperature, 2);
            standard_deviation_humidity += pow(group_records[i].humidity - average_humidity, 2);
            standard_deviation_wind_speed += pow(group_records[i].wind_speed - average_wind_speed, 2);
            standard_deviation_atmospheric_pressure += pow(group_records[i].atmospheric_pressure - average_atmospheric_pressure, 2);
        }
        standard_deviation_temperature = sqrt(standard_deviation_temperature / group_size);
        standard_deviation_humidity = sqrt(standard_deviation_humidity / group_size);
        standard_deviation_wind_speed = sqrt(standard_deviation_wind_speed / group_size);
        standard_deviation_atmospheric_pressure = sqrt(standard_deviation_atmospheric_pressure / group_size);
        printf("Location: %s\n", location_name);
        printf("Average temperature: %.2f\n", average_temperature);
        printf("Standard deviation of temperature: %.2f\n", standard_deviation_temperature);
        printf("Average humidity: %.2f\n", average_humidity);
        printf("Standard deviation of humidity: %.2f\n", standard_deviation_humidity);
        printf("Average wind speed: %.2f\n", average_wind_speed);
        printf("Standard deviation of wind speed: %.2f\n", standard_deviation_wind_speed);
        printf("Average atmospheric pressure: %.2f\n", average_atmospheric_pressure);
        printf("Standard deviation of atmospheric pressure: %.2f\n", standard_deviation_atmospheric_pressure);
    }
}
