#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>

// Define the session ID and state structure
typedef struct {
    char* id;
    bool authenticated;
    time_t last_activity;
} SessionState;

// Define the session collection data structure
typedef struct {
    SessionState** sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SessionCollection;

// Initialize a new session collection with an initial capacity
SessionCollection* init_session_collection(size_t initial_capacity) {
    SessionCollection* collection = malloc(sizeof(SessionCollection));
    if (!collection) {
        return NULL;
    }
    collection->sessions = calloc(initial_capacity, sizeof(SessionState*));
    if (!collection->sessions) {
        free(collection);
        return NULL;
    }
    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

// Add a new session to the collection
bool add_session(SessionCollection* collection, char* id) {
    if (!collection || !id) {
        return false;
    }
    pthread_mutex_lock(&collection->lock);
    // Check for duplicate IDs and append a suffix if necessary
    bool duplicate = false;
    for (size_t i = 0; i < collection->count; ++i) {
        if (!strcmp(id, collection->sessions[i]->id)) {
            duplicate = true;
            break;
        }
    }
    if (duplicate) {
        id = strcat(id, "_");
    }
    // Allocate memory for the new session state and initialize it
    SessionState* state = malloc(sizeof(SessionState));
    if (!state) {
        pthread_mutex_unlock(&collection->lock);
        return false;
    }
    state->id = id;
    state->authenticated = false;
    state->last_activity = 0;
    // Add the new session to the collection and update the count
    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        SessionState** new_sessions = realloc(collection->sessions, new_capacity * sizeof(SessionState*));
        if (!new_sessions) {
            free(state);
            pthread_mutex_unlock(&collection->lock);
            return false;
        }
        collection->sessions = new_sessions;
        collection->capacity = new_capacity;
    }
    collection->sessions[collection->count++] = state;
    pthread_mutex_unlock(&collection->lock);
    return true;
}

// Remove a session from the collection by ID
bool remove_session(SessionCollection* collection, char* id) {
    if (!collection || !id) {
        return false;
    }
    pthread_mutex_lock(&collection->lock);
    // Find the session with the given ID and remove it from the collection
    for (size_t i = 0; i < collection->count; ++i) {
        if (!strcmp(id, collection->sessions[i]->id)) {
            free(collection->sessions[i]);
            memmove(&collection->sessions[i], &collection->sessions[i + 1], (collection->count - i - 1) * sizeof(SessionState*));
            --collection->count;
            pthread_mutex_unlock(&collection->lock);
            return true;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return false;
}

// Update the authentication status of a session by ID
bool update_session(SessionCollection* collection, char* id, bool authenticated) {
    if (!collection || !id) {
        return false;
    }
    pthread_mutex_lock(&collection->lock);
    // Find the session with the given ID and update its authentication status
    for (size_t i = 0; i < collection->count; ++i) {
        if (!strcmp(id, collection->sessions[i]->id)) {
            collection->sessions[i]->authenticated = authenticated;
            pthread_mutex_unlock(&collection->lock);
            return true;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return false;
}

// Get the authentication status of a session by ID
bool get_session(SessionCollection* collection, char* id) {
    if (!collection || !id) {
        return false;
    }
    pthread_mutex_lock(&collection->lock);
    // Find the session with the given ID and return its authentication status
    for (size_t i = 0; i < collection->count; ++i) {
        if (!strcmp(id, collection->sessions[i]->id)) {
            pthread_mutex_unlock(&collection->lock);
            return collection->sessions[i]->authenticated;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return false;
}

// Release allocated memory and clean up resources when no longer needed
void destroy_session_collection(SessionCollection* collection) {
    if (!collection) {
        return;
    }
    pthread_mutex_destroy(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->sessions[i]);
    }
    free(collection->sessions);
    free(collection);
}
```
