int init(char* password, int offset_size, int key_size, int record_size) {
    // Check if the input parameters are valid
    if (password == NULL || offset_size <= 0 || key_size <= 0 || record_size <= 0) {
        return -1;
    }

    // Initialize the arrays and hash table
    long* offsets = malloc(offset_size * sizeof(long));
    int* keys = malloc(key_size * sizeof(int));
    record* records = malloc(record_size * sizeof(record));
    hash_table* hash_table = create_hash_table();

    // Initialize the arrays and hash table with random values
    for (int i = 0; i < offset_size; i++) {
