        keys[i] = rand() % MAX_KEY_SIZE;
    }
    for (int i = 0; i < record_size; i++) {
        records[i].key = rand() % MAX_RECORD_SIZE;
    }

    // Initialize the hash table with the records
    for (int i = 0; i < record_size; i++) {
