        *offsets = realloc(*offsets, total_size);
        *keys = realloc(*keys, total_size);
        *records = realloc(*records, total_size);
    }
    pthread_mutex_unlock(&mutex);
}

// Define a method to free all allocated memory when the function completes its operations, ensuring resource management is handled gracefully
