// Define the node structure
typedef struct Node {
    char buffer[256]; // variable length buffer (up to 256 bytes)
    int priority; // integer value representing a priority
} Node;

// Define the tree structure
typedef struct Tree {
    Node* nodes; // array of nodes
    size_t num_nodes; // number of nodes in the tree
    pthread_mutex_t mutex; // mutex for synchronizing access to the tree
} Tree;

// Function to initialize a new tree with a specified number of nodes
Tree* init_tree(size_t n) {
    if (n <= 0) {
        return NULL;
    }

    Tree* tree = malloc(sizeof(Tree));
    if (!tree) {
        return NULL;
    }

    // Initialize the mutex for synchronizing access to the tree
    pthread_mutex_init(&tree->mutex, NULL);

    // Allocate memory for the nodes
    tree->nodes = malloc(n * sizeof(Node));
    if (!tree->nodes) {
        free(tree);
        return NULL;
    }

    // Initialize the number of nodes in the tree
    tree->num_nodes = n;

    // Initialize each node's priority to a random value within a specified range
    for (size_t i = 0; i < n; i++) {
        tree->nodes[i].priority = rand() % 100 + 1;
    }

    // Initialize each node's buffer with a unique string that does not exceed the maximum allowed length
    for (size_t i = 0; i < n; i++) {
        char* buf = tree->nodes[i].buffer;
        size_t len = strlen(buf);
        if (len > 256) {
            len = 256;
        }
        for (size_t j = 0; j < len; j++) {
            buf[j] = 'a' + rand() % 26;
        }
    }

    return tree;
}

// Function to insert a new node into the tree
void insert_node(Tree* tree, const char* buffer) {
    if (!tree || !buffer) {
        return;
    }

    // Acquire the mutex for synchronizing access to the tree
    pthread_mutex_lock(&tree->mutex);

    // Check if there is enough memory to allocate a new node
    if (tree->num_nodes >= tree->nodes) {
        // Reallocate memory for the nodes array
        size_t new_size = tree->num_nodes * 2;
        Node* new_nodes = realloc(tree->nodes, new_size * sizeof(Node));
        if (!new_nodes) {
            pthread_mutex_unlock(&tree->mutex);
            return;
        }
        tree->nodes = new_nodes;
    }

    // Insert the new node into the tree
    Node* new_node = &tree->nodes[tree->num_nodes++];
    strcpy(new_node->buffer, buffer);
    new_node->priority = rand() % 100 + 1;

    // Release the mutex for synchronizing access to the tree
    pthread_mutex_unlock(&tree->mutex);
}

// Function to find a node in the tree based on its priority value
Node* find_node(Tree* tree, int priority) {
    if (!tree || !priority) {
        return NULL;
    }

    // Acquire the mutex for synchronizing access to the tree
    pthread_mutex_lock(&tree->mutex);

    // Search for the node with the specified priority value
    for (size_t i = 0; i < tree->num_nodes; i++) {
        if (tree->nodes[i].priority == priority) {
            Node* found_node = &tree->nodes[i];
            pthread_mutex_unlock(&tree->mutex);
            return found_node;
        }
    }

    // Release the mutex for synchronizing access to the tree
    pthread_mutex_unlock(&tree->mutex);

    return NULL;
}

// Function to free all memory allocated by the tree
void free_tree(Tree* tree) {
    if (!tree) {
        return;
    }

    // Acquire the mutex for synchronizing access to the tree
    pthread_mutex_lock(&tree->mutex);

    // Free all memory allocated by the nodes array
    free(tree->nodes);

    // Release the mutex for synchronizing access to the tree
    pthread_mutex_unlock(&tree->mutex);

    // Free the tree structure itself
    free(tree);
}
