// Define function to group records by location and calculate averages
void group_records(int n, record *records, sensor_location *locations) {
    // Initialize variables for grouping and aggregation
    int num_groups = 0;
    int total_temperature = 0;
    int total_humidity = 0;
    float total_wind_speed = 0.0f;
    long total_timestamp = 0;
    bool data_quality_flag = false;
    enum sensor_type type = 0;

    // Iterate over records and group by location
    for (int i = 0; i < n; i++) {
        int j = 0;
        while (j < num_groups && strcmp(locations[i].geographic_identifier, locations[j].geographic_identifier) != 0) {
            j++;
        }
        if (j == num_groups) {
            // New location found, add to group list and initialize aggregates
            num_groups++;
            total_temperature = records[i].temperature;
            total_humidity = records[i].humidity;
            total_wind_speed += records[i].wind_speed;
            total_timestamp = records[i].offset;
            data_quality_flag = records[i].data_quality;
            type = records[i].type;
        } else {
            // Existing location found, update aggregates
            total_temperature += records[i].temperature;
            total_humidity += records[i].humidity;
            total_wind_speed += records[i].wind_speed;
            total_timestamp = (total_timestamp + records[i].offset) / 2;
            data_quality_flag &= records[i].data_quality;
            type = records[i].type;
        }
    }

    // Print results for each group
    for (int i = 0; i < num_groups; i++) {
        printf("Group %d: \n", i);
        printf("\tAverage temperature: %.2f\n", total_temperature / num_groups);
        printf("\tAverage humidity: %.2f%%\n", total_humidity / num_groups);
        printf("\tAverage wind speed: %.2f km/h\n", total_wind_speed / num_groups);
        printf("\tAverage timestamp: %ld\n", total_timestamp / num_groups);
        printf("\tData quality flag: %s\n", data_quality_flag ? "true" : "false");
        printf("\tSensor type: %d\n", type);
    }
}

// Define function to compute standard deviation of temperatures and humidity levels for each group
void stddev_records(int n, record *records, sensor_location *locations) {
    // Initialize variables for grouping and aggregation
