    double total_temperature = 0.0;
    double total_humidity = 0.0;
    double temp_sum_squares = 0.0;
    double hum_sum_squares = 0.0;

    // Iterate over records and group by location
    for (int i = 0; i < n; i++) {
        int j = 0;
        while (j < num_groups && strcmp(locations[i].geographic_identifier, locations[j].geographic_identifier) != 0) {
            j++;
        }
        if (j == num_groups) {
            // New location found, add to group list and initialize aggregates
            num_groups++;
            total_temperature = records[i].temperature;
            total_humidity = records[i].humidity;
            temp_sum_squares += pow(records[i].temperature, 2);
            hum_sum_squares += pow(records[i].humidity, 2);
        } else {
            // Existing location found, update aggregates
            total_temperature += records[i].temperature;
            total_humidity += records[i].humidity;
            temp_sum_squares += pow(records[i].temperature, 2);
            hum_sum_squares += pow(records[i].humidity, 2);
        }
    }

    // Print results for each group
    for (int i = 0; i < num_groups; i++) {
        printf("Group %d: \n", i);
        printf("\tStandard deviation of temperatures: %.2f\n", sqrt(temp_sum_squares / num_groups - pow(total_temperature / num_groups, 2)));
        printf("\tStandard deviation of humidity levels: %.2f%%\n", sqrt(hum_sum_squares / num_groups - pow(total_humidity / num_groups, 2)) * 100);
    }
}
