            group_array[i].average_status |= sensor_array[j].status;

            // Calculate standard deviation of signal strengths for current record
            float temp = pow(aggregated_record_array[j].signal_strength - group_array[i].average_signal_strength, 2);
            group_array[i].standard_deviation += temp;
        }

        // Calculate average latitude, longitude, elevation, signal strength, and status for current group
        group_array[i].average_latitude /= group_array[i].count;
        group_array[i].average_longitude /= group_array[i].count;
        group_array[i].average_elevation /= group_array[i].count;
        group_array[i].average_signal_strength /= group_array[i].count;
