#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdio.h>

// Define the structure for a node in the tree
typedef struct Node {
    char buffer[256]; // variable length string up to 256 bytes
    int priority; // integer representing priority
} Node;

// Define the structure for the tree itself
typedef struct Tree {
    Node* nodes; // array of nodes
    size_t count; // number of nodes in the tree
    size_t capacity; // maximum number of nodes that can be stored in the tree
    pthread_mutex_t mutex; // mutex for synchronizing access to the tree
} Tree;

// Initialize a new tree with a specified number of nodes
Tree* tree_init(size_t n) {
    if (n < 0) {
        return NULL;
    }

    Tree* tree = malloc(sizeof(Tree));
    if (!tree) {
        return NULL;
    }

    tree->nodes = malloc(n * sizeof(Node));
    if (!tree->nodes) {
        free(tree);
        return NULL;
    }

    tree->count = 0;
    tree->capacity = n;
    pthread_mutex_init(&tree->mutex, NULL);

    return tree;
}

// Insert a new node into the tree with a specified priority and buffer
int tree_insert(Tree* tree, int priority, const char* buffer) {
    if (!tree || !buffer) {
        return -1;
    }

    pthread_mutex_lock(&tree->mutex);

    // Check if the tree needs to be resized
    if (tree->count == tree->capacity) {
        size_t new_capacity = tree->capacity * 2;
        Node* new_nodes = realloc(tree->nodes, new_capacity * sizeof(Node));
        if (!new_nodes) {
            pthread_mutex_unlock(&tree->mutex);
            return -1;
        }
        tree->nodes = new_nodes;
        tree->capacity = new_capacity;
    }

    // Generate a random priority for the new node
    int rand_priority = rand() % 100 + 1;

    // Copy the buffer into the new node
    strncpy(tree->nodes[tree->count].buffer, buffer, sizeof(tree->nodes[tree->count].buffer));
    tree->nodes[tree->count].priority = priority ? priority : rand_priority;

    tree->count++;

    pthread_mutex_unlock(&tree->mutex);

    return 0;
}

// Remove a node from the tree with a specified priority
int tree_remove(Tree* tree, int priority) {
    if (!tree) {
        return -1;
    }

    pthread_mutex_lock(&tree->mutex);

    // Find the node with the specified priority
    size_t i = 0;
    for (i = 0; i < tree->count; i++) {
        if (tree->nodes[i].priority == priority) {
            break;
        }
    }

    // If the node was not found, return an error
    if (i == tree->count) {
        pthread_mutex_unlock(&tree->mutex);
        return -1;
    }

    // Shift all nodes after the removed node to fill the gap
    for (size_t j = i; j < tree->count - 1; j++) {
        tree->nodes[j] = tree->nodes[j + 1];
    }

    tree->count--;

    pthread_mutex_unlock(&tree->mutex);

    return 0;
}

// Search for a node in the tree with a specified priority
Node* tree_search(Tree* tree, int priority) {
    if (!tree) {
        return NULL;
    }

    pthread_mutex_lock(&tree->mutex);

    // Find the node with the specified priority
    size_t i = 0;
    for (i = 0; i < tree->count; i++) {
        if (tree->nodes[i].priority == priority) {
            break;
        }
    }

    // If the node was not found, return NULL
    if (i == tree->count) {
        pthread_mutex_unlock(&tree->mutex);
        return NULL;
    }

    Node* result = &tree->nodes[i];

    pthread_mutex_unlock(&tree->mutex);

    return result;
}

// Free the memory allocated for the tree
void tree_free(Tree* tree) {
    if (!tree) {
        return;
    }

    pthread_mutex_lock(&tree->mutex);

    free(tree->nodes);
    tree->nodes = NULL;
    tree->count = 0;
    tree->capacity = 0;

    pthread_mutex_unlock(&tree->mutex);

    pthread_mutex_destroy(&tree->mutex);
    free(tree);
}
```
This code implements a thread-safe tree data structure that can be used to store nodes with character buffers and integer priorities. The `tree_init` function initializes a new tree with a specified number of nodes, and the `tree_insert` function inserts a new node into the tree with a specified priority and buffer. The `tree_remove` function removes a node from the tree with a specified priority, and the `tree_search` function searches for a node in the tree with a specified priority. Finally, the `tree_free` function frees the memory allocated for the tree.

The code uses a mutex to synchronize access to the tree, which ensures that multiple threads can safely modify the tree without interfering with each other. The mutex is also used to protect the `count` and `capacity` variables, which are modified by both the insertion and removal functions.

The code also includes a mechanism for resizing the tree structure dynamically, which allows it to accommodate new nodes while preserving existing data. This is done by reallocating the memory for the node array with a larger size when the tree needs to be resized. The `tree_insert` function checks if the tree needs to be resized before inserting a new node, and the `tree_remove` function shifts all nodes after the removed node to fill the gap.

The code also includes a feature for removing nodes from the tree without causing memory leaks, which is achieved by simply shifting all nodes after the removed node to fill the gap. This ensures that the tree maintains its structural integrity even after deletions.

Finally, the code supports efficient search operations, enabling the application to find nodes based on priority values. The `tree_search` function uses a linear search algorithm to find the first node with the specified priority, and returns a pointer to that node if it is found. If no such node is found, the function returns NULL.

Overall, this code provides a robust and efficient implementation of a thread-safe tree data structure for storing nodes with character buffers and integer priorities. It supports dynamic resizing, removal of nodes without causing memory leaks, and efficient search operations, making it suitable for use in a wide range of applications.']

