    }
}

// Define a mechanism to periodically check the health of the allocated memory and log any potential leaks or anomalies
void check_memory() {
    // Check if there are any memory leaks by comparing the current size of the allocated memory with the previous size
    long prev_size = 0;
    while (1) {
        long curr_size = get_allocated_memory();
        if (curr_size > prev_size) {
            printf("Memory leak detected: %ld bytes\n", curr_size - prev_size);
            break;
        } else {
            prev_size = curr_size;
        }
    }
}

// Define a function to resize the arrays if n is increased after initial allocation
void resize_arrays(int new_n) {
    // Reallocate memory for the offset array
    long *new_offset = realloc(offset, new_n * sizeof(long));
    if (new_offset == NULL) {
        printf("Error: Failed to reallocate memory for offset array\n");
        exit(1);
    }
    offset = new_offset;

    // Reallocate memory for the key array
    int *new_key = realloc(key, new_n * sizeof(int));
    if (new_key == NULL) {
        printf("Error: Failed to reallocate memory for key array\n");
        exit(1);
