// Initialize the data structure with a specified number of elements
void initDataStructure(DataStructure* ds, int n) {
    if (n <= 0) {
        // Handle edge case: invalid input
        return;
    }

    // Allocate memory for the record array
    Record* records = malloc(sizeof(Record) * n);
    if (!records) {
        // Handle error: out of memory
        return;
    }

