    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        records[i].value = rand() % 100;
        snprintf(records[i].buffer, sizeof(records[i].buffer), "Record %d", i);
    }

    // Initialize the offset and key arrays with sequential integers
    int* offsets = malloc(sizeof(int) * n);
    if (!offsets) {
        // Handle error: out of memory
        return;
    }
    for (int i = 0; i < n; i++) {
        offsets[i] = i;
    }
    int* keys = malloc(sizeof(int) * n);
    if (!keys) {
        // Handle error: out of memory
        return;
    }
    for (int i = 0; i < n; i++) {
        keys[i] = i;
    }

    // Initialize the data structure with the allocated arrays
    ds->records = records;
    ds->capacity = n;
    ds->offsets = offsets;
    ds->keys = keys;

    // Initialize the mutex for thread-safe operations
    pthread_mutex_init(&ds->mutex, NULL);
}

// Insert a new record into the data structure
void insertRecord(DataStructure* ds, int key, int value) {
    pthread_mutex_lock(&ds->mutex);

    // Check if the data structure is full and needs to be resized
    if (ds->capacity == ds->size) {
        // Reallocate memory for the record array
        Record* newRecords = realloc(ds->records, sizeof(Record) * (ds->capacity + 1));
        if (!newRecords) {
            // Handle error: out of memory
            pthread_mutex_unlock(&ds->mutex);
            return;
        }
        ds->records = newRecords;
        ds->capacity++;
    }

    // Insert the new record into the data structure
    int index = ds->size++;
    ds->records[index].value = value;
    snprintf(ds->records[index].buffer, sizeof(ds->records[index].buffer), "Record %d", key);
    ds->offsets[key] = index;
    ds->keys[index] = key;

    pthread_mutex_unlock(&ds->mutex);
}

// Update a record in the data structure
void updateRecord(DataStructure* ds, int key, int value) {
    pthread_mutex_lock(&ds->mutex);

    // Check if the key exists in the data structure
    if (ds->offsets[key] == -1) {
        // Handle error: key not found
        pthread_mutex_unlock(&ds->mutex);
        return;
    }

    // Update the record value and offset
    int index = ds->offsets[key];
    ds->records[index].value = value;
    ds->offsets[key] = index;

    pthread_mutex_unlock(&ds->mutex);
}

// Retrieve a record from the data structure
Record* getRecord(DataStructure* ds, int key) {
    pthread_mutex_lock(&ds->mutex);

    // Check if the key exists in the data structure
    if (ds->offsets[key] == -1) {
        // Handle error: key not found
        pthread_mutex_unlock(&ds->mutex);
        return NULL;
    }

    // Retrieve the record and its offset
    int index = ds->offsets[key];
    Record* record = &ds->records[index];
    ds->offsets[key] = index;

    pthread_mutex_unlock(&ds->mutex);
    return record;
}

// Remove a record from the data structure
void removeRecord(DataStructure* ds, int key) {
    pthread_mutex_lock(&ds->mutex);

    // Check if the key exists in the data structure
    if (ds->offsets[key] == -1) {
        // Handle error: key not found
        pthread_mutex_unlock(&ds->mutex);
        return;
    }

    // Remove the record and its offset
    int index = ds->offsets[key];
    Record* record = &ds->records[index];
    ds->offsets[key] = -1;
    ds->keys[index] = -1;

    pthread_mutex_unlock(&ds->mutex);
}

// Free the memory allocated for the data structure
void freeDataStructure(DataStructure* ds) {
    // Check if the data structure is empty
    if (ds->size == 0) {
        return;
    }

    // Free the record array and offset arrays
    free(ds->records);
    free(ds->offsets);
    free(ds->keys);

    // Destroy the mutex for thread-safe operations
    pthread_mutex_destroy(&ds->mutex);
}
