    }

    // Unlock the mutex after accessing the shared data
    pthread_mutex_unlock(&mutex);
}

// Function to add a new record to the array
void add_record(int key, long offset, char* buffer, int temperature_reading, char* location_name, double humidity_level, float wind_speed, bool data_quality_flag, enum sensor_type sensor_type) {
    // Lock the mutex before accessing the shared data
    pthread_mutex_lock(&mutex);

    // Check if the array has already been initialized
    if (records == NULL) {
        // If it hasn't, initialize it with a single element
        init_array(1, 0, 0);
    }

    // Allocate memory for the new record
    record* new_record = malloc(sizeof(record));
    assert(new_record != NULL);

    // Copy the data from the input parameters into the new record
    new_record->key = key;
    new_record->offset = offset;
    strcpy(new_record->buffer, buffer);
    new_record->temperature_reading = temperature_reading;
    strcpy(new_record->location_name, location_name);
    new_record->humidity_level = humidity_level;
    new_record->wind_speed = wind_speed;
    new_record->data_quality_flag = data_quality_flag;
    new_record->sensor_type = sensor_type;

    // Add the new record to the end of the array
    records[n++] = *new_record;

    // Unlock the mutex after accessing the shared data
    pthread_mutex_unlock(&mutex);
}

// Function to remove a record from the array by key
void remove_record(int key) {
    // Lock the mutex before accessing the shared data
    pthread_mutex_lock(&mutex);

    // Find the index of the record with the specified key
    int i = 0;
    while (i < n && records[i].key != key) {
        i++;
    }

    // If the record was found, remove it from the array
    if (i < n) {
        for (int j = i; j < n - 1; j++) {
            records[j] = records[j + 1];
        }
        n--;
    }

    // Unlock the mutex after accessing the shared data
    pthread_mutex_unlock(&mutex);
}

// Function to group the entries by location name and calculate the average temperature, humidity, wind speed, timestamp, and sensor accuracy for each group
void group_by_location(void) {
    // Lock the mutex before accessing the shared data
    pthread_mutex_lock(&mutex);

    // Create a hash table to store the grouped records
    int num_groups = 0;
    record** groups = NULL;

    // Iterate over each record in the array
    for (int i = 0; i < n; i++) {
        // Check if the current record is already in a group
        bool found = false;
        for (int j = 0; j < num_groups; j++) {
            if (strcmp(records[i].location_name, groups[j]->location_name) == 0) {
                // If it is, add the record to the group
                groups[j]->temperature_reading += records[i].temperature_reading;
                groups[j]->humidity_level += records[i].humidity_level;
                groups[j]->wind_speed += records[i].wind_speed;
                groups[j]->data_quality_flag = records[i].data_quality_flag || groups[j]->data_quality_flag;
                found = true;
            }
        }

        // If the current record is not in a group, create a new one
        if (!found) {
            num_groups++;
            groups = realloc(groups, num_groups * sizeof(record*));
            assert(groups != NULL);
            groups[num_groups - 1] = malloc(sizeof(record));
            assert(groups[num_groups - 1] != NULL);
            strcpy(groups[num_groups - 1]->location_name, records[i].location_name);
            groups[num_groups - 1]->temperature_reading = records[i].temperature_reading;
            groups[num_groups - 1]->humidity_level = records[i].humidity_level;
            groups[num_groups - 1]->wind_speed = records[i].wind_speed;
            groups[num_groups - 1]->data_quality_flag = records[i].data_quality_flag;
        }
    }

    // Unlock the mutex after accessing the shared data
    pthread_mutex_unlock(&mutex);
}

// Function to calculate the average temperature, humidity, wind speed, timestamp, and sensor accuracy for each group
void calculate_averages(void) {
    // Lock the mutex before accessing the shared data
    pthread_mutex_lock(&mutex);

    // Iterate over each group in the hash table
    for (int i = 0; i < num_groups; i++) {
        groups[i]->temperature_reading /= n;
        groups[i]->humidity_level /= n;
        groups[i]->wind_speed /= n;
        groups[i]->data_quality_flag = true;
    }

    // Unlock the mutex after accessing the shared data
    pthread_mutex_unlock(&mutex);
}

// Function to determine the maximum and minimum wind speeds recorded for each location
void find_wind_speeds(void) {
    // Lock the mutex before accessing the shared data
    pthread_mutex_lock(&mutex);

    // Iterate over each group in the hash table
    for (int i = 0; i < num_groups; i++) {
        int max_wind_speed = -1;
        int min_wind_speed = -1;
        for (int j = 0; j < n; j++) {
            if (strcmp(records[j].location_name, groups[i]->location_name) == 0) {
                if (max_wind_speed < records[j].wind_speed) {
                    max_wind_speed = records[j].wind_speed;
                }
                if (min_wind_speed > records[j].wind_speed || min_wind_speed == -1) {
                    min_wind_speed = records[j].wind_speed;
                }
            }
        }
        groups[i]->max_wind_speed = max_wind_speed;
        groups[i]->min_wind_speed = min_wind_speed;
    }

    // Unlock the mutex after accessing the shared data
    pthread_mutex_unlock(&mutex);
}

// Function to provide a robust error handling mechanism to manage data inconsistencies
void handle_errors(void) {
    // Lock the mutex before accessing the shared data
    pthread_mutex_lock(&mutex);

    // Iterate over each record in the array
    for (int i = 0; i < n; i++) {
        if (!records[i].data_quality_flag) {
            // If the record is inconsistent, remove it from the array
            remove_record(records[i].key);
        }
    }

    // Unlock the mutex after accessing the shared data
    pthread_mutex_unlock(&mutex);
}
