struct weather_station {
    int id;
    float temperature;
    float humidity;
    double pressure;
    char location[256];
    float wind_speed;
    bool weather_condition;
};

// Function to dynamically allocate memory for and initialize one thousand records
struct weather_station* init_records(int num_records) {
    // Validate input parameters
    if (num_records < 500 || num_records > 50000) {
        printf("Invalid number of records. Must be between 500 and 50,000.\n");
        return NULL;
    }

    // Allocate memory for the records
    struct weather_station* records = (struct weather_station*)malloc(num_records * sizeof(struct weather_station));
    if (!records) {
        printf("Failed to allocate memory for records.\n");
        return NULL;
    }

    // Initialize the records with random values within specified ranges
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        records[i].id = i + 1;
        records[i].temperature = -30.0f + (float)(rand() % 81);
        records[i].humidity = (float)(rand() % 101) / 100.0f;
        records[i].pressure = 950.0 + (double)(rand() % 61) * 0.1;
        records[i].wind_speed = 0.0f + (float)(rand() % 61);
        records[i].weather_condition = rand() % 2 == 0 ? true : false;
        strcpy(records[i].location, "Location #");
        records[i].location[strlen(records[i].location) - 1] += i + '0';
    }

    // Validate the input parameters again after initialization
    for (int i = 0; i < num_records; ++i) {
        if (records[i].temperature < -30.0f || records[i].temperature > 50.0f) {
            printf("Invalid temperature value for record %d.\n", i + 1);
            return NULL;
        }
        if (records[i].humidity < 0.0f || records[i].humidity > 100.0f) {
            printf("Invalid humidity value for record %d.\n", i + 1);
            return NULL;
        }
        if (records[i].pressure < 950.0 || records[i].pressure > 1050.0) {
            printf("Invalid pressure value for record %d.\n", i + 1);
            return NULL;
        }
        if (records[i].wind_speed < 0.0f || records[i].wind_speed > 60.0f) {
            printf("Invalid wind speed value for record %d.\n", i + 1);
            return NULL;
        }
    }

    // Group the entries by location and calculate the average temperature, humidity, pressure, wind speed, weather condition, and weather station accuracy for each group
    struct weather_station* groups = (struct weather_station*)malloc(num_records * sizeof(struct weather_station));
    if (!groups) {
        printf("Failed to allocate memory for groups.\n");
        return NULL;
    }
    int num_groups = 0;
    for (int i = 0; i < num_records; ++i) {
        bool found = false;
        for (int j = 0; j < num_groups; ++j) {
            if (strcmp(records[i].location, groups[j].location) == 0) {
                found = true;
                break;
            }
        }
        if (!found) {
            strcpy(groups[num_groups].location, records[i].location);
            groups[num_groups].id = num_groups + 1;
            groups[num_groups].temperature = records[i].temperature;
            groups[num_groups].humidity = records[i].humidity;
            groups[num_groups].pressure = records[i].pressure;
            groups[num_groups].wind_speed = records[i].wind_speed;
            groups[num_groups].weather_condition = records[i].weather_condition;
            ++num_groups;
        } else {
            groups[j].temperature += records[i].temperature;
            groups[j].humidity += records[i].humidity;
            groups[j].pressure += records[i].pressure;
            groups[j].wind_speed += records[i].wind_speed;
            if (records[i].weather_condition) {
                ++groups[j].num_stable_conditions;
            } else {
                ++groups[j].num_unstable_conditions;
            }
        }
    }

    // Compute the average temperature, humidity, pressure, wind speed, weather condition, and weather station accuracy for each group
    for (int i = 0; i < num_groups; ++i) {
        groups[i].temperature /= num_records;
        groups[i].humidity /= num_records;
        groups[i].pressure /= num_records;
        groups[i].wind_speed /= num_records;
        if (groups[i].num_stable_conditions > 0) {
            groups[i].weather_condition = true;
        } else {
            groups[i].weather_condition = false;
        }
    }

    // Compute the standard deviation of wind speeds for each group
    for (int i = 0; i < num_groups; ++i) {
        double sum = 0.0;
        for (int j = 0; j < num_records; ++j) {
            if (strcmp(records[j].location, groups[i].location) == 0) {
                sum += pow(records[j].wind_speed - groups[i].wind_speed, 2);
            }
        }
        groups[i].stddev_wind_speed = sqrt(sum / (num_records - 1));
    }

    return groups;
}
