            hash_value = 0;
        }
    }

    // Return the index of the key, or -1 if not found
    return hash_table->records[hash_value] != NULL ? hash_value : -1;
}

// Function to compare two records by frequency
int compare_records(const void* a, const void* b) {
    Record* record_a = (Record*)a;
    Record* record_b = (Record*)b;
    return record_a->frequency - record_b->frequency;
}

