// Define the data structure for a record in the cache
typedef struct {
    int key;
    char buffer[128];
    float value;
} Record;

// Define the data structure for the cache itself
typedef struct {
    int size; // The current size of the cache
    int capacity; // The maximum capacity of the cache
    int num_records; // The total number of records in the cache
    pthread_mutex_t mutex; // A mutex to protect the cache from concurrent access
    Record* records; // An array of records in the cache
} Cache;

// Define a function to initialize the cache
void init_cache(Cache* cache, int size, int capacity) {
    cache->size = 0;
    cache->capacity = capacity;
    cache->num_records = 0;
    pthread_mutex_init(&cache->mutex, NULL);
    cache->records = (Record*)malloc(sizeof(Record) * capacity);
}

// Define a function to insert a new record into the cache
void insert_record(Cache* cache, int key, char* buffer, float value) {
    pthread_mutex_lock(&cache->mutex);
    // Check if the cache is full and needs to be resized
    if (cache->size == cache->capacity) {
        resize_cache(cache);
    }
    // Insert the new record into the cache
    cache->records[cache->size].key = key;
    strcpy(cache->records[cache->size].buffer, buffer);
    cache->records[cache->size].value = value;
    cache->size++;
    cache->num_records++;
    pthread_mutex_unlock(&cache->mutex);
}

// Define a function to retrieve a record from the cache
Record* get_record(Cache* cache, int key) {
    pthread_mutex_lock(&cache->mutex);
    // Search for the record in the cache
    for (int i = 0; i < cache->size; i++) {
        if (cache->records[i].key == key) {
            Record* record = &cache->records[i];
            pthread_mutex_unlock(&cache->mutex);
            return record;
        }
    }
    // If the record is not found, return NULL
    pthread_mutex_unlock(&cache->mutex);
    return NULL;
}

// Define a function to update a record in the cache
void update_record(Cache* cache, int key, char* buffer, float value) {
    pthread_mutex_lock(&cache->mutex);
    // Search for the record in the cache
    for (int i = 0; i < cache->size; i++) {
        if (cache->records[i].key == key) {
            strcpy(cache->records[i].buffer, buffer);
            cache->records[i].value = value;
            pthread_mutex_unlock(&cache->mutex);
            return;
        }
    }
    // If the record is not found, insert a new one
    insert_record(cache, key, buffer, value);
}

// Define a function to remove a record from the cache
void remove_record(Cache* cache, int key) {
    pthread_mutex_lock(&cache->mutex);
    // Search for the record in the cache
    for (int i = 0; i < cache->size; i++) {
        if (cache->records[i].key == key) {
            // Remove the record from the cache
            cache->num_records--;
            cache->size--;
            memmove(&cache->records[i], &cache->records[i + 1], sizeof(Record) * (cache->size - i));
            pthread_mutex_unlock(&cache->mutex);
            return;
        }
    }
    // If the record is not found, do nothing
    pthread_mutex_unlock(&cache->mutex);
}

// Define a function to resize the cache
void resize_cache(Cache* cache) {
    int new_capacity = cache->capacity * 2;
    Record* new_records = (Record*)malloc(sizeof(Record) * new_capacity);
    for (int i = 0; i < cache->size; i++) {
        new_records[i] = cache->records[i];
    }
    free(cache->records);
    cache->records = new_records;
    cache->capacity = new_capacity;
}

// Define a function to clean up the cache and release all allocated resources
void cleanup_cache(Cache* cache) {
    pthread_mutex_destroy(&cache->mutex);
    free(cache->records);
}
