// Define the data structure for storing records
typedef struct {
    record_t *records;
    size_t num_records;
    size_t capacity;
    pthread_mutex_t mutex;
} record_store_t;

// Function to initialize a record store
void initialize_record_store(record_store_t *store) {
    // Allocate memory for the records array
    store->records = (record_t *)malloc(sizeof(record_t) * INITIAL_CAPACITY);
    if (!store->records) {
        fprintf(stderr, "Failed to allocate memory for record store\n");
        exit(1);
    }

    // Initialize the number of records and capacity
    store->num_records = 0;
    store->capacity = INITIAL_CAPACITY;

    // Initialize the mutex
    pthread_mutex_init(&store->mutex, NULL);
}

// Function to add a record to the store
void add_record(record_store_t *store, unique_id_t id, status_t status, timestamp_t timestamp, score_t score) {
    // Lock the mutex
    pthread_mutex_lock(&store->mutex);

    // Check if the store needs to be resized
    if (store->num_records == store->capacity) {
        // Resize the store by 50%
        size_t new_capacity = store->capacity * 1.5;
        record_t *new_records = (record_t *)realloc(store->records, sizeof(record_t) * new_capacity);
        if (!new_records) {
            fprintf(stderr, "Failed to resize record store\n");
            exit(1);
        }
        store->records = new_records;
        store->capacity = new_capacity;
    }

    // Add the record to the store
    store->records[store->num_records].id = id;
    store->records[store->num_records].status = status;
    store->records[store->num_records].timestamp = timestamp;
    store->records[store->num_records].score = score;
    store->num_records++;

    // Unlock the mutex
    pthread_mutex_unlock(&store->mutex);
}

// Function to update a record in the store
void update_record(record_store_t *store, unique_id_t id, status_t status, timestamp_t timestamp, score_t score) {
    // Lock the mutex
    pthread_mutex_lock(&store->mutex);

    // Find the record with the given ID
    size_t i;
    for (i = 0; i < store->num_records; i++) {
        if (store->records[i].id == id) {
            break;
        }
    }

    // Check if the record was found
    if (i == store->num_records) {
        fprintf(stderr, "Record with ID %d not found\n", id);
        exit(1);
    }

    // Update the record
    store->records[i].status = status;
    store->records[i].timestamp = timestamp;
    store->records[i].score = score;

    // Unlock the mutex
    pthread_mutex_unlock(&store->mutex);
}

// Function to retrieve records from the store based on their status and score range
void get_records(record_store_t *store, status_t status, score_t min_score, score_t max_score) {
    // Lock the mutex
    pthread_mutex_lock(&store->mutex);

    // Find records with the given status and score range
    size_t i;
    for (i = 0; i < store->num_records; i++) {
        if (store->records[i].status == status && store->records[i].score >= min_score && store->records[i].score <= max_score) {
            printf("Record %d: status=%d, timestamp=%ld, score=%.2f\n", i, store->records[i].id, store->records[i].timestamp, store->records[i].score);
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&store->mutex);
}

// Function to remove outdated records from the store
void cleanup(record_store_t *store) {
    // Lock the mutex
    pthread_mutex_lock(&store->mutex);

    // Find the oldest record
    size_t i;
    for (i = 0; i < store->num_records; i++) {
        if (store->records[i].timestamp == 0) {
            break;
        }
    }

    // Check if there are any outdated records
    if (i == store->num_records) {
        fprintf(stderr, "No outdated records found\n");
        exit(1);
    }

    // Remove the oldest record
    free(store->records[i].id);
    store->records[i] = store->records[--store->num_records];

    // Unlock the mutex
    pthread_mutex_unlock(&store->mutex);
}

// Function to validate the consistency of the data structure across all threads
void validate(record_store_t *store) {
    // Lock the mutex
    pthread_mutex_lock(&store->mutex);

    // Check if there are any inconsistencies in the data structure
    for (size_t i = 0; i < store->num_records; i++) {
        if (store->records[i].id == NULL || store->records[i].status == NULL || store->records[i].timestamp == NULL || store->records[i].score == NULL) {
            fprintf(stderr, "Inconsistency found in record %d\n", i);
            exit(1);
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&store->mutex);
}

// Function to log changes to the data structure
void log(record_store_t *store, timestamp_t timestamp, char *operation, record_t *record) {
    // Lock the mutex
    pthread_mutex_lock(&store->mutex);

    // Log the change
    printf("[%ld] %s: id=%d, status=%d, timestamp=%ld, score=%.2f\n", timestamp, operation, record->id, record->status, record->timestamp, record->score);

    // Unlock the mutex
    pthread_mutex_unlock(&store->mutex);
}

// Function to compress the data structure when memory usage exceeds a certain threshold
void compress(record_store_t *store) {
    // Lock the mutex
    pthread_mutex_lock(&store->mutex);

    // Check if the store needs to be compressed
    if (store->capacity > MAX_CAPACITY) {
        // Compress the store by 50%
        size_t new_capacity = store->capacity / 2;
        record_t *new_records = (record_t *)realloc(store->records, sizeof(record_t) * new_capacity);
        if (!new_records) {
            fprintf(stderr, "Failed to compress record store\n");
            exit(1);
        }
        store->records = new_records;
        store->capacity = new_capacity;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&store->mutex);
}

// Function to dynamically resize the data structure
void resize(record_store_t *store, size_t new_capacity) {
    // Lock the mutex
    pthread_mutex_lock(&store->mutex);

    // Check if the new capacity is valid
    if (new_capacity < store->num_records) {
        fprintf(stderr, "Invalid new capacity: %zu\n", new_capacity);
        exit(1);
    }

    // Resize the store
    record_t *new_records = (record_t *)realloc(store->records, sizeof(record_t) * new_capacity);
    if (!new_records) {
        fprintf(stderr, "Failed to resize record store\n");
        exit(1);
    }
    store->records = new_records;
    store->capacity = new_capacity;

    // Unlock the mutex
    pthread_mutex_unlock(&store->mutex);
}
