        // Copy the records from the old data structure to the new one, skipping any duplicates
        int i = 0;
        while (i < data->num_records && i < new_num_records) {
            if (data->records[i].id != data->records[i + 1].id) {
                new_records[i] = data->records[i];
                i++;
            } else {
                i += 2;
            }
        }

        // Update the data structure with the new records
        free(data->records);
        data->num_records = new_num_records;
        data->records = new_records;
    }
}

// Define the function to dynamically resize the data structure when necessary
void resize_data(record_data_t *data, int num_records) {
    // If the number of records exceeds the current capacity of the data structure, resize it
    if (num_records > data->num_records) {
        record_t *new_records = (record_t *)realloc(data->records, sizeof(record_t) * num_records);
        if (new_records == NULL) {
            // If the reallocation fails, log an error and exit the function
            printf("Error: Failed to resize data structure\n");
            return;
        }

        // Update the data structure with the new records
        data->num_records = num_records;
        data->records = new_records;
    }
}
