        event_records[i].event_description[0] = '\0';
        event_records[i].impact_level = 0;
    }
}

// Define the function to update the hash table with new location codes and descriptions
void update_location_codes(char **location_codes, int max_table_size, char *new_code, char *new_description) {
    // Check if the hash table is full
    if (max_table_size == 0) {
        printf("Error: Hash table is full\n");
        return;
    }

    // Find an empty slot in the hash table
    int i = 0;
    while (location_codes[i] != NULL && i < max_table_size) {
        i++;
    }

    // If no empty slot is found, resize the hash table
    if (i == max_table_size) {
        printf("Error: Hash table is full\n");
        return;
    }

    // Allocate memory for the new location code and description
    char *new_code_copy = (char *)malloc(strlen(new_code) + 1);
    if (!new_code_copy) {
        printf("Error: Out of memory\n");
        return;
    }
    strcpy(new_code_copy, new_code);

    char *new_description_copy = (char *)malloc(strlen(new_description) + 1);
    if (!new_description_copy) {
        printf("Error: Out of memory\n");
        free(new_code_copy);
        return;
    }
    strcpy(new_description_copy, new_description);

    // Add the new location code and description to the hash table
    location_codes[i] = new_code_copy;
    location_codes[i + 1] = new_description_copy;
}

// Define the function to reset the entire system to its initial state
void reset_traffic_monitoring_system(int n) {
    // Free all allocated memory
    free(vehicle_counts);
    free(sensor_metadata);
    free(location_codes);
    free(event_records);

    // Reinitialize the arrays with zeros
    vehicle_counts = (int *)malloc(n * sizeof(int));
    memset(vehicle_counts, 0, n * sizeof(int));

    sensor_metadata = (SensorMetadata *)malloc(n * sizeof(SensorMetadata));
    for (int i = 0; i < n; i++) {
        sensor_metadata[i].speed_limit = 50.0f;
        sensor_metadata[i].average_speed = 0;
        sensor_metadata[i].congestion_alert_status = false;
        sensor_metadata[i].incident_code = 'N';
        sensor_metadata[i].event_type = NORMAL;
    }

    location_codes = (char **)malloc(max_table_size * sizeof(char *));
    for (int i = 0; i < max_table_size; i++) {
        location_codes[i] = NULL;
    }

    event_records = (EventRecord *)malloc(n * sizeof(EventRecord));
    for (int i = 0; i < n; i++) {
        event_records[i].timestamp = 0;
        event_records[i].event_description[0] = '\0';
        event_records[i].impact_level = 0;
    }
}

// Define the function to reset only the average speed and congestion alert status to their initial states, leaving other data unchanged
void partial_reset(int n) {
    // Reset the average speed and congestion alert status for each sensor metadata structure
    for (int i = 0; i < n; i++) {
        sensor_metadata[i].average_speed = 0;
        sensor_metadata[i].congestion_alert_status = false;
    }
}
