#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Define the database structure
typedef struct {
    long *offset_array;
    int *key_array;
    Record **record_array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} Database;

// Define the hash table structure
typedef struct {
    long key;
    int index;
} HashTableEntry;

// Define the binary search tree structure
typedef struct {
    long key;
    int index;
} BSTreeNode;

// Function to initialize the database
void init_database(Database *db, size_t capacity) {
    db->offset_array = (long *)malloc(capacity * sizeof(long));
    db->key_array = (int *)malloc(capacity * sizeof(int));
    db->record_array = (Record **)malloc(capacity * sizeof(Record *));
    db->capacity = capacity;
    db->size = 0;
    pthread_mutex_init(&db->mutex, NULL);
}

// Function to insert a new record into the database
void insert_record(Database *db, int key, Record *record) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&db->mutex);

    // Check if the database is full
    if (db->size == db->capacity) {
        // If so, double the capacity of the database
        size_t new_capacity = db->capacity * 2;
        long *new_offset_array = (long *)realloc(db->offset_array, new_capacity * sizeof(long));
        int *new_key_array = (int *)realloc(db->key_array, new_capacity * sizeof(int));
        Record **new_record_array = (Record **)realloc(db->record_array, new_capacity * sizeof(Record *));
        db->offset_array = new_offset_array;
        db->key_array = new_key_array;
        db->record_array = new_record_array;
        db->capacity = new_capacity;
    }

    // Insert the record into the database
    int index = db->size++;
    db->offset_array[index] = 0;
    db->key_array[index] = key;
    db->record_array[index] = record;

    // Update the hash table and binary search tree
    HashTableEntry *hash_table_entry = (HashTableEntry *)malloc(sizeof(HashTableEntry));
    hash_table_entry->key = key;
    hash_table_entry->index = index;
    insert_into_hash_table(db, hash_table_entry);
    BSTreeNode *bst_node = (BSTreeNode *)malloc(sizeof(BSTreeNode));
    bst_node->key = key;
    bst_node->index = index;
    insert_into_binary_search_tree(db, bst_node);

    // Release lock on the mutex
    pthread_mutex_unlock(&db->mutex);
}

// Function to retrieve a record from the database
Record *get_record(Database *db, int key) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&db->mutex);

    // Search for the record in the hash table and binary search tree
    HashTableEntry *hash_table_entry = search_in_hash_table(db, key);
    BSTreeNode *bst_node = search_in_binary_search_tree(db, key);

    // If the record is found, return it
    if (hash_table_entry != NULL && bst_node != NULL) {
        Record *record = db->record_array[hash_table_entry->index];
        pthread_mutex_unlock(&db->mutex);
        return record;
    }

    // If the record is not found, return NULL
    pthread_mutex_unlock(&db->mutex);
    return NULL;
}

// Function to delete a record from the database
void delete_record(Database *db, int key) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&db->mutex);

    // Search for the record in the hash table and binary search tree
    HashTableEntry *hash_table_entry = search_in_hash_table(db, key);
    BSTreeNode *bst_node = search_in_binary_search_tree(db, key);

    // If the record is found, delete it from the database
    if (hash_table_entry != NULL && bst_node != NULL) {
        int index = hash_table_entry->index;
        db->offset_array[index] = 0;
        db->key_array[index] = 0;
        db->record_array[index] = NULL;
        delete_from_hash_table(db, hash_table_entry);
        delete_from_binary_search_tree(db, bst_node);
    }

    // Release lock on the mutex
    pthread_mutex_unlock(&db->mutex);
}

// Function to set the value of a record's int field to a random value within a specified range
void set_record_value(Database *db, int key, int min, int max) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&db->mutex);

    // Search for the record in the hash table and binary search tree
    HashTableEntry *hash_table_entry = search_in_hash_table(db, key);
    BSTreeNode *bst_node = search_in_binary_search_tree(db, key);

    // If the record is found, set its value to a random value within the specified range
    if (hash_table_entry != NULL && bst_node != NULL) {
        int index = hash_table_entry->index;
        db->record_array[index]->value = rand() % (max - min + 1) + min;
    }

    // Release lock on the mutex
    pthread_mutex_unlock(&db->mutex);
}

// Function to monitor and report memory usage and performance metrics
void monitor_database(Database *db) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&db->mutex);

    // Calculate the total memory usage of the database
    size_t total_memory = 0;
    for (int i = 0; i < db->size; i++) {
        total_memory += sizeof(long) + sizeof(int) + sizeof(Record *);
    }

    // Calculate the average memory usage per record
    size_t average_memory = 0;
    if (db->size > 0) {
        average_memory = total_memory / db->size;
    }

    // Print the memory usage and performance metrics to stdout
    printf("Memory Usage: %zu bytes\n", total_memory);
    printf("Average Memory Per Record: %zu bytes\n", average_memory);

    // Release lock on the mutex
    pthread_mutex_unlock(&db->mutex);
}

// Function to insert an entry into the hash table
void insert_into_hash_table(Database *db, HashTableEntry *entry) {
    int index = entry->key % db->capacity;
    while (db->offset_array[index] != 0) {
        index++;
        if (index == db->capacity) {
            index = 0;
        }
    }
    db->offset_array[index] = entry->key;
    db->key_array[index] = entry->index;
}

// Function to search for an entry in the hash table
HashTableEntry *search_in_hash_table(Database *db, int key) {
    int index = key % db->capacity;
    while (db->offset_array[index] != 0 && db->offset_array[index] != key) {
        index++;
        if (index == db->capacity) {
            index = 0;
        }
    }
    if (db->offset_array[index] == key) {
        return &(db->key_array[index]);
    } else {
        return NULL;
    }
}

// Function to delete an entry from the hash table
void delete_from_hash_table(Database *db, HashTableEntry *entry) {
    int index = entry->key % db->capacity;
    while (db->offset_array[index] != 0 && db->offset_array[index] != entry->key) {
        index++;
        if (index == db->capacity) {
            index = 0;
        }
    }
    db->offset_array[index] = 0;
}

// Function to insert an entry into the binary search tree
void insert_into_binary_search_tree(Database *db, BSTreeNode *node) {
    int index = node->key % db->capacity;
    while (db->offset_array[index] != 0 && db->offset_array[index] != node->key) {
        index++;
        if (index == db->capacity) {
            index = 0;
        }
    }
    db->offset_array[index] = node->key;
    db->key_array[index] = node->index;
}

// Function to search for an entry in the binary search tree
BSTreeNode *search_in_binary_search_tree(Database *db, int key) {
    int index = key % db->capacity;
    while (db->offset_array[index] != 0 && db->offset_array[index] != key) {
        index++;
        if (index == db->capacity) {
            index = 0;
        }
    }
    if (db->offset_array[index] == key) {
        return &(db->key_array[index]);
    } else {
        return NULL;
    }
}

// Function to delete an entry from the binary search tree
void delete_from_binary_search_tree(Database *db, BSTreeNode *node) {
    int index = node->key % db->capacity;
    while (db->offset_array[index] != 0 && db->offset_array[index] != node->key) {
        index++;
        if (index == db->capacity) {
            index = 0;
        }
    }
    db->offset_array[index] = 0;
}
