    // Check if the key exists in the hash table
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] == key) {
            return ht->records[i];
        }
    }
    return NULL;
}

// Define a function to serialize the hash table to a file
void serializeHashTable(HashTable *ht, FILE *file) {
    // Write the size of the hash table to the file
    fwrite(&ht->size, sizeof(int), 1, file);

    // Write each record in the hash table to the file
    for (int i = 0; i < ht->size; i++) {
        Record *record = ht->records[i];
        fwrite(&record->value, sizeof(int), 1, file);
    }
}

// Define a function to deserialize the hash table from a file
void deserializeHashTable(HashTable *ht, FILE *file) {
    // Read the size of the hash table from the file
    fread(&ht->size, sizeof(int), 1, file);

    // Allocate memory for the hash table
    initHashTable(ht, ht->size);

