        fread(&record->value, sizeof(int), 1, file);
        insertRecord(ht, i, record);
    }
}

// Define a function to compact the hash table by removing unused entries
void compactHashTable(HashTable *ht) {
    // Create a new hash table with half the capacity of the current one
    HashTable new_ht;
    initHashTable(&new_ht, ht->capacity / 2);

    // Copy each record from the old hash table to the new one
