// Define a function to delete a record from the hash table using separate chaining
void deleteRecordSeparateChaining(HashTable *ht, int key) {
    // Check if the key exists in the hash table
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] == key) {
            // Remove the record from the hash table
            free(ht->records[i]);
            ht->offsets[i] = ht->offsets[ht->size - 1];
            ht->keys[i] = ht->keys[ht->size - 1];
            ht->records[i] = ht->records[ht->size - 1];
            ht->size--;
            return;
        }
    }
