#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

// Define structures for network monitoring system
typedef struct link_t {
    int latency;
} link_t;

typedef struct status_t {
    int status_code;
} status_t;

typedef struct identifier_t {
    char error_code;
} identifier_t;

typedef struct record_t {
    time_t timestamp;
    char event_description;
    int status_code;
    float latency;
} record_t;

// Define functions for network monitoring system
void setup_network_monitoring_system(int n) {
    // Allocate memory for arrays of integers and structures
    link_t *links = malloc(n * sizeof(link_t));
    status_t *statuses = malloc(n * sizeof(status_t));
    identifier_t *identifiers = malloc(n * sizeof(identifier_t));
    record_t *records = malloc(n * sizeof(record_t));

    // Initialize arrays with random latency values and status codes
    for (int i = 0; i < n; i++) {
        links[i].latency = rand() % 100 + 1;
        statuses[i].status_code = 0;
        identifiers[i].error_code = 'N';
    }

    // Initialize linked list of node metadata
    struct node_metadata {
        float bandwidth_threshold;
        int average_utilization_percentage;
        bool overload_status;
        char error_code;
        enum event_type;
    };

    // Allocate memory for linked list of node metadata
    struct node_metadata *node_metadata = malloc(n * sizeof(struct node_metadata));

    // Initialize linked list with provided bandwidth utilization percentages and thresholds
    for (int i = 0; i < n; i++) {
        node_metadata[i].bandwidth_threshold = rand() % 100 + 1;
        node_metadata[i].average_utilization_percentage = 0;
        node_metadata[i].overload_status = false;
        node_metadata[i].error_code = 'N';
    }

    // Allocate memory for hash table of IP addresses and descriptions
    struct ip_address {
        char *ip_address;
        char *description;
    };

    // Initialize hash table with maximum size defined by parameter max_table_size
    struct ip_address *hash_table = malloc(max_table_size * sizeof(struct ip_address));

    // Reset function to free all allocated memory, reinitialize arrays with zeros, and set overload status to false
    void reset() {
        for (int i = 0; i < n; i++) {
            links[i].latency = 0;
            statuses[i].status_code = 0;
            identifiers[i].error_code = 'N';
            records[i].timestamp = 0;
            records[i].event_description = '\0';
            records[i].status_code = 0;
            records[i].latency = 0.0f;
        }

        for (int i = 0; i < n; i++) {
            node_metadata[i].bandwidth_threshold = 0;
            node_metadata[i].average_utilization_percentage = 0;
            node_metadata[i].overload_status = false;
            node_metadata[i].error_code = 'N';
        }

        for (int i = 0; i < max_table_size; i++) {
            hash_table[i].ip_address = NULL;
            hash_table[i].description = NULL;
        }
    }

    // Partial reset function to reset only the average utilization percentage and overload status to their initial states, leaving other data unchanged
    void partial_reset() {
        for (int i = 0; i < n; i++) {
            node_metadata[i].average_utilization_percentage = 0;
            node_metadata[i].overload_status = false;
        }
    }

    // Update hash table with new IP addresses and descriptions, ensuring the hash table does not exceed a maximum size defined by parameter max_table_size
    void update_hash_table(char *ip_address, char *description) {
        if (hash_table[max_table_size - 1].ip_address != NULL) {
            // Resize hash table to accommodate new IP address and description
            struct ip_address *new_hash_table = realloc(hash_table, (max_table_size + 1) * sizeof(struct ip_address));
            if (new_hash_table == NULL) {
                // Handle out-of-memory condition gracefully by logging error without crashing program
                printf("Error: Out of memory\n");
                return;
            }

            hash_table = new_hash_table;
        }

        // Insert new IP address and description into hash table
        hash_table[max_table_size - 1].ip_address = ip_address;
        hash_table[max_table_size - 1].description = description;
    }
}
