// Define the allocator function
void AdvancedDynamicMemoryAllocator(void* data, size_t size) {
    // Check if the input is valid
    if (data == NULL || size <= 0) {
        return;
    }

    // Get the hash table and random value generator from the data structure
    HashTable* hash_table = (HashTable*)data;
    RandomValueGenerator* random_value_generator = (RandomValueGenerator*)hash_table->records[0];

    // Check if the size is within the bounds of the hash table
    if (size > hash_table->capacity) {
        return;
    }

    // Generate a random value for the record
    int random_value = RandomValueGenerator_Generate(random_value_generator);

    // Set the value of the record to the random value
    Record* record = (Record*)malloc(sizeof(Record));
    record->value = random_value;

    // Add the record to the hash table
    hash_table->records[size] = record;

    // Increment the allocation count and current memory consumption
    hash_table->allocations++;
    hash_table->current_memory_consumption += sizeof(Record);
}

// Define the resizing function
void AdvancedDynamicMemoryAllocator_Resize(void* data, size_t new_size) {
    // Check if the input is valid
    if (data == NULL || new_size <= 0) {
        return;
    }

    // Get the hash table and random value generator from the data structure
    HashTable* hash_table = (HashTable*)data;
    RandomValueGenerator* random_value_generator = (RandomValueGenerator*)hash_table->records[0];

    // Check if the new size is within the bounds of the hash table
    if (new_size > hash_table->capacity) {
        return;
    }

    // Resize the hash table to the new size
    hash_table->records = realloc(hash_table->records, sizeof(Record*) * new_size);
    hash_table->capacity = new_size;

    // Update the allocation count and current memory consumption
    hash_table->allocations += (new_size - hash_table->size);
    hash_table->current_memory_consumption += sizeof(Record) * (new_size - hash_table->size);
}

// Define the deallocation function
void AdvancedDynamicMemoryAllocator_Deallocate(void* data, size_t size) {
    // Check if the input is valid
    if (data == NULL || size <= 0) {
        return;
    }

    // Get the hash table and random value generator from the data structure
    HashTable* hash_table = (HashTable*)data;
    RandomValueGenerator* random_value_generator = (RandomValueGenerator*)hash_table->records[0];

    // Check if the size is within the bounds of the hash table
    if (size > hash_table->capacity) {
        return;
    }

    // Deallocate the record at the specified index
    free(hash_table->records[size]);

    // Decrement the allocation count and current memory consumption
    hash_table->allocations--;
    hash_table->current_memory_consumption -= sizeof(Record);
}

// Define the tracking function
void AdvancedDynamicMemoryAllocator_TrackMemoryUsage(void* data) {
    // Check if the input is valid
    if (data == NULL) {
        return;
    }

    // Get the hash table and random value generator from the data structure
    HashTable* hash_table = (HashTable*)data;
    RandomValueGenerator* random_value_generator = (RandomValueGenerator*)hash_table->records[0];

    // Print the memory usage statistics
