    // Check if the input is valid
    if (generator == NULL) {
        return 0;
    }

    // Generate a random value based on the seed and precision
    int random_value = rand() % (generator->max_value - generator->min_value + 1) + generator->min_value;

    // Return the generated value
    return random_value;
}

int RandomValueGenerator_GenerateInclusive(RandomValueGenerator* generator, int min_value, int max_value) {
    // Check if the input is valid
    if (generator == NULL || min_value > max_value) {
        return 0;
    }

    // Generate a random value within the specified range
    int random_value = rand() % (max_value - min_value + 1) + min_value;

    // Return the generated value
    return random_value;
}

int RandomValueGenerator_GenerateExclusive(RandomValueGenerator* generator, int max_value) {
    // Check if the input is valid
    if (generator == NULL || max_value <= 0) {
        return 0;
    }

    // Generate a random value within the specified range
    int random_value = rand() % max_value;

    // Return the generated value
    return random_value;
}

float RandomValueGenerator_GenerateFloat(RandomValueGenerator* generator) {
    // Check if the input is valid
    if (generator == NULL) {
        return 0.0f;
    }

    // Generate a random value within the specified range
    float random_value = ((float)rand() / RAND_MAX) * generator->precision + generator->min_value;

    // Return the generated value
    return random_value;
}

float RandomValueGenerator_GenerateFloatInclusive(RandomValueGenerator* generator, float min_value, float max_value) {
    // Check if the input is valid
    if (generator == NULL || min_value > max_value) {
        return 0.0f;
    }

    // Generate a random value within the specified range
    float random_value = ((float)rand() / RAND_MAX) * (max_value - min_value) + min_value;

    // Return the generated value
    return random_value;
}

