// Define the string conversion functions for logging levels
const char* LogLevelToString(LogLevel level) {
    // Check if the input is valid
    if (level < DEBUG || level > ERROR) {
        return NULL;
    }

    // Convert the logging level to a string
    switch (level) {
        case DEBUG:
            return "DEBUG";
        case INFO:
            return "INFO";
        case WARNING:
            return "WARNING";
        case ERROR:
            return "ERROR";
        default:
            return NULL;
    }
