            handle_error(pool, hostname, port, -1);
            continue;
        }
        printf("Received data: %s\n", received_data);
        free(received_data);
        if (disconnect_from_server(pool, hostname, port) < 0) {
            handle_error(pool, hostname, port, -1);
            continue;
        }
    }
    return 0;
}
