// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Function to manage a collection of records in a memory-efficient manner
void manage_records(int num_records, int min_value, int max_value) {
    // Allocate and initialize the arrays for offsets and keys
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    Record *records = malloc(num_records * sizeof(Record));

    // Initialize the arrays with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (max_value - min_value + 1) + min_value;
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
    }

    // Initialize the records with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    // Handle allocation failures and other runtime errors gracefully
    if (!offsets || !keys || !records) {
        printf("Error: Failed to allocate memory for records\n");
        return;
    }

    // Integrate with external data sources for generating random values
    // ...

    // Free the allocated memory when done
    free(offsets);
    free(keys);
    free(records);
}
```
