        sensor_metadata[i].incident_code = '\0';
        sensor_metadata[i].event_type = OTHER;
    }

    // Allocate memory for a hash table to store location codes and descriptions
    char **location_codes = (char **)malloc(max_table_size * sizeof(char *));
    if (!location_codes) {
        printf("Error: Out of memory\n");
        exit(1);
    }

    // Initialize the hash table with default values
    for (int i = 0; i < max_table_size; i++) {
        location_codes[i] = NULL;
    }

    // Allocate memory for an array of record structures
    record_t *event_records = (record_t *)malloc(n * sizeof(record_t));
    if (!event_records) {
        printf("Error: Out of memory\n");
        exit(1);
    }

    // Initialize the array of record structures with default values
    for (int i = 0; i < n; i++) {
        event_records[i].timestamp = 0;
        event_records[i].event_description[0] = '\0';
        event_records[i].impact_level = 0;
    }
}

