    sensor_metadata->average_speed = 0;
    sensor_metadata->congestion_alert_status = false;
}

// Define a function to update the hash table with new location codes and descriptions
void update_location_codes(char **location_codes, int max_table_size, char *new_code, char *new_description) {
    // Check if the hash table is full
    if (max_table_size <= 0) {
        printf("Error: Hash table is full\n");
        exit(1);
    }

    // Find an empty slot in the hash table
    int i = 0;
    while (location_codes[i] != NULL && i < max_table_size) {
        i++;
    }

    // If no empty slots were found, resize the hash table
    if (i == max_table_size) {
        location_codes = (char **)realloc(location_codes, (max_table_size + 1) * sizeof(char *));
        if (!location_codes) {
            printf("Error: Out of memory\n");
            exit(1);
        }
    }

    // Add the new location code and description to the hash table
    location_codes[i] = (char *)malloc((strlen(new_code) + 1) * sizeof(char));
    if (!location_codes[i]) {
        printf("Error: Out of memory\n");
        exit(1);
    }
    strcpy(location_codes[i], new_code);
    location_codes[i][strlen(new_code)] = '\0';
}
