void free_memory(int* resource_counts, ResourceMetadata* metadata) {
    if (resource_counts) {
        free(resource_counts);
    }
    if (metadata) {
        free(metadata);
    }
}

// Function to initialize the hash table with a configurable maximum size
void init_hash_table(HashTable* table, int max_size) {
    table->size = 0;
    table->capacity = max_size;
    table->metadata = (ResourceMetadata*)malloc(max_size * sizeof(ResourceMetadata));
    if (!table->metadata) {
        printf("Error: Failed to allocate memory for hash table\n");
        return;
    }
    memset(table->metadata, 0, max_size * sizeof(ResourceMetadata));
}

// Function to insert a new resource type into the hash table
void insert_resource_type(HashTable* table, char* resource_type) {
    if (table->size == table->capacity) {
        // Resize the hash table if it is full
        int new_capacity = table->capacity * 2;
        ResourceMetadata* new_metadata = (ResourceMetadata*)realloc(table->metadata, new_capacity * sizeof(ResourceMetadata));
        if (!new_metadata) {
            printf("Error: Failed to resize hash table\n");
            return;
        }
        table->metadata = new_metadata;
        table->capacity = new_capacity;
    }
    // Insert the new resource type into the hash table
    int index = hash(resource_type);
    while (table->metadata[index].resource_type != NULL) {
        index++;
        if (index == table->capacity) {
            index = 0;
        }
    }
    strcpy(table->metadata[index].resource_type, resource_type);
    table->size++;
}

// Function to retrieve the metadata for a given resource type from the hash table
ResourceMetadata* get_resource_metadata(HashTable* table, char* resource_type) {
    int index = hash(resource_type);
    while (table->metadata[index].resource_type != NULL && strcmp(table->metadata[index].resource_type, resource_type) != 0) {
        index++;
        if (index == table->capacity) {
            index = 0;
        }
    }
    return &table->metadata[index];
}

// Function to update the metadata for a given resource type in the hash table
void update_resource_metadata(HashTable* table, char* resource_type, int capacity, float average_usage, bool alert_status, char* incident_code) {
    ResourceMetadata* metadata = get_resource_metadata(table, resource_type);
    if (metadata != NULL) {
        metadata->capacity = capacity;
        metadata->average_usage = average_usage;
        metadata->alert_status = alert_status;
        strcpy(metadata->incident_code, incident_code);
    }
}

// Function to handle memory allocation and deallocation for resource events
ResourceEvent* allocate_resource_events(int n) {
    ResourceEvent* events = (ResourceEvent*)malloc(n * sizeof(ResourceEvent));
    if (!events) {
        printf("Error: Failed to allocate memory for resource events\n");
        return NULL;
    }
    memset(events, 0, n * sizeof(ResourceEvent));
    return events;
}

// Function to handle memory allocation and deallocation for the linked list of metadata records
void free_metadata_records(ResourceMetadata* metadata) {
    if (metadata != NULL) {
        free(metadata);
    }
}

// Function to initialize the linked list of metadata records
void init_metadata_records(ResourceMetadata** metadata, int n) {
    *metadata = allocate_metadata_records(n);
    if (*metadata == NULL) {
        printf("Error: Failed to allocate memory for metadata records\n");
        return;
    }
}

// Function to insert a new resource event into the linked list of metadata records
void insert_resource_event(ResourceMetadata** metadata, long timestamp, char* event_description, int utilization_metric) {
    ResourceEvent* event = (ResourceEvent*)malloc(sizeof(ResourceEvent));
    if (!event) {
        printf("Error: Failed to allocate memory for resource event\n");
        return;
    }
    event->timestamp = timestamp;
    strcpy(event->event_description, event_description);
    event->utilization_metric = utilization_metric;
    // Insert the new resource event into the linked list of metadata records
    ResourceMetadata* current = *metadata;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = event;
}

// Function to retrieve the metadata for a given resource type from the linked list of metadata records
ResourceMetadata* get_resource_event(ResourceMetadata** metadata, char* resource_type) {
    ResourceMetadata* current = *metadata;
    while (current != NULL && strcmp(current->resource_type, resource_type) != 0) {
        current = current->next;
    }
    return current;
}

// Function to update the metadata for a given resource type in the linked list of metadata records
void update_resource_event(ResourceMetadata** metadata, char* resource_type, long timestamp, char* event_description, int utilization_metric) {
    ResourceMetadata* event = get_resource_event(metadata, resource_type);
    if (event != NULL) {
        event->timestamp = timestamp;
        strcpy(event->event_description, event_description);
        event->utilization_metric = utilization_metric;
    }
}

