#include <stdlib.h>
#include <string.h>
#include <pthread.h>

struct account {
    int customer_id;
    double balance;
    char* transaction_ids;
    char* timestamps;
};

void process_transactions(int transaction_id, int customer_id, double amount, char* timestamp) {
    // Validate the transaction details using a service class
    if (!validate_transaction(transaction_id, customer_id, amount, timestamp)) {
        return;
    }

    // Dynamically allocate memory for and initialize three arrays: one for 'double' transaction amounts, one for 'char*' transaction descriptions, and one for 'struct account' objects
    double* transaction_amounts = malloc(sizeof(double) * 10);
    char** transaction_descriptions = malloc(sizeof(char*) * 10);
    struct account* accounts = malloc(sizeof(struct account) * 10);

    // Initialize the arrays with the transaction details
    for (int i = 0; i < 10; i++) {
        transaction_amounts[i] = amount;
        transaction_descriptions[i] = strdup(timestamp);
        accounts[i].customer_id = customer_id;
        accounts[i].balance = 0.0;
        accounts[i].transaction_ids = malloc(sizeof(char*) * 10);
        accounts[i].timestamps = malloc(sizeof(char*) * 10);
    }

    // Update the balance of each account concurrently using a mutex
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    for (int i = 0; i < 10; i++) {
        pthread_mutex_lock(&mutex);
        accounts[i].balance += transaction_amounts[i];
        pthread_mutex_unlock(&mutex);
    }
    pthread_mutex_destroy(&mutex);

    // Track the number of transactions per customer and calculate the average transaction amount per customer
    int num_transactions = 0;
    double total_transaction_amount = 0.0;
    for (int i = 0; i < 10; i++) {
        num_transactions++;
        total_transaction_amount += transaction_amounts[i];
    }
    double average_transaction_amount = total_transaction_amount / num_transactions;

    // Return a response indicating that the transaction has been processed successfully, along with a summary of the total number of transactions and the average transaction amount per customer
    printf("Transaction processed successfully.\n");
    printf("Total number of transactions: %d\n", num_transactions);
    printf("Average transaction amount per customer: %.2f\n", average_transaction_amount);
}
