#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <math.h>

// Define the structure for sensor data
struct sensor_data {
    long offset;
    int key;
    int temperature;
    char location[20];
    double humidity;
    float wind_speed;
    enum weather_type cloud_cover;
    bool precipitation;
    time_t timestamp;
    float atmospheric_pressure;
};

// Define the structure for sensor locations
struct sensor_location {
    int geographic_id;
    int altitude;
};

// Define the record structure
struct record {
    int value;
    int temperature;
    char location[20];
    double humidity;
    float wind_speed;
    enum weather_type cloud_cover;
    bool precipitation;
    time_t timestamp;
    float atmospheric_pressure;
};

// Define the function to initialize the data
void init_data(int num_records, struct record *records) {
    // Validate the input parameters
    if (num_records < 500 || num_records > 50000) {
        printf("Invalid number of records: %d\n", num_records);
        return;
    }

    for (int i = 0; i < num_records; i++) {
        // Set the value of each record's fields to random values within given ranges
        records[i].value = rand() % 1000;
        records[i].temperature = round((rand() % 120 - 60) / 10.0);
        records[i].humidity = (rand() % 100) / 100.0;
        records[i].wind_speed = rand() % 30;
        records[i].atmospheric_pressure = round((rand() % 2000 - 1000) / 100.0);
        records[i].cloud_cover = (enum weather_type)(rand() % 4);
        records[i].precipitation = rand() % 2;
        records[i].timestamp = time(NULL) + rand() % 365 * 86400;
    }
}

// Define the function to group the entries by location name and calculate the average temperature, humidity, wind speed, atmospheric pressure, timestamp, cloud cover percentage, and sensor accuracy for each group
void group_data(int num_records, struct record *records) {
    // Create a hash table to store the grouped data
    struct hash_table *hash = create_hash_table();

    // Loop through all records and add them to the hash table
    for (int i = 0; i < num_records; i++) {
        // Get the location name of the current record
        char *location = records[i].location;

        // Check if the location is already in the hash table
        struct sensor_location *sensor_loc = (struct sensor_location *)hash_get(hash, location);
        if (!sensor_loc) {
            // If not, create a new entry for it
            sensor_loc = malloc(sizeof(struct sensor_location));
            strcpy(sensor_loc->location, location);
            hash_put(hash, location, sensor_loc);
        }

        // Add the current record to the list of records for this location
        struct record *record = malloc(sizeof(struct record));
        memcpy(record, &records[i], sizeof(struct record));
        record->next = sensor_loc->records;
        sensor_loc->records = record;
    }

    // Loop through all locations and calculate the average values for each group
    struct hash_table_iterator *it = hash_get_iterator(hash);
    while (hash_has_next(it)) {
        char *location = hash_next_key(it);
        struct sensor_location *sensor_loc = hash_next_value(it);

        // Calculate the average temperature, humidity, wind speed, atmospheric pressure, timestamp, cloud cover percentage, and sensor accuracy for this group
        double avg_temperature = 0;
        double avg_humidity = 0;
        double avg_wind_speed = 0;
        double avg_atmospheric_pressure = 0;
        time_t avg_timestamp = 0;
        int avg_cloud_cover = 0;
        int avg_precipitation = 0;
        float avg_sensor_accuracy = 0;
        struct record *record = sensor_loc->records;
        while (record) {
            avg_temperature += record->temperature;
            avg_humidity += record->humidity;
            avg_wind_speed += record->wind_speed;
            avg_atmospheric_pressure += record->atmospheric_pressure;
            avg_timestamp += record->timestamp;
            avg_cloud_cover += record->cloud_cover;
            avg_precipitation += record->precipitation;
            avg_sensor_accuracy += record->value;
            record = record->next;
        }

        // Calculate the standard deviation of temperatures for this group
        double stddev_temperature = 0;
        record = sensor_loc->records;
        while (record) {
            double diff = record->temperature - avg_temperature;
            stddev_temperature += diff * diff;
            record = record->next;
        }
        stddev_temperature /= num_records - 1;
        stddev_temperature = sqrt(stddev_temperature);

        // Print the results for this group
        printf("Location: %s\n", location);
        printf("Average temperature: %.2f\n", avg_temperature / num_records);
        printf("Standard deviation of temperatures: %.2f\n", stddev_temperature);
        printf("Average humidity: %.2f\n", avg_humidity / num_records);
        printf("Average wind speed: %.2f\n", avg_wind_speed / num_records);
        printf("Average atmospheric pressure: %.2f\n", avg_atmospheric_pressure / num_records);
        printf("Average timestamp: %ld\n", avg_timestamp / num_records);
        printf("Average cloud cover percentage: %.2f\n", (float)avg_cloud_cover / num_records);
        printf("Average precipitation flag: %d\n", avg_precipitation / num_records);
        printf("Average sensor accuracy: %.2f\n", avg_sensor_accuracy / num_records);
    }

    // Free the hash table and its contents
    free_hash_table(hash, true);
}
