#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

// Define the structure for sensor data
typedef struct {
    long offset;
    int key;
    int temperature;
    char location[256];
    double humidity;
    float wind_speed;
    enum weather_type cloud_cover;
    bool precipitation;
    time_t timestamp;
    float atmospheric_pressure;
} record;

// Define the structure for sensor location data
typedef struct {
    int geographic_id;
    int altitude;
} sensor_location;

// Function to dynamically allocate memory for and initialize multiple arrays
void init_data(int num_records, int temperature_range, int humidity_range, int wind_speed_range, int atmospheric_pressure_range, int cloud_cover_types, bool precipitation_flags) {
    // Validate input parameters
    if (num_records < 500 || num_records > 50000) {
        printf("Invalid number of records: %d\n", num_records);
        return;
    }
    if (temperature_range < -60 || temperature_range > 60) {
        printf("Invalid temperature range: %d\n", temperature_range);
        return;
    }
    if (humidity_range < 0 || humidity_range > 100) {
        printf("Invalid humidity range: %d\n", humidity_range);
        return;
    }
    if (wind_speed_range < 0 || wind_speed_range > 30) {
        printf("Invalid wind speed range: %d\n", wind_speed_range);
        return;
    }
    if (atmospheric_pressure_range < 900 || atmospheric_pressure_range > 1100) {
        printf("Invalid atmospheric pressure range: %d\n", atmospheric_pressure_range);
        return;
    }
    if (cloud_cover_types != 0 && cloud_cover_types != 1) {
        printf("Invalid number of cloud cover types: %d\n", cloud_cover_types);
        return;
    }
    if (precipitation_flags != true && precipitation_flags != false) {
        printf("Invalid value for precipitation flags: %s\n", (precipitation_flags ? "true" : "false"));
        return;
    }

    // Allocate memory for arrays
    record *records = malloc(num_records * sizeof(record));
    sensor_location *sensor_locations = malloc(num_records * sizeof(sensor_location));

    // Initialize arrays with random values within given ranges
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand() % 1000000;
        records[i].key = rand() % 1000000;
        records[i].temperature = round(rand() % temperature_range * 10) / 10;
        records[i].humidity = (float)(rand() % humidity_range) / 100;
        records[i].wind_speed = (float)(rand() % wind_speed_range) / 10;
        records[i].atmospheric_pressure = (float)(rand() % atmospheric_pressure_range) / 10;
        records[i].cloud_cover = rand() % cloud_cover_types;
        records[i].precipitation = (bool)(rand() % 2);
        records[i].timestamp = time(NULL) + rand() % 365 * 86400;
        sensor_locations[i].geographic_id = rand() % 1000000;
        sensor_locations[i].altitude = rand() % 1000000;
    }

    // Group records by location name and calculate averages
    int num_groups = 0;
    for (int i = 0; i < num_records; i++) {
        bool found = false;
        for (int j = 0; j < num_groups; j++) {
            if (strcmp(sensor_locations[i].location, sensor_locations[j].location) == 0) {
                found = true;
                break;
            }
        }
        if (!found) {
            num_groups++;
        }
    }
    record *grouped_records = malloc(num_groups * sizeof(record));
    sensor_location *grouped_sensor_locations = malloc(num_groups * sizeof(sensor_location));
    int group_index = 0;
    for (int i = 0; i < num_records; i++) {
        bool found = false;
        for (int j = 0; j < num_groups; j++) {
            if (strcmp(sensor_locations[i].location, sensor_locations[j].location) == 0) {
                grouped_records[group_index] = records[i];
                grouped_sensor_locations[group_index] = sensor_locations[i];
                found = true;
                break;
            }
        }
        if (!found) {
            grouped_records[group_index] = records[i];
            grouped_sensor_locations[group_index] = sensor_locations[i];
            group_index++;
        }
    }
    for (int i = 0; i < num_groups; i++) {
        printf("Group %d: Location=%s, Temperature=%.2f, Humidity=%.2f, Wind Speed=%.2f, Atmospheric Pressure=%.2f, Cloud Cover=%d, Precipitation=%s\n", i + 1, grouped_sensor_locations[i].location, grouped_records[i].temperature, grouped_records[i].humidity, grouped_records[i].wind_speed, grouped_records[i].atmospheric_pressure, grouped_records[i].cloud_cover, (grouped_records[i].precipitation ? "true" : "false"));
    }

    // Compute standard deviation of temperatures
    double sum = 0;
    for (int i = 0; i < num_groups; i++) {
        sum += grouped_records[i].temperature;
    }
    double mean = sum / num_groups;
    double temp_sum = 0;
    for (int i = 0; i < num_groups; i++) {
        temp_sum += pow(grouped_records[i].temperature - mean, 2);
    }
    double stddev = sqrt(temp_sum / (num_groups - 1));
    printf("Standard deviation of temperatures: %.2f\n", stddev);

    // Free memory
    free(records);
    free(sensor_locations);
    free(grouped_records);
    free(grouped_sensor_locations);
}
