        data[i].city_name[2] = 'C';
        data[i].population = rand() % 100000 + 1;
        data[i].annual_rainfall = rand() % 4000 + 1;
        data[i].climate = (enum climate_type)rand() % 3;
        data[i].average_temperature = ((float)rand() / RAND_MAX) * 50 - 25;
        data[i].vegetation = (enum vegetation_type)rand() % 4;
        data[i].years_since_event = rand() % 100 + 1;
        data[i].AQI = ((float)rand() / RAND_MAX) * 500;
        data[i].urbanization = (bool)(rand() % 2);
    }

    // Group the entries by city name and calculate the average temperature, annual rainfall, AQI, elevation, years since last major environmental event, latitude, and longitude for each group
    struct CityGroup *groups = malloc(sizeof(struct CityGroup) * num_records);
    if (groups == NULL) {
        printf("Failed to allocate memory for groups array\n");
        return;
    }

    // Initialize the groups array with default values
    for (int i = 0; i < num_records; i++) {
        groups[i].city_name[0] = 'A';
        groups[i].city_name[1] = 'B';
        groups[i].city_name[2] = 'C';
        groups[i].average_latitude = 0;
        groups[i].average_longitude = 0;
        groups[i].average_elevation = 0;
        groups[i].average_population = 0;
        groups[i].average_annual_rainfall = 0;
        groups[i].average_AQI = 0;
        groups[i].climate = (enum climate_type)rand() % 3;
        groups[i].vegetation = (enum vegetation_type)rand() % 4;
        groups[i].years_since_event = 0;
    }

    // Loop through the data array and update the corresponding group's values
    for (int i = 0; i < num_records; i++) {
        int j = 0;
        while (j < num_records && strcmp(data[i].city_name, groups[j].city_name) != 0) {
            j++;
        }
        if (j == num_records) {
            printf("Failed to find group for city %s\n", data[i].city_name);
            return;
        }
        groups[j].average_latitude += data[i].latitude;
        groups[j].average_longitude += data[i].longitude;
        groups[j].average_elevation += data[i].elevation;
        groups[j].average_population += data[i].population;
        groups[j].average_annual_rainfall += data[i].annual_rainfall;
        groups[j].average_AQI += data[i].AQI;
