            j++;
        }
        if (j == num_records) {
            printf("Failed to find group for city %s\n", data[i].city_name);
            return;
        }
        float temp_dev = pow(data[i].average_temperature - groups[j].average_temperature, 2);
        float rain_dev = pow(data[i].annual_rainfall - groups[j].average_annual_rainfall, 2);
        groups[j].temp_stddev += temp_dev;
        groups[j].rain_stddev += rain_dev;
    }

    // Validate the integrity of the data by checking for any inconsistencies in the coordinates (e.g., overlapping city boundaries) and ensuring that all records adhere to the defined constraints
    for (int i = 0; i < num_records; i++) {
