        }
        if (data[i].latitude < -90 || data[i].latitude > 90) {
            printf("Invalid latitude value: %f\n", data[i].latitude);
            return;
        }
        if (data[i].longitude < -180 || data[i].longitude > 180) {
            printf("Invalid longitude value: %f\n", data[i].longitude);
            return;
        }
        if (data[i].elevation < 0 || data[i].elevation > 8848) {
            printf("Invalid elevation value: %f\n", data[i].elevation);
            return;
        }
        if (strlen(data[i].city_name) > 100) {
            printf("City name exceeds maximum length of 100 characters: %s\n", data[i].city_name);
