#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <math.h>

// Define the structure for the transaction record
typedef struct {
    int value;
    int count;
    char *account_id;
    float amount;
    enum transaction_status status;
    bool is_fraudulent;
    time_t timestamp;
    double fee;
} transaction_record;

// Define the function to initialize the data
void init_data(int num_records, int min_value, int max_value, float min_amount, float max_amount, float min_fee, float max_fee, enum transaction_status *statuses, bool *is_fraudulent, time_t *timestamps) {
    // Validate the input parameters
    if (num_records < 10000 || num_records > 1000000) {
        printf("Invalid number of records: %d\n", num_records);
        return;
    }
    if (min_value < 0 || max_value < min_value) {
        printf("Invalid value range: [%d, %d]\n", min_value, max_value);
        return;
    }
    if (min_amount < 0.01f || max_amount < min_amount) {
        printf("Invalid amount range: [%.2f, %.2f]\n", min_amount, max_amount);
        return;
    }
    if (min_fee < 0.0f || max_fee < min_fee) {
        printf("Invalid fee range: [%.2f, %.2f]\n", min_fee, max_fee);
        return;
    }
    if (!statuses || !is_fraudulent || !timestamps) {
        printf("Invalid input parameters\n");
        return;
    }

    // Allocate memory for the arrays
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    int *counts = malloc(num_records * sizeof(int));
    char **account_ids = malloc(num_records * sizeof(char*));
    float *amounts = malloc(num_records * sizeof(float));
    enum transaction_status *statuses = malloc(num_records * sizeof(enum transaction_status));
    bool *is_fraudulent = malloc(num_records * sizeof(bool));
    time_t *timestamps = malloc(num_records * sizeof(time_t));
    double *fees = malloc(num_records * sizeof(double));

    // Initialize the arrays with random values within given ranges
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (max_value - min_value + 1) + min_value;
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        counts[i] = rand() % (max_value - min_value + 1) + min_value;
        account_ids[i] = malloc(strlen("account_id") + 1);
        strcpy(account_ids[i], "account_id");
        amounts[i] = roundf((rand() % (max_amount - min_amount + 1) + min_amount) * 100.0f) / 100.0f;
        statuses[i] = rand() % (sizeof(transaction_status) / sizeof(int));
        is_fraudulent[i] = rand() % 2 == 0 ? true : false;
        timestamps[i] = time(NULL);
        fees[i] = roundf((rand() % (max_fee - min_fee + 1) + min_fee) * 100.0f) / 100.0f;
    }

    // Allocate memory for the transaction records array
    transaction_record *records = malloc(num_records * sizeof(transaction_record));

    // Initialize the transaction records with random values within given ranges
    for (int i = 0; i < num_records; i++) {
        records[i].value = offsets[i];
        records[i].count = counts[i];
        records[i].account_id = account_ids[i];
        records[i].amount = amounts[i];
        records[i].status = statuses[i];
        records[i].is_fraudulent = is_fraudulent[i];
        records[i].timestamp = timestamps[i];
        records[i].fee = fees[i];
    }

    // Group the entries by account ID and calculate the total transaction amount, average transaction fee, and average timestamp for each group
    for (int i = 0; i < num_records; i++) {
        int account_id = records[i].account_id;
        float total_amount = 0.0f;
        double avg_fee = 0.0f;
        time_t avg_timestamp = 0;
        for (int j = i; j < num_records && records[j].account_id == account_id; j++) {
            total_amount += records[j].amount;
            avg_fee += records[j].fee;
            avg_timestamp += records[j].timestamp;
        }
        printf("Account ID: %s\n", account_ids[i]);
        printf("Total transaction amount: %.2f\n", total_amount);
        printf("Average transaction fee: %.2f\n", avg_fee / (j - i + 1));
        printf("Average timestamp: %ld\n", avg_timestamp / (j - i + 1));
    }

    // Compute the median transaction amount and identify the most frequent transaction status for each account
    for (int i = 0; i < num_records; i++) {
        int account_id = records[i].account_id;
        float median_amount = 0.0f;
        enum transaction_status most_frequent_status = statuses[i];
        for (int j = i; j < num_records && records[j].account_id == account_id; j++) {
            if (records[j].amount > median_amount) {
                median_amount = records[j].amount;
            }
            most_frequent_status = statuses[j] > most_frequent_status ? statuses[j] : most_frequent_status;
        }
        printf("Account ID: %s\n", account_ids[i]);
        printf("Median transaction amount: %.2f\n", median_amount);
        printf("Most frequent transaction status: %d\n", most_frequent_status);
    }

    // Validate the integrity of the data by checking for any inconsistencies in the timestamps (e.g., overlapping transactions) and ensure that the total transaction amount for each group matches the sum of individual transactions
    for (int i = 0; i < num_records; i++) {
        int account_id = records[i].account_id;
        float total_amount = 0.0f;
        time_t min_timestamp = timestamps[i];
        time_t max_timestamp = timestamps[i];
        for (int j = i; j < num_records && records[j].account_id == account_id; j++) {
            total_amount += records[j].amount;
            min_timestamp = timestamps[j] < min_timestamp ? timestamps[j] : min_timestamp;
            max_timestamp = timestamps[j] > max_timestamp ? timestamps[j] : max_timestamp;
        }
        if (total_amount != records[i].amount) {
            printf("Inconsistent transaction amount for account ID %s: expected %.2f, actual %.2f\n", account_ids[i], total_amount, records[i].amount);
        }
        if (min_timestamp > max_timestamp) {
            printf("Overlapping transactions for account ID %s: [%ld, %ld]\n", account_ids[i], min_timestamp, max_timestamp);
        }
    }

    // Free the memory allocated for the arrays and the transaction records array
    free(offsets);
    free(keys);
    free(counts);
    free(account_ids);
    free(amounts);
    free(statuses);
    free(is_fraudulent);
    free(timestamps);
    free(fees);
    free(records);
}
