#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <math.h>

// Define the structure to hold transaction records
typedef struct {
    long offset;
    int key;
    int daily_transactions;
    char *account_id;
    float transaction_amount;
    enum transaction_status status;
    bool fraudulent;
    time_t timestamp;
    double transaction_fee;
} transaction_record;

// Define the function to generate random values for each field
void generate_random_values(transaction_record *records, int num_records) {
    // Initialize a random seed based on the current time
    srand((unsigned int)time(NULL));

    // Loop through each record and generate random values
    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand() % 1000000000;
        records[i].key = rand() % 1000000000;
        records[i].daily_transactions = rand() % 1000000000;
        records[i].account_id = malloc(sizeof(char) * 256);
        sprintf(records[i].account_id, "Account ID %d", i);
        records[i].transaction_amount = (float)(rand() % 1000000000) / 100;
        records[i].status = rand() % 3;
        records[i].fraudulent = rand() % 2;
        records[i].timestamp = time(NULL) + (rand() % 365 * 24 * 60 * 60);
        records[i].transaction_fee = (float)(rand() % 1000000000) / 100;
    }
}

// Define the function to validate input parameters
void validate_input(int num_records, float min_amount, float max_amount, double min_fee, double max_fee) {
    // Check that the number of records is between 10,000 and 1,000,000
    if (num_records < 10000 || num_records > 10000000) {
        printf("Invalid number of records: %d\n", num_records);
        exit(1);
    }

    // Check that the transaction amounts are between $0.01 and $1,000,000
    if (min_amount < 0.01 || max_amount > 1000000) {
        printf("Invalid minimum or maximum transaction amount: %f\n", min_amount);
        exit(1);
    }

    // Check that the transaction fees are between $0 and $100
    if (min_fee < 0 || max_fee > 100) {
        printf("Invalid minimum or maximum transaction fee: %f\n", min_fee);
        exit(1);
    }
}

// Define the function to allocate memory for and initialize an array of 'transaction_record' structures
void allocate_and_initialize_records(int num_records, transaction_record **records) {
    // Allocate memory for the array of records
    *records = malloc(sizeof(transaction_record) * num_records);

    // Initialize each record with random values
    generate_random_values(*records, num_records);
}

// Define the function to group entries by account ID and calculate statistics
void group_and_calculate_statistics(transaction_record *records, int num_records) {
    // Create a hash table to store the grouped records
    hash_table *grouped_records = create_hash_table();

    // Loop through each record and add it to the hash table
    for (int i = 0; i < num_records; i++) {
        char *account_id = records[i].account_id;
        transaction_record *record = &records[i];
        if (!hash_table_contains(grouped_records, account_id)) {
            hash_table_add(grouped_records, account_id, record);
        } else {
            transaction_record *existing_record = hash_table_get(grouped_records, account_id);
            existing_record->daily_transactions += record->daily_transactions;
            existing_record->transaction_amount += record->transaction_amount;
            existing_record->status |= record->status;
            existing_record->fraudulent |= record->fraudulent;
            existing_record->timestamp = fmax(existing_record->timestamp, record->timestamp);
            existing_record->transaction_fee += record->transaction_fee;
        }
    }

    // Loop through each group and calculate the statistics
    hash_table_iterator *it = hash_table_iterator_create(grouped_records);
    while (hash_table_iterator_has_next(it)) {
        char *account_id = hash_table_iterator_next(it);
        transaction_record *record = hash_table_get(grouped_records, account_id);
        printf("Account ID: %s\n", account_id);
        printf("Total daily transactions: %d\n", record->daily_transactions);
        printf("Average transaction amount: %.2f\n", record->transaction_amount / record->daily_transactions);
        printf("Average transaction fee: %.2f\n", record->transaction_fee / record->daily_transactions);
        printf("Median transaction amount: %.2f\n", median(record->transaction_amount, record->daily_transactions));
        printf("Most frequent transaction status: %d\n", most_frequent_status(record->status, record->daily_transactions));
    }
}

// Define the function to compute the median of an array of 'float' values
float median(float *values, int num_values) {
    // Sort the array of values in ascending order
    qsort(values, num_values, sizeof(float), compare_floats);

    // If there are an odd number of values, return the middle value
    if (num_values % 2 == 1) {
        return values[num_values / 2];
    } else {
        // If there are an even number of values, return the average of the two middle values
        return (values[num_values / 2 - 1] + values[num_values / 2]) / 2;
    }
}

// Define the function to compute the most frequent transaction status for each account
int most_frequent_status(enum transaction_status *statuses, int num_statuses) {
    // Create a hash table to store the counts of each status
    hash_table *counts = create_hash_table();

    // Loop through each status and increment its count in the hash table
    for (int i = 0; i < num_statuses; i++) {
        enum transaction_status status = statuses[i];
        if (!hash_table_contains(counts, &status)) {
            hash_table_add(counts, &status, 1);
        } else {
            int *count = hash_table_get(counts, &status);
            (*count)++;
        }
    }

    // Find the most frequent status by comparing its count with others
    enum transaction_status most_frequent_status = 0;
    int most_frequent_count = -1;
    hash_table_iterator *it = hash_table_iterator_create(counts);
    while (hash_table_iterator_has_next(it)) {
        enum transaction_status status = *(enum transaction_status *)hash_table_iterator_next(it);
        int count = *(int *)hash_table_get(counts, &status);
        if (count > most_frequent_count) {
            most_frequent_status = status;
            most_frequent_count = count;
        }
    }

    // Return the most frequent status
    return most_frequent_status;
}
