// Define function to validate input parameters
bool validateInputParameters(int num_records, int pressure_range, int wind_speed_range, int wind_direction_range, int weather_station_identifier_length, int years_since_installation_range, int weather_condition_severity_range, int humidity_level_range, int geographic_region_range, int cumulative_precipitation_amount_range, int maximum_wind_gust_range, int automated_monitoring_flag_range, int solar_radiation_range) {
    // Check if number of records is within valid range
    if (num_records < 10 || num_records > 1000000) {
        return false;
    }

    // Check if pressure range is valid
    if (pressure_range < PRESSURE_MIN || pressure_range > PRESSURE_MAX) {
        return false;
    }

    // Check if wind speed range is valid
    if (wind_speed_range < WIND_SPEED_MIN || wind_speed_range > WIND_SPEED_MAX) {
        return false;
    }

    // Check if wind direction range is valid
    if (wind_direction_range < WIND_DIRECTION_MIN || wind_direction_range > WIND_DIRECTION_MAX) {
        return false;
    }

    // Check if weather station identifier length is within valid range
    if (weather_station_identifier_length < 1 || weather_station_identifier_length > 100) {
        return false;
    }

    // Check if years since installation range is non-negative
    if (years_since_installation_range < 0) {
        return false;
    }

    // Check if weather condition severity range is within valid range
    if (weather_condition_severity_range < WEATHER_CONDITION_SEVERITY_MIN || weather_condition_severity_range > WEATHER_CONDITION_SEVERITY_MAX) {
        return false;
    }

    // Check if humidity level range is within valid range
    if (humidity_level_range < HUMIDITY_MIN || humidity_level_range > HUMIDITY_MAX) {
        return false;
    }

    // Check if geographic region range is within valid range
    if (geographic_region_range < GEOGRAPHIC_REGION_MIN || geographic_region_range > GEOGRAPHIC_REGION_MAX) {
        return false;
    }

    // Check if cumulative precipitation amount range is non-negative
    if (cumulative_precipitation_amount_range < 0) {
        return false;
    }

    // Check if maximum wind gust range is realistic
    if (maximum_wind_gust_range < WIND_SPEED_MIN || maximum_wind_gust_range > WIND_SPEED_MAX) {
        return false;
    }

    // Check if automated monitoring flag range is binary
    if (automated_monitoring_flag_range != AUTOMATED_MONITORING_FLAG_TRUE && automated_monitoring_flag_range != AUTOMATED_MONITORING_FLAG_FALSE) {
        return false;
    }

    // Check if solar radiation range is within valid range
    if (solar_radiation_range < SOLAR_RADIATION_MIN || solar_radiation_range > SOLAR_RADIATION_MAX) {
        return false;
    }

    return true;
}

// Define function to initialize weather data
void initWeatherData(struct WeatherData *weather_data, int num_records) {
    // Initialize random seed
    srand(time(NULL));

    // Loop through each record and set values randomly within given ranges
    for (int i = 0; i < num_records; i++) {
        weather_data[i].id = generateRandomValue(1, 1000);
        weather_data[i].pressure = generateRandomValue(PRESSURE_MIN, PRESSURE_MAX);
        weather_data[i].wind_speed = generateRandomValue(WIND_SPEED_MIN, WIND_SPEED_MAX);
        weather_data[i].wind_direction = generateRandomValue(WIND_DIRECTION_MIN, WIND_DIRECTION_MAX);
        weather_data[i].weather_station_identifier[0] = '\0';
        for (int j = 1; j < weather_data[i].weather_station_identifier_length; j++) {
            weather_data[i].weather_station_identifier[j] = generateRandomValue(65, 90);
        }
        weather_data[i].years_since_installation = generateRandomValue(0, 100);
        weather_data[i].weather_condition = generateRandomValue(WEATHER_CONDITION_SEVERITY_MIN, WEATHER_CONDITION_SEVERITY_MAX);
        weather_data[i].humidity_level = generateRandomValue(HUMIDITY_MIN, HUMIDITY_MAX);
        weather_data[i].geographic_region = generateRandomValue(GEOGRAPHIC_REGION_MIN, GEOGRAPHIC_REGION_MAX);
        weather_data[i].cumulative_precipitation_amount = generateRandomValue(0, 10000);
        weather_data[i].maximum_wind_gust = generateRandomValue(WIND_SPEED_MIN, WIND_SPEED_MAX);
        weather_data[i].automated_monitoring_flag = generateRandomValue(AUTOMATED_MONITORING_FLAG_TRUE, AUTOMATED_MONITORING_FLAG_FALSE);
        weather_data[i].solar_radiation = generateRandomValue(SOLAR_RADIATION_MIN, SOLAR_RADIATION_MAX);
    }
}

// Define function to group weather data by geographic region and calculate averages
void groupWeatherDataByGeographicRegion(struct WeatherData *weather_data, int num_records) {
    // Initialize hash table for storing grouped data
    struct HashTable *hash_table = createHashTable();

    // Loop through each record and add to hash table
    for (int i = 0; i < num_records; i++) {
        int geographic_region = weather_data[i].geographic_region;
        struct WeatherData *weather_data_ptr = &weather_data[i];
        addToHashTable(hash_table, geographic_region, weather_data_ptr);
    }

    // Loop through each group and calculate averages
    for (int i = 0; i < hash_table->num_buckets; i++) {
        struct WeatherData *weather_data_ptr = hash_table->bucket[i];
        while (weather_data_ptr != NULL) {
            int num_records = hash_table->bucket[i]->num_records;
            float pressure_sum = 0;
            float wind_speed_sum = 0;
            float wind_direction_sum = 0;
            float humidity_level_sum = 0;
            float cumulative_precipitation_amount_sum = 0;
            float maximum_wind_gust_sum = 0;
            int years_since_installation_sum = 0;
            float solar_radiation_sum = 0;
            for (int j = 0; j < num_records; j++) {
                pressure_sum += weather_data_ptr[j].pressure;
                wind_speed_sum += weather_data_ptr[j].wind_speed;
                wind_direction_sum += weather_data_ptr[j].wind_direction;
                humidity_level_sum += weather_data_ptr[j].humidity_level;
                cumulative_precipitation_amount_sum += weather_data_ptr[j].cumulative_precipitation_amount;
                maximum_wind_gust_sum += weather_data_ptr[j].maximum_wind_gust;
                years_since_installation_sum += weather_data_ptr[j].years_since_installation;
                solar_radiation_sum += weather_data_ptr[j].solar_radiation;
            }
            float pressure_average = pressure_sum / num_records;
            float wind_speed_average = wind_speed_sum / num_records;
            float wind_direction_average = wind_direction_sum / num_records;
            float humidity_level_average = humidity_level_sum / num_records;
            float cumulative_precipitation_amount_average = cumulative_precipitation_amount_sum / num_records;
            float maximum_wind_gust_average = maximum_wind_gust_sum / num_records;
            int years_since_installation_average = years_since_installation_sum / num_records;
            float solar_radiation_average = solar_radiation_sum / num_records;
            printf("Geographic region: %d\n", geographic_region);
            printf("Pressure average: %.2f hPa\n", pressure_average);
            printf("Wind speed average: %.2f km/h\n", wind_speed_average);
            printf("Wind direction average: %.2f degrees\n", wind_direction_average);
            printf("Humidity level average: %.2f %%\n", humidity_level_average);
            printf("Cumulative precipitation amount average: %.2f mm\n", cumulative_precipitation_amount_average);
            printf("Maximum wind gust average: %.2f km/h\n", maximum_wind_gust_average);
            printf("Years since installation average: %d\n", years_since_installation_average);
            printf("Solar radiation average: %.2f W/m^2\n", solar_radiation_average);
        }
    }
}
