float generate_random_value(float min, float max) {
    return (float)(rand() % 1000) / 1000 * (max - min) + min;
}

// Define a function to validate input parameters and initialize data
void init_data(int num_records, record* records) {
    // Validate input parameters
    if (num_records < 100 || num_records > 1000000) {
        printf("Invalid number of records: %d\n", num_records);
        return;
    }

    // Initialize data
    for (int i = 0; i < num_records; i++) {
        records[i].id = i + 1;
        records[i].temperature = generate_random_value(TEMP_MIN, TEMP_MAX);
        records[i].pressure = generate_random_value(PRESSURE_MIN, PRESSURE_MAX);
        records[i].humidity = generate_random_value(HUMIDITY_MIN, HUMIDITY_MAX);
        records[i].city = "City" + i;
        records[i].population = 100000 + (rand() % 50000);
        records[i].annual_precipitation = generate_random_value(PRECIPITATION_MIN, PRECIPITATION_MAX);
        records[i].weather_condition = rand() % WEATHER_CONDITIONS_COUNT;
        records[i].wind_speed = generate_random_value(WIND_SPEED_MIN, WIND_SPEED_MAX);
        records[i].season = rand() % SEASONS_COUNT;
        records[i].days_since_last_recorded_weather_event = (rand() % 365) - 180;
        records[i].aqi = generate_random_value(AQI_MIN, AQI_MAX);
        records[i].urbanization = rand() % 2;
    }
}

// Define a function to group records by city and calculate averages
void group_records(record* records, int num_records) {
    // Initialize variables for grouping and aggregation
    char* city_names[num_records];
    float temperatures[num_records];
    float pressures[num_records];
    float humidities[num_records];
    int annual_precipitations[num_records];
    float wind_speeds[num_records];
    int days_since_last_recorded_weather_events[num_records];
    float aqis[num_records];
    bool urbanizations[num_records];
    int num_cities = 0;

    // Loop through records and group by city
    for (int i = 0; i < num_records; i++) {
        bool found = false;
        for (int j = 0; j < num_cities; j++) {
            if (strcmp(records[i].city, city_names[j]) == 0) {
                found = true;
                break;
            }
        }
        if (!found) {
            strcpy(city_names[num_cities], records[i].city);
            temperatures[num_cities] = records[i].temperature;
            pressures[num_cities] = records[i].pressure;
            humidities[num_cities] = records[i].humidity;
            annual_precipitations[num_cities] = records[i].annual_precipitation;
            wind_speeds[num_cities] = records[i].wind_speed;
            days_since_last_recorded_weather_events[num_cities] = records[i].days_since_last_recorded_weather_event;
            aqis[num_cities] = records[i].aqi;
            urbanizations[num_cities] = records[i].urbanization;
            num_cities++;
        }
    }

    // Calculate averages for each group
    for (int i = 0; i < num_cities; i++) {
        temperatures[i] /= num_records;
        pressures[i] /= num_records;
        humidities[i] /= num_records;
        annual_precipitations[i] /= num_records;
        wind_speeds[i] /= num_records;
        days_since_last_recorded_weather_events[i] /= num_records;
        aqis[i] /= num_records;
        urbanizations[i] = (urbanizations[i] == 1) ? true : false;
    }
}

// Define a function to validate the integrity of the data
void validate_data(record* records, int num_records) {
    // Loop through records and check for inconsistencies in atmospheric readings
    for (int i = 0; i < num_records; i++) {
        if (records[i].pressure - records[i].temperature > 10.0f) {
            printf("Unrealistic pressure drop detected: %d\n", records[i].id);
        } else if (records[i].temperature + records[i].humidity > 50.0f) {
            printf("Unrealistic temperature spike detected: %d\n", records[i].id);
        }
    }
}
