};

// Define the function to dynamically allocate memory for and initialize multiple arrays
void init_data(int num_records, struct record **records) {
  // Validate the input parameters
  if (num_records < 100 || num_records > 1000000) {
    printf("Invalid number of records: %d\n", num_records);
    return;
  }

  // Allocate memory for the arrays
  *records = (struct record *)malloc(num_records * sizeof(struct record));
  if (*records == NULL) {
    printf("Failed to allocate memory for records\n");
    return;
  }

  // Initialize the values of each record's fields to random values within given ranges
  srand(time(NULL));
  for (int i = 0; i < num_records; i++) {
    (*records)[i].user_id = rand() % 1000000 + 1;
    (*records)[i].transaction_amount = (double)rand() / RAND_MAX * 10000 - 5000;
    strcpy((*records)[i].account_number, "ACCOUNT-");
    strcat((*records)[i].account_number, rand() % 10000 + 1);
    (*records)[i].transaction_type = (enum transaction_type)rand() % 2;
    (*records)[i].average_daily_balance = (float)rand() / RAND_MAX * 10000 - 5000;
    (*records)[i].account_status = (enum account_status)rand() % 2;
    (*records)[i].account_age = rand() % 10000 + 1;
    (*records)[i].credit_score = (float)rand() / RAND_MAX * 500 - 250;
    strcpy((*records)[i].financial_institution, "FINANCIAL-");
    strcat((*records)[i].financial_institution, rand() % 100 + 1);
    (*records)[i].interest_rate = (float)rand() / RAND_MAX * 20 - 10;
    (*records)[i].active_status = (bool)(rand() % 2);
    (*records)[i].total_fees = (float)rand() / RAND_MAX * 10000 - 5000;
  }
}

// Define the function to group the entries by financial institution and calculate the average transaction amount, average balance, average age of accounts, average credit score, average interest rate, and average total fees for each institution
void group_data(struct record *records, int num_records) {
  // Initialize a map to store the data grouped by financial institution
  std::map<std::string, struct record> grouped_data;

  // Iterate over the records and add them to the map
  for (int i = 0; i < num_records; i++) {
    grouped_data[records[i].financial_institution].transaction_amount += records[i].transaction_amount;
    grouped_data[records[i].financial_institution].average_daily_balance += records[i].average_daily_balance;
    grouped_data[records[i].financial_institution].account_age += records[i].account_age;
    grouped_data[records[i].financial_institution].credit_score += records[i].credit_score;
    grouped_data[records[i].financial_institution].interest_rate += records[i].interest_rate;
    grouped_data[records[i].financial_institution].total_fees += records[i].total_fees;
  }

  // Calculate the average transaction amount, average balance, average age of accounts, average credit score, average interest rate, and average total fees for each institution
  for (auto it = grouped_data.begin(); it != grouped_data.end(); ++it) {
    it->second.transaction_amount /= num_records;
    it->second.average_daily_balance /= num_records;
    it->second.account_age /= num_records;
    it->second.credit_score /= num_records;
    it->second.interest_rate /= num_records;
    it->second.total_fees /= num_records;
  }
