#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>

// Define structs for sensor data and weather updates
struct sensor_data {
    long offset;
    int key;
    int temperature;
    char location[256];
    double humidity;
    float wind_speed;
    enum weather_type cloud_cover;
    bool precipitation;
    time_t timestamp;
    float atmospheric_pressure;
};

struct weather_update {
    char location[256];
    int temperature;
    double humidity;
    float wind_speed;
    enum weather_type cloud_cover;
    bool precipitation;
    time_t timestamp;
    float atmospheric_pressure;
};

// Define function to validate input parameters
bool validate_input(int num_records, int temperature_range, int humidity_range, int wind_speed_range, int atmospheric_pressure_range, bool precipitation_flag) {
    // Check that number of records is between 500 and 50,000
    if (num_records < 500 || num_records > 50000) {
        return false;
    }

    // Check that temperature ranges are valid
    if (temperature_range < -60 || temperature_range > 60) {
        return false;
    }

    // Check that humidity levels are within valid range
    if (humidity_range < 0 || humidity_range > 100) {
        return false;
    }

    // Check that timestamps are non-negative and less than 10 years from current time
    time_t current_time = time(NULL);
    if (timestamp < 0 || timestamp > current_time + 365 * 24 * 60 * 60) {
        return false;
    }

    // Check that wind speeds are within valid range
    if (wind_speed_range < 0 || wind_speed_range > 30) {
        return false;
    }

    // Check that atmospheric pressures are within realistic limits
    if (atmospheric_pressure_range < 900 || atmospheric_pressure_range > 1100) {
        return false;
    }

    // Check that precipitation flags are binary (true or false)
    if (precipitation_flag != true && precipitation_flag != false) {
        return false;
    }

    return true;
}

// Define function to initialize data structures
void init_data(int num_records, int temperature_range, int humidity_range, int wind_speed_range, int atmospheric_pressure_range, bool precipitation_flag) {
    // Allocate memory for arrays of sensor data and weather updates
    struct sensor_data *sensor_data = malloc(num_records * sizeof(struct sensor_data));
    struct weather_update *weather_updates = malloc(num_records * sizeof(struct weather_update));

    // Initialize arrays with random values within given ranges
    for (int i = 0; i < num_records; i++) {
        sensor_data[i].offset = rand() % 1000000;
        sensor_data[i].key = rand() % 1000000;
        sensor_data[i].temperature = (rand() % temperature_range) - temperature_range / 2;
        sensor_data[i].humidity = (rand() % humidity_range) / 100.0;
        sensor_data[i].wind_speed = (rand() % wind_speed_range) / 10.0;
        sensor_data[i].cloud_cover = rand() % 5;
        sensor_data[i].precipitation = precipitation_flag ? true : false;
        sensor_data[i].timestamp = time(NULL);
        sensor_data[i].atmospheric_pressure = (rand() % atmospheric_pressure_range) / 10.0;

        weather_updates[i].temperature = round(sensor_data[i].temperature * 100) / 100;
        weather_updates[i].humidity = sensor_data[i].humidity;
        weather_updates[i].wind_speed = sensor_data[i].wind_speed;
        weather_updates[i].cloud_cover = sensor_data[i].cloud_cover;
        weather_updates[i].precipitation = sensor_data[i].precipitation;
        weather_updates[i].timestamp = sensor_data[i].timestamp;
        weather_updates[i].atmospheric_pressure = sensor_data[i].atmospheric_pressure;
    }
}

// Define function to group records by location name and calculate averages
void group_records(struct sensor_data *sensor_data, int num_records) {
    // Create hash table for storing grouped records
    struct hash_table *hash_table = create_hash_table();

    // Loop through each record and add to hash table
    for (int i = 0; i < num_records; i++) {
        char location[256];
        strcpy(location, sensor_data[i].location);
        struct hash_entry *hash_entry = find_or_create_hash_entry(hash_table, location);
        if (hash_entry == NULL) {
            continue;
        }
        hash_entry->num_records++;
        hash_entry->temperature += sensor_data[i].temperature;
        hash_entry->humidity += sensor_data[i].humidity;
        hash_entry->wind_speed += sensor_data[i].wind_speed;
        hash_entry->atmospheric_pressure += sensor_data[i].atmospheric_pressure;
    }

    // Loop through each hash entry and calculate averages
    for (int i = 0; i < hash_table->num_entries; i++) {
        struct hash_entry *hash_entry = &hash_table->entries[i];
        if (hash_entry->num_records > 0) {
            hash_entry->temperature /= hash_entry->num_records;
            hash_entry->humidity /= hash_entry->num_records;
            hash_entry->wind_speed /= hash_entry->num_records;
            hash_entry->atmospheric_pressure /= hash_entry->num_records;
        }
    }
}

// Define function to compute standard deviation of temperatures
void compute_standard_deviation(struct sensor_data *sensor_data, int num_records) {
    // Create array for storing squared differences from mean temperature
    double *squared_differences = malloc(num_records * sizeof(double));

    // Loop through each record and calculate squared difference from mean temperature
    for (int i = 0; i < num_records; i++) {
        double mean_temperature = sensor_data[i].temperature;
        double squared_difference = pow(sensor_data[i].temperature - mean_temperature, 2);
        squared_differences[i] = squared_difference;
    }

    // Calculate sum of squared differences and standard deviation
    double sum_squared_differences = 0.0;
    for (int i = 0; i < num_records; i++) {
        sum_squared_differences += squared_differences[i];
    }
    double standard_deviation = sqrt(sum_squared_differences / (num_records - 1));

    // Free memory for squared differences array
    free(squared_differences);
}

// Define function to integrate with external weather data API
void fetch_weather_updates(struct sensor_data *sensor_data, int num_records) {
    // Loop through each record and fetch real-time weather updates for location
    for (int i = 0; i < num_records; i++) {
        char location[256];
        strcpy(location, sensor_data[i].location);
        struct weather_update *weather_update = fetch_weather_update(location);
        if (weather_update == NULL) {
            continue;
        }
        sensor_data[i].temperature = weather_update->temperature;
        sensor_data[i].humidity = weather_update->humidity;
        sensor_data[i].wind_speed = weather_update->wind_speed;
        sensor_data[i].cloud_cover = weather_update->cloud_cover;
        sensor_data[i].precipitation = weather_update->precipitation;
        sensor_data[i].timestamp = weather_update->timestamp;
        sensor_data[i].atmospheric_pressure = weather_update->atmospheric_pressure;
    }
}
