// Define the function to initialize the data
void init_data(struct record *records, int num_records) {
    // Validate the input parameters
    if (num_records < 500 || num_records > 50000) {
        printf("Invalid number of records: %d\n", num_records);
        return;
    }

    // Allocate memory for the arrays and structures
    struct sensor_reading *sensor_readings = malloc(num_records * sizeof(struct sensor_reading));
    struct sensor_location *sensor_locations = malloc(num_records * sizeof(struct sensor_location));
    struct record *grouped_records = malloc(num_records * sizeof(struct record));

    // Initialize the arrays and structures
    for (int i = 0; i < num_records; i++) {
        sensor_readings[i].offset = rand() % 1000000;
        sensor_readings[i].key = rand() % 1000000;
        sensor_readings[i].temperature = round(rand() % 120 - 60);
        strcpy(sensor_readings[i].location, "Location ");
        strcat(sensor_readings[i].location, rand() % 1000000);
        sensor_readings[i].humidity = (rand() % 100) / 100.0;
        sensor_readings[i].wind_speed = round(rand() % 30);
        sensor_readings[i].cloud_cover = rand() % 5;
        sensor_readings[i].precipitation = (rand() % 2) ? true : false;
        sensor_readings[i].timestamp = time(NULL) + rand() % 31536000;
        sensor_readings[i].atmospheric_pressure = round(rand() % 1100 - 900);

        sensor_locations[i].geographic_id = i;
        sensor_locations[i].altitude = rand() % 10000;

        grouped_records[i].value = i;
        grouped_records[i].temperature = round(sensor_readings[i].temperature * 100) / 100.0;
        strcpy(grouped_records[i].location, sensor_readings[i].location);
        grouped_records[i].humidity = sensor_readings[i].humidity;
        grouped_records[i].wind_speed = sensor_readings[i].wind_speed;
        grouped_records[i].cloud_cover = sensor_readings[i].cloud_cover;
        grouped_records[i].precipitation = sensor_readings[i].precipitation;
        grouped_records[i].timestamp = sensor_readings[i].timestamp;
        grouped_records[i].atmospheric_pressure = sensor_readings[i].atmospheric_pressure;
    }

    // Group the records by location name and calculate the average temperature, humidity, wind speed, atmospheric pressure, timestamp, cloud cover percentage, and sensor accuracy for each group
    struct record *grouped_records = malloc(num_records * sizeof(struct record));
    for (int i = 0; i < num_records; i++) {
        grouped_records[i].value = i;
        grouped_records[i].temperature = round(sensor_readings[i].temperature * 100) / 100.0;
        strcpy(grouped_records[i].location, sensor_readings[i].location);
        grouped_records[i].humidity = sensor_readings[i].humidity;
        grouped_records[i].wind_speed = sensor_readings[i].wind_speed;
        grouped_records[i].cloud_cover = sensor_readings[i].cloud_cover;
        grouped_records[i].precipitation = sensor_readings[i].precipitation;
        grouped_records[i].timestamp = sensor_readings[i].timestamp;
        grouped_records[i].atmospheric_pressure = sensor_readings[i].atmospheric_pressure;
    }

    // Compute the standard deviation of temperatures
    double sum = 0.0;
    for (int i = 0; i < num_records; i++) {
        sum += grouped_records[i].temperature;
    }
    double mean = sum / num_records;
    double variance = 0.0;
    for (int i = 0; i < num_records; i++) {
        variance += pow(grouped_records[i].temperature - mean, 2);
    }
    variance /= num_records - 1;
    double stddev = sqrt(variance);

    // Print the results
    printf("Average temperature: %.2f\n", mean);
    printf("Standard deviation of temperatures: %.2f\n", stddev);
}
