#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <errno.h>

#define MAX_BUFFER_SIZE 1024
#define MAX_CONNECTIONS 5
#define MAX_RETRIES 3
#define RATE_LIMIT_INTERVAL 60 // seconds
#define RATE_LIMIT_THRESHOLD 10 // requests per minute

// Structure to store weather data
typedef struct {
    int id;
    char location[256];
    float temperature;
    float humidity;
    float windSpeed;
    float uvIndex;
    float visibility;
    float dewPoint;
} WeatherData;

// Structure to store weather data in a linked list
typedef struct {
    WeatherData *data;
    struct Node *next;
} Node;

// Function to fetch weather data from an external API
int fetchWeatherData(char *location, WeatherData *data) {
    // Initialize variables
    int sock = 0, valread;
    struct sockaddr_in serv_addr;
    char buffer[MAX_BUFFER_SIZE];
    memset(&serv_addr, '0', sizeof(serv_addr));

    // Create socket
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket creation failed");
        return -1;
    }

    // Set address and port number of the server
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, "192.168.1.1", &serv_addr.sin_addr) <= 0) {
        printf("\nInvalid address/ Address not supported \n");
        return -1;
    }

    // Connect to the server
    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Connection failed");
        return -1;
    }

    // Send request to the server
    char *request = "GET /weather?location=" + location + " HTTP/1.1\r\nHost: weather-api.com\r\n\r\n";
    send(sock, request, strlen(request), 0);

    // Receive response from the server
    valread = read(sock, buffer, MAX_BUFFER_SIZE);
    if (valread < 0) {
        perror("Failed to receive data");
        return -1;
    }

    // Close the socket
    close(sock);

    // Parse response and extract weather data
    char *token = strtok(buffer, " ");
    while (token != NULL) {
        if (strcmp(token, "id") == 0) {
            token = strtok(NULL, ":");
            data->id = atoi(token);
        } else if (strcmp(token, "location") == 0) {
            token = strtok(NULL, ":");
            strcpy(data->location, token);
        } else if (strcmp(token, "temperature") == 0) {
            token = strtok(NULL, ":");
            data->temperature = atof(token);
        } else if (strcmp(token, "humidity") == 0) {
            token = strtok(NULL, ":");
            data->humidity = atof(token);
        } else if (strcmp(token, "windSpeed") == 0) {
            token = strtok(NULL, ":");
            data->windSpeed = atof(token);
        } else if (strcmp(token, "uvIndex") == 0) {
            token = strtok(NULL, ":");
            data->uvIndex = atof(token);
        } else if (strcmp(token, "visibility") == 0) {
            token = strtok(NULL, ":");
            data->visibility = atof(token);
        } else if (strcmp(token, "dewPoint") == 0) {
            token = strtok(NULL, ":");
            data->dewPoint = atof(token);
        }
        token = strtok(NULL, " ");
    }

    return 0;
}

// Function to handle network failures gracefully and cache responses
int handleNetworkFailures(char *location) {
    // Initialize variables
    int retries = MAX_RETRIES;
    WeatherData data;

    // Retry fetching weather data from the API for a maximum of 3 times
    while (retries-- > 0) {
        if (fetchWeatherData(location, &data) == 0) {
            return 0;
        } else {
            printf("Network failure. Retrying...\n");
            sleep(1); // Sleep for 1 second before retrying
        }
    }

    return -1;
}

// Function to handle rate limiting logic and cache responses
int handleRateLimiting(char *location) {
    // Initialize variables
    int retries = MAX_RETRIES;
    WeatherData data;

    // Retry fetching weather data from the API for a maximum of 3 times
    while (retries-- > 0) {
        if (fetchWeatherData(location, &data) == 0) {
            return 0;
        } else {
            printf("Rate limit exceeded. Retrying...\n");
            sleep(RATE_LIMIT_INTERVAL); // Sleep for RATE_LIMIT_INTERVAL seconds before retrying
        }
    }

    return -1;
}

