#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>

#define MAX_IDS 100000
#define MIN_AGE 18
#define MAX_AGE 65
#define MIN_SALARY 20000
#define MAX_SALARY 100000
#define DEPARTMENT_COUNT 5

typedef struct {
    int id;
    char* name;
    int age;
    float salary;
    bool active;
    time_t timestamp;
    char* department;
} entry;

void validateInput(int numEntries, int minAge, int maxAge, float minSalary, float maxSalary) {
    if (numEntries < 1000 || numEntries > 100000) {
        printf("Invalid number of entries: %d\n", numEntries);
        exit(EXIT_FAILURE);
    }
    if (minAge < 18 || minAge > 65) {
        printf("Invalid minimum age: %d\n", minAge);
        exit(EXIT_FAILURE);
    }
    if (maxAge < 18 || maxAge > 65) {
        printf("Invalid maximum age: %d\n", maxAge);
        exit(EXIT_FAILURE);
    }
    if (minSalary < 20000 || minSalary > 100000) {
        printf("Invalid minimum salary: %f\n", minSalary);
        exit(EXIT_FAILURE);
    }
    if (maxSalary < 20000 || maxSalary > 100000) {
        printf("Invalid maximum salary: %f\n", maxSalary);
        exit(EXIT_FAILURE);
    }
}

void* generateIDs(void* args) {
    int* numIDs = (int*)args;
    for (int i = 0; i < *numIDs; i++) {
        // Generate a unique ID using a secure, thread-safe random number generator
        int id = generateRandomNumber();
        // Validate the ID is within an acceptable range and resize the array if necessary
        if (id > MAX_IDS) {
            *numIDs += 10;
            numIDs = realloc(numIDs, (*numIDs) * sizeof(int));
            generateIDs(args);
        } else {
            // Set the ID in the array and increment the global counter
            ids[i] = id;
            __sync_fetch_and_add(&globalCounter, 1);
        }
    }
}

void* initializeEntries(void* args) {
    entry* entries = (entry*)args;
    for (int i = 0; i < numEntries; i++) {
        // Initialize each entry with a random number between 1 and 1000
        int id = generateRandomNumber();
        while (id > MAX_IDS) {
            id = generateRandomNumber();
        }
        entries[i].id = id;
        entries[i].name = generateRandomString(10);
        entries[i].age = generateRandomNumber(MIN_AGE, MAX_AGE);
        entries[i].salary = generateRandomNumber(MIN_SALARY, MAX_SALARY);
        entries[i].active = generateRandomBoolean();
        entries[i].timestamp = time(NULL);
        entries[i].department = generateRandomString(10);
    }
}

int main() {
    int numEntries = 1000;
    int minAge = 25;
    int maxAge = 60;
    float minSalary = 30000;
    float maxSalary = 80000;
    validateInput(numEntries, minAge, maxAge, minSalary, maxSalary);

    // Allocate memory for the arrays and initialize them with default values
    int* ids = (int*)malloc(numEntries * sizeof(int));
    entry* entries = (entry*)malloc(numEntries * sizeof(entry));
    memset(ids, 0, numEntries * sizeof(int));
    memset(entries, 0, numEntries * sizeof(entry));

    // Initialize the global counter and start the thread for generating IDs
    int globalCounter = 0;
    pthread_t generateIDsThread;
    pthread_create(&generateIDsThread, NULL, generateIDs, &numEntries);

    // Wait for the thread to finish and initialize the entries with random values
    pthread_join(generateIDsThread, NULL);
    initializeEntries(entries);

    // Free all allocated memory before returning
    free(ids);
    free(entries);
    return 0;
}
