// Define the function to initialize the data
void init_data(int num_devices, int min_device_id, int max_device_id, float min_sensor_reading, float max_sensor_reading, double min_voltage_level, double max_voltage_level, float min_current_value, float max_current_value, time_t min_last_updated, time_t max_last_updated, float min_energy_consumption, float max_energy_consumption, enum status_flag min_operational_state, enum status_flag max_operational_state) {
    // Validate the input parameters
    if (num_devices < 1000 || num_devices > 100000) {
        printf("Invalid number of devices: %d\n", num_devices);
        return;
    }
    if (min_device_id < 0 || max_device_id < 0) {
        printf("Invalid device ID range: [%d, %d]\n", min_device_id, max_device_id);
        return;
    }
    if (min_sensor_reading < -100.0 || max_sensor_reading > 100.0) {
        printf("Invalid sensor reading range: [%f, %f]\n", min_sensor_reading, max_sensor_reading);
        return;
    }
    if (min_voltage_level < 0.0 || max_voltage_level > 240.0) {
        printf("Invalid voltage level range: [%f, %f]\n", min_voltage_level, max_voltage_level);
        return;
    }
    if (min_current_value < 0.0 || max_current_value > 100.0) {
        printf("Invalid current value range: [%f, %f]\n", min_current_value, max_current_value);
        return;
    }
    if (min_last_updated < 0 || max_last_updated < 0) {
        printf("Invalid last updated timestamp range: [%ld, %ld]\n", min_last_updated, max_last_updated);
        return;
    }
    if (min_energy_consumption < 0.0 || max_energy_consumption > 1000.0) {
        printf("Invalid energy consumption range: [%f, %f]\n", min_energy_consumption, max_energy_consumption);
        return;
    }
    if (min_operational_state < 0 || max_operational_state > 10) {
        printf("Invalid operational state range: [%d, %d]\n", min_operational_state, max_operational_state);
        return;
    }

    // Allocate memory for the arrays and structures
    device_info *devices = (device_info *)malloc(num_devices * sizeof(device_info));
    manufacturer_info *manufacturers = (manufacturer_info *)malloc(sizeof(manufacturer_info) * num_devices);

    // Initialize the arrays and structures with random values within given ranges
    for (int i = 0; i < num_devices; i++) {
        devices[i].device_id = rand() % (max_device_id - min_device_id + 1) + min_device_id;
        devices[i].sensor_reading = roundf(rand() % (max_sensor_reading - min_sensor_reading + 1) + min_sensor_reading);
        devices[i].voltage_level = rand() % (max_voltage_level - min_voltage_level + 1) + min_voltage_level;
        devices[i].current_value = roundf(rand() % (max_current_value - min_current_value + 1) + min_current_value);
        devices[i].last_updated = rand() % (max_last_updated - min_last_updated + 1) + min_last_updated;
        devices[i].energy_consumption = roundf(rand() % (max_energy_consumption - min_energy_consumption + 1) + min_energy_consumption);
        devices[i].operational_state = rand() % (max_operational_state - min_operational_state + 1) + min_operational_state;
        devices[i].alarm_trigger = rand() % 2 == 0 ? true : false;
        strcpy(devices[i].manufacturer, "Manufacturer");
    }

    // Group the entries by manufacturer name and calculate the average sensor reading, voltage level, current value, energy consumption, last updated timestamp, and operational state stability for each group
    for (int i = 0; i < num_devices; i++) {
        int j = 0;
        while (j < num_devices && strcmp(devices[i].manufacturer, devices[j].manufacturer) == 0) {
            manufacturers[i].num_devices++;
            manufacturers[i].avg_sensor_reading += devices[j].sensor_reading;
            manufacturers[i].avg_voltage_level += devices[j].voltage_level;
            manufacturers[i].avg_current_value += devices[j].current_value;
            manufacturers[i].avg_energy_consumption += devices[j].energy_consumption;
            manufacturers[i].avg_last_updated += devices[j].last_updated;
            manufacturers[i].avg_operational_state += devices[j].operational_state;
            j++;
        }
    }

    // Compute the standard deviation of sensor readings, voltage levels, current values, energy consumption, and last updated timestamps for each group
    for (int i = 0; i < num_devices; i++) {
        manufacturers[i].std_sensor_reading = sqrt(manufacturers[i].avg_sensor_reading);
        manufacturers[i].std_voltage_level = sqrt(manufacturers[i].avg_voltage_level);
        manufacturers[i].std_current_value = sqrt(manufacturers[i].avg_current_value);
        manufacturers[i].std_energy_consumption = sqrt(manufacturers[i].avg_energy_consumption);
        manufacturers[i].std_last_updated = sqrt(manufacturers[i].avg_last_updated);
    }

    // Free the memory allocated for the arrays and structures
    free(devices);
    free(manufacturers);
}
