    // Allocate memory for the hash table
    int *hash_table = (int *)malloc(MAX_TABLE_SIZE * sizeof(int));
    if (!hash_table) {
        printf("Error: Out of memory\n");
        free(pollutant_concentrations);
        free(sensor_metadata);
        return;
    }

    // Initialize the hash table with zeros
    memset(hash_table, 0, MAX_TABLE_SIZE * sizeof(int));

    // Allocate memory for the alert records array
    alert_record_t *alert_records = (alert_record_t *)malloc(n * sizeof(alert_record_t));
    if (!alert_records) {
        printf("Error: Out of memory\n");
        free(pollutant_concentrations);
        free(sensor_metadata);
        free(hash_table);
        return;
    }

    // Initialize the alert records array with zeros
    memset(alert_records, 0, n * sizeof(alert_record_t));
}

// Define the function to update the hash table with new location codes and descriptions
void update_hash_table(int max_table_size) {
    // Check if the hash table has exceeded its maximum size
    if (hash_table_size > max_table_size) {
        printf("Error: Hash table has exceeded its maximum size\n");
        return;
    }

    // Add new location codes and descriptions to the hash table
    for (int i = 0; i < n; i++) {
        int code = sensor_metadata[i].pollution_code;
        char *description = sensor_metadata[i].alert_description;
        if (!hash_table[code]) {
            hash_table[code] = description;
        } else {
            printf("Error: Hash table has duplicate location code\n");
            return;
        }
    }
}

// Define the function to update the alert records with new pollutant concentrations and safety thresholds
void update_alert_records(int n) {
    // Check if the alert records array has exceeded its maximum size
    if (n > MAX_TABLE_SIZE) {
        printf("Error: Alert records array has exceeded its maximum size\n");
        return;
    }

    // Update the pollutant concentrations and safety thresholds in the alert records array
    for (int i = 0; i < n; i++) {
        float concentration = pollutant_concentrations[i];
        float threshold = sensor_metadata[i].safety_threshold;
        if (concentration > threshold) {
            alert_records[i].impact_level = concentration - threshold;
            alert_records[i].alert_status = true;
        } else {
            alert_records[i].impact_level = 0.0f;
            alert_records[i].alert_status = false;
        }
    }
}

// Define the function to reset the entire system to its initial state
void reset_system() {
    // Free all allocated memory
    free(pollutant_concentrations);
    free(sensor_metadata);
    free(hash_table);
    free(alert_records);

    // Initialize the arrays with zeros
    pollutant_concentrations = (float *)malloc(n * sizeof(float));
    memset(pollutant_concentrations, 0, n * sizeof(float));
    sensor_metadata = (sensor_metadata_t *)malloc(n * sizeof(sensor_metadata_t));
    memset(sensor_metadata, 0, n * sizeof(sensor_metadata_t));
    hash_table = (int *)malloc(MAX_TABLE_SIZE * sizeof(int));
    memset(hash_table, 0, MAX_TABLE_SIZE * sizeof(int));
    alert_records = (alert_record_t *)malloc(n * sizeof(alert_record_t));
    memset(alert_records, 0, n * sizeof(alert_record_t));
}

// Define the function to reset only the average pollution level and alert status to their initial states
void partial_reset() {
    // Reset the arrays with zeros
    memset(pollutant_concentrations, 0, n * sizeof(float));
    for (int i = 0; i < n; i++) {
        sensor_metadata[i].alert_status = false;
    }
}
