// Define the structure for a point
typedef struct {
    int x;
    int y;
    time_t timestamp;
    char status[256];
} Point;

// Define the structure for a dynamic collection of points
typedef struct {
    Point* points;
    size_t num_points;
    pthread_mutex_t mutex;
} Points;

// Function to initialize a new point
Point* init_point(int x, int y) {
    Point* point = (Point*)malloc(sizeof(Point));
    if (!point) {
        return NULL;
    }
    point->x = x;
    point->y = y;
    point->timestamp = time(NULL);
    sprintf(point->status, "Point at (%d, %d) with status: %s", x, y, "initialized");
    return point;
}

// Function to add a new point to the collection
int add_point(Points* points, int x, int y) {
    if (!points || !points->points) {
        return -1;
    }
    pthread_mutex_lock(&points->mutex);
    Point* new_point = init_point(x, y);
    if (!new_point) {
        pthread_mutex_unlock(&points->mutex);
        return -1;
    }
    points->points[points->num_points++] = new_point;
    pthread_mutex_unlock(&points->mutex);
    return 0;
}

// Function to update the status of a point in the collection
int update_status(Points* points, int index, char* status) {
    if (!points || !points->points || index >= points->num_points) {
        return -1;
    }
    pthread_mutex_lock(&points->mutex);
    Point* point = &points->points[index];
    strcpy(point->status, status);
    pthread_mutex_unlock(&points->mutex);
    return 0;
}

// Function to retrieve a point from the collection by index
Point* get_point(Points* points, int index) {
    if (!points || !points->points || index >= points->num_points) {
        return NULL;
    }
    pthread_mutex_lock(&points->mutex);
    Point* point = &points->points[index];
    pthread_mutex_unlock(&points->mutex);
    return point;
}

// Function to retrieve all points from the collection
Point** get_all_points(Points* points) {
    if (!points || !points->points) {
        return NULL;
    }
    pthread_mutex_lock(&points->mutex);
    Point** all_points = (Point**)malloc(sizeof(Point*) * points->num_points);
    for (int i = 0; i < points->num_points; i++) {
        all_points[i] = &points->points[i];
    }
    pthread_mutex_unlock(&points->mutex);
    return all_points;
}

// Function to free the memory allocated for a point
void free_point(Point* point) {
    if (!point) {
        return;
    }
    free(point);
}

// Function to free the memory allocated for all points in the collection
void free_all_points(Points* points) {
    if (!points || !points->points) {
        return;
    }
    pthread_mutex_lock(&points->mutex);
    for (int i = 0; i < points->num_points; i++) {
        free_point(&points->points[i]);
    }
    free(points->points);
    pthread_mutex_unlock(&points->mutex);
}
