    for (int i = 0; i < num_records; i++) {
        key_arr[i] = rand() % (max_value - min_value + 1) + min_value;
    }

    // Allocate memory for the record array
    rec_arr = (record*)malloc(num_records * sizeof(record));
    if (!rec_arr) {
        printf("Error: Failed to allocate memory for record array\n");
        free(offset_arr);
        free(key_arr);
        return;
