// Define the record structure
typedef struct {
    int value;
} Record;

// Function to dynamically allocate memory for arrays
void *allocate_memory(size_t size, char *type) {
    void *ptr = NULL;
    if ((ptr = malloc(size)) == NULL) {
        fprintf(stderr, "Error: Failed to allocate %zu bytes of memory for %s\n", size, type);
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to read initial values from configuration file
void read_config(char *filename, int **offset, int **key) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Error: Failed to open configuration file %s\n", filename);
        exit(EXIT_FAILURE);
    }
    int num_records;
    if (fscanf(file, "%d", &num_records) != 1) {
        fprintf(stderr, "Error: Failed to read number of records from configuration file\n");
        exit(EXIT_FAILURE);
    }
    *offset = allocate_memory(sizeof(int) * num_records, "offset array");
    *key = allocate_memory(sizeof(int) * num_records, "key array");
    for (int i = 0; i < num_records; i++) {
        if (fscanf(file, "%d %d", &(*offset)[i], &(*key)[i]) != 2) {
            fprintf(stderr, "Error: Failed to read offset and key values from configuration file\n");
            exit(EXIT_FAILURE);
        }
    }
}

// Function to read data from network stream
void read_network_stream(int sockfd, Record **records) {
    int num_records;
    if (read(sockfd, &num_records, sizeof(int)) < 0) {
        fprintf(stderr, "Error: Failed to read number of records from network stream\n");
        exit(EXIT_FAILURE);
    }
    *records = allocate_memory(sizeof(Record) * num_records, "record array");
    for (int i = 0; i < num_records; i++) {
        if (read(sockfd, &(*records)[i].value, sizeof(int)) < 0) {
            fprintf(stderr, "Error: Failed to read record value from network stream\n");
            exit(EXIT_FAILURE);
        }
    }
}

// Function to handle memory allocation failures
void handle_memory_allocation_failure() {
    fprintf(stderr, "Error: Memory allocation failed\n");
    exit(EXIT_FAILURE);
}

// Function to handle network errors
void handle_network_error() {
    fprintf(stderr, "Error: Network error occurred\n");
    exit(EXIT_FAILURE);
}

// Main function
int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <configuration file> <network stream>\n", argv[0]);
        exit(EXIT_FAILURE);
    }
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        handle_network_error();
    }
    struct sockaddr_in serv_addr;
