        fprintf(stderr, "Error: Failed to convert network address\n");
        exit(EXIT_FAILURE);
    }
    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        handle_network_error();
    }
    int *offset = NULL;
    int *key = NULL;
    read_config(argv[1], &offset, &key);
    Record **records = allocate_memory(sizeof(Record *) * (offset[0] + offset[1]), "record array");
    for (int i = 0; i < offset[0]; i++) {
        read_network_stream(sockfd, &(*records)[i]);
    }
    for (int i = 0; i < offset[1]; i++) {
        read_network_stream(sockfd, &(*records)[offset[0] + i]);
    }
    // Handle race conditions and partial data received due to network interruptions
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    int num_threads = 2; // Number of threads to read from network stream
    pthread_t thread[num_threads];
    for (int i = 0; i < num_threads; i++) {
