            pthread_mutex_lock(&mutex);
            int num_partial_records = num_records - (offset[0] + offset[1]);
            Record *partial_record = allocate_memory(sizeof(Record) * num_partial_records, "partial record array");
            memcpy(partial_record, &(*records)[offset[0] + offset[1]], sizeof(Record) * num_partial_records);
            pthread_mutex_unlock(&mutex);
        }
    }
}
