}

// Function to create a binary search tree with the given maximum depth
bst_node_t* create_bst(int max_depth) {
    bst_node_t* root = (bst_node_t*)malloc(sizeof(bst_node_t));
    if (!root) {
        printf("Error: Failed to allocate memory for binary search tree\n");
        return NULL;
    }
    root->data = NULL;
    root->left = NULL;
    root->right = NULL;
    return root;
}

// Function to insert a configuration profile into the binary search tree
void insert_profile(bst_node_t* root, config_profile_t* profile) {
    if (!root) {
        printf("Error: Binary search tree is empty\n");
        return;
    }
    if (root->data == NULL) {
        root->data = profile;
        return;
    }
    int cmp_result = strcmp(profile->name, root->data->name);
    if (cmp_result < 0) {
        insert_profile(root->left, profile);
    } else if (cmp_result > 0) {
        insert_profile(root->right, profile);
    } else {
        printf("Error: Configuration profile with name %s already exists\n", profile->name);
    }
}

// Function to search for a configuration profile in the binary search tree
config_profile_t* search_profile(bst_node_t* root, char* name) {
    if (!root) {
        printf("Error: Binary search tree is empty\n");
        return NULL;
    }
    if (strcmp(name, root->data->name) == 0) {
        return root->data;
    } else if (strcmp(name, root->left->data->name) < 0) {
        return search_profile(root->left, name);
    } else if (strcmp(name, root->right->data->name) > 0) {
        return search_profile(root->right, name);
    } else {
        printf("Error: Configuration profile with name %s does not exist\n", name);
        return NULL;
    }
}

// Function to update a configuration profile in the binary search tree
void update_profile(bst_node_t* root, config_profile_t* profile) {
    if (!root) {
        printf("Error: Binary search tree is empty\n");
        return;
    }
    int cmp_result = strcmp(profile->name, root->data->name);
    if (cmp_result < 0) {
        update_profile(root->left, profile);
    } else if (cmp_result > 0) {
        update_profile(root->right, profile);
    } else {
        root->data = profile;
    }
}

// Function to delete a configuration profile from the binary search tree
void delete_profile(bst_node_t* root, char* name) {
    if (!root) {
        printf("Error: Binary search tree is empty\n");
        return;
    }
