#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define constants for the system
#define MAX_VEHICLE_COUNT 10000
#define MIN_SPEED_LIMIT 50
#define MAX_SPEED_LIMIT 80
#define CONGESTION_THRESHOLD 60
#define INCIDENT_CODE_DEFAULT 'N'
#define EVENT_TYPE_NORMAL 1
#define EVENT_TYPE_CONGESTION 2
#define EVENT_TYPE_INCIDENT 3

// Define data structures for the system
typedef struct {
    time_t timestamp;
    char event_description[50];
    int impact_level;
} EventRecord;

typedef struct {
    float speed_limit;
    int average_speed;
    bool congestion_alert;
    char incident_code;
    enum EventType event_type;
} SensorMetadata;

// Define functions for the system
void init_system(int n) {
    // Allocate memory for the arrays
    vehicle_counts = (int*)malloc(n * sizeof(int));
    sensor_metadata = (SensorMetadata*)malloc(n * sizeof(SensorMetadata));
    event_records = (EventRecord*)malloc(MAX_VEHICLE_COUNT * sizeof(EventRecord));

    // Initialize the arrays with zeros
    memset(vehicle_counts, 0, n * sizeof(int));
    memset(sensor_metadata, 0, n * sizeof(SensorMetadata));
    memset(event_records, 0, MAX_VEHICLE_COUNT * sizeof(EventRecord));

    // Set the congestion alert status to false for all sensors
    for (int i = 0; i < n; i++) {
        sensor_metadata[i].congestion_alert = false;
    }

    // Clear the incident code for all events
    for (int i = 0; i < MAX_VEHICLE_COUNT; i++) {
        event_records[i].incident_code = INCIDENT_CODE_DEFAULT;
    }
}

void reset_system() {
    // Free all allocated memory
    free(vehicle_counts);
    free(sensor_metadata);
    free(event_records);

    // Reinitialize the arrays with zeros
    init_system(n);
}

void partial_reset() {
    // Reset only the average speed and congestion alert status for all sensors
    for (int i = 0; i < n; i++) {
        sensor_metadata[i].average_speed = 0;
        sensor_metadata[i].congestion_alert = false;
    }
}

void update_sensor_data(int sensor_index, float speed_limit, int average_speed) {
    // Update the speed limit and average speed for the specified sensor
    sensor_metadata[sensor_index].speed_limit = speed_limit;
    sensor_metadata[sensor_index].average_speed = average_speed;

    // Check if the average speed is below the congestion threshold
    if (sensor_metadata[sensor_index].average_speed < CONGESTION_THRESHOLD) {
        sensor_metadata[sensor_index].congestion_alert = true;
    } else {
        sensor_metadata[sensor_index].congestion_alert = false;
    }
}

void update_event_records(int vehicle_count, char incident_code) {
    // Update the event records with the specified vehicle count and incident code
    for (int i = 0; i < MAX_VEHICLE_COUNT; i++) {
        if (vehicle_counts[i] == vehicle_count) {
            event_records[i].incident_code = incident_code;
            break;
        }
    }
}

void handle_api_throttling() {
    // Implement API throttling logic here
}

void handle_network_failure() {
    // Implement network failure handling logic here
}

int main() {
    int n = 10; // Number of sensors

    init_system(n);

    while (true) {
        // Handle real-time traffic updates here

        // Update the sensor data and event records as needed
        update_sensor_data(sensor_index, speed_limit, average_speed);
        update_event_records(vehicle_count, incident_code);
    }

    return 0;
}
```
This implementation includes a `init_system` function that allocates memory for the arrays and initializes them with zeros. It also sets the congestion alert status to false for all sensors and clears the incident code for all events. A `reset_system` function is provided to free all allocated memory and reinitialize the arrays with zeros. A `partial_reset` function is also provided to reset only the average speed and congestion alert status for all sensors, leaving other data unchanged.

The `update_sensor_data` function updates the speed limit and average speed for the specified sensor, and checks if the average speed is below the congestion threshold. If it is, the congestion alert status is set to true. Otherwise, it is set to false. The `update_event_records` function updates the event records with the specified vehicle count and incident code.

The `handle_api_throttling` and `handle_network_failure` functions are not implemented in this example, but they could be used to handle API throttling and network failure handling logic.

This implementation also includes a `main` function that initializes the system with 10 sensors and enters an infinite loop to handle real-time traffic updates. It updates the sensor data and event records as needed, and continues running until the program is terminated."]

