// Resize an array to a new capacity, preserving data integrity and handling potential failures gracefully
void DynamicMemoryAllocator_resize_array(DynamicMemoryAllocator* allocator, void** array, size_t old_capacity, size_t new_capacity) {
    // Check if the new capacity is greater than the old capacity
    if (new_capacity > old_capacity) {
        // Reallocate memory for the array with a new capacity
        void* new_array = realloc(*array, new_capacity * sizeof(**array));
        if (!new_array) {
            // Handle allocation failure gracefully by logging an error and returning early
            fprintf(stderr, "Failed to resize array: %s\n", strerror(errno));
