        allocator->capacity = new_capacity;
    }
}

// Populate an array with random integers within a specified range, preserving data integrity and handling potential failures gracefully
void DynamicMemoryAllocator_populate_array(DynamicMemoryAllocator* allocator, void** array, size_t capacity, int min, int max) {
    // Check if the capacity is greater than 0
    if (capacity > 0) {
        // Generate a random integer within the specified range for each element in the array
        for (size_t i = 0; i < capacity; ++i) {
