void DynamicMemoryAllocator_insert_record(DynamicMemoryAllocator* allocator, Record* record) {
    // Check if the capacity of the array is greater than 0
    if (allocator->record_array_capacity > 0) {
        // Reallocate memory for the array with a new capacity
        Record* new_array = realloc(allocator->record_array, allocator->record_array_capacity * sizeof(*new_array));
        if (!new_array) {
            // Handle allocation failure gracefully by logging an error and returning early
