    // Remove the record with the specified key from the data structure
    ds->records[i] = NULL;
    ds->keys[i] = 0;
    ds->offsets[i] = 0;

    // Decrement the capacity of the data structure
    ds->capacity--;

    // Reallocate memory for the record structures if necessary
    if (ds->capacity > 0 && ds->records[ds->capacity - 1] == NULL) {
        ds->records = realloc(ds->records, sizeof(Record *) * (ds->capacity));
    }

    // Release the mutex for synchronizing access to the data structure
    pthread_mutex_unlock(&ds->mutex);
