void filterRecords(DataStructure *ds, int (*condition)(Record *)) {
    // Acquire the mutex for synchronizing access to the data structure
    pthread_mutex_lock(&ds->mutex);

    // Iterate over all records in the data structure and apply the user-defined condition
    for (size_t i = 0; i < ds->capacity; i++) {
