void serializeRecords(DataStructure *ds, FILE *file) {
    // Acquire the mutex for synchronizing access to the data structure
    pthread_mutex_lock(&ds->mutex);

    // Iterate over all records in the data structure and write them to the binary file
    for (size_t i = 0; i < ds->capacity; i++) {
        Record *record = ds->records[i];
        fwrite(record, sizeof(Record), 1, file);
    }

    // Release the mutex for synchronizing access to the data structure
    pthread_mutex_unlock(&ds->mutex);
}

void deserializeRecords(DataStructure *ds, FILE *file) {
    // Acquire the mutex for synchronizing access to the data structure
    pthread_mutex_lock(&ds->mutex);

    // Iterate over all records in the binary file and add them to the data structure
    while (!feof(file)) {
        Record *record = malloc(sizeof(Record));
        fread(record, sizeof(Record), 1, file);
        insertRecord(ds, record->key, record);
    }

    // Release the mutex for synchronizing access to the data structure
    pthread_mutex_unlock(&ds->mutex);
}
