typedef struct {
    int presence_flag;
} Metadata;

// Define an array of pointers to hold the records and their metadata
Record *records[4];
Metadata *metadata[4];

// Define a function to initialize the data store with a specified size
void init_data_store(int size) {
    // Allocate memory for the records and metadata arrays
    records = (Record **)malloc(size * sizeof(Record));
    metadata = (Metadata **)malloc(size * sizeof(Metadata));

    // Initialize each record with a unique key and buffer
    for (int i = 0; i < size; i++) {
        records[i] = (Record *)malloc(sizeof(Record));
        metadata[i] = (Metadata *)malloc(sizeof(Metadata));
        records[i]->key = i;
        strcpy(records[i]->buffer, "unique_string");
        metadata[i]->presence_flag = 0;
    }
}

// Define a function to insert a new record into the data store
void insert_record(int key, char *buffer, float value) {
    // Check if the key is already present in the cache
    for (int i = 0; i < size; i++) {
        if (records[i]->key == key) {
            // Update the existing record with the new buffer and value
            strcpy(records[i]->buffer, buffer);
            records[i]->value = value;
            metadata[i]->presence_flag = 1;
            return;
        }
    }

    // If the key is not present in the cache, insert a new record
    for (int i = 0; i < size; i++) {
        if (metadata[i]->presence_flag == 0) {
            records[i]->key = key;
            strcpy(records[i]->buffer, buffer);
            records[i]->value = value;
            metadata[i]->presence_flag = 1;
            return;
        }
    }
}

// Define a function to retrieve a record from the data store
Record *get_record(int key) {
    // Check if the key is present in the cache
    for (int i = 0; i < size; i++) {
        if (records[i]->key == key) {
            metadata[i]->presence_flag = 1;
            return records[i];
        }
    }

    // If the key is not present in the cache, return NULL
    return NULL;
}

// Define a function to update a record in the data store
void update_record(int key, char *buffer, float value) {
    // Check if the key is present in the cache
    for (int i = 0; i < size; i++) {
        if (records[i]->key == key) {
            strcpy(records[i]->buffer, buffer);
            records[i]->value = value;
            metadata[i]->presence_flag = 1;
            return;
        }
    }
}

// Define a function to delete a record from the data store
void delete_record(int key) {
    // Check if the key is present in the cache
    for (int i = 0; i < size; i++) {
        if (records[i]->key == key) {
            metadata[i]->presence_flag = 0;
            return;
        }
    }
}

// Define a function to clean up the data store and release all allocated resources
void cleanup() {
    // Free the memory for the records and metadata arrays
    free(records);
    free(metadata);
}
