void manage_data(int num_offsets, int num_keys) {
    // Allocate memory for the offsets array
    long* offsets = (long*)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        return;
    }

    // Allocate memory for the keys array
    int* keys = (int*)malloc(num_keys * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Define a record structure to store metadata efficiently
    Record* records = (Record*)malloc(num_offsets * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Populate the offsets array with unique values within a specified range
    int offset_value = 0;
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = offset_value++;
    }

    // Populate the keys array with unique values within a specified range
    int key_value = 0;
    for (int i = 0; i < num_keys; i++) {
        keys[i] = key_value++;
    }

    // Assign unique identifiers to each character string pointer in the records array
    for (int i = 0; i < num_offsets; i++) {
        Record* record = &records[i];
        record->string = (char*)malloc(256 * sizeof(char));
        if (!record->string) {
            printf("Error: Failed to allocate memory for string\n");
            free(offsets);
            free(keys);
            free(records);
            return;
        }
        record->value = i;
    }

    // Cleanup mechanism that can handle unexpected termination gracefully
    atexit(cleanup);
}

// Cleanup function to deallocate all memory allocated by the manage_data function
void cleanup() {
    free(offsets);
    free(keys);
    for (int i = 0; i < num_offsets; i++) {
        Record* record = &records[i];
        free(record->string);
    }
    free(records);
}
