    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    if (pthread_mutex_lock(&mutex) != 0) {
        printf("Error: Failed to lock mutex\n");
        free(timestamps);
        free(event_types);
        free(log_entries);
        return;
