        }
    } else {
        printf("Error: Invalid value or priority for retrieving node\n");
    }
    if (pthread_mutex_unlock(&mutex) != 0) {
        printf("Error: Failed to unlock mutex\n");
    }

    // Clean up the memory and exit
    free(timestamps);
    free(event_types);
    free(log_entries);
    pthread_join(cleanup_thread, NULL);
}

// Define the cleanup function to remove nodes older than a specified age threshold
void* cleanup_function(void* arg) {
