    if (outfile == NULL) {
        printf("Error opening output file\n");
        return;
    }

    // Write the configuration settings to the output file
    for (int i = 0; i < num_settings; i++) {
        fprintf(outfile, "%s %d %d\n", configs[i].name, configs[i].value, configs[i].flag);
