// Define the function to deserialize the current state of the configuration settings from a file format of your choice
void deserialize_configs(config_t* configs, FILE* fp) {
    // Check if the file pointer is valid
    if (fp == NULL) {
        fprintf(stderr, "Invalid file pointer\n");
        return;
    }

    // Deserialize the configuration settings from the file
