// Custom allocator for managing memory pools
struct MemoryPool {
    size_t capacity; // Total capacity of the pool
    size_t used;     // Amount of memory currently in use
    char* buffer;    // Pointer to the start of the buffer
};

// Function to allocate a new memory pool with a given capacity
struct MemoryPool* createMemoryPool(size_t capacity) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) {
        return NULL;
    }
    pool->capacity = capacity;
    pool->used = 0;
    pool->buffer = malloc(capacity);
    if (!pool->buffer) {
        free(pool);
        return NULL;
    }
    return pool;
}

// Function to allocate memory from a given memory pool
void* allocateMemory(struct MemoryPool* pool, size_t size) {
    void* ptr = NULL;
    if (size > 0 && pool->used + size <= pool->capacity) {
        ptr = pool->buffer + pool->used;
        pool->used += size;
    }
    return ptr;
}

// Function to free a memory pool and all its allocated memory
void destroyMemoryPool(struct MemoryPool* pool) {
    if (pool) {
        free(pool->buffer);
        free(pool);
    }
}

// Custom allocator for managing memory pools with best-fit allocation strategy
struct BestFitAllocator {
    struct MemoryPool* pool; // Pointer to the current memory pool
};

// Function to create a new best-fit allocator
struct BestFitAllocator* createBestFitAllocator() {
    struct BestFitAllocator* allocator = malloc(sizeof(struct BestFitAllocator));
    if (!allocator) {
        return NULL;
    }
    allocator->pool = createMemoryPool(1000); // Default pool size is 1000 bytes
    if (!allocator->pool) {
        free(allocator);
        return NULL;
    }
    return allocator;
}

// Function to allocate memory from the best-fit allocator
void* allocateMemoryBestFit(struct BestFitAllocator* allocator, size_t size) {
    void* ptr = NULL;
    if (size > 0 && allocator->pool->used + size <= allocator->pool->capacity) {
        ptr = allocator->pool->buffer + allocator->pool->used;
        allocator->pool->used += size;
    } else {
        // If the current pool is full, create a new one with double the capacity
        struct MemoryPool* new_pool = createMemoryPool(allocator->pool->capacity * 2);
        if (new_pool) {
            allocator->pool = new_pool;
            ptr = allocateMemoryBestFit(allocator, size);
        }
    }
    return ptr;
}

// Function to free a best-fit allocator and all its allocated memory pools
void destroyBestFitAllocator(struct BestFitAllocator* allocator) {
    if (allocator) {
        destroyMemoryPool(allocator->pool);
        free(allocator);
    }
}

