    printf("%s\n", message);
}

// Initialize dynamic memory allocation for offsets, keys, and records
int init_memory(Offset** offsets, Key** keys, Record*** records, int num_records) {
    // Allocate memory for offsets array
    *offsets = (Offset*)malloc(sizeof(Offset) * num_records);
    if (*offsets == NULL) {
        log("Error: Failed to allocate memory for offsets");
        return -1;
    }

    // Allocate memory for keys array
    *keys = (Key*)malloc(sizeof(Key) * num_records);
    if (*keys == NULL) {
        log("Error: Failed to allocate memory for keys");
        free(*offsets);
        return -1;
    }

    // Allocate memory for records array
    *records = (Record**)malloc(sizeof(Record*) * num_records);
    if (*records == NULL) {
        log("Error: Failed to allocate memory for records");
        free(*offsets);
        free(*keys);
        return -1;
    }

    // Initialize offsets array with default values
    for (int i = 0; i < num_records; i++) {
        (*offsets)[i].offset = 0;
    }

    // Initialize keys array with default values
    for (int i = 0; i < num_records; i++) {
        (*keys)[i].key = i;
    }

    // Initialize records array with unique values and strings
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (record == NULL) {
            log("Error: Failed to allocate memory for record");
            free(*offsets);
            free(*keys);
            return -1;
        }
        (*records)[i] = record;
        record->value = i;
        for (int j = 0; j < 10; j++) {
            char c = 'a' + rand() % 26;
            record->buffer[j] = c;
        }
        record->last_modified = time(NULL);
        record->access_frequency = 0;
    }

    return 0;
}

// Free all allocated memory when done
void free_memory(Offset* offsets, Key* keys, Record** records) {
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    if (records != NULL) {
        for (int i = 0; i < num_records; i++) {
            Record* record = records[i];
            if (record != NULL) {
                free(record);
            }
        }
        free(records);
    }
}
