// Structure to represent a node in the linked list
typedef struct Node {
    char key;
    struct Node* next;
    bool isSpecial;
} Node;

// Function to dynamically allocate memory for an array of 'node' structures
Node** createArray(int size) {
    // Allocate memory for the array of pointers
    Node** arr = malloc(size * sizeof(Node*));
    if (arr == NULL) {
        printf("Error: Failed to allocate memory for array\n");
        return NULL;
    }

    // Initialize each pointer in the array to NULL
    for (int i = 0; i < size; i++) {
        arr[i] = NULL;
    }

    return arr;
}

// Function to initialize a new node with the given key and insert it into the linked list
void insertNode(Node** head, char key) {
    // Allocate memory for the new node
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Error: Failed to allocate memory for new node\n");
        return;
    }

    // Set the key and next pointer of the new node
    newNode->key = key;
    newNode->next = *head;

    // Update the head pointer to point to the new node
    *head = newNode;
}

// Function to check if a given key is already present in the linked list
bool isKeyPresent(Node* head, char key) {
    while (head != NULL) {
        if (head->key == key) {
            return true;
        }
        head = head->next;
    }
    return false;
}

// Function to insert a new node into the linked list based on the given key, ensuring no duplicates are added
void insertNodeWithCheck(Node** head, char key) {
    if (!isKeyPresent(*head, key)) {
        insertNode(head, key);
    } else {
        printf("Error: Duplicate key detected\n");
    }
}

// Function to free the memory allocated for the linked list
void freeArray(Node** head) {
    while (*head != NULL) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}
