#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>

// Define the node structure for the linked list
typedef struct Node {
    char key;
    struct Node* next;
    bool special_category;
} Node;

// Function to dynamically allocate memory for a new node and initialize it with the given key
Node* create_node(char key) {
    // Allocate memory for the new node
    Node* new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Error: Failed to allocate memory for new node\n");
        return NULL;
    }

    // Initialize the new node with the given key and set its next pointer to NULL
    new_node->key = key;
    new_node->next = NULL;
    new_node->special_category = false;

    return new_node;
}

// Function to insert a new node into the linked list based on the given key value, ensuring no duplicate keys are added
void insert_node(Node** head_ref, char key) {
    // Check if the key already exists in the linked list
    Node* current = *head_ref;
    while (current != NULL && current->key != key) {
        current = current->next;
    }

    // If the key already exists, return without inserting a new node
    if (current != NULL) {
        printf("Error: Duplicate key detected\n");
        return;
    }

    // Allocate memory for the new node and initialize it with the given key
    Node* new_node = create_node(key);
    if (new_node == NULL) {
        printf("Error: Failed to allocate memory for new node\n");
        return;
    }

    // Insert the new node at the beginning of the linked list
    new_node->next = *head_ref;
    *head_ref = new_node;
}

// Function to delete a node from the linked list based on the given key value
void delete_node(Node** head_ref, char key) {
    // Check if the key exists in the linked list
    Node* current = *head_ref;
    while (current != NULL && current->key != key) {
        current = current->next;
    }

    // If the key does not exist, return without deleting a node
    if (current == NULL) {
        printf("Error: Key not found\n");
        return;
    }

    // Delete the node from the linked list by updating the next pointer of the previous node to skip over it
    Node* previous = *head_ref;
    while (previous->next != current) {
        previous = previous->next;
    }
    previous->next = current->next;

    // Free the memory allocated for the deleted node
    free(current);
}

// Function to search for a node in the linked list based on the given key value
Node* search_node(Node** head_ref, char key) {
    // Check if the key exists in the linked list
    Node* current = *head_ref;
    while (current != NULL && current->key != key) {
        current = current->next;
    }

    // If the key does not exist, return NULL
    if (current == NULL) {
        printf("Error: Key not found\n");
        return NULL;
    }

    return current;
}

// Function to print all nodes in the linked list
void print_nodes(Node* head) {
    // Check if the linked list is empty
    if (head == NULL) {
        printf("Error: Linked list is empty\n");
        return;
    }

    // Print all nodes in the linked list
    Node* current = head;
    while (current != NULL) {
        printf("%c ", current->key);
        current = current->next;
    }
    printf("\n");
}

// Function to free all memory allocated for the linked list
void free_nodes(Node** head_ref) {
    // Check if the linked list is empty
    if (*head_ref == NULL) {
        return;
    }

    // Free all nodes in the linked list
    Node* current = *head_ref;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}
