        free(offsets);
        free(keys);
        free(records);
        return;
    }
    offset_cache->capacity = num_offsets / 2;
    offset_cache->size = 0;
    offset_cache->offsets = (Offset*)malloc(offset_cache->capacity * sizeof(Offset));
    if (!offset_cache->offsets) {
        printf("Error: Failed to allocate memory for offset cache\n");
        free(offset_cache);
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Create a cache for frequently accessed keys
