        printf("Error: Failed to allocate memory for key cache\n");
        free(offset_cache);
        free(offsets);
        free(keys);
        free(records);
        return;
    }
    key_cache->capacity = num_keys / 2;
    key_cache->size = 0;
    key_cache->keys = (Key*)malloc(key_cache->capacity * sizeof(Key));
    if (!key_cache->keys) {
        printf("Error: Failed to allocate memory for key cache\n");
        free(key_cache);
        free(offset_cache);
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Create a cache for records
    struct RecordCache* record_cache = (struct RecordCache*)malloc(sizeof(struct RecordCache));
    if (!record_cache) {
        printf("Error: Failed to allocate memory for record cache\n");
        free(key_cache);
        free(offset_cache);
        free(offsets);
        free(keys);
        free(records);
        return;
