    bool validateTemperature(float temperature) {
        return (temperature >= 0 && temperature <= 100);
    }

    // Validate the humidity level against predefined operational thresholds
    bool validateHumidity(int humidity) {
        return (humidity >= 0 && humidity <= 100);
    }

    // Validate the pressure measurement against predefined operational thresholds
    bool validatePressure(double pressure) {
        return (pressure >= 0 && pressure <= 100);
    }
};

