#include <string.h>
#include <openssl/evp.h>

// Define a structure to store information about a cryptographic hash function
typedef struct {
    const char *name;
    EVP_MD *(*func)();
} hash_function_t;

// Define a function to get a list of available cryptographic hash functions
int get_available_cryptographic_hash_functions(hash_function_t **hash_functions, int *num_hash_functions) {
    // Get the number of available hash functions
    int num_hashes = EVP_MD_count();

    // Allocate memory for the list of hash functions
    hash_function_t *hash_functions_list = (hash_function_t *)malloc(sizeof(hash_function_t) * num_hashes);
    if (!hash_functions_list) {
        printf("Failed to allocate memory for hash function list\n");
        return -1;
    }

    // Loop through the available hash functions and store their information in the list
    int i = 0;
    EVP_MD *md;
    while ((md = EVP_get_digestbyname(EVP_MD_names[i])) != NULL) {
        hash_functions_list[i].name = md->name;
        hash_functions_list[i].func = md->init;
        i++;
    }

    // Set the number of available hash functions and return the list
    *num_hash_functions = num_hashes;
    *hash_functions = hash_functions_list;

    return 0;
}
