// Define a function to put a key-value pair in the map
void mapPut(Map* map, char* key, void* value) {
    // Check if the map is full
    if (map->size == map->capacity) {
        printf("Error: Map is full\n");
        return;
    }

    // Allocate memory for a new key-value pair
    char* newKey = (char*)malloc(strlen(key) + 1);
    if (newKey == NULL) {
        printf("Error: Failed to allocate memory for map key\n");
        return;
    }
    strcpy(newKey, key);
    void* newValue = malloc(sizeof(void*));
    if (newValue == NULL) {
        printf("Error: Failed to allocate memory for map value\n");
        return;
    }
    memcpy(newValue, value, sizeof(void*));

    // Add the key-value pair to the map
    map->keys[map->size] = newKey;
    map->values[map->size] = newValue;
    map->size++;
}

// Define a function to get a value from the map given a key
void* mapGet(Map* map, char* key) {
    // Find the index of the key in the map
    int index = -1;
    for (int i = 0; i < map->size; i++) {
        if (strcmp(map->keys[i], key) == 0) {
            index = i;
            break;
        }
    }

    // Check if the key was found
    if (index == -1) {
        printf("Error: Key '%s' not found in map\n", key);
        return NULL;
    }

    // Return the value associated with the key
    return map->values[index];
}

// Define a function to check if a key is present in the map
int mapContainsKey(Map* map, char* key) {
    // Find the index of the key in the map
    int index = -1;
    for (int i = 0; i < map->size; i++) {
        if (strcmp(map->keys[i], key) == 0) {
            index = i;
            break;
        }
    }

    // Return whether the key was found
    return index != -1;
}

// Define a function to get the size of the map
int mapSize(Map* map) {
    return map->size;
}

// Define a function to get the capacity of the map
int mapCapacity(Map* map) {
    return map->capacity;
}

// Define a function to resize the map
void mapResize(Map* map, int newCapacity) {
    // Check if the new capacity is valid
    if (newCapacity <= 0 || newCapacity < map->size) {
        printf("Error: Invalid new capacity for map\n");
        return;
    }

    // Allocate memory for a new keys and values array
    char** newKeys = (char**)malloc(newCapacity * sizeof(char*));
    if (newKeys == NULL) {
        printf("Error: Failed to allocate memory for map keys\n");
        return;
    }
    void** newValues = (void**)malloc(newCapacity * sizeof(void*));
    if (newValues == NULL) {
        printf("Error: Failed to allocate memory for map values\n");
        return;
    }

    // Copy the old keys and values to the new arrays
    int numKeys = map->size;
    for (int i = 0; i < numKeys; i++) {
        char* key = map->keys[i];
        void* value = map->values[i];
        newKeys[i] = key;
        newValues[i] = value;
    }

    // Free the old keys and values arrays
    free(map->keys);
    free(map->values);

    // Update the map's size, capacity, and keys/values arrays
    map->size = numKeys;
    map->capacity = newCapacity;
    map->keys = newKeys;
    map->values = newValues;
}

// Define a function to free the memory of the map
void mapFree(Map* map) {
    // Free the keys and values arrays
    for (int i = 0; i < map->size; i++) {
        char* key = map->keys[i];
        void* value = map->values[i];
        free(key);
        free(value);
    }
    free(map->keys);
    free(map->values);

    // Free the map structure itself
    free(map);
}
