// Custom allocator for managing memory pools
struct MemoryPool {
    size_t capacity; // Total capacity of the pool
    size_t used;     // Amount of memory currently in use
    void* buffer;    // Pointer to the start of the buffer
};

// Function to allocate a new memory pool with a given capacity
struct MemoryPool* createMemoryPool(size_t capacity) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) {
        return NULL;
    }
    pool->capacity = capacity;
    pool->used = 0;
    pool->buffer = malloc(capacity);
    if (!pool->buffer) {
        free(pool);
        return NULL;
    }
    return pool;
}

// Function to deallocate a memory pool
void destroyMemoryPool(struct MemoryPool* pool) {
    free(pool->buffer);
    free(pool);
}

// Function to allocate memory from a memory pool
void* allocateFromPool(struct MemoryPool* pool, size_t size) {
    if (size > pool->capacity - pool->used) {
        return NULL;
    }
    void* ptr = pool->buffer + pool->used;
    pool->used += size;
    return ptr;
}

// Function to deallocate memory from a memory pool
void deallocateFromPool(struct MemoryPool* pool, void* ptr) {
    if (ptr < pool->buffer || ptr >= pool->buffer + pool->capacity) {
        return;
    }
    size_t offset = ptr - pool->buffer;
    pool->used -= offset;
}

// Function to manage a dynamic collection of network packets efficiently
struct Packet {
    void* payload; // Payload data for the packet
    uint32_t uid;  // Unique identifier for the packet
    uint32_t srcIP; // Source IP address for the packet
    uint32_t dstIP; // Destination IP address for the packet
    time_t timestamp; // Timestamp indicating when the packet was received
};

// Function to allocate an array of packets with a given size and capacity
struct Packet* createPackets(size_t size, size_t capacity) {
    struct MemoryPool* pool = createMemoryPool(capacity);
    if (!pool) {
        return NULL;
    }
    struct Packet* packets = allocateFromPool(pool, sizeof(struct Packet) * size);
    if (!packets) {
        destroyMemoryPool(pool);
        return NULL;
    }
    for (size_t i = 0; i < size; ++i) {
        packets[i].payload = allocateFromPool(pool, sizeof(uint32_t));
        if (!packets[i].payload) {
            destroyMemoryPool(pool);
            return NULL;
        }
        packets[i].uid = i + 1;
        packets[i].srcIP = rand();
        packets[i].dstIP = rand();
        packets[i].timestamp = time(NULL);
    }
    return packets;
}

// Function to deallocate an array of packets
void destroyPackets(struct Packet* packets, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        deallocateFromPool(packets[i].payload);
    }
    destroyMemoryPool(packets->pool);
}

// Function to initialize an array of packets with random integer values within a specified range
void initPackets(struct Packet* packets, size_t size, uint32_t min, uint32_t max) {
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        *((uint32_t*)packets[i].payload) = rand() % (max - min + 1) + min;
    }
}

// Function to update the payload of a packet with data from an external source
void updatePacket(struct Packet* packet, void* data, size_t size) {
    if (!packet || !data || size > sizeof(packet->payload)) {
        return;
    }
    memcpy(packet->payload, data, size);
}

// Function to reset all packet payloads to zero without reallocating memory
void resetPackets(struct Packet* packets, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        memset(packets[i].payload, 0, sizeof(uint32_t));
    }
}

// Function to handle allocation failures and ensure the function handles cases where memory allocation might fail gracefully
void* allocateFromPoolOrNull(struct MemoryPool* pool, size_t size) {
    void* ptr = allocateFromPool(pool, size);
    if (!ptr) {
        return NULL;
    }
    return ptr;
}

