pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory for an array of 'session' structures
void allocate_sessions(int num_sessions) {
    // Check if the number of sessions is within the allowed range
    if (num_sessions < 100 || num_sessions > MAX_SESSIONS) {
        printf("Invalid number of sessions: %d\n", num_sessions);
        return;
    }

    // Allocate memory for the array of sessions
    sessions = (session_t*) malloc(num_sessions * sizeof(session_t));
    if (!sessions) {
        printf("Failed to allocate memory for sessions\n");
        return;
    }

    // Initialize each session's ID, user information, timestamp, status flag, and connection IP address
    for (int i = 0; i < num_sessions; i++) {
        sessions[i].id = generate_session_id();
        sessions[i].user_info = "generic placeholder";
        sessions[i].timestamp = time(NULL);
        sessions[i].status = active;
        sessions[i].connection_ip = "127.0.0.1";
    }
}

// Function to generate a unique session ID based on the current time and an incremental counter
int generate_session_id() {
    // Generate a random number between 1 and 10,000
    int id = rand() % 10000 + 1;

    // Check if the generated ID is already in use
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i].id == id) {
            return generate_session_id();
        }
    }

    return id;
}

// Function to update the user information, status, and timestamp of a specific session by its unique ID
void update_session(int id, char* user_info, enum status status, time_t timestamp) {
    // Acquire mutex for thread safety
    pthread_mutex_lock(&mutex);

    // Check if the session exists and is active
    int index = find_session(id);
    if (index < 0 || sessions[index].status == inactive) {
        printf("Session %d does not exist or is inactive\n", id);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Update the user information, status, and timestamp of the session
    sessions[index].user_info = user_info;
    sessions[index].status = status;
    sessions[index].timestamp = timestamp;

    // Release mutex for thread safety
    pthread_mutex_unlock(&mutex);
}

// Function to find the index of a session by its unique ID
int find_session(int id) {
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i].id == id) {
            return i;
        }
    }
    return -1;
}

// Function to remove an inactive session by its unique ID
void remove_session(int id) {
    // Acquire mutex for thread safety
    pthread_mutex_lock(&mutex);

    // Check if the session exists and is active
    int index = find_session(id);
    if (index < 0 || sessions[index].status == inactive) {
        printf("Session %d does not exist or is inactive\n", id);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Remove the session from the array of sessions
    for (int i = index + 1; i < num_sessions; i++) {
        sessions[i - 1] = sessions[i];
    }
    num_sessions--;

    // Release mutex for thread safety
    pthread_mutex_unlock(&mutex);
}

// Function to periodically clean up expired sessions
void cleanup_expired_sessions() {
    time_t current_time = time(NULL);
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i].status == inactive && current_time - sessions[i].timestamp > DEFAULT_EXPIRATION_TIME) {
            remove_session(sessions[i].id);
        }
    }
}
