        sensors[i].temperature = rand() % 50 + 20.0f;
        sensors[i].humidity = rand() % 100 / 100.0f;
        sensors[i].wind_speed = rand() % 100 / 100.0f;
        sensors[i].timestamp = time(NULL);
        sensors[i].sensor_location = rand() % 100;
        sensors[i].sensor_type = rand() % 100;
        sensors[i].data_quality = rand() % 100;
    }
}

// Define function to group environmental sensor data by location name and calculate average temperature, humidity, wind speed, timestamp, sensor accuracy, and geographic identifier for each group
void groupSensors(int numSensors, SensorData* sensors) {
    // Initialize hash table for grouping environmental sensor data by location name
    HashTable* location_table = createHashTable();

    // Iterate over all environmental sensor data and add to hash table based on location name
    for (int i = 0; i < numSensors; i++) {
        char* location_name = sensors[i].location_name;
        if (!hashTableContains(location_table, location_name)) {
            // Add new entry to hash table with default values
            HashEntry* entry = createHashEntry();
            entry->key = location_name;
            entry->value = malloc(sizeof(SensorData));
            memcpy(entry->value, &sensors[i], sizeof(SensorData));
            hashTableAdd(location_table, entry);
        } else {
            // Update existing entry in hash table with new values
            HashEntry* entry = hashTableGet(location_table, location_name);
            SensorData* sensor_data = (SensorData*)entry->value;
            sensor_data->offset += sensors[i].offset;
            sensor_data->temperature += sensors[i].temperature;
            sensor_data->humidity += sensors[i].humidity;
            sensor_data->wind_speed += sensors[i].wind_speed;
            sensor_data->timestamp = max(sensor_data->timestamp, sensors[i].timestamp);
            sensor_data->sensor_location += sensors[i].sensor_location;
            sensor_data->sensor_type += sensors[i].sensor_type;
            sensor_data->data_quality += sensors[i].data_quality;
        }
    }

    // Iterate over all entries in hash table and calculate average temperature, humidity, wind speed, timestamp, sensor accuracy, and geographic identifier for each group
    HashIterator* it = hashTableGetIterator(location_table);
    while (hashIteratorHasNext(it)) {
        HashEntry* entry = hashIteratorNext(it);
        SensorData* sensor_data = (SensorData*)entry->value;
        float average_temperature = sensor_data->temperature / numSensors;
        float average_humidity = sensor_data->humidity / numSensors;
        float average_wind_speed = sensor_data->wind_speed / numSensors;
        time_t average_timestamp = sensor_data->timestamp / numSensors;
        int average_sensor_location = sensor_data->sensor_location / numSensors;
        int average_sensor_type = sensor_data->sensor_type / numSensors;
        int average_data_quality = sensor_data->data_quality / numSensors;
        printf("Average temperature for location %s: %.2f\n", entry->key, average_temperature);
        printf("Average humidity for location %s: %.2f\n", entry->key, average_humidity);
        printf("Average wind speed for location %s: %.2f\n", entry->key, average_wind_speed);
        printf("Average timestamp for location %s: %d\n", entry->key, average_timestamp);
        printf("Average sensor location for location %s: %d\n", entry->key, average_sensor_location);
        printf("Average sensor type for location %s: %d\n", entry->key, average_sensor_type);
        printf("Average data quality for location %s: %d\n", entry->key, average_data_quality);
    }
}
