void manage_profiles(int num_profiles, int default_age) {
    // Allocate memory for an array of 'profile' structures
    profile* profiles = malloc(num_profiles * sizeof(profile));
    if (profiles == NULL) {
        printf("Error: Failed to allocate memory for profiles\n");
        return;
    }
