    if (fp == NULL) {
        printf("Error: unable to open file for reading\n");
        return;
    }

    // Read the configuration settings from the file
    while (!feof(fp)) {
        char line[1024];
        fgets(line, 1024, fp);
        if (strlen(line) > 0) {
            char* key = strtok(line, "=");
            int value = atoi(strtok(NULL, "\n"));
