// Define struct for graph node
struct graph_node {
    int key;
    double weight;
    struct graph_node** adjacency_list;
};

void allocate_memory(int num_nodes, int num_edges) {
    // Allocate memory for arrays of 'double' precision floating-point numbers, 'char' byte codes, and 'struct point' objects
    double* double_array = (double*)malloc(num_nodes * sizeof(double));
    char* char_array = (char*)malloc(num_nodes * sizeof(char));
    struct point* point_array = (struct point*)malloc(num_nodes * sizeof(struct point));

    // Allocate memory for array of 'graph_node' structures
    struct graph_node** graph_node_array = (struct graph_node**)malloc(num_nodes * sizeof(struct graph_node*));

    // Initialize adjacency list pointers in each node
    for (int i = 0; i < num_nodes; i++) {
        graph_node_array[i] = (struct graph_node*)malloc(sizeof(struct graph_node));
        graph_node_array[i]->key = i;
        graph_node_array[i]->weight = 0.0;
        graph_node_array[i]->adjacency_list = NULL;
    }

    // Set weight of each node to a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_nodes; i++) {
        graph_node_array[i]->weight = ((double)rand() / RAND_MAX) * 10.0;
    }

    // Initialize adjacency list pointers in each node
    for (int i = 0; i < num_edges; i++) {
        int src = rand() % num_nodes;
        int dest = rand() % num_nodes;
        graph_node_array[src]->adjacency_list = (struct graph_node**)realloc(graph_node_array[src]->adjacency_list, sizeof(struct graph_node*) * (graph_node_array[src]->num_edges + 1));
        graph_node_array[src]->adjacency_list[graph_node_array[src]->num_edges] = graph_node_array[dest];
        graph_node_array[src]->num_edges++;
    }
}

void free_memory() {
    // Free memory allocated for arrays of 'double' precision floating-point numbers, 'char' byte codes, and 'struct point' objects
    free(double_array);
    free(char_array);
    free(point_array);

    // Free memory allocated for array of 'graph_node' structures
    for (int i = 0; i < num_nodes; i++) {
        free(graph_node_array[i]->adjacency_list);
        free(graph_node_array[i]);
    }
    free(graph_node_array);
}
```
