        network_nodes[i].connected_nodes = (int *)malloc(sizeof(int) * MAX_CONNECTED_NODES);
    }

    // Initialize connection pool
    for (int i = 0; i < NUM_CONNECTION_POOLS; i++) {
        connection_pools[i].connection_count = 0;
        for (int j = 0; j < MAX_CONNECTIONS; j++) {
            connection_pools[i].last_seen_activity[j] = 0;
        }
    }

    // Initialize logging context
    logging_context->user_id = 0;
    logging_context->logged_in = 0;
    logging_context->last_access_time = time(NULL);
}

void populate_message_queue(message_queue_t *message_queue) {
    // Generate random content lengths within a specified range
    int min_content_length = 10;
    int max_content_length = 50;
    for (int i = 0; i < message_queue->capacity; i++) {
        int content_length = rand() % (max_content_length - min_content_length + 1) + min_content_length;
        message_queue->messages[i].content = (char *)malloc(sizeof(char) * content_length);
        for (int j = 0; j < content_length; j++) {
            message_queue->messages[i].content[j] = 'a' + rand() % 26;
        }
    }
}

void populate_connection_pool(connection_pool_t *connection_pool) {
    // Generate random last seen activity times within a specified range
    int min_last_seen_activity = 10;
    int max_last_seen_activity = 50;
    for (int i = 0; i < connection_pool->connection_count; i++) {
        connection_pool->last_seen_activity[i] = rand() % (max_last_seen_activity - min_last_seen_activity + 1) + min_last_seen_activity;
    }
}

void free_data_structures(double_t *doubles, string_t *strings, message_queue_t *message_queues, network_node_t *network_nodes, connection_pool_t *connection_pools, logging_context_t *logging_context) {
    // Free double precision floating-point numbers
    for (int i = 0; i < NUM_DOUBLES; i++) {
        free(doubles[i].value);
    }

    // Free string byte codes
    for (int i = 0; i < NUM_STRINGS; i++) {
        free(strings[i].content);
    }

    // Free message queue
    for (int i = 0; i < NUM_MESSAGE_QUEUES; i++) {
        free(message_queues[i].messages);
    }

    // Free network nodes
    for (int i = 0; i < NUM_NETWORK_NODES; i++) {
        free(network_nodes[i].connected_nodes);
    }

    // Free connection pool
    for (int i = 0; i < NUM_CONNECTION_POOLS; i++) {
        free(connection_pools[i].last_seen_activity);
    }

    // Free logging context
    free(logging_context->user_id);
    free(logging_context->logged_in);
    free(logging_context->last_access_time);
}

void handle_memory_allocation_failure() {
    printf("Memory allocation failure occurred. Exiting...\n");
    exit(1);
}

void handle_error(char *message) {
    printf("%s\n", message);
    exit(1);
}

int main() {
    // Initialize data structures
    double_t doubles[NUM_DOUBLES];
    string_t strings[NUM_STRINGS];
    message_queue_t message_queues[NUM_MESSAGE_QUEUES];
    network_node_t network_nodes[NUM_NETWORK_NODES];
    connection_pool_t connection_pools[NUM_CONNECTION_POOLS];
    logging_context_t logging_context;
    initialize_data_structures(doubles, strings, message_queues, network_nodes, connection_pools, &logging_context);

    // Populate message queue with random content lengths within a specified range
    for (int i = 0; i < NUM_MESSAGE_QUEUES; i++) {
        populate_message_queue(&message_queues[i]);
    }

    // Populate connection pool with random last seen activity times within a specified range
    for (int i = 0; i < NUM_CONNECTION_POOLS; i++) {
        populate_connection_pool(&connection_pools[i]);
    }

    // Free data structures upon function exit
    free_data_structures(doubles, strings, message_queues, network_nodes, connection_pools, &logging_context);

    return 0;
}
