// Define the transaction structure
typedef struct {
    transaction_id_t id;
    currency_code_t currency;
    double amount;
    time_t timestamp;
    status_t status;
} transaction_t;

// Define the data structure for managing transactions
typedef struct {
    transaction_t *transactions;
    size_t capacity;
    pthread_mutex_t mutex;
} transaction_manager_t;

// Initialize the transaction manager with a given capacity
void initialize_transaction_manager(transaction_manager_t *manager, size_t capacity) {
    // Allocate memory for the transactions array
    manager->transactions = (transaction_t *)malloc(capacity * sizeof(transaction_t));
    if (!manager->transactions) {
        fprintf(stderr, "Failed to allocate memory for transactions\n");
        exit(1);
    }

    // Initialize the mutex and capacity fields
    manager->mutex = PTHREAD_MUTEX_INITIALIZER;
    manager->capacity = capacity;
}

// Add a new transaction to the manager
void add_transaction(transaction_manager_t *manager, transaction_id_t id, currency_code_t currency, double amount) {
    // Acquire the mutex before modifying the transactions array
    pthread_mutex_lock(&manager->mutex);

    // Check if the manager is full and needs to be resized
    if (manager->capacity == manager->transactions.size()) {
        resize_transaction_manager(manager, 2 * manager->capacity);
    }

    // Add the new transaction to the end of the array
    manager->transactions[manager->capacity++] = (transaction_t) { id, currency, amount, time(NULL), PENDING };

    // Release the mutex after modifying the transactions array
    pthread_mutex_unlock(&manager->mutex);
}

// Update the status of a transaction by its ID
void update_transaction_status(transaction_manager_t *manager, transaction_id_t id, status_t new_status) {
    // Acquire the mutex before modifying the transactions array
    pthread_mutex_lock(&manager->mutex);

    // Find the index of the transaction with the given ID
    size_t i = 0;
    for (i = 0; i < manager->capacity && manager->transactions[i].id != id; ++i) {}

    // Check if the transaction was found and update its status
    if (i < manager->capacity) {
        manager->transactions[i].status = new_status;
    } else {
        fprintf(stderr, "Transaction with ID %d not found\n", id);
    }

    // Release the mutex after modifying the transactions array
    pthread_mutex_unlock(&manager->mutex);
}

// Retrieve details of a transaction by its currency and amount
transaction_t *get_transaction(transaction_manager_t *manager, currency_code_t currency, double amount) {
    // Acquire the mutex before accessing the transactions array
    pthread_mutex_lock(&manager->mutex);

    // Find the index of the transaction with the given currency and amount
    size_t i = 0;
    for (i = 0; i < manager->capacity && !(manager->transactions[i].currency == currency && manager->transactions[i].amount == amount); ++i) {}

    // Check if the transaction was found and return its details
    if (i < manager->capacity) {
        return &manager->transactions[i];
    } else {
        fprintf(stderr, "Transaction with currency %d and amount %.2f not found\n", currency, amount);
        return NULL;
    }

    // Release the mutex after accessing the transactions array
    pthread_mutex_unlock(&manager->mutex);
}

// Periodically reconcile transactions against external records
void reconcile_transactions(transaction_manager_t *manager) {
    // Acquire the mutex before modifying the transactions array
    pthread_mutex_lock(&manager->mutex);

    // Iterate over all transactions and update their status based on external records
    for (size_t i = 0; i < manager->capacity; ++i) {
        transaction_t *transaction = &manager->transactions[i];
        if (external_record_exists(transaction->id)) {
            transaction->status = PROCESSED;
        } else {
            transaction->status = FAILED;
        }
    }

    // Release the mutex after modifying the transactions array
    pthread_mutex_unlock(&manager->mutex);
