// Resize the transaction manager to a new capacity
void resize_transaction_manager(transaction_manager_t *manager, size_t new_capacity) {
    // Allocate memory for the new transactions array
    transaction_t *new_transactions = (transaction_t *)malloc(new_capacity * sizeof(transaction_t));
    if (!new_transactions) {
        fprintf(stderr, "Failed to allocate memory for new transactions\n");
        exit(1);
    }

    // Copy the old transactions to the new array
    size_t i = 0;
    for (i = 0; i < manager->capacity && i < new_capacity; ++i) {
        new_transactions[i] = manager->transactions[i];
    }

    // Free the old transactions array and update the fields of the manager
    free(manager->transactions);
    manager->transactions = new_transactions;
    manager->capacity = new_capacity;
}

