    node *head = NULL, *tail = NULL;

    // Loop through each data point and create a record
    for (int i = 0; i < n; i++) {
        record *record = malloc(sizeof(record));
        if (record == NULL) {
            printf("Memory allocation failed\n");
            return;
        }
        record->key = rand() % (max - min + 1) + min;
        record->offset = i;
        record->timestamp = time(NULL);
        record->status = 'A';

        // Add the record to the linked list
        node *new_node = malloc(sizeof(node));
        new_node->record = record;
        new_node->next = NULL;
        if (head == NULL) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }

        // Add the record to the memory pool
        if (pool.capacity < n) {
            pool.records = realloc(pool.records, (pool.capacity + 1) * sizeof(record));
            if (pool.records == NULL) {
                printf("Memory allocation failed\n");
                return;
            }
            pool.capacity++;
        }
        memcpy(&pool.records[i], record, sizeof(record));
    }

    // Initialize the data points array
    for (int i = 0; i < n; i++) {
        data_points[i].value = rand() % (max - min + 1) + min;
        data_points[i].metric_threshold = 0.5;
        data_points[i].event_counter = 0;
        data_points[i].resource_identifier = 'A';
    }

    // Process and aggregate metrics
    for (int i = 0; i < n; i++) {
        record *record = &pool.records[i];
        data_point *data_point = &data_points[i];
        if (record->status == 'A') {
            data_point->value += record->key;
            data_point->metric_threshold += 0.5;
            data_point->event_counter++;
        } else {
            data_point->value -= record->key;
            data_point->metric_threshold -= 0.5;
            data_point->event_counter--;
        }
    }

    // Log all operations
    FILE *log = fopen("log.txt", "a");
    if (log == NULL) {
        printf("Error opening log file\n");
        return;
    }
    for (int i = 0; i < n; i++) {
        record *record = &pool.records[i];
        data_point *data_point = &data_points[i];
        fprintf(log, "Record %d: key=%d, offset=%ld, timestamp=%lf, status=%c\n", i, record->key, record->offset, record->timestamp, record->status);
        fprintf(log, "Data point %d: value=%d, metric_threshold=%.1lf, event_counter=%d, resource_identifier=%c\n", i, data_point->value, data_point->metric_threshold, data_point->event_counter, data_point->resource_identifier);
    }
    fclose(log);
}
