#define MEMORY_POOL_SIZE 1024 * 1024 // 1 MB
static char memory_pool[MEMORY_POOL_SIZE];
static size_t memory_pool_used = 0;

// Define function to allocate memory from the pool
void* alloc(size_t size) {
    if (memory_pool_used + size > MEMORY_POOL_SIZE) {
        return NULL;
    }
    void* ptr = &memory_pool[memory_pool_used];
    memory_pool_used += size;
    return ptr;
}

// Define function to free memory from the pool
void free(void* ptr) {
    if (ptr < &memory_pool[0] || ptr >= &memory_pool[MEMORY_POOL_SIZE]) {
        return;
    }
    size_t offset = ptr - &memory_pool[0];
    memory_pool_used -= offset;
}

