// Initialize the concurrent data structure
void initialize_transactions(int num_threads) {
    struct transaction_list *transaction_list = malloc(sizeof(struct transaction_list));
    if (!transaction_list) {
        perror("Failed to allocate memory for transaction list");
        exit(1);
    }
    transaction_list->mutex = PTHREAD_MUTEX_INITIALIZER;
    transaction_list->size = 0;
    transaction_list->transactions = NULL;
}

// Add a new transaction to the concurrent data structure
void add_transaction(struct transaction_list *transaction_list, int transaction_id, char currency_code[3], float amount, time_t timestamp, int status) {
    pthread_mutex_lock(&transaction_list->mutex);
    // Check if the transaction list is full
    if (transaction_list->size == transaction_list->capacity) {
        // Double the capacity of the transaction list
        transaction_list->capacity *= 2;
        transaction_list->transactions = realloc(transaction_list->transactions, transaction_list->capacity * sizeof(transaction_t));
        if (!transaction_list->transactions) {
            perror("Failed to allocate memory for transactions");
            exit(1);
        }
    }
    // Add the new transaction to the list
    transaction_list->transactions[transaction_list->size].transaction_id = transaction_id;
    strcpy(transaction_list->transactions[transaction_list->size].currency_code, currency_code);
    transaction_list->transactions[transaction_list->size].amount = amount;
    transaction_list->transactions[transaction_list->size].timestamp = timestamp;
    transaction_list->transactions[transaction_list->size].status = status;
    transaction_list->size++;
    pthread_mutex_unlock(&transaction_list->mutex);
}

// Update the status, amount, and timestamp of a transaction by its ID
void update_transaction(struct transaction_list *transaction_list, int transaction_id, int new_status, float new_amount, time_t new_timestamp) {
    pthread_mutex_lock(&transaction_list->mutex);
    // Find the index of the transaction with the given ID
    int i;
    for (i = 0; i < transaction_list->size; i++) {
        if (transaction_list->transactions[i].transaction_id == transaction_id) {
            break;
        }
    }
    // If the transaction was found, update its status, amount, and timestamp
    if (i < transaction_list->size) {
        transaction_list->transactions[i].status = new_status;
        transaction_list->transactions[i].amount = new_amount;
        transaction_list->transactions[i].timestamp = new_timestamp;
    } else {
        printf("Transaction with ID %d not found\n", transaction_id);
    }
    pthread_mutex_unlock(&transaction_list->mutex);
}

