    // Allocate memory for the grouped data structures
    grouped_data *grouped_transactions = malloc(num_groups * sizeof(grouped_data));
    if (!grouped_transactions) {
        perror("Failed to allocate memory for grouped transactions");
        exit(1);
    }
    // Initialize the grouped data structures
    for (int i = 0; i < num_groups; i++) {
        grouped_transactions[i].location[0] = '\0';
        grouped_transactions[i].average_temperature = 0.0f;
    }
    // Iterate over the transactions and group them by location name
    for (int i = 0; i < transaction_list->size; i++) {
        int j;
        for (j = 0; j < num_groups; j++) {
            if (strcmp(transaction_list->transactions[i].location, grouped_transactions[j].location) == 0) {
                break;
            }
        }
        // If the transaction is not already in a group, add it to a new group
