// Function to dynamically allocate memory for an array of sensor_reading structures
sensor_reading* get_sensor_readings(int num_readings) {
    // Allocate memory for the array of sensor_reading structures
    sensor_reading* readings = (sensor_reading*)malloc(num_readings * sizeof(sensor_reading));
    if (!readings) {
        // Handle error: out of memory or other allocation failure
        return NULL;
    }

    // Initialize the device identifier for each reading to a default value
    for (int i = 0; i < num_readings; i++) {
        readings[i].device_identifier = "default";
    }

    // Retrieve data from the sensor network API
    api_response* response = get_api_response();
    if (!response) {
        // Handle error: failed to retrieve data from API
        free(readings);
        return NULL;
    }

    // Check for API failures or partial responses
    if (response->status_code != 200 || response->num_readings == 0) {
        // Handle error: API failed or returned no readings
        free(readings);
        return NULL;
    }

    // Copy the sensor values and timestamps from the API response to the array of sensor_reading structures
    for (int i = 0; i < num_readings && i < response->num_readings; i++) {
        readings[i].timestamp = response->readings[i].timestamp;
        readings[i].sensor_value = response->readings[i].sensor_value;
    }

    // Set the device identifier for each reading to the default value if not available in the API response
    for (int i = 0; i < num_readings && i < response->num_readings; i++) {
        if (!response->readings[i].device_identifier) {
            readings[i].device_identifier = "default";
        } else {
            readings[i].device_identifier = strdup(response->readings[i].device_identifier);
        }
    }

    // Free the API response data
    free_api_response(response);

    // Set the smoothed sensor values based on the smoothing algorithm
    for (int i = 0; i < num_readings; i++) {
        if (SMOOTHING_ALGORITHM == 0) {
            readings[i].sensor_value = get_simple_average(readings, i);
        } else if (SMOOTHING_ALGORITHM == 1) {
            readings[i].sensor_value = get_exponential_smoothing(readings, i);
        }
    }

    return readings;
}

// Function to free all allocated memory for an array of sensor_reading structures
void free_sensor_readings(sensor_reading* readings) {
    if (!readings) {
        return;
    }

    // Free the device identifier strings
    for (int i = 0; i < num_readings; i++) {
        free(readings[i].device_identifier);
    }

    // Free the array of sensor_reading structures
    free(readings);
}

// Function to retrieve data from the sensor network API
api_response* get_api_response() {
    // Implement API retrieval logic here
    return NULL;
}

// Function to free all allocated memory for an api_response structure
void free_api_response(api_response* response) {
    if (!response) {
        return;
    }

    // Free the error message string
    free(response->error_message);

    // Free the array of sensor readings
    for (int i = 0; i < response->num_readings; i++) {
        free(response->readings[i].device_identifier);
    }
    free(response->readings);

    // Free the api_response structure
    free(response);
}

// Function to calculate a simple average of the sensor values in an array of sensor_reading structures
double get_simple_average(sensor_reading* readings, int num_readings) {
    double sum = 0;
    for (int i = 0; i < num_readings; i++) {
        sum += readings[i].sensor_value;
    }
    return sum / num_readings;
}

// Function to calculate an exponential smoothing of the sensor values in an array of sensor_reading structures
double get_exponential_smoothing(sensor_reading* readings, int num_readings) {
    double alpha = 0.5; // Exponential smoothing factor
    double sum = 0;
    for (int i = 0; i < num_readings; i++) {
        sum += alpha * readings[i].sensor_value + (1 - alpha) * sum;
    }
    return sum / num_readings;
}
