    int num_active_readings = 0;

    // Retrieve data from the API and store it in an array of sensor readings
    for (int i = 0; i < num_readings; i++) {
        // Allocate memory for a new sensor reading structure
        *(readings + i) = malloc(sizeof(sensor_reading));
        if (*(readings + i) == NULL) {
            // Handle error: unable to allocate memory for the sensor reading
