        (*(readings + i))->timestamp = timestamp;
        (*(readings + i))->value = value;
        (*(readings + i))->device_identifier = device_identifier;

        // Increment the number of active sensor readings
        num_active_readings++;
    }

    // Set the number of active sensor readings to the number of retrieved readings
    *num_active_readings = num_readings;

    return 0;
}

// Define a function to smooth the sensor values based on previous readings
void smooth_sensor_values(sensor_reading* readings, int num_readings) {
    // Initialize the number of active sensor readings to 0
    int num_active_readings = 0;

    // Iterate over the array of sensor readings and smooth the values based on previous readings
    for (int i = 0; i < num_readings; i++) {
        // Check if the current reading is a duplicate of a previous reading
        bool is_duplicate = false;
        for (int j = i - 1; j >= 0; j--) {
            if ((*(readings + i))->timestamp == (*(readings + j))->timestamp &&
                (*(readings + i))->device_identifier == (*(readings + j))->device_identifier) {
                is_duplicate = true;
                break;
