        }

        // If the current reading is a duplicate, set its value to the smoothed estimate based on previous readings
        if (is_duplicate) {
            (*(readings + i))->value = smooth_estimate((*(readings + i))->timestamp, (*(readings + i))->device_identifier);
        }
    }
}

