void init_device_identifier(sensor_reading* readings, int num_readings) {
    // Initialize the number of active sensor readings to 0
    int num_active_readings = 0;

    // Iterate over the array of sensor readings and initialize the device identifier with a default value or fetch it from the API response if available
    for (int i = 0; i < num_readings; i++) {
        // Check if the current reading has a valid device identifier
        if ((*(readings + i))->device_identifier == NULL) {
