void update_sensor_data(sensor_reading** readings, int* num_readings) {
    // Retrieve the number of active sensor readings from the API response
    int num_active_readings = get_num_active_readings();

    // Check if the number of active sensor readings has changed since the last update
    if (*num_readings != num_active_readings) {
        // Reallocate memory for the array of sensor readings to accommodate the new number of active readings
        *readings = realloc(*readings, sizeof(sensor_reading) * num_active_readings);
        if (*readings == NULL) {
            // Handle error: unable to reallocate memory for the array of sensor readings
            return;
        }

        // Initialize the new elements in the array of sensor readings with default values
        for (int i = *num_readings; i < num_active_readings; i++) {
            (*(readings + i))->timestamp = 0;
            (*(readings + i))->value = 0.0;
            (*(readings + i))->device_identifier = "default";
        }

        // Set the number of active sensor readings to the new number of active readings
        *num_readings = num_active_readings;
    }
}

// Define a function to track the number of active sensor readings and limit the maximum number of entries to prevent excessive memory usage
void track_active_sensor_readings(sensor_reading* readings, int num_readings) {
    // Initialize the number of active sensor readings to 0
    int num_active_readings = 0;

    // Iterate over the array of sensor readings and track the number of active sensor readings
    for (int i = 0; i < num_readings; i++) {
        if ((*(readings + i))->timestamp != 0) {
            num_active_readings++;
        }
    }

    // Limit the maximum number of entries to prevent excessive memory usage
    if (num_active_readings > MAX_NUM_READINGS) {
        num_active_readings = MAX_NUM_READINGS;
    }
}

// Define a function to free all allocated memory and ensure robust resource management
void cleanup(sensor_reading* readings, int num_readings) {
    // Iterate over the array of sensor readings and free each element's device identifier
    for (int i = 0; i < num_readings; i++) {
        if ((*(readings + i))->device_identifier != NULL) {
            free((*(readings + i))->device_identifier);
        }
    }

    // Free the array of sensor readings
    free(readings);
}
