#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the structure for storing document metadata
typedef struct {
    char *filename;
    size_t filesize;
    time_t creation_date;
    time_t last_modified_date;
    char **tags;
} DocumentMetadata;

// Define the structure for storing multiple arrays and structures
typedef struct {
    int num_documents;
    DocumentMetadata *documents;
} DocumentList;

// Define the function to dynamically allocate memory for and initialize multiple arrays and structures
void init_document_list(DocumentList *list) {
    // Allocate memory for the array of documents
    list->documents = (DocumentMetadata *)malloc(sizeof(DocumentMetadata) * 10);
    if (!list->documents) {
        printf("Error: Failed to allocate memory for document list\n");
        exit(1);
    }

    // Initialize the array of documents with default values
    for (int i = 0; i < 10; i++) {
        list->documents[i].filename = NULL;
        list->documents[i].filesize = 0;
        list->documents[i].creation_date = 0;
        list->documents[i].last_modified_date = 0;
        list->documents[i].tags = NULL;
