void remove_entry(data_structures_t *data, size_t index) {
    // Check if the index is valid
    if (index >= data->entries.num_entries) {
        printf("Invalid index\n");
        return;
    }

    // Remove the entry at the specified index and update the offset and key data structures accordingly
    for (size_t i = index; i < data->entries.num_entries - 1; i++) {
        data->entries.entries[i] = data->entries.entries[i + 1];
        data->offsets.offsets[i] = data->offsets.offsets[i + 1];
        data->keys.keys[i] = data->keys.keys[i + 1];
