#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int key;
    unsigned long timestamp;
} record;

// Define the hash table data structure
typedef struct {
    record **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t *lock;
} hash_table;

// Initialize the hash table with a given strategy
void init_hash_table(hash_table *ht, size_t capacity) {
    ht->records = (record **)malloc(sizeof(record *) * capacity);
    if (!ht->records) {
        perror("Failed to allocate memory for hash table");
        exit(1);
    }
    ht->capacity = capacity;
    ht->size = 0;
    ht->lock = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t));
    if (!ht->lock) {
        perror("Failed to allocate memory for lock");
        exit(1);
    }
    pthread_mutex_init(ht->lock, NULL);
}

// Add a new record to the hash table
void add_record(hash_table *ht, int key, unsigned long timestamp) {
    // Check if the key already exists in the hash table
    if (get_record(ht, key)) {
        printf("Key %d already exists in the hash table\n", key);
        return;
    }
    // Allocate memory for the new record
    record *new_record = (record *)malloc(sizeof(record));
    if (!new_record) {
        perror("Failed to allocate memory for new record");
        exit(1);
    }
    // Initialize the new record with the given key and timestamp
    new_record->key = key;
    new_record->timestamp = timestamp;
    // Lock the hash table to prevent concurrent access
    pthread_mutex_lock(ht->lock);
    // Check if the hash table needs to be resized
    if (ht->size == ht->capacity) {
        resize_hash_table(ht, 2 * ht->capacity);
    }
    // Add the new record to the hash table
    ht->records[ht->size++] = new_record;
    // Unlock the hash table
    pthread_mutex_unlock(ht->lock);
}

// Get a record from the hash table using its key
record *get_record(hash_table *ht, int key) {
    // Lock the hash table to prevent concurrent access
    pthread_mutex_lock(ht->lock);
    // Search for the record in the hash table
    for (size_t i = 0; i < ht->size; i++) {
        if (ht->records[i]->key == key) {
            // Unlock the hash table and return the found record
            pthread_mutex_unlock(ht->lock);
            return ht->records[i];
        }
    }
    // Unlock the hash table and return NULL if the record is not found
    pthread_mutex_unlock(ht->lock);
    return NULL;
}

// Update a record in the hash table using its key
void update_record(hash_table *ht, int key, unsigned long timestamp) {
    // Lock the hash table to prevent concurrent access
    pthread_mutex_lock(ht->lock);
    // Search for the record in the hash table
    for (size_t i = 0; i < ht->size; i++) {
        if (ht->records[i]->key == key) {
            // Update the timestamp of the found record
            ht->records[i]->timestamp = timestamp;
            break;
        }
    }
    // Unlock the hash table
    pthread_mutex_unlock(ht->lock);
}

// Delete a record from the hash table using its key
void delete_record(hash_table *ht, int key) {
    // Lock the hash table to prevent concurrent access
    pthread_mutex_lock(ht->lock);
    // Search for the record in the hash table
    for (size_t i = 0; i < ht->size; i++) {
        if (ht->records[i]->key == key) {
            // Remove the found record from the hash table
            free(ht->records[i]);
            ht->records[i] = NULL;
            break;
        }
    }
    // Unlock the hash table
    pthread_mutex_unlock(ht->lock);
}

// Resize the hash table to a given capacity
void resize_hash_table(hash_table *ht, size_t capacity) {
    // Allocate memory for the new records array
    record **new_records = (record **)malloc(sizeof(record *) * capacity);
    if (!new_records) {
        perror("Failed to allocate memory for new records");
        exit(1);
    }
    // Copy the old records to the new records array
    size_t i;
    for (i = 0; i < ht->size; i++) {
        new_records[i] = ht->records[i];
    }
    // Free the old records array
    free(ht->records);
    // Update the hash table with the new records array and capacity
    ht->records = new_records;
    ht->capacity = capacity;
}

// Periodically verify the integrity of the data structures
void verify_data_structures(hash_table *ht) {
    // Lock the hash table to prevent concurrent access
    pthread_mutex_lock(ht->lock);
    // Check if any records are missing or have incorrect timestamps
    for (size_t i = 0; i < ht->size; i++) {
        record *r = ht->records[i];
        if (!r || r->timestamp == 0) {
            printf("Record %d is missing or has incorrect timestamp\n", r->key);
        }
    }
    // Unlock the hash table
    pthread_mutex_unlock(ht->lock);
}

// Implement a memory management strategy to prevent leaks and ensure efficient deallocation of resources
void free_hash_table(hash_table *ht) {
    // Lock the hash table to prevent concurrent access
    pthread_mutex_lock(ht->lock);
    // Free the records array
    for (size_t i = 0; i < ht->size; i++) {
        free(ht->records[i]);
    }
    free(ht->records);
    // Free the lock
    pthread_mutex_destroy(ht->lock);
    free(ht->lock);
    // Unlock the hash table
    pthread_mutex_unlock(ht->lock);
}
