    // Calculate the total size of memory needed to allocate
    int total_size = sizeof(record) * offset + sizeof(int) * key + sizeof(char*) * (offset * key);

    // Allocate memory for the records and initialize it
    record* records = malloc(total_size);
    if (!records) {
        return NULL;
