    for (i = 0; i < offset; i++) {
        for (j = 0; j < key; j++) {
            records[i * key + j].string = malloc(sizeof(char) * (offset - i));
            if (!records[i * key + j].string) {
                return NULL;
            }
            records[i * key + j].value = rand() % (max_range - min_range + 1) + min_range;
        }
