        free(offsets);
        fclose(fp);
        return NULL;
    }
    sensorData* records = malloc(sizeof(sensorData) * 1000);
    if (records == NULL) {
        printf("Error: unable to allocate memory for records\n");
        free(offsets);
        free(keys);
        fclose(fp);
        return NULL;
    }

    // Initialize the linked list of sensor data
    sensorData* head = NULL;
    sensorData* current = NULL;

    // Read the file line by line and process each line
    char line[1024];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Parse the line to extract the reading and device ID
        double reading;
        char* device_id = strtok(line, ",");
        if (device_id == NULL) {
            printf("Error: unable to parse device ID\n");
            free(offsets);
            free(keys);
            free(records);
            fclose(fp);
            return NULL;
        }
        reading = atof(strtok(NULL, ","));
        if (reading == 0.0) {
