        // Generate a random value within the specified range for the short value
        short value = (short)((seed * 1000 + rand()) % (maxValue - minValue)) + minValue;

        // Allocate memory for the record structure and initialize it
        sensorData* newRecord = malloc(sizeof(sensorData));
        if (newRecord == NULL) {
            printf("Error: unable to allocate memory for record\n");
            free(offsets);
            free(keys);
            free(records);
            fclose(fp);
            return NULL;
        }
        newRecord->reading = reading;
        newRecord->device_id = strdup(device_id);
        newRecord->timestamp = time(NULL);

        // Add the record to the linked list
        if (head == NULL) {
            head = current = newRecord;
        } else {
            current->next = newRecord;
            current = newRecord;
        }
    }

    // Close the input file
    fclose(fp);

    // Free any unused memory in the arrays and return the linked list of sensor data
    free(offsets);
    free(keys);
    free(records);
    return head;
}
