// Define the structure for a record
typedef struct {
    float value;
    char buffer[256];
    struct log_entry* next;
} record;

// Define the structure for a log entry
typedef struct {
    int id;
    char message[256];
} log_entry;

void manage_memory(record** records, size_t num_records, size_t max_string_length) {
    // Allocate memory for the record structures
    *records = (record*)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        return;
    }

    // Initialize each record structure
    for (size_t i = 0; i < num_records; i++) {
        (*records)[i].value = 0.0f;
        memset((*records)[i].buffer, 0, max_string_length);
        (*records)[i].next = NULL;
    }

    // Populate the char buffers with user-provided strings
    for (size_t i = 0; i < num_records; i++) {
        printf("Enter a string for record %zu: ", i + 1);
        fgets((*records)[i].buffer, max_string_length, stdin);
    }

    // Insert and manage log entries within the linked list
    for (size_t i = 0; i < num_records; i++) {
        log_entry* entry = (log_entry*)malloc(sizeof(log_entry));
        if (entry == NULL) {
            printf("Error: Failed to allocate memory for log entry\n");
            return;
        }
        entry->id = i + 1;
        strcpy(entry->message, (*records)[i].buffer);
        entry->next = (*records)[i].next;
        (*records)[i].next = entry;
    }

    // Safely deallocate all allocated resources upon completion
    for (size_t i = 0; i < num_records; i++) {
        log_entry* current = (*records)[i].next;
        while (current != NULL) {
            log_entry* next = current->next;
            free(current);
            current = next;
        }
    }
    free(*records);
}
