    int size;
    struct node** buckets;
};

// Define the secondary index structure
struct secondary_index {
    int size;
    struct transaction** transactions;
};

// Function to initialize a linked list of transactions
void init_linked_list(struct node** head) {
    *head = NULL;
}

// Function to insert a new transaction into the linked list
void insert_transaction(struct node** head, struct transaction* data) {
    struct node* new_node = malloc(sizeof(struct node));
    new_node->data = data;
    new_node->next = *head;
    *head = new_node;
}

// Function to delete a transaction from the linked list
void delete_transaction(struct node** head, unsigned long id) {
    struct node* current = *head;
    struct node* previous = NULL;
    while (current != NULL && current->data->id != id) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
}

// Function to initialize a hash table for fast lookups based on IDs
void init_hash_table(struct hash_table* table, int size) {
    table->size = size;
    table->buckets = malloc(sizeof(struct node*) * size);
    memset(table->buckets, 0, sizeof(struct node*) * size);
}

// Function to insert a new transaction into the hash table
void insert_hash_table(struct hash_table* table, struct transaction* data) {
    int index = data->id % table->size;
    struct node* new_node = malloc(sizeof(struct node));
    new_node->data = data;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
}

// Function to delete a transaction from the hash table
void delete_hash_table(struct hash_table* table, unsigned long id) {
    int index = id % table->size;
    struct node* current = table->buckets[index];
    struct node* previous = NULL;
    while (current != NULL && current->data->id != id) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    if (previous == NULL) {
        table->buckets[index] = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
}

// Function to initialize a secondary index for transaction statuses
void init_secondary_index(struct secondary_index* index, int size) {
