        ids[i] = rand() % range + 1;
        temperatures[i] = (float)rand() / RAND_MAX * 100.0f;
        sensor_data[i].sensor_type = 'A' + (rand() % 26);
        sensor_data[i].sensor_id = rand() % range + 1;
        timestamps[i] = time(NULL);
