// Define the function to manage memory for an array of records
void manageRecords(Record** records, int numRecords, time_t startTime, int interval) {
    // Allocate memory for the array of records
    *records = (Record*)malloc(numRecords * sizeof(Record));
    if (*records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        return;
    }

    // Initialize each record with a timestamp and status
    for (int i = 0; i < numRecords; i++) {
        (*records)[i].timestamp = startTime + interval * i;
        strcpy((*records)[i].status, "operational");
    }

    // Update the status field with a sequence of state changes at regular intervals
    for (int i = 0; i < numRecords; i++) {
        if ((*records)[i].timestamp % interval == 0) {
            strcpy((*records)[i].status, "maintenance");
        } else if ((*records)[i].timestamp % (interval * 2) == 0) {
            strcpy((*records)[i].status, "error");
        } else {
            strcpy((*records)[i].status, "operational");
        }
    }

    // Handle concurrent access from multiple threads safely
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Deallocate memory for the array of records upon completion
    free(*records);
    *records = NULL;

    // Handle error handling for memory allocation failures
    if (errno == ENOMEM) {
        printf("Error: Failed to allocate memory for records\n");
    }
}
