void filter_and_aggregate(struct observation *observations, int num_observations) {
    // Iterate over each observation in the array
    for (int i = 0; i < num_observations; i++) {
        struct detail *current = observations[i].details;

        // Filter out low-confidence readings by checking the accuracy level of each detail node
        while (current != NULL) {
            if (current->accuracy < 75.0) { // If the accuracy level is less than 75 percent, filter it out
                struct detail *next = current->next;
                free(current);
                current = next;
            } else {
                current = current->next;
            }
        }

        // Aggregate the temperature readings by summing up all the valid values
        double total_temperature = 0.0;
        struct detail *current = observations[i].details;
        while (current != NULL) {
            if (current->accuracy >= 75.0) { // If the accuracy level is greater than or equal to 75 percent, include it in the aggregation
                total_temperature += current->temperature;
            }
            current = current->next;
        }

        // Print the aggregated temperature reading and the number of valid readings
        printf("Observation %d: Average temperature = %.2f, Number of valid readings = %d\n", i + 1, total_temperature / num_details, num_details);
    }
}

