        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Allocate memory for the entries array
    entry_t *entries = (entry_t *)malloc(num_records * sizeof(entry_t));
    if (!entries) {
        printf("Error: Failed to allocate memory for entries\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the offsets array
    for (int i = 0; i < num_records; i++) {
        offsets[i].key = i;
        offsets[i].offset = -1;
    }

    // Initialize the keys array
    for (int i = 0; i < num_records; i++) {
        keys[i].value = i;
        keys[i].str = malloc(max_str_len * sizeof(char));
        if (!keys[i].str) {
            printf("Error: Failed to allocate memory for key %d\n", i);
            free(offsets);
            free(keys);
            return;
        }
    }

    // Initialize the entries array
    for (int i = 0; i < num_records; i++) {
        entries[i].record = malloc(sizeof(record_t));
        if (!entries[i].record) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            free(offsets);
            free(keys);
            return;
        }
        entries[i].log = malloc(sizeof(log_entry_t));
        if (!entries[i].log) {
            printf("Error: Failed to allocate memory for log %d\n", i);
            free(offsets);
            free(keys);
            return;
        }
    }

    // Initialize the record values and string pointers
    for (int i = 0; i < num_records; i++) {
        entries[i].record->value = i;
        entries[i].record->str = keys[i].str;
        sprintf(entries[i].record->str, "Record %d", i);
    }

    // Initialize the log entries
    for (int i = 0; i < num_records; i++) {
        entries[i].log->timestamp = time(NULL);
        entries[i].log->operation = 1;
        entries[i].log->affected_entries = 1;
    }

    // Initialize the offset array
    for (int i = 0; i < num_records; i++) {
        offsets[i].offset = -1;
    }

    // Populate the offset array with valid offsets
    for (int i = 0; i < num_records; i++) {
        if (offsets[i].offset == -1) {
            int j = i + 1;
            while (j < num_records && offsets[j].offset != -1) {
                j++;
            }
            if (j < num_records) {
                offsets[i].offset = j;
                offsets[j].offset = i;
            } else {
                break;
            }
        }
    }

    // Print the record values and string pointers
    for (int i = 0; i < num_records; i++) {
        printf("Record %d: Value=%f, String=%s\n", i, entries[i].record->value, entries[i].record->str);
    }

    // Print the log entries
    for (int i = 0; i < num_records; i++) {
        printf("Log Entry %d: Timestamp=%ld, Operation=%d, Affected Entries=%d\n", i, entries[i].log->timestamp, entries[i].log->operation, entries[i].log->affected_entries);
    }

    // Print the offset array
    for (int i = 0; i < num_records; i++) {
        printf("Offset %d: Key=%d, Offset=%d\n", i, offsets[i].key, offsets[i].offset);
    }

    // Print the keys array
    for (int i = 0; i < num_records; i++) {
        printf("Key %d: Value=%d, String=%s\n", i, keys[i].value, keys[i].str);
    }

    // Free the memory allocated for the offsets array
    free(offsets);

    // Free the memory allocated for the keys array
    for (int i = 0; i < num_records; i++) {
        free(keys[i].str);
    }
    free(keys);

    // Free the memory allocated for the entries array
    for (int i = 0; i < num_records; i++) {
        free(entries[i].record);
        free(entries[i].log);
    }
    free(entries);
}
