char* generate_random_string(const char* character_set, int length) {
    // Initialize the random seed
    srand(time(NULL));

    // Generate a random string of the specified length
    char *string = malloc(length + 1);
    for (int i = 0; i < length; i++) {
        int index = rand() % strlen(character_set);
        string[i] = character_set[index];
    }
    string[length] = '\0';

    return string;
}

// Function to hash a given password using the default hashing algorithm
char* hash_password(const char* password) {
