    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();

    // Set the hashing algorithm and initialize the context
    EVP_DigestInit_ex(mdctx, ENCRYPTION_ALGORITHM, NULL);

    // Hash the password and return the result
    char *hash = malloc(EVP_MD_size(ENCRYPTION_ALGORITHM));
    EVP_DigestUpdate(mdctx, password, strlen(password));
    EVP_DigestFinal_ex(mdctx, hash, NULL);

    return hash;
}

