#include <pthread.h>

// Define the record structure
typedef struct {
    float value;
    time_t timestamp;
    char status[10];
} Record;

// Define the array of records
Record* records = NULL;

// Define the number of records to allocate
int num_records = 0;

// Define the start time for the timestamps
time_t start_time = 0;

// Define the interval between timestamps
double interval = 0.0;

// Define the status sequence
char* status_seq[] = {"operational", "maintenance", "error"};

// Define the number of statuses in the sequence
int num_statuses = sizeof(status_seq) / sizeof(status_seq[0]);

// Define the current status index
int curr_status_idx = 0;

// Define the mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate and initialize memory for the array of records
void init_records(int num_records, time_t start_time, double interval) {
    // Allocate memory for the array of records
    records = (Record*) malloc(num_records * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        exit(1);
    }

    // Initialize the timestamp for each record
    time_t curr_time = start_time;
    for (int i = 0; i < num_records; i++) {
        records[i].timestamp = curr_time;
        curr_time += interval;
    }

    // Initialize the status for each record
    for (int i = 0; i < num_records; i++) {
        strcpy(records[i].status, status_seq[curr_status_idx]);
    }
}

// Function to update the status of a record at regular intervals
void update_status(Record* record) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&mutex);

    // Update the status of the record
    strcpy(record->status, status_seq[curr_status_idx]);

    // Increment the current status index
    curr_status_idx = (curr_status_idx + 1) % num_statuses;

    // Release the mutex for thread safety
    pthread_mutex_unlock(&mutex);
}

// Function to handle memory allocation failures
void handle_memory_allocation_failure() {
    printf("Error: Failed to allocate memory\n");
    exit(1);
}

// Function to deallocate the array of records
void free_records() {
    // Deallocate the memory for the array of records
    if (records) {
        free(records);
        records = NULL;
    }
}

// Main function that manages memory for an array of 'record' structures
int main(int argc, char* argv[]) {
    // Check the number of arguments
    if (argc != 4) {
        printf("Usage: %s <num_records> <start_time> <interval>\n", argv[0]);
        return 1;
    }

    // Parse the command-line arguments
    num_records = atoi(argv[1]);
    start_time = atol(argv[2]);
    interval = atof(argv[3]);

    // Initialize the array of records
    init_records(num_records, start_time, interval);

    // Update the status of each record at regular intervals
    for (int i = 0; i < num_records; i++) {
        update_status(&records[i]);
    }

    // Handle memory allocation failures
    if (!records) {
        handle_memory_allocation_failure();
    }

    // Deallocate the array of records
    free_records();

    return 0;
}
