#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>

// Define the record structure
typedef struct {
    char *data;
    short value;
} record_t;

// Define the entry structure for the concurrent data structure
typedef struct {
    int key;
    long timestamp;
    int priority;
} entry_t;

// Define the memory allocation strategy for the record structures
#define MEMORY_ALLOCATION_STRATEGY 1024 // in bytes

// Define the maximum age threshold for removing entries
#define MAX_AGE_THRESHOLD 3600 // in seconds

// Define the predefined memory usage threshold
#define PREDEFINED_MEMORY_USAGE_THRESHOLD 80 // in percentage

// Define the concurrent data structure for managing key-value pairs, timestamps, and priority levels
static entry_t *entries;

// Define the array of long type offsets
static long *offsets;

// Define the array of int type keys
static int *keys;

// Define the contiguous block of memory for record structures
static record_t *records;

// Define the number of records in the data structure
static int num_records = 0;

// Define the number of entries in the concurrent data structure
static int num_entries = 0;

// Define the maximum number of records that can be stored in the data structure
#define MAX_RECORDS 1000000

// Define the maximum number of keys that can be stored in the concurrent data structure
#define MAX_KEYS 1000000

// Define the memory usage threshold for triggering a cleanup mechanism
static int memory_usage = 0;

// Define the periodic cleanup mechanism
static void cleanup() {
    // Remove entries older than the maximum age threshold
    for (int i = 0; i < num_entries; i++) {
        if (entries[i].timestamp < time(NULL) - MAX_AGE_THRESHOLD) {
            removeEntry(i);
            i--;
        }
    }
}

// Define the function for reading sensor data from a compressed binary file, line by line
static void readSensorData(char *filepath) {
    // Open the file in read-only mode
    int fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    // Read the file line by line
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fd)) != -1) {
        // Parse the line and extract the data and value
        char *data = strtok(line, ",");
        short value = atoi(strtok(NULL, "\n"));

        // Add the record to the data structure
        addRecord(data, value);
    }

    // Close the file
    close(fd);
}

// Define the function for adding a record to the data structure
static void addRecord(char *data, short value) {
    // Check if the data structure is full
    if (num_records == MAX_RECORDS) {
        printf("Data structure is full. Removing oldest entry.\n");
        removeEntry(0);
    }

    // Allocate memory for the record
    record_t *record = malloc(sizeof(record_t));
    if (record == NULL) {
        perror("Error allocating memory for record");
        exit(EXIT_FAILURE);
    }

    // Initialize the record with random values between a given minimum and maximum range, ensuring no duplicates
    int min = 0;
    int max = 10000;
    while (true) {
        record->value = rand() % (max - min + 1) + min;
        if (!containsValue(record->value)) {
            break;
        }
    }

    // Allocate memory for the data string and copy the data
    int len = strlen(data);
    record->data = malloc(len + 1);
    memcpy(record->data, data, len + 1);

    // Add the record to the data structure
    records[num_records++] = *record;
}

// Define the function for removing an entry from the data structure
static void removeEntry(int index) {
    // Check if the index is valid
    if (index < 0 || index >= num_entries) {
        printf("Invalid index. Cannot remove entry.\n");
        return;
    }

    // Remove the entry from the concurrent data structure
    removeKey(entries[index].key);

    // Free the memory for the record
    free(records[index].data);
    records[index] = (record_t){NULL, 0};
}

// Define the function for updating a record in the data structure
static void updateRecord(int index, char *data, short value) {
    // Check if the index is valid
    if (index < 0 || index >= num_records) {
        printf("Invalid index. Cannot update record.\n");
        return;
    }

    // Update the record in the data structure
    records[index].data = malloc(strlen(data) + 1);
    memcpy(records[index].data, data, strlen(data) + 1);
    records[index].value = value;
}

// Define the function for retrieving a record from the data structure
static void retrieveRecord(int index) {
    // Check if the index is valid
    if (index < 0 || index >= num_records) {
        printf("Invalid index. Cannot retrieve record.\n");
        return;
    }

    // Print the record
    printf("%s, %d\n", records[index].data, records[index].value);
}

// Define the function for computing the average of the last two fields and appending this average to the end of the line
static void computeAverage(char *line) {
    // Parse the line and extract the data and value
    char *data = strtok(line, ",");
    short value = atoi(strtok(NULL, "\n"));

    // Compute the average of the last two fields
    int average = (value + records[num_records - 2].value) / 2;

    // Append the average to the end of the line
    printf("%s, %d\n", data, average);
}

// Define the function for handling updates, deletions, and retrievals in the concurrent data structure
static void handleUpdates(int key, long timestamp, int priority) {
    // Check if the key is valid
    if (key < 0 || key >= MAX_KEYS) {
        printf("Invalid key. Cannot update entry.\n");
        return;
    }

    // Update or insert the entry in the concurrent data structure
    if (containsKey(key)) {
        updateEntry(key, timestamp, priority);
    } else {
        addEntry(key, timestamp, priority);
    }
}

// Define the function for updating an entry in the concurrent data structure
static void updateEntry(int key, long timestamp, int priority) {
    // Check if the index is valid
    if (index < 0 || index >= num_entries) {
        printf("Invalid index. Cannot update entry.\n");
        return;
    }

    // Update the entry in the concurrent data structure
    entries[index].key = key;
    entries[index].timestamp = timestamp;
    entries[index].priority = priority;
}

// Define the function for adding an entry to the concurrent data structure
static void addEntry(int key, long timestamp, int priority) {
    // Check if the key is valid
    if (key < 0 || key >= MAX_KEYS) {
        printf("Invalid key. Cannot add entry.\n");
        return;
    }

    // Check if the data structure is full
    if (num_entries == MAX_ENTRIES) {
        printf("Data structure is full. Removing oldest entry.\n");
        removeEntry(0);
    }

    // Add the entry to the concurrent data structure
    entries[num_entries++] = (entry_t){key, timestamp, priority};
}

// Define the function for removing a key from the concurrent data structure
static void removeKey(int key) {
    // Check if the key is valid
    if (key < 0 || key >= MAX_KEYS) {
        printf("Invalid key. Cannot remove entry.\n");
        return;
    }

    // Remove the entry from the concurrent data structure
    for (int i = 0; i < num_entries; i++) {
        if (entries[i].key == key) {
            removeEntry(i);
            i--;
        }
    }
}

// Define the function for checking if a value is contained in the data structure
static bool containsValue(short value) {
    // Check if the value is contained in the data structure
    for (int i = 0; i < num_records; i++) {
        if (records[i].value == value) {
            return true;
        }
    }
    return false;
}

// Define the function for checking if a key is contained in the concurrent data structure
static bool containsKey(int key) {
    // Check if the key is contained in the concurrent data structure
    for (int i = 0; i < num_entries; i++) {
        if (entries[i].key == key) {
            return true;
        }
    }
    return false;
}

// Define the function for initializing the memory allocation strategy for the record structures
static void initializeMemoryAllocationStrategy() {
    // Allocate memory for the record structures
    records = malloc(MEMORY_ALLOCATION_STRATEGY * sizeof(record_t));
    if (records == NULL) {
        perror("Error allocating memory for record structures");
        exit(EXIT_FAILURE);
    }
}

// Define the function for initializing the concurrent data structure
