    // Allocate memory for the entries array
    entries = malloc(MAX_ENTRIES * sizeof(entry_t));
    if (entries == NULL) {
        perror("Error allocating memory for entries");
        exit(EXIT_FAILURE);
    }
}

// Define the function for initializing the array of long type offsets
static void initializeOffsets() {
    // Allocate memory for the offsets array
    offsets = malloc(MAX_RECORDS * sizeof(long));
    if (offsets == NULL) {
        perror("Error allocating memory for offsets");
        exit(EXIT_FAILURE);
    }
}

// Define the function for initializing the array of int type keys
