// Define the data structures
struct node {
    float value;
    int index;
    struct child* children;
};

struct child {
    char* string;
    unsigned int id;
};

struct parent {
    struct node** nodes;
    size_t num_nodes;
    pthread_mutex_t mutex;
};

// Define the functions for managing the data structures
void init_parent(struct parent* parent) {
    // Initialize the parent structure with a null pointer array and 0 as the number of nodes
    parent->nodes = NULL;
    parent->num_nodes = 0;

    // Initialize the mutex for thread safety
    pthread_mutex_init(&parent->mutex, NULL);
}

void add_node(struct parent* parent, float value, int index) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&parent->mutex);

    // Allocate memory for a new node and initialize its values
    struct node* new_node = malloc(sizeof(struct node));
    new_node->value = value;
    new_node->index = index;
    new_node->children = NULL;

    // Reallocate the nodes array to accommodate the new node
    parent->nodes = realloc(parent->nodes, (parent->num_nodes + 1) * sizeof(struct node*));
    parent->nodes[parent->num_nodes] = new_node;
    parent->num_nodes++;

    // Unlock the mutex
    pthread_mutex_unlock(&parent->mutex);
}

void remove_node(struct parent* parent, int index) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&parent->mutex);

    // Find the node at the specified index and free its memory
    struct node* node = parent->nodes[index];
    free(node);

    // Reallocate the nodes array to remove the freed node
    parent->nodes = realloc(parent->nodes, (parent->num_nodes - 1) * sizeof(struct node*));
    parent->num_nodes--;

    // Unlock the mutex
    pthread_mutex_unlock(&parent->mutex);
}

void iterate_nodes(struct parent* parent, void (*callback)(struct node*)) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&parent->mutex);

    // Iterate over all nodes and call the callback function for each one
    for (size_t i = 0; i < parent->num_nodes; i++) {
        struct node* node = parent->nodes[i];
        callback(node);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&parent->mutex);
}

// Define a function to initialize the data structures with random values and strings within specified ranges
void init_data_structures(struct parent* parent, float value_min, float value_max, int index_min, int index_max, char* string_prefix, unsigned int id_min, unsigned int id_max) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&parent->mutex);

    // Initialize the nodes array with random values and strings within specified ranges
    for (size_t i = 0; i < parent->num_nodes; i++) {
        struct node* node = parent->nodes[i];
        node->value = value_min + ((float)rand() / RAND_MAX) * (value_max - value_min);
        node->index = index_min + ((int)rand() % (index_max - index_min));
        node->children = malloc(sizeof(struct child*) * 2);
        for (size_t j = 0; j < 2; j++) {
            struct child* child = malloc(sizeof(struct child));
            child->string = malloc(strlen(string_prefix) + 1);
            strcpy(child->string, string_prefix);
            child->id = id_min + ((unsigned int)rand() % (id_max - id_min));
            node->children[j] = child;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&parent->mutex);
}
