struct HashTable {
    struct Record** records;
    size_t capacity;
    size_t used;
};

void hash_table_init(struct HashTable* table, size_t capacity) {
    table->records = malloc(capacity * sizeof(struct Record*));
    memset(table->records, 0, capacity * sizeof(struct Record*));
    table->capacity = capacity;
    table->used = 0;
}

void hash_table_destroy(struct HashTable* table) {
    free(table->records);
}

int hash_table_insert(struct HashTable* table, struct Record* record) {
    size_t index = record->value % table->capacity;
    while (table->records[index] != NULL && table->records[index]->value != record->value) {
        index = (index + 1) % table->capacity;
    }
    if (table->records[index] == NULL) {
        table->used++;
    }
    table->records[index] = record;
    return 0;
}

struct Record* hash_table_find(struct HashTable* table, float value) {
    size_t index = value % table->capacity;
    while (table->records[index] != NULL && table->records[index]->value != value) {
        index = (index + 1) % table->capacity;
    }
    return table->records[index];
}

