#include <pthread.h>

// Define the data structure for an event
typedef struct Event {
    char* message;
    struct Event* next;
} Event;

// Define the data structure for the linked list of events
typedef struct EventList {
    Event* head;
    Event* tail;
} EventList;

// Define the function to dynamically allocate memory for and initialize the data structure
int init_events(int num_events, int message_len, EventList** event_list) {
    // Allocate memory for the arrays of timestamps and event types
    long* timestamps = (long*)malloc(num_events * sizeof(long));
    if (!timestamps) {
        return -1;
    }
    int* event_types = (int*)malloc(num_events * sizeof(int));
    if (!event_types) {
        free(timestamps);
        return -1;
    }

    // Allocate memory for the linked list of events
    EventList* event_list_head = (EventList*)malloc(sizeof(EventList));
    if (!event_list_head) {
        free(timestamps);
        free(event_types);
        return -1;
    }
    EventList* event_list_tail = (EventList*)malloc(sizeof(EventList));
    if (!event_list_tail) {
        free(timestamps);
        free(event_types);
        free(event_list_head);
        return -1;
    }

    // Initialize the linked list of events
    Event* event = (Event*)malloc(sizeof(Event));
    if (!event) {
        free(timestamps);
        free(event_types);
        free(event_list_head);
        free(event_list_tail);
        return -1;
    }
    event->message = (char*)malloc(message_len * sizeof(char));
    if (!event->message) {
        free(timestamps);
        free(event_types);
        free(event_list_head);
        free(event_list_tail);
        free(event);
        return -1;
    }
    event->next = NULL;
    event_list_head->head = event;
    event_list_tail->tail = event;

    // Initialize the arrays of timestamps and event types
    for (int i = 0; i < num_events; i++) {
        timestamps[i] = 0;
        event_types[i] = 0;
    }

    // Validate that all allocated memory has been correctly initialized
    if (!timestamps || !event_types || !event_list_head || !event_list_tail || !event) {
        free(timestamps);
        free(event_types);
        free(event_list_head);
        free(event_list_tail);
        free(event);
        return -1;
    }

    // Log memory usage statistics for each allocation
    printf("Memory usage: %lu bytes\n", sizeof(long) * num_events + sizeof(int) * num_events + sizeof(EventList) + sizeof(Event));

    // Set the output parameter to point to the initialized data structure
    *event_list = event_list_head;

    return 0;
}

// Define the function to add a new event to the linked list without reallocating the entire data structure
void add_event(EventList* event_list, long timestamp, int event_type, char* message) {
    // Allocate memory for the new event node
    Event* new_event = (Event*)malloc(sizeof(Event));
    if (!new_event) {
        return;
    }
    new_event->message = (char*)malloc(strlen(message) + 1);
    if (!new_event->message) {
        free(new_event);
        return;
    }
    strcpy(new_event->message, message);
    new_event->next = NULL;

    // Add the new event to the linked list
    pthread_mutex_lock(&event_list->tail->mutex);
    event_list->tail->next = new_event;
    event_list->tail = new_event;
    pthread_mutex_unlock(&event_list->tail->mutex);
}

// Define the function to serialize and deserialize the data structure to disk
void serialize(EventList* event_list, FILE* file) {
    // Write the number of events to the file
    fwrite(&event_list->head->next, sizeof(int), 1, file);

    // Write each event to the file
    Event* current = event_list->head;
    while (current != NULL) {
        fwrite(current->message, strlen(current->message) + 1, 1, file);
        current = current->next;
    }
}

void deserialize(EventList** event_list, FILE* file) {
    // Read the number of events from the file
    int num_events;
    fread(&num_events, sizeof(int), 1, file);

    // Allocate memory for the arrays of timestamps and event types
    long* timestamps = (long*)malloc(num_events * sizeof(long));
    if (!timestamps) {
        return;
    }
    int* event_types = (int*)malloc(num_events * sizeof(int));
    if (!event_types) {
        free(timestamps);
        return;
    }

    // Allocate memory for the linked list of events
    EventList* event_list_head = (EventList*)malloc(sizeof(EventList));
    if (!event_list_head) {
        free(timestamps);
        free(event_types);
        return;
    }
    EventList* event_list_tail = (EventList*)malloc(sizeof(EventList));
    if (!event_list_tail) {
        free(timestamps);
        free(event_types);
        free(event_list_head);
        return;
    }

    // Initialize the linked list of events
    Event* event = (Event*)malloc(sizeof(Event));
    if (!event) {
        free(timestamps);
        free(event_types);
        free(event_list_head);
        free(event_list_tail);
        return;
    }
    event->message = (char*)malloc(strlen(message) + 1);
    if (!event->message) {
        free(timestamps);
        free(event_types);
        free(event_list_head);
        free(event_list_tail);
        free(event);
        return;
    }
    event->next = NULL;
    event_list_head->head = event;
    event_list_tail->tail = event;

    // Read each event from the file and add it to the linked list
    for (int i = 0; i < num_events; i++) {
        fread(event->message, strlen(event->message) + 1, 1, file);
        add_event(event_list_tail, timestamps[i], event_types[i], event->message);
    }

    // Set the output parameter to point to the initialized data structure
    *event_list = event_list_head;
}

// Define the function to periodically check and report the total memory usage of the data structure and its components
void check_memory_usage(EventList* event_list) {
    // Calculate the total memory usage of the linked list
    long total_memory = 0;
    Event* current = event_list->head;
    while (current != NULL) {
        total_memory += sizeof(Event);
        if (current->message != NULL) {
            total_memory += strlen(current->message) + 1;
        }
        current = current->next;
    }

    // Calculate the total memory usage of the arrays of timestamps and event types
    total_memory += sizeof(long) * num_events;
    total_memory += sizeof(int) * num_events;

    // Print a message indicating the total memory usage
    printf("Total memory usage: %lu bytes\n", total_memory);
}
