    if (event_list->tail == NULL || event_list->tail->next != NULL) {
        return;
    }

    // Allocate memory for the new event node
    EventNode* node = (EventNode*)malloc(sizeof(EventNode));
    if (!node) {
        return;
    }
    node->message = (char*)malloc(strlen(message) + 1);
    if (!node->message) {
        free(node);
        return;
