    // Add the new event to the linked list
    event_list->tail->next = node;
    event_list->tail = node;

    // Update the timestamp and event type arrays
    if (timestamp_event_arrays->num_events < timestamp_event_arrays->capacity) {
        timestamp_event_arrays->timestamps[timestamp_event_arrays->num_events] = timestamp;
        timestamp_event_arrays->event_types[timestamp_event_arrays->num_events] = event_type;
        timestamp_event_arrays->num_events++;
