#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>
#include <stdbool.h>

// Define the record structure
typedef struct {
    double value;
} Record;

// Define the data structures to hold the records
typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t capacity;
    size_t count;
} DataStructures;

// Function to initialize the data structures with random values within a specified range
void initDataStructures(DataStructures *ds, long min, long max) {
    // Allocate memory for the offsets array
    ds->offsets = (long *)malloc(sizeof(long) * ds->capacity);
    assert(ds->offsets != NULL);

    // Initialize the offsets with random values within the specified range
    for (size_t i = 0; i < ds->count; i++) {
        ds->offsets[i] = rand() % (max - min + 1) + min;
    }

    // Allocate memory for the keys array
    ds->keys = (int *)malloc(sizeof(int) * ds->capacity);
    assert(ds->keys != NULL);

    // Initialize the keys with random values within the specified range
    for (size_t i = 0; i < ds->count; i++) {
        ds->keys[i] = rand() % (max - min + 1) + min;
    }

    // Allocate memory for the records array
    ds->records = (Record *)malloc(sizeof(Record) * ds->capacity);
    assert(ds->records != NULL);

    // Initialize the records with random values within the specified range
    for (size_t i = 0; i < ds->count; i++) {
        ds->records[i].value = rand() % (max - min + 1) + min;
    }
}

// Function to sort the records based on their double values in either ascending or descending order
void sortRecords(DataStructures *ds, bool ascending) {
    // Define a comparison function for sorting the records
    int compare(const void *a, const void *b) {
        Record *ra = (Record *)a;
        Record *rb = (Record *)b;
        if (ascending) {
            return ra->value < rb->value ? -1 : 1;
        } else {
            return ra->value > rb->value ? -1 : 1;
        }
    }

    // Sort the records using the comparison function
    qsort(ds->records, ds->count, sizeof(Record), compare);
}

// Function to add a new record to the data structures
void addRecord(DataStructures *ds, long offset, int key, double value) {
    // Check if the data structures need to be resized
    if (ds->count == ds->capacity) {
        // Double the capacity of the data structures
        ds->capacity *= 2;

        // Reallocate memory for the offsets array
        long *new_offsets = (long *)realloc(ds->offsets, sizeof(long) * ds->capacity);
        assert(new_offsets != NULL);
        ds->offsets = new_offsets;

        // Reallocate memory for the keys array
        int *new_keys = (int *)realloc(ds->keys, sizeof(int) * ds->capacity);
        assert(new_keys != NULL);
        ds->keys = new_keys;

        // Reallocate memory for the records array
        Record *new_records = (Record *)realloc(ds->records, sizeof(Record) * ds->capacity);
        assert(new_records != NULL);
        ds->records = new_records;
    }

    // Add the new record to the data structures
    ds->offsets[ds->count] = offset;
    ds->keys[ds->count] = key;
    ds->records[ds->count].value = value;
    ds->count++;
}

// Function to remove a specific record from the data structures by key value
void removeRecord(DataStructures *ds, int key) {
    // Find the index of the record with the specified key
    size_t i = 0;
    while (i < ds->count && ds->keys[i] != key) {
        i++;
    }

    // Check if the record was found
    if (i == ds->count) {
        return;
    }

    // Remove the record from the data structures
    for (size_t j = i; j < ds->count - 1; j++) {
        ds->offsets[j] = ds->offsets[j + 1];
        ds->keys[j] = ds->keys[j + 1];
        ds->records[j].value = ds->records[j + 1].value;
    }
    ds->count--;
}

// Function to free the memory allocated for the data structures
void freeDataStructures(DataStructures *ds) {
    // Free the memory allocated for the offsets array
    free(ds->offsets);

    // Free the memory allocated for the keys array
    free(ds->keys);

    // Free the memory allocated for the records array
    free(ds->records);
}
