// Function to manage a dynamic array of records
Record** allocateRecords(int maxSize) {
    // Allocate memory for the array of pointers to records
    Record** records = (Record**)malloc(maxSize * sizeof(Record*));
    if (!records) {
        printf("Error: Failed to allocate memory for record array\n");
        return NULL;
    }

    // Initialize each record with a unique identifier, integer value, and character string
    srand(time(NULL));
    for (int i = 0; i < maxSize; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            return NULL;
        }

        // Generate a unique identifier combining letters and numbers
        int id = rand() % 10000 + 1000;
        while (idExists(records, maxSize, id)) {
            id = rand() % 10000 + 1000;
        }
        records[i]->id = id;

        // Initialize the integer value to a random value within a specified range
        int value = rand() % 100 + 1;
        while (valueExists(records, maxSize, value)) {
            value = rand() % 100 + 1;
        }
        records[i]->value = value;

        // Initialize the character string to a random sequence of uppercase letters and digits
        char* string = (char*)malloc(51 * sizeof(char));
        if (!string) {
            printf("Error: Failed to allocate memory for record %d's string\n", i);
            return NULL;
        }
        for (int j = 0; j < 50; j++) {
            string[j] = rand() % 26 + 'A';
            if (rand() % 2 == 0) {
                string[j] += rand() % 10 + '0';
            }
        }
        records[i]->string = string;

        // Initialize the offset to a unique positive integer
        int offset = rand() % maxSize + 1;
        while (offsetExists(records, maxSize, offset)) {
            offset = rand() % maxSize + 1;
        }
        records[i]->offset = offset;
    }

    // Return a pointer to the array of pointers to records and their total count
    return records;
}

// Function to free memory allocated for the record array
void freeRecords(Record** records, int maxSize) {
