typedef struct HashTable {
    size_t capacity;
    size_t size;
    size_t max_table_size;
    void** buckets;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity, size_t max_table_size) {
    HashTable* table = allocate_memory(sizeof(HashTable));
    table->capacity = initial_capacity;
    table->size = 0;
    table->max_table_size = max_table_size;
    table->buckets = allocate_memory(initial_capacity * sizeof(void*));
    return table;
}

void destroy_hash_table(HashTable* table) {
    deallocate_memory(table->buckets);
    deallocate_memory(table);
}

void resize_hash_table(HashTable* table, size_t new_capacity) {
    void** new_buckets = allocate_memory(new_capacity * sizeof(void*));
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->buckets[i] != NULL) {
            size_t index = hash_function(table->buckets[i]);
            while (new_buckets[index] != NULL) {
                index++;
                if (index == new_capacity) {
                    index = 0;
                }
            }
            new_buckets[index] = table->buckets[i];
        }
    }
    deallocate_memory(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

void insert_into_hash_table(HashTable* table, void* key) {
    size_t index = hash_function(key);
    while (table->buckets[index] != NULL) {
        index++;
        if (index == table->capacity) {
            resize_hash_table(table, table->capacity * 2);
        }
    }
    table->buckets[index] = key;
    table->size++;
}

void* find_in_hash_table(HashTable* table, void* key) {
    size_t index = hash_function(key);
    while (table->buckets[index] != NULL && table->buckets[index] != key) {
        index++;
        if (index == table->capacity) {
            index = 0;
        }
    }
    return table->buckets[index];
}

void remove_from_hash_table(HashTable* table, void* key) {
    size_t index = hash_function(key);
    while (table->buckets[index] != NULL && table->buckets[index] != key) {
        index++;
        if (index == table->capacity) {
            index = 0;
        }
    }
    table->buckets[index] = NULL;
    table->size--;
}

// Caching mechanism using a custom hash table with dynamic resizing, LRU eviction policies, and support for both read and write operations
typedef struct Cache {
    size_t capacity;
    size_t size;
    HashTable* hash_table;
} Cache;

Cache* create_cache(size_t initial_capacity) {
    Cache* cache = allocate_memory(sizeof(Cache));
    cache->capacity = initial_capacity;
    cache->size = 0;
    cache->hash_table = create_hash_table(initial_capacity, initial_capacity * 2);
    return cache;
}

void destroy_cache(Cache* cache) {
    destroy_hash_table(cache->hash_table);
    deallocate_memory(cache);
}

void resize_cache(Cache* cache, size_t new_capacity) {
    resize_hash_table(cache->hash_table, new_capacity);
    cache->capacity = new_capacity;
}

void insert_into_cache(Cache* cache, void* key, void* value) {
    insert_into_hash_table(cache->hash_table, key);
    cache->size++;
}

void* find_in_cache(Cache* cache, void* key) {
    void* value = find_in_hash_table(cache->hash_table, key);
    if (value != NULL) {
