        remove_from_hash_table(cache->hash_table, key);
        insert_into_hash_table(cache->hash_table, key);
    }
    return value;
}

void remove_from_cache(Cache* cache, void* key) {
    remove_from_hash_table(cache->hash_table, key);
    cache->size--;
}

