class User {
public:
    User(const std::string& id, const std::string& profilePictureUrl) : id_(id), profilePictureUrl_(profilePictureUrl) {}

    void addFriend(const std::string& friendId) { friends_.push_back(friendId); }

    void removeFriend(const std::string& friendId) {
        auto it = std::find(friends_.begin(), friends_.end(), friendId);
        if (it != friends_.end()) {
            friends_.erase(it);
        }
    }

    const std::vector<std::string>& getFriends() const { return friends_; }

    void setProfilePictureUrl(const std::string& profilePictureUrl) { profilePictureUrl_ = profilePictureUrl; }

    const std::string& getId() const { return id_; }

    const std::string& getProfilePictureUrl() const { return profilePictureUrl_; }

private:
    std::string id_;
    std::vector<std::string> friends_;
    std::string profilePictureUrl_;
};

class UserManager {
public:
    void addUser(const std::string& id, const std::string& profilePictureUrl) {
        users_.emplace(id, std::make_shared<User>(id, profilePictureUrl));
    }

    void removeUser(const std::string& id) { users_.erase(id); }

    std::shared_ptr<User> getUser(const std::string& id) const { return users_.at(id); }

    void addFriendship(const std::string& userId, const std::string& friendId) {
        auto user = users_.at(userId);
        user->addFriend(friendId);
    }

    void removeFriendship(const std::string& userId, const std::string& friendId) {
        auto user = users_.at(userId);
        user->removeFriend(friendId);
    }

    std::vector<std::shared_ptr<User>> getUsers() const {
        std::vector<std::shared_ptr<User>> result;
        for (const auto& [id, user] : users_) {
            result.push_back(user);
        }
        return result;
    }

    void setProfilePictureUrl(const std::string& id, const std::string& profilePictureUrl) {
        auto user = users_.at(id);
        user->setProfilePictureUrl(profilePictureUrl);
    }

private:
    std::unordered_map<std::string, std::shared_ptr<User>> users_;
};

class UserFriendList {
public:
    UserFriendList(const std::vector<std::shared_ptr<User>>& users) : users_(users) {}

    void sortByUsername() {
        std::sort(users_.begin(), users_.end(), [](const auto& a, const auto& b) { return a->getId() < b->getId(); });
    }

    void sortByConnectionStrength() {
        // TODO: implement sorting by connection strength
    }

    std::vector<std::shared_ptr<User>> getUsers() const { return users_; }

private:
    std::vector<std::shared_ptr<User>> users_;
};

class UserBlocker {
public:
    void block(const std::string& userId, const std::string& friendId) {
        auto user = users_.at(userId);
        user->removeFriend(friendId);
    }

    void unblock(const std::string& userId, const std::string& friendId) {
        auto user = users_.at(userId);
        user->addFriend(friendId);
    }

private:
    std::unordered_map<std::string, std::shared_ptr<User>> users_;
};

class UserManagerWithExternalAPIs {
public:
    void addUser(const std::string& id, const std::string& profilePictureUrl) {
        // TODO: integrate external APIs for user authentication and social graph retrieval
