// Custom memory management system
struct MemoryPool {
    size_t size;
    void* data;
};

struct MemoryManager {
    struct MemoryPool* pools;
    int num_pools;
};

void initMemoryManager(struct MemoryManager* manager) {
    // Initialize memory pools with default sizes
    for (int i = 0; i < manager->num_pools; i++) {
        struct MemoryPool* pool = &manager->pools[i];
        pool->size = 1 << 20; // 1 MB
        pool->data = malloc(pool->size);
    }
}

void* allocateMemory(struct MemoryManager* manager, size_t size) {
    for (int i = 0; i < manager->num_pools; i++) {
        struct MemoryPool* pool = &manager->pools[i];
        if (pool->size >= size) {
            void* data = malloc(size);
            memcpy(data, pool->data, size);
            return data;
        }
    }
    // No available pools found, allocate new memory
    void* data = malloc(size);
    return data;
}

void deallocateMemory(struct MemoryManager* manager, void* data) {
    for (int i = 0; i < manager->num_pools; i++) {
        struct MemoryPool* pool = &manager->pools[i];
        if (pool->data == data) {
            free(data);
            return;
        }
    }
    // Not found in any pools, deallocate new memory
    free(data);
}

