struct HashTable {
    struct MemoryManager* manager;
    size_t num_buckets;
    void** buckets;
};

void initHashTable(struct HashTable* table, size_t num_buckets) {
    table->num_buckets = num_buckets;
    table->buckets = malloc(table->num_buckets * sizeof(void*));
}

void destroyHashTable(struct HashTable* table) {
    for (int i = 0; i < table->num_buckets; i++) {
        free(table->buckets[i]);
    }
    free(table->buckets);
}

void* hashLookup(struct HashTable* table, void* key) {
    size_t index = (size_t)key % table->num_buckets;
    if (table->buckets[index] == NULL) {
        return NULL;
    } else {
        return table->buckets[index];
    }
}

void hashInsert(struct HashTable* table, void* key, void* value) {
    size_t index = (size_t)key % table->num_buckets;
    if (table->buckets[index] == NULL) {
        table->buckets[index] = malloc(sizeof(void*));
    } else {
        // Reallocate memory for existing value
        void** new_bucket = realloc(table->buckets[index], sizeof(void*) * 2);
        if (new_bucket == NULL) {
            return;
        }
        table->buckets[index] = new_bucket;
    }
    // Insert new value at end of bucket
    table->buckets[index][table->num_buckets - 1] = value;
}

