            data[i].str[j] = 'a' + rand() % 26;
        }
    }

    // Deallocate all resources at the end of the function
    free(offsets);
    free(keys);
    for (int i = 0; i < num_data; i++) {
        free(data[i].str);
    }
    free(data);
}
