// Function to generate a secure 256-bit encryption key and a unique 12-byte initialization vector (IV) using a secure key derivation function (KDF) that incorporates a salt
void generate_key(unsigned char *key, int size) {
    // Generate a random salt of the specified size
    unsigned char salt[size];
    for (int i = 0; i < size; i++) {
        salt[i] = rand() % 256;
    }

    // Use PBKDF2 to derive the key and IV from the salt
    unsigned char *derived_key = malloc(size);
    if (derived_key == NULL) {
        printf("Error: unable to allocate memory for derived key\n");
        return;
    }
    unsigned char *derived_iv = malloc(16);
    if (derived_iv == NULL) {
        printf("Error: unable to allocate memory for derived IV\n");
        return;
    }
    pbkdf2(salt, size, "password", 8, derived_key, size, 1000);
    pbkdf2(salt, size, "IV", 3, derived_iv, 16, 1000);

    // Copy the derived key and IV to the output parameters
    for (int i = 0; i < size; i++) {
        key[i] = derived_key[i];
    }
    for (int i = 0; i < 16; i++) {
        iv[i] = derived_iv[i];
    }

    // Free the memory allocated by PBKDF2
    free(derived_key);
    free(derived_iv);
}

// Function to generate a unique 12-byte initialization vector (IV) using a secure key derivation function (KDF) that incorporates a salt
void generate_iv(unsigned char *iv, int size) {
    // Generate a random salt of the specified size
    unsigned char salt[size];
    for (int i = 0; i < size; i++) {
        salt[i] = rand() % 256;
    }

    // Use PBKDF2 to derive the IV from the salt
    unsigned char *derived_iv = malloc(16);
    if (derived_iv == NULL) {
        printf("Error: unable to allocate memory for derived IV\n");
        return;
    }
    pbkdf2(salt, size, "IV", 3, derived_iv, 16, 1000);

    // Copy the derived IV to the output parameter
    for (int i = 0; i < 16; i++) {
        iv[i] = derived_iv[i];
    }

    // Free the memory allocated by PBKDF2
    free(derived_iv);
}

// Function to encrypt data using AES-256 in CTR mode with a secure IV
unsigned char *encrypt(const unsigned char *data, int size, const unsigned char *key, const unsigned char *iv) {
    // Allocate memory for the encrypted data
    unsigned char *encrypted = malloc(size);
    if (encrypted == NULL) {
        printf("Error: unable to allocate memory for encrypted data\n");
        return NULL;
    }

    // Initialize the AES-256 CTR encryption context
    aes_ctr_ctx ctx;
    aes_ctr_init(&ctx, key, 32);

    // Encrypt the data using AES-256 in CTR mode with the secure IV
    int ret = aes_ctr_encrypt(data, size, encrypted, &ctx, iv);
    if (ret != 0) {
        printf("Error: unable to encrypt data\n");
        return NULL;
    }

    // Return the encrypted data
    return encrypted;
}
