#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

// Define a structure to represent a record
typedef struct {
    int id;
    int value;
    char* string;
    int offset;
} Record;

// Function to manage a dynamic array of records
Record** manage_records(int max_size) {
    // Allocate memory for the array of pointers to records
    Record** records = (Record**)malloc(max_size * sizeof(Record*));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize each record with a unique identifier, integer value, and character string
    srand(time(NULL));
    for (int i = 0; i < max_size; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            return NULL;
        }

        // Generate a unique identifier combining letters and numbers
        char id_str[10];
        sprintf(id_str, "%c%d", 'A' + (i / 26), i % 26);
        record->id = atoi(id_str);

        // Initialize the integer value to a random value within a specified range
        int min_value = 1;
        int max_value = 100;
        record->value = rand() % (max_value - min_value + 1) + min_value;

        // Generate a random sequence of uppercase letters and digits for the character string
        char str[50];
        for (int j = 0; j < 50; j++) {
            int index = rand() % 26 + 'A';
            if (j % 2 == 0) {
                index += ('0' - 'A') / 2;
            }
            str[j] = index;
        }
        record->string = (char*)malloc(50 * sizeof(char));
        if (!record->string) {
            printf("Error: Failed to allocate memory for string %d\n", i);
            return NULL;
        }
        strcpy(record->string, str);

        // Initialize the offset to a unique positive integer
        record->offset = rand() % 10000 + 1;

        records[i] = record;
    }

    return records;
}

// Function to free memory allocated for the dynamic array of records
void free_records(Record** records, int max_size) {
    if (!records) {
        return;
    }

    // Free each record and its associated memory
    for (int i = 0; i < max_size; i++) {
        Record* record = records[i];
        if (record) {
            free(record->string);
            free(record);
        }
    }

    // Free the array of pointers to records
    free(records);
