void initialize_records(record_manager_t *rm, int num_records, size_t mem_usage_threshold) {
    // Allocate memory for the linked list and initialize it
    rm->records = malloc(sizeof(linked_list_t));
    if (rm->records == NULL) {
        printf("Error: Failed to allocate memory for linked list\n");
        return;
    }
    rm->head = NULL;
    rm->tail = NULL;
    rm->num_records = 0;

    // Allocate memory for the record array and initialize it with default values
    rm->records->records = malloc(sizeof(record_t) * num_records);
    if (rm->records->records == NULL) {
        printf("Error: Failed to allocate memory for record array\n");
        free(rm->records);
        return;
    }
    for (int i = 0; i < num_records; i++) {
        rm->records->records[i].offset = -1;
        strcpy(rm->records->records[i].username, "");
        rm->records->records[i].user_id = -1;
        rm->records->records[i].value = 0.0;
    }

    // Set the memory usage threshold and initialize the mutex
    rm->mem_usage_threshold = mem_usage_threshold;
    pthread_mutex_init(&rm->mutex, NULL);
}

// Function to clean up inactive records periodically
void cleanup_records(record_manager_t *rm) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&rm->mutex);

    // Iterate over all records and remove any that are inactive
    node_t *node = rm->head;
    while (node != NULL) {
        if (node->record->offset == -1 && strlen(node->record->username) == 0 && node->record->user_id == -1 && node->record->value == 0.0) {
            // Remove the node from the linked list
            if (node == rm->head) {
                rm->head = node->next;
            } else if (node == rm->tail) {
                rm->tail = node->prev;
            } else {
                node->prev->next = node->next;
                node->next->prev = node->prev;
            }

            // Free the memory for the record and the node
            free(node->record);
            free(node);

            // Decrement the number of records
            rm->num_records--;
        } else {
            node = node->next;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&rm->mutex);
}
```
