// Define a custom linked list structure to support concurrent access
typedef struct Node {
    UserRecord *record;
    struct Node *next;
} Node;

// Define the head node of the linked list
Node *head = NULL;

// Define the mutex for protecting the linked list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to initialize records from an external database
void initialize_records(char *filename) {
    // Open the file and read the records into memory
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    UserRecord record;
    while (fread(&record, sizeof(UserRecord), 1, file)) {
        // Add the record to the linked list
        Node *node = malloc(sizeof(Node));
        node->record = &record;
        node->next = head;
        head = node;
    }

    fclose(file);
}

// Define a function to add a new record to the linked list
void add_record(UserRecord *record) {
    // Lock the mutex to protect the linked list
    pthread_mutex_lock(&mutex);

    // Add the record to the end of the linked list
    Node *node = malloc(sizeof(Node));
    node->record = record;
    node->next = head;
    head = node;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Define a function to remove a record from the linked list
void remove_record(UserRecord *record) {
    // Lock the mutex to protect the linked list
    pthread_mutex_lock(&mutex);

    // Find the node containing the record and remove it
    Node *node = head;
    while (node != NULL && node->record != record) {
        node = node->next;
    }
    if (node == NULL) {
        printf("Error: unable to find record %p\n", record);
        return;
    }
    Node *prev = node->prev;
    head = prev;
    free(node);

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Define a function to update a record in the linked list
void update_record(UserRecord *record) {
    // Lock the mutex to protect the linked list
    pthread_mutex_lock(&mutex);

    // Find the node containing the record and update it
    Node *node = head;
    while (node != NULL && node->record != record) {
        node = node->next;
    }
    if (node == NULL) {
        printf("Error: unable to find record %p\n", record);
        return;
    }
    node->record = record;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Define a function to retrieve a record from the linked list by index
UserRecord *get_record(int index) {
    // Lock the mutex to protect the linked list
    pthread_mutex_lock(&mutex);

    // Find the node containing the record and return it
    Node *node = head;
    for (int i = 0; i < index && node != NULL; i++) {
        node = node->next;
    }
    if (node == NULL) {
        printf("Error: unable to find record at index %d\n", index);
        return NULL;
    }
    UserRecord *record = node->record;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);

    return record;
}

