    // Lock the mutex to protect the linked list
    pthread_mutex_lock(&mutex);

    // Find the node containing the record and return it
    Node *node = head;
    while (node != NULL && node->record->user_id != id) {
        node = node->next;
    }
    if (node == NULL) {
        printf("Error: unable to find record with user ID %d\n", id);
        return NULL;
    }
    UserRecord *record = node->record;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);

    return record;
}

