#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdint.h>
#include <assert.h>

// Define the record structure
typedef struct {
    double value;
    char *str;
    uint64_t id;
} record_t;

// Define the log entry structure
typedef struct {
    uint64_t timestamp;
    uint8_t operation;
    uint32_t index;
} log_entry_t;

// Define the offset structure
typedef struct {
    uint32_t offset;
    uint32_t length;
} offset_t;

// Define the key structure
typedef struct {
    uint64_t id;
    char *str;
} key_t;

// Define the entry structure
typedef struct {
    record_t record;
    log_entry_t log[];
} entry_t;

// Define the collection structure
typedef struct {
    uint32_t size;
    uint32_t capacity;
    offset_t *offsets;
    key_t *keys;
    entry_t *entries;
} collection_t;

// Initialize the collection
void initialize_collection(collection_t *coll) {
    coll->size = 0;
    coll->capacity = 16;
    coll->offsets = malloc(sizeof(offset_t) * coll->capacity);
    coll->keys = malloc(sizeof(key_t) * coll->capacity);
    coll->entries = malloc(sizeof(entry_t) * coll->capacity);
}

// Add a new record to the collection
void add_record(collection_t *coll, double value, char *str) {
    // Check if the collection needs to be resized
    if (coll->size == coll->capacity) {
        resize_collection(coll);
    }

    // Generate a unique identifier for the string
    uint64_t id = generate_id(str);

    // Add the record to the collection
    coll->offsets[coll->size].offset = coll->size;
    coll->offsets[coll->size].length = strlen(str) + 1;
    coll->keys[coll->size].id = id;
    coll->keys[coll->size].str = strdup(str);
    coll->entries[coll->size].record.value = value;
    coll->entries[coll->size].record.id = id;
    coll->entries[coll->size].record.str = strdup(str);
    coll->size++;
}

// Modify an existing record in the collection
void modify_record(collection_t *coll, uint32_t index, double value, char *str) {
    // Check if the index is valid
    assert(index < coll->size);

    // Generate a unique identifier for the string
    uint64_t id = generate_id(str);

    // Update the record in the collection
    coll->entries[index].record.value = value;
    coll->entries[index].record.id = id;
    coll->entries[index].record.str = strdup(str);
}

// Retrieve a record from the collection by index
record_t *get_record(collection_t *coll, uint32_t index) {
    // Check if the index is valid
    assert(index < coll->size);

    return &coll->entries[index].record;
}

// Retrieve a record from the collection by key
record_t *get_record_by_key(collection_t *coll, uint64_t id) {
    // Check if the key is valid
    assert(id < coll->capacity);

    for (uint32_t i = 0; i < coll->size; i++) {
        if (coll->keys[i].id == id) {
            return &coll->entries[i].record;
        }
    }

    return NULL;
}

// Resize the collection when it needs to be resized
void resize_collection(collection_t *coll) {
    coll->capacity = coll->capacity * 2;
    coll->offsets = realloc(coll->offsets, sizeof(offset_t) * coll->capacity);
    coll->keys = realloc(coll->keys, sizeof(key_t) * coll->capacity);
    coll->entries = realloc(coll->entries, sizeof(entry_t) * coll->capacity);
}

// Generate a unique identifier for a string
uint64_t generate_id(char *str) {
    uint64_t id = 0;
    for (int i = 0; i < strlen(str); i++) {
        id += str[i];
    }
    return id;
}

// Clean up the collection when it's no longer needed
void cleanup_collection(collection_t *coll) {
    for (uint32_t i = 0; i < coll->size; i++) {
        free(coll->entries[i].record.str);
        free(coll->keys[i].str);
    }
    free(coll->offsets);
    free(coll->keys);
    free(coll->entries);
}
