#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>

// Custom memory management system for slab allocation
struct MemoryManager {
    void* slabs[10]; // 10 slabs of memory
    int nextSlab; // index of the next available slab
};

typedef struct Event {
    time_t timestamp;
    char* message;
    double priority;
} Event;

int allocateEvents(Event** events, int maxEvents, int seed) {
    if (maxEvents <= 0) {
        return -1; // error: invalid maximum number of events
    }

    struct MemoryManager* manager = malloc(sizeof(struct MemoryManager));
    if (!manager) {
        return -2; // error: unable to allocate memory for the memory manager
    }

    manager->nextSlab = 0;

    int i, j;
    for (i = 0; i < 10; i++) {
        manager->slabs[i] = malloc(sizeof(Event) * maxEvents);
        if (!manager->slabs[i]) {
            break; // error: unable to allocate memory for the slab
        }
    }

    if (i == 10) {
        return -3; // error: unable to allocate enough memory for all events
    }

    *events = malloc(sizeof(Event) * maxEvents);
    if (!*events) {
        return -4; // error: unable to allocate memory for the event array
    }

    srand(seed);

    for (i = 0; i < maxEvents; i++) {
        Event* event = &(*events)[i];
        event->timestamp = time(NULL);
        char message[16]; // maximum length of an event message is 15 characters + null terminator
        sprintf(message, "Event %d", i);
        event->message = strdup(message);
        event->priority = (double)i / maxEvents;
    }

    return maxEvents;
}

void deallocateEvents(Event** events, int count) {
    if (!events || !*events) {
        return; // error: invalid event array or pointer
    }

    for (int i = 0; i < count; i++) {
        free((*events)[i].message);
    }

    free(*events);
    *events = NULL;
}
